+  <script>
+    (() => {
+      const viewport = document.querySelector('.map-viewport');
+      if (!viewport) return;
+
+      // Start centered on the map
+      viewport.scrollLeft = (viewport.scrollWidth - viewport.clientWidth) / 2;
+      viewport.scrollTop = (viewport.scrollHeight - viewport.clientHeight) / 2;
+
+      // Native scroll-axis-lock handles free 2D panning; otherwise apply raw deltas ourselves.
+      if (CSS.supports('scroll-axis-lock', 'none')) return;
+
+      const LINE_HEIGHT = 16;
+      viewport.addEventListener('wheel', (e) => {
+        if (e.ctrlKey) return; // let Ctrl+wheel / trackpad pinch zoom the page
+        e.preventDefault();
+        const scale = e.deltaMode === 1 ? LINE_HEIGHT : e.deltaMode === 2 ? viewport.clientHeight : 1;
+        viewport.scrollLeft += e.deltaX * scale;
+        viewport.scrollTop += e.deltaY * scale;
+      }, { passive: false });
+
+      const DRAG_THRESHOLD = 4;
+      let start = null;
+      let last = null;
+      let dragging = false;
+      let suppressClick = false;
+
+      viewport.addEventListener('pointerdown', (e) => {
+        const rect = viewport.getBoundingClientRect();
+        if (
+          !e.isPrimary ||
+          e.button !== 0 ||
+          e.clientX - rect.left - viewport.clientLeft >= viewport.clientWidth ||
+          e.clientY - rect.top - viewport.clientTop >= viewport.clientHeight
+        ) {
+          return; // ignore secondary buttons and native scrollbar clicks
+        }
+        start = last = { x: e.clientX, y: e.clientY, id: e.pointerId };
+        dragging = false;
+      });
+
+      viewport.addEventListener('pointermove', (e) => {
+        if (!start || e.pointerId !== start.id) return;
+        if (!dragging) {
+          if (Math.hypot(e.clientX - start.x, e.clientY - start.y) < DRAG_THRESHOLD) return;
+          // Only capture once a real drag starts so taps on location pins still click through.
+          dragging = true;
+          viewport.setPointerCapture(e.pointerId);
+          viewport.classList.add('is-panning');
+        }
+        viewport.scrollLeft -= e.clientX - last.x;
+        viewport.scrollTop -= e.clientY - last.y;
+        last = { x: e.clientX, y: e.clientY, id: e.pointerId };
+      });
+
+      const endPan = () => {
+        if (dragging) suppressClick = true;
+        start = last = null;
+        dragging = false;
+        viewport.classList.remove('is-panning');
+        setTimeout(() => { suppressClick = false; }, 0);
+      };
+      viewport.addEventListener('pointerup', endPan);
+      viewport.addEventListener('pointercancel', endPan);
+
+      // Don't follow a pin link when the gesture was a pan
+      viewport.addEventListener('click', (e) => {
+        if (suppressClick) {
+          e.preventDefault();
+          e.stopPropagation();
+        }
+      }, true);
+
+      // Prevent native link/image dragging from hijacking mouse pans
+      viewport.addEventListener('dragstart', (e) => e.preventDefault());
+    })();
+  </script>
+
