+template.innerHTML = `
+  <style>
+    :host {
+      display: inline-flex;
+      vertical-align: middle;
+      font: inherit;
+    }
+    :host([hidden]) { display: none; }
+
+    button {
+      all: unset;
+      box-sizing: border-box;
+      display: inline-flex;
