+          drinkLabel: drinkOpt && drinkOpt.value ? drinkOpt.textContent.split(' — ')[0] : '',
+          basePrice: drinkOpt && drinkOpt.dataset.price ? parseFloat(drinkOpt.dataset.price) : 0,
+          size: data.get('size') || '',
+          temperature: data.get('drink') === 'cold-brew' ? 'iced' : (data.get('temperature') || 'hot'),
