+        return Math.round(total * 100) / 100;
+      }
+
+      function validate(o) {
+        const errors = [];
+        if (!o.drink) errors.push('Please choose a drink.');
+        if (!(o.size in SIZE_UPCHARGE)) errors.push('Please choose a size (small, medium, or large).');
+        if (!Number.isInteger(o.extraShots) || o.extraShots < 0 || o.extraShots > 4) {
