@@ -0,0 +1,101 @@
+import { useEffect, useRef } from 'react';
+
+/**
+ * Minimal WebMCP (navigator.modelContext) helpers used to expose client-side
+ * functionality to in-browser AI agents as tools.
+ *
+ * See https://github.com/webmachinelearning/webmcp
+ */
+
+export interface ToolResult {
+  content: Array<{ type: 'text'; text: string }>;
+  isError?: boolean;
+}
+
+export interface ToolDefinition<TInput = any> {
+  name: string;
+  description: string;
+  inputSchema: {
+    type: 'object';
+    properties: Record<string, unknown>;
+    required?: string[];
+    additionalProperties?: boolean;
+  };
+  annotations?: {
+    readOnlyHint?: boolean;
+    [key: string]: unknown;
+  };
+  execute: (input: TInput, agent?: unknown) => Promise<ToolResult> | ToolResult;
+}
+
+interface ModelContext {
+  registerTool: (
+    tool: ToolDefinition,
+    options?: { signal?: AbortSignal },
+  ) => { unregister?: () => void } | void;
+  unregisterTool?: (name: string) => void;
+}
+
+declare global {
+  interface Navigator {
+    modelContext?: ModelContext;
+  }
+}
+
+export function textResult(text: string, isError = false): ToolResult {
+  return { content: [{ type: 'text', text }], ...(isError ? { isError: true } : {}) };
+}
+
+/**
+ * Registers a WebMCP tool for as long as the calling component is mounted.
+ * `execute` always calls the latest version of the provided callback, so it
+ * can freely close over component state without re-registering the tool.
+ */
+export function useWebMCPTool<TInput>(tool: ToolDefinition<TInput>) {
+  const executeRef = useRef(tool.execute);
+  executeRef.current = tool.execute;
+
+  useEffect(() => {
+    const modelContext = typeof navigator !== 'undefined' ? navigator.modelContext : undefined;
+    if (!modelContext?.registerTool) return;
+
+    const controller = new AbortController();
+    let registration: { unregister?: () => void } | void;
+    try {
+      registration = modelContext.registerTool(
+        {
+          ...tool,
+          execute: async (input: TInput, agent?: unknown) => {
+            try {
+              return await executeRef.current(input ?? ({} as TInput), agent);
+            } catch (err) {
+              return textResult(
+                `Tool "${tool.name}" failed: ${err instanceof Error ? err.message : String(err)}`,
+                true,
+              );
+            }
+          },
+        },
+        { signal: controller.signal },
+      );
+    } catch (err) {
+      console.warn(`[WebMCP] Failed to register tool "${tool.name}":`, err);
+      return;
+    }
+
+    return () => {
+      controller.abort();
+      try {
+        if (registration && typeof registration.unregister === 'function') {
+          registration.unregister();
+        } else {
+          modelContext.unregisterTool?.(tool.name);
+        }
+      } catch {
+        // Already unregistered (e.g. via the abort signal).
+      }
+    };
+    // The tool's metadata is static; only re-register if its name changes.
+    // eslint-disable-next-line react-hooks/exhaustive-deps
+  }, [tool.name]);
+}

