+// GPU ripple distortion for the hero section, using the HTML-in-Canvas API.
+// The hero's live DOM (heading, tagline, "Order Now" link) is uploaded into a
+// WebGL texture and drawn through a ripple shader. updateElementGeometry()
+// keeps the real elements aligned with their pixels, so text stays selectable
+// and the link stays clickable/focusable.
+
+const hero = document.querySelector('.hero');
+const canvas = hero?.querySelector('.hero-canvas');
+const content = canvas?.querySelector('.hero-content');
+
+const supportsHtmlInCanvas =
+  typeof HTMLCanvasElement !== 'undefined' &&
+  'content' in HTMLCanvasElement.prototype &&
+  'requestPaint' in HTMLCanvasElement.prototype &&
+  'updateElementGeometry' in HTMLCanvasElement.prototype &&
+  typeof WebGL2RenderingContext !== 'undefined' &&
+  'texElementSubImage2D' in WebGL2RenderingContext.prototype;
+
+// Fallback: show the HTML on top of the hero as plain, static content.
+function fallbackToStatic() {
+  if (!canvas || !content) return;
+  hero.append(content);
+  content.removeAttribute('drawable');
+  canvas.remove();
+}
+
+if (hero && canvas && content) {
+  const gl = supportsHtmlInCanvas
+    ? canvas.getContext('webgl2', { premultipliedAlpha: true, antialias: false })
+    : null;
+  if (!gl) fallbackToStatic();
+  else initRipple(gl);
