+          const g = ctx.createLinearGradient(0, 0, w, h);
+          g.addColorStop(0, '#6d4c41');
+          g.addColorStop(1, '#3e2723');
+          ctx.fillStyle = g;
+          ctx.fillRect(0, 0, w, h);
+        }
+        ctx.fillStyle = 'rgba(0,0,0,0.5)';
+        ctx.fillRect(0, 0, w, h);
+
+        // text
+        ctx.shadowColor = 'rgba(0,0,0,0.35)';
+        ctx.shadowBlur = 8;
+        ctx.shadowOffsetY = 2;
+        textEls.forEach(el => drawText(el, textColors.get(el), origin));
+
+        // button
+        if (btn) {
+          const r = btn.getBoundingClientRect();
+          const rad = parseFloat(getComputedStyle(btn).borderTopLeftRadius) || 0;
+          ctx.fillStyle = btnHover ? btnColors.bgHover : btnColors.bg;
+          roundRect(r.left - origin.left, r.top - origin.top, r.width, r.height, rad);
+          ctx.fill();
+          ctx.shadowColor = 'transparent';
+          drawText(btn, btnColors.fg, origin);
+        }
+        ctx.shadowColor = 'transparent';
