+        gl.bindTexture(gl.TEXTURE_2D, tex);
+        try {
+          gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, src);
+        } catch (e) {
+          // tainted canvas (image without CORS) — fall back to gradient
+          if (bgImg) { bgImg = null; rasterize(); }
+        }
+      }
+
+      function resize() {
+        dpr = Math.min(window.devicePixelRatio || 1, 2);
+        const rect = hero.getBoundingClientRect();
+        canvas.width = Math.max(1, Math.round(rect.width * dpr));
+        canvas.height = Math.max(1, Math.round(rect.height * dpr));
+        gl.viewport(0, 0, canvas.width, canvas.height);
+        rasterize();
+      }
+
+      // ---------- Ripples ----------
+      const ripples = new Float32Array(MAX_RIPPLES * 4);
+      let rippleIdx = 0;
+      const t0 = performance.now();
+      const now = () => (performance.now() - t0) / 1000;
+      let lastInteraction = -10;
+
+      function addRipple(clientX, clientY, strength) {
+        const rect = hero.getBoundingClientRect();
+        const o = rippleIdx * 4;
+        ripples[o] = (clientX - rect.left) * dpr;
+        ripples[o + 1] = (clientY - rect.top) * dpr;
+        ripples[o + 2] = now();
+        ripples[o + 3] = strength;
+        rippleIdx = (rippleIdx + 1) % MAX_RIPPLES;
+      }
+
+      let lastX = -1e4, lastY = -1e4, lastT = 0;
+      hero.addEventListener('pointermove', e => {
+        const t = now();
+        const dx = e.clientX - lastX, dy = e.clientY - lastY;
+        if (dx * dx + dy * dy > 45 * 45 || t - lastT > 0.25) {
+          addRipple(e.clientX, e.clientY, 0.55);
+          lastX = e.clientX; lastY = e.clientY; lastT = t;
+        }
+        lastInteraction = t;
+      }, { passive: true });
+
+      hero.addEventListener('pointerdown', e => {
+        addRipple(e.clientX, e.clientY, 1.2);
+        lastInteraction = now();
+      }, { passive: true });
+
+      if (btn) {
+        const setHover = v => () => { btnHover = v; rasterize(); };
+        btn.addEventListener('pointerenter', setHover(true));
+        btn.addEventListener('pointerleave', setHover(false));
+        btn.addEventListener('focus', setHover(true));
+        btn.addEventListener('blur', setHover(false));
+      }
+
+      // ---------- Loop ----------
+      let visible = true, raf = 0, nextAmbient = 0.6;
+      function frame() {
+        raf = 0;
+        if (!visible) return;
+        const t = now();
+        if (t > nextAmbient && t - lastInteraction > 2) {
+          const rect = hero.getBoundingClientRect();
+          addRipple(rect.left + rect.width * (0.2 + Math.random() * 0.6),
+            rect.top + rect.height * (0.25 + Math.random() * 0.5), 0.6);
+          nextAmbient = t + 2.2 + Math.random() * 1.5;
+        }
