+    function nextAnniversary(anniversary) {
+      const today = Temporal.Now.plainDateISO();
+      const monthDay = anniversary.toPlainMonthDay();
+      // Convert to a PlainDate before arithmetic; Feb 29 is constrained to Feb 28 in non-leap years.
+      let next = monthDay.toPlainDate({ year: today.year });
+      if (Temporal.PlainDate.compare(next, today) < 0) {
+        next = monthDay.toPlainDate({ year: today.year + 1 });
+      }
+      return { next, days: today.until(next, { largestUnit: 'day' }).days, years: next.year - anniversary.year };
+    }
+
+    function render({ pickupTime, anniversary }) {
+      const parts = [];
+      if (pickupTime) {
+        const t = pickupTime.toLocaleString(undefined, { hour: 'numeric', minute: '2-digit' });
+        parts.push(`Daily pickup reminder: ${t} (local time, wherever you are).`);
+      }
+      if (anniversary) {
+        const d = anniversary.toLocaleString(undefined, { dateStyle: 'long' });
+        const { days, years } = nextAnniversary(anniversary);
+        let when = days === 0 ? 'Happy coffee anniversary — it\'s today! ☕'
+          : `${days} day${days === 1 ? '' : 's'} until your next one.`;
+        if (years > 0 && days !== 0) when = `${days} day${days === 1 ? '' : 's'} until your ${years}-year mark.`;
+        parts.push(`Coffee anniversary: ${d}. ${when}`);
+      }
+      summary.textContent = parts.join(' ');
+    }
+
+    const initial = load();
+    // Native inputs use the same zone-free ISO formats as Temporal's toString().
+    if (initial.pickupTime) timeInput.value = initial.pickupTime.toString({ smallestUnit: 'minute' });
+    if (initial.anniversary) dateInput.value = initial.anniversary.toString();
+    render(initial);
+
+    form.addEventListener('submit', (e) => {
+      e.preventDefault();
+      // Read input.value strings directly; avoid valueAsDate/valueAsNumber, which are UTC instants.
+      const prefs = {
+        pickupTime: timeInput.value ? Temporal.PlainTime.from(timeInput.value) : null,
+        anniversary: dateInput.value ? Temporal.PlainDate.from(dateInput.value) : null,
+      };
+      save(prefs);
+      render(prefs);
+    });
+  </script>
+
 </body>

