+  <script>
+    /*
+     * Location-agnostic preferences.
+     *
+     * The pickup time and anniversary are stored as plain wall-clock strings
+     * ("HH:MM" and "YYYY-MM-DD"), exactly as the user entered them. They are
+     * never turned into timestamps, UTC strings or Date objects for storage,
+     * so travelling across time zones (or DST changes) can't shift them.
+     *
+     * Note: `new Date("YYYY-MM-DD")` parses as UTC midnight and shows the
+     * previous day west of UTC, and toISOString() converts to UTC. Both are
+     * deliberately avoided here.
+     */
+    (function () {
+      var STORAGE_KEY = 'dailyGrind.preferences';
+      var TIME_RE = /^([01]\d|2[0-3]):([0-5]\d)$/;
+      var DATE_RE = /^(\d{4})-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/;
+      var MONTHS = ['January', 'February', 'March', 'April', 'May', 'June',
+        'July', 'August', 'September', 'October', 'November', 'December'];
+
+      var form = document.getElementById('prefs-form');
+      var timeInput = document.getElementById('pickup-time');
+      var dateInput = document.getElementById('anniversary-date');
+      var statusEl = document.getElementById('prefs-status');
+      var summaryEl = document.getElementById('prefs-summary');
+
+      function daysInMonth(year, month) {
+        // month is 1-12; pure calendar math, no time zone involved.
+        return [31, (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0 ? 29 : 28,
+          31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1];
+      }
+
+      function normalizeTime(value) {
+        // Inputs may report "HH:MM:SS"; keep only hours and minutes.
+        var v = String(value || '').slice(0, 5);
+        return TIME_RE.test(v) ? v : '';
+      }
+
+      function normalizeDate(value) {
+        var v = String(value || '');
+        var m = DATE_RE.exec(v);
+        if (!m) return '';
+        return Number(m[3]) <= daysInMonth(Number(m[1]), Number(m[2])) ? v : '';
+      }
+
+      function formatTime(hhmm) {
+        var parts = hhmm.split(':');
+        var h = Number(parts[0]);
+        var suffix = h < 12 ? 'AM' : 'PM';
+        var h12 = h % 12 === 0 ? 12 : h % 12;
+        return h12 + ':' + parts[1] + ' ' + suffix;
+      }
+
+      function formatDate(ymd) {
+        var p = ymd.split('-');
+        return MONTHS[Number(p[1]) - 1] + ' ' + Number(p[2]) + ', ' + p[0];
+      }
+
+      // Day number for a calendar date (days since 1970-01-01), computed with
+      // Date.UTC purely as calendar arithmetic, so DST and offsets don't matter.
+      function dayNumber(y, m, d) {
