+      function daysUntilAnniversary(ymd) {
+        var p = ymd.split('-').map(Number);
+        var now = new Date(); // today's date as seen on the user's own wall clock
+        var ty = now.getFullYear(), tm = now.getMonth() + 1, td = now.getDate();
+        var today = dayNumber(ty, tm, td);
+
+        function occurrence(year) {
+          // Feb 29 anniversaries fall on Feb 28 in non-leap years.
+          return dayNumber(year, p[1], Math.min(p[2], daysInMonth(year, p[1])));
+        }
+
+        var next = occurrence(ty);
+        var year = ty;
+        if (next < today) {
+          year = ty + 1;
+          next = occurrence(year);
+        }
+        return { days: next - today, years: year - p[0] };
+      }
