+        }
+      }
+
+      function save(prefs) {
+        try {
+          localStorage.setItem(STORAGE_KEY, JSON.stringify(prefs));
+          return true;
+        } catch (e) {
+          return false;
+        }
+      }
+
+      function renderSummary(prefs) {
+        var lines = [];
+        if (prefs.pickupTime) {
+          lines.push('&#9749; Daily pickup reminder at <strong>' + formatTime(prefs.pickupTime) +
+            '</strong> local time, wherever you are.');
+        }
+        if (prefs.anniversaryDate) {
+          var info = daysUntilAnniversary(prefs.anniversaryDate);
+          var when = info.days === 0 ? 'is <strong>today</strong>!' :
+            'is in <strong>' + info.days + ' day' + (info.days === 1 ? '' : 's') + '</strong>.';
+          var label = info.years > 0 ? 'Your ' + info.years + '-year coffee anniversary ' : 'Your coffee anniversary ';
