+  <script>
+    (() => {
+      const STORAGE_KEY = 'daily-grind-order';
+      const money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });
+      const countEl = document.getElementById('order-count');
+      const statusEl = document.getElementById('order-status');
+
+      let order = [];
+      try {
+        order = JSON.parse(sessionStorage.getItem(STORAGE_KEY)) || [];
+      } catch { /* storage unavailable or corrupt: start fresh */ }
+
+      const renderCount = () => {
+        countEl.value = order.reduce((n, line) => n + line.qty, 0);
+      };
+
+      const save = () => {
+        try { sessionStorage.setItem(STORAGE_KEY, JSON.stringify(order)); } catch { }
+      };
+
+      document.querySelectorAll('.order-form').forEach((form) => {
+        const priceEl = form.querySelector('.price');
+        const button = form.querySelector('button[type="submit"]');
+        const selected = () => form.querySelector('input[name="size"]:checked');
+
+        const updatePrice = () => {
+          priceEl.value = money.format(Number(selected().dataset.price));
+        };
+
+        form.addEventListener('change', updatePrice);
+        updatePrice();
+
+        let resetTimer;
+        form.addEventListener('submit', (event) => {
+          event.preventDefault();
+          const radio = selected();
+          const item = form.elements.item.value;
+          const size = radio.value;
+          const price = Number(radio.dataset.price);
+
+          const line = order.find((l) => l.item === item && l.size === size);
+          if (line) line.qty += 1;
+          else order.push({ item, name: form.dataset.item, size, price, qty: 1 });
+
+          save();
+          renderCount();
+
+          const sizeLabel = radio.nextElementSibling.textContent;
+          statusEl.textContent = `Added ${sizeLabel.toLowerCase()} ${form.dataset.item} to your order.`;
+
+          button.textContent = 'Added \u2713';
+          clearTimeout(resetTimer);
+          resetTimer = setTimeout(() => { button.textContent = 'Add to order'; }, 1500);
+        });
+      });
+
+      renderCount();
+    })();
+  </script>
+
 </body>

