+// Delivery-notes crypto core (no DOM access).
+//
+// Every note gets a fresh shared secret from one of three public-key schemes,
+// aimed at the store's long-term public key:
+//
+//   xwing    X-Wing hybrid KEM (ML-KEM-768 + X25519, draft-connolly-cfrg-xwing-kem).
+//            Stays secure if either ML-KEM or X25519 holds up. This is the default.
+//   mlkem768 ML-KEM-768 (FIPS 203) on its own, for post-quantum-only protection.
+//   x25519   Ephemeral-static X25519 ECDH key agreement (classical, no PQ protection).
+//
+// The shared secret goes through HKDF-SHA-256 to make a single-use AES-256-GCM key.
+// HKDF's `info` binds the suite, the recipient key id and the encapsulation/ephemeral
+// value. The envelope header is the GCM additional authenticated data, so any change to
+// the ciphertext or the metadata makes decryption fail.
+
+import { ml_kem768_x25519 as xwing } from '@noble/post-quantum/hybrid.js';
+import { ml_kem768 } from '@noble/post-quantum/ml-kem.js';
+import { x25519 } from '@noble/curves/ed25519.js';
+
+export const ENVELOPE_VERSION = 1;
+export const MAX_NOTE_LENGTH = 1000;
+const LABEL = 'DailyGrind/DeliveryNotes/v1';
+
+const subtle = globalThis.crypto?.subtle;
+const enc = new TextEncoder();
+const dec = new TextDecoder();
+
+// ---------- encoding helpers ----------
+export function b64u(bytes) {
+  let s = '';
+  for (let i = 0; i < bytes.length; i += 0x8000) {
+    s += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
+  }
+  return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+export function unb64u(str) {
+  if (typeof str !== 'string' || !/^[A-Za-z0-9_-]*$/.test(str)) throw new Error('Invalid base64url');
+  const pad = str.length % 4 === 0 ? '' : '='.repeat(4 - (str.length % 4));
+  const bin = atob(str.replace(/-/g, '+').replace(/_/g, '/') + pad);
+  const out = new Uint8Array(bin.length);
+  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
+  return out;
+}
+
+function concat(...parts) {
+  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
+  let off = 0;
+  for (const p of parts) { out.set(p, off); off += p.length; }
+  return out;
+}
+
+async function sha256(bytes) {
+  return new Uint8Array(await subtle.digest('SHA-256', bytes));
+}
+
+/** Key id: base64url(SHA-256(suite || 0x00 || publicKey)), truncated to 128 bits. */
+export async function keyId(suite, publicKey) {
+  const h = await sha256(concat(enc.encode(suite), new Uint8Array([0]), publicKey));
+  return b64u(h.subarray(0, 16));
+}
+
+/** Readable fingerprint of a public key, e.g. "3F9A 0C11 ...". */
+export async function fingerprint(suite, publicKey) {
+  const h = await sha256(concat(enc.encode(suite), new Uint8Array([0]), publicKey));
+  return Array.from(h.subarray(0, 12), (b) => b.toString(16).padStart(2, '0'))
+    .join('').toUpperCase().match(/.{4}/g).join(' ');
+}
+
+// ---------- X25519 (WebCrypto where available, audited JS fallback otherwise) ----------
+let webcryptoX25519; // undefined = not probed yet
+async function hasWebCryptoX25519() {
+  if (webcryptoX25519 === undefined) {
+    try {
+      await subtle.generateKey({ name: 'X25519' }, false, ['deriveBits']);
+      webcryptoX25519 = true;
+    } catch {
+      webcryptoX25519 = false;
+    }
+  }
+  return webcryptoX25519;
+}
+
+async function x25519Ephemeral(recipientPub) {
+  if (await hasWebCryptoX25519()) {
+    const eph = await subtle.generateKey({ name: 'X25519' }, true, ['deriveBits']);
+    const peer = await subtle.importKey('raw', recipientPub, { name: 'X25519' }, false, []);
+    const ss = new Uint8Array(await subtle.deriveBits({ name: 'X25519', public: peer }, eph.privateKey, 256));
+    const ephPub = new Uint8Array(await subtle.exportKey('raw', eph.publicKey));
+    return { ephPub, ss };
+  }
+  const sk = x25519.utils.randomSecretKey();
+  try {
+    return { ephPub: x25519.getPublicKey(sk), ss: x25519.getSharedSecret(sk, recipientPub) };
+  } finally {
+    sk.fill(0);
+  }
+}
+
+function assertNonZero(ss) {
+  // Low-order peer points give an all-zero X25519 output (RFC 7748 §6.1), so reject it.
+  if (ss.every((b) => b === 0)) throw new Error('Invalid X25519 public key');
+}
+
+// ---------- suite table ----------
+export const SUITES = {
+  xwing: {
+    id: 'xwing',
+    label: 'Hybrid post-quantum (X-Wing: ML-KEM-768 + X25519)',
+    short: 'X-Wing hybrid KEM',
+    kind: 'kem',
+    publicKeyLength: 1216,
+    encLength: 1120,
+    keygen() {
+      const { publicKey, secretKey } = xwing.keygen();
+      return { publicKey, secretKey };
+    },
+    async encapsulate(pk) {
+      const { cipherText, sharedSecret } = xwing.encapsulate(pk);
+      return { encapsulated: cipherText, sharedSecret };
+    },
+    async decapsulate(encapsulated, sk) {
+      return xwing.decapsulate(encapsulated, sk);
+    },
+  },
+  mlkem768: {
+    id: 'mlkem768',
+    label: 'Post-quantum only (ML-KEM-768, FIPS 203)',
+    short: 'ML-KEM-768',
+    kind: 'kem',
+    publicKeyLength: 1184,
+    encLength: 1088,
+    keygen() {
+      const { publicKey, secretKey } = ml_kem768.keygen();
+      return { publicKey, secretKey };
+    },
+    async encapsulate(pk) {
+      const { cipherText, sharedSecret } = ml_kem768.encapsulate(pk);
+      return { encapsulated: cipherText, sharedSecret };
+    },
+    async decapsulate(encapsulated, sk) {
+      return ml_kem768.decapsulate(encapsulated, sk);
+    },
+  },
+  x25519: {
+    id: 'x25519',
+    label: 'Classical key agreement (X25519 ECDH)',
+    short: 'X25519 ECDH',
+    kind: 'key-agreement',
+    publicKeyLength: 32,
+    encLength: 32,
+    keygen() {
+      const secretKey = x25519.utils.randomSecretKey();
+      return { publicKey: x25519.getPublicKey(secretKey), secretKey };
+    },
+    async encapsulate(pk) {
+      const { ephPub, ss } = await x25519Ephemeral(pk);
+      assertNonZero(ss);
+      return { encapsulated: ephPub, sharedSecret: ss };
+    },
+    async decapsulate(ephPub, sk) {
+      const ss = x25519.getSharedSecret(sk, ephPub);
+      assertNonZero(ss);
+      return ss;
+    },
+  },
+};
+
+function getSuite(id) {
+  const s = Object.prototype.hasOwnProperty.call(SUITES, id) ? SUITES[id] : undefined;
+  if (!s) throw new Error(`Unsupported suite: ${id}`);
+  return s;
+}
+
+// ---------- key derivation & AEAD ----------
+async function deriveAeadKey(suite, kid, recipientPk, encapsulated, sharedSecret, usage) {
+  const ikm = await subtle.importKey('raw', sharedSecret, 'HKDF', false, ['deriveKey']);
+  // Bind the context: label, suite, recipient key id, a hash of the recipient public key
+  // and a hash of the encapsulation/ephemeral value. This matters most for the plain
+  // ECDH suite, where the raw DH output does not commit to either public key.
+  const info = concat(
+    enc.encode(`${LABEL}/${suite}`), new Uint8Array([0]),
+    enc.encode(kid), new Uint8Array([0]),
+    await sha256(recipientPk),
+    await sha256(encapsulated),
+  );
+  return subtle.deriveKey(
+    { name: 'HKDF', hash: 'SHA-256', salt: new Uint8Array(32), info },
+    ikm,
+    { name: 'AES-GCM', length: 256 },
+    false,
+    [usage],
+  );
+}
+
+/** Canonical AAD: a fixed-order JSON array of every header field. */
+function aadFor(h) {
+  return enc.encode(JSON.stringify([h.v, h.suite, h.kid, h.enc, h.iv, h.orderRef, h.createdAt]));
+}
+
+/**
+ * Encrypts a note to a recipient public key.
+ * @param {{suite: string, kid: string, publicKey: Uint8Array}} recipient
+ * @param {string} note
+ * @param {{orderRef?: string}} [meta]
+ */
+export async function encryptNote(recipient, note, meta = {}) {
+  if (!subtle) throw new Error('WebCrypto is unavailable (a secure HTTPS context is required).');
+  if (typeof note !== 'string' || !note.trim()) throw new Error('Please enter a note to encrypt.');
+  if (note.length > MAX_NOTE_LENGTH) throw new Error(`Notes are limited to ${MAX_NOTE_LENGTH} characters.`);
+  const suite = getSuite(recipient.suite);
+  if (recipient.publicKey.length !== suite.publicKeyLength) throw new Error('Recipient key has the wrong length.');
+
+  const { encapsulated, sharedSecret } = await suite.encapsulate(recipient.publicKey);
+  let key;
+  try {
+    key = await deriveAeadKey(suite.id, recipient.kid, recipient.publicKey, encapsulated, sharedSecret, 'encrypt');
+  } finally {
+    sharedSecret.fill(0);
+  }
+
+  const iv = crypto.getRandomValues(new Uint8Array(12));
+  const header = {
+    v: ENVELOPE_VERSION,
+    suite: suite.id,
+    kid: recipient.kid,
+    enc: b64u(encapsulated),
+    iv: b64u(iv),
+    orderRef: String(meta.orderRef || '').slice(0, 64),
+    createdAt: new Date().toISOString(),
+  };
+  const plaintext = enc.encode(note);
+  const ct = new Uint8Array(await subtle.encrypt(
+    { name: 'AES-GCM', iv, additionalData: aadFor(header), tagLength: 128 }, key, plaintext,
+  ));
+  plaintext.fill(0);
+  return { ...header, ct: b64u(ct) };
+}
+
+/**
+ * Decrypts an envelope with the matching recipient key pair. In production this runs
+ * on the store's side; the page only calls it in demo mode.
+ */
+export async function decryptNote(envelope, recipient) {
+  if (!envelope || envelope.v !== ENVELOPE_VERSION) throw new Error('Unsupported envelope version.');
+  const suite = getSuite(envelope.suite);
+  if (envelope.suite !== recipient.suite || envelope.kid !== recipient.kid) {
+    throw new Error('Envelope was encrypted to a different key.');
+  }
+  const encapsulated = unb64u(envelope.enc);
+  const iv = unb64u(envelope.iv);
+  if (encapsulated.length !== suite.encLength || iv.length !== 12) throw new Error('Malformed envelope.');
+
+  const sharedSecret = await suite.decapsulate(encapsulated, recipient.secretKey);
+  let key;
+  try {
+    key = await deriveAeadKey(suite.id, recipient.kid, recipient.publicKey, encapsulated, sharedSecret, 'decrypt');
+  } finally {
+    sharedSecret.fill(0);
+  }
+  try {
+    const pt = await subtle.decrypt(
+      { name: 'AES-GCM', iv, additionalData: aadFor(envelope), tagLength: 128 }, key, unb64u(envelope.ct),
+    );
+    return dec.decode(pt);
+  } catch {
+    throw new Error('Authentication failed: the envelope was tampered with or the key is wrong.');
+  }
+}
+
+/**
+ * Checks a server-supplied public key: known suite, correct length, and a kid that
+ * matches the key bytes. Returns the decoded recipient record.
+ */
+export async function importRecipientKey({ suite, kid, publicKey }) {
+  const s = getSuite(suite);
+  const pk = unb64u(publicKey);
+  if (pk.length !== s.publicKeyLength) throw new Error(`Bad ${suite} public key length.`);
+  if (s.id === 'mlkem768' || s.id === 'xwing') {
+    // FIPS 203 encapsulation-key check: run an encapsulation, which throws on a non-canonical key.
+    try { (s.id === 'xwing' ? xwing : ml_kem768).encapsulate(pk); } catch {
+      throw new Error(`Invalid ${suite} public key.`);
+    }
+  }
+  const expected = await keyId(s.id, pk);
+  if (kid !== expected) throw new Error(`Key id mismatch for ${suite}.`);
+  return { suite: s.id, kid, publicKey: pk, fingerprint: await fingerprint(s.id, pk) };
+}
+
+/** Makes an in-memory demo key pair for a suite (only used when no store key is published). */
+export async function generateDemoRecipient(suiteId) {
+  const s = getSuite(suiteId);
+  const { publicKey, secretKey } = s.keygen();
+  const kid = await keyId(s.id, publicKey);
+  return { suite: s.id, kid, publicKey, secretKey, fingerprint: await fingerprint(s.id, publicKey) };
+}
