+// UI controller for the Encrypted Delivery Notes panel on the homepage.
+import {
+  SUITES, MAX_NOTE_LENGTH, encryptNote, decryptNote, importRecipientKey, generateDemoRecipient,
+} from './delivery-notes-crypto.js';
+
+// The store publishes its long-term public keys here, in the form
+// { "keys": [ { "suite": "xwing", "kid": "...", "publicKey": "<base64url>" }, ... ] }.
+// Secret keys never leave the store's backend.
+const KEYS_ENDPOINT = '/api/delivery-notes/keys';
+const SUBMIT_ENDPOINT = '/api/delivery-notes';
+const STORAGE_KEY = 'dailyGrind.deliveryNote.v1'; // only ciphertext envelopes are stored
+
+const $ = (id) => document.getElementById(id);
+const form = $('dn-form');
+const noteEl = $('dn-note');
+const orderEl = $('dn-order');
+const counterEl = $('dn-counter');
+const statusEl = $('dn-status');
+const keyInfoEl = $('dn-keyinfo');
+const modeEl = $('dn-mode');
+const outputWrap = $('dn-output');
+const envelopeEl = $('dn-envelope');
+const submitBtn = $('dn-submit');
+const copyBtn = $('dn-copy');
+const clearBtn = $('dn-clear');
+const demoWrap = $('dn-demo');
+const decryptBtn = $('dn-decrypt');
+const tamperBtn = $('dn-tamper');
+const decryptedEl = $('dn-decrypted');
+
+const recipients = {}; // suite -> recipient record
+let demoMode = false;
+let lastEnvelope = null;
+
+function setStatus(msg, kind = 'info') {
+  statusEl.textContent = msg;
+  statusEl.dataset.kind = kind;
+}
+
+function selectedSuite() {
+  return form.querySelector('input[name="dn-suite"]:checked')?.value || 'xwing';
+}
+
+function renderKeyInfo() {
+  const r = recipients[selectedSuite()];
+  if (!r) { keyInfoEl.textContent = 'No key available for this suite.'; return; }
+  const s = SUITES[r.suite];
+  keyInfoEl.textContent = `${s.short} · key ${r.kid.slice(0, 10)}… · fingerprint ${r.fingerprint}`;
+}
+
+async function loadKeys() {
+  try {
+    const res = await fetch(KEYS_ENDPOINT, { cache: 'no-store', credentials: 'same-origin' });
+    if (!res.ok) throw new Error(`HTTP ${res.status}`);
+    const body = await res.json();
+    for (const k of body.keys || []) {
+      try {
+        const r = await importRecipientKey(k);
+        recipients[r.suite] = r;
+      } catch (err) {
+        console.warn('Rejected delivery-notes key:', err.message);
+      }
+    }
+    if (!Object.keys(recipients).length) throw new Error('no valid keys');
+  } catch {
+    // No published store key (for example a static preview), so generate in-memory demo key
+    // pairs. The secret keys exist only in this tab's memory and are gone on reload.
+    demoMode = true;
+    for (const id of Object.keys(SUITES)) recipients[id] = await generateDemoRecipient(id);
+  }
+  // Turn off suites the store doesn't publish keys for.
+  for (const input of form.querySelectorAll('input[name="dn-suite"]')) {
+    input.disabled = !recipients[input.value];
+  }
+  if (!recipients[selectedSuite()]) {
+    form.querySelector('input[name="dn-suite"]:not(:disabled)')?.click();
+  }
+  modeEl.hidden = !demoMode;
+  demoWrap.hidden = true;
+  renderKeyInfo();
+  submitBtn.disabled = false;
+  setStatus(demoMode
