+  lastEnvelope = envelope;
+  envelopeEl.value = JSON.stringify(envelope, null, 2);
+  outputWrap.hidden = false;
+  demoWrap.hidden = !(demoMode && recipients[envelope.suite]?.kid === envelope.kid);
+  decryptedEl.textContent = '';
+}
+
+async function submitEnvelope(envelope) {
+  if (demoMode) return false;
+  try {
+    const res = await fetch(SUBMIT_ENDPOINT, {
+      method: 'POST',
+      credentials: 'same-origin',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify(envelope),
+    });
+    return res.ok;
+  } catch {
+    return false;
+  }
+}
+
+form.addEventListener('submit', async (e) => {
+  e.preventDefault();
+  const recipient = recipients[selectedSuite()];
+  if (!recipient) return setStatus('No key available for the selected protection level.', 'error');
+  submitBtn.disabled = true;
+  setStatus('Encrypting on your device…');
+  try {
+    const envelope = await encryptNote(recipient, noteEl.value, { orderRef: orderEl.value.trim() });
+    noteEl.value = ''; // don't leave the plaintext on screen
+    counterEl.textContent = `0 / ${MAX_NOTE_LENGTH}`;
