+  if (e.target.name === 'dn-suite') renderKeyInfo();
+});
+
+noteEl.addEventListener('input', () => {
+  counterEl.textContent = `${noteEl.value.length} / ${MAX_NOTE_LENGTH}`;
+});
+
+copyBtn.addEventListener('click', async () => {
+  try {
+    await navigator.clipboard.writeText(envelopeEl.value);
