+  } catch {
+    envelopeEl.select();
+    setStatus('Copy failed. The envelope text is selected so you can copy it yourself.', 'warn');
+  }
+});
+
+clearBtn.addEventListener('click', () => {
+  try { localStorage.removeItem(STORAGE_KEY); } catch { /* ignore */ }
+  lastEnvelope = null;
+  envelopeEl.value = '';
+  outputWrap.hidden = true;
+  setStatus('Saved encrypted note removed from this device.', 'info');
+});
+
+decryptBtn.addEventListener('click', async () => {
+  if (!lastEnvelope) return;
+  try {
+    const text = await decryptNote(lastEnvelope, recipients[lastEnvelope.suite]);
+    decryptedEl.textContent = `Decrypted with the demo store key: "${text}"`;
+    decryptedEl.dataset.kind = 'ok';
+  } catch (err) {
+    decryptedEl.textContent = err.message;
+    decryptedEl.dataset.kind = 'error';
+  }
+});
+
+tamperBtn.addEventListener('click', async () => {
+  if (!lastEnvelope) return;
