+} else {
+  try {
+    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY) || 'null');
+    if (saved && saved.v === 1 && typeof saved.ct === 'string') showEnvelope(saved);
+  } catch { /* ignore corrupt storage */ }
+  loadKeys().catch((err) => setStatus(`Could not set up encryption: ${err.message}`, 'error'));
+}
