+        generateKeyPair,
+        deriveKeyPair: (seed, keyInfo) => deriveKeyPair(ctxVOPRF, seed, keyInfo),
+        blind: (input, rng = randomBytes) => blind(ctxVOPRF, input, rng),
+        blindEvaluateBatch(secretKey, publicKey, blinded, rng = randomBytes) {
