diff --git a/js/theme-toggle.js b/js/theme-toggle.js
new file mode 100644
index 0000000..7bef96a
--- /dev/null
+++ b/js/theme-toggle.js
@@ -0,0 +1,17 @@
+// Non-critical: wires up the theme toggle button after parsing.
+// The initial theme is applied by the inline render-blocking script in <head>.
+const button = document.querySelector('.theme-toggle');
+if (button) {
+  const sync = () => {
+    const dark = document.documentElement.dataset.theme === 'dark';
+    button.setAttribute('aria-pressed', String(dark));
+    button.textContent = dark ? 'Light mode' : 'Dark mode';
+  };
+  sync();
+  button.addEventListener('click', () => {
+    const next = document.documentElement.dataset.theme === 'dark' ? 'light' : 'dark';
+    document.documentElement.dataset.theme = next;
+    try { localStorage.setItem('theme', next); } catch {}
+    sync();
+  });
+}
