+:root {
+  --primary: #4e342e;
+  --secondary: #d7ccc8;
+  --accent: #ffab40;
+  --text: #3e2723;
+  --light: #fafafa;
+}
+
+* {
+  box-sizing: border-box;
+  margin: 0;
+  padding: 0;
+}
+
+body {
+  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
+  line-height: 1.6;
+  color: var(--text);
+  background-color: var(--light);
+  transition: background-color 0.3s, color 0.3s;
+}
+
+/* Navigation */
+nav {
+  background: var(--primary);
+  color: white;
+  padding: 1rem 5%;
+  display: flex;
+  justify-content: space-between;
+  align-items: center;
+  position: sticky;
+  top: 0;
+  z-index: 1000;
+}
+
+.logo {
+  color: white;
+  text-decoration: none;
+  font-size: 1.5rem;
+  font-weight: bold;
+  letter-spacing: 1px;
+}
+
+nav ul {
+  display: flex;
+  list-style: none;
+}
+
+nav ul li {
+  margin-left: 20px;
+}
+
+nav a {
+  color: white;
+  text-decoration: none;
+  font-size: 0.9rem;
+  transition: color 0.3s;
+}
+
+nav a:hover {
+  color: var(--accent);
+}
+
+.logout-link {
+  border: 1px solid var(--accent);
+  padding: 5px 12px;
+  border-radius: 4px;
+}
+
+/* Hero Section */
+.hero {
+  height: 60vh;
+  background: linear-gradient(rgba(0, 0, 0, 0.5), rgba(0, 0, 0, 0.5)),
+    url('https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?auto=format&fit=crop&w=1350&q=80');
+  background-size: cover;
+  background-position: center;
+  display: flex;
+  flex-direction: column;
+  justify-content: center;
+  align-items: center;
+  color: white;
+  text-align: center;
+  padding: 0 20px;
+}
+
+.hero h1 {
+  font-size: 3rem;
+  margin-bottom: 1rem;
+}
+
+/* Content Sections */
+.container {
+  max-width: 1100px;
+  margin: 40px auto;
+  padding: 0 20px;
+}
+
+.grid {
+  display: grid;
+  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
+  gap: 20px;
+  margin-top: 20px;
+}
+
+.card {
+  background: white;
+  padding: 20px;
+  border-radius: 8px;
+  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
+  text-align: center;
+}
+
+.card h3 {
+  margin-bottom: 10px;
+  color: var(--primary);
+}
+
+.btn {
+  display: inline-block;
+  background: var(--primary);
+  color: white;
+  padding: 10px 20px;
+  text-decoration: none;
+  border-radius: 5px;
+  margin-top: 15px;
+  transition: background 0.3s;
+}
+
+.btn:hover {
+  background: #3e2723;
+}
+
+footer {
+  background: var(--secondary);
+  text-align: center;
+  padding: 40px 20px;
+  margin-top: 40px;
+}
+
+.footer-links {
+  margin-bottom: 20px;
+}
+
+.footer-links a {
+  margin: 0 10px;
+  color: var(--text);
+  text-decoration: none;
+  font-size: 0.85rem;
+}
+
+/* ---------- Theme ---------- */
+:root[data-theme="dark"] {
+  --primary: #2b1d19;
+  --secondary: #3e2723;
+  --text: #efebe9;
+  --light: #1b1412;
+  color-scheme: dark;
+}
+
+:root[data-theme="dark"] .card { background: #2b201d; }
+:root[data-theme="dark"] .card h3 { color: var(--accent); }
+:root[data-theme="dark"] .btn { background: #6d4c41; }
+
+.theme-toggle {
+  background: none;
+  border: 1px solid rgba(255, 255, 255, 0.4);
+  color: white;
+  border-radius: 4px;
+  padding: 4px 10px;
+  margin-left: 20px;
+  cursor: pointer;
+  font: inherit;
+  font-size: 0.85rem;
+}
+
+.nav-right { display: flex; align-items: center; }
+
+:root[data-page="menu"] nav a[href="/menu"],
+:root[data-page="locations"] nav a[href="/locations"] {
+  color: var(--accent);
+}
+
+/* Compact hero for inner pages */
+.hero.hero--compact { height: 35vh; }
+.hero--menu {
+  background-image: linear-gradient(rgba(0, 0, 0, 0.55), rgba(0, 0, 0, 0.55)),
+    url('https://images.unsplash.com/photo-1509042239860-f550ce710b93?auto=format&fit=crop&w=1350&q=80');
+}
+.hero--locations {
+  background-image: linear-gradient(rgba(0, 0, 0, 0.55), rgba(0, 0, 0, 0.55)),
+    url('https://images.unsplash.com/photo-1554118811-1e0d58224f24?auto=format&fit=crop&w=1350&q=80');
+}
+
+.price { font-weight: bold; color: var(--accent); margin-top: 8px; }
+
+/* ---------- Cross-document view transitions ---------- */
+@view-transition {
+  navigation: auto;
+}
+
+/* Persistent header: stays put (no crossfade flicker) across pages. */
+nav { view-transition-name: site-nav; }
+/* The hero morphs between the homepage banner and inner-page banners. */
+.hero { view-transition-name: hero; }
+.hero h1 { view-transition-name: hero-title; }
+/* Primary above-the-fold content slides in. */
+main { view-transition-name: page-content; }
+footer { view-transition-name: site-footer; }
+
+::view-transition-group(*) {
+  animation-duration: 0.4s;
+  animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
+}
+
+::view-transition-old(site-nav),
+::view-transition-new(site-nav) {
+  animation: none;
+  mix-blend-mode: normal;
+}
+
+::view-transition-old(hero),
+::view-transition-new(hero) {
+  height: 100%;
+  object-fit: cover;
+}
+
+@keyframes dg-fade-out { to { opacity: 0; } }
+@keyframes dg-fade-in { from { opacity: 0; } }
+@keyframes dg-slide-out-left { to { transform: translateX(-40px); } }
+@keyframes dg-slide-in-right { from { transform: translateX(40px); } }
+@keyframes dg-slide-out-right { to { transform: translateX(40px); } }
+@keyframes dg-slide-in-left { from { transform: translateX(-40px); } }
+
+::view-transition-old(page-content) {
+  animation: 0.2s ease-in both dg-fade-out, 0.4s ease both dg-slide-out-left;
+}
+::view-transition-new(page-content) {
+  animation: 0.3s ease-out 0.1s both dg-fade-in, 0.4s cubic-bezier(0.22, 1, 0.36, 1) both dg-slide-in-right;
+}
+
+html:active-view-transition-type(backwards)::view-transition-old(page-content) {
+  animation-name: dg-fade-out, dg-slide-out-right;
+}
+html:active-view-transition-type(backwards)::view-transition-new(page-content) {
+  animation-name: dg-fade-in, dg-slide-in-left;
+}
+
+@media (prefers-reduced-motion: reduce) {
+  @view-transition { navigation: none; }
+}
diff --git a/assets/theme.js b/assets/theme.js
new file mode 100644
index 0000000..56bda03
--- /dev/null
+++ b/assets/theme.js
@@ -0,0 +1,45 @@
+/*
+ * Initial theme + layout bootstrap.
+ * Loaded as a classic, synchronous <script> in <head> so it is parser- and
+ * render-blocking: the theme is applied before first paint and before any
+ * cross-document view transition captures the incoming page (no flash).
+ */
+(function () {
+  var root = document.documentElement;
+  var KEY = 'dg-theme';
+  var stored = null;
+  try { stored = localStorage.getItem(KEY); } catch (e) {}
+  var prefersDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
+  root.dataset.theme = stored === 'dark' || stored === 'light' ? stored : (prefersDark ? 'dark' : 'light');
+
+  // Layout hint: record the current section so CSS can style the active nav link
+  // before paint.
+  var seg = location.pathname.split('/').filter(Boolean)[0] || 'home';
+  root.dataset.page = seg;
+
+  window.dgToggleTheme = function () {
+    var next = root.dataset.theme === 'dark' ? 'light' : 'dark';
+    root.dataset.theme = next;
+    try { localStorage.setItem(KEY, next); } catch (e) {}
+  };
+
+  // Tag transitions with a direction so CSS can slide forward/back.
+  var ORDER = { home: 0, menu: 1, locations: 2 };
+  function rank(url) {
+    try {
+      var s = new URL(url, location.href).pathname.split('/').filter(Boolean)[0] || 'home';
+      return s in ORDER ? ORDER[s] : 1;
+    } catch (e) { return 1; }
+  }
+  window.addEventListener('pagereveal', function (e) {
+    if (!e.viewTransition || !window.navigation || !navigation.activation) return;
+    var from = navigation.activation.from;
+    if (!from) return;
+    e.viewTransition.types.add(rank(location.href) >= rank(from.url) ? 'forwards' : 'backwards');
+  });
+
+  document.addEventListener('DOMContentLoaded', function () {
+    var btn = document.querySelector('.theme-toggle');
+    if (btn) btn.addEventListener('click', window.dgToggleTheme);
+  });
+})();
