+/* ------------------------------------------------------------------
+ * Cross-document view transitions
+ * Every page loads this stylesheet, so all same-origin navigations
+ * (homepage <-> category <-> article) opt in on both sides.
+ * ------------------------------------------------------------------ */
+@view-transition {
+  navigation: auto;
+}
+
+@media (prefers-reduced-motion: reduce) {
+  @view-transition {
+    navigation: none;
+  }
+}
+
+/* The masthead is identical on every page: lift it out of the root
+ * snapshot so it stays put while the page content below transitions. */
+.site-header {
+  view-transition-name: site-header;
+}
+
+::view-transition-group(site-header) {
+  animation-duration: 0s;
+}
+
+/* Page content: quick fade out, then fade in while sliding up slightly. */
+::view-transition-old(root) {
+  animation: 160ms ease-in both vt-fade-out;
+}
+
+::view-transition-new(root) {
+  animation: 280ms cubic-bezier(0.2, 0, 0, 1) 60ms both vt-fade-in-up;
+}
+
+@keyframes vt-fade-out {
+  to {
+    opacity: 0;
+  }
+}
+
+@keyframes vt-fade-in-up {
+  from {
+    opacity: 0;
+    transform: translateY(12px);
+  }
+}

