+/* ---------------------------------------------------------------------------
+ * Page transitions (cross-document View Transitions API)
+ *
+ * Header, ads and footer are identical on every page, so the root snapshot is
+ * swapped without animation. Only the page body (#page-content) animates: the
+ * old content fades out while the new one fades and slides in.
+ * Render blocking (<link rel="expect" blocking="render"> in Layout.astro)
+ * guarantees the new snapshot is taken only once the content is fully parsed
+ * and styled.
+ * ------------------------------------------------------------------------- */
+@view-transition {
+  navigation: auto;
+}
+
+#page-content {
+  view-transition-name: page-content;
+}
+
+::view-transition-old(root),
+::view-transition-new(root) {
+  animation: none;
+}
+
+::view-transition-group(page-content) {
+  animation-duration: 320ms;
+  animation-timing-function: cubic-bezier(0.2, 0, 0, 1);
+}
+
+::view-transition-old(page-content) {
+  animation: 160ms cubic-bezier(0.4, 0, 1, 1) both page-fade-out;
+}
+
+::view-transition-new(page-content) {
+  animation: 320ms cubic-bezier(0, 0, 0.2, 1) 60ms both page-fade-in;
+}
+
+/* Snapshots keep their natural size; anchor them to the top so differing
+   page heights don't cause a stretched or vertically shifting image. */
+::view-transition-old(page-content),
+::view-transition-new(page-content) {
+  height: auto;
+  object-position: top;
+}
+
+@keyframes page-fade-out {
+  to {
+    opacity: 0;
+  }
+}
+
+@keyframes page-fade-in {
+  from {
+    opacity: 0;
+    transform: translateY(12px);
+  }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  ::view-transition-group(*),
+  ::view-transition-old(*),
+  ::view-transition-new(*) {
+    animation: none !important;
+  }
+}

