+            '); the repeat is at ' + fmtOffset(offsetMinutes(instants[1], tz)) + '.');
+          grid.dataset.state = 'ambiguous';
+        } else {
+          setStatus('ok',
+            'Tasting starts ' + fmtDate(ms, tz) + ' at ' + fmtTime(ms, tz) + ' in ' + hostLabel +
+            ' (' + fmtOffset(offsetMinutes(ms, tz)) + ') — ' + new Date(ms).toISOString().replace('.000', '') + '.');
