+          card.appendChild(el('div', 'date', fmtDate(ms, zone) +
+            (dayDiff ? (dayDiff > 0 ? '  (+' + dayDiff + ' day)' : '  (' + dayDiff + ' day)') : '')));
+          const meta = el('div', 'meta');
+          const abbr = zoneAbbr(ms, zone);
+          meta.appendChild(el('span', 'tag', fmtOffset(off) + (abbr && !/^GMT/.test(abbr) ? ' · ' + abbr : '')));
