+// Drives the smallpt WebAssembly path tracer: splits the image into bands,
+// renders each band in its own Web Worker, and composites progress to a canvas.
+const WIDTH = 320;
+const HEIGHT = 240;
+const MAX_SPP = 512;
+
+// Sphere indices in smallpt's scene (see wasm/smallpt.cpp).
+const SPHERES = [
+  { index: 0, name: 'Left wall', base: [0.75, 0.25, 0.25] },
+  { index: 1, name: 'Right wall', base: [0.25, 0.25, 0.75] },
+  { index: 2, name: 'Back wall', base: [0.75, 0.75, 0.75] },
+  { index: 4, name: 'Floor', base: [0.75, 0.75, 0.75] },
+  { index: 5, name: 'Ceiling', base: [0.75, 0.75, 0.75] },
+  { index: 6, name: 'Mirror ball', base: [0.999, 0.999, 0.999], shiny: true },
+  { index: 7, name: 'Glass ball', base: [0.999, 0.999, 0.999], shiny: true },
+];
+
+const canvas = document.getElementById('smallpt-canvas');
+const ctx = canvas.getContext('2d');
+const status = document.getElementById('smallpt-status');
+const swatches = document.getElementById('smallpt-swatches');
+const randomButton = document.getElementById('smallpt-randomize');
+const resetButton = document.getElementById('smallpt-reset');
+
+canvas.width = WIDTH;
+canvas.height = HEIGHT;
+
+let workers = [];
+
+function hslToRgb(h, s, l) {
+  const k = (n) => (n + h * 12) % 12;
+  const a = s * Math.min(l, 1 - l);
+  const f = (n) => l - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
+  return [f(0), f(8), f(4)];
+}
+
+function randomColors() {
+  return Object.fromEntries(
+    SPHERES.map(({ index, shiny }) => {
+      // Keep walls at a moderate albedo (like the original .75/.25) and the
+      // mirror/glass tints bright so they stay reflective rather than dark.
+      const rgb = shiny
+        ? hslToRgb(Math.random(), 0.4 + Math.random() * 0.5, 0.7 + Math.random() * 0.15)
+        : hslToRgb(Math.random(), 0.3 + Math.random() * 0.6, 0.35 + Math.random() * 0.3);
+      return [index, rgb];
+    }),
+  );
+}
+
+function showSwatches(colors) {
+  swatches.replaceChildren(
+    ...SPHERES.map(({ index, name, base }) => {
+      const [r, g, b] = (colors[index] ?? base).map((c) => Math.round(c * 255));
+      const li = document.createElement('li');
+      const chip = document.createElement('span');
+      chip.className = 'swatch';
+      chip.style.backgroundColor = `rgb(${r} ${g} ${b})`;
+      li.append(chip, name);
+      return li;
+    }),
+  );
+}
+
+function render(colors = {}) {
+  for (const w of workers) w.terminate();
+  showSwatches(colors);
+
+  const count = Math.max(1, Math.min(navigator.hardwareConcurrency || 4, 16, HEIGHT));
+  const seed = crypto.getRandomValues(new Uint32Array(1))[0];
+  const bandSpp = new Array(count).fill(0);
+  const start = performance.now();
+
+  status.ariaBusy = 'true'; // suppress live-region chatter until the render finishes
+  status.textContent = `Rendering ${WIDTH}×${HEIGHT} on ${count} worker${count > 1 ? 's' : ''}…`;
+  workers = Array.from({ length: count }, (_, i) => {
+    const y0 = Math.floor((HEIGHT * i) / count);
+    const y1 = Math.floor((HEIGHT * (i + 1)) / count);
+    const worker = new Worker(new URL('./worker.js', import.meta.url), { type: 'module' });
+    worker.onmessage = ({ data }) => {
+      ctx.putImageData(new ImageData(data.pixels, WIDTH, data.y1 - data.y0), 0, data.y0);
+      bandSpp[i] = data.spp;
+      const minSpp = Math.min(...bandSpp);
+      const secs = ((performance.now() - start) / 1000).toFixed(1);
+      if (minSpp >= MAX_SPP) status.ariaBusy = 'false';
+      status.textContent =
+        minSpp >= MAX_SPP
+          ? `Done: ${MAX_SPP} samples/pixel in ${secs}s on ${count} workers.`
+          : `${minSpp} samples/pixel · ${secs}s · ${count} workers`;
+    };
+    worker.onerror = (e) => {
+      status.ariaBusy = 'false';
+      status.textContent = `Render failed: ${e.message ?? 'worker error'}`;
+    };
+    worker.postMessage({ width: WIDTH, height: HEIGHT, y0, y1, seed: seed + i * 7919, colors, maxSpp: MAX_SPP });
+    return worker;
+  });
+}
+
+randomButton.addEventListener('click', () => render(randomColors()));
+resetButton.addEventListener('click', () => render());
+render();
