+// Renders one horizontal band of the smallpt image in WebAssembly and streams
+// progressive results back to the page after every pass.
+import initSmallpt from './smallpt.js';
+
+const wasmReady = initSmallpt();
+
+self.onmessage = async ({ data }) => {
+  const { width, height, y0, y1, seed, colors, maxSpp } = data;
+  const wasm = await wasmReady;
+
+  wasm._reset_scene();
+  for (const [i, [r, g, b]] of Object.entries(colors ?? {})) {
+    wasm._set_sphere_color(Number(i), r, g, b);
+  }
+
+  const ptr = wasm._begin_render(width, height, y0, y1, seed >>> 0);
+  const byteLength = width * (y1 - y0) * 4;
+  let spp = 0;
+  while (spp < maxSpp) {
+    spp = wasm._render_pass();
+    // Read HEAPU8 fresh after each call: memory growth detaches old buffers.
+    const pixels = new Uint8ClampedArray(wasm.HEAPU8.buffer, ptr, byteLength).slice();
+    self.postMessage({ y0, y1, spp, pixels }, [pixels.buffer]);
+    // Yield so the page can terminate us promptly between passes.
+    await new Promise((resolve) => setTimeout(resolve, 0));
+  }
+};
