+// Web Worker that runs the smallpt WebAssembly module on a band of rows.
+// Protocol (main -> worker):
+//   { type: 'render', job, w, h, y0, y1, seed, passes, colors: [[r,g,b] | null, ...] }
+//     Starts a new render job (implicitly cancelling any previous one).
+//   { type: 'stop' }  Cancels the current job.
+// Protocol (worker -> main):
+//   { type: 'ready' }
+//   { type: 'band', job, pass, row, w, rows, pixels }  RGBA8 rows starting at
+//     canvas row `row` (top-down), sent after every completed pass.
+//   { type: 'done', job }
+importScripts('smallpt.js');
+
+let mod = null;
+let currentJob = -1;
+const ready = createSmallpt().then((m) => {
+  mod = m;
+  postMessage({ type: 'ready' });
+});
+
+function yieldToEvents() {
+  return new Promise((resolve) => setTimeout(resolve, 0));
+}
+
+async function render(msg) {
+  await ready;
+  const { job, w, h, y0, y1, seed, passes, colors } = msg;
+  if (job !== currentJob) return;
+  colors.forEach((c, i) => {
+    if (c) mod._set_sphere_color(i, c[0], c[1], c[2]);
+  });
+  const ptr = mod._init(w, h, seed >>> 0);
+  // smallpt rows are bottom-up; band [y0, y1) lands at canvas rows [h-y1, h-y0).
+  const row = h - y1;
+  const rows = y1 - y0;
+  for (let p = 0; p < passes; p++) {
+    const pass = mod._render_pass(y0, y1);
+    // HEAPU8 may be replaced on memory growth, so read it after each call.
+    const start = ptr + row * w * 4;
+    const pixels = mod.HEAPU8.slice(start, start + rows * w * 4);
+    postMessage({ type: 'band', job, pass, row, w, rows, pixels }, [pixels.buffer]);
+    await yieldToEvents(); // let a newer 'render' or 'stop' message arrive
+    if (job !== currentJob) return;
+  }
+  postMessage({ type: 'done', job });
+}
+
+onmessage = (e) => {
+  const msg = e.data;
+  if (msg.type === 'render') {
+    currentJob = msg.job;
+    render(msg);
+  } else if (msg.type === 'stop') {
+    currentJob = -1;
+  }
+};
