+// Module worker that drives the smallpt WebAssembly build progressively.
+//
+// Messages in:  { type: 'render', id, width, height, passes, seed, colors }
+//               colors: array of [r, g, b] (0..1) per sphere, or null for the
+//               scene's original colors.
+// Messages out: { type: 'ready' }
+//               { type: 'progress', id, pass, passes, spp, ms, pixels }
+//               { type: 'done', id, spp, ms }
+//               { type: 'error', message }
+import initSmallpt from './smallpt.js';
+
+const ROWS_PER_CHUNK = 12; // yield to the event loop between row chunks
+const yieldToEventLoop = () => new Promise((resolve) => setTimeout(resolve));
+
+let wasm;
+let currentId = 0; // id of the most recent render request
+
+async function render({ id, width, height, passes, seed, colors }) {
+  currentId = id;
+
+  wasm._sp_reset_colors();
+  if (colors) {
+    colors.forEach(([r, g, b], i) => wasm._sp_set_color(i, r, g, b));
+  }
+  const ptr = wasm._sp_init(width, height, seed);
+  const byteLength = width * height * 4;
+  const start = performance.now();
+
+  for (let pass = 1; pass <= passes; pass++) {
+    for (let y = 0; y < height; y += ROWS_PER_CHUNK) {
+      wasm._sp_render_rows(y, y + ROWS_PER_CHUNK);
+      await yieldToEventLoop();
+      if (currentId !== id) return; // superseded by a newer request
+    }
+    wasm._sp_end_pass();
+    wasm._sp_update_image();
+
+    // Read HEAPU8 fresh: memory growth detaches old views.
+    const pixels = wasm.HEAPU8.slice(ptr, ptr + byteLength);
+    self.postMessage(
+      {
+        type: 'progress',
+        id,
+        pass,
+        passes,
+        spp: pass * 4,
+        ms: performance.now() - start,
+        pixels,
+      },
+      [pixels.buffer],
+    );
+  }
+  self.postMessage({
+    type: 'done',
+    id,
+    spp: passes * 4,
+    ms: performance.now() - start,
+  });
+}
+
+self.addEventListener('message', (event) => {
+  if (event.data?.type === 'render') {
+    render(event.data).catch((err) => {
+      self.postMessage({ type: 'error', message: String(err?.message ?? err) });
+    });
+  }
+});
+
+try {
+  wasm = await initSmallpt();
+  self.postMessage({ type: 'ready' });
+} catch (err) {
+  self.postMessage({ type: 'error', message: String(err?.message ?? err) });
+}
