+++ b/src/components/SmallptRenderer.tsx
@@ -0,0 +1,204 @@
+import { useCallback, useEffect, useRef, useState } from 'react';
+
+const WIDTH = 320;
+const HEIGHT = 240;
+const PASSES = 64; // 4 samples per pixel per pass -> 256 spp
+
+type RGB = [number, number, number];
+
+// Sphere order matches the `spheres[]` array in wasm/smallpt.cpp.
+const SPHERES = [
+  { name: 'Left wall', kind: 'wall' },
+  { name: 'Right wall', kind: 'wall' },
+  { name: 'Back wall', kind: 'wall' },
+  { name: 'Front wall', kind: 'fixed' }, // behind the camera, stays black
+  { name: 'Floor', kind: 'wall' },
+  { name: 'Ceiling', kind: 'wall' },
+  { name: 'Mirror sphere', kind: 'shiny' },
+  { name: 'Glass sphere', kind: 'shiny' },
+  { name: 'Light', kind: 'fixed' },
+] as const;
+
+const DEFAULT_COLORS: RGB[] = [
+  [0.75, 0.25, 0.25],
+  [0.25, 0.25, 0.75],
+  [0.75, 0.75, 0.75],
+  [0, 0, 0],
+  [0.75, 0.75, 0.75],
+  [0.75, 0.75, 0.75],
+  [0.999, 0.999, 0.999],
+  [0.999, 0.999, 0.999],
+  [0, 0, 0],
+];
+
+function hslToRgb(h: number, s: number, l: number): RGB {
+  const k = (n: number) => (n + h / 30) % 12;
+  const a = s * Math.min(l, 1 - l);
+  const f = (n: number) => l - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
+  return [f(0), f(8), f(4)];
+}
+
+function randomColors(): RGB[] {
+  return SPHERES.map((sphere, i) => {
+    if (sphere.kind === 'fixed') return DEFAULT_COLORS[i];
+    const hue = Math.random() * 360;
+    if (sphere.kind === 'shiny') {
+      // Keep mirror/glass highly reflective; just tint them.
+      const [r, g, b] = hslToRgb(hue, 0.3 + Math.random() * 0.5, 0.5);
+      const max = Math.max(r, g, b);
+      return [r, g, b].map((c) => (c / max) * 0.999) as RGB;
+    }
+    // Diffuse walls: albedo up to ~0.8, like the original scene's 0.75.
+    const [r, g, b] = hslToRgb(hue, 0.35 + Math.random() * 0.6, 0.3 + Math.random() * 0.35);
+    return [r, g, b].map((c) => c * 0.95) as RGB;
+  });
+}
+
+// Show the swatch roughly as it appears in the gamma-corrected render.
+const toCss = ([r, g, b]: RGB) =>
+  `rgb(${[r, g, b].map((c) => Math.round(Math.pow(c, 1 / 2.2) * 255)).join(' ')})`;
+
+type Status =
+  | { state: 'loading' }
+  | { state: 'rendering'; spp: number; ms: number }
+  | { state: 'done'; spp: number; ms: number }
+  | { state: 'error'; message: string };
+
+export default function SmallptRenderer() {
+  const canvasRef = useRef<HTMLCanvasElement>(null);
+  const workerRef = useRef<Worker | null>(null);
+  const requestIdRef = useRef(0);
+  const [ready, setReady] = useState(false);
+  const [colors, setColors] = useState<RGB[]>(DEFAULT_COLORS);
+  const [status, setStatus] = useState<Status>({ state: 'loading' });
+
+  const startRender = useCallback((nextColors: RGB[] | null) => {
+    const worker = workerRef.current;
+    if (!worker) return;
+    const id = ++requestIdRef.current;
+    setColors(nextColors ?? DEFAULT_COLORS);
+    setStatus({ state: 'rendering', spp: 0, ms: 0 });
+    worker.postMessage({
+      type: 'render',
+      id,
+      width: WIDTH,
+      height: HEIGHT,
+      passes: PASSES,
+      seed: Math.floor(Math.random() * 65536),
+      colors: nextColors,
+    });
+  }, []);
+
+  useEffect(() => {
+    const worker = new Worker(`${import.meta.env.BASE_URL}smallpt/worker.js`, {
+      type: 'module',
+    });
+    workerRef.current = worker;
+    const ctx = canvasRef.current?.getContext('2d');
+
+    worker.addEventListener('message', (event) => {
+      const msg = event.data;
+      if (msg.type === 'ready') {
+        setReady(true);
+        startRender(null); // first render uses smallpt's original scene
+      } else if (msg.type === 'error') {
+        setStatus({ state: 'error', message: msg.message });
+      } else if (msg.id !== requestIdRef.current) {
+        // Stale message from a superseded render.
+      } else if (msg.type === 'progress') {
+        ctx?.putImageData(
+          new ImageData(new Uint8ClampedArray(msg.pixels.buffer), WIDTH, HEIGHT),
+          0,
+          0,
+        );
+        setStatus({ state: 'rendering', spp: msg.spp, ms: msg.ms });
+      } else if (msg.type === 'done') {
+        setStatus({ state: 'done', spp: msg.spp, ms: msg.ms });
+      }
+    });
+    worker.addEventListener('error', () => {
+      setStatus({ state: 'error', message: 'Failed to load the WebAssembly worker.' });
+    });
+
+    return () => {
+      worker.terminate();
+      workerRef.current = null;
+    };
+  }, [startRender]);
+
+  let statusText: string;
+  switch (status.state) {
+    case 'loading':
+      statusText = 'Loading WebAssembly…';
+      break;
+    case 'rendering':
+      statusText =
+        status.spp === 0
+          ? 'Rendering first pass…'
+          : `Rendering… ${status.spp} / ${PASSES * 4} samples per pixel (${(status.ms / 1000).toFixed(1)}s)`;
+      break;
+    case 'done':
+      statusText = `Done: ${status.spp} samples per pixel in ${(status.ms / 1000).toFixed(1)}s`;
+      break;
+    case 'error':
+      statusText = `Error: ${status.message}`;
+      break;
+  }
+
+  return (
+    <div className="grid gap-6 md:grid-cols-[minmax(0,2fr)_minmax(0,1fr)] items-start">
+      <figure>
+        <canvas
+          ref={canvasRef}
+          width={WIDTH}
+          height={HEIGHT}
+          className="w-full h-auto bg-black aspect-[4/3]"
+          role="img"
+          aria-label="Path-traced Cornell box with a mirror sphere and a glass sphere, rendered by smallpt"
+        />
+        <figcaption className="mt-2 text-sm text-gray-500" aria-live="polite">
+          {statusText}
+        </figcaption>
+      </figure>
+
+      <div>
+        <p className="text-gray-700 mb-4">
+          This image is path traced live in your browser by{' '}
+          <a
+            className="underline hover:text-amber-500"
+            href="http://www.kevinbeason.com/smallpt/"
+            target="_blank"
+            rel="noopener noreferrer"
+          >
+            smallpt
+          </a>
+          , Kevin Beason's 99-line C++ global illumination renderer, compiled to WebAssembly and
+          running in a Web Worker. Each pass adds 4 samples per pixel, so the noise fades as it
+          renders.
+        </p>
+        <button
+          type="button"
+          onClick={() => startRender(randomColors())}
+          disabled={!ready}
+          className="w-full rounded bg-gray-900 px-4 py-2 font-semibold text-white hover:bg-amber-500 hover:text-gray-900 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-amber-500 disabled:cursor-not-allowed disabled:opacity-50"
+        >
+          Render again with random colors
+        </button>
+        <ul className="mt-4 grid grid-cols-2 gap-x-4 gap-y-1 text-sm text-gray-600">
+          {SPHERES.map((sphere, i) =>
+            sphere.kind === 'fixed' ? null : (
+              <li key={sphere.name} className="flex items-center gap-2">
+                <span
+                  className="inline-block size-4 rounded-full border border-gray-300"
+                  style={{ background: toCss(colors[i]) }}
+                  aria-hidden="true"
+                />
+                {sphere.name}
+              </li>
+            ),
+          )}
+        </ul>
+      </div>
+    </div>
+  );
+}
