@@ -0,0 +1,20 @@
+#!/bin/sh
+# Compiles smallpt to an ES module + .wasm in public/smallpt/.
+# Requires Emscripten (em++) on PATH. Outputs are committed, so the regular
+# site build does not need Emscripten installed. (-flto is omitted: single TU,
+# and some distro Emscripten packages ship a broken LTO libc++.)
+set -eu
+cd "$(dirname "$0")"
+OUT=../public/smallpt
+mkdir -p build "$OUT"
+em++ -c smallpt.cpp -o build/smallpt.o -O3 -Wall -Werror
+em++ build/smallpt.o -o "$OUT/smallpt.js" \
+  -O3 \
+  -sSTRICT \
+  -sEXPORT_ES6 \
+  -sENVIRONMENT=worker \
+  -sALLOW_MEMORY_GROWTH \
+  -sSTACK_SIZE=1MB \
+  -sEXPORTED_FUNCTIONS=_sp_sphere_count,_sp_set_color,_sp_reset_colors,_sp_init,_sp_passes,_sp_render_rows,_sp_end_pass,_sp_update_image \
+  -sEXPORTED_RUNTIME_METHODS=HEAPU8
+echo "Built $OUT/smallpt.js and $OUT/smallpt.wasm"
