+// Web Worker that runs smallpt (compiled to WebAssembly) and streams rows back.
+// Message in:  { w, h, colors: [[r,g,b] | null, ...], passes, spp, index, count }
+//   Renders `passes` passes of `spp` samples/pixel for rows y where
+//   y % count === index (rows are in smallpt's bottom-up order).
+// Messages out: { type: 'ready' } then { type: 'row', pass, y, pixels } ... { type: 'done' }
+importScripts('smallpt.js');
+
+const modulePromise = createSmallpt();
+
+self.onmessage = async (e) => {
+  const { w, h, colors, passes, spp, index, count } = e.data;
+  const M = await modulePromise;
+  colors.forEach((c, i) => { if (c) M._set_sphere_color(i, c[0], c[1], c[2]); });
+  const ptr = M._render_begin(w, h);
+  const rowBytes = w * 4;
+  for (let pass = 0; pass < passes; pass++) {
+    for (let y = index; y < h; y += count) {
+      M._render_row(y, pass, spp);
+      const offset = ptr + (h - y - 1) * rowBytes;
+      const pixels = M.HEAPU8.slice(offset, offset + rowBytes);
+      self.postMessage({ type: 'row', pass, y, pixels }, [pixels.buffer]);
+    }
+  }
+  self.postMessage({ type: 'done' });
+};
