new file mode 100644
index 0000000..14df532
--- /dev/null
+++ b/src/components/SmallptRenderer.astro
@@ -0,0 +1,189 @@
+---
+// Client-side path tracer: Kevin Beason's smallpt compiled to WebAssembly
+// (see wasm/smallpt.cpp and wasm/build.sh). Rendering runs in Web Workers.
+const base = import.meta.env.BASE_URL;
+const workerUrl = `${base.endsWith('/') ? base : base + '/'}wasm/smallpt-worker.js`;
+---
+<section class="p-4 md:p-6" data-smallpt data-worker-url={workerUrl}>
+  <h2 class="text-3xl font-bold border-b-2 border-gray-900 pb-2 mb-6 lg:mb-8">
+    Rendered In Your Browser
+  </h2>
+  <div class="grid md:grid-cols-3 gap-6 items-start">
+    <figure class="md:col-span-2">
+      <canvas
+        data-smallpt-canvas
+        width="480"
+        height="360"
+        class="w-full h-auto bg-black block"
+        aria-label="Path-traced image of two spheres in a box, rendered by smallpt"
+      ></canvas>
+      <div class="mt-2 h-1 bg-gray-300" aria-hidden="true">
+        <div data-smallpt-bar class="h-1 bg-amber-400 transition-[width] duration-150" style="width: 0%"></div>
+      </div>
+      <figcaption data-smallpt-status class="text-xs text-gray-500 mt-2" aria-live="polite">
+        Loading WebAssembly…
+      </figcaption>
+    </figure>
+    <div>
+      <h3 class="text-xl font-bold text-gray-900 mb-2">A path tracer in 99 lines, now in WebAssembly</h3>
+      <p class="text-gray-700 mb-4">
+        This image is rendered as you watch, by
+        <a class="underline hover:text-amber-500" href="http://www.kevinbeason.com/smallpt/" target="_blank" rel="noopener">smallpt</a>,
+        Kevin Beason's tiny C++ global-illumination renderer, compiled to WebAssembly with Emscripten.
+        It runs in Web Workers on your CPU. It starts out noisy and gets cleaner with each pass.
+      </p>
+      <button
+        type="button"
+        data-smallpt-button
+        class="bg-gray-900 text-white font-bold px-4 py-2 hover:bg-amber-400 hover:text-gray-900 transition-colors disabled:opacity-50"
+      >
+        Randomize sphere colors
+      </button>
+      <ul data-smallpt-swatches class="mt-4 grid grid-cols-2 gap-x-4 gap-y-1 text-sm text-gray-700"></ul>
+    </div>
+  </div>
+</section>
+
+<script>
+  // smallpt's scene is 9 spheres: 6 huge ones form the walls, then a mirror
+  // ball, a glass ball and the light. Indices match `spheres[]` in smallpt.cpp.
+  const ORIGINAL: ([number, number, number] | null)[] = [
+    [0.75, 0.25, 0.25], // left wall
+    [0.25, 0.25, 0.75], // right wall
+    [0.75, 0.75, 0.75], // back wall
+    null, // front (behind camera, black)
+    [0.75, 0.75, 0.75], // floor
+    [0.75, 0.75, 0.75], // ceiling
+    [0.999, 0.999, 0.999], // mirror ball
+    [0.999, 0.999, 0.999], // glass ball
+    null, // light
+  ];
+  const LABELS: Record<number, string> = {
+    0: 'Left wall', 1: 'Right wall', 2: 'Back wall', 4: 'Floor', 5: 'Ceiling', 6: 'Mirror ball', 7: 'Glass ball',
+  };
+  const PASSES = 16;
+  const SPP_PER_PASS = 8; // 128 samples per pixel in total
+
+  function hsv(h: number, s: number, v: number): [number, number, number] {
+    const f = (n: number) => {
+      const k = (n + h * 6) % 6;
+      return v - v * s * Math.max(0, Math.min(k, 4 - k, 1));
+    };
+    return [f(5), f(3), f(1)];
+  }
+
+  function randomColors() {
+    return ORIGINAL.map((c, i) => {
+      if (!c) return null;
+      // Mirror/glass: light tints keep them reflective. Walls: saturated
+      // albedos kept <= 0.85 so the box doesn't blow out.
+      if (i === 6 || i === 7) return hsv(Math.random(), 0.15 + Math.random() * 0.5, 0.999);
+      return hsv(Math.random(), 0.35 + Math.random() * 0.6, 0.55 + Math.random() * 0.3);
+    });
+  }
+
+  function init() {
+    const root = document.querySelector<HTMLElement>('[data-smallpt]');
+    if (!root || root.dataset.ready) return;
+    root.dataset.ready = '1';
+
+    const canvas = root.querySelector<HTMLCanvasElement>('[data-smallpt-canvas]')!;
+    const status = root.querySelector<HTMLElement>('[data-smallpt-status]')!;
+    const bar = root.querySelector<HTMLElement>('[data-smallpt-bar]')!;
+    const button = root.querySelector<HTMLButtonElement>('[data-smallpt-button]')!;
+    const swatches = root.querySelector<HTMLElement>('[data-smallpt-swatches]')!;
+    const ctx = canvas.getContext('2d')!;
+    const w = canvas.width, h = canvas.height;
+    const workerUrl = root.dataset.workerUrl!;
+    const count = Math.max(1, Math.min(navigator.hardwareConcurrency || 4, 16));
+    let workers: Worker[] = [];
+    let generation = 0; // bumped on every render so stale messages/frames are ignored
+
+    function stop() {
+      workers.forEach((wk) => wk.terminate());
+      workers = [];
+    }
+
+    function showSwatches(colors: ([number, number, number] | null)[]) {
+      swatches.replaceChildren(
+        ...colors.flatMap((c, i) => {
+          if (!c) return [];
+          const li = document.createElement('li');
+          li.className = 'flex items-center gap-2';
+          const sw = document.createElement('span');
+          sw.className = 'inline-block w-3 h-3 border border-gray-400';
+          sw.style.background = `rgb(${c.map((v) => Math.round(v * 255)).join(',')})`;
+          li.append(sw, LABELS[i]);
+          return [li];
+        }),
+      );
+    }
+
+    function render(colors: ([number, number, number] | null)[]) {
+      stop();
+      const gen = ++generation;
+      showSwatches(colors);
+      const image = ctx.createImageData(w, h);
+      const rowsPerPass = new Int32Array(PASSES);
+      const total = h * PASSES;
+      let rowsDone = 0, finished = 0, dirty = false, raf = 0;
+      const t0 = performance.now();
+
+      const flush = () => {
+        raf = 0;
+        if (gen !== generation) return;
+        if (dirty) ctx.putImageData(image, 0, 0);
+        dirty = false;
+      };
+
+      const update = () => {
+        let passesComplete = 0;
+        while (passesComplete < PASSES && rowsPerPass[passesComplete] === h) passesComplete++;
+        bar.style.width = `${(100 * rowsDone) / total}%`;
+        const secs = ((performance.now() - t0) / 1000).toFixed(1);
+        status.textContent = finished === count
+          ? `Done: ${w}×${h}, ${PASSES * SPP_PER_PASS} samples/pixel in ${secs}s on ${count} worker${count > 1 ? 's' : ''}.`
+          : `Rendering… ${passesComplete * SPP_PER_PASS} of ${PASSES * SPP_PER_PASS} samples/pixel (${secs}s)`;
+      };
+
+      status.textContent = 'Rendering…';
+      bar.style.width = '0%';
+
+      for (let index = 0; index < count; index++) {
+        const wk = new Worker(workerUrl);
+        wk.onmessage = (e) => {
+          if (gen !== generation) return;
+          const msg = e.data;
+          if (msg.type === 'row') {
+            image.data.set(msg.pixels, (h - msg.y - 1) * w * 4);
+            rowsPerPass[msg.pass]++;
+            rowsDone++;
+            dirty = true;
+            if (!raf) raf = requestAnimationFrame(() => { flush(); if (gen === generation) update(); });
+          } else if (msg.type === 'done') {
+            finished++;
+            if (finished === count) {
+              flush();
+              update();
+              stop();
+            }
+          }
+        };
+        wk.onerror = (err) => {
+          if (gen !== generation) return;
+          status.textContent = `Renderer failed: ${err.message || 'could not load WebAssembly'}`;
+          stop();
+        };
+        wk.postMessage({ w, h, colors, passes: PASSES, spp: SPP_PER_PASS, index, count });
+        workers.push(wk);
+      }
+    }
+
+    button.addEventListener('click', () => render(randomColors()));
+    document.addEventListener('astro:before-swap', stop, { once: true });
+    render(ORIGINAL);
+  }
+
+  // Works on first load and after Astro client-side (view transition) navigations.
+  document.addEventListener('astro:page-load', init);
+</script>
