+#!/bin/sh
+# Compiles smallpt.cpp to WebAssembly. Requires Emscripten (emcc) on PATH.
+# Output goes to public/wasm/ and is committed, so the site build doesn't need emcc.
+set -e
+cd "$(dirname "$0")"
+emcc smallpt.cpp -O3 -fno-exceptions -Wno-dangling-else \
+  -sMODULARIZE=1 -sEXPORT_NAME=createSmallpt \
+  -sENVIRONMENT=worker -sFILESYSTEM=0 -sALLOW_MEMORY_GROWTH=1 -sSTACK_SIZE=8MB \
+  -sEXPORTED_FUNCTIONS=_num_spheres,_set_sphere_color,_get_sphere_color,_render_begin,_render_row,_malloc,_free \
+  -sEXPORTED_RUNTIME_METHODS=HEAPU8 \
+  -o ../public/wasm/smallpt.js
