+#include <emscripten/emscripten.h>
+
+static const int NUM_SPHERES = sizeof(spheres)/sizeof(Sphere);
+static int g_w = 0, g_h = 0;
+static unsigned char *g_rgba = 0; // displayable image (RGBA, gamma corrected)
+static Vec *g_accum = 0;          // running sum of per-pass pixel radiance
+static int *g_passes = 0;         // passes accumulated per row
+static Ray g_cam(Vec(50,52,295.6), Vec(0,-0.042612,-1).norm());
+static Vec g_cx, g_cy;
+
+extern "C" {
+
+EMSCRIPTEN_KEEPALIVE int num_spheres(){ return NUM_SPHERES; }
+
+EMSCRIPTEN_KEEPALIVE void set_sphere_color(int i, double r, double g, double b){
+  if (i >= 0 && i < NUM_SPHERES) spheres[i].c = Vec(r, g, b);
+}
+
+EMSCRIPTEN_KEEPALIVE double get_sphere_color(int i, int ch){
+  if (i < 0 || i >= NUM_SPHERES) return 0;
+  const Vec &c = spheres[i].c;
+  return ch == 0 ? c.x : ch == 1 ? c.y : c.z;
+}
+
+// Allocates buffers, clears the accumulation and sets up the camera (same
+// camera as the original). Returns a pointer to the w*h*4 RGBA buffer.
+EMSCRIPTEN_KEEPALIVE unsigned char *render_begin(int w, int h){
+  g_w = w; g_h = h;
+  free(g_rgba); free(g_accum); free(g_passes);
+  g_rgba = (unsigned char *)calloc((size_t)w*h*4, 1);
+  g_accum = (Vec *)calloc((size_t)w*h, sizeof(Vec));
+  g_passes = (int *)calloc((size_t)h, sizeof(int));
+  g_cam = Ray(Vec(50,52,295.6), Vec(0,-0.042612,-1).norm());
+  g_cx = Vec(w*.5135/h);
+  g_cy = (g_cx%g_cam.d).norm()*.5135;
+  return g_rgba;
+}
+
+// Traces one more pass of `spp` samples per pixel (rounded down to a multiple
+// of 4: 2x2 subpixels, as in the original) for image row y (0 = bottom), adds
+// it to the accumulation and refreshes that row of the RGBA buffer.
+EMSCRIPTEN_KEEPALIVE void render_row(int y, int pass, int spp){
+  if (!g_rgba || y < 0 || y >= g_h) return;
+  const int w = g_w, h = g_h, samps = spp/4 < 1 ? 1 : spp/4;
+  const int n = ++g_passes[y];
+  Vec r;
+  for (unsigned short x=0, Xi[3]={(unsigned short)(pass*40503u),
+       (unsigned short)(pass*2654435761u>>16), (unsigned short)(y*y*y)}; x<w; x++){
+    Vec c;
+    for (int sy=0; sy<2; sy++)
+      for (int sx=0; sx<2; sx++, r=Vec()){
+        for (int s=0; s<samps; s++){
+          double r1=2*erand48(Xi), dx=r1<1 ? sqrt(r1)-1: 1-sqrt(2-r1);
+          double r2=2*erand48(Xi), dy=r2<1 ? sqrt(r2)-1: 1-sqrt(2-r2);
+          Vec d = g_cx*( ( (sx+.5 + dx)/2 + x)/w - .5) +
+                  g_cy*( ( (sy+.5 + dy)/2 + y)/h - .5) + g_cam.d;
+          r = r + radiance(Ray(g_cam.o+d*140,d.norm()),0,Xi)*(1./samps);
+        }
+        c = c + Vec(clamp(r.x),clamp(r.y),clamp(r.z))*.25;
+      }
+    const size_t i = (size_t)(h-y-1)*w + x;
+    g_accum[i] = g_accum[i] + c;
+    Vec a = g_accum[i]*(1./n);
+    unsigned char *px = g_rgba + i*4;
+    px[0] = toInt(a.x); px[1] = toInt(a.y); px[2] = toInt(a.z); px[3] = 255;
+  }
+}
