+
+      const commandRegistry = {
+        '--spin': toggle('is-spun'),
+        '--grow': toggle('is-grown'),
+        '--round': toggle('is-rounded'),
+        '--reset': (el) => {
+          el.classList.remove('is-spun', 'is-grown', 'is-rounded');
+          document.querySelectorAll(`button[commandfor="${el.id}"][aria-pressed]`)
+            .forEach((btn) => btn.setAttribute('aria-pressed', 'false'));
+        },
+      };
+
+      // Fallback for browsers without the Invoker Commands API
+      if (!('commandForElement' in HTMLButtonElement.prototype)) {
+        document.addEventListener('click', (event) => {
+          if (event.defaultPrevented) return;
+          const button = event.target.closest?.('button[commandfor]');
+          if (!button) return;
+          const el = document.getElementById(button.getAttribute('commandfor'));
+          const command = button.getAttribute('command');
+          if (el && command) {
+            const evt = new Event('command');
+            evt.command = command;
+            evt.source = button;
+            el.dispatchEvent(evt);
+          }
+        });
+      }
+
+      // The command event does not bubble, so listen on the target itself
+      target.addEventListener('command', (event) => {
+        commandRegistry[event.command]?.(event.target, event.source);
+      });
+    })();
