+    (() => {
+      const scroller = document.getElementById('scroller');
+      const status = document.getElementById('status');
+      const beans = [...scroller.querySelectorAll('.bean')];
+      let scrolling = false;
+      let activeBean = null;
+
+      // Find the bean whose leading edge is closest to the scroller's snap position.
+      // Only runs once scrolling has settled, so layout reads never happen mid-scroll.
+      function findVisibleBean() {
+        const { left } = scroller.getBoundingClientRect();
+        const snapLine = left + scroller.clientLeft + parseFloat(getComputedStyle(scroller).scrollPaddingInlineStart || 0);
+        let best = beans[0];
+        let bestDist = Infinity;
+        for (const bean of beans) {
+          const dist = Math.abs(bean.getBoundingClientRect().left - snapLine);
+          if (dist < bestDist) {
+            bestDist = dist;
+            best = bean;
+          }
+        }
+        return best;
+      }
+
+      function setActive(bean) {
+        if (activeBean && activeBean !== bean) activeBean.classList.remove('is-active');
+        activeBean = bean;
+        bean.classList.add('is-active');
+        status.dataset.state = 'idle';
+        status.textContent = `Viewing: ${bean.dataset.name}`;
+      }
+
+      // Cheap, write-once update while moving: no layout reads, and only touch the DOM
