+// Daily Grind — signed receipts & gift vouchers.
+//
+// Uses the Web Cryptography API (crypto.subtle) to sign and verify documents
+// with either a post-quantum (ML-DSA, FIPS 204) or classical (Ed25519 /
+// ECDSA P-256) asymmetric key pair. The private key is generated as
+// non-extractable and persisted in IndexedDB, so it never leaves the browser.
+//
+// Token format: "DGS1." + base64url(JSON envelope)
+//   {
+//     format: "daily-grind-signed/v1",
+//     type: "receipt" | "voucher",
+//     alg: "ML-DSA-65" | ... | "Ed25519" | "ECDSA-P256",
+//     publicKey: base64url(public key bytes),
+//     payload: base64url(UTF-8 JSON document bytes),   // exact bytes signed
+//     signature: base64url(signature bytes)
+//   }
+//
+// Signatures are bound to the document type through a domain-separation
+// context ("daily-grind/receipt/v1" or "daily-grind/voucher/v1") so a receipt
+// signature can never be replayed as a voucher, or vice versa.
+
+const FORMAT = 'daily-grind-signed/v1';
+const TOKEN_PREFIX = 'DGS1.';
+const CONTEXTS = {
+  receipt: 'daily-grind/receipt/v1',
+  voucher: 'daily-grind/voucher/v1',
+};
+
+/**
+ * Supported signature suites. `pq` suites take a native `context`; classical
+ * suites get a length-prefixed context header prepended to the payload.
+ */
+const SUITES = {
+  'ML-DSA-65': { label: 'ML-DSA-65 (post-quantum, recommended)', pq: true, keyFormat: 'raw-public', keyLength: 1952, gen: 'ML-DSA-65' },
+  'ML-DSA-44': { label: 'ML-DSA-44 (post-quantum, compact)', pq: true, keyFormat: 'raw-public', keyLength: 1312, gen: 'ML-DSA-44' },
+  'ML-DSA-87': { label: 'ML-DSA-87 (post-quantum, CNSA 2.0)', pq: true, keyFormat: 'raw-public', keyLength: 2592, gen: 'ML-DSA-87' },
+  Ed25519: { label: 'Ed25519 (classical)', pq: false, keyFormat: 'raw', keyLength: 32, gen: 'Ed25519', sign: 'Ed25519' },
+  'ECDSA-P256': {
+    label: 'ECDSA P-256 / SHA-256 (classical, legacy)',
+    pq: false,
+    keyFormat: 'raw',
+    keyLength: 65,
+    gen: { name: 'ECDSA', namedCurve: 'P-256' },
+    sign: { name: 'ECDSA', hash: 'SHA-256' },
+  },
+};
+const PREFERENCE = ['ML-DSA-65', 'Ed25519', 'ECDSA-P256'];
+
+const enc = new TextEncoder();
+const dec = new TextDecoder('utf-8', { fatal: true });
+
+/* ------------------------------------------------------------------ */
+/* base64url helpers (native Uint8Array.toBase64 with btoa fallback)   */
+/* ------------------------------------------------------------------ */
+
+function toB64url(bytes) {
+  if (typeof bytes.toBase64 === 'function') {
+    return bytes.toBase64({ alphabet: 'base64url', omitPadding: true });
+  }
+  let bin = '';
+  for (let i = 0; i < bytes.length; i += 0x8000) {
+    bin += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
+  }
+  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+function fromB64url(str) {
+  if (typeof str !== 'string' || !/^[A-Za-z0-9_-]*$/.test(str)) {
+    throw new Error('Malformed base64url data');
+  }
+  if (typeof Uint8Array.fromBase64 === 'function') {
+    return Uint8Array.fromBase64(str, { alphabet: 'base64url' });
+  }
+  const b64 = str.replace(/-/g, '+').replace(/_/g, '/').padEnd(Math.ceil(str.length / 4) * 4, '=');
+  const bin = atob(b64);
+  const out = new Uint8Array(bin.length);
+  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
+  return out;
+}
+
+/* ------------------------------------------------------------------ */
+/* Feature detection                                                   */
+/* ------------------------------------------------------------------ */
+
+/** Returns true / false when the browser can tell us, or null when unknown. */
+function suiteSupport(id) {
+  const suite = SUITES[id];
+  // SubtleCrypto.supports() is a *static* method on the constructor.
+  if (typeof globalThis.SubtleCrypto?.supports === 'function') {
+    try {
+      return SubtleCrypto.supports('generateKey', suite.gen) && SubtleCrypto.supports('sign', suite.pq ? id : suite.sign);
+    } catch {
+      return false;
+    }
+  }
+  // Without supports(), ML-DSA is certainly unavailable; classical suites must be probed.
+  return suite.pq ? false : null;
+}
+
+async function probeSuite(id) {
+  const known = suiteSupport(id);
+  if (known !== null) return known;
+  try {
+    await crypto.subtle.generateKey(SUITES[id].gen, false, ['sign', 'verify']);
+    return true;
+  } catch {
+    return false;
+  }
+}
+
+async function bestSuite() {
+  for (const id of PREFERENCE) {
+    if (await probeSuite(id)) return id;
+  }
+  throw new Error('This browser does not support any digital signature algorithm.');
+}
+
+/* ------------------------------------------------------------------ */
+/* Core sign / verify                                                  */
+/* ------------------------------------------------------------------ */
+
+function frameWithContext(payloadBytes, contextBytes) {
+  if (contextBytes.byteLength > 255) {
+    throw new DOMException('Context must not exceed 255 bytes', 'OperationError');
+  }
+  const framed = new Uint8Array(1 + contextBytes.byteLength + payloadBytes.byteLength);
+  framed[0] = contextBytes.byteLength;
+  framed.set(contextBytes, 1);
+  framed.set(payloadBytes, 1 + contextBytes.byteLength);
+  return framed;
+}
+
+async function signBytes(suiteId, privateKey, payloadBytes, contextBytes) {
+  const suite = SUITES[suiteId];
+  const sig = suite.pq
+    ? await crypto.subtle.sign({ name: suiteId, context: contextBytes }, privateKey, payloadBytes)
+    : await crypto.subtle.sign(suite.sign, privateKey, frameWithContext(payloadBytes, contextBytes));
+  return new Uint8Array(sig);
+}
+
+async function importPublicKey(suiteId, publicKeyBytes) {
+  const suite = SUITES[suiteId];
+  if (publicKeyBytes.byteLength !== suite.keyLength) {
+    throw new Error(`Public key length does not match ${suiteId}`);
+  }
+  return crypto.subtle.importKey(suite.keyFormat, publicKeyBytes, suite.gen, true, ['verify']);
+}
+
+async function verifyBytes(suiteId, publicKey, signatureBytes, payloadBytes, contextBytes) {
+  const suite = SUITES[suiteId];
+  return suite.pq
+    ? crypto.subtle.verify({ name: suiteId, context: contextBytes }, publicKey, signatureBytes, payloadBytes)
+    : crypto.subtle.verify(suite.sign, publicKey, signatureBytes, frameWithContext(payloadBytes, contextBytes));
+}
+
+async function fingerprint(publicKeyBytes) {
+  const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', publicKeyBytes));
+  return Array.from(digest.subarray(0, 16), (b) => b.toString(16).padStart(2, '0'))
+    .join('')
+    .toUpperCase()
+    .match(/.{4}/g)
+    .join(' ');
+}
+
+/* ------------------------------------------------------------------ */
+/* Key storage (IndexedDB keeps the non-extractable CryptoKey)         */
+/* ------------------------------------------------------------------ */
+
+const DB_NAME = 'daily-grind-signing';
+
+function openDb() {
+  return new Promise((resolve, reject) => {
+    const req = indexedDB.open(DB_NAME, 1);
+    req.onupgradeneeded = () => {
+      req.result.createObjectStore('keys');
+      req.result.createObjectStore('trusted', { keyPath: 'fingerprint' });
+    };
+    req.onsuccess = () => resolve(req.result);
+    req.onerror = () => reject(req.error);
+  });
+}
+
+async function dbOp(store, mode, fn) {
+  const db = await openDb();
+  try {
+    return await new Promise((resolve, reject) => {
+      const tx = db.transaction(store, mode);
+      const req = fn(tx.objectStore(store));
+      tx.oncomplete = () => resolve(req?.result);
+      tx.onerror = () => reject(tx.error);
+      tx.onabort = () => reject(tx.error);
+    });
+  } finally {
+    db.close();
+  }
+}
+
+async function loadActiveKey() {
+  try {
+    return (await dbOp('keys', 'readonly', (s) => s.get('active'))) ?? null;
+  } catch {
+    return null;
+  }
+}
+
+async function createKey(suiteId) {
+  const suite = SUITES[suiteId];
+  const keyPair = await crypto.subtle.generateKey(suite.gen, false, ['sign', 'verify']);
+  const publicKeyBytes = new Uint8Array(await crypto.subtle.exportKey(suite.keyFormat, keyPair.publicKey));
+  const record = {
+    suite: suiteId,
+    privateKey: keyPair.privateKey,
+    publicKey: keyPair.publicKey,
+    publicKeyBytes,
+    fingerprint: await fingerprint(publicKeyBytes),
+    createdAt: new Date().toISOString(),
+  };
+  try {
+    await dbOp('keys', 'readwrite', (s) => s.put(record, 'active'));
+    // Keep retired public keys trusted so previously issued documents still verify as ours.
+    await dbOp('trusted', 'readwrite', (s) =>
+      s.put({ fingerprint: record.fingerprint, suite: suiteId, createdAt: record.createdAt }),
+    );
+  } catch {
+    // Private browsing / storage disabled: key works for this session only.
+  }
+  return record;
+}
+
+async function isTrusted(fp) {
+  try {
+    return Boolean(await dbOp('trusted', 'readonly', (s) => s.get(fp)));
+  } catch {
+    return activeKey?.fingerprint === fp;
+  }
+}
+
+/* ------------------------------------------------------------------ */
+/* Token encode / decode                                               */
+/* ------------------------------------------------------------------ */
+
+async function issue(type, document, key = activeKey) {
+  if (!key) throw new Error('No signing key available.');
+  const payloadBytes = enc.encode(JSON.stringify({ type, ...document }));
+  const signature = await signBytes(key.suite, key.privateKey, payloadBytes, enc.encode(CONTEXTS[type]));
+  const envelope = {
+    format: FORMAT,
+    type,
+    alg: key.suite,
+    publicKey: toB64url(key.publicKeyBytes),
+    payload: toB64url(payloadBytes),
+    signature: toB64url(signature),
+  };
+  return { envelope, token: encodeEnvelope(envelope) };
+}
+
+function parseToken(input) {
+  const text = input.trim();
+  if (!text) throw new Error('Paste a signed token first.');
+  let envelope;
+  try {
+    envelope = text.startsWith('{')
+      ? JSON.parse(text)
+      : text.startsWith(TOKEN_PREFIX)
+        ? JSON.parse(dec.decode(fromB64url(text.slice(TOKEN_PREFIX.length))))
+        : null;
+  } catch {
+    throw new Error('This token is corrupted and cannot be read.');
+  }
+  if (!envelope || envelope.format !== FORMAT) throw new Error('Not a Daily Grind signed document.');
+  if (!Object.hasOwn(CONTEXTS, envelope.type)) throw new Error('Unknown document type.');
+  if (!Object.hasOwn(SUITES, envelope.alg)) throw new Error(`Unsupported signature algorithm "${envelope.alg}".`);
+  return envelope;
+}
+
+function encodeEnvelope(envelope) {
+  return TOKEN_PREFIX + toB64url(enc.encode(JSON.stringify(envelope)));
+}
+
+/**
+ * Verifies a token. Resolves to
+ *   { valid, trusted, envelope, document, fingerprint, warnings }
+ * or throws for structurally invalid input.
+ */
+async function verifyToken(input) {
+  const envelope = parseToken(input);
+  const publicKeyBytes = fromB64url(envelope.publicKey);
+  const payloadBytes = fromB64url(envelope.payload);
+  const signatureBytes = fromB64url(envelope.signature);
+
+  if (suiteSupport(envelope.alg) === false) {
+    throw new Error(`This browser cannot verify ${envelope.alg} signatures. Try an up-to-date browser.`);
+  }
+
+  let publicKey;
+  try {
+    publicKey = await importPublicKey(envelope.alg, publicKeyBytes);
+  } catch (err) {
+    throw new Error(`Invalid public key: ${err.message}`);
+  }
+
+  let valid = false;
+  try {
+    valid = await verifyBytes(envelope.alg, publicKey, signatureBytes, payloadBytes, enc.encode(CONTEXTS[envelope.type]));
+  } catch {
+    valid = false;
+  }
+
+  const fp = await fingerprint(publicKeyBytes);
+  const result = { valid, trusted: false, envelope, document: null, fingerprint: fp, warnings: [] };
+  if (!valid) return result;
+
+  // Only parse the document once its bytes are known to be authentic.
+  result.document = JSON.parse(dec.decode(payloadBytes));
+  if (result.document.type !== envelope.type) {
+    result.valid = false;
+    return result;
+  }
+  result.trusted = await isTrusted(fp);
+  if (envelope.type === 'voucher' && result.document.expires) {
+    if (new Date(result.document.expires + 'T23:59:59') < new Date()) {
+      result.warnings.push(`This voucher expired on ${result.document.expires}.`);
+    }
+  }
+  return result;
+}
+
+/* ------------------------------------------------------------------ */
+/* UI                                                                  */
+/* ------------------------------------------------------------------ */
+
+const MENU = {
+  'maple-oat-latte': { name: 'Maple Oat Latte', cents: 550 },
+  'dark-roast-espresso': { name: 'Dark Roast Espresso', cents: 375 },
+  'cold-brew': { name: 'Cold Brew', cents: 495 },
+};
+const money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });
+const fmtCents = (c) => money.format(c / 100);
+
+let activeKey = null;
+const $ = (sel) => document.querySelector(sel);
+
+function randomId(prefix, groups = 3) {
+  const alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
+  const bytes = crypto.getRandomValues(new Uint8Array(groups * 4));
+  const chars = Array.from(bytes, (b) => alphabet[b % alphabet.length]).join('');
+  return `${prefix}-${chars.match(/.{4}/g).join('-')}`;
+}
+
+function el(tag, props = {}, ...children) {
+  const node = Object.assign(document.createElement(tag), props);
+  node.append(...children.filter((c) => c != null));
+  return node;
+}
+
+function renderKeyStatus() {
+  const status = $('#sig-key-status');
+  if (!activeKey) {
+    status.textContent = 'No signing key yet.';
+    return;
+  }
+  const suite = SUITES[activeKey.suite];
+  status.replaceChildren(
+    el('strong', {}, suite.pq ? 'Quantum-resistant key active' : 'Classical key active'),
+    el('br'),
+    `${activeKey.suite} · created ${new Date(activeKey.createdAt).toLocaleString()}`,
+    el('br'),
+    'Fingerprint: ',
+    el('code', {}, activeKey.fingerprint),
+  );
