+
+function populateSuiteSelect() {
+  const select = $('#sig-suite');
+  for (const [id, suite] of Object.entries(SUITES)) {
+    const supported = suiteSupport(id);
+    const option = el('option', { value: id, textContent: suite.label + (supported === false ? ' — not supported here' : '') });
+    option.disabled = supported === false;
+    select.append(option);
+  }
+}
+
+function renderDocument(type, doc) {
+  const rows =
+    type === 'receipt'
+      ? [
+          ['Order', doc.orderId],
+          ['Customer', doc.customer || '—'],
+          ['Issued', new Date(doc.issuedAt).toLocaleString()],
+          ...doc.items.map((i) => [`${i.qty} × ${i.name}`, fmtCents(i.qty * i.unitCents)]),
+          ['Total', fmtCents(doc.totalCents)],
+        ]
+      : [
+          ['Voucher code', doc.code],
+          ['Value', fmtCents(doc.amountCents)],
+          ['To', doc.recipient],
+          ['From', doc.sender || '—'],
+          ['Message', doc.message || '—'],
+          ['Expires', doc.expires],
+          ['Issued', new Date(doc.issuedAt).toLocaleString()],
+        ];
+  return el('dl', { className: 'sig-doc' }, ...rows.flatMap(([k, v]) => [el('dt', {}, k), el('dd', {}, String(v))]));
+}
+
+let lastIssued = null;
+
+function showIssued(type, doc, token, envelope) {
+  lastIssued = { type, doc, token, envelope };
+  const out = $('#sig-issued');
+  out.hidden = false;
+  $('#sig-issued-title').textContent = type === 'receipt' ? 'Signed order receipt' : 'Signed gift voucher';
+  $('#sig-issued-meta').textContent = `Signed with ${envelope.alg} · key ${activeKey.fingerprint}`;
+  $('#sig-issued-doc').replaceChildren(renderDocument(type, doc));
+  $('#sig-token').value = token;
+  $('#sig-issued').scrollIntoView({ behavior: 'smooth', block: 'nearest' });
+}
+
+function updateReceiptTotal() {
+  const form = $('#receipt-form');
+  let total = 0;
+  for (const [id, item] of Object.entries(MENU)) total += (Number(form.elements[id].value) || 0) * item.cents;
+  $('#receipt-total').textContent = fmtCents(total);
+  return total;
+}
+
+async function withBusy(button, fn) {
+  button.setAttribute('aria-busy', 'true');
+  button.disabled = true;
+  try {
+    return await fn();
+  } finally {
+    button.disabled = false;
+    button.removeAttribute('aria-busy');
+  }
+}
+
+function setStatus(node, kind, ...content) {
+  node.dataset.kind = kind;
+  node.replaceChildren(...content);
+}
+
+async function onReceiptSubmit(event) {
+  event.preventDefault();
+  const form = event.currentTarget;
+  const items = Object.entries(MENU)
+    .map(([id, item]) => ({ sku: id, name: item.name, unitCents: item.cents, qty: Number(form.elements[id].value) || 0 }))
+    .filter((i) => i.qty > 0);
