+  await withBusy(event.submitter ?? form.querySelector('button[type=submit]'), async () => {
+    try {
+      const { token, envelope } = await issue('receipt', doc);
+      setStatus(status, 'ok', `Receipt ${doc.orderId} signed.`);
+      showIssued('receipt', { type: 'receipt', ...doc }, token, envelope);
