+async function onVoucherSubmit(event) {
+  event.preventDefault();
+  const form = event.currentTarget;
+  const status = $('#voucher-status');
+  if (!form.reportValidity()) return;
+  const doc = {
+    code: randomId('GIFT', 4),
+    amountCents: Math.round(Number(form.elements.amount.value) * 100),
+    currency: 'USD',
+    recipient: form.elements.recipient.value.trim(),
+    sender: form.elements.sender.value.trim(),
+    message: form.elements.message.value.trim(),
+    expires: form.elements.expires.value,
+    issuedAt: new Date().toISOString(),
+  };
+  await withBusy(event.submitter ?? form.querySelector('button[type=submit]'), async () => {
+    try {
+      const { token, envelope } = await issue('voucher', doc);
+      setStatus(status, 'ok', `Voucher ${doc.code} signed.`);
+      showIssued('voucher', { type: 'voucher', ...doc }, token, envelope);
+    } catch (err) {
+      setStatus(status, 'error', `Signing failed: ${err.message}`);
+    }
+  });
