+
+async function onVerifySubmit(event) {
+  event.preventDefault();
+  const status = $('#verify-status');
+  const input = $('#verify-input').value;
+  await withBusy(event.submitter ?? event.currentTarget.querySelector('button[type=submit]'), async () => {
+    try {
+      const r = await verifyToken(input);
+      if (!r.valid) {
+        setStatus(
+          status,
+          'error',
+          el('strong', {}, '✗ Signature INVALID'),
+          el('p', {}, 'This document has been altered or was not signed by the key it claims. Do not accept it.'),
+        );
