+// The Daily Grind — browser keystore (IndexedDB).
+//
+// Stores:
+//   issuerKeys  – this browser's signing keys. Classical private keys are
+//                 non-extractable WebCrypto CryptoKeys (structured-cloned into
+//                 IndexedDB, so their raw bytes can never be read out).
+//                 ML-DSA secret keys are raw bytes, so they are encrypted at
+//                 rest with a non-extractable AES-GCM "vault" key.
+//   trustedKeys – public keys of other issuers (e.g. a store's register) that
+//                 this browser accepts as authentic.
+//   meta        – the vault key.
+
+import { generateKeyPair, computeKid } from './dg-sign.js';
+
+const DB_NAME = 'daily-grind-signing';
+const DB_VERSION = 1;
+const ACTIVE_KEY = 'dg.activeIssuerKid';
+
+let dbPromise = null;
+
+function openDb() {
+  if (!dbPromise) {
+    dbPromise = new Promise((resolve, reject) => {
+      const req = indexedDB.open(DB_NAME, DB_VERSION);
+      req.onupgradeneeded = () => {
+        const db = req.result;
+        if (!db.objectStoreNames.contains('issuerKeys')) db.createObjectStore('issuerKeys', { keyPath: 'kid' });
+        if (!db.objectStoreNames.contains('trustedKeys')) db.createObjectStore('trustedKeys', { keyPath: 'kid' });
+        if (!db.objectStoreNames.contains('meta')) db.createObjectStore('meta');
+      };
+      req.onsuccess = () => resolve(req.result);
+      req.onerror = () => { dbPromise = null; reject(req.error); };
+    });
+  }
+  return dbPromise;
+}
+
+async function tx(store, mode, fn) {
+  const db = await openDb();
+  return new Promise((resolve, reject) => {
+    const t = db.transaction(store, mode);
+    const req = fn(t.objectStore(store));
+    t.oncomplete = () => resolve(req ? req.result : undefined);
+    t.onerror = () => reject(t.error);
+    t.onabort = () => reject(t.error || new Error('IndexedDB transaction aborted'));
+  });
+}
+
+const getAll = (store) => tx(store, 'readonly', (s) => s.getAll());
+const getOne = (store, key) => tx(store, 'readonly', (s) => s.get(key));
+const put = (store, value, key) => tx(store, 'readwrite', (s) => s.put(value, key));
+const del = (store, key) => tx(store, 'readwrite', (s) => s.delete(key));
+
+// --- vault key for raw (ML-DSA) secret keys --------------------------------
+
+let vaultPromise = null;
+function vaultKey() {
+  if (!vaultPromise) {
+    vaultPromise = (async () => {
+      let key = await getOne('meta', 'vault');
+      if (!key) {
+        key = await crypto.subtle.generateKey({ name: 'AES-GCM', length: 256 }, false, ['encrypt', 'decrypt']);
+        await put('meta', key, 'vault');
+      }
+      return key;
+    })().catch((err) => { vaultPromise = null; throw err; });
+  }
+  return vaultPromise;
+}
+
+async function sealPrivateKey(priv, aad) {
+  if (!(priv instanceof Uint8Array)) return { kind: 'cryptokey', key: priv };
+  const iv = crypto.getRandomValues(new Uint8Array(12));
+  const ct = await crypto.subtle.encrypt({ name: 'AES-GCM', iv, additionalData: aad }, await vaultKey(), priv);
+  return { kind: 'sealed', iv, ct: new Uint8Array(ct) };
+}
+
+async function openPrivateKey(sealed, aad) {
+  if (sealed.kind === 'cryptokey') return sealed.key;
+  const pt = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: sealed.iv, additionalData: aad }, await vaultKey(), sealed.ct);
+  return new Uint8Array(pt);
+}
+
+const aadFor = (kid, i) => new TextEncoder().encode(`dg-issuer-key:${kid}:${i}`);
+
+// --- issuer keys -----------------------------------------------------------
+
+export async function listIssuerKeys() {
+  const keys = await getAll('issuerKeys');
+  return keys
+    .map(({ kid, alg, label, createdAt, publicKeys }) => ({ kid, alg, label, createdAt, publicKeys }))
+    .sort((a, b) => a.createdAt.localeCompare(b.createdAt));
+}
+
+export async function createIssuerKey(alg, label) {
+  const kp = await generateKeyPair(alg);
+  const sealed = [];
+  for (let i = 0; i < kp.privateKeys.length; i++) sealed.push(await sealPrivateKey(kp.privateKeys[i], aadFor(kp.kid, i)));
+  const record = {
+    kid: kp.kid,
+    alg,
+    label: String(label || '').trim().slice(0, 80) || `${alg} key`,
+    createdAt: new Date().toISOString(),
+    publicKeys: kp.publicKeys,
+    privateKeys: sealed,
+  };
+  await put('issuerKeys', record);
+  if (!getActiveKid()) setActiveKid(kp.kid);
+  return { kid: record.kid, alg, label: record.label, createdAt: record.createdAt, publicKeys: record.publicKeys };
+}
+
+/** Load a key with usable private keys, for signing only. */
+export async function loadSigningKey(kid) {
+  const rec = await getOne('issuerKeys', kid);
+  if (!rec) throw new Error('Signing key not found. Create an issuer key first.');
+  // Defend against a modified database record: the kid must match the stored public keys.
+  if ((await computeKid(rec.alg, rec.publicKeys)) !== rec.kid) throw new Error('Stored key record is corrupted');
+  const privateKeys = [];
+  for (let i = 0; i < rec.privateKeys.length; i++) privateKeys.push(await openPrivateKey(rec.privateKeys[i], aadFor(kid, i)));
+  return { kid: rec.kid, alg: rec.alg, publicKeys: rec.publicKeys, privateKeys };
+}
+
+export async function deleteIssuerKey(kid) {
+  await del('issuerKeys', kid);
+  if (getActiveKid() === kid) {
+    const rest = await listIssuerKeys();
+    setActiveKid(rest.length ? rest[rest.length - 1].kid : null);
+  }
+}
+
+export function getActiveKid() {
+  try { return localStorage.getItem(ACTIVE_KEY); } catch { return null; }
+}
+
+export function setActiveKid(kid) {
+  try {
+    if (kid) localStorage.setItem(ACTIVE_KEY, kid);
+    else localStorage.removeItem(ACTIVE_KEY);
+  } catch { /* storage disabled; active key falls back to most recent */ }
+}
+
+// --- trusted (third-party) public keys -------------------------------------
+
+export async function listTrustedKeys() {
+  const keys = await getAll('trustedKeys');
+  return keys.sort((a, b) => a.addedAt.localeCompare(b.addedAt));
+}
+
+export async function addTrustedKey({ kid, alg, publicKeys, label }) {
+  const rec = { kid, alg, publicKeys, label: label || `${alg} issuer`, addedAt: new Date().toISOString() };
+  await put('trustedKeys', rec);
+  return rec;
+}
+
+export const removeTrustedKey = (kid) => del('trustedKeys', kid);
+
+/** Every key id this browser accepts as an authentic issuer: its own keys plus imported ones. */
+export async function trustedKidMap() {
+  const map = new Map();
+  for (const k of await listIssuerKeys()) map.set(k.kid, { label: k.label, source: 'This device' });
+  for (const k of await listTrustedKeys()) if (!map.has(k.kid)) map.set(k.kid, { label: k.label, source: 'Imported' });
+  return map;
+}
