+  return node;
+}
+
+function randomCode(groups, len) {
+  const alphabet = '23456789ABCDEFGHJKMNPQRSTVWXYZ'; // no 0/O/1/I/L/U confusion
+  const out = [];
+  for (let g = 0; g < groups; g++) {
+    const bytes = crypto.getRandomValues(new Uint8Array(len * 2));
+    let s = '';
+    for (const b of bytes) {
+      if (b < 240) s += alphabet[b % 30]; // rejection sampling for uniformity
+      if (s.length === len) break;
+    }
+    out.push(s.padEnd(len, '2'));
+  }
+  return out.join('-');
