+      el('div', { class: 'doc-head' }, el('strong', { text: 'THE DAILY GRIND' }), el('span', { text: String(p.store ?? '') })),
+      el('div', { class: 'doc-meta' }, `Order ${String(p.orderId ?? '')}`, el('br'), issuedStr),
+      el('table', { class: 'doc-items' },
