+
+// ---------------------------------------------------------------------------
+// Create & sign panel
+// ---------------------------------------------------------------------------
+
+function receiptPayload() {
+  const items = MENU
+    .map((m) => ({ name: m.name, qty: Math.max(0, Math.min(99, parseInt($(`#qty-${m.id}`).value, 10) || 0)), unitCents: m.unitCents }))
