+
+// ---------------------------------------------------------------------------
+// Verify panel
+// ---------------------------------------------------------------------------
+
+function checkList(checks) {
+  return el('ul', { class: 'checks' }, checks.map((c) => el('li', { class: c.ok ? 'ok' : 'fail' },
+    el('span', { class: 'icon', 'aria-hidden': 'true', text: c.ok ? '✔' : '✖' }), ' ', c.label)));
+}
+
+async function runVerify() {
+  const out = $('#verify-result');
+  let env;
+  try {
+    env = decodeToken($('#verify-input').value);
+  } catch (err) {
+    out.replaceChildren(el('div', { class: 'verdict verdict-fail' }, el('strong', { text: 'Cannot verify' }), el('p', { text: err.message })));
+    return;
+  }
+  out.replaceChildren(el('p', { class: 'hint', text: 'Verifying…' }));
+  const trusted = await store.trustedKidMap();
+  const res = await verifyDocument(env, { trustedKids: trusted });
+  const rules = res.signatureValid ? checkPayloadRules(env.typ, env.payload) : [];
+  const rulesOk = rules.every((r) => r.ok);
+  const what = env.typ === 'receipt' ? 'receipt' : 'gift voucher';
+
+  let cls; let title; let detail;
+  if (!res.signatureValid) {
+    cls = 'verdict-fail'; title = `Invalid ${what}`;
+    detail = 'The signature does not match. This document was altered or forged — do not accept it.';
+  } else if (!res.trusted) {
+    cls = 'verdict-warn'; title = 'Intact, but issuer not trusted';
+    detail = 'The contents have not changed since signing, but the key that signed it is not one of your trusted Daily Grind issuer keys. Import the issuer’s public key below if you trust it.';
+  } else if (!rulesOk) {
+    cls = 'verdict-warn'; title = `Authentic ${what}, with problems`;
+    detail = 'Signed by a trusted issuer, but see the failed checks below.';
+  } else {
+    const issuer = trusted.get(res.kid);
+    cls = 'verdict-ok'; title = `Authentic ${what}`;
+    detail = `Signed by “${issuer.label}” (${issuer.source.toLowerCase()}) and unmodified.`;
+  }
