+  out.replaceChildren(
+    el('div', { class: `verdict ${cls}` }, el('strong', { text: title }), el('p', { text: detail })),
+    checkList([...res.checks, ...rules]),
+    // Only show contents when the signature is valid; otherwise they are attacker-controlled.
+    res.signatureValid ? el('div', { class: 'verified-doc' }, renderDocument(env), signatureFooter(env)) : null,
+  );
+}
+
+function tamper() {
+  let env;
+  try { env = decodeToken($('#verify-input').value); } catch { toast('Load a signed document first', 'error'); return; }
+  if (env.typ === 'receipt') {
+    // Make the order look cheaper while keeping the arithmetic consistent.
+    const it = env.payload.items?.[0];
+    if (it) it.unitCents = Math.max(0, it.unitCents - 200);
+    if (Array.isArray(env.payload.items)) {
+      env.payload.subtotalCents = env.payload.items.reduce((s, x) => s + x.qty * x.unitCents, 0);
+      env.payload.totalCents = env.payload.subtotalCents + env.payload.taxCents;
+    }
+  } else {
+    env.payload.amountCents = (env.payload.amountCents || 0) * 10;
+  }
+  $('#verify-input').value = encodeToken(env);
+  toast(env.typ === 'receipt' ? 'Lowered the first item’s price by $2.00' : 'Multiplied the voucher value by 10', 'info');
+  runVerify();
+}
+
+async function refreshTrusted() {
+  const list = $('#trust-list');
+  const keys = await store.listTrustedKeys();
+  list.replaceChildren();
+  if (!keys.length) list.append(el('li', { class: 'empty', text: 'No imported issuer keys. Keys created on this device are trusted automatically.' }));
+  for (const k of keys) {
+    list.append(el('li', {},
+      el('div', { class: 'key-title' }, el('strong', { text: k.label }), ' ', familyBadge(k.alg)),
+      el('div', { class: 'key-meta' }, el('code', { text: formatKid(k.kid) })),
+      el('div', { class: 'key-actions' }, el('button', {
+        type: 'button', class: 'link-btn danger', text: 'Remove',
+        onclick: async () => { await store.removeTrustedKey(k.kid); await refreshTrusted(); },
+      }))));
+  }
+}
+
+function setupVerifyPanel() {
+  $('#verify-btn').addEventListener('click', runVerify);
+  $('#tamper-btn').addEventListener('click', tamper);
+  $('#verify-file').addEventListener('change', async (e) => {
+    const file = e.target.files?.[0];
+    if (!file) return;
+    if (file.size > 128 * 1024) { toast('File is too large to be a signed document', 'error'); return; }
+    $('#verify-input').value = (await file.text()).trim();
+    e.target.value = '';
+    runVerify();
+  });
+  $('#trust-import').addEventListener('click', (e) => busy(e.currentTarget, 'Importing…', async () => {
+    const pk = await decodePublicKey($('#trust-input').value);
+    const label = $('#trust-label').value.trim().slice(0, 80) || pk.label || `${pk.alg} issuer`;
+    await store.addTrustedKey({ ...pk, label });
+    $('#trust-input').value = '';
+    $('#trust-label').value = '';
+    await refreshTrusted();
+    toast(`Trusted "${label}" (${formatKid(pk.kid).slice(0, 9)}…)`, 'success');
+    if ($('#verify-input').value.trim()) runVerify();
+  }));
+}
+
+function loadFromHash() {
+  if (!location.hash.startsWith(VERIFY_HASH)) return;
+  const token = decodeURIComponent(location.hash.slice(VERIFY_HASH.length));
+  if (!token.startsWith(TOKEN_PREFIX)) return;
+  $('#verify-input').value = token;
+  $('#panel-verify').scrollIntoView({ block: 'start' });
+  runVerify();
+}
+
+// ---------------------------------------------------------------------------
+
+async function init() {
+  const warn = $('#dg-env-warning');
+  if (!window.isSecureContext || !crypto?.subtle || !window.indexedDB) {
+    warn.textContent = 'Signing needs a secure context (HTTPS or localhost) with WebCrypto and IndexedDB. Please reopen this page over HTTPS.';
+    warn.hidden = false;
+    document.querySelectorAll('#secure-receipts button, #secure-receipts input, #secure-receipts select, #secure-receipts textarea')
+      .forEach((n) => { n.disabled = true; });
+    return;
+  }
+  support = await detectSupport();
+  if (!support['ML-DSA-65']) {
+    warn.textContent = 'The post-quantum (ML-DSA) module could not be loaded; only classical algorithms are available.';
+    warn.hidden = false;
+  }
+  setupKeyPanel();
+  setupSignPanel();
+  setupVerifyPanel();
+  await Promise.all([refreshKeys(), refreshTrusted()]);
+  loadFromHash();
+  window.addEventListener('hashchange', loadFromHash);
+}
+
+init().catch((err) => {
+  console.error(err);
+  const warn = $('#dg-env-warning');
+  warn.textContent = `Signing is unavailable: ${err.message}`;
+  warn.hidden = false;
+});
