+++ b/js/dg-sign.js
@@ -0,0 +1,436 @@
+// The Daily Grind — signed document core.
+//
+// Signs and verifies coffee order receipts and gift vouchers in the browser,
+// using classical (ECDSA P-256, Ed25519 via WebCrypto) or quantum-resistant
+// (ML-DSA-65, FIPS 204) asymmetric keys, or a hybrid of Ed25519 + ML-DSA-65.
+//
+// No DOM or storage access here, so this module can be unit-tested in Node.
+//
+// Wire formats
+//   Signed document token:  "DGSIG1." + base64url(UTF-8 JSON envelope)
+//   Public key token:       "DGPUB1." + base64url(UTF-8 JSON {v, alg, pub, label})
+//
+// Envelope: { v, typ, alg, kid, iat, payload, pub: [b64url...], sig: [b64url...] }
+// The signature covers DOMAIN_TAG || canonicalJSON(envelope without "sig"),
+// which binds the algorithm, key id and public key(s) to the payload so that
+// none of them can be swapped without invalidating the signature.
+
+const MLDSA_URL = new URL('../vendor/noble-post-quantum-ml-dsa-0.7.1.mjs', import.meta.url).href;
+
+export const TOKEN_PREFIX = 'DGSIG1.';
+export const PUBKEY_PREFIX = 'DGPUB1.';
+export const ENVELOPE_VERSION = 1;
+export const DOCUMENT_TYPES = ['receipt', 'voucher'];
+const DOMAIN_TAG = 'DailyGrind/SignedDocument/v1\u0000';
+const KID_TAG = 'DailyGrind/KeyId/v1\u0000';
+const MAX_TOKEN_CHARS = 64 * 1024;
+
+const enc = new TextEncoder();
+const dec = new TextDecoder('utf-8', { fatal: true });
+
+// ---------------------------------------------------------------------------
+// Encoding helpers
+// ---------------------------------------------------------------------------
+
+export function bytesToB64url(bytes) {
+  let bin = '';
+  for (let i = 0; i < bytes.length; i += 0x8000) {
+    bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
+  }
+  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+export function b64urlToBytes(str) {
+  if (typeof str !== 'string' || !/^[A-Za-z0-9_-]*$/.test(str) || str.length % 4 === 1) {
+    throw new Error('Invalid base64url data');
+  }
+  const b64 = str.replace(/-/g, '+').replace(/_/g, '/') + '==='.slice((str.length + 3) % 4);
+  const bin = atob(b64);
+  const out = new Uint8Array(bin.length);
+  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
+  return out;
+}
+
+function concatBytes(...parts) {
+  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
+  let off = 0;
+  for (const p of parts) { out.set(p, off); off += p.length; }
+  return out;
+}
+
+function u32be(n) {
+  return new Uint8Array([(n >>> 24) & 255, (n >>> 16) & 255, (n >>> 8) & 255, n & 255]);
+}
+
+function toHex(bytes) {
+  return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
+}
+
+/**
+ * Deterministic JSON: object keys sorted by code unit, no whitespace.
+ * Only plain JSON values are allowed; non-finite numbers are rejected.
+ */
+export function canonicalize(value) {
+  if (value === null || typeof value === 'boolean' || typeof value === 'string') {
+    return JSON.stringify(value);
+  }
+  if (typeof value === 'number') {
+    if (!Number.isFinite(value)) throw new Error('Non-finite number in signed data');
+    return JSON.stringify(value);
+  }
+  if (Array.isArray(value)) return '[' + value.map(canonicalize).join(',') + ']';
+  if (typeof value === 'object') {
+    const proto = Object.getPrototypeOf(value);
+    if (proto !== Object.prototype && proto !== null) throw new Error('Unsupported value in signed data');
+    return '{' + Object.keys(value).sort()
+      .filter((k) => value[k] !== undefined)
+      .map((k) => JSON.stringify(k) + ':' + canonicalize(value[k]))
+      .join(',') + '}';
+  }
+  throw new Error(`Unsupported type in signed data: ${typeof value}`);
+}
+
+// ---------------------------------------------------------------------------
+// Algorithm components
+// ---------------------------------------------------------------------------
+
+let mlDsaPromise = null;
+function loadMlDsa() {
+  if (!mlDsaPromise) {
+    mlDsaPromise = import(MLDSA_URL).then((m) => m.ml_dsa65).catch((err) => {
+      mlDsaPromise = null; // allow a retry later
+      throw err;
+    });
+  }
+  return mlDsaPromise;
+}
+
+function subtle() {
+  if (!globalThis.crypto || !globalThis.crypto.subtle) {
+    throw new Error('WebCrypto is unavailable. Open the page over HTTPS (or localhost).');
+  }
+  return globalThis.crypto.subtle;
+}
+
+const ECDSA_PARAMS = { name: 'ECDSA', namedCurve: 'P-256' };
+const ECDSA_SIGN = { name: 'ECDSA', hash: 'SHA-256' };
+
+/**
+ * A component is one primitive signature scheme. Private keys are either
+ * non-extractable WebCrypto CryptoKeys (classical) or raw Uint8Arrays (ML-DSA;
+ * the keystore encrypts those at rest).
+ */
+const COMPONENTS = {
+  'ecdsa-p256': {
+    publicKeyLength: 65,
+    signatureLength: 64,
+    async generate() {
+      const kp = await subtle().generateKey(ECDSA_PARAMS, false, ['sign', 'verify']);
+      const pub = new Uint8Array(await subtle().exportKey('raw', kp.publicKey));
+      return { publicKey: pub, privateKey: kp.privateKey };
+    },
+    async sign(privateKey, data) {
+      return new Uint8Array(await subtle().sign(ECDSA_SIGN, privateKey, data));
+    },
+    async verify(publicKey, signature, data) {
+      const key = await subtle().importKey('raw', publicKey, ECDSA_PARAMS, false, ['verify']);
+      return subtle().verify(ECDSA_SIGN, key, signature, data);
+    },
+  },
+  ed25519: {
+    publicKeyLength: 32,
+    signatureLength: 64,
+    async generate() {
+      const kp = await subtle().generateKey({ name: 'Ed25519' }, false, ['sign', 'verify']);
+      const pub = new Uint8Array(await subtle().exportKey('raw', kp.publicKey));
+      return { publicKey: pub, privateKey: kp.privateKey };
+    },
+    async sign(privateKey, data) {
+      return new Uint8Array(await subtle().sign({ name: 'Ed25519' }, privateKey, data));
+    },
+    async verify(publicKey, signature, data) {
+      const key = await subtle().importKey('raw', publicKey, { name: 'Ed25519' }, false, ['verify']);
+      return subtle().verify({ name: 'Ed25519' }, key, signature, data);
+    },
+  },
+  'ml-dsa-65': {
+    publicKeyLength: 1952,
+    signatureLength: 3309,
+    async generate() {
+      const mldsa = await loadMlDsa();
+      const { publicKey, secretKey } = mldsa.keygen(); // seeded from crypto.getRandomValues
+      return { publicKey, privateKey: secretKey };
+    },
+    async sign(secretKey, data) {
+      const mldsa = await loadMlDsa();
+      return mldsa.sign(data, secretKey); // hedged (randomized) signing
+    },
+    async verify(publicKey, signature, data) {
+      const mldsa = await loadMlDsa();
+      return mldsa.verify(signature, data, publicKey);
+    },
+  },
+};
+
+/** Signature suites offered to users. A hybrid suite requires every component to verify. */
+export const SUITES = {
+  'ECDSA-P256': {
+    label: 'ECDSA P-256 / SHA-256',
+    family: 'classical',
+    components: ['ecdsa-p256'],
+    note: 'Classical. Universally supported by WebCrypto; private key is non-extractable.',
+  },
+  Ed25519: {
+    label: 'Ed25519',
+    family: 'classical',
+    components: ['ed25519'],
+    note: 'Classical. Compact and fast; needs a recent browser. Private key is non-extractable.',
+  },
+  'ML-DSA-65': {
+    label: 'ML-DSA-65 (FIPS 204)',
+    family: 'post-quantum',
+    components: ['ml-dsa-65'],
+    note: 'Quantum-resistant lattice signature. Larger keys (1.9 KB) and signatures (3.3 KB).',
+  },
+  'Ed25519+ML-DSA-65': {
+    label: 'Hybrid: Ed25519 + ML-DSA-65',
+    family: 'hybrid',
+    components: ['ed25519', 'ml-dsa-65'],
+    note: 'Both signatures must verify, so it stays secure unless both schemes are broken.',
+  },
+};
+
+export function getSuite(alg) {
+  const suite = Object.prototype.hasOwnProperty.call(SUITES, alg) ? SUITES[alg] : null;
+  if (!suite) throw new Error(`Unsupported signature algorithm: ${String(alg)}`);
+  return suite;
+}
+
+/** Probe which suites this browser can actually run. */
+export async function detectSupport() {
+  const probe = async (fn) => { try { await fn(); return true; } catch { return false; } };
+  const comp = {
+    'ecdsa-p256': await probe(() => subtle().generateKey(ECDSA_PARAMS, false, ['sign'])),
+    ed25519: await probe(() => subtle().generateKey({ name: 'Ed25519' }, false, ['sign'])),
+    'ml-dsa-65': await probe(loadMlDsa),
+  };
+  const out = {};
+  for (const [alg, suite] of Object.entries(SUITES)) out[alg] = suite.components.every((c) => comp[c]);
+  return out;
+}
+
+// ---------------------------------------------------------------------------
+// Keys
+// ---------------------------------------------------------------------------
+
+/** Key id: first 16 bytes of SHA-256 over the algorithm and length-prefixed public keys. */
+export async function computeKid(alg, publicKeys) {
+  const parts = [enc.encode(KID_TAG + alg + '\u0000')];
+  for (const pk of publicKeys) parts.push(u32be(pk.length), pk);
+  const digest = new Uint8Array(await subtle().digest('SHA-256', concatBytes(...parts)));
+  return toHex(digest.subarray(0, 16));
+}
+
+/** Human-friendly fingerprint for display, e.g. "3f2a 9c01 ...". */
+export function formatKid(kid) {
+  return String(kid).match(/.{1,4}/g).join(' ');
+}
+
+export async function generateKeyPair(alg) {
+  const suite = getSuite(alg);
+  const publicKeys = [];
+  const privateKeys = [];
+  for (const name of suite.components) {
+    const { publicKey, privateKey } = await COMPONENTS[name].generate();
+    publicKeys.push(publicKey);
+    privateKeys.push(privateKey);
+  }
+  return { alg, kid: await computeKid(alg, publicKeys), publicKeys, privateKeys };
+}
+
+function checkPublicKeys(alg, publicKeys) {
+  const suite = getSuite(alg);
+  if (!Array.isArray(publicKeys) || publicKeys.length !== suite.components.length) {
+    throw new Error(`${alg} requires ${suite.components.length} public key(s)`);
+  }
+  suite.components.forEach((name, i) => {
+    if (publicKeys[i].length !== COMPONENTS[name].publicKeyLength) {
+      throw new Error(`Wrong public key length for ${name}`);
+    }
+  });
+}
+
+export function encodePublicKey({ alg, publicKeys, label }) {
+  const body = { v: ENVELOPE_VERSION, alg, pub: publicKeys.map(bytesToB64url) };
+  if (label) body.label = String(label).slice(0, 80);
+  return PUBKEY_PREFIX + bytesToB64url(enc.encode(JSON.stringify(body)));
+}
+
+export async function decodePublicKey(token) {
+  const str = String(token || '').trim();
+  if (!str.startsWith(PUBKEY_PREFIX)) throw new Error(`Public keys start with "${PUBKEY_PREFIX}"`);
+  if (str.length > MAX_TOKEN_CHARS) throw new Error('Public key token is too large');
+  let body;
+  try {
+    body = JSON.parse(dec.decode(b64urlToBytes(str.slice(PUBKEY_PREFIX.length))));
+  } catch {
+    throw new Error('Public key token is malformed');
+  }
+  if (!body || body.v !== ENVELOPE_VERSION || !Array.isArray(body.pub)) throw new Error('Unsupported public key format');
+  const publicKeys = body.pub.map(b64urlToBytes);
+  checkPublicKeys(body.alg, publicKeys);
+  const label = typeof body.label === 'string' ? body.label.slice(0, 80) : '';
+  return { alg: body.alg, publicKeys, label, kid: await computeKid(body.alg, publicKeys) };
+}
+
+// ---------------------------------------------------------------------------
+// Signing & verification
+// ---------------------------------------------------------------------------
+
+function signingInput(unsigned) {
+  return enc.encode(DOMAIN_TAG + canonicalize(unsigned));
+}
+
+function unsignedPart(env) {
+  return { v: env.v, typ: env.typ, alg: env.alg, kid: env.kid, iat: env.iat, payload: env.payload, pub: env.pub };
+}
+
+/**
+ * Sign a document.
+ * @param {{typ: string, payload: object, key: {alg, kid, publicKeys, privateKeys}, now?: Date}} args
+ */
+export async function signDocument({ typ, payload, key, now = new Date() }) {
+  if (!DOCUMENT_TYPES.includes(typ)) throw new Error(`Unknown document type: ${typ}`);
+  const suite = getSuite(key.alg);
+  checkPublicKeys(key.alg, key.publicKeys);
+  const unsigned = {
+    v: ENVELOPE_VERSION,
+    typ,
+    alg: key.alg,
+    kid: await computeKid(key.alg, key.publicKeys),
+    iat: now.toISOString(),
+    payload: JSON.parse(canonicalize(payload)), // normalise and reject non-JSON values early
+    pub: key.publicKeys.map(bytesToB64url),
+  };
+  const data = signingInput(unsigned);
+  const sig = [];
+  for (let i = 0; i < suite.components.length; i++) {
+    sig.push(bytesToB64url(await COMPONENTS[suite.components[i]].sign(key.privateKeys[i], data)));
+  }
+  return { ...unsigned, sig };
+}
+
+export function encodeToken(env) {
+  return TOKEN_PREFIX + bytesToB64url(enc.encode(canonicalize(env)));
+}
+
+/** Parse a token ("DGSIG1.…") or the raw JSON envelope. Throws on structural problems. */
+export function decodeToken(input) {
+  const str = String(input || '').trim();
+  if (!str) throw new Error('Paste a signed receipt or voucher first');
+  if (str.length > MAX_TOKEN_CHARS) throw new Error('Signed document is too large');
+  let env;
+  try {
+    const json = str.startsWith(TOKEN_PREFIX) ? dec.decode(b64urlToBytes(str.slice(TOKEN_PREFIX.length))) : str;
+    env = JSON.parse(json);
+  } catch {
+    throw new Error('Not a valid Daily Grind signed document (could not decode)');
+  }
+  const isObj = (o) => o && typeof o === 'object' && !Array.isArray(o);
+  if (!isObj(env)) throw new Error('Signed document must be a JSON object');
+  if (env.v !== ENVELOPE_VERSION) throw new Error(`Unsupported document version: ${String(env.v)}`);
+  if (!DOCUMENT_TYPES.includes(env.typ)) throw new Error('Unknown document type');
+  if (typeof env.kid !== 'string' || typeof env.iat !== 'string') throw new Error('Missing key id or issue date');
+  if (!isObj(env.payload)) throw new Error('Missing payload');
+  if (!Array.isArray(env.pub) || !Array.isArray(env.sig)) throw new Error('Missing public key or signature');
+  const allowed = new Set(['v', 'typ', 'alg', 'kid', 'iat', 'payload', 'pub', 'sig']);
+  for (const k of Object.keys(env)) if (!allowed.has(k)) throw new Error(`Unexpected field "${k}"`);
+  getSuite(env.alg);
+  return env;
+}
+
+/**
+ * Verify a decoded envelope.
+ * @param env  decoded envelope
+ * @param opts.trustedKids  Set/Map/array of key ids this verifier trusts (issuer keys)
+ * @returns {{signatureValid, trusted, authentic, kid, alg, checks: Array<{ok, label}>, error?}}
+ */
+export async function verifyDocument(env, { trustedKids = [] } = {}) {
+  const checks = [];
+  const result = { signatureValid: false, trusted: false, authentic: false, kid: env.kid, alg: env.alg, checks };
+  try {
+    const suite = getSuite(env.alg);
+    const publicKeys = env.pub.map(b64urlToBytes);
+    checkPublicKeys(env.alg, publicKeys);
+    if (env.sig.length !== suite.components.length) throw new Error('Wrong number of signatures for algorithm');
+
+    const kid = await computeKid(env.alg, publicKeys);
+    const kidOk = kid === env.kid;
+    checks.push({ ok: kidOk, label: kidOk ? 'Key id matches the embedded public key' : 'Key id does not match the embedded public key' });
+
+    const data = signingInput(unsignedPart(env));
+    let allOk = kidOk;
+    for (let i = 0; i < suite.components.length; i++) {
+      const name = suite.components[i];
+      let ok = false;
+      try {
+        const sig = b64urlToBytes(env.sig[i]);
+        ok = sig.length === COMPONENTS[name].signatureLength &&
+          (await COMPONENTS[name].verify(publicKeys[i], sig, data)) === true;
+      } catch {
+        ok = false;
+      }
+      checks.push({ ok, label: `${name.toUpperCase()} signature ${ok ? 'valid' : 'INVALID'}` });
+      allOk = allOk && ok;
+    }
+    result.signatureValid = allOk;
+
+    const trustedSet = trustedKids instanceof Set || trustedKids instanceof Map ? trustedKids : new Set(trustedKids);
+    result.trusted = kidOk && trustedSet.has(kid);
+    checks.push({
+      ok: result.trusted,
+      label: result.trusted ? 'Signed by a trusted Daily Grind issuer key' : 'Signing key is not in your trusted issuer list',
+    });
+    result.authentic = result.signatureValid && result.trusted;
+  } catch (err) {
+    result.error = err.message;
+    checks.push({ ok: false, label: err.message });
+  }
+  return result;
+}
+
+// ---------------------------------------------------------------------------
+// Business rules (checked after the signature, on the signed payload only)
+// ---------------------------------------------------------------------------
+
+export function formatCents(cents, currency = 'USD') {
+  return new Intl.NumberFormat('en-US', { style: 'currency', currency }).format(cents / 100);
+}
+
+const isCents = (n) => Number.isSafeInteger(n) && n >= 0;
+
+/** Returns [{ok, label}] describing whether the payload is internally consistent and currently usable. */
+export function checkPayloadRules(typ, payload, now = new Date()) {
+  const out = [];
+  if (typ === 'receipt') {
+    const items = Array.isArray(payload.items) ? payload.items : [];
+    const itemsOk = items.length > 0 && items.every((it) =>
+      it && typeof it.name === 'string' && Number.isSafeInteger(it.qty) && it.qty > 0 && isCents(it.unitCents));
+    out.push({ ok: itemsOk, label: itemsOk ? `${items.length} line item(s) well-formed` : 'Line items are malformed' });
+    if (itemsOk) {
+      const subtotal = items.reduce((s, it) => s + it.qty * it.unitCents, 0);
+      const totalsOk = subtotal === payload.subtotalCents && isCents(payload.taxCents) &&
+        payload.subtotalCents + payload.taxCents === payload.totalCents;
+      out.push({ ok: totalsOk, label: totalsOk ? 'Subtotal, tax and total add up' : 'Totals do not add up' });
+    }
+  } else if (typ === 'voucher') {
+    const amountOk = isCents(payload.amountCents) && payload.amountCents > 0;
+    out.push({ ok: amountOk, label: amountOk ? 'Voucher amount is valid' : 'Voucher amount is invalid' });
+    if (payload.expires) {
+      const exp = new Date(`${payload.expires}T23:59:59`);
+      const notExpired = !Number.isNaN(exp.getTime()) && exp >= now;
+      out.push({ ok: notExpired, label: notExpired ? `Valid until ${payload.expires}` : `Expired on ${payload.expires}` });
+    }
+  }
+  return out;
+}
