diff --git a/tests/dg-sign.test.mjs b/tests/dg-sign.test.mjs
new file mode 100644
index 0000000..bbe0e76
--- /dev/null
+++ b/tests/dg-sign.test.mjs
@@ -0,0 +1,51 @@
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import * as S from '../js/dg-sign.js';
+
+const receipt = {
+  orderId: 'DG-20261120-ABC123', store: 'Main St. Roastery', currency: 'USD',
+  items: [{ name: 'Cold Brew', qty: 2, unitCents: 495 }], subtotalCents: 990, taxCents: 88, totalCents: 1078,
+};
+
+for (const alg of Object.keys(S.SUITES)) {
+  test(`${alg}: sign, encode, decode, verify`, async () => {
+    const key = await S.generateKeyPair(alg);
+    const env = S.decodeToken(S.encodeToken(await S.signDocument({ typ: 'receipt', payload: receipt, key })));
+    const res = await S.verifyDocument(env, { trustedKids: [key.kid] });
+    assert.equal(res.authentic, true);
+    assert.deepEqual(S.checkPayloadRules('receipt', env.payload).map((c) => c.ok), [true, true]);
+
+    // Untrusted key: intact but not authentic.
+    const untrusted = await S.verifyDocument(env, { trustedKids: [] });
+    assert.equal(untrusted.signatureValid, true);
+    assert.equal(untrusted.authentic, false);
+
+    // Tampered payload.
+    const t = structuredClone(env); t.payload.totalCents -= 100;
+    assert.equal((await S.verifyDocument(t, { trustedKids: [key.kid] })).signatureValid, false);
+
+    // Swapped public key (even if also trusted) must fail.
+    const other = await S.generateKeyPair(alg);
+    const sw = structuredClone(env); sw.pub = other.publicKeys.map(S.bytesToB64url); sw.kid = other.kid;
+    assert.equal((await S.verifyDocument(sw, { trustedKids: [key.kid, other.kid] })).signatureValid, false);
+
+    // Public key token round-trip.
+    const pk = await S.decodePublicKey(S.encodePublicKey({ alg, publicKeys: key.publicKeys, label: 'Till 1' }));
+    assert.equal(pk.kid, key.kid);
+  });
+}
+
+test('algorithm downgrade/relabel fails', async () => {
+  const key = await S.generateKeyPair('Ed25519+ML-DSA-65');
+  const env = await S.signDocument({ typ: 'voucher', payload: { code: 'X', amountCents: 2500 }, key });
+  const down = { ...env, alg: 'Ed25519', pub: env.pub.slice(0, 1), sig: env.sig.slice(0, 1) };
+  assert.equal((await S.verifyDocument(down, { trustedKids: [key.kid] })).signatureValid, false);
+});
+
+test('voucher expiry and malformed tokens', () => {
+  const rules = S.checkPayloadRules('voucher', { amountCents: 500, expires: '2020-01-01' });
+  assert.equal(rules.at(-1).ok, false);
+  assert.throws(() => S.decodeToken('DGSIG1.!!!'));
+  assert.throws(() => S.decodeToken('{"v":1,"typ":"receipt","alg":"RSA"}'));
+  assert.throws(() => S.canonicalize({ a: NaN }));
+});
