+            if (carousel.dataset.bound) return;
+            carousel.dataset.bound = 'true';
+
+            const viewport = carousel.querySelector<HTMLElement>('[data-viewport]')!;
+            const slides = Array.from(carousel.querySelectorAll<HTMLElement>('[data-slide]'));
+            const counter = carousel.querySelector<HTMLElement>('[data-counter]');
+            const status = carousel.querySelector<HTMLElement>('[data-status]');
+            const total = slides.length;
+            let current = Math.max(0, slides.findIndex((slide) => !slide.hidden));
