+import { useState } from 'react';
+import { ChevronLeftIcon, ChevronRightIcon } from '@heroicons/react/24/outline';
+
+export interface TopStory {
+  id: string;
+  title: string;
+  date: string;
+}
+
+interface Props {
+  stories: TopStory[];
+}
+
+type Direction = 'next' | 'prev' | null;
+
+export default function TopStoriesCarousel({ stories }: Props) {
+  const [index, setIndex] = useState(0);
+  const [direction, setDirection] = useState<Direction>(null);
+  // Bumped on every navigation so the slide re-mounts and the animation replays,
+  // even when wrapping around to the same story (e.g. a single-story list).
+  const [changeCount, setChangeCount] = useState(0);
+
+  if (stories.length === 0) return null;
+
+  const go = (dir: Exclude<Direction, null>) => {
+    setDirection(dir);
+    setIndex((i) => (dir === 'next' ? (i + 1) % stories.length : (i - 1 + stories.length) % stories.length));
+    setChangeCount((c) => c + 1);
+  };
+
+  const story = stories[index];
+  const animationClass =
+    direction === 'next' ? 'top-story-enter-from-right' : direction === 'prev' ? 'top-story-enter-from-left' : '';
+
+  const buttonClass =
+    'flex-shrink-0 p-2 rounded-full border border-gray-300 text-gray-700 hover:text-amber-400 hover:border-amber-400 focus:outline-none focus-visible:ring-2 focus-visible:ring-amber-400 transition-colors';
+
+  return (
+    <section aria-roledescription="carousel" aria-label="Top stories" className="flex items-center gap-4">
+      <button type="button" onClick={() => go('prev')} className={buttonClass} aria-label="Previous story">
+        <ChevronLeftIcon className="w-5 h-5" />
+      </button>
+
+      <div className="flex-grow overflow-hidden" aria-live="polite">
+        <div
+          key={changeCount}
+          className={`text-center ${animationClass}`}
+          role="group"
+          aria-roledescription="slide"
+          aria-label={`${index + 1} of ${stories.length}`}
+        >
+          <a href={`${import.meta.env.BASE_URL}articles/${story.id}`}>
+            <h3 className="font-bold text-gray-900 hover:text-amber-400 cursor-pointer">{story.title}</h3>
+          </a>
+          <span className="text-xs text-gray-500">
+            {story.date}
+            <span className="mx-2" aria-hidden="true">·</span>
+            {index + 1} / {stories.length}
+          </span>
+        </div>
+      </div>
+
+      <button type="button" onClick={() => go('next')} className={buttonClass} aria-label="Next story">
+        <ChevronRightIcon className="w-5 h-5" />
+      </button>
+    </section>
+  );
+}
