+        <div class="field row">
+          <span id="qty-label" style="font-weight:600;font-size:0.8rem;color:var(--primary)">Quantity</span>
+          <div class="stepper" role="group" aria-labelledby="qty-label">
+            <button type="button" id="qty-dec" aria-label="Decrease quantity">&minus;</button>
+            <output id="qty" aria-live="polite">1</output>
+            <button type="button" id="qty-inc" aria-label="Increase quantity">+</button>
+          </div>
+        </div>
+
+        <button type="submit" class="add-btn">Add to cart · <span id="line-price">$5.75</span></button>
+      </form>
+
+      <ul class="cart-list" id="cart-list" aria-label="Cart items">
+        <li class="cart-empty">Your cart is empty.</li>
+      </ul>
+      <p class="cart-total">Total: <span id="cart-total">$0.00</span></p>
+      <a href="/order-online" class="checkout-btn" id="checkout-btn" aria-disabled="true">Checkout</a>
+
+      <details class="help-text" id="drag-help" hidden>
+        <summary>How do I move this panel?</summary>
+        <p>Drag the brown header to move the panel. Or focus the <strong>&#8942;&#8942;</strong> handle and use the
+          <kbd>&larr;</kbd> <kbd>&uarr;</kbd> <kbd>&rarr;</kbd> <kbd>&darr;</kbd> keys (hold <kbd>Shift</kbd> for
+          bigger steps). The <strong>&#10021;</strong> button docks it to a corner.</p>
+      </details>
+    </div>
+    <div class="visually-hidden" aria-live="polite" id="quick-order-status"></div>
+  </aside>
+
+  <script>
+    (() => {
+      const panel = document.querySelector('[data-draggable]');
+      if (!panel) return;
+      const handle = panel.querySelector('[data-drag-handle]');
+      const grip = panel.querySelector('#quick-order-grip');
+      const status = panel.querySelector('#quick-order-status');
+      const STORAGE_KEY = 'dailyGrind.quickOrder';
+      const KEY_STEP = 15;
+      const EDGE = 12;
+
+      /* ---------- persistence ---------- */
+      const load = () => {
+        try { return JSON.parse(localStorage.getItem(STORAGE_KEY)) || {}; } catch { return {}; }
+      };
+      const state = Object.assign({ cart: [], pos: null, collapsed: false }, load());
+      const save = () => {
+        try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); } catch { /* storage unavailable */ }
+      };
+
+      /* ---------- announcements ---------- */
+      let statusTimer;
+      const announce = (msg) => {
+        status.textContent = msg;
+        clearTimeout(statusTimer);
+        statusTimer = setTimeout(() => { status.textContent = ''; }, 1000);
+      };
+
+      /* ---------- positioning ---------- */
+      function moveTo(left, top) {
+        const maxLeft = Math.max(0, window.innerWidth - panel.offsetWidth);
+        const maxTop = Math.max(0, window.innerHeight - panel.offsetHeight);
+        const x = Math.max(0, Math.min(left, maxLeft));
+        const y = Math.max(0, Math.min(top, maxTop));
+        panel.style.left = `${x}px`;
+        panel.style.top = `${y}px`;
+        state.pos = { left: x, top: y };
+        return state.pos;
+      }
+
+      function initPosition() {
+        const rect = panel.getBoundingClientRect();
+        panel.classList.add('is-positioned');
+        if (state.pos) moveTo(state.pos.left, state.pos.top);
+        else moveTo(rect.left, rect.top);
+      }
+
+      function dock(corner) {
+        const w = panel.offsetWidth;
+        const h = panel.offsetHeight;
+        const left = corner.endsWith('left') ? EDGE : window.innerWidth - w - EDGE;
+        const top = corner.startsWith('top') ? EDGE + (document.querySelector('nav')?.offsetHeight || 0)
+          : window.innerHeight - h - EDGE;
+        panel.classList.add('is-docking');
+        moveTo(left, top);
+        setTimeout(() => panel.classList.remove('is-docking'), 300);
+        save();
+        announce(`Quick order panel docked ${corner.replace('-', ' ')}`);
+      }
+
+      /* ---------- pointer dragging ---------- */
+      let offsetX = 0, offsetY = 0, startX = 0, startY = 0, dragging = false;
+
+      handle.addEventListener('pointerdown', (event) => {
+        const control = event.target.closest('button, input, select, textarea, a');
+        if (event.button !== 0 || (control && control !== grip)) return;
+        const rect = panel.getBoundingClientRect();
+        offsetX = event.clientX - rect.left;
+        offsetY = event.clientY - rect.top;
+        startX = event.clientX;
+        startY = event.clientY;
+        dragging = false;
+        handle.setPointerCapture(event.pointerId);
+      });
+
+      handle.addEventListener('pointermove', (event) => {
+        if (!handle.hasPointerCapture(event.pointerId)) return;
+        if (!dragging) {
+          if (Math.hypot(event.clientX - startX, event.clientY - startY) < 4) return;
+          dragging = true;
+          handle.classList.add('dragging');
+          panel.classList.add('is-dragging');
+        }
+        moveTo(event.clientX - offsetX, event.clientY - offsetY);
+      });
+
+      handle.addEventListener('lostpointercapture', () => {
+        handle.classList.remove('dragging');
+        panel.classList.remove('is-dragging');
+        if (dragging) {
+          save();
+          announce('Quick order panel moved');
+        }
+        dragging = false;
+      });
+
+      /* ---------- keyboard moving ---------- */
+      const KEY_DELTAS = {
+        ArrowLeft: [-1, 0, 'left'],
+        ArrowRight: [1, 0, 'right'],
+        ArrowUp: [0, -1, 'up'],
+        ArrowDown: [0, 1, 'down'],
+      };
+
+      grip.addEventListener('keydown', (event) => {
+        const delta = KEY_DELTAS[event.key];
+        if (!delta) return;
+        event.preventDefault();
+        const step = event.shiftKey ? KEY_STEP * 4 : KEY_STEP;
+        const rect = panel.getBoundingClientRect();
+        const before = { left: rect.left, top: rect.top };
+        const after = moveTo(rect.left + delta[0] * step, rect.top + delta[1] * step);
+        save();
+        const hitEdge = after.left === before.left && after.top === before.top;
+        announce(hitEdge ? 'Quick order panel is at the edge of the screen' : `Quick order panel moved ${delta[2]}`);
+      });
+
+      /* ---------- dock menu ---------- */
+      const dockToggle = panel.querySelector('#dock-toggle');
+      const dockMenu = panel.querySelector('#dock-menu');
+      const supportsPopover = typeof HTMLElement.prototype.showPopover === 'function';
+
+      if (supportsPopover) {
+        dockToggle.hidden = false;
+        dockMenu.addEventListener('toggle', (event) => {
+          if (event.newState !== 'open') return;
+          const r = dockToggle.getBoundingClientRect();
+          const mw = dockMenu.offsetWidth;
+          const mh = dockMenu.offsetHeight;
+          const below = r.bottom + 4 + mh <= window.innerHeight;
+          dockMenu.style.top = `${below ? r.bottom + 4 : Math.max(4, r.top - mh - 4)}px`;
+          dockMenu.style.left = `${Math.max(4, Math.min(r.right - mw, window.innerWidth - mw - 4))}px`;
+          dockMenu.querySelector('button')?.focus();
+        });
+        dockMenu.addEventListener('click', (event) => {
+          const btn = event.target.closest('[data-dock]');
+          if (!btn) return;
+          dockMenu.hidePopover();
+          dock(btn.dataset.dock);
+          dockToggle.focus();
+        });
+      } else {
+        dockMenu.remove();
+      }
+
+      /* ---------- collapse ---------- */
+      const collapseToggle = panel.querySelector('#collapse-toggle');
+      function setCollapsed(collapsed) {
+        state.collapsed = collapsed;
+        panel.classList.toggle('is-collapsed', collapsed);
+        collapseToggle.setAttribute('aria-expanded', String(!collapsed));
+        collapseToggle.setAttribute('aria-label', `${collapsed ? 'Expand' : 'Minimize'} quick order panel`);
+        collapseToggle.innerHTML = collapsed ? '&#43;' : '&minus;';
+        if (state.pos) moveTo(state.pos.left, state.pos.top);
+      }
+      collapseToggle.addEventListener('click', () => {
+        setCollapsed(!state.collapsed);
+        save();
+      });
+
+      /* ---------- order builder ---------- */
+      const form = panel.querySelector('#quick-order-form');
+      const qtyOut = panel.querySelector('#qty');
+      const qtyDec = panel.querySelector('#qty-dec');
+      const qtyInc = panel.querySelector('#qty-inc');
+      const linePrice = panel.querySelector('#line-price');
+      const cartList = panel.querySelector('#cart-list');
+      const cartTotal = panel.querySelector('#cart-total');
+      const cartCount = panel.querySelector('#cart-count');
+      const checkoutBtn = panel.querySelector('#checkout-btn');
+      const money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });
+      const MAX_QTY = 10;
+      let qty = 1;
+
+      function currentItem() {
+        const drink = form.drink.selectedOptions[0];
+        const size = form.querySelector('input[name="size"]:checked');
+        const milk = form.milk.selectedOptions[0];
+        const shot = form.shot.checked;
+        const unit = parseFloat(drink.dataset.price) + parseFloat(size.dataset.upcharge)
+          + parseFloat(milk.dataset.upcharge) + (shot ? 0.75 : 0);
+        const extras = [size.value, milk.value === 'None' ? 'no milk' : `${milk.value.toLowerCase()} milk`];
+        if (shot) extras.push('extra shot');
+        return { name: drink.value, details: extras.join(', '), unit, qty };
+      }
+
+      function updateLinePrice() {
+        const item = currentItem();
+        linePrice.textContent = money.format(item.unit * item.qty);
+        qtyOut.textContent = qty;
+        qtyDec.disabled = qty <= 1;
+        qtyInc.disabled = qty >= MAX_QTY;
+      }
+
+      function renderCart() {
+        cartList.replaceChildren();
+        if (!state.cart.length) {
+          const li = document.createElement('li');
+          li.className = 'cart-empty';
+          li.textContent = 'Your cart is empty.';
+          cartList.append(li);
+        }
+        state.cart.forEach((item, index) => {
+          const li = document.createElement('li');
+          const name = document.createElement('span');
+          name.className = 'item-name';
+          name.textContent = `${item.qty}× ${item.name} (${item.details})`;
+          const price = document.createElement('span');
+          price.textContent = money.format(item.unit * item.qty);
+          const remove = document.createElement('button');
+          remove.type = 'button';
+          remove.className = 'remove-btn';
+          remove.dataset.index = index;
+          remove.setAttribute('aria-label', `Remove ${item.name}`);
+          remove.textContent = '×';
+          li.append(name, price, remove);
+          cartList.append(li);
+        });
+        const count = state.cart.reduce((n, i) => n + i.qty, 0);
+        const total = state.cart.reduce((n, i) => n + i.unit * i.qty, 0);
+        cartTotal.textContent = money.format(total);
+        cartCount.textContent = count;
+        cartCount.setAttribute('aria-label', `${count} item${count === 1 ? '' : 's'} in cart`);
+        checkoutBtn.setAttribute('aria-disabled', String(count === 0));
+        if (count === 0) checkoutBtn.setAttribute('tabindex', '-1');
+        else checkoutBtn.removeAttribute('tabindex');
+        if (state.pos) moveTo(state.pos.left, state.pos.top);
+      }
+
+      form.addEventListener('change', updateLinePrice);
+      qtyDec.addEventListener('click', () => { qty = Math.max(1, qty - 1); updateLinePrice(); });
+      qtyInc.addEventListener('click', () => { qty = Math.min(MAX_QTY, qty + 1); updateLinePrice(); });
+
+      form.addEventListener('submit', (event) => {
+        event.preventDefault();
+        const item = currentItem();
+        const existing = state.cart.find((i) => i.name === item.name && i.details === item.details && i.unit === item.unit);
+        if (existing) existing.qty = Math.min(99, existing.qty + item.qty);
+        else state.cart.push(item);
+        save();
+        renderCart();
+        announce(`Added ${item.qty} ${item.name} to cart`);
+        qty = 1;
+        updateLinePrice();
+      });
+
+      cartList.addEventListener('click', (event) => {
+        const btn = event.target.closest('.remove-btn');
+        if (!btn) return;
+        const [removed] = state.cart.splice(Number(btn.dataset.index), 1);
+        save();
+        renderCart();
+        announce(`Removed ${removed.name} from cart`);
+        (cartList.querySelector('.remove-btn') || form.drink).focus();
+      });
+
+      /* ---------- init ---------- */
+      grip.hidden = false;
+      panel.querySelector('#drag-help').hidden = false;
+      handle.classList.add('drag-ready');
+      setCollapsed(state.collapsed);
+      updateLinePrice();
+      renderCart();
+      initPosition();
+
+      const reclamp = () => { if (state.pos) moveTo(state.pos.left, state.pos.top); };
+      window.addEventListener('resize', reclamp);
+      new ResizeObserver(reclamp).observe(panel);
+    })();
+  </script>
+
 </body>

 </html>

