--- /dev/null
+++ b/src/scripts/section-router.ts
@@ -0,0 +1,280 @@
+/**
+ * Client-side router for the main sections (Top News, World, Politics,
+ * Multimedia, Reports).
+ *
+ * - Every section has a real server route; the first visit to a section that
+ *   is not in the DOM yet fetches that route and extracts its view.
+ * - Views are never destroyed: inactive ones stay in `#section-views` with
+ *   `content-visibility: hidden` (+ `inert`), so returning to them restores
+ *   the cached DOM, rendering state, hydrated islands, and scroll position.
+ * - Cooperates with Astro's <ClientRouter />: section clicks/popstates are
+ *   handled here when the current page is a section page; everything else is
+ *   left to Astro. The container is `transition:persist`ed, and on
+ *   `astro:before-swap` the incoming page's view is merged into the cache.
+ *
+ * The number of views is fixed and small (5), so no eviction is needed.
+ */
+import { sectionFromPath, sectionHref, type SectionId } from '../utils/sections';
+
+const CONTAINER_ID = 'section-views';
+const INACTIVE_CLASS = 'is-inactive';
+
+const inflight = new Map<SectionId, Promise<HTMLElement>>();
+let navigationToken = 0;
+
+const getContainer = () => document.getElementById(CONTAINER_ID);
+
+/** A section page is one whose main content is a section view. */
+const isSectionPage = (container: HTMLElement | null): container is HTMLElement =>
+  !!container?.dataset.currentView;
+
+const findView = (container: ParentNode, id: string) =>
+  container.querySelector<HTMLElement>(`:scope > [data-section-view="${CSS.escape(id)}"]`);
+
+function setViewActive(view: HTMLElement, active: boolean) {
+  view.classList.toggle(INACTIVE_CLASS, !active);
+  view.inert = !active;
+  if (active) view.removeAttribute('aria-hidden');
+  else view.setAttribute('aria-hidden', 'true');
+}
+
+function updateNav(id: string) {
+  for (const link of document.querySelectorAll<HTMLAnchorElement>('[data-section-nav] a[data-section-link]')) {
+    if (link.dataset.sectionLink === id) link.setAttribute('aria-current', 'page');
+    else link.removeAttribute('aria-current');
+  }
+}
+
+/** Shows view `id` (or none if `id` is empty) and hides all other cached views. */
+function activate(container: HTMLElement, id: string, { updateDocument }: { updateDocument: boolean }) {
+  for (const view of container.querySelectorAll<HTMLElement>(':scope > [data-section-view]')) {
+    setViewActive(view, view.dataset.sectionView === id);
+  }
+  container.dataset.currentView = id;
+  if (!updateDocument) return;
+
+  const view = findView(container, id);
+  if (view?.dataset.title) document.title = view.dataset.title;
+  updateNav(id);
+}
+
+/** Re-creates scripts so they execute (parsed/adopted scripts are inert). */
+function runScripts(root: ParentNode) {
+  for (const old of root.querySelectorAll<HTMLScriptElement>('script')) {
+    const type = old.getAttribute('type');
+    if (type && type !== 'module' && type !== 'text/javascript') continue;
+    const script = document.createElement('script');
+    for (const attr of old.attributes) script.setAttribute(attr.name, attr.value);
+    script.textContent = old.textContent;
+    // Mark as executed so Astro's ClientRouter won't run it again after a swap.
+    script.dataset.astroExec = '';
+    old.replaceWith(script);
+  }
+}
+
+/** Adds stylesheets/module scripts the fetched page needs but the current one lacks. */
+function mergeHeadAssets(doc: Document, baseUrl: string) {
+  const keyOf = (el: Element) => {
+    const url = el.getAttribute('href') ?? el.getAttribute('src');
+    return url ? `${el.localName}:${new URL(url, baseUrl).href}` : `${el.localName}:${el.textContent}`;
+  };
+  const selector = 'link[rel="stylesheet"], style, script[type="module"][src]';
+  const present = new Set([...document.head.querySelectorAll(selector)].map(keyOf));
+
+  for (const el of doc.head.querySelectorAll(selector)) {
+    const key = keyOf(el);
+    if (present.has(key)) continue;
+    present.add(key);
+    const clone = document.importNode(el, true);
+    for (const attr of ['href', 'src'] as const) {
+      const value = el.getAttribute(attr);
+      if (value) clone.setAttribute(attr, new URL(value, baseUrl).href);
+    }
+    if (clone.localName === 'script') {
+      const script = document.createElement('script');
+      for (const attr of clone.attributes) script.setAttribute(attr.name, attr.value);
+      script.dataset.astroExec = '';
+      document.head.append(script);
+    } else {
+      document.head.append(clone);
+    }
+  }
+}
+
+/** Inserts a view into the cache as an inactive (offscreen) view. */
+function adoptView(container: HTMLElement, view: Element): HTMLElement {
+  const adopted = document.adoptNode(view) as HTMLElement;
+  setViewActive(adopted, false);
+  container.append(adopted);
+  return adopted;
+}
+
+async function fetchView(id: SectionId): Promise<HTMLElement> {
+  const response = await fetch(sectionHref(id), { headers: { Accept: 'text/html' } });
+  if (!response.ok) throw new Error(`Failed to load section "${id}": ${response.status}`);
+  const doc = new DOMParser().parseFromString(await response.text(), 'text/html');
+  const view = doc.querySelector(`[data-section-view="${CSS.escape(id)}"]`);
+  if (!view) throw new Error(`Section "${id}" not found in response`);
+
+  const container = getContainer();
+  if (!container) throw new Error('Section views container missing');
+  // The view may have arrived through an Astro page swap in the meantime.
+  const existing = findView(container, id);
+  if (existing) return existing;
+
+  mergeHeadAssets(doc, response.url);
+  const adopted = adoptView(container, view);
+  runScripts(adopted);
+  return adopted;
+}
+
+/** Returns the cached view, fetching and caching it on first use. */
+function loadView(id: SectionId): Promise<HTMLElement> {
+  const container = getContainer();
+  const cached = container && findView(container, id);
+  if (cached) return Promise.resolve(cached);
+
+  let promise = inflight.get(id);
+  if (!promise) {
+    promise = fetchView(id).finally(() => inflight.delete(id));
+    inflight.set(id, promise);
+  }
+  return promise;
+}
+
+function saveScrollPosition() {
+  if (!history.state) return;
+  history.replaceState({ ...history.state, scrollX, scrollY }, '');
+}
+
+type ShowOptions =
+  | { mode: 'push' }
+  | { mode: 'pop'; scroll: { x: number; y: number } };
+
+async function showSection(id: SectionId, options: ShowOptions) {
+  const token = ++navigationToken;
+  const container = getContainer();
+  if (!container) return;
+
+  if (!findView(container, id)) {
+    container.setAttribute('aria-busy', 'true');
+    try {
+      await loadView(id);
+    } catch (error) {
+      console.error(error);
+      // Fall back to a regular full page load.
+      if (options.mode === 'push') location.assign(sectionHref(id));
+      else location.reload();
+      return;
+    } finally {
+      if (token === navigationToken) container.removeAttribute('aria-busy');
+    }
+    // A newer navigation superseded this one.
+    if (token !== navigationToken || getContainer() !== container) return;
+  }
+
+  if (options.mode === 'push') {
+    saveScrollPosition();
+    const index = typeof history.state?.index === 'number' ? history.state.index + 1 : 0;
+    // Astro-compatible state shape, so Astro's router can restore this entry
+    // when the user comes back to it from a non-section page.
+    history.pushState({ index, scrollX: 0, scrollY: 0 }, '', sectionHref(id));
+  }
+
+  activate(container, id, { updateDocument: true });
+  const view = findView(container, id)!;
+  // Move focus into the new view to keep a logical tab order.
+  view.focus({ preventScroll: true });
+
+  if (options.mode === 'pop') {
+    scrollTo(options.scroll.x, options.scroll.y);
+  } else {
+    // Keep the section nav in context: only scroll up if we're past the views' top.
+    const top = container.getBoundingClientRect().top + scrollY;
+    if (scrollY > top) scrollTo(0, top);
+  }
+}
+
+/** Resolves a same-origin, plain link to the section it points to. */
+function sectionForLink(link: HTMLAnchorElement): SectionId | null {
+  if (link.hasAttribute('download') || link.hasAttribute('data-astro-reload')) return null;
+  if (link.target && link.target !== '_self') return null;
+  const url = new URL(link.href, location.href);
+  if (url.origin !== location.origin || url.search || url.hash) return null;
+  return sectionFromPath(url.pathname);
+}
+
+function linkFromEvent(event: Event) {
+  return event.target instanceof Element
+    ? event.target.closest<HTMLAnchorElement>('a[href]')
+    : null;
+}
+
+// Capture phase + preventDefault() so Astro's ClientRouter (which ignores
+// default-prevented clicks) doesn't also fetch and swap the whole page.
+document.addEventListener(
+  'click',
+  (event) => {
+    if (event.defaultPrevented || event.button !== 0) return;
+    if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
+    const link = linkFromEvent(event);
+    const id = link && sectionForLink(link);
+    const container = getContainer();
+    if (!id || !isSectionPage(container)) return;
+
+    event.preventDefault();
+    if (id === container.dataset.currentView) {
+      const top = container.getBoundingClientRect().top + scrollY;
+      if (scrollY > top) scrollTo({ top, behavior: 'smooth' });
+      return;
+    }
+    showSection(id, { mode: 'push' });
+  },
+  { capture: true },
+);
+
+// Warm the cache on hover/focus intent so the first switch is fast too.
+const prefetch = (event: Event) => {
+  const link = linkFromEvent(event);
+  const id = link && sectionForLink(link);
+  if (id && isSectionPage(getContainer())) loadView(id).catch(() => {});
+};
+document.addEventListener('pointerover', prefetch, { passive: true });
+document.addEventListener('focusin', prefetch);
+
+// Handle back/forward between section views locally. Capture listeners run
+// before Astro's (non-capture) popstate listener on window, which we stop.
+addEventListener(
+  'popstate',
+  (event) => {
+    const container = getContainer();
+    if (!event.state || !isSectionPage(container)) return;
+    const id = sectionFromPath(location.pathname);
+    if (!id) return;
+    event.stopImmediatePropagation();
+    showSection(id, {
+      mode: 'pop',
+      scroll: { x: event.state.scrollX ?? 0, y: event.state.scrollY ?? 0 },
+    });
+  },
+  { capture: true },
+);
+
+// Astro page navigations (e.g. article → section): the persisted container
+// replaces the incoming one, so merge the incoming page's view into the cache
+// (unless we already have it) and activate the right view before the swap.
+document.addEventListener('astro:before-swap', (event) => {
+  navigationToken++;
+  const live = getContainer();
+  const incoming = event.newDocument.getElementById(CONTAINER_ID);
+  if (!live || !incoming) return;
+
+  const id = incoming.dataset.currentView ?? '';
+  const fresh = id ? findView(incoming, id) : null;
+  if (fresh && !findView(live, id)) {
+    // Its scripts are run by Astro after the swap (they lack data-astro-exec).
+    adoptView(live, fresh);
+  }
+  live.removeAttribute('aria-busy');
+  activate(live, id, { updateDocument: false });
+});
