+/* ---- SPA section views ---------------------------------------------------
+ * Inactive views are kept in the DOM instead of being destroyed.
+ * `content-visibility: hidden` skips their layout/paint but keeps the cached
+ * rendering state, so re-activating a previously visited view is near-instant.
+ */
+.section-view.is-inactive {
