+/**
+ * Main sections of The DevTools Times. Each section is a client-side SPA view
+ * that is also backed by a real server route, so deep links, reloads and
+ * no-JS navigation keep working.
+ */
+export const SECTIONS = [
+  { id: 'top-news', label: 'Top News', path: '', title: 'The DevTools Times' },
+  { id: 'world', label: 'World', path: 'world', title: 'World – The DevTools Times' },
+  { id: 'politics', label: 'Politics', path: 'politics', title: 'Politics – The DevTools Times' },
+  { id: 'multimedia', label: 'Multimedia', path: 'multimedia', title: 'Multimedia – The DevTools Times' },
+  { id: 'reports', label: 'Reports', path: 'reports', title: 'Reports – The DevTools Times' },
+] as const;
+
+export type SectionId = (typeof SECTIONS)[number]['id'];
+
+const BASE = import.meta.env.BASE_URL.endsWith('/')
+  ? import.meta.env.BASE_URL
+  : `${import.meta.env.BASE_URL}/`;
+
+const trimSlashes = (path: string) => path.replace(/\/+$/, '');
+
+export function getSection(id: SectionId) {
+  return SECTIONS.find((section) => section.id === id)!;
+}
+
+export function sectionHref(id: SectionId): string {
+  return `${BASE}${getSection(id).path}`;
+}
+
+/** Maps a URL pathname to the section it renders, or `null` for non-section pages. */
+export function sectionFromPath(pathname: string): SectionId | null {
+  let decoded = pathname;
+  try {
+    decoded = decodeURI(pathname);
+  } catch {
+    // Malformed escape sequences: compare the raw pathname.
+  }
+  const normalized = trimSlashes(decoded);
+  const match = SECTIONS.find((section) => trimSlashes(`${BASE}${section.path}`) === normalized);
+  return match?.id ?? null;
+}

