+++ b/src/components/SectionRouter.astro
@@ -0,0 +1,220 @@
+---
+import { SECTIONS } from '../utils/sections';
+
+const base = import.meta.env.BASE_URL;
+const sections = Object.fromEntries(SECTIONS.map((s) => [s.path, s.key]));
+---
+{/*
+  Client-side controller for the main section views (Top News, World, Politics,
+  Multimedia, Reports).
+
+  It must be a classic inline script placed *before* <ClientRouter /> so that its
+  document "click" and window "popstate" listeners run before Astro's router.
+  For navigations between section URLs on a page that contains the section
+  shell, it takes over (preventDefault / stopImmediatePropagation) and:
+    - shows an already-visited view instantly by toggling it back on (its DOM,
+      hydrated islands and component state are preserved offscreen),
+    - otherwise fetches the view once (or reuses a hover prefetch), extracts it,
+      and appends it next to the other cached views.
+  Everything else is left to Astro's ClientRouter. History entries use the same
+  state shape ({ index, scrollX, scrollY }) as the ClientRouter so it can still
+  handle them, e.g. when going back to a section from an article page.
+*/}
+<style is:global>
+  /*
+   * Offscreen views stay in the DOM. content-visibility: hidden skips their
+   * rendering work (and size-contains them to 0px) while letting the browser
+   * keep their rendering state around, which makes re-showing them cheap.
+   */
+  [data-section-view][hidden] {
+    display: block;
+    content-visibility: hidden;
+  }
+</style>
+<script is:inline define:vars={{ base, sections }}>
+  if (!window.__sectionViews) {
+    const normalizedBase = '/' + base.replace(/^\/+|\/+$/g, '');
+    const basePrefix = normalizedBase === '/' ? '/' : normalizedBase + '/';
+    const pending = new Map(); // key -> Promise<HTMLElement>
+    let navToken = 0;
+
+    const getContainer = () => document.querySelector('[data-section-views]');
+    const getView = (container, key) =>
+      container.querySelector(`:scope > [data-section-view="${CSS.escape(key)}"]`);
+
+    function viewKeyFor(url) {
+      if (url.origin !== location.origin) return null;
+      let path = url.pathname.replace(/\/+$/, '');
+      if (path === normalizedBase || path === '') path = '';
+      else if (path.startsWith(basePrefix)) path = path.slice(basePrefix.length);
+      else return null;
+      return Object.prototype.hasOwnProperty.call(sections, path) ? sections[path] : null;
+    }
+
+    function adoptStyles(doc) {
+      const have = new Set(
+        [...document.head.querySelectorAll('link[rel="stylesheet"], style')].map((el) =>
+          el.tagName === 'LINK' ? el.href : el.textContent,
+        ),
+      );
+      for (const el of doc.head.querySelectorAll('link[rel="stylesheet"], style')) {
+        const id = el.tagName === 'LINK' ? new URL(el.getAttribute('href'), location.href).href : el.textContent;
+        if (!have.has(id)) {
+          document.head.append(document.importNode(el, true));
+          have.add(id);
+        }
+      }
+    }
+
+    // Scripts parsed by DOMParser are inert; recreate them so island directive
+    // scripts (e.g. client:visible) run once the view is attached.
+    function activateScripts(root) {
+      for (const old of root.querySelectorAll('script')) {
+        const script = document.createElement('script');
+        for (const { name, value } of old.attributes) script.setAttribute(name, value);
+        script.textContent = old.textContent;
+        old.replaceWith(script);
+      }
+    }
+
+    function loadView(key, url) {
+      if (pending.has(key)) return pending.get(key);
+      const promise = fetch(url.pathname, { headers: { Accept: 'text/html' }, credentials: 'same-origin' })
+        .then((res) => {
+          if (!res.ok) throw new Error(`Failed to load section "${key}": ${res.status}`);
+          return res.text();
+        })
+        .then((html) => {
+          const doc = new DOMParser().parseFromString(html, 'text/html');
+          const view = doc.querySelector(`[data-section-views] > [data-section-view="${CSS.escape(key)}"]`);
+          if (!view) throw new Error(`Section "${key}" not found in response`);
+          adoptStyles(doc);
+          const el = document.importNode(view, true);
+          el.hidden = true;
+          return el;
+        });
+      pending.set(key, promise);
+      promise.catch(() => pending.delete(key));
+      return promise;
+    }
+
+    function setActiveLinks(key) {
+      for (const link of document.querySelectorAll('[data-section-link]')) {
+        if (link.dataset.sectionLink === key) link.setAttribute('aria-current', 'page');
+        else link.removeAttribute('aria-current');
+      }
+    }
+
+    function show(container, el) {
+      for (const view of container.querySelectorAll(':scope > [data-section-view]')) {
+        const visible = view === el;
+        view.hidden = !visible;
+        view.inert = !visible;
+      }
+      if (el.dataset.sectionTitle) document.title = el.dataset.sectionTitle;
+    }
+
+    async function activate(key, url, { push, scrollY }) {
+      const container = getContainer();
+      if (!container) return false;
+      const token = ++navToken;
+
+      // Update tabs + URL immediately so the UI feels responsive even while a
+      // not-yet-visited view is still loading.
+      setActiveLinks(key);
+      if (push) {
+        history.pushState(
+          { index: (history.state?.index ?? 0) + 1, scrollX: 0, scrollY: window.scrollY },
+          '',
+          url.href,
+        );
+      }
+
+      let el = getView(container, key);
+      if (!el) {
+        container.setAttribute('aria-busy', 'true');
+        try {
+          const loaded = await loadView(key, url);
+          pending.delete(key);
+          // The shell may have been replaced by a ClientRouter navigation meanwhile.
+          if (getContainer() === container) {
+            // A concurrent navigation to the same view may already have attached it.
+            el = getView(container, key);
+            if (!el) {
+              el = loaded;
+              container.append(el);
+              activateScripts(el);
+            }
+          }
+        } catch (err) {
+          console.error(err);
+          if (token === navToken) location.href = url.href;
+          return true;
+        } finally {
+          if (token === navToken) container.removeAttribute('aria-busy');
+        }
+        if (token !== navToken || !el) return true; // superseded by a newer navigation
+      }
+
+      show(container, el);
+
+      if (typeof scrollY === 'number') {
+        window.scrollTo({ left: 0, top: scrollY, behavior: 'instant' });
+      } else {
+        // Keep the section tabs in view instead of jumping to the very top.
+        const shellTop = container.closest('[data-section-shell]').getBoundingClientRect().top + window.scrollY;
+        if (window.scrollY > shellTop) window.scrollTo({ left: 0, top: shellTop, behavior: 'instant' });
+      }
+      document.dispatchEvent(new CustomEvent('section-view:change', { detail: { key, url: url.href } }));
+      return true;
+    }
+
+    document.addEventListener('click', (ev) => {
+      if (ev.defaultPrevented || ev.button !== 0 || ev.metaKey || ev.ctrlKey || ev.shiftKey || ev.altKey) return;
+      const link = ev.composedPath().find((n) => n instanceof HTMLAnchorElement && n.hasAttribute('href'));
+      if (!link || link.hasAttribute('download') || link.hasAttribute('data-astro-reload')) return;
+      if (link.target && link.target !== '_self') return;
+      const url = new URL(link.href, location.href);
+      const key = viewKeyFor(url);
+      if (!key || !getContainer()) return;
+      const current = new URL(location.href);
+      if (url.hash && url.pathname === current.pathname) return; // in-page anchor
+      ev.preventDefault();
+      if (viewKeyFor(current) === key && getView(getContainer(), key) && !getView(getContainer(), key).hidden) {
+        const shell = getContainer().closest('[data-section-shell]');
+        shell.scrollIntoView({ behavior: 'smooth', block: 'start' });
+        return;
+      }
+      activate(key, url, { push: true });
+    });
+
+    window.addEventListener('popstate', (ev) => {
+      const url = new URL(location.href);
+      const key = viewKeyFor(url);
+      const container = getContainer();
+      if (!key || !container) return; // let ClientRouter / the browser handle it
+      // Same view still visible (e.g. hash-only history entries): leave it to ClientRouter.
+      const visible = getView(container, key);
+      if (visible && !visible.hidden) return;
+      ev.stopImmediatePropagation();
+      activate(key, url, { push: false, scrollY: ev.state?.scrollY ?? 0 });
+    });
+
+    // Warm up views on hover/focus so first visits are fast too.
+    const prefetch = (ev) => {
+      const link = ev.target instanceof Element && ev.target.closest('a[data-section-link]');
+      if (!link) return;
+      const container = getContainer();
+      const url = new URL(link.href, location.href);
+      const key = viewKeyFor(url);
+      if (key && container && !getView(container, key)) loadView(key, url).catch(() => {});
+    };
+    document.addEventListener('pointerover', prefetch, { passive: true });
+    document.addEventListener('focusin', prefetch);
+
+    // A ClientRouter swap replaces the shell; drop stale prefetches with it.
+    document.addEventListener('astro:after-swap', () => pending.clear());
+
+    window.__sectionViews = { activate, viewKeyFor };
+  }
+</script>
