+<!doctype html>
+<html lang="en">
+<head>
+  <meta charset="utf-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1">
+  <title>Northwind — Ship faster with less friction</title>
+  <meta name="description" content="Northwind helps product teams plan, build, and ship in one calm, focused workspace.">
+
+  <!-- Open the connection to the experiment CDN as early as possible. -->
+  <link rel="preconnect" href="https://cdn.example.com" crossorigin>
+
+  <!--
+    Experiment SDK.
+    - async: does not block HTML parsing, so the DOM is built while the script downloads.
+    - blocking="render": the browser will not paint anything until this script has run,
+      so the user never sees the original (control) content before the variant is applied.
+  -->
+  <script
+    id="experiment-sdk"
+    src="https://cdn.example.com/experiment-sdk.js"
+    async
+    blocking="render"
+  ></script>
+
+  <!--
+    Fallback for browsers without blocking="render" support (e.g. Firefox):
+    hide the page until the SDK runs, with a safety timeout so the page is never
+    left blank if the CDN is slow or down. Skipped entirely where blocking="render" works.
+  -->
+  <script>
+    if (!Object.hasOwn(HTMLScriptElement.prototype, 'blocking')) {
+      const root = document.documentElement;
+      root.classList.add('ab-loading');
+
+      const reveal = () => root.classList.remove('ab-loading');
+
+      // The SDK can call this once its variant is applied.
+      window.onExperimentReady = reveal;
