+    // Fallback for browsers without `field-sizing: content` (e.g. Firefox).
+    (function () {
+      if (CSS.supports('field-sizing', 'content')) return;
+
+      const canvas = document.createElement('canvas').getContext('2d');
+
+      function textWidth(el, text) {
+        const cs = getComputedStyle(el);
+        canvas.font = `${cs.fontStyle} ${cs.fontWeight} ${cs.fontSize} ${cs.fontFamily}`;
+        return Math.max(...text.split('\n').map(line => canvas.measureText(line).width));
+      }
+
+      function chrome(el) {
+        const cs = getComputedStyle(el);
+        return ['paddingLeft', 'paddingRight', 'borderLeftWidth', 'borderRightWidth']
+          .reduce((sum, p) => sum + parseFloat(cs[p]), 0);
+      }
+
+      function resize(el) {
+        if (el.tagName === 'SELECT') {
+          const opt = el.options[el.selectedIndex];
+          // Extra room for the dropdown arrow.
+          el.style.width = `${Math.ceil(textWidth(el, opt ? opt.text : '') + chrome(el) + 24)}px`;
+          return;
+        }
+        const text = el.value || el.placeholder || '';
+        el.style.width = `${Math.ceil(textWidth(el, text) + chrome(el) + 2)}px`;
+        if (el.tagName === 'TEXTAREA') {
+          el.style.height = 'auto';
+          const cs = getComputedStyle(el);
+          const borders = parseFloat(cs.borderTopWidth) + parseFloat(cs.borderBottomWidth);
+          el.style.height = `${el.scrollHeight + borders}px`;
+        }
+      }
+
+      document.querySelectorAll('.autosize').forEach(el => {
+        resize(el);
+        el.addEventListener(el.tagName === 'SELECT' ? 'change' : 'input', () => resize(el));
+      });
+      if (document.fonts) document.fonts.ready.then(() => document.querySelectorAll('.autosize').forEach(resize));
+    })();
