@@ -0,0 +1,26 @@
+/**
+ * Light-dismiss fallback for <dialog closedby="any"> in browsers that don't
+ * support `closedby` yet (e.g. Safari). Esc/back-gesture already work natively.
+ * Tests the pointer position rather than event.target, because the <dialog>
+ * itself is the target for clicks on its own padding.
+ * Returns a cleanup function.
+ */
+export function enableLightDismissFallback(dialog: HTMLDialogElement): () => void {
+  if (typeof HTMLDialogElement === 'undefined' || 'closedBy' in HTMLDialogElement.prototype) {
+    return () => {};
+  }
+  const outside = (e: PointerEvent) => {
+    const r = dialog.getBoundingClientRect();
+    return e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom;
+  };
+  let pressedOutside = false;
+  const onDown = (e: PointerEvent) => { pressedOutside = outside(e); };
+  // Require press and release outside so a text-selection drag ending on the backdrop doesn't dismiss.
+  const onUp = (e: PointerEvent) => { if (pressedOutside && outside(e)) dialog.close(); };
+  dialog.addEventListener('pointerdown', onDown);
+  dialog.addEventListener('pointerup', onUp);
+  return () => {
+    dialog.removeEventListener('pointerdown', onDown);
+    dialog.removeEventListener('pointerup', onUp);
+  };
+}
