+---
+import { Image } from 'astro:assets';
+import type { HTMLAttributes } from 'astro/types';
+
+export interface Props extends Omit<HTMLAttributes<'img'>, 'src' | 'width' | 'height' | 'alt' | 'sizes'> {
+    src: ImageMetadata | string;
+    alt: string;
+    /** Intrinsic width/height used for the aspect ratio and the `width`/`height` attributes (prevents CLS). */
+    width: number;
+    height: number;
+    /** Candidate widths for the generated `srcset` (local images only). */
+    widths: number[];
+    /** The `sizes` attribute describing the rendered width at each breakpoint. */
+    sizes: string;
+    /** Mark as the page's likely LCP element: eager load with high fetch priority. */
+    priority?: boolean;
+    quality?: number;
+}
+
+const { src, alt, width, height, widths, sizes, priority = false, quality, ...attrs } = Astro.props;
+
+const loading = priority ? 'eager' : 'lazy';
+const fetchpriority = priority ? 'high' : 'auto';
+const decoding = priority ? 'sync' : 'async';
+
+// Only local images can be transformed into multiple widths. Never upscale beyond the source.
+const isLocal = typeof src !== 'string';
+const srcWidths = isLocal
+    ? [...new Set(widths.filter(w => w <= src.width).concat(Math.min(width, src.width)))].sort((a, b) => a - b)
+    : undefined;
+---
+{isLocal ? (
+    <Image
+        src={src}
+        alt={alt}
+        width={width}
+        height={height}
+        widths={srcWidths}
+        sizes={sizes}
+        format="webp"
+        quality={quality}
+        loading={loading}
+        decoding={decoding}
+        fetchpriority={fetchpriority}
+        {...attrs}
+    />
+) : (
+    <img
+        src={src}
+        alt={alt}
+        width={width}
+        height={height}
+        loading={loading}
+        decoding={decoding}
+        fetchpriority={fetchpriority}
+        {...attrs}
+    />
+)}
