new file mode 100644
index 0000000..4afd673
--- /dev/null
+++ b/src/components/ModalDialog.tsx
@@ -0,0 +1,77 @@
+import React, { useEffect, useId, useRef } from 'react';
+
+interface Props {
+    /** Accessible name of the dialog, rendered as its heading. */
+    title: string;
+    /** Visually hide the heading while keeping it as the dialog's accessible name. */
+    hideTitle?: boolean;
+    onClose: () => void;
+    /** Element to focus once the dialog opens. Defaults to the browser's dialog focusing steps. */
+    initialFocusRef?: React.RefObject<HTMLElement | null>;
+    children: React.ReactNode;
+}
+
+/**
+ * Thin wrapper around the native <dialog> element opened with showModal().
+ * The browser provides the top layer, ::backdrop, inertness of the rest of the page,
+ * Escape-to-close, focus containment and focus restoration to the invoking element.
+ */
+export default function ModalDialog({ title, hideTitle = false, onClose, initialFocusRef, children }: Props) {
+    const dialogRef = useRef<HTMLDialogElement>(null);
+    const titleId = useId();
+
+    // Keep the latest onClose without re-running the open effect when the parent re-renders.
+    const onCloseRef = useRef(onClose);
+    onCloseRef.current = onClose;
+
+    useEffect(() => {
+        const dialog = dialogRef.current;
+        if (!dialog) return;
+
+        const handleClose = () => onCloseRef.current();
+        dialog.addEventListener('close', handleClose);
+
+        if (!dialog.open) dialog.showModal();
+        initialFocusRef?.current?.focus();
+
+        return () => {
+            dialog.removeEventListener('close', handleClose);
+            // Closing (rather than just unmounting) lets the browser restore focus to the invoker.
+            if (dialog.open) dialog.close();
+        };
+    }, [initialFocusRef]);
+
+    // Light dismiss for browsers without `closedby="any"`: a click whose target is the
+    // <dialog> element itself landed on the backdrop, since the content fills the box.
+    const handleClick = (event: React.MouseEvent<HTMLDialogElement>) => {
+        if (event.target === event.currentTarget) event.currentTarget.close();
+    };
+
+    return (
+        <dialog
+            ref={dialogRef}
+            aria-labelledby={titleId}
+            onClick={handleClick}
+            {...{ closedby: 'any' }}
+            className="modal-dialog bg-transparent p-0 m-auto mt-[15vh] w-[calc(100%-2rem)] max-w-2xl overflow-visible"
+        >
+            <div className="bg-white shadow-xl relative">
+                <h2 id={titleId} className={hideTitle ? 'sr-only' : 'px-4 pt-4 text-lg font-semibold text-gray-800'}>
+                    {title}
+                </h2>
+                {children}
+                <form method="dialog">
+                    <button
+                        type="submit"
+                        aria-label="Close"
+                        className="absolute -top-2 -right-2 bg-white rounded-full p-1 shadow-md text-gray-500 hover:text-amber-400 hover:scale-110 focus-visible:outline-2 focus-visible:outline-amber-500 transition-transform z-10"
+                    >
+                        <svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
+                            <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
+                        </svg>
+                    </button>
+                </form>
+            </div>
+        </dialog>
+    );
+}
