+
+/* ---------------------------------------------------------------------------
+ * Mega menu: a native popover anchored to the section navigation bar.
+ * ------------------------------------------------------------------------- */
+.site-nav {
+  anchor-name: --site-nav;
+}
+
+.mega-menu[popover] {
+  /* Reset UA popover centering. */
+  inset: auto;
+  margin: 0;
+  padding: 0;
+  color: inherit;
+  border-inline: 0;
+  border-top: 0;
+  overflow: auto;
+
+  /* Fallback for browsers without CSS anchor positioning: dock to the top of the viewport. */
+  top: 0;
+  left: 50%;
+  translate: -50% 0;
+  width: min(72rem, 100vw);
+  max-height: 100dvh;
+}
+
+@supports (anchor-name: --a) {
+  .mega-menu[popover] {
+    position-anchor: --site-nav;
+    top: anchor(bottom);
+    left: anchor(left);
+    translate: none;
+    width: anchor-size(width);
+  }
+}
+
+/* ---------------------------------------------------------------------------
+ * Modal dialogs: fade/scale in, honouring reduced-motion preferences.
+ * ------------------------------------------------------------------------- */
+dialog.modal-dialog {
+  opacity: 0;
+  transform: translateY(-0.5rem) scale(0.98);
+  transition:
+    opacity 150ms ease-out,
+    transform 150ms ease-out,
+    overlay 150ms ease-out allow-discrete,
+    display 150ms ease-out allow-discrete;
+}
+
+dialog.modal-dialog[open] {
+  opacity: 1;
+  transform: none;
+}
+
+@starting-style {
+  dialog.modal-dialog[open] {
+    opacity: 0;
+    transform: translateY(-0.5rem) scale(0.98);
+  }
+}
+
+dialog.modal-dialog::backdrop {
+  background-color: rgb(255 255 255 / 0.3);
+  backdrop-filter: blur(4px);
+}
+
+@media (prefers-reduced-motion: reduce) {
+  dialog.modal-dialog {
+    transition: none;
+  }
+}
+
+/* Prevent background scrolling while a modal dialog is open. */
+html:has(dialog[open]:modal) {
+  overflow: hidden;
+}

