+      var KEY = 'dailyGrindFavorites';
+      var favs;
+      try { favs = JSON.parse(localStorage.getItem(KEY)) || []; } catch (e) { favs = []; }
+
+      function render(btn) {
+        var item = btn.dataset.item;
+        var on = favs.indexOf(item) !== -1;
+        btn.setAttribute('aria-pressed', String(on));
+        btn.setAttribute('aria-label', (on ? 'Remove ' : 'Add ') + item + (on ? ' from' : ' to') + ' favorites');
+      }
+
+      document.querySelectorAll('.fav-btn').forEach(function (btn) {
+        render(btn);
+        btn.addEventListener('click', function () {
+          var item = btn.dataset.item;
+          var i = favs.indexOf(item);
+          if (i === -1) favs.push(item); else favs.splice(i, 1);
+          try { localStorage.setItem(KEY, JSON.stringify(favs)); } catch (e) { }
+          render(btn);
+        });
+      });
+    })();
+  </script>
