@@ -0,0 +1,227 @@
+/**
+ * Daily Grind client-side performance monitoring.
+ *
+ * Measures how long it takes from a user interaction until the resulting
+ * visual update is painted on screen, for:
+ *   - clicks in the navigation bar          (data-perf-region="nav")
+ *   - the "Order Now" hero button           (data-perf-region="order-now")
+ *   - "Seasonal Favorites" cards            (data-perf-region="seasonal-card")
+ *   - client-side view switches (SPA soft navigations)
+ *
+ * Primary APIs (Chromium 151+):
+ *   - 'interaction-contentful-paint': interaction start -> contentful paint,
+ *     following async work (fetch, await, setTimeout) back to the interaction.
+ *   - 'soft-navigation': client-side route changes, with FCP/LCP per view.
+ * Fallback (all Event Timing browsers):
+ *   - 'event' entries: interaction start -> next paint (INP-style latency).
+ *
+ * Results are logged to the console and batched to REPORT_ENDPOINT with
+ * navigator.sendBeacon() when the page is hidden.
+ */
+
+const REPORT_ENDPOINT = '/analytics/perf';
+const REGION_ATTR = 'data-perf-region';
+
+const supported = (type) =>
+  typeof PerformanceObserver !== 'undefined' &&
+  PerformanceObserver.supportedEntryTypes?.includes(type);
+
+/** @type {Array<Record<string, unknown>>} */
+const queue = [];
+
+function report(metric) {
+  queue.push(metric);
+  console.debug('[perf]', metric.type, metric.region ?? metric.url ?? '', `${Math.round(metric.duration)}ms`, metric);
+}
+
+function flush() {
+  if (!queue.length) return;
+  const body = JSON.stringify({ page: location.pathname, metrics: queue.splice(0) });
+  navigator.sendBeacon?.(REPORT_ENDPOINT, body);
+}
+
+addEventListener('visibilitychange', () => {
+  if (document.visibilityState === 'hidden') flush();
+});
+
+/** Returns { region, label } for a tracked element, or null. */
+function describeTarget(node) {
+  const el = node instanceof Element ? node : node?.parentElement;
+  const regionEl = el?.closest(`[${REGION_ATTR}]`);
+  if (!regionEl) return null;
+  const region = regionEl.getAttribute(REGION_ATTR);
+  const labelEl = region === 'seasonal-card' ? regionEl.querySelector('h3') : el.closest('a, button') ?? regionEl;
+  return { region, label: labelEl?.textContent.trim().slice(0, 80) ?? '' };
+}
+
+// --- Map interactions to the UI region that triggered them -----------------
+
+/** interactionId -> { region, label } (from Event Timing entries). */
+const interactionTargets = new Map();
+/** Recent clicks captured directly, matched to entries by start time. */
+const recentClicks = [];
+
+// Captured clicks cover fast interactions that fall below the Event Timing
+// duration threshold (and therefore never produce an 'event' entry).
+document.addEventListener(
+  'pointerdown',
+  (e) => {
+    const target = describeTarget(e.target);
+    if (!target) return;
+    recentClicks.push({ ...target, timeStamp: e.timeStamp });
+    if (recentClicks.length > 20) recentClicks.shift();
