+  const pending = new Map();
+
+  const finalize = (interactionId) => {
+    const entry = pending.get(interactionId);
+    if (!entry) return;
+    pending.delete(interactionId);
+    const target = targetFor(interactionId, entry.startTime);
+    if (!target) return;
+    const lcp = entry.largestContentfulPaint;
+    report({
+      type: 'interaction-contentful-paint',
+      ...target,
+      interactionId,
+      // duration = presentationTime - startTime (interaction start -> pixels on screen).
+      duration: entry.duration,
+      paintedElement: lcp?.element ? describeElement(lcp.element) : null,
+      paintedSize: lcp?.size ?? null,
+      paintedUrl: lcp?.url || null,
+    });
