+  new PerformanceObserver((list) => {
+    for (const entry of list.getEntries()) {
+      // Entries for one interaction arrive progressively larger; keep the latest.
+      pending.set(entry.interactionId, entry);
+      // Finalize older interactions once a newer one starts painting.
+      for (const id of pending.keys()) if (id !== entry.interactionId) finalize(id);
+    }
+  }).observe({ type: 'interaction-contentful-paint', buffered: true });
+
+  addEventListener('visibilitychange', () => {
+    if (document.visibilityState === 'hidden') for (const id of [...pending.keys()]) finalize(id);
+  }, { capture: true }); // capture: run before the flush listener above
+}
+
+// --- 3. Soft navigations: client-side view switches -------------------------
+
+if (supported('soft-navigation') && hasICP) {
+  let activeNav = null;
+  let activeLcp = null;
+
+  const finalizeNav = () => {
+    if (!activeNav) return;
+    const target = targetFor(activeNav.interactionId, activeNav.startTime);
+    report({
+      type: 'soft-navigation',
+      url: activeNav.name,
+      trigger: target,
+      interactionId: activeNav.interactionId,
+      navigationId: activeNav.navigationId,
+      // duration = presentationTime - startTime: first contentful paint of the new view.
+      duration: activeNav.duration,
+      fcp: activeNav.duration,
+      lcp: activeLcp?.duration ?? null,
+      lcpElement: activeLcp?.largestContentfulPaint?.element
+        ? describeElement(activeLcp.largestContentfulPaint.element)
+        : null,
+    });
+    activeNav = activeLcp = null;
+  };
+
+  new PerformanceObserver((list) => {
+    for (const nav of list.getEntries()) {
+      finalizeNav();
+      activeNav = nav;
+      // Include paints that happened before the URL was updated.
+      activeLcp = nav.getLargestInteractionContentfulPaint();
+    }
+  }).observe({ type: 'soft-navigation', buffered: true });
+
+  new PerformanceObserver((list) => {
+    for (const entry of list.getEntries()) {
+      // Match by interactionId, not navigationId.
+      if (activeNav && entry.interactionId === activeNav.interactionId) activeLcp = entry;
+    }
+  }).observe({ type: 'interaction-contentful-paint', buffered: true });
+
+  addEventListener('visibilitychange', () => {
+    if (document.visibilityState === 'hidden') finalizeNav();
+  }, { capture: true });
+}
+
+function describeElement(el) {
+  let s = el.tagName.toLowerCase();
+  if (el.id) s += `#${el.id}`;
+  if (el.classList.length) s += `.${[...el.classList].join('.')}`;
+  return s;
+}

