+  'use strict';
+
+  if (typeof window === 'undefined' || typeof performance === 'undefined') return;
+
+  var CLICK_MATCH_TIMEOUT_MS = 1000; // how long to wait for an Event Timing entry
+  var VIEW_QUIET_MS = 250;           // DOM must be quiet this long for a view switch to settle
+  var VIEW_MAX_MS = 10000;           // hard cap on a view-switch measurement
+  var MAX_BUFFER = 100;
+
+  var endpointMeta = document.querySelector('meta[name="perf-endpoint"]');
+  var endpoint = endpointMeta && endpointMeta.content ? endpointMeta.content : null;
+
+  var debug = false;
+  try {
+    debug = /[?&]perfdebug\b/.test(location.search) || localStorage.getItem('dgPerfDebug') === '1';
+  } catch (e) { /* storage may be unavailable */ }
+
+  var metrics = [];      // everything recorded this page view
+  var unsent = [];       // waiting to be beaconed
+  var pendingClicks = []; // clicks awaiting an Event Timing entry
+  var lastClick = null;
+
+  /* ------------------------------------------------------------------ */
+  /* Helpers                                                             */
+  /* ------------------------------------------------------------------ */
+
