+      var ch = new MessageChannel();
+      ch.port1.onmessage = function () { cb(performance.now()); };
+      ch.port2.postMessage(null);
+    });
+  }
+
+  function record(metric) {
+    metric.page = location.pathname;
+    metric.recordedAt = Date.now();
+    metrics.push(metric);
+    unsent.push(metric);
+    if (metrics.length > MAX_BUFFER) metrics.shift();
+    if (unsent.length > MAX_BUFFER) unsent.shift();
+
+    try {
+      performance.measure('dg:' + metric.type + ':' + metric.name, {
+        start: metric.startTime,
+        end: metric.startTime + metric.duration,
+        detail: metric
+      });
+    } catch (e) { /* older browsers don't support measure options */ }
+
+    try {
+      window.dispatchEvent(new CustomEvent('dailygrind:perf', { detail: metric }));
+    } catch (e) { /* ignore */ }
+
+    if (debug) {
+      console.log('[perf] ' + metric.type + ':' + metric.name + ' painted in ' +
+        metric.duration + 'ms', metric);
+    }
+  }
+
+  function flush() {
+    if (!endpoint || !unsent.length) return;
+    var payload = JSON.stringify({
+      url: location.href,
+      userAgent: navigator.userAgent,
+      metrics: unsent.splice(0, unsent.length)
+    });
+    var sent = false;
+    if (navigator.sendBeacon) {
+      try { sent = navigator.sendBeacon(endpoint, new Blob([payload], { type: 'application/json' })); }
+      catch (e) { sent = false; }
