+  /* ------------------------------------------------------------------ */
+  /* Client-side view switches                                           */
+  /* ------------------------------------------------------------------ */
+
+  var activeView = null;
+
+  /**
+   * Begins measuring a view switch. Returns an `end()` function: call it once
+   * the new view has been rendered into the DOM, and the measurement completes
