+    if (document.visibilityState === 'hidden') onPageHide();
+  });
+  window.addEventListener('pagehide', onPageHide);
+
+  /* ------------------------------------------------------------------ */
+  /* Public API                                                          */
+  /* ------------------------------------------------------------------ */
+
+  window.dailyGrindPerf = {
+    metrics: metrics,
+    startViewSwitch: startViewSwitch,
+    flush: flush,
+    setEndpoint: function (url) { endpoint = url || null; },
+    setDebug: function (on) { debug = !!on; }
+  };
+})();

