+        { id: 103, customer: 'Noah', drink: 'Cappuccino', size: 'Medium', status: 'queued' },
+        { id: 104, customer: 'Mia', drink: 'Cold Brew', size: 'Large', status: 'brewing' },
+        { id: 105, customer: 'Zoe', drink: 'Chai Latte', size: 'Medium', status: 'brewing' },
+        { id: 106, customer: 'Eli', drink: 'Flat White', size: 'Small', status: 'ready' }
+      ];
+
+      // ---- State -------------------------------------------------------
+      // Each column owns its own ordered list of orders; a move only touches
+      // the source and destination lists, and only those columns re-render.
+      var state = {};
