+        } else {
+          orders.forEach(function (o) { list.appendChild(buildCard(o)); });
+        }
+        col.replaceChildren(header, list);
+      }
+
+      function focusCard(id) {
+        var c = document.querySelector('.board .card[data-id="' + id + '"]');
+        if (c && document.activeElement && document.activeElement.closest &&
+            document.activeElement.closest('.board')) {
+          c.focus();
+        }
+      }
+
+      // ---- Drag & drop -------------------------------------------------
