+
+      // ---- Init --------------------------------------------------------
+      load();
+      board.querySelectorAll('.board-column').forEach(function (col) {
+        columnEls[col.dataset.status] = col;
+        setupColumn(col);
+        renderColumn(col.dataset.status);
