+        // Copy again so edits after restoring never leak back into the snapshot.
+        orderItems = deepCopy(snapshot.items);
+        renderOrder();
+        snapshotStatus.textContent = 'Restored snapshot with ' + itemCountText(orderItems.length) + '.';
+      }
+
+      function clearOrder() {
+        orderItems = [];
+        renderOrder();
+        snapshotStatus.textContent = snapshot
+          ? 'Order cleared. A saved snapshot is still available.'
+          : 'Order cleared.';
+      }
+
+      menuList.addEventListener('click', function (e) {
+        const btn = e.target.closest('.add-to-order');
+        if (btn) addToOrder(btn.dataset.id);
+      });
+      orderList.addEventListener('click', function (e) {
+        const btn = e.target.closest('.remove-item');
+        if (btn) removeFromOrder(btn.dataset.lineId);
+      });
+      saveBtn.addEventListener('click', saveSnapshot);
+      restoreBtn.addEventListener('click', restoreSnapshot);
+      clearBtn.addEventListener('click', clearOrder);
+
+      // ---- Init ----
+      filterState = readStateFromUrl();
+      applyStateToControls(filterState);
+      writeStateToUrl(filterState);
+      renderMenu();
+      renderOrder();
+
+      // Read-only hooks for debugging/integration.
+      window.dailyGrind = Object.freeze({
+        menu: MENU,
+        getFilterState: function () { return Object.assign({}, filterState); },
+        getVisibleItems: function () { return getVisibleItems(filterState); },
+        getOrder: function () { return deepCopy(orderItems); },
+        getSnapshot: function () { return snapshot ? deepCopy(snapshot) : null; }
+      });
+    })();
+  </script>
