+        const group = groupOf(menu);
+        const sub = isSubmenu(menu);
+
+        // aria-expanded and focus entry follow the real open state.
+        menu.addEventListener('toggle', event => {
+          const open = event.newState === 'open';
+          trigger.setAttribute('aria-expanded', String(open));
+          if (!open) { enterOnOpen.delete(menu); return; }
+          if (!supportsAnchor) placeMenu(menu, trigger, sub);
+          if (enterOnOpen.has(menu)) {
+            enterOnOpen.delete(menu);
+            itemsOf(group)[0]?.focus();
+          } else if (!sub && document.activeElement !== trigger) {
+            // Pointer open: pointerdown prevented focus, but arrow keys must still work.
+            focusQuietly(trigger);
+          }
+        });
+
+        // Restore focus before content hides (light dismiss, cascading close).
+        menu.addEventListener('beforetoggle', event => {
+          if (event.newState !== 'closed' || !menu.contains(document.activeElement)) return;
+          const parent = sub ? trigger.closest('.menu') : null;
+          focusQuietly(parent && !isOpen(parent) ? triggerFor(rootOf(menu)) : trigger);
+        });
+
+        // Triggers: pointer presses don't move focus; keyboard activations enter the menu.
+        trigger.addEventListener('pointerdown', event => event.preventDefault());
+        trigger.addEventListener('click', event => {
+          if (event.detail === 0 && !isOpen(menu)) enterOnOpen.add(menu);
+          if (!hasInvokers) {
+            event.preventDefault();
+            if (isOpen(menu)) closeAndRestore(menu, { fromPointer: event.detail !== 0 });
+            else menu.showPopover({ source: trigger });
+          }
+        });
+
+        if (sub) {
+          trigger.addEventListener('pointerleave', event => startBridge(menu, event));
+        } else {
+          trigger.addEventListener('keydown', event => {
+            if (event.key === 'ArrowDown') {
+              event.preventDefault();
+              openAndEnter(trigger);
+            }
+          });
+        }
+
+        group.addEventListener('keydown', event => {
+          if (event.target.closest('[focusgroup]') !== group) return;
+          lastKey = event.key;
+          switch (event.key) {
+            case 'Home':
+            case 'End': {
+              const items = itemsOf(group);
+              event.preventDefault();
+              (event.key === 'Home' ? items[0] : items.at(-1))?.focus();
+              break;
+            }
+            case 'Escape':
+              event.preventDefault();
+              event.stopPropagation();
+              closeAndRestore(menu);
+              break;
+            case 'ArrowLeft':
+              if (!sub) break;
+              event.preventDefault();
+              event.stopPropagation();
+              closeAndRestore(menu);
+              break;
+            case 'ArrowRight':
+              if (!event.target.matches('[commandfor]')) break;
+              event.preventDefault();
+              event.stopPropagation();
+              openAndEnter(event.target);
+              break;
+            case 'Tab': {
+              // Leave the menu system: close everything and continue from the root trigger.
+              const root = rootOf(menu);
+              const rootTrigger = triggerFor(root);
+              if (event.shiftKey) event.preventDefault();
+              rootTrigger.focus({ preventScroll: true });
+              root.hidePopover();
+              break;
+            }
+          }
+        });
+
+        // Hover follows focus.
+        group.addEventListener('pointermove', event => {
+          const item = event.target.closest(ITEM);
+          if (!item || item.closest('[focusgroup]') !== group || item === document.activeElement) return;
+          if (!item.contains(document.elementFromPoint(event.clientX, event.clientY))) return;
+          pointerFocus = true;
+          focusQuietly(item);
+          pointerFocus = false;
+        });
+
+        // Focusing an item closes sibling submenus; focusing a submenu trigger previews its submenu.
+        group.addEventListener('focusin', event => {
+          const item = event.target;
+          if (item.closest('[focusgroup]') !== group) return;
+          clearTimeout(previewTimer);
+          group.querySelectorAll(':scope > .menu').forEach(child => {
+            if (isOpen(child) && triggerFor(child) !== item) child.hidePopover();
+          });
+          if (!item.matches('[commandfor]')) return;
+          const submenu = menuFor(item);
+          if (isOpen(submenu) || submenu.contains(event.relatedTarget) || windowBlurred) return;
+          const show = () => {
+            if (document.activeElement === item && !isOpen(submenu)) submenu.showPopover({ source: item });
+          };
+          if (pointerFocus) previewTimer = setTimeout(show, 180);
+          else show();
+        });
+
+        // Item activation.
+        group.addEventListener('click', event => {
+          const item = event.target.closest(ITEM);
+          if (!item || item.closest('[focusgroup]') !== group || item.matches('[commandfor]')) return;
+          const fromPointer = event.detail !== 0;
+          const viaSpace = !fromPointer && lastKey === ' ';
+          lastKey = null;
+          const role = item.getAttribute('role');
+
+          if (role === 'menuitemcheckbox') {
+            item.setAttribute('aria-checked', String(item.getAttribute('aria-checked') !== 'true'));
+          } else if (role === 'menuitemradio') {
+            item.closest('[role="group"]').querySelectorAll('[role="menuitemradio"]').forEach(radio => {
+              radio.setAttribute('aria-checked', String(radio === item));
+            });
+          }
+
+          if (!item.matches('a[href]')) {
+            item.dispatchEvent(new CustomEvent('menuselect', { bubbles: true, detail: { item } }));
+          }
+
+          // Space on a checkbox keeps the menu open; checkable items linger so the new mark is visible.
+          if (role === 'menuitemcheckbox' && viaSpace) return;
+          if (role === 'menuitemcheckbox' || role === 'menuitemradio') {
+            setTimeout(() => closeRootOf(item, fromPointer), 300);
+          } else {
+            closeRootOf(item, fromPointer);
+          }
+        });
+      }
+
+      // Close every open menu when focus lands outside the menu system.
+      document.addEventListener('focusin', event => {
+        for (const menu of menus) {
+          if (isSubmenu(menu) || !isOpen(menu)) continue;
+          if (!menu.contains(event.target) && triggerFor(menu) !== event.target) menu.hidePopover();
+        }
+      });
+    })();
+  </script>
