+        card.addEventListener('menuselect', (e) => {
+          const { type, item } = e.detail;
+          const key = item.dataset.opt;
+          if (type === 'select' && key) state[key] = item.dataset.value;
+          else if (type === 'toggle' && key) state[key] = e.detail.checked;
+          else if (type === 'action') {
+            switch (e.detail.action) {
+              case 'add': add(); break;
+              case 'favorite': toast(`Saved “${card.dataset.name}: ${summaryOf(state)}” to your favorites`); break;
+              case 'reset':
+                state = defaultsFor(card);
+                syncMenu();
+                toast(`${card.dataset.name} reset to defaults`);
+                break;
+            }
+          }
+          render();
+        });
+
+        card.querySelector('[data-quick-add]').addEventListener('click', add);
+        render();
+      });
+
+      /* ---------- nav menus ---------- */
+      MenuButton.init(document.getElementById('drinks-btn'));
+      MenuButton.init(document.getElementById('account-btn'));
+
+      document.getElementById('account-menu').addEventListener('menuselect', (e) => {
+        const { type, item, checked, value } = e.detail;
+        if (type === 'toggle' && item.dataset.pref === 'emailOffers') {
+          toast(checked ? 'You’ll receive email offers' : 'Email offers turned off');
+        } else if (type === 'toggle' && item.dataset.pref === 'pushReady') {
+          toast(checked ? 'We’ll notify you when your order is ready' : 'Order-ready notifications off');
+        } else if (type === 'select' && item.dataset.pref === 'pickup') {
+          toast(`Default pickup set to ${value}`);
+        }
+      });
