+// Old origin (app.dailygrind.com): point users at the new origin and carry
+// their saved preferences along. Installation/shortcuts migrate via the
+// manifest (Chromium 149+), but localStorage is origin-bound and does not.
+const NEW_ORIGIN = 'https://www.dailygrind.com/';
+const DISMISS_KEY = 'dg:migration-banner-dismissed';
+
+function exportSettings() {
+  const data = {};
+  for (let i = 0; i < localStorage.length; i++) {
+    const key = localStorage.key(i);
+    if (key !== DISMISS_KEY) data[key] = localStorage.getItem(key);
+  }
+  const bytes = new TextEncoder().encode(JSON.stringify(data));
+  return btoa(String.fromCharCode(...bytes));
+}
+
+function migrationUrl() {
+  const url = new URL(NEW_ORIGIN);
+  // Fragment is never sent to the server, so settings stay client-side.
+  url.hash = 'migrate=' + encodeURIComponent(exportSettings());
+  return url.href;
+}
+
+const banner = document.getElementById('migration-banner');
+if (banner && localStorage.getItem(DISMISS_KEY) !== '1') {
+  const link = banner.querySelector('a');
+  link.href = NEW_ORIGIN;
+  // Build the URL at click time so it holds the latest settings.
+  link.addEventListener('click', () => { link.href = migrationUrl(); });
+  banner.querySelector('button').addEventListener('click', () => {
+    localStorage.setItem(DISMISS_KEY, '1');
+    banner.hidden = true;
+  });
+  banner.hidden = false;
+}
