@@ -0,0 +1,19 @@
+// New origin (www.dailygrind.com): import preferences handed over from
+// app.dailygrind.com via the URL fragment, then remove them from the URL.
+const match = location.hash.match(/^#migrate=(.+)$/);
+if (match) {
+  try {
+    const bin = atob(decodeURIComponent(match[1]));
+    const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));
+    const data = JSON.parse(new TextDecoder().decode(bytes));
+    for (const [key, value] of Object.entries(data)) {
+      // Don't overwrite settings the user already changed on the new origin.
+      if (typeof value === 'string' && localStorage.getItem(key) === null) {
+        localStorage.setItem(key, value);
+      }
+    }
+  } catch (err) {
+    console.warn('Settings migration failed:', err);
+  }
+  history.replaceState(null, '', location.pathname + location.search);
+}
