diff --git a/js/app.js b/js/app.js
new file mode 100644
index 0000000..4720756
--- /dev/null
+++ b/js/app.js
@@ -0,0 +1,50 @@
+// Binds the "Your Usual" preferences form to DGSettings.
+(function () {
+  'use strict';
+  var S = window.DGSettings;
+  var form = document.getElementById('prefs-form');
+  var status = document.getElementById('prefs-status');
+  if (!S || !form) return;
+
+  function render() {
+    var prefs = S.get();
+    Object.keys(S.SCHEMA).forEach(function (key) {
+      var field = form.elements[key];
+      if (!field) return;
+      if (field.type === 'checkbox') field.checked = !!prefs[key];
+      else field.value = prefs[key];
+    });
+  }
+
+  function flash(msg) {
+    status.textContent = msg;
+    clearTimeout(flash.t);
+    flash.t = setTimeout(function () { status.textContent = ''; }, 4000);
+  }
+
+  form.addEventListener('change', function (e) {
+    var field = e.target;
+    if (!field.name) return;
+    var update = {};
+    update[field.name] = field.type === 'checkbox' ? field.checked : field.value;
+    flash(S.set(update) ? 'Saved.' : 'Could not save on this device.');
+  });
+
+  document.addEventListener('dg:settings-imported', function () {
+    render();
+    flash('Welcome to our new home — your preferences came with you.');
+  });
+
+  // Keep multiple open windows/tabs in sync.
+  window.addEventListener('storage', function (e) {
+    if (e.key === 'dg:settings') render();
+  });
+
+  render();
+  try {
+    var m = JSON.parse(localStorage.getItem('dg:migration'));
+    if (m && m.imported && Date.now() - m.at < 10000) {
+      flash('Welcome to our new home — your preferences came with you.');
+    }
+  } catch (e) { /* ignore */ }
+})();
diff --git a/js/migration.js b/js/migration.js
new file mode 100644
index 0000000..9aa8c2f
--- /dev/null
+++ b/js/migration.js
@@ -0,0 +1,157 @@
+// Origin migration: carries user preferences from the old origin to the new one.
+//
+// localStorage is partitioned per origin (and third-party iframes get
+// partitioned storage), so the only reliable way to read the old origin's data
+// is a first-party, top-level visit to it. The handoff therefore works by
+// navigation:
+//
+//   NEW  ──(first launch, no prefs)──▶  OLD/migrate-export.html?return=/path
+//   OLD  ──location.replace──────────▶  NEW/path#dg-migrate=<base64url JSON>
+//   NEW  imports, records completion, strips the fragment.
+//
+// The payload rides in the URL fragment, which is never sent to any server.
+// The export page only ever redirects to the hard-coded NEW origin.
+(function () {
+  'use strict';
+
+  var O = window.DG_ORIGINS;
+  var S = window.DGSettings;
+  if (!O || !S) return;
+
+  var STATE_KEY = 'dg:migration';
+  var PARAM = 'dg-migrate';
+
+  function encode(obj) {
+    var bytes = new TextEncoder().encode(JSON.stringify(obj));
+    var bin = '';
+    bytes.forEach(function (b) { bin += String.fromCharCode(b); });
+    return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+  }
+
+  function decode(str) {
+    var b64 = str.replace(/-/g, '+').replace(/_/g, '/');
+    while (b64.length % 4) b64 += '=';
+    var bin = atob(b64);
+    var bytes = new Uint8Array(bin.length);
+    for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
+    return JSON.parse(new TextDecoder().decode(bytes));
+  }
+
+  function getState() {
+    try { return JSON.parse(localStorage.getItem(STATE_KEY)) || {}; } catch (e) { return {}; }
+  }
+
+  function setState(state) {
+    try { localStorage.setItem(STATE_KEY, JSON.stringify(state)); } catch (e) { /* ignore */ }
+  }
+
+  /** Only same-origin absolute paths are accepted as return targets. */
+  function safePath(p) {
+    // Reject protocol-relative ("//host"), backslash and control characters
+    // (browsers strip tabs/newlines, so "/\t/host" would become "//host").
+    if (typeof p !== 'string' || p.charAt(0) !== '/' || /^\/[\/\\]|[\u0000-\u001f\\]/.test(p)) {
+      return O.APP_PATH;
+    }
+    return p.split('#')[0];
+  }
+
+  function currentPath() {
+    return location.pathname + location.search;
+  }
+
+  // ---------------------------------------------------------------- OLD side
+
+  /** Navigate to the new origin, carrying this origin's preferences along. */
+  function handoffToNew(returnPath) {
+    var data = S.exportData();
+    var payload = data ? encode({ v: 1, from: O.OLD, settings: data }) : 'none';
+    location.replace(O.NEW + safePath(returnPath) + '#' + PARAM + '=' + payload);
+  }
+
+  function showMovedBanner() {
+    var bar = document.createElement('div');
+    bar.className = 'moved-banner';
+    bar.setAttribute('role', 'status');
+
+    var text = document.createElement('span');
+    text.textContent = 'The Daily Grind has a new home at ' + O.NEW.replace(/^https?:\/\//, '') + '. ';
+
+    var btn = document.createElement('button');
+    btn.type = 'button';
+    btn.textContent = 'Move my app & preferences';
+    btn.addEventListener('click', function () { handoffToNew(currentPath()); });
+
+    bar.appendChild(text);
+    bar.appendChild(btn);
+    document.body.insertBefore(bar, document.body.firstChild);
+  }
+
+  // ---------------------------------------------------------------- NEW side
+
+  /** Consume a #dg-migrate=… fragment if present. Returns true if handled. */
+  function consumeFragment() {
+    var hash = location.hash.slice(1);
+    if (!hash) return false;
+    var params = new URLSearchParams(hash);
+    if (!params.has(PARAM)) return false;
+
+    var raw = params.get(PARAM);
+    var imported = false;
+    if (raw && raw !== 'none') {
+      try {
+        var msg = decode(raw);
+        if (msg && msg.v === 1 && msg.from === O.OLD) imported = S.importData(msg.settings);
+      } catch (e) { /* malformed payload: ignore, defaults stay */ }
+    }
+    setState({ done: true, at: Date.now(), imported: imported });
+
+    params.delete(PARAM);
+    var rest = params.toString();
+    history.replaceState(history.state, '', currentPath() + (rest ? '#' + rest : ''));
+
+    if (imported) document.dispatchEvent(new CustomEvent('dg:settings-imported'));
+    return true;
+  }
+
+  /**
+   * On first launch at the new origin with no saved preferences, bounce once
+   * through the old origin to collect them. Skipped if the old origin is
+   * unreachable (e.g. decommissioned or offline) so users are never stranded.
+   */
+  function pullFromOld() {
+    var state = getState();
+    if (state.done || state.attempted || S.hasStored() || !navigator.onLine) return;
+
+    var exportUrl = O.OLD + '/migrate-export.html';
+    var controller = 'AbortController' in window ? new AbortController() : null;
+    var timer = setTimeout(function () { if (controller) controller.abort(); }, 3000);
+
+    fetch(exportUrl, { mode: 'no-cors', cache: 'no-store', signal: controller && controller.signal })
+      .then(function () {
+        clearTimeout(timer);
+        // Re-check: user may have saved something while we were probing.
+        if (S.hasStored()) return setState({ done: true, at: Date.now(), imported: false });
+        setState({ attempted: Date.now() }); // never loop, even if the round-trip fails
+        location.replace(exportUrl + '?return=' + encodeURIComponent(currentPath()));
+      })
+      .catch(function () {
+        clearTimeout(timer);
+        setState({ done: true, at: Date.now(), imported: false, unreachable: true });
+      });
+  }
+
+  window.DGMigration = { handoffToNew: handoffToNew, safePath: safePath };
+
+  // The export page drives the handoff itself; don't auto-run anything there.
+  if (/\/migrate-export\.html$/.test(location.pathname)) return;
+
+  if (location.origin === O.OLD) {
+    if (document.readyState === 'loading') {
+      document.addEventListener('DOMContentLoaded', showMovedBanner);
+    } else {
+      showMovedBanner();
+    }
+  } else if (location.origin === O.NEW) {
+    if (!consumeFragment()) pullFromOld();
+  }
+})();
