new file mode 100644
index 0000000..3311cd4
--- /dev/null
+++ b/js/settings.js
@@ -0,0 +1,109 @@
+// User preferences, persisted per-origin in localStorage.
+// Exposed as window.DGSettings so migration.js can import/export them.
+(function () {
+  'use strict';
+
+  var KEY = 'dg:settings';
+  var VERSION = 1;
+
+  // Whitelist of every preference and its allowed values. Anything imported
+  // from another origin is validated against this before it is stored.
+  var SCHEMA = {
+    preferredLocation: ['', 'downtown', 'riverside', 'university', 'airport'],
+    milk: ['whole', 'skim', 'oat', 'almond', 'soy', 'none'],
+    size: ['small', 'medium', 'large'],
+    sweetener: ['none', 'sugar', 'maple', 'honey', 'stevia'],
+    orderReminders: [true, false],
+  };
+
+  var DEFAULTS = {
+    preferredLocation: '',
+    milk: 'whole',
+    size: 'medium',
+    sweetener: 'none',
+    orderReminders: false,
+  };
+
+  function sanitize(input) {
+    var clean = {};
+    if (!input || typeof input !== 'object') return clean;
+    Object.keys(SCHEMA).forEach(function (k) {
+      if (Object.prototype.hasOwnProperty.call(input, k) && SCHEMA[k].indexOf(input[k]) !== -1) {
+        clean[k] = input[k];
+      }
+    });
+    return clean;
+  }
+
+  function readRaw() {
+    try {
+      var parsed = JSON.parse(localStorage.getItem(KEY));
+      return parsed && typeof parsed === 'object' ? parsed : null;
+    } catch (e) {
+      return null;
+    }
+  }
+
+  function write(values, updatedAt) {
+    try {
+      localStorage.setItem(KEY, JSON.stringify({
+        version: VERSION,
+        updatedAt: updatedAt || Date.now(),
+        values: sanitize(values),
+      }));
+      return true;
+    } catch (e) {
+      return false; // storage disabled / full — keep running with defaults
+    }
+  }
+
+  var api = {
+    SCHEMA: SCHEMA,
+    DEFAULTS: DEFAULTS,
+    sanitize: sanitize,
+
+    /** True when the user has saved preferences on this origin. */
+    hasStored: function () {
+      var raw = readRaw();
+      return !!(raw && raw.values && Object.keys(sanitize(raw.values)).length);
+    },
+
+    /** Preferences merged over defaults. */
+    get: function () {
+      var raw = readRaw();
+      var values = raw ? sanitize(raw.values) : {};
+      return Object.assign({}, DEFAULTS, values);
+    },
+
+    set: function (partial) {
+      var raw = readRaw();
+      var current = raw ? sanitize(raw.values) : {};
+      return write(Object.assign(current, sanitize(partial)));
+    },
+
+    /** Snapshot for transfer to another origin. */
+    exportData: function () {
+      var raw = readRaw();
+      if (!raw) return null;
+      var values = sanitize(raw.values);
+      if (!Object.keys(values).length) return null;
+      return { version: VERSION, updatedAt: raw.updatedAt || 0, values: values };
+    },
+
+    /**
+     * Import a snapshot from another origin. Preferences already saved on this
+     * origin win (the user may have configured the new app already); imported
+     * values only fill in what is missing.
+     */
+    importData: function (data) {
+      if (!data || typeof data !== 'object') return false;
+      var incoming = sanitize(data.values);
+      if (!Object.keys(incoming).length) return false;
+      var raw = readRaw();
+      var local = raw ? sanitize(raw.values) : {};
+      return write(Object.assign(incoming, local), raw ? Date.now() : data.updatedAt);
+    },
+  };
+
+  window.DGSettings = api;
+})();
