+<!DOCTYPE html>
+<html lang="en">
+<head>
+  <meta charset="UTF-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1.0">
+  <meta name="robots" content="noindex">
+  <meta name="referrer" content="no-referrer">
+  <title>Moving The Daily Grind…</title>
+  <style>
+    body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; background: #4e342e; color: #fafafa;
+           display: flex; min-height: 100vh; align-items: center; justify-content: center; margin: 0; text-align: center; }
+    a { color: #ffab40; }
+  </style>
+  <script src="/js/origins.js"></script>
+  <script src="/js/settings.js"></script>
+  <script src="/js/migration.js"></script>
+</head>
+<body>
+  <main>
+    <p>Moving your Daily Grind preferences to our new home…</p>
+    <noscript><p><a href="/">Continue</a></p></noscript>
+  </main>
+  <script>
+    // Old-origin export endpoint. Reads this origin's preferences (first-party,
+    // top-level, so storage is not partitioned) and hands them to the NEW
+    // origin only — the destination origin is fixed in js/origins.js and the
+    // ?return parameter is restricted to a same-origin path.
+    (function () {
+      var O = window.DG_ORIGINS, M = window.DGMigration;
+      if (!O || !M) return;
