+#!/usr/bin/env node
+// Generates every origin-dependent artifact from migration.config.json so the
+// old and new origins can never drift out of sync:
+//
+//   manifest.webmanifest          – served/linked on the NEW origin (migrate_from)
+//   legacy.webmanifest            – linked on the OLD origin (migrate_to)
+//   .well-known/web-app-origin-association – new origin vouches for the old app
+//   js/origins.js                 – runtime constants for the client scripts
+//
+// Usage: node scripts/generate-migration.mjs   (or `npm run build:migration`)
+
+import { readFile, writeFile, mkdir } from 'node:fs/promises';
+import { dirname, join } from 'node:path';
+import { fileURLToPath } from 'node:url';
+
+const root = join(dirname(fileURLToPath(import.meta.url)), '..');
+const config = JSON.parse(await readFile(join(root, 'migration.config.json'), 'utf8'));
+
+const normOrigin = (value, name) => {
+  const url = new URL(value);
+  if (url.protocol !== 'https:' && url.hostname !== 'localhost') {
+    throw new Error(`${name} must be https (got ${value})`);
+  }
+  return url.origin;
+};
+
+const oldOrigin = normOrigin(config.oldOrigin, 'oldOrigin');
+const newOrigin = normOrigin(config.newOrigin, 'newOrigin');
+if (oldOrigin === newOrigin) throw new Error('oldOrigin and newOrigin must differ');
+
+const appPath = config.appPath || '/';
+const behavior = config.behavior === 'force' ? 'force' : 'suggest';
+const oldId = new URL(appPath, oldOrigin).href;
+const newId = new URL(appPath, newOrigin).href;
+
+// Everything the OS integrates with (name, icons, shortcuts, display mode)
+// is identical in both manifests so pinned icons, jump-list / dock shortcuts
+// and window behaviour carry over unchanged when the browser migrates the app.
+// Paths are root-relative, so they resolve against whichever origin serves them.
+const shared = {
+  name: 'The Daily Grind',
+  short_name: 'Daily Grind',
+  description: 'Ethically sourced, locally roasted coffee — order ahead and earn rewards.',
+  start_url: appPath,
+  scope: appPath,
+  display: 'standalone',
+  display_override: ['window-controls-overlay', 'standalone'],
+  orientation: 'any',
+  background_color: '#fafafa',
+  theme_color: '#4e342e',
+  lang: 'en',
+  dir: 'ltr',
+  categories: ['food', 'shopping', 'lifestyle'],
+  icons: [
+    { src: '/icons/icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any' },
+    { src: '/icons/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any' },
+    { src: '/icons/icon-maskable-512.png', sizes: '512x512', type: 'image/png', purpose: 'maskable' },
+    { src: '/icons/icon.svg', sizes: 'any', type: 'image/svg+xml', purpose: 'any' },
+  ],
+  shortcuts: [
+    {
+      name: 'Order Now',
+      short_name: 'Order',
+      description: 'Start a new order',
+      url: '/order-online?source=shortcut',
+      icons: [{ src: '/icons/icon-192.png', sizes: '192x192', type: 'image/png' }],
+    },
+    {
+      name: 'Menu',
+      url: '/menu?source=shortcut',
+      icons: [{ src: '/icons/icon-192.png', sizes: '192x192', type: 'image/png' }],
+    },
+    {
+      name: 'Rewards',
+      url: '/rewards?source=shortcut',
+      icons: [{ src: '/icons/icon-192.png', sizes: '192x192', type: 'image/png' }],
+    },
+    {
+      name: 'Find a Location',
+      short_name: 'Locations',
+      url: '/locations?source=shortcut',
+      icons: [{ src: '/icons/icon-192.png', sizes: '192x192', type: 'image/png' }],
+    },
+  ],
+};
+
+// NEW origin: same relative id → identity is "<newOrigin>/". Declares which
+// installed app it replaces. The browser only honours this when the old app's
+// manifest points back here (mutual consent).
+const newManifest = {
+  id: appPath,
+  ...shared,
+  migrate_from: [{ id: oldId, behavior }],
+};
+
+// OLD origin: keeps its original identity and points at the replacement.
+// install_url is the page the browser loads to fetch/validate the new manifest.
+const legacyManifest = {
+  id: appPath,
+  ...shared,
+  migrate_to: { id: newId, install_url: new URL(appPath, newOrigin).href },
+};
+
+// The new origin explicitly associates itself with the old app as well,
+// which browsers use to validate cross-site (non same-site) migrations.
+const association = {
+  [oldId]: { scope: appPath, migrate_to: newId },
+};
+
+const originsJs = `// GENERATED by scripts/generate-migration.mjs — do not edit by hand.
+// Edit migration.config.json and run \`npm run build:migration\` instead.
+window.DG_ORIGINS = Object.freeze({
+  OLD: ${JSON.stringify(oldOrigin)},
+  NEW: ${JSON.stringify(newOrigin)},
+  APP_PATH: ${JSON.stringify(appPath)},
+});
+`;
+
+const out = async (rel, data) => {
+  const file = join(root, rel);
+  await mkdir(dirname(file), { recursive: true });
+  await writeFile(file, typeof data === 'string' ? data : JSON.stringify(data, null, 2) + '\n');
+  console.log('wrote', rel);
+};
+
+await out('manifest.webmanifest', newManifest);
+await out('legacy.webmanifest', legacyManifest);
+await out('.well-known/web-app-origin-association', association);
+await out('js/origins.js', originsJs);
+console.log(`migration: ${oldId} -> ${newId} (${behavior})`);

