+          long: 'Single-origin dark chocolate melted into espresso and steamed milk, topped with Ceylon cinnamon and optional whipped cream.',
+          meta: { Size: '12 / 16 / 20 oz', Caffeine: 'Medium', Milk: 'Whole (alternatives available)', Calories: '290 (16 oz)' }
+        },
+        'chai-latte': {
+          url: '/menu/seasonal',
+          long: 'Assam black tea simmered in-house with fresh ginger, green cardamom, cinnamon, and clove, then balanced with steamed milk and a touch of honey.',
+          meta: { Size: '12 / 16 / 20 oz', Caffeine: 'Low', Milk: 'Whole (alternatives available)', Calories: '220 (16 oz)' }
+        }
+      };
+
+      var reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
+
+      /* ---------------- Carousel ---------------- */
+      var track = document.getElementById('seasonal-track');
+      var slides = Array.prototype.slice.call(track.children);
+      var prevBtn = document.querySelector('[data-carousel-prev]');
+      var nextBtn = document.querySelector('[data-carousel-next]');
+      var dotsWrap = document.querySelector('.carousel-dots');
+
+      function slideStep() {
+        if (slides.length < 2) return track.clientWidth;
+        return slides[1].offsetLeft - slides[0].offsetLeft;
+      }
+
+      function currentIndex() {
+        var step = slideStep() || 1;
+        return Math.min(slides.length - 1, Math.max(0, Math.round(track.scrollLeft / step)));
+      }
+
+      function scrollToIndex(i) {
+        i = Math.max(0, Math.min(slides.length - 1, i));
+        track.scrollTo({
+          left: slides[i].offsetLeft - slides[0].offsetLeft,
+          behavior: reduceMotion.matches ? 'auto' : 'smooth'
+        });
+      }
+
+      var dots = slides.map(function (slide, i) {
+        var dot = document.createElement('button');
+        dot.type = 'button';
+        dot.className = 'carousel-dot';
+        var name = slide.querySelector('h3').textContent;
+        dot.setAttribute('aria-label', 'Show ' + name + ' (' + (i + 1) + ' of ' + slides.length + ')');
+        dot.setAttribute('aria-controls', 'seasonal-track');
+        dot.addEventListener('click', function () { scrollToIndex(i); });
+        dotsWrap.appendChild(dot);
+        return dot;
+      });
+
+      function updateControls() {
+        var max = track.scrollWidth - track.clientWidth - 2;
+        prevBtn.disabled = track.scrollLeft <= 2;
+        nextBtn.disabled = track.scrollLeft >= max;
+        var idx = track.scrollLeft >= max ? slides.length - 1 : currentIndex();
+        dots.forEach(function (d, i) {
+          if (i === idx) d.setAttribute('aria-current', 'true');
+          else d.removeAttribute('aria-current');
+        });
+      }
+
+      prevBtn.addEventListener('click', function () { scrollToIndex(currentIndex() - 1); });
+      nextBtn.addEventListener('click', function () { scrollToIndex(currentIndex() + 1); });
+
+      var scrollTimer;
+      track.addEventListener('scroll', function () {
+        cancelAnimationFrame(scrollTimer);
+        scrollTimer = requestAnimationFrame(updateControls);
+      }, { passive: true });
+      window.addEventListener('resize', updateControls);
+
+      // Keyboard support when the track (or something inside it) is focused
+      track.addEventListener('keydown', function (e) {
+        var handled = true;
+        switch (e.key) {
+          case 'ArrowRight': scrollToIndex(currentIndex() + 1); break;
+          case 'ArrowLeft': scrollToIndex(currentIndex() - 1); break;
+          case 'Home': scrollToIndex(0); break;
+          case 'End': scrollToIndex(slides.length - 1); break;
+          default: handled = false;
+        }
+        if (handled) e.preventDefault();
+      });
+
+      // Keep a focused card fully in view when tabbing through buttons
+      track.addEventListener('focusin', function (e) {
+        var li = e.target.closest('li');
+        if (!li || e.target === track) return;
+        var left = li.offsetLeft - slides[0].offsetLeft;
+        var right = left + li.offsetWidth;
+        if (left < track.scrollLeft || right > track.scrollLeft + track.clientWidth) {
+          scrollToIndex(slides.indexOf(li));
+        }
+      });
+
+      // Mouse drag-to-swipe (touch devices use native swipe scrolling)
+      var drag = null;
+      var suppressClick = false;
+      track.addEventListener('click', function (ev) {
+        if (suppressClick) { ev.stopPropagation(); ev.preventDefault(); suppressClick = false; }
+      }, true);
+      track.addEventListener('pointerdown', function (e) {
+        if (e.pointerType !== 'mouse' || e.button !== 0) return;
+        drag = { x: e.clientX, left: track.scrollLeft, moved: false, id: e.pointerId };
+      });
+      track.addEventListener('pointermove', function (e) {
+        if (!drag || e.pointerId !== drag.id) return;
+        var dx = e.clientX - drag.x;
+        if (!drag.moved && Math.abs(dx) > 5) {
+          drag.moved = true;
+          track.classList.add('is-dragging');
+          track.setPointerCapture(e.pointerId);
+        }
+        if (drag.moved) track.scrollLeft = drag.left - dx;
+      });
+      function endDrag(e) {
+        if (!drag) return;
+        var wasMoved = drag.moved;
+        var startLeft = drag.left;
+        drag = null;
+        track.classList.remove('is-dragging');
+        if (wasMoved) {
+          // Swallow the click that follows a drag so buttons don't fire accidentally
+          suppressClick = true;
+          setTimeout(function () { suppressClick = false; }, 0);
+          var dir = track.scrollLeft > startLeft ? 0.3 : -0.3;
+          scrollToIndex(Math.round(track.scrollLeft / (slideStep() || 1) + dir));
+        }
+      }
+      track.addEventListener('pointerup', endDrag);
+      track.addEventListener('pointercancel', endDrag);
+      track.addEventListener('dragstart', function (e) { e.preventDefault(); });
+
+      updateControls();
+
+      /* ---------------- Detail dialog (expands from trigger) ---------------- */
+      var dialog = document.getElementById('detail-dialog');
+      var dTitle = document.getElementById('detail-title');
+      var dPrice = document.getElementById('detail-price');
+      var dDesc = document.getElementById('detail-description');
+      var dMeta = document.getElementById('detail-meta');
+      var dImg = document.getElementById('detail-image');
+      var dLink = document.getElementById('detail-link');
+      var trigger = null;
+      var anim = null;
+      var closing = false;
+
+      function populate(card) {
+        var key = card.getAttribute('data-drink');
+        var data = DRINKS[key] || {};
+        var img = card.querySelector('img');
+        dTitle.textContent = card.querySelector('h3').textContent;
+        dPrice.textContent = (card.querySelector('.price') || {}).textContent || '';
+        dDesc.textContent = data.long || card.querySelector('p').textContent;
+        dImg.src = img ? img.currentSrc || img.src : '';
+        dImg.alt = img ? img.alt : '';
+        dLink.href = data.url || '/menu';
+        dMeta.innerHTML = '';
+        Object.keys(data.meta || {}).forEach(function (k) {
+          var dt = document.createElement('dt');
+          var dd = document.createElement('dd');
+          dt.textContent = k;
+          dd.textContent = data.meta[k];
+          dMeta.appendChild(dt);
+          dMeta.appendChild(dd);
+        });
+      }
+
+      // FLIP: compute a transform + clip that makes the dialog look like the trigger button
+      function fromButtonKeyframes(btnRect) {
+        var dRect = dialog.getBoundingClientRect();
+        var dx = (btnRect.left + btnRect.width / 2) - (dRect.left + dRect.width / 2);
+        var dy = (btnRect.top + btnRect.height / 2) - (dRect.top + dRect.height / 2);
+        var sx = btnRect.width / dRect.width;
+        var sy = btnRect.height / dRect.height;
+        var radius = 5 / Math.min(sx, sy);
+        return [
+          {
+            transform: 'translate(' + dx + 'px,' + dy + 'px) scale(' + sx + ',' + sy + ')',
+            borderRadius: radius + 'px',
+            backgroundColor: getComputedStyle(trigger).backgroundColor,
+            opacity: 0.6
+          },
+          {
+            transform: 'translate(0,0) scale(1,1)',
+            borderRadius: '12px',
+            backgroundColor: '#ffffff',
+            opacity: 1
+          }
+        ];
+      }
+
+      function openDetails(btn) {
+        var card = btn.closest('.card');
+        if (!card) return;
+        trigger = btn;
+        closing = false;
+        if (anim) anim.cancel();
+        populate(card);
+
+        dialog.showModal();
+        dialog.querySelector('.detail-inner').scrollTop = 0;
+        requestAnimationFrame(function () { dialog.classList.add('is-open'); });
+
+        if (reduceMotion.matches || !dialog.animate) return;
+
+        dialog.classList.add('is-animating');
+        anim = dialog.animate(fromButtonKeyframes(btn.getBoundingClientRect()), {
+          duration: 420,
+          easing: 'cubic-bezier(0.22, 1, 0.36, 1)'
+        });
+        anim.onfinish = anim.oncancel = function () {
+          dialog.classList.remove('is-animating');
+          anim = null;
+        };
+      }
+
+      function finishClose() {
+        closing = false;
+        dialog.classList.remove('is-animating');
+        dialog.close();
+      }
+
+      function closeDetails() {
+        if (!dialog.open || closing) return;
+        closing = true;
+        dialog.classList.remove('is-open');
+        if (anim) anim.cancel();
+
+        if (reduceMotion.matches || !dialog.animate || !trigger || !trigger.isConnected) {
+          finishClose();
+          return;
+        }
+
+        dialog.classList.add('is-animating');
+        var frames = fromButtonKeyframes(trigger.getBoundingClientRect()).reverse();
+        anim = dialog.animate(frames, {
+          duration: 300,
+          easing: 'cubic-bezier(0.4, 0, 0.2, 1)',
+          fill: 'forwards'
+        });
+        anim.onfinish = function () {
+          anim.cancel();
+          anim = null;
+          finishClose();
+        };
+      }
+
+      track.addEventListener('click', function (e) {
+        var btn = e.target.closest('[data-details]');
+        if (btn) openDetails(btn);
+      });
+
+      dialog.querySelector('[data-close]').addEventListener('click', closeDetails);
+
+      // Escape: animate closed instead of the abrupt native close
+      dialog.addEventListener('cancel', function (e) {
+        e.preventDefault();
+        closeDetails();
+      });
+
+      // Click on backdrop closes
+      dialog.addEventListener('click', function (e) {
+        if (e.target !== dialog) return;
+        var r = dialog.getBoundingClientRect();
+        var inside = e.clientX >= r.left && e.clientX <= r.right && e.clientY >= r.top && e.clientY <= r.bottom;
+        if (!inside) closeDetails();
+      });
+
+      // Return focus to the button that opened the dialog
+      dialog.addEventListener('close', function () {
+        dialog.classList.remove('is-open');
+        if (trigger && trigger.isConnected) trigger.focus();
+      });
+    })();
+  </script>
