--- /dev/null
+++ b/account/api.js
@@ -0,0 +1,190 @@
+// Account API client.
+//
+// Talks to the account backend:
+//   GET    /api/user                            -> { name, displayName, rpId, userId }
+//   PUT    /api/user                            -> { name, displayName, rpId, userId }
+//   GET    /api/credentials                     -> { rpId, userId, credentials: StoredPasskeyCredential[] }
+//   PUT    /api/credential/:id   { name }       -> StoredPasskeyCredential
+//   DELETE /api/credential/:id                  -> { success: true }
+//   POST   /api/passkeys/registration-options   -> PublicKeyCredentialCreationOptionsJSON
+//   POST   /api/passkeys/registration           -> StoredPasskeyCredential
+//
+// `userId` and every credential `id` are unpadded Base64URL strings, and `rpId` is
+// the server's RP ID (the `rp.id` used at registration).
+//
+// The site is currently deployed as static files with no backend. When the API
+// doesn't answer with JSON, the client switches to a demo store in localStorage
+// so the page still works. Demo responses have `demo: true` and no `rpId`, so
+// the page never sends Signal API calls for fake credentials.
+
+export class ApiError extends Error {
+  constructor(message, status) {
+    super(message);
+    this.name = 'ApiError';
+    this.status = status;
+  }
+}
+
+let mode = null; // 'server' | 'demo'
+
+export function isDemo() {
+  return mode === 'demo';
+}
+
+async function request(method, path, body) {
+  if (mode !== 'demo') {
+    let res;
+    try {
+      res = await fetch(path, {
+        method,
+        credentials: 'same-origin',
+        headers: {
+          Accept: 'application/json',
+          ...(body !== undefined && { 'Content-Type': 'application/json' }),
+        },
+        body: body !== undefined ? JSON.stringify(body) : undefined,
+      });
+    } catch (err) {
+      if (mode === 'server') throw new ApiError('Network error. Check your connection and try again.', 0);
+      res = null;
+    }
+
+    if (res?.status === 401) {
+      location.assign(`/login?next=${encodeURIComponent(location.pathname)}`);
+      throw new ApiError('Your session has expired. Please sign in again.', 401);
+    }
+
+    if (res && res.headers.get('content-type')?.includes('application/json')) {
+      mode = 'server';
+      const data = await res.json();
+      if (!res.ok) throw new ApiError(data?.error || `Request failed (${res.status}).`, res.status);
+      return data;
+    }
+
+    if (mode === 'server') {
+      throw new ApiError(`Unexpected response from server (${res?.status ?? 'network'}).`, res?.status ?? 0);
+    }
+    mode = 'demo';
+  }
+  return demoRequest(method, path, body);
+}
+
+export const getUser = () => request('GET', '/api/user');
+export const updateUser = (details) => request('PUT', '/api/user', details);
+export const listCredentials = () => request('GET', '/api/credentials');
+export const renameCredential = (id, name) =>
+  request('PUT', `/api/credential/${encodeURIComponent(id)}`, { name });
+export const deleteCredential = (id) => request('DELETE', `/api/credential/${encodeURIComponent(id)}`);
+export const getRegistrationOptions = () => request('POST', '/api/passkeys/registration-options', {});
+export const verifyRegistration = (credentialJSON) =>
+  request('POST', '/api/passkeys/registration', credentialJSON);
+
+// ---------------------------------------------------------------------------
+// Demo store (static hosting only)
+// ---------------------------------------------------------------------------
+
+const DEMO_KEY = 'daily-grind:account-demo';
+const DAY = 24 * 60 * 60 * 1000;
+
+function seedDemo() {
+  const now = Date.now();
+  return {
+    user: {
+      name: 'alex.barista@example.com',
+      displayName: 'Alex Rivera',
+      passkeyUserId: 'ZGctdXNlci0xMDQy', // base64url("dg-user-1042")
+    },
+    credentials: [
+      {
+        id: 'ZGctY3JlZC1ncG0tMDE', // base64url("dg-cred-gpm-01")
+        aaguid: 'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4',
+        name: 'Google Password Manager',
+        credentialDeviceType: 'multiDevice',
+        credentialBackedUp: true,
+        registeredAt: now - 140 * DAY,
+        lastUsedAt: now - 2 * 60 * 60 * 1000,
+      },
+      {
+        id: 'ZGctY3JlZC1pY2xvdWQtMDI', // base64url("dg-cred-icloud-02")
+        aaguid: 'fbfc3007-154e-4ecc-8c0b-6e020557d7bd',
+        name: 'iCloud Keychain',
+        credentialDeviceType: 'multiDevice',
+        credentialBackedUp: true,
+        registeredAt: now - 61 * DAY,
+        lastUsedAt: now - 9 * DAY,
+      },
+      {
+        id: 'ZGctY3JlZC15dWJpLTAz', // base64url("dg-cred-yubi-03")
+        aaguid: 'cb69481e-8ff7-4039-93ec-0a2729a154a8',
+        name: 'Security key',
+        credentialDeviceType: 'singleDevice',
+        credentialBackedUp: false,
+        registeredAt: now - 300 * DAY,
+      },
+    ],
+  };
+}
+
+function loadDemo() {
+  try {
+    const stored = JSON.parse(localStorage.getItem(DEMO_KEY));
+    if (stored?.user && Array.isArray(stored.credentials)) return stored;
+  } catch {
+    /* fall through to seed */
+  }
+  const seeded = seedDemo();
+  saveDemo(seeded);
+  return seeded;
+}
+
+function saveDemo(state) {
+  try {
+    localStorage.setItem(DEMO_KEY, JSON.stringify(state));
+  } catch {
+    /* storage unavailable; changes last until reload */
+  }
+}
+
+function publicUser(user) {
+  return { name: user.name, displayName: user.displayName, rpId: null, userId: user.passkeyUserId, demo: true };
+}
+
+async function demoRequest(method, path, body) {
+  const state = loadDemo();
+  const credMatch = path.match(/^\/api\/credential\/([^/]+)$/);
+
+  if (path === '/api/user' && method === 'GET') return publicUser(state.user);
+
+  if (path === '/api/user' && method === 'PUT') {
+    state.user.displayName = String(body.displayName ?? state.user.displayName).trim();
+    saveDemo(state);
+    return publicUser(state.user);
+  }
+
+  if (path === '/api/credentials' && method === 'GET') {
+    return { rpId: null, userId: state.user.passkeyUserId, credentials: state.credentials, demo: true };
+  }
+
+  if (credMatch) {
+    const id = decodeURIComponent(credMatch[1]);
+    const index = state.credentials.findIndex((c) => c.id === id);
+    if (index === -1) throw new ApiError('Credential not found.', 404);
+
+    if (method === 'PUT') {
+      state.credentials[index].name = String(body.name).trim();
+      saveDemo(state);
+      return state.credentials[index];
+    }
+    if (method === 'DELETE') {
+      state.credentials.splice(index, 1);
+      saveDemo(state);
+      return { success: true };
+    }
+  }
+
+  if (path.startsWith('/api/passkeys/')) {
+    throw new ApiError('Creating passkeys needs the account server.', 501);
+  }
+
+  throw new ApiError('Not found.', 404);
+}
