+++ b/account/passkeys.js
@@ -0,0 +1,487 @@
+import * as api from './api.js';
+
+// ---------------------------------------------------------------------------
+// Progressive-enhancement polyfills (loaded only when native support is missing)
+// ---------------------------------------------------------------------------
+
+async function loadPolyfills() {
+  const tasks = [];
+
+  if (!('commandForElement' in HTMLButtonElement.prototype)) {
+    tasks.push(
+      import('https://esm.sh/invokers-polyfill@1.0.4').catch((err) => {
+        console.warn('Invoker commands polyfill failed to load; using click fallback.', err);
+        installCommandFallback();
+      }),
+    );
+  }
+
+  if (
+    window.PublicKeyCredential &&
+    (!PublicKeyCredential.getClientCapabilities || !PublicKeyCredential.parseCreationOptionsFromJSON)
+  ) {
+    tasks.push(
+      import('https://esm.sh/webauthn-polyfills@0.1.7').catch((err) =>
+        console.warn('WebAuthn polyfills failed to load.', err),
+      ),
+    );
+  }
+
+  await Promise.all(tasks);
+}
+
+// Minimal stand-in for `command="show-modal"` if the polyfill can't be fetched.
+function installCommandFallback() {
+  document.addEventListener('click', (event) => {
+    if (event.defaultPrevented) return;
+    const button = event.target.closest?.('button[commandfor][command]');
+    if (!button) return;
+    const target = document.getElementById(button.getAttribute('commandfor'));
+    const command = button.getAttribute('command');
+    if (!target) return;
+    const commandEvent = new Event('command', { cancelable: true });
+    Object.assign(commandEvent, { command, source: button });
+    target.dispatchEvent(commandEvent);
+    if (!commandEvent.defaultPrevented && command === 'show-modal' && !target.open) target.showModal();
+  });
+}
+
+// Light dismiss for browsers without <dialog closedby> (e.g. Safari). Esc already works everywhere.
+if (!('closedBy' in HTMLDialogElement.prototype)) {
+  const outside = (e, dialog) => {
+    const r = dialog.getBoundingClientRect();
+    return e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom;
+  };
+  for (const dialog of document.querySelectorAll('dialog[closedby="any"]')) {
+    let pressedOutside = false;
+    dialog.addEventListener('pointerdown', (e) => (pressedOutside = outside(e, dialog)));
+    // Press and release must both be outside, so a text-selection drag ending on the backdrop doesn't close it.
+    dialog.addEventListener('pointerup', (e) => {
+      if (pressedOutside && outside(e, dialog)) dialog.close();
+    });
+  }
+}
+
+// ---------------------------------------------------------------------------
+// Signal API: keep the browser / password manager in sync with the server
+// ---------------------------------------------------------------------------
+
+// Valid unpadded Base64URL: non-empty, [A-Za-z0-9_-] only, no '=' padding, length % 4 !== 1
+function isValidBase64Url(value) {
+  return typeof value === 'string' && value.length > 0 && value.length % 4 !== 1 && /^[A-Za-z0-9_-]+$/.test(value);
+}
+
+async function syncAcceptedCredentials({ rpId, userId, credentials, demo }) {
+  // Demo data isn't real: never tell the authenticator to hide passkeys based on it.
+  if (demo) return;
+  if (!window.PublicKeyCredential || !PublicKeyCredential.signalAllAcceptedCredentials) return;
+
+  const allAcceptedCredentialIds = credentials.map((c) => c.id);
+  if (!rpId || !isValidBase64Url(userId) || !allAcceptedCredentialIds.every(isValidBase64Url)) {
+    console.warn('signalAllAcceptedCredentials skipped: server rpId and Base64URL userId/credential IDs are required.');
+    return;
+  }
+
+  try {
+    // rpId always comes from the server, never from location.hostname.
+    await PublicKeyCredential.signalAllAcceptedCredentials({ rpId, userId, allAcceptedCredentialIds });
+  } catch (err) {
+    console.warn('signalAllAcceptedCredentials sync warning:', err);
+  }
+}
+
+async function syncCurrentUserDetails({ rpId, userId, name, displayName, demo }) {
+  if (demo) return;
+  if (!window.PublicKeyCredential || !PublicKeyCredential.signalCurrentUserDetails) return;
+  if (!rpId || !isValidBase64Url(userId)) {
+    console.warn('signalCurrentUserDetails skipped: server rpId and Base64URL userId are required.');
+    return;
+  }
+  try {
+    await PublicKeyCredential.signalCurrentUserDetails({ rpId, userId, name, displayName });
+  } catch (err) {
+    console.warn('signalCurrentUserDetails sync warning:', err);
+  }
+}
+
+async function signalUnknownCredential(rpId, credentialId) {
+  if (!window.PublicKeyCredential || !PublicKeyCredential.signalUnknownCredential) return;
+  if (!rpId || !isValidBase64Url(credentialId)) return;
+  try {
+    await PublicKeyCredential.signalUnknownCredential({ rpId, credentialId });
+  } catch (err) {
+    console.warn('signalUnknownCredential sync warning:', err);
+  }
+}
+
+// ---------------------------------------------------------------------------
+// Rendering
+// ---------------------------------------------------------------------------
+
+const $ = (id) => document.getElementById(id);
+const list = $('passkey-list');
+const template = $('passkey-row-template');
+const statusEl = $('passkey-status');
+
+const ZERO_AAGUID = '00000000-0000-0000-0000-000000000000';
+// Names for common providers, used when the server didn't store one.
+// The server should resolve names and icons from the community AAGUID registry
+// (passkeydeveloper/passkey-authenticator-aaguids) when a passkey is registered.
+const KNOWN_PROVIDERS = {
+  'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4': 'Google Password Manager',
+  'fbfc3007-154e-4ecc-8c0b-6e020557d7bd': 'iCloud Keychain',
+  'bada5566-a7aa-401f-bd96-45619a55120d': '1Password',
+  'd548826e-79b4-db40-a3d8-11116f7e8349': 'Bitwarden',
+  '08987058-cadc-4b81-b6e1-30de50dcbe96': 'Windows Hello',
+  '9ddd1817-af5a-4672-a2b9-3e3dd95000a9': 'Windows Hello',
+  'cb69481e-8ff7-4039-93ec-0a2729a154a8': 'YubiKey 5 Series',
+};
+
+const GENERIC_ICON =
+  'data:image/svg+xml,' +
+  encodeURIComponent(
+    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="#4e342e" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="8" cy="15" r="4"/><path d="m10.85 12.15 8.65-8.65M17 6l3 3M14 9l2 2"/></svg>',
+  );
+
+const dateFormat = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium' });
+const dateTimeFormat = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' });
+const relativeFormat = new Intl.RelativeTimeFormat(undefined, { numeric: 'auto' });
+
+function formatRelative(epochMs) {
+  const diffSeconds = Math.round((epochMs - Date.now()) / 1000);
+  const units = [
+    ['year', 31536000],
+    ['month', 2592000],
+    ['week', 604800],
+    ['day', 86400],
+    ['hour', 3600],
+    ['minute', 60],
+  ];
+  for (const [unit, seconds] of units) {
+    if (Math.abs(diffSeconds) >= seconds) return relativeFormat.format(Math.round(diffSeconds / seconds), unit);
+  }
+  return 'just now';
+}
+
+function providerLabel(cred) {
+  if (cred.name) return cred.name;
+  if (cred.aaguid && cred.aaguid !== ZERO_AAGUID && KNOWN_PROVIDERS[cred.aaguid]) return KNOWN_PROVIDERS[cred.aaguid];
+  return 'Unknown passkey provider';
+}
+
+function safeIcon(src) {
+  return typeof src === 'string' && /^(data:image\/|https:\/\/)/.test(src) ? src : GENERIC_ICON;
+}
+
+let state = { rpId: null, userId: null, credentials: [], demo: false };
+let user = null;
+
+function renderCredentials() {
+  list.replaceChildren();
+  list.setAttribute('aria-busy', 'false');
+
+  if (state.credentials.length === 0) {
+    const empty = document.createElement('li');
+    empty.className = 'passkey-placeholder';
+    empty.textContent = "No passkeys yet. Create one to sign in faster, without a password.";
+    list.append(empty);
+    return;
+  }
+
+  const sorted = [...state.credentials].sort(
+    (a, b) => (b.lastUsedAt ?? b.registeredAt ?? 0) - (a.lastUsedAt ?? a.registeredAt ?? 0),
+  );
+
+  for (const cred of sorted) {
+    const row = template.content.firstElementChild.cloneNode(true);
+    const label = providerLabel(cred);
+    row.dataset.id = cred.id;
+
+    const icon = row.querySelector('.passkey-icon');
+    icon.src = safeIcon(cred.providerIcon);
+
+    row.querySelector('.passkey-name').textContent = label;
+
+    const created = row.querySelector('.passkey-created');
+    if (cred.registeredAt) {
+      created.dateTime = new Date(cred.registeredAt).toISOString();
+      created.textContent = dateFormat.format(cred.registeredAt);
+    } else {
+      created.parentElement.remove();
+    }
+
+    const lastUsed = row.querySelector('.passkey-last-used');
+    if (cred.lastUsedAt) {
+      const time = document.createElement('time');
+      time.dateTime = new Date(cred.lastUsedAt).toISOString();
+      time.title = dateTimeFormat.format(cred.lastUsedAt);
+      time.textContent = formatRelative(cred.lastUsedAt);
+      lastUsed.append('Last used ', time);
+    } else {
+      lastUsed.textContent = 'Never used';
+    }
+
+    row.querySelector('.passkey-synced').hidden = !(cred.credentialBackedUp || cred.credentialDeviceType === 'multiDevice');
+
+    // Give each action button a unique accessible name: "Rename Google Password Manager".
+    for (const button of row.querySelectorAll('.passkey-actions button')) {
+      button.setAttribute('aria-label', `${button.textContent.trim()} ${label}`);
+    }
+
+    list.append(row);
+  }
+}
+
+function renderUser() {
+  if (!user) return;
+  $('profile-display-name').textContent = user.displayName || '—';
+  $('profile-name').textContent = user.name || '—';
+}
+
+let statusTimer;
+function announce(message, tone = 'success') {
+  clearTimeout(statusTimer);
+  statusEl.dataset.tone = tone;
+  statusEl.textContent = message;
+  if (tone === 'success') statusTimer = setTimeout(() => (statusEl.textContent = ''), 6000);
+}
+
+function errorMessage(err, fallback) {
+  return err instanceof api.ApiError && err.message ? err.message : fallback;
+}
+
+async function refreshCredentials() {
+  list.setAttribute('aria-busy', 'true');
+  const data = await api.listCredentials();
+  state = { rpId: data.rpId, userId: data.userId, credentials: data.credentials ?? [], demo: Boolean(data.demo) };
+  renderCredentials();
+  $('demo-notice').hidden = !state.demo;
+  return state;
+}
+
+function findCredential(id) {
+  return state.credentials.find((c) => c.id === id);
+}
+
+// ---------------------------------------------------------------------------
+// Rename
+// ---------------------------------------------------------------------------
+
+const renameDialog = $('rename-dialog');
+const renameInput = $('rename-input');
+let renameTargetId = null;
+
+renameDialog.addEventListener('command', (event) => {
+  const id = event.source?.closest('.passkey')?.dataset.id;
+  const cred = id && findCredential(id);
+  if (!cred) {
+    event.preventDefault();
+    return;
+  }
+  renameTargetId = id;
+  renameInput.value = providerLabel(cred);
+});
+
+renameDialog.addEventListener('close', async () => {
+  const action = renameDialog.returnValue;
+  renameDialog.returnValue = '';
+  const id = renameTargetId;
+  renameTargetId = null;
+  if (action !== 'save' || !id) return;
+
+  const cred = findCredential(id);
+  const name = renameInput.value.trim();
+  if (!cred || !name || name === providerLabel(cred)) return;
+
+  try {
+    // A passkey nickname is a server-side label only; it doesn't change anything in the authenticator.
+    await api.renameCredential(id, name);
+    await refreshCredentials();
+    announce(`Passkey renamed to "${name}".`);
+  } catch (err) {
+    announce(errorMessage(err, "We couldn't rename that passkey. Please try again."), 'error');
+    list.setAttribute('aria-busy', 'false');
+  }
+});
+
+// ---------------------------------------------------------------------------
+// Delete
+// ---------------------------------------------------------------------------
+
+const deleteDialog = $('delete-dialog');
+let deleteTargetId = null;
+
+deleteDialog.addEventListener('command', (event) => {
+  const id = event.source?.closest('.passkey')?.dataset.id;
+  const cred = id && findCredential(id);
+  if (!cred) {
+    event.preventDefault();
+    return;
+  }
+  deleteTargetId = id;
+  $('delete-name').textContent = providerLabel(cred);
+  $('delete-last-warning').hidden = state.credentials.length > 1;
+});
+
+deleteDialog.addEventListener('close', async () => {
+  const action = deleteDialog.returnValue;
+  deleteDialog.returnValue = '';
+  const id = deleteTargetId;
+  deleteTargetId = null;
+  if (action !== 'delete' || !id) return;
+
+  const label = providerLabel(findCredential(id) ?? {});
+  list.setAttribute('aria-busy', 'true');
+  try {
+    await api.deleteCredential(id);
+  } catch (err) {
+    list.setAttribute('aria-busy', 'false');
+    announce(errorMessage(err, "We couldn't delete that passkey. Please try again."), 'error');
+    return;
+  }
+
+  try {
+    const latest = await refreshCredentials();
+    announce(`${label} was deleted.`);
+    // Tell the passkey provider which credentials are still valid so it can hide the deleted one.
+    await syncAcceptedCredentials(latest);
+  } catch (err) {
+    list.setAttribute('aria-busy', 'false');
+    announce(`${label} was deleted, but we couldn't refresh the list. Reload the page to see it.`, 'error');
+  }
+});
+
+// ---------------------------------------------------------------------------
+// Profile display name (synced to the passkey provider)
+// ---------------------------------------------------------------------------
+
+const profileDialog = $('profile-dialog');
+const displayNameInput = $('display-name-input');
+
+profileDialog.addEventListener('command', () => {
+  displayNameInput.value = user?.displayName ?? '';
+});
+
+profileDialog.addEventListener('close', async () => {
+  const action = profileDialog.returnValue;
+  profileDialog.returnValue = '';
+  if (action !== 'save' || !user) return;
+
+  const displayName = displayNameInput.value.trim();
+  if (!displayName || displayName === user.displayName) return;
+
+  try {
+    const updated = await api.updateUser({ name: user.name, displayName });
+    user = updated;
+    renderUser();
+    announce('Display name updated.');
+    await syncCurrentUserDetails({
+      rpId: updated.rpId,
+      userId: updated.userId,
+      name: updated.name,
+      displayName: updated.displayName,
+      demo: updated.demo,
+    });
+  } catch (err) {
+    announce(errorMessage(err, "We couldn't update your display name. Please try again."), 'error');
+  }
+});
+
+// ---------------------------------------------------------------------------
+// Create passkey (management flow: platform authenticators and security keys)
+// ---------------------------------------------------------------------------
+
+const createButton = $('create-passkey');
+
+async function isPasskeySupported() {
+  if (!window.PublicKeyCredential || !PublicKeyCredential.getClientCapabilities) return false;
+  try {
+    const capabilities = await PublicKeyCredential.getClientCapabilities();
+    return Boolean(capabilities.passkeyPlatformAuthenticator);
+  } catch {
+    return false;
+  }
+}
+
+async function createPasskey() {
+  if (createButton.getAttribute('aria-disabled') === 'true') return;
+  createButton.setAttribute('aria-disabled', 'true');
+
+  try {
+    let publicKey;
+    try {
+      // Options omit authenticatorAttachment so security keys are allowed too.
+      publicKey = PublicKeyCredential.parseCreationOptionsFromJSON(await api.getRegistrationOptions());
+    } catch (err) {
+      announce(errorMessage(err, "We couldn't start passkey setup. Please try again."), 'error');
+      return;
+    }
+
+    let credential;
+    try {
+      credential = await navigator.credentials.create({ publicKey });
+    } catch (err) {
+      if (err.name === 'InvalidStateError') {
+        announce('You already have a passkey for this account in that password manager or device.', 'error');
+      } else if (err.name === 'SecurityError') {
+        announce("Passkeys aren't available on this connection. Please contact support.", 'error');
+      } else if (err.name !== 'NotAllowedError' && err.name !== 'AbortError') {
+        announce("We couldn't create a passkey. Please try again.", 'error');
+      }
+      // NotAllowedError / AbortError: the user cancelled. Nothing to report.
+      return;
+    }
+
+    const encoded = credential.toJSON();
+    try {
+      await api.verifyRegistration(encoded);
+    } catch (err) {
+      // The server rejected it, so the new passkey is orphaned. Ask the provider to remove it.
+      await signalUnknownCredential(publicKey.rp.id, encoded.id);
+      announce(errorMessage(err, "We couldn't save your new passkey. Please try again."), 'error');
+      return;
+    }
+
+    await refreshCredentials();
+    announce('Passkey created. You can now use it to sign in.');
+  } finally {
+    createButton.removeAttribute('aria-disabled');
+  }
+}
+
+createButton.addEventListener('click', createPasskey);
+
+// ---------------------------------------------------------------------------
+// Init
+// ---------------------------------------------------------------------------
+
+async function init() {
+  const polyfills = loadPolyfills();
+
+  try {
+    // Load the list first: the first response decides between server and demo mode.
+    await refreshCredentials();
+    user = await api.getUser();
+    renderUser();
+  } catch (err) {
+    list.setAttribute('aria-busy', 'false');
+    list.replaceChildren();
+    announce(errorMessage(err, "We couldn't load your account. Please refresh the page."), 'error');
+    return;
+  }
+
+  // Page-load sync: hide any passkeys in the user's password manager that the server no longer accepts.
+  syncAcceptedCredentials(state);
+
+  await polyfills;
+  if (state.demo) {
+    // Real WebAuthn registration needs the server to issue a challenge and verify the result.
+    createButton.hidden = true;
+  } else if (await isPasskeySupported()) {
+    createButton.hidden = false;
+  } else {
+    $('passkey-unsupported').hidden = false;
+  }
+}
+
+init();
