diff --git a/assets/passkeys.js b/assets/passkeys.js
new file mode 100644
index 0000000..42ecbb9
--- /dev/null
+++ b/assets/passkeys.js
@@ -0,0 +1,482 @@
+/**
+ * Passkey management for My Account → Sign-in & Security.
+ *
+ * Expected backend contract (session cookie auth, JSON):
+ *
+ *   GET    /api/account/passkeys
+ *     200 → {
+ *       rpId: "dailygrind.example",             // optional, defaults to location.hostname
+ *       user: { id, name, displayName },         // id = base64url WebAuthn user handle
+ *       passkeys: [{
+ *         id,                                    // base64url credential ID
+ *         name,                                  // user-facing label
+ *         createdAt, lastUsedAt,                 // ISO-8601 strings (lastUsedAt may be null)
+ *         backedUp,                              // boolean: synced passkey (BS flag)
+ *         provider: { name, icon }               // optional, from AAGUID lookup
+ *       }]
+ *     }
+ *   PATCH  /api/account/passkeys/:id   body { name }  → 200 updated passkey (or 204)
+ *   DELETE /api/account/passkeys/:id                  → 204
+ *
+ * 401 responses redirect to the login page. Mutating requests send the CSRF
+ * token from <meta name="csrf-token">.
+ *
+ * Authenticator sync uses the WebAuthn Signals API: after loading and after any
+ * deletion we call PublicKeyCredential.signalAllAcceptedCredentials() with the
+ * complete list of credential IDs the server still accepts, so the browser /
+ * password manager hides or removes passkeys that were deleted here. We also
+ * signal the current user's name/displayName so stored passkeys show
+ * up-to-date account details.
+ *
+ * Append ?demo to the URL to try the UI with local mock data (no network calls,
+ * and no signals are ever sent to the authenticator in demo mode).
+ */
+
+const API_BASE = '/api/account/passkeys';
+const NAME_MAX = 64;
+const DEMO = new URLSearchParams(location.search).has('demo');
+
+const $ = (id) => document.getElementById(id);
+const els = {
+  status: $('passkey-status'),
+  loading: $('passkey-loading'),
+  error: $('passkey-error'),
+  retry: $('passkey-retry'),
+  empty: $('passkey-empty'),
+  list: $('passkey-list'),
+  syncNote: $('sync-note'),
+  template: $('passkey-item-template'),
+  dialog: $('delete-dialog'),
+  dialogName: $('delete-dialog-name'),
+  dialogLast: $('delete-dialog-last'),
+};
+
+const state = {
+  rpId: location.hostname,
+  user: null,
+  passkeys: [],
+};
+
+/* ------------------------------------------------------------------ */
+/* API                                                                 */
+/* ------------------------------------------------------------------ */
+
+class ApiError extends Error {
+  constructor(message, status) {
+    super(message);
+    this.status = status;
+  }
+}
+
+function csrfToken() {
+  return document.querySelector('meta[name="csrf-token"]')?.content || '';
+}
+
+async function request(path, { method = 'GET', body } = {}) {
+  const headers = { Accept: 'application/json' };
+  if (method !== 'GET') headers['X-CSRF-Token'] = csrfToken();
+  if (body !== undefined) headers['Content-Type'] = 'application/json';
+
+  const res = await fetch(API_BASE + path, {
+    method,
+    headers,
+    credentials: 'same-origin',
+    body: body === undefined ? undefined : JSON.stringify(body),
+  });
+
+  if (res.status === 401) {
+    location.assign('/login?next=' + encodeURIComponent(location.pathname + location.hash));
+    throw new ApiError('Your session has expired. Please sign in again.', 401);
+  }
+
+  let data = null;
+  if (res.status !== 204) {
+    try {
+      data = await res.json();
+    } catch {
+      data = null;
+    }
+  }
+  if (!res.ok) {
+    throw new ApiError(data?.message || data?.error || `Request failed (${res.status})`, res.status);
+  }
+  return data;
+}
+
+const api = DEMO ? createDemoApi() : {
+  list: () => request(''),
+  rename: (id, name) => request('/' + encodeURIComponent(id), { method: 'PATCH', body: { name } }),
+  remove: (id) => request('/' + encodeURIComponent(id), { method: 'DELETE' }),
+};
+
+/* ------------------------------------------------------------------ */
+/* Authenticator sync (WebAuthn Signals API)                           */
+/* ------------------------------------------------------------------ */
+
+const PKC = window.PublicKeyCredential;
+const signals = {
+  allAccepted: !DEMO && typeof PKC?.signalAllAcceptedCredentials === 'function',
+  unknown: !DEMO && typeof PKC?.signalUnknownCredential === 'function',
+  userDetails: !DEMO && typeof PKC?.signalCurrentUserDetails === 'function',
+};
+
+async function safeSignal(fn) {
+  try {
+    await fn();
+    return true;
+  } catch (err) {
+    // Signals are best-effort; never block the UI on them.
+    console.warn('Passkey signal failed:', err);
+    return false;
+  }
+}
+
+/**
+ * Tell the authenticator which credentials are still valid for this user.
+ * Must be passed the COMPLETE list — any credential for this rpId/user that
+ * isn't listed may be removed or hidden by the password manager.
+ */
+async function syncAcceptedCredentials({ deletedId } = {}) {
+  if (!state.user?.id) return false;
+  if (signals.allAccepted) {
+    return safeSignal(() => PKC.signalAllAcceptedCredentials({
+      rpId: state.rpId,
+      userId: state.user.id,
+      allAcceptedCredentialIds: state.passkeys.map((p) => p.id),
+    }));
+  }
+  if (deletedId && signals.unknown) {
+    return safeSignal(() => PKC.signalUnknownCredential({
+      rpId: state.rpId,
+      credentialId: deletedId,
+    }));
+  }
+  return false;
+}
+
+async function syncUserDetails() {
+  const u = state.user;
+  if (!signals.userDetails || !u?.id || !u.name) return;
+  await safeSignal(() => PKC.signalCurrentUserDetails({
+    rpId: state.rpId,
+    userId: u.id,
+    name: u.name,
+    displayName: u.displayName || u.name,
+  }));
+}
+
+function renderSyncNote() {
+  if (DEMO) {
+    els.syncNote.textContent = 'Demo mode: changes are stored locally and are not sent to your browser’s passkey manager.';
+  } else if (signals.allAccepted || signals.unknown) {
+    els.syncNote.textContent = 'Your browser’s passkey manager is updated automatically when you remove a passkey here.';
+  } else {
+    els.syncNote.textContent = 'Your browser can’t be updated automatically. After deleting a passkey here, also remove it from your device or password manager settings.';
+  }
+  els.syncNote.hidden = false;
+}
+
+/* ------------------------------------------------------------------ */
+/* Rendering                                                           */
+/* ------------------------------------------------------------------ */
+
+const dateFmt = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium' });
+const relFmt = new Intl.RelativeTimeFormat(undefined, { numeric: 'auto' });
+
+function formatDate(iso) {
+  const d = iso ? new Date(iso) : null;
+  return d && !isNaN(d) ? dateFmt.format(d) : null;
+}
+
+function formatRelative(iso) {
+  const d = iso ? new Date(iso) : null;
+  if (!d || isNaN(d)) return null;
+  const days = Math.round((d - Date.now()) / 86400000);
+  if (Math.abs(days) < 1) return 'today';
+  if (Math.abs(days) < 30) return relFmt.format(days, 'day');
+  return dateFmt.format(d);
+}
+
+function metaText(p) {
+  const parts = [];
+  if (p.provider?.name) parts.push(p.provider.name);
+  const created = formatDate(p.createdAt);
+  if (created) parts.push(`Added ${created}`);
+  const used = formatRelative(p.lastUsedAt);
+  parts.push(used ? `Last used ${used}` : 'Never used');
+  return parts.join(' · ');
+}
+
+function isSafeIcon(src) {
+  return typeof src === 'string' && /^(data:image\/(png|svg\+xml|webp|jpeg);|https:\/\/)/i.test(src);
+}
+
+function renderItem(p) {
+  const li = els.template.content.firstElementChild.cloneNode(true);
+  li.dataset.id = p.id;
+
+  if (isSafeIcon(p.provider?.icon)) {
+    const icon = li.querySelector('.passkey-icon');
+    const img = document.createElement('img');
+    img.src = p.provider.icon;
+    img.alt = '';
+    icon.replaceChildren(img);
+  }
+
+  const nameEl = li.querySelector('.passkey-name');
+  nameEl.textContent = p.name || 'Unnamed passkey';
+  if (p.backedUp) {
+    const badge = document.createElement('span');
+    badge.className = 'badge';
+    badge.textContent = 'Synced';
+    badge.title = 'This passkey is backed up and available on your other devices';
+    nameEl.append(badge);
+  }
+  li.querySelector('.passkey-meta').textContent = metaText(p);
+
+  const input = li.querySelector('.rename-form input');
+  const inputId = 'rename-' + cssSafe(p.id);
+  input.id = inputId;
+  li.querySelector('.rename-form label').htmlFor = inputId;
+  input.maxLength = NAME_MAX;
+
+  li.querySelector('[data-action="rename"]').setAttribute('aria-label', `Rename ${p.name || 'passkey'}`);
+  li.querySelector('[data-action="delete"]').setAttribute('aria-label', `Delete ${p.name || 'passkey'}`);
+  return li;
+}
+
+function cssSafe(s) {
+  return String(s).replace(/[^a-zA-Z0-9_-]/g, '_');
+}
+
+function render() {
+  els.loading.hidden = true;
+  els.error.hidden = true;
+  const has = state.passkeys.length > 0;
+  els.empty.hidden = has;
+  els.list.hidden = !has;
+  els.list.replaceChildren(...state.passkeys.map(renderItem));
+  renderSyncNote();
+}
+
+function setStatus(message, { error = false } = {}) {
+  els.status.textContent = message;
+  els.status.classList.toggle('is-error', error);
+}
+
+function findItem(id) {
+  return [...els.list.children].find((li) => li.dataset.id === id);
+}
+
+/* ------------------------------------------------------------------ */
+/* Actions                                                             */
+/* ------------------------------------------------------------------ */
+
+async function load() {
+  els.loading.hidden = false;
+  els.error.hidden = true;
+  els.empty.hidden = true;
+  els.list.hidden = true;
+  setStatus('');
+  try {
+    const data = await api.list();
+    state.rpId = data?.rpId || location.hostname;
+    state.user = data?.user || null;
+    state.passkeys = Array.isArray(data?.passkeys) ? data.passkeys : [];
+    render();
+    // Reconcile the authenticator with the server's view on every visit, so
+    // passkeys removed elsewhere (another device, support) also disappear.
+    syncAcceptedCredentials();
+    syncUserDetails();
+  } catch (err) {
+    if (err.status === 401) return;
+    console.error(err);
+    els.loading.hidden = true;
+    els.error.hidden = false;
+  }
+}
+
+function startRename(li) {
+  const p = state.passkeys.find((x) => x.id === li.dataset.id);
+  if (!p) return;
+  // Only one rename at a time.
+  els.list.querySelectorAll('.rename-form:not([hidden])').forEach((f) => cancelRename(f.closest('.passkey')));
+  const form = li.querySelector('.rename-form');
+  const input = form.querySelector('input');
+  input.value = p.name || '';
+  li.querySelector('.passkey-view').hidden = true;
+  li.querySelector('.passkey-actions').hidden = true;
+  form.hidden = false;
+  input.focus();
+  input.select();
+}
+
+function cancelRename(li) {
+  li.querySelector('.rename-form').hidden = true;
+  li.querySelector('.passkey-view').hidden = false;
+  li.querySelector('.passkey-actions').hidden = false;
+}
+
+async function submitRename(li) {
+  const id = li.dataset.id;
+  const p = state.passkeys.find((x) => x.id === id);
+  const input = li.querySelector('.rename-form input');
+  const name = input.value.trim().replace(/\s+/g, ' ');
+
+  if (!name) {
+    input.setCustomValidity('Please enter a name.');
+    input.reportValidity();
+    return;
+  }
+  if (name.length > NAME_MAX) {
+    input.setCustomValidity(`Names can be at most ${NAME_MAX} characters.`);
+    input.reportValidity();
+    return;
+  }
+  if (!p || name === p.name) {
+    cancelRename(li);
+    li.querySelector('[data-action="rename"]').focus();
+    return;
+  }
+
+  li.classList.add('is-busy');
+  try {
+    const updated = await api.rename(id, name);
+    Object.assign(p, updated && typeof updated === 'object' ? updated : { name });
+    render();
+    setStatus(`Passkey renamed to “${p.name}”.`);
+    findItem(id)?.querySelector('[data-action="rename"]')?.focus();
+  } catch (err) {
+    li.classList.remove('is-busy');
+    setStatus(err.message || 'Could not rename the passkey.', { error: true });
+    input.focus();
+  }
+}
+
+function confirmDelete(p) {
+  els.dialogName.textContent = p.name || 'This passkey';
+  els.dialogLast.hidden = state.passkeys.length > 1;
+  els.dialog.returnValue = '';
+  return new Promise((resolve) => {
+    els.dialog.addEventListener('close', () => resolve(els.dialog.returnValue === 'confirm'), { once: true });
+    els.dialog.showModal();
+  });
+}
+
+async function deletePasskey(li) {
+  const id = li.dataset.id;
+  const p = state.passkeys.find((x) => x.id === id);
+  if (!p) return;
+  if (!(await confirmDelete(p))) {
+    li.querySelector('[data-action="delete"]').focus();
+    return;
+  }
+
+  const index = state.passkeys.indexOf(p);
+  li.classList.add('is-busy');
+  try {
+    await api.remove(id);
+  } catch (err) {
+    li.classList.remove('is-busy');
+    // Already gone on the server — treat as success so we still sync it away.
+    if (err.status !== 404) {
+      setStatus(err.message || 'Could not delete the passkey.', { error: true });
+      return;
+    }
+  }
+
+  state.passkeys = state.passkeys.filter((x) => x.id !== id);
+  render();
+  const synced = await syncAcceptedCredentials({ deletedId: id });
+  setStatus(
+    synced
+      ? `“${p.name || 'Passkey'}” was deleted and removed from your browser’s passkey list.`
+      : `“${p.name || 'Passkey'}” was deleted. You may also want to remove it from your device or password manager.`,
+  );
+
+  // Move focus somewhere sensible.
+  const next = state.passkeys[Math.min(index, state.passkeys.length - 1)];
+  (next ? findItem(next.id)?.querySelector('[data-action="delete"]') : null)?.focus();
+}
+
+/* ------------------------------------------------------------------ */
+/* Wiring                                                              */
+/* ------------------------------------------------------------------ */
+
+els.list.addEventListener('click', (e) => {
+  const btn = e.target.closest('button[data-action]');
+  if (!btn) return;
+  const li = btn.closest('.passkey');
+  switch (btn.dataset.action) {
+    case 'rename': startRename(li); break;
+    case 'cancel-rename':
+      cancelRename(li);
+      li.querySelector('[data-action="rename"]').focus();
+      break;
+    case 'delete': deletePasskey(li); break;
+  }
+});
+
+els.list.addEventListener('submit', (e) => {
+  e.preventDefault();
+  submitRename(e.target.closest('.passkey'));
+});
+
+els.list.addEventListener('input', (e) => {
+  if (e.target.matches('.rename-form input')) e.target.setCustomValidity('');
+});
+
+els.list.addEventListener('keydown', (e) => {
+  if (e.key === 'Escape' && e.target.matches('.rename-form input')) {
+    const li = e.target.closest('.passkey');
+    cancelRename(li);
+    li.querySelector('[data-action="rename"]').focus();
+  }
+});
+
+els.retry.addEventListener('click', load);
+
+load();
+
+/* ------------------------------------------------------------------ */
+/* Demo backend (?demo)                                                */
+/* ------------------------------------------------------------------ */
+
+function createDemoApi() {
+  const KEY = 'dg-demo-passkeys';
+  const day = 86400000;
+  const seed = () => ({
+    rpId: location.hostname,
+    user: { id: 'ZGVtby11c2Vy', name: 'alex@example.com', displayName: 'Alex' },
+    passkeys: [
+      { id: 'demo-cred-1', name: 'iCloud Keychain', createdAt: new Date(Date.now() - 200 * day).toISOString(), lastUsedAt: new Date(Date.now() - 1 * day).toISOString(), backedUp: true, provider: { name: 'iCloud Keychain' } },
+      { id: 'demo-cred-2', name: 'Work laptop', createdAt: new Date(Date.now() - 90 * day).toISOString(), lastUsedAt: new Date(Date.now() - 40 * day).toISOString(), backedUp: true, provider: { name: 'Google Password Manager' } },
+      { id: 'demo-cred-3', name: 'YubiKey', createdAt: new Date(Date.now() - 400 * day).toISOString(), lastUsedAt: null, backedUp: false, provider: { name: 'Security key' } },
+    ],
+  });
+  const read = () => {
+    try { return JSON.parse(localStorage.getItem(KEY)) || seed(); } catch { return seed(); }
+  };
+  const write = (d) => localStorage.setItem(KEY, JSON.stringify(d));
+  const delay = () => new Promise((r) => setTimeout(r, 250));
+
+  return {
+    async list() { await delay(); return read(); },
+    async rename(id, name) {
+      await delay();
+      const d = read();
+      const p = d.passkeys.find((x) => x.id === id);
+      if (!p) throw new ApiError('Passkey not found', 404);
+      p.name = name;
+      write(d);
+      return { ...p };
+    },
+    async remove(id) {
+      await delay();
+      const d = read();
+      d.passkeys = d.passkeys.filter((x) => x.id !== id);
+      write(d);
+      return null;
+    },
+  };
+}
