@@ -0,0 +1,428 @@
+import React, { useEffect, useId, useRef, useState } from 'react';
+import { KeyIcon, PencilSquareIcon, TrashIcon } from '@heroicons/react/24/outline';
+
+export interface PasskeyCredential {
+  id: string;
+  name: string | null;
+  aaguid: string;
+  registeredAt: number;
+  lastUsedAt: number | null;
+  providerName: string;
+  providerIcon: string | null;
+}
+
+export interface PasskeyAccountData {
+  rpId: string;
+  userId: string;
+  username: string;
+  displayName: string;
+  credentials: PasskeyCredential[];
+}
+
+interface Props {
+  initialData: PasskeyAccountData;
+  maxNameLength: number;
+}
+
+const API_BASE = `${import.meta.env.BASE_URL.replace(/\/$/, '')}/api/account`;
+
+/* ---------------- WebAuthn Signal API helpers ---------------- */
+
+// Signal API methods are recent additions; declare them locally so TS knows the shape.
+type SignalCapablePKC = {
+  signalAllAcceptedCredentials?: (opts: {
+    rpId: string;
+    userId: string;
+    allAcceptedCredentialIds: string[];
+  }) => Promise<void>;
+  signalCurrentUserDetails?: (opts: {
+    rpId: string;
+    userId: string;
+    name: string;
+    displayName: string;
+  }) => Promise<void>;
+};
+
+function getPKC(): SignalCapablePKC | null {
+  return typeof window !== 'undefined' && 'PublicKeyCredential' in window
+    ? (window.PublicKeyCredential as unknown as SignalCapablePKC)
+    : null;
+}
+
+/** Unpadded Base64URL: non-empty, [A-Za-z0-9_-], length % 4 !== 1. Browsers reject anything else. */
+function isValidBase64Url(value: unknown): value is string {
+  return typeof value === 'string' && value.length > 0 && value.length % 4 !== 1 && /^[A-Za-z0-9_-]+$/.test(value);
+}
+
+/**
+ * Tell the password manager which credential IDs are still valid for this account,
+ * so it can hide or remove passkeys that were deleted on the server.
+ * Passive background sync: never throws, warns instead of erroring.
+ */
+async function syncAcceptedCredentials(data: Pick<PasskeyAccountData, 'rpId' | 'userId' | 'credentials'>) {
+  const pkc = getPKC();
+  if (!pkc?.signalAllAcceptedCredentials) return;
+  const ids = data.credentials.map((c) => c.id);
+  if (!data.rpId || !isValidBase64Url(data.userId) || !ids.every(isValidBase64Url)) {
+    console.warn('signalAllAcceptedCredentials skipped: server rpId and valid Base64URL IDs are required.');
+    return;
+  }
+  try {
+    await pkc.signalAllAcceptedCredentials({
+      rpId: data.rpId, // server-provided; never window.location.hostname
+      userId: data.userId,
+      allAcceptedCredentialIds: ids,
+    });
+  } catch (e) {
+    console.warn('signalAllAcceptedCredentials sync warning:', e);
+  }
+}
+
+/** Push updated account name/display name to the password manager. */
+async function syncUserDetails(details: { rpId: string; userId: string; username: string; displayName: string }) {
+  const pkc = getPKC();
+  if (!pkc?.signalCurrentUserDetails) return;
+  if (!details.rpId || !isValidBase64Url(details.userId)) {
+    console.warn('signalCurrentUserDetails skipped: server rpId and valid Base64URL userId are required.');
+    return;
+  }
+  try {
+    await pkc.signalCurrentUserDetails({
+      rpId: details.rpId,
+      userId: details.userId,
+      name: details.username,
+      displayName: details.displayName,
+    });
+  } catch (e) {
+    console.warn('signalCurrentUserDetails sync warning:', e);
+  }
+}
+
+/* ---------------- Network ---------------- */
+
+async function request<T>(path: string, init?: RequestInit): Promise<T> {
+  const res = await fetch(`${API_BASE}${path}`, {
+    ...init,
+    headers: { 'Content-Type': 'application/json', ...init?.headers },
+    credentials: 'same-origin',
+  });
+  const body = await res.json().catch(() => ({}));
+  if (!res.ok) {
+    if (res.status === 401) throw new Error('Your session has expired. Please sign in again.');
+    throw new Error(body.error || `Request failed (${res.status}).`);
+  }
+  return body as T;
+}
+
+/* ---------------- UI ---------------- */
+
+const dateFormat = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium' });
+const formatDate = (epoch: number) => dateFormat.format(new Date(epoch));
+
+const buttonBase =
+  'inline-flex items-center gap-1.5 rounded-md px-3 py-1.5 text-sm font-medium focus:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 disabled:opacity-60 disabled:cursor-not-allowed';
+const primaryBtn = `${buttonBase} bg-gray-900 text-white hover:bg-gray-800 focus-visible:ring-gray-900`;
+const secondaryBtn = `${buttonBase} border border-gray-300 bg-white text-gray-800 hover:bg-gray-50 focus-visible:ring-gray-900`;
+const dangerBtn = `${buttonBase} bg-red-700 text-white hover:bg-red-800 focus-visible:ring-red-700`;
+const inputCls =
+  'w-full rounded-md border border-gray-300 px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500';
+
+export default function PasskeyManager({ initialData, maxNameLength }: Props) {
+  const [data, setData] = useState(initialData);
+  const [status, setStatus] = useState('');
+  const [error, setError] = useState<string | null>(null);
+  const [editingId, setEditingId] = useState<string | null>(null);
+  const [pendingDelete, setPendingDelete] = useState<PasskeyCredential | null>(null);
+  const [busy, setBusy] = useState(false);
+  const [signalSupported, setSignalSupported] = useState(true);
+  const dialogRef = useRef<HTMLDialogElement>(null);
+  const baseId = useId();
+
+  // On load, reconcile the password manager with the server's list of passkeys.
+  useEffect(() => {
+    setSignalSupported(Boolean(getPKC()?.signalAllAcceptedCredentials));
+    void syncAcceptedCredentials(initialData);
+  }, [initialData]);
+
+  const announce = (msg: string) => {
+    setError(null);
+    setStatus(msg);
+  };
+  const fail = (e: unknown) => {
+    setStatus('');
+    setError(e instanceof Error ? e.message : 'Something went wrong. Please try again.');
+  };
+
+  /* ---- Rename passkey (server-side label only, no Signal API call) ---- */
+  const handleRename = async (cred: PasskeyCredential, newName: string) => {
+    setBusy(true);
+    try {
+      const next = await request<PasskeyAccountData>(`/credentials/${encodeURIComponent(cred.id)}`, {
+        method: 'PUT',
+        body: JSON.stringify({ name: newName }),
+      });
+      setData(next);
+      setEditingId(null);
+      const updated = next.credentials.find((c) => c.id === cred.id);
+      announce(`Passkey renamed to “${updated?.name ?? updated?.providerName ?? newName}”.`);
+    } catch (e) {
+      fail(e);
+    } finally {
+      setBusy(false);
+    }
+  };
+
+  /* ---- Delete passkey (then signal remaining IDs) ---- */
+  const openDeleteDialog = (cred: PasskeyCredential) => {
+    setPendingDelete(cred);
+    dialogRef.current?.showModal();
+  };
+
+  const handleDialogClose = async () => {
+    const dialog = dialogRef.current;
+    if (!dialog) return;
+    const choice = dialog.returnValue;
+    dialog.returnValue = ''; // Esc sets no value; avoid leaking a stale one.
+    const cred = pendingDelete;
+    setPendingDelete(null);
+    if (choice !== 'delete' || !cred) return;
+
+    setBusy(true);
+    try {
+      const next = await request<PasskeyAccountData>(`/credentials/${encodeURIComponent(cred.id)}`, {
+        method: 'DELETE',
+      });
