+      announce(`Removed “${cred.name ?? cred.providerName}”.`);
+      await syncAcceptedCredentials(next);
+    } catch (e) {
+      fail(e);
+    } finally {
+      setBusy(false);
+    }
+  };
+
+  /* ---- Account display name (then signal user details) ---- */
+  const handleDisplayName = async (e: React.FormEvent<HTMLFormElement>) => {
+    e.preventDefault();
+    const displayName = String(new FormData(e.currentTarget).get('displayName') ?? '');
+    setBusy(true);
+    try {
+      const next = await request<Omit<PasskeyAccountData, 'credentials'>>('/user', {
+        method: 'PUT',
+        body: JSON.stringify({ displayName }),
+      });
+      setData((d) => ({ ...d, ...next }));
+      announce('Display name updated.');
+      await syncUserDetails(next);
+    } catch (err) {
+      fail(err);
+    } finally {
+      setBusy(false);
+    }
+  };
+
+  const headingId = `${baseId}-heading`;
+  const dialogTitleId = `${baseId}-dialog-title`;
+
+  return (
+    <section aria-labelledby={headingId} className="space-y-6">
+      <div>
+        <h2 id={headingId} className="text-xl font-bold text-gray-900">
+          Passkeys
+        </h2>
+        <p className="mt-1 text-sm text-gray-600">
+          Passkeys let you sign in with your fingerprint, face, screen lock, or a security key. Removing a passkey
+          here also asks your password manager to stop offering it.
+        </p>
+        {!signalSupported && (
+          <p className="mt-2 text-xs text-gray-500">
+            Your browser can’t sync changes to your password manager automatically. After removing a passkey, also
+            delete it from your device’s password manager.
+          </p>
+        )}
+      </div>
+
+      <div aria-live="polite" role="status" className="text-sm text-green-800 empty:hidden">
+        {status}
+      </div>
+      {error && (
+        <div role="alert" className="rounded-md bg-red-100 p-3 text-sm text-red-700">
+          {error}
+        </div>
+      )}
+
+      {/* Account display name */}
+      <form onSubmit={handleDisplayName} className="rounded-lg border border-gray-200 p-4">
+        <label htmlFor={`${baseId}-display-name`} className="block text-sm font-medium text-gray-800">
+          Display name
+        </label>
+        <p id={`${baseId}-display-name-hint`} className="mt-0.5 text-xs text-gray-500">
+          Shown next to your passkeys in password managers. Signed in as <strong>{data.username}</strong>.
+        </p>
+        <div className="mt-2 flex flex-col gap-2 sm:flex-row">
+          <input
+            id={`${baseId}-display-name`}
+            name="displayName"
+            key={data.displayName}
+            defaultValue={data.displayName}
+            required
+            maxLength={maxNameLength}
+            autoComplete="name"
+            aria-describedby={`${baseId}-display-name-hint`}
+            className={inputCls}
+          />
+          <button type="submit" className={primaryBtn} disabled={busy}>
+            Save
+          </button>
+        </div>
+      </form>
+
+      {/* Passkey list */}
+      {data.credentials.length === 0 ? (
+        <div className="rounded-lg border border-dashed border-gray-300 p-6 text-center text-sm text-gray-600">
+          <KeyIcon aria-hidden="true" className="mx-auto mb-2 h-8 w-8 text-gray-400" />
+          No passkeys found. Passkeys you create will appear here.
+        </div>
+      ) : (
+        <ul className="divide-y divide-gray-200 rounded-lg border border-gray-200">
+          {data.credentials.map((cred) => (
+            <PasskeyRow
+              key={cred.id}
+              cred={cred}
+              editing={editingId === cred.id}
+              busy={busy}
+              maxNameLength={maxNameLength}
+              onEdit={() => {
+                setEditingId(cred.id);
+                setStatus('');
+              }}
+              onCancelEdit={() => setEditingId(null)}
+              onRename={(name) => handleRename(cred, name)}
+              onDelete={() => openDeleteDialog(cred)}
+            />
+          ))}
+        </ul>
+      )}
+
+      <dialog
+        ref={dialogRef}
+        aria-labelledby={dialogTitleId}
+        onClose={handleDialogClose}
+        className="m-auto w-[min(28rem,calc(100%-2rem))] rounded-lg p-6 shadow-xl"
+      >
+        <h1 id={dialogTitleId} className="text-lg font-bold text-gray-900">
+          Remove this passkey?
