+        <p className="mt-2 text-sm text-gray-600">
+          You will no longer be able to sign in with{' '}
+          <strong>{pendingDelete ? pendingDelete.name ?? pendingDelete.providerName : 'this passkey'}</strong>.
+          {data.credentials.length === 1 && ' This is your only passkey; you can still sign in with your password.'}
+        </p>
+        <form method="dialog" className="mt-6 flex justify-end gap-2">
+          <button value="cancel" className={secondaryBtn} autoFocus>
+            Cancel
+          </button>
+          <button value="delete" className={dangerBtn}>
+            Remove
+          </button>
+        </form>
+      </dialog>
+    </section>
+  );
+}
+
+interface RowProps {
+  cred: PasskeyCredential;
+  editing: boolean;
+  busy: boolean;
+  maxNameLength: number;
+  onEdit: () => void;
+  onCancelEdit: () => void;
+  onRename: (name: string) => void;
+  onDelete: () => void;
+}
+
+function PasskeyRow({ cred, editing, busy, maxNameLength, onEdit, onCancelEdit, onRename, onDelete }: RowProps) {
+  const inputId = useId();
+  const label = cred.name ?? cred.providerName;
+
+  return (
+    <li className="flex flex-col gap-3 p-4 sm:flex-row sm:items-center">
+      <div className="flex min-w-0 flex-1 items-start gap-3">
+        {cred.providerIcon ? (
+          <img src={cred.providerIcon} alt="" width={32} height={32} className="h-8 w-8 shrink-0 rounded" />
+        ) : (
+          <span className="flex h-8 w-8 shrink-0 items-center justify-center rounded bg-gray-100">
+            <KeyIcon aria-hidden="true" className="h-5 w-5 text-gray-500" />
+          </span>
+        )}
+
+        <div className="min-w-0 flex-1">
+          {editing ? (
+            <form
+              onSubmit={(e) => {
+                e.preventDefault();
+                onRename(String(new FormData(e.currentTarget).get('name') ?? ''));
