+              onKeyDown={(e) => {
+                if (e.key === 'Escape') onCancelEdit();
+              }}
+              className="flex flex-col gap-2 sm:flex-row sm:items-center"
+            >
+              <label htmlFor={inputId} className="sr-only">
+                Passkey name
+              </label>
+              <input
+                id={inputId}
+                name="name"
