+            </form>
+          ) : (
+            <p className="truncate font-semibold text-gray-900">{label}</p>
+          )}
+          <p className="mt-0.5 text-xs text-gray-500">
+            {cred.name && <>{cred.providerName} · </>}
+            Created <time dateTime={new Date(cred.registeredAt).toISOString()}>{formatDate(cred.registeredAt)}</time>
+            {' · '}
+            {cred.lastUsedAt ? (
+              <>
+                Last used <time dateTime={new Date(cred.lastUsedAt).toISOString()}>{formatDate(cred.lastUsedAt)}</time>
+              </>
+            ) : (
+              'Never used'
+            )}
+          </p>
+        </div>
+      </div>
+
+      {!editing && (
+        <div className="flex gap-2 sm:shrink-0">
+          <button type="button" className={secondaryBtn} onClick={onEdit} disabled={busy} aria-label={`Rename ${label}`}>
+            <PencilSquareIcon aria-hidden="true" className="h-4 w-4" />
+            Rename
