--- /dev/null
+++ b/src/lib/auth.ts
@@ -0,0 +1,32 @@
+
+/** Minimal shape of the signed-in reader kept in the Astro session. */
+export interface SessionUser {
+  username: string;
+}
+
+type SessionLike = {
+  get(key: string): Promise<any>;
+  set(key: string, value: any): void | Promise<void>;
+  delete?(key: string): void;
+  regenerate?(): Promise<void>;
+} | undefined;
+
+export const SESSION_USER_KEY = 'user';
+
+export async function getSessionUser(session: SessionLike): Promise<SessionUser | null> {
+  const user = await session?.get(SESSION_USER_KEY);
+  if (user && typeof user.username === 'string' && user.username.length > 0) {
+    return { username: user.username };
+  }
+  return null;
+}
+
+export function jsonResponse(body: unknown, status = 200): Response {
+  return new Response(JSON.stringify(body), {
+    status,
+    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' },
+  });
+}
+
+export const unauthorized = () => jsonResponse({ error: 'You must be signed in.' }, 401);
+
diff --git a/src/lib/passkeys.ts b/src/lib/passkeys.ts
new file mode 100644
index 0000000..c79a343
--- /dev/null
+++ b/src/lib/passkeys.ts
@@ -0,0 +1,197 @@
+import { randomBytes } from 'node:crypto';
+
+/**
+ * Passkey credential record as persisted on the server.
+ * `id` and the account's `passkeyUserId` are unpadded Base64URL strings, which is
+ * what the WebAuthn Signal API requires.
+ */
+export interface StoredPasskeyCredential {
+  id: string;
+  /** User-chosen nickname; falls back to the AAGUID provider name when null. */
+  name: string | null;
+  aaguid: string;
+  /** Epoch milliseconds. */
+  registeredAt: number;
+  /** Epoch milliseconds, or null if never used to sign in. */
+  lastUsedAt: number | null;
+}
+
+export interface PasskeyAccount {
+  username: string;
+  displayName: string;
+  /** WebAuthn user handle (user.id), unpadded Base64URL. */
+  passkeyUserId: string;
+  credentials: StoredPasskeyCredential[];
+}
+
+/** Credential shape sent to the client, with AAGUID provider details resolved. */
+export interface PasskeyCredentialView extends StoredPasskeyCredential {
+  providerName: string;
+  providerIcon: string | null;
+}
+
+export const MAX_NAME_LENGTH = 64;
+
+/**
+ * RP ID the passkeys were registered against. Configure with PASSKEY_RP_ID in
+ * production; otherwise fall back to the hostname the server was reached on.
+ * Never derived on the client.
+ */
+export function getRpId(requestUrl: URL): string {
+  return process.env.PASSKEY_RP_ID || requestUrl.hostname;
+}
+
+const base64url = (bytes: Buffer) => bytes.toString('base64url');
+
+/*
+ * In-memory store. The site has no database yet, so accounts live for the
+ * lifetime of the server process. Swap these functions for real persistence
+ * when one is added.
+ */
+const accounts = new Map<string, PasskeyAccount>();
+
+const DAY = 24 * 60 * 60 * 1000;
+
+/** Seed a few demo passkeys from common providers so the section is populated. */
+function seedCredentials(): StoredPasskeyCredential[] {
+  const now = Date.now();
+  return [
+    {
+      id: base64url(randomBytes(16)),
+      name: null,
+      aaguid: 'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4', // Google Password Manager
+      registeredAt: now - 120 * DAY,
+      lastUsedAt: now - 2 * DAY,
+    },
+    {
+      id: base64url(randomBytes(16)),
+      name: 'Work MacBook',
+      aaguid: 'fbfc3007-154e-4ecc-8c0b-6e020557d7bd', // iCloud Keychain
+      registeredAt: now - 60 * DAY,
+      lastUsedAt: now - 9 * DAY,
+    },
+    {
+      id: base64url(randomBytes(16)),
+      name: null,
+      aaguid: 'cb69481e-8ff7-4039-93ec-0a2729a154a8', // YubiKey 5 Series
+      registeredAt: now - 300 * DAY,
+      lastUsedAt: null,
+    },
+  ];
+}
+
+export function getAccount(username: string): PasskeyAccount {
+  let account = accounts.get(username);
+  if (!account) {
+    account = {
+      username,
+      displayName: username,
+      passkeyUserId: base64url(randomBytes(32)),
+      credentials: seedCredentials(),
+    };
+    accounts.set(username, account);
+  }
+  return account;
+}
+
+export function renameCredential(username: string, id: string, name: string | null) {
+  const cred = getAccount(username).credentials.find((c) => c.id === id);
+  if (!cred) return null;
+  cred.name = name;
+  return cred;
+}
+
+export function deleteCredential(username: string, id: string): boolean {
+  const account = getAccount(username);
+  const before = account.credentials.length;
+  account.credentials = account.credentials.filter((c) => c.id !== id);
+  return account.credentials.length !== before;
+}
+
+export function updateDisplayName(username: string, displayName: string) {
+  const account = getAccount(username);
+  account.displayName = displayName;
+  return account;
+}
+
+/** Trim and validate a user-supplied label. Returns null for "clear", or an error string. */
+export function normalizeName(value: unknown): { value: string | null } | { error: string } {
+  if (value === null || value === undefined) return { value: null };
+  if (typeof value !== 'string') return { error: 'Name must be a string.' };
+  const trimmed = value.trim().replace(/\s+/g, ' ');
+  if (trimmed.length > MAX_NAME_LENGTH) {
+    return { error: `Name must be ${MAX_NAME_LENGTH} characters or fewer.` };
+  }
+  return { value: trimmed || null };
+}
+
+/* ---------- AAGUID → provider lookup (UX hint only, never for security) ---------- */
+
+interface AaguidEntry {
+  name: string;
+  icon_light?: string;
+  icon_dark?: string;
+}
+
+const ZERO_AAGUID = '00000000-0000-0000-0000-000000000000';
+const AAGUID_REGISTRY_URL =
+  'https://raw.githubusercontent.com/passkeydeveloper/passkey-authenticator-aaguids/refs/heads/main/combined_aaguid.json';
+
+/** Local fallback used until (or if) the community registry can be fetched. */
+const FALLBACK_REGISTRY: Record<string, AaguidEntry> = {
+  'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4': { name: 'Google Password Manager' },
+  'fbfc3007-154e-4ecc-8c0b-6e020557d7bd': { name: 'iCloud Keychain' },
+  'dd4ec289-e01d-41c9-bb89-70fa845d4bf2': { name: 'iCloud Keychain (Managed)' },
+  'bada5566-a7aa-401f-bd96-45619a55120d': { name: '1Password' },
+  'd548826e-79b4-db40-a3d8-11116f7e8349': { name: 'Bitwarden' },
+  '08987058-cadc-4b81-b6e1-30de50dcbe96': { name: 'Windows Hello' },
+  'cb69481e-8ff7-4039-93ec-0a2729a154a8': { name: 'YubiKey 5 Series' },
+};
+
+let registry: Record<string, AaguidEntry> | null = null;
+let registryPromise: Promise<void> | null = null;
+let registryFailedAt = 0;
+
+async function loadRegistry(): Promise<void> {
+  if (registry || Date.now() - registryFailedAt < 10 * 60 * 1000) return;
+  registryPromise ??= (async () => {
+    try {
+      const res = await fetch(AAGUID_REGISTRY_URL, { signal: AbortSignal.timeout(3000) });
+      if (!res.ok) throw new Error(`HTTP ${res.status}`);
+      registry = (await res.json()) as Record<string, AaguidEntry>;
+    } catch {
+      registryFailedAt = Date.now();
+    } finally {
+      registryPromise = null;
+    }
+  })();
+  await registryPromise;
+}
+
+export async function toCredentialViews(
+  credentials: StoredPasskeyCredential[],
+): Promise<PasskeyCredentialView[]> {
+  await loadRegistry();
+  return credentials.map((cred) => {
+    const entry =
+      cred.aaguid === ZERO_AAGUID ? undefined : registry?.[cred.aaguid] ?? FALLBACK_REGISTRY[cred.aaguid];
+    const iconOk = entry?.icon_light?.startsWith('data:image/');
+    return {
+      ...cred,
+      providerName: entry?.name ?? 'Unknown passkey provider',
+      providerIcon: iconOk ? entry!.icon_light! : null,
+    };
+  });
+}
+
+/** Payload for GET /api/account/credentials and responses after mutations. */
+export async function credentialsPayload(username: string, requestUrl: URL) {
+  const account = getAccount(username);
+  return {
+    rpId: getRpId(requestUrl),
+    userId: account.passkeyUserId,
+    username: account.username,
+    displayName: account.displayName,
+    credentials: await toCredentialViews(account.credentials),
+  };
+}
