+import type { APIRoute } from 'astro';
+import { getSessionUser, jsonResponse, unauthorized } from '../../../../lib/auth';
+import { credentialsPayload, deleteCredential, normalizeName, renameCredential } from '../../../../lib/passkeys';
+
+const notFound = () => jsonResponse({ error: 'Passkey not found.' }, 404);
+
+/** Rename a passkey. This is a server-side label only; the authenticator is not involved. */
+export const PUT: APIRoute = async ({ params, request, session, url }) => {
+  const user = await getSessionUser(session);
+  if (!user) return unauthorized();
+
+  const body = await request.json().catch(() => null);
+  if (!body || typeof body !== 'object') return jsonResponse({ error: 'Invalid request body.' }, 400);
+  const name = normalizeName((body as { name?: unknown }).name);
+  if ('error' in name) return jsonResponse({ error: name.error }, 400);
+
+  // Lookup is scoped to the signed-in user's own credentials.
+  if (!renameCredential(user.username, params.id!, name.value)) return notFound();
+  return jsonResponse(await credentialsPayload(user.username, url));
+};
+
+/** Delete a passkey. The client then signals the remaining IDs to the authenticator. */
+export const DELETE: APIRoute = async ({ params, session, url }) => {
+  const user = await getSessionUser(session);
+  if (!user) return unauthorized();
+  if (!deleteCredential(user.username, params.id!)) return notFound();
+  return jsonResponse(await credentialsPayload(user.username, url));
+};
