+import type { APIRoute } from 'astro';
+import { getSessionUser, jsonResponse, unauthorized } from '../../../lib/auth';
+import { getRpId, normalizeName, updateDisplayName } from '../../../lib/passkeys';
+
+/** Update the account display name shown by password managers next to this site's passkeys. */
+export const PUT: APIRoute = async ({ request, session, url }) => {
+  const user = await getSessionUser(session);
+  if (!user) return unauthorized();
+
+  const body = await request.json().catch(() => null);
+  if (!body || typeof body !== 'object') return jsonResponse({ error: 'Invalid request body.' }, 400);
+  const result = normalizeName((body as { displayName?: unknown }).displayName);
+  if ('error' in result) return jsonResponse({ error: result.error }, 400);
+  if (!result.value) return jsonResponse({ error: 'Display name cannot be empty.' }, 400);
+
+  const account = updateDisplayName(user.username, result.value);
+  return jsonResponse({
+    rpId: getRpId(url),
+    userId: account.passkeyUserId,
+    username: account.username,
+    displayName: account.displayName,
+  });
+};
