+import type { APIRoute } from 'astro';
+import { SESSION_USER_KEY, jsonResponse } from '../../../lib/auth';
+
+const LOGIN_URL = 'https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api/login';
+
+/**
+ * Proxies sign-in to the upstream auth service and, on success, records the
+ * reader in the server session so account pages (like passkey management) know
+ * who is signed in. Upstream status and error codes are passed through unchanged.
+ */
+export const POST: APIRoute = async ({ request, session }) => {
+  let body: { username?: unknown; password?: unknown };
+  try {
+    body = await request.json();
+  } catch {
+    return jsonResponse({ error: 'Invalid request body.' }, 400);
+  }
+  const { username, password } = body;
+  if (typeof username !== 'string' || typeof password !== 'string' || !username || !password) {
+    return jsonResponse({ error: 'Username and password are required.' }, 400);
+  }
+
+  let upstream: Response;
+  try {
+    upstream = await fetch(LOGIN_URL, {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ username, password }),
+    });
+  } catch {
+    return jsonResponse({ error: 'Sign-in service unavailable.' }, 502);
+  }
+
+  const data = await upstream.json().catch(() => ({}));
+  if (upstream.ok) {
+    // New session ID on privilege change to prevent session fixation.
+    await session?.regenerate();
+    session?.set(SESSION_USER_KEY, { username });
+  }
+  return jsonResponse(data, upstream.status);
+};
