+
+const API = `${import.meta.env.BASE_URL}api/passkeys`;
+const MAX_NAME_LENGTH = 64;
+
+type Notice = { kind: 'success' | 'error' | 'info'; text: string } | null;
+
+// ---------------------------------------------------------------------------
+// WebAuthn helpers
+// ---------------------------------------------------------------------------
+
+function b64urlToBuffer(value: string): ArrayBuffer {
+  const base64 = value.replace(/-/g, '+').replace(/_/g, '/').padEnd(Math.ceil(value.length / 4) * 4, '=');
+  const binary = atob(base64);
+  const bytes = new Uint8Array(binary.length);
+  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
+  return bytes.buffer;
+}
+
+function bufferToB64url(buffer: ArrayBuffer | ArrayBufferView): string {
+  const bytes = buffer instanceof ArrayBuffer ? new Uint8Array(buffer) : new Uint8Array(buffer.buffer, buffer.byteOffset, buffer.byteLength);
+  let binary = '';
+  for (const b of bytes) binary += String.fromCharCode(b);
+  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+function isWebAuthnSupported(): boolean {
+  return typeof window !== 'undefined' && typeof window.PublicKeyCredential === 'function' && !!navigator.credentials?.create;
+}
+
+/** WebAuthn Signal API — not yet in TypeScript's DOM lib. */
+interface SignalCapablePublicKeyCredential {
+  signalAllAcceptedCredentials?: (options: { rpId: string; userId: string; allAcceptedCredentialIds: string[] }) => Promise<void>;
+  signalCurrentUserDetails?: (options: { rpId: string; userId: string; name: string; displayName: string }) => Promise<void>;
+}
+
+function signalApi(): SignalCapablePublicKeyCredential | null {
+  if (typeof window === 'undefined' || typeof window.PublicKeyCredential !== 'function') return null;
+  return window.PublicKeyCredential as unknown as SignalCapablePublicKeyCredential;
+}
+
+function isSignalApiSupported(): boolean {
+  const api = signalApi();
+  return !!api && typeof api.signalAllAcceptedCredentials === 'function';
+}
+
+/**
+ * Tells the browser's passkey provider which credentials are still valid and
+ * what the account's current names are, so removed passkeys disappear from the
+ * authenticator and its account labels stay up to date.
+ */
+async function syncAuthenticator(account: PasskeyAccount): Promise<boolean> {
+  const api = signalApi();
+  if (!api?.signalAllAcceptedCredentials) return false;
+  const results = await Promise.allSettled([
+    api.signalAllAcceptedCredentials({
+      rpId: account.rpId,
+      userId: account.userId,
+      allAcceptedCredentialIds: account.passkeys.map((p) => p.id),
+    }),
+    api.signalCurrentUserDetails?.({
+      rpId: account.rpId,
+      userId: account.userId,
+      name: account.username,
+      displayName: account.displayName,
+    }),
+  ]);
+  return results.every((r) => r.status === 'fulfilled');
+}
+
+async function readJson(response: Response) {
+  const data = await response.json().catch(() => ({}));
+  if (!response.ok) throw new Error(data?.error || `Request failed (${response.status})`);
+  return data;
+}
+
+function formatDate(iso: string | null): string {
+  if (!iso) return 'Never';
+  return new Date(iso).toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
+}
+
+function transportLabel(transports: string[]): string | null {
+  const labels: Record<string, string> = {
+    internal: 'This device',
+    hybrid: 'Phone or tablet',
+    usb: 'USB',
+    nfc: 'NFC',
+    ble: 'Bluetooth',
+    'smart-card': 'Smart card',
+  };
+  const mapped = transports.map((t) => labels[t]).filter(Boolean);
+  return mapped.length ? mapped.join(' · ') : null;
+}
+
+// ---------------------------------------------------------------------------
+// Component
+// ---------------------------------------------------------------------------
+
+export default function PasskeyManager({ initialAccount }: Props) {
+  const [account, setAccount] = useState<PasskeyAccount>(initialAccount);
+  const [notice, setNotice] = useState<Notice>(null);
+  const [busy, setBusy] = useState<string | null>(null);
+  const [editingId, setEditingId] = useState<string | null>(null);
+  const [editName, setEditName] = useState('');
+  const [confirmRemoveId, setConfirmRemoveId] = useState<string | null>(null);
+  const [displayName, setDisplayName] = useState(initialAccount.displayName);
+  const [supportsWebAuthn, setSupportsWebAuthn] = useState(false);
+  const [supportsSignals, setSupportsSignals] = useState(false);
+  const editInputRef = useRef<HTMLInputElement>(null);
+
+  const applyAccount = useCallback(async (next: PasskeyAccount, successText?: string) => {
+    setAccount(next);
+    setDisplayName(next.displayName);
+    const synced = await syncAuthenticator(next).catch(() => false);
+    if (successText) {
+      setNotice({
+        kind: 'success',
+        text: synced ? `${successText} Your browser's passkey manager has been updated.` : successText,
+      });
+    }
+  }, []);
+
+  // Feature detection + initial authenticator sync on mount.
+  useEffect(() => {
+    setSupportsWebAuthn(isWebAuthnSupported());
+    setSupportsSignals(isSignalApiSupported());
+    syncAuthenticator(initialAccount).catch(() => undefined);
+  }, [initialAccount]);
+
+  useEffect(() => {
+    if (editingId) editInputRef.current?.focus();
+  }, [editingId]);
+
+  const run = async (key: string, fn: () => Promise<void>) => {
+    setBusy(key);
+    setNotice(null);
+    try {
+      await fn();
+    } catch (err) {
+      setNotice({ kind: 'error', text: (err as Error).message || 'Something went wrong.' });
+    } finally {
+      setBusy(null);
+    }
+  };
+
+  const handleRename = (id: string) =>
+    run(`rename:${id}`, async () => {
+      const name = editName.trim();
+      if (!name) throw new Error('Please enter a name for this passkey.');
+      const data = await readJson(
+        await fetch(`${API}/${encodeURIComponent(id)}`, {
+          method: 'PATCH',
+          headers: { 'Content-Type': 'application/json' },
+          body: JSON.stringify({ name }),
+        }),
+      );
+      setEditingId(null);
+      await applyAccount(data, `Passkey renamed to “${name}”.`);
+    });
+
+  const handleRemove = (passkey: Passkey) =>
+    run(`remove:${passkey.id}`, async () => {
+      const data = await readJson(await fetch(`${API}/${encodeURIComponent(passkey.id)}`, { method: 'DELETE' }));
+      setConfirmRemoveId(null);
+      await applyAccount(data, `“${passkey.name}” was removed.`);
+    });
+
+  const handleDisplayName = (e: React.FormEvent) => {
+    e.preventDefault();
+    run('displayName', async () => {
+      const value = displayName.trim();
+      if (!value) throw new Error('Please enter a display name.');
+      const data = await readJson(
+        await fetch(API, {
+          method: 'PATCH',
+          headers: { 'Content-Type': 'application/json' },
+          body: JSON.stringify({ displayName: value }),
+        }),
+      );
+      await applyAccount(data, 'Display name updated.');
+    });
+  };
+
+  const handleAdd = () =>
+    run('add', async () => {
+      const options = await readJson(
+        await fetch(`${API}/options`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' }),
+      );
+
+      const publicKey: PublicKeyCredentialCreationOptions = {
+        ...options,
+        challenge: b64urlToBuffer(options.challenge),
+        user: { ...options.user, id: b64urlToBuffer(options.user.id) },
+        excludeCredentials: options.excludeCredentials.map((c: { id: string; type: 'public-key'; transports: AuthenticatorTransport[] }) => ({
+          ...c,
+          id: b64urlToBuffer(c.id),
+        })),
+      };
+
+      let credential: PublicKeyCredential | null;
+      try {
+        credential = (await navigator.credentials.create({ publicKey })) as PublicKeyCredential | null;
+      } catch (err) {
+        const name = (err as DOMException)?.name;
+        if (name === 'NotAllowedError') throw new Error('Passkey creation was cancelled.');
+        if (name === 'InvalidStateError') throw new Error('This authenticator already has a passkey for your account.');
+        throw err;
+      }
+      if (!credential) throw new Error('No passkey was created.');
+
+      const response = credential.response as AuthenticatorAttestationResponse;
+      const spki = response.getPublicKey?.();
+      const data = await readJson(
+        await fetch(API, {
+          method: 'POST',
+          headers: { 'Content-Type': 'application/json' },
+          body: JSON.stringify({
+            credential: {
+              id: credential.id,
+              rawId: bufferToB64url(credential.rawId),
+              type: credential.type,
+              response: {
+                clientDataJSON: bufferToB64url(response.clientDataJSON),
+                authenticatorData: bufferToB64url(response.getAuthenticatorData()),
+                publicKey: spki ? bufferToB64url(spki) : null,
+                publicKeyAlgorithm: response.getPublicKeyAlgorithm?.() ?? null,
+                transports: response.getTransports?.() ?? [],
+              },
+            },
+          }),
+        }),
+      );
+      await applyAccount(data, 'New passkey added.');
+    });
+
+  const startEditing = (passkey: Passkey) => {
+    setConfirmRemoveId(null);
+    setEditingId(passkey.id);
+    setEditName(passkey.name);
+  };
+
+  return (
+    <section aria-labelledby="passkeys-heading" className="bg-white border border-gray-200 rounded-lg shadow-sm">
+      <header className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-4 p-6 border-b border-gray-200">
+        <div>
+          <h2 id="passkeys-heading" className="text-xl font-bold text-gray-900 flex items-center gap-2">
+            <KeyIcon className="h-5 w-5" aria-hidden="true" />
+            Passkeys
+          </h2>
+          <p className="mt-1 text-sm text-gray-600 max-w-prose">
+            Passkeys let you sign in with your fingerprint, face, screen lock, or security key instead of a password.
+            Changes you make here are shared with your browser's passkey manager so it only offers keys that still work.
+          </p>
+        </div>
+        {supportsWebAuthn && (
+          <button
+            type="button"
+            onClick={handleAdd}
+            disabled={busy !== null}
+            className="inline-flex items-center gap-1 shrink-0 py-2 px-3 rounded-md text-sm font-medium text-white bg-gray-900 hover:bg-gray-800 disabled:opacity-60 disabled:cursor-not-allowed"
+          >
+            <PlusIcon className="h-4 w-4" aria-hidden="true" />
+            {busy === 'add' ? 'Waiting for authenticator…' : 'Add a passkey'}
+          </button>
+        )}
+      </header>
+
+      <div className="p-6 space-y-6">
+        <div aria-live="polite">
+          {notice && (
+            <div
+              role={notice.kind === 'error' ? 'alert' : 'status'}
+              className={`p-3 text-sm rounded-lg ${
+                notice.kind === 'error'
+                  ? 'text-red-700 bg-red-100'
+                  : notice.kind === 'success'
+                    ? 'text-green-700 bg-green-100'
+                    : 'text-gray-700 bg-gray-100'
+              }`}
+            >
+              {notice.text}
+            </div>
+          )}
+        </div>
+
+        {!supportsSignals && (
+          <p className="text-xs text-gray-500 bg-gray-50 border border-gray-200 rounded-md p-3">
+            Your browser doesn't support automatic passkey syncing yet. After removing a passkey here, you may also want
+            to delete it from your device's password manager.
+          </p>
+        )}
+
+        {/* Account display name, as shown by authenticators */}
+        <form onSubmit={handleDisplayName} className="space-y-2">
+          <label htmlFor="passkey-display-name" className="block text-sm font-medium text-gray-700">
+            Name shown in your passkey manager
+          </label>
+          <div className="flex flex-col sm:flex-row gap-2">
+            <input
+              id="passkey-display-name"
+              type="text"
+              value={displayName}
+              maxLength={MAX_NAME_LENGTH}
+              onChange={(e) => setDisplayName(e.target.value)}
+              className="flex-1 px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
+            />
+            <button
+              type="submit"
+              disabled={busy !== null || displayName.trim() === account.displayName}
+              className="py-2 px-4 rounded-md text-sm font-medium border border-gray-300 text-gray-800 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
+            >
+              {busy === 'displayName' ? 'Saving…' : 'Save'}
+            </button>
+          </div>
+          <p className="text-xs text-gray-500">
+            Signed in as <span className="font-medium">{account.username}</span>.
+          </p>
+        </form>
+
+        {/* Passkey list */}
+        {account.passkeys.length === 0 ? (
+          <div className="text-center border border-dashed border-gray-300 rounded-lg py-10 px-4">
+            <KeyIcon className="h-8 w-8 mx-auto text-gray-400" aria-hidden="true" />
+            <p className="mt-2 text-sm font-medium text-gray-900">No passkeys yet</p>
+            <p className="mt-1 text-sm text-gray-500">
+              {supportsWebAuthn
+                ? 'Add a passkey to sign in faster and more securely.'
+                : "This browser doesn't support passkeys."}
+            </p>
+          </div>
+        ) : (
+          <ul className="divide-y divide-gray-200 border border-gray-200 rounded-lg">
+            {account.passkeys.map((passkey) => {
+              const isEditing = editingId === passkey.id;
+              const isConfirming = confirmRemoveId === passkey.id;
+              const transports = transportLabel(passkey.transports);
+              return (
+                <li key={passkey.id} className="p-4">
+                  <div className="flex flex-col sm:flex-row sm:items-center gap-3">
+                    <div className="flex items-start gap-3 flex-1 min-w-0">
+                      <div className="w-10 h-10 rounded bg-gray-100 flex items-center justify-center shrink-0">
+                        {passkey.backedUp ? (
+                          <CloudIcon className="h-5 w-5 text-gray-600" aria-hidden="true" />
+                        ) : (
+                          <DevicePhoneMobileIcon className="h-5 w-5 text-gray-600" aria-hidden="true" />
+                        )}
+                      </div>
+                      <div className="min-w-0 flex-1">
+                        {isEditing ? (
+                          <form
+                            onSubmit={(e) => {
+                              e.preventDefault();
+                              handleRename(passkey.id);
+                            }}
+                            className="flex flex-col sm:flex-row gap-2"
+                          >
+                            <label htmlFor={`rename-${passkey.id}`} className="sr-only">
+                              Passkey name
+                            </label>
+                            <input
+                              ref={editInputRef}
+                              id={`rename-${passkey.id}`}
+                              type="text"
+                              value={editName}
+                              maxLength={MAX_NAME_LENGTH}
+                              onChange={(e) => setEditName(e.target.value)}
+                              onKeyDown={(e) => e.key === 'Escape' && setEditingId(null)}
+                              className="flex-1 px-3 py-1.5 border border-gray-300 rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
+                            />
+                            <div className="flex gap-2">
+                              <button
+                                type="submit"
+                                disabled={busy !== null}
+                                className="py-1.5 px-3 rounded-md text-sm font-medium text-white bg-gray-900 hover:bg-gray-800 disabled:opacity-60"
+                              >
+                                {busy === `rename:${passkey.id}` ? 'Saving…' : 'Save'}
+                              </button>
+                              <button
+                                type="button"
+                                onClick={() => setEditingId(null)}
+                                className="py-1.5 px-3 rounded-md text-sm font-medium border border-gray-300 text-gray-800 hover:bg-gray-50"
+                              >
+                                Cancel
+                              </button>
+                            </div>
+                          </form>
+                        ) : (
+                          <p className="font-semibold text-gray-900 truncate">{passkey.name}</p>
+                        )}
+                        <p className="mt-1 text-xs text-gray-500 flex flex-wrap gap-x-3 gap-y-1">
+                          <span>Added {formatDate(passkey.createdAt)}</span>
+                          <span>Last used: {formatDate(passkey.lastUsedAt)}</span>
+                          <span>{passkey.backedUp ? 'Synced across devices' : 'Stored on one device'}</span>
+                          {transports && <span>{transports}</span>}
+                        </p>
+                      </div>
+                    </div>
+
+                    {!isEditing && !isConfirming && (
+                      <div className="flex gap-2 sm:ml-auto">
+                        <button
+                          type="button"
+                          onClick={() => startEditing(passkey)}
+                          disabled={busy !== null}
+                          aria-label={`Rename ${passkey.name}`}
+                          className="inline-flex items-center gap-1 py-1.5 px-3 rounded-md text-sm font-medium border border-gray-300 text-gray-800 hover:bg-gray-50 disabled:opacity-50"
+                        >
+                          <PencilSquareIcon className="h-4 w-4" aria-hidden="true" />
+                          Rename
+                        </button>
+                        <button
+                          type="button"
+                          onClick={() => {
+                            setEditingId(null);
+                            setConfirmRemoveId(passkey.id);
+                          }}
+                          disabled={busy !== null}
+                          aria-label={`Remove ${passkey.name}`}
+                          className="inline-flex items-center gap-1 py-1.5 px-3 rounded-md text-sm font-medium border border-red-200 text-red-700 hover:bg-red-50 disabled:opacity-50"
+                        >
+                          <TrashIcon className="h-4 w-4" aria-hidden="true" />
+                          Remove
+                        </button>
+                      </div>
+                    )}
+                  </div>
+
+                  {isConfirming && (
+                    <div role="alertdialog" aria-labelledby={`confirm-${passkey.id}`} className="mt-3 p-3 rounded-md bg-red-50 border border-red-200">
+                      <p id={`confirm-${passkey.id}`} className="text-sm text-red-800">
+                        Remove <strong>{passkey.name}</strong>? You won't be able to sign in with it anymore
+                        {supportsSignals ? ', and your browser will stop offering it.' : '.'}
+                      </p>
+                      <div className="mt-2 flex gap-2">
+                        <button
+                          type="button"
+                          onClick={() => handleRemove(passkey)}
+                          disabled={busy !== null}
+                          className="py-1.5 px-3 rounded-md text-sm font-medium text-white bg-red-600 hover:bg-red-700 disabled:opacity-60"
+                        >
+                          {busy === `remove:${passkey.id}` ? 'Removing…' : 'Remove passkey'}
+                        </button>
+                        <button
+                          type="button"
+                          onClick={() => setConfirmRemoveId(null)}
+                          className="py-1.5 px-3 rounded-md text-sm font-medium border border-gray-300 text-gray-800 hover:bg-white"
+                        >
+                          Cancel
+                        </button>
+                      </div>
+                    </div>
+                  )}
+                </li>
+              );
+            })}
+          </ul>
+        )}
+      </div>
+    </section>
+  );
+}
