@@ -0,0 +1,43 @@
+/** Shape of the signed-in reader stored in the server-side session. */
+export interface SessionUser {
+  username: string;
+}
+
+type Session = NonNullable<import('astro').APIContext['session']>;
+
+export async function getCurrentUser(session: Session | undefined): Promise<SessionUser | null> {
+  if (!session) return null;
+  const user = await session.get('user');
+  if (user && typeof user === 'object' && typeof (user as SessionUser).username === 'string') {
+    return user as SessionUser;
+  }
+  return null;
+}
+
+export function json(body: unknown, init: ResponseInit = {}): Response {
+  return new Response(JSON.stringify(body), {
+    ...init,
+    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store', ...(init.headers ?? {}) },
+  });
+}
+
+/**
+ * Basic CSRF protection for state-changing JSON endpoints. Astro's built-in
+ * origin check is disabled in astro.config.mjs, so we require a JSON body
+ * (which forces a CORS preflight for cross-site callers) and, when the browser
+ * sends an Origin header, that it matches the host serving the request.
+ */
+export function isTrustedMutation(request: Request, { requireJson = true } = {}): boolean {
+  if (requireJson) {
+    const contentType = request.headers.get('content-type') ?? '';
+    if (!contentType.toLowerCase().startsWith('application/json')) return false;
+  }
+  const origin = request.headers.get('origin');
+  if (!origin) return true;
+  try {
+    const host = request.headers.get('x-forwarded-host') ?? request.headers.get('host') ?? new URL(request.url).host;
+    return new URL(origin).host === host;
+  } catch {
+    return false;
+  }
+}
