+import { promises as fs } from 'node:fs';
+import path from 'node:path';
+import { randomBytes } from 'node:crypto';
+import { toBase64Url } from './webauthn';
+
+export interface StoredPasskey {
+  /** base64url-encoded credential ID */
+  id: string;
+  /** base64url-encoded SubjectPublicKeyInfo, kept for future assertion verification */
+  publicKey: string | null;
+  publicKeyAlgorithm: number | null;
+  /** Reader-chosen nickname shown in account settings */
+  name: string;
+  aaguid: string | null;
+  transports: string[];
+  backedUp: boolean;
+  createdAt: string;
+  lastUsedAt: string | null;
+}
+
+interface UserRecord {
+  /** base64url-encoded WebAuthn user handle (user.id) */
+  userId: string;
+  displayName: string;
+  passkeys: StoredPasskey[];
+}
+
+type Store = Record<string, UserRecord>;
+
+const STORE_PATH = path.resolve(process.env.PASSKEY_STORE_PATH ?? '.data/passkeys.json');
+
+export const MAX_NAME_LENGTH = 64;
+
+let writeQueue: Promise<unknown> = Promise.resolve();
+
+async function readStore(): Promise<Store> {
+  try {
+    const raw = await fs.readFile(STORE_PATH, 'utf8');
+    const parsed = JSON.parse(raw);
+    return parsed && typeof parsed === 'object' ? (parsed as Store) : {};
+  } catch (err: any) {
+    if (err?.code === 'ENOENT') return {};
+    throw err;
+  }
+}
+
+async function writeStore(store: Store): Promise<void> {
+  await fs.mkdir(path.dirname(STORE_PATH), { recursive: true });
+  const tmp = `${STORE_PATH}.${process.pid}.tmp`;
+  await fs.writeFile(tmp, JSON.stringify(store, null, 2), 'utf8');
+  await fs.rename(tmp, STORE_PATH);
+}
+
+/** Serialises read-modify-write cycles so concurrent requests don't clobber each other. */
+function mutate<T>(fn: (store: Store) => T | Promise<T>): Promise<T> {
+  const run = writeQueue.then(async () => {
+    const store = await readStore();
+    const result = await fn(store);
+    await writeStore(store);
+    return result;
+  });
+  writeQueue = run.catch(() => undefined);
+  return run;
+}
+
+function ensureUser(store: Store, username: string): UserRecord {
+  if (!Object.hasOwn(store, username)) {
+    store[username] = { userId: toBase64Url(randomBytes(32)), displayName: username, passkeys: [] };
+  }
+  return store[username];
+}
+
+export function normalizeName(value: unknown): string | null {
+  if (typeof value !== 'string') return null;
+  const name = value.replace(/\s+/g, ' ').trim();
+  if (!name || name.length > MAX_NAME_LENGTH) return null;
+  return name;
+}
+
+export async function getUserRecord(username: string): Promise<UserRecord> {
+  await writeQueue;
+  const store = await readStore();
+  if (Object.hasOwn(store, username)) return store[username];
+  return mutate((s) => ensureUser(s, username));
+}
+
+export async function setDisplayName(username: string, displayName: string): Promise<UserRecord> {
+  return mutate((store) => {
+    const user = ensureUser(store, username);
+    user.displayName = displayName;
+    return user;
+  });
+}
+
+export async function addPasskey(username: string, passkey: StoredPasskey): Promise<UserRecord | null> {
+  return mutate((store) => {
+    // Credential IDs must be unique across all accounts.
+    for (const record of Object.values(store)) {
+      if (record.passkeys.some((p) => p.id === passkey.id)) return null;
+    }
+    const user = ensureUser(store, username);
+    user.passkeys.push(passkey);
+    return user;
+  });
+}
+
+export async function renamePasskey(username: string, id: string, name: string): Promise<UserRecord | null> {
+  return mutate((store) => {
+    const user = ensureUser(store, username);
+    const passkey = user.passkeys.find((p) => p.id === id);
+    if (!passkey) return null;
+    passkey.name = name;
+    return user;
+  });
+}
+
+export async function removePasskey(username: string, id: string): Promise<UserRecord | null> {
+  return mutate((store) => {
+    const user = ensureUser(store, username);
+    const before = user.passkeys.length;
+    user.passkeys = user.passkeys.filter((p) => p.id !== id);
+    return user.passkeys.length === before ? null : user;
+  });
+}
+
+/** Public representation sent to the browser (no key material). */
+export function toClientRecord(user: UserRecord) {
+  return {
+    userId: user.userId,
+    displayName: user.displayName,
+    passkeys: user.passkeys.map(({ publicKey: _pk, publicKeyAlgorithm: _alg, ...rest }) => rest),
+  };
+}
+
+export type ClientRecord = ReturnType<typeof toClientRecord>;
+export type ClientPasskey = ClientRecord['passkeys'][number];
