@@ -0,0 +1,122 @@
+import { createHash, timingSafeEqual } from 'node:crypto';
+
+export function toBase64Url(bytes: Uint8Array): string {
+  return Buffer.from(bytes).toString('base64url');
+}
+
+export function fromBase64Url(value: string): Buffer {
+  return Buffer.from(value, 'base64url');
+}
+
+export function isBase64Url(value: unknown, maxLength = 2048): value is string {
+  return typeof value === 'string' && value.length > 0 && value.length <= maxLength && /^[A-Za-z0-9_-]+$/.test(value);
+}
+
+/** Relying party ID: the effective domain the passkeys are scoped to. */
+export function getRpId(url: URL): string {
+  return url.hostname;
+}
+
+export interface RegistrationPayload {
+  id: string;
+  rawId: string;
+  type: string;
+  response: {
+    clientDataJSON: string;
+    authenticatorData: string;
+    publicKey: string | null;
+    publicKeyAlgorithm: number | null;
+    transports: string[];
+  };
+}
+
+export interface VerifiedRegistration {
+  credentialId: string;
+  aaguid: string | null;
+  backedUp: boolean;
+  publicKey: string | null;
+  publicKeyAlgorithm: number | null;
+  transports: string[];
+}
+
+const KNOWN_TRANSPORTS = new Set(['usb', 'nfc', 'ble', 'smart-card', 'hybrid', 'internal']);
+
+function formatAaguid(bytes: Buffer): string | null {
+  if (bytes.every((b) => b === 0)) return null;
+  const hex = bytes.toString('hex');
+  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
+}
+
+/**
+ * Verifies a passkey registration response (attestation "none").
+ * Throws an Error with a reader-friendly message when verification fails.
+ */
+export function verifyRegistration(
+  payload: RegistrationPayload,
+  { expectedChallenge, rpId }: { expectedChallenge: string; rpId: string },
+): VerifiedRegistration {
+  if (!payload || payload.type !== 'public-key' || !isBase64Url(payload.rawId) || payload.id !== payload.rawId) {
+    throw new Error('Malformed credential.');
+  }
+  const { response } = payload;
+  if (!response || !isBase64Url(response.clientDataJSON, 8192) || !isBase64Url(response.authenticatorData, 8192)) {
+    throw new Error('Malformed credential response.');
+  }
+
+  // 1. Client data
+  let clientData: { type?: string; challenge?: string; origin?: string };
+  try {
+    clientData = JSON.parse(fromBase64Url(response.clientDataJSON).toString('utf8'));
+  } catch {
+    throw new Error('Invalid client data.');
+  }
+  if (clientData.type !== 'webauthn.create') throw new Error('Unexpected ceremony type.');
+  const challengeA = Buffer.from(clientData.challenge ?? '');
+  const challengeB = Buffer.from(expectedChallenge);
+  if (challengeA.length !== challengeB.length || !timingSafeEqual(challengeA, challengeB)) {
+    throw new Error('Registration challenge mismatch. Please try again.');
+  }
+  let origin: URL;
+  try {
+    origin = new URL(clientData.origin ?? '');
+  } catch {
+    throw new Error('Invalid origin.');
+  }
+  const secureOrigin = origin.protocol === 'https:' || origin.hostname === 'localhost';
+  if (!secureOrigin || origin.hostname !== rpId) throw new Error('Origin mismatch.');
+
+  // 2. Authenticator data
+  const authData = fromBase64Url(response.authenticatorData);
+  if (authData.length < 37 + 18) throw new Error('Authenticator data too short.');
+  const rpIdHash = authData.subarray(0, 32);
+  const expectedHash = createHash('sha256').update(rpId).digest();
+  if (!timingSafeEqual(rpIdHash, expectedHash)) throw new Error('Relying party mismatch.');
+  const flags = authData[32];
+  const userPresent = (flags & 0x01) !== 0;
+  const backupEligible = (flags & 0x08) !== 0;
+  const backedUp = (flags & 0x10) !== 0;
+  const attestedData = (flags & 0x40) !== 0;
+  if (!userPresent) throw new Error('User presence was not confirmed.');
+  if (!attestedData) throw new Error('No credential data was returned.');
+  if (backedUp && !backupEligible) throw new Error('Invalid backup flags.');
+
+  const aaguid = authData.subarray(37, 53);
+  const credIdLength = authData.readUInt16BE(53);
+  const credId = authData.subarray(55, 55 + credIdLength);
+  if (credId.length !== credIdLength || toBase64Url(credId) !== payload.rawId) {
+    throw new Error('Credential ID mismatch.');
+  }
+
+  const transports = Array.isArray(response.transports)
+    ? response.transports.filter((t): t is string => typeof t === 'string' && KNOWN_TRANSPORTS.has(t))
+    : [];
+
+  return {
+    credentialId: payload.rawId,
+    aaguid: formatAaguid(aaguid),
+    backedUp,
+    publicKey: isBase64Url(response.publicKey, 4096) ? response.publicKey : null,
+    publicKeyAlgorithm: Number.isInteger(response.publicKeyAlgorithm) ? response.publicKeyAlgorithm : null,
+    transports,
+  };
+}
