+import type { APIRoute } from 'astro';
+import { isTrustedMutation, json } from '../../../lib/auth';
+
+const LOGIN_ENDPOINT = 'https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api/login';
+
+/**
+ * Proxies the reader's credentials to the Times login service and, on success,
+ * records the reader in the server-side session so account pages can be served.
+ */
+export const POST: APIRoute = async ({ request, session }) => {
+  if (!isTrustedMutation(request)) return json({ error: 'Forbidden' }, { status: 403 });
+  if (!session) return json({ error: 'Sessions are not available' }, { status: 500 });
+
+  let username: unknown;
+  let password: unknown;
+  try {
+    ({ username, password } = await request.json());
+  } catch {
+    return json({ error: 'Invalid request body' }, { status: 400 });
+  }
+  if (typeof username !== 'string' || typeof password !== 'string' || !username.trim() || !password) {
+    return json({ error: 'Username and password are required' }, { status: 400 });
+  }
+
+  let upstream: Response;
+  try {
+    upstream = await fetch(LOGIN_ENDPOINT, {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ username, password }),
+    });
+  } catch {
+    return json({ error: 'Login service unavailable' }, { status: 502 });
+  }
+
+  const data = await upstream.json().catch(() => ({}));
+  if (!upstream.ok) {
+    return json({ error: data?.error ?? 'Unknown error' }, { status: upstream.status });
+  }
+
+  // Prevent session fixation: issue a fresh session ID on privilege change.
+  session.regenerate();
+  session.set('user', { username: username.trim() });
+  return json({ ok: true, username: username.trim() });
+};
