+import type { APIRoute } from 'astro';
+import { getCurrentUser, isTrustedMutation, json } from '../../../lib/auth';
+import { normalizeName, removePasskey, renamePasskey, toClientRecord } from '../../../lib/passkeyStore';
+import { getRpId, isBase64Url } from '../../../lib/webauthn';
+
+/** Renames one of the signed-in reader's passkeys. */
+export const PATCH: APIRoute = async ({ request, session, params, url }) => {
+  if (!isTrustedMutation(request)) return json({ error: 'Forbidden' }, { status: 403 });
+  const user = await getCurrentUser(session);
+  if (!user) return json({ error: 'Not signed in' }, { status: 401 });
+  if (!isBase64Url(params.id)) return json({ error: 'Invalid passkey ID' }, { status: 400 });
+
+  const body = await request.json().catch(() => ({}));
+  const name = normalizeName(body?.name);
+  if (!name) return json({ error: 'Name must be 1–64 characters.' }, { status: 400 });
+
+  const record = await renamePasskey(user.username, params.id, name);
+  if (!record) return json({ error: 'Passkey not found' }, { status: 404 });
+  return json({ rpId: getRpId(url), username: user.username, ...toClientRecord(record) });
+};
+
+/** Removes one of the signed-in reader's passkeys. */
+export const DELETE: APIRoute = async ({ request, session, params, url }) => {
+  if (!isTrustedMutation(request, { requireJson: false })) return json({ error: 'Forbidden' }, { status: 403 });
+  const user = await getCurrentUser(session);
+  if (!user) return json({ error: 'Not signed in' }, { status: 401 });
+  if (!isBase64Url(params.id)) return json({ error: 'Invalid passkey ID' }, { status: 400 });
+
+  const record = await removePasskey(user.username, params.id);
+  if (!record) return json({ error: 'Passkey not found' }, { status: 404 });
+  return json({ rpId: getRpId(url), username: user.username, ...toClientRecord(record) });
+};
