+import type { APIRoute } from 'astro';
+import { getCurrentUser, isTrustedMutation, json } from '../../../lib/auth';
+import { addPasskey, getUserRecord, normalizeName, setDisplayName, toClientRecord } from '../../../lib/passkeyStore';
+import { getRpId, verifyRegistration, type RegistrationPayload } from '../../../lib/webauthn';
+
+/** Lists the signed-in reader's passkeys. */
+export const GET: APIRoute = async ({ session, url }) => {
+  const user = await getCurrentUser(session);
+  if (!user) return json({ error: 'Not signed in' }, { status: 401 });
+  const record = await getUserRecord(user.username);
+  return json({ rpId: getRpId(url), username: user.username, ...toClientRecord(record) });
+};
+
+/** Completes a passkey registration started via /api/passkeys/options. */
+export const POST: APIRoute = async ({ request, session, url }) => {
+  if (!isTrustedMutation(request)) return json({ error: 'Forbidden' }, { status: 403 });
+  const user = await getCurrentUser(session);
+  if (!user) return json({ error: 'Not signed in' }, { status: 401 });
+
+  const pending = await session!.get('passkeyRegistration');
+  session!.delete('passkeyRegistration');
+  if (!pending || pending.username !== user.username || Date.now() > pending.expiresAt) {
+    return json({ error: 'Registration expired. Please try again.' }, { status: 400 });
+  }
+
+  let body: { credential?: RegistrationPayload; name?: unknown };
+  try {
+    body = await request.json();
+  } catch {
+    return json({ error: 'Invalid request body' }, { status: 400 });
+  }
+
+  let verified;
+  try {
+    verified = verifyRegistration(body.credential as RegistrationPayload, {
+      expectedChallenge: pending.challenge,
+      rpId: getRpId(url),
+    });
+  } catch (err) {
+    return json({ error: (err as Error).message }, { status: 400 });
+  }
+
+  const existing = await getUserRecord(user.username);
+  const name = normalizeName(body.name) ?? `Passkey ${existing.passkeys.length + 1}`;
+  const record = await addPasskey(user.username, {
+    id: verified.credentialId,
+    publicKey: verified.publicKey,
+    publicKeyAlgorithm: verified.publicKeyAlgorithm,
+    name,
+    aaguid: verified.aaguid,
+    transports: verified.transports,
+    backedUp: verified.backedUp,
+    createdAt: new Date().toISOString(),
+    lastUsedAt: null,
+  });
+  if (!record) return json({ error: 'This passkey is already registered.' }, { status: 409 });
+
+  return json({ rpId: getRpId(url), username: user.username, ...toClientRecord(record) }, { status: 201 });
+};
+
+/** Updates the account display name that authenticators show next to passkeys. */
+export const PATCH: APIRoute = async ({ request, session, url }) => {
+  if (!isTrustedMutation(request)) return json({ error: 'Forbidden' }, { status: 403 });
+  const user = await getCurrentUser(session);
+  if (!user) return json({ error: 'Not signed in' }, { status: 401 });
+
+  const body = await request.json().catch(() => ({}));
+  const displayName = normalizeName(body?.displayName);
+  if (!displayName) return json({ error: 'Display name must be 1–64 characters.' }, { status: 400 });
+
+  const record = await setDisplayName(user.username, displayName);
+  return json({ rpId: getRpId(url), username: user.username, ...toClientRecord(record) });
+};
