+import type { APIRoute } from 'astro';
+import { randomBytes } from 'node:crypto';
+import { getCurrentUser, isTrustedMutation, json } from '../../../lib/auth';
+import { getUserRecord } from '../../../lib/passkeyStore';
+import { getRpId, toBase64Url } from '../../../lib/webauthn';
+
+const REGISTRATION_TIMEOUT_MS = 5 * 60 * 1000;
+
+/** Issues PublicKeyCredentialCreationOptions (JSON form) for adding a passkey. */
+export const POST: APIRoute = async ({ request, session, url }) => {
+  if (!isTrustedMutation(request)) return json({ error: 'Forbidden' }, { status: 403 });
+  const user = await getCurrentUser(session);
+  if (!user) return json({ error: 'Not signed in' }, { status: 401 });
+
+  const record = await getUserRecord(user.username);
+  const challenge = toBase64Url(randomBytes(32));
+  session!.set('passkeyRegistration', {
+    username: user.username,
+    challenge,
+    expiresAt: Date.now() + REGISTRATION_TIMEOUT_MS,
+  });
+
+  return json({
+    challenge,
+    rp: { id: getRpId(url), name: 'The DevTools Times' },
+    user: { id: record.userId, name: user.username, displayName: record.displayName },
+    pubKeyCredParams: [
+      { type: 'public-key', alg: -7 }, // ES256
+      { type: 'public-key', alg: -8 }, // EdDSA
+      { type: 'public-key', alg: -257 }, // RS256
+    ],
+    excludeCredentials: record.passkeys.map((p) => ({ type: 'public-key', id: p.id, transports: p.transports })),
+    authenticatorSelection: { residentKey: 'required', requireResidentKey: true, userVerification: 'preferred' },
+    attestation: 'none',
+    timeout: REGISTRATION_TIMEOUT_MS,
+  });
+};

