+          const err = new Error('Request failed with status ' + res.status);
+          err.status = res.status;
+          throw err;
+        }
+        return data;
+      }
+
+      async function isWebAuthnSupported() {
+        return (
+          window.isSecureContext &&
+          typeof window.PublicKeyCredential === 'function' &&
+          !!navigator.credentials &&
+          typeof navigator.credentials.create === 'function'
+        );
+      }
+
+      async function registerPasskey() {
+        if (inFlight) return; // prevent concurrent ceremonies / double clicks
+
+        if (!(await isWebAuthnSupported())) {
+          setStatus('Passkeys are not supported on this browser or device.', 'error');
+          return;
+        }
+
+        const controller = new AbortController();
+        inFlight = controller;
+        button.disabled = true;
+        button.setAttribute('aria-busy', 'true');
+        setStatus('Preparing passkey…');
+
+        let credential = null;
+        let rpId = null;
+
+        try {
+          // 1. Fetch server-generated options (challenge must come from the server).
+          const optionsResponse = await postJSON('/api/register/options', { promotion: true }, controller.signal);
+          const optionsJSON = optionsResponse && optionsResponse.publicKey
+            ? optionsResponse.publicKey
+            : optionsResponse;
+          if (!optionsJSON || !optionsJSON.challenge || !optionsJSON.user || !optionsJSON.rp) {
+            throw new Error('Invalid registration options received from server');
+          }
+          rpId = optionsJSON.rp.id || window.location.hostname;
+
+          const publicKey = parseCreationOptions(optionsJSON);
+
+          // 2. Create the credential with the authenticator.
+          setStatus('Follow your device prompt to create a passkey…');
+          credential = await navigator.credentials.create({ publicKey, signal: controller.signal });
+          if (!credential) throw new Error('No credential was created');
+
+          // 3. Send the attestation to the server for verification.
+          setStatus('Verifying passkey…');
+          const result = await postJSON('/api/register/verify', credentialToJSON(credential), controller.signal);
+          if (result && (result.verified === false || result.success === false)) {
+            throw Object.assign(new Error('Server could not verify passkey'), { verifyFailed: true });
+          }
+
+          setStatus('Passkey created! You can now sign in with it.', 'success');
+        } catch (err) {
+          // If the authenticator created a credential but the server rejected it,
+          // tell the passkey provider so it can remove the orphaned passkey.
+          if (credential && rpId && typeof PublicKeyCredential.signalUnknownCredential === 'function') {
+            PublicKeyCredential.signalUnknownCredential({
+              rpId,
+              credentialId: credential.id,
+            }).catch(() => {});
+          }
+          setStatus(describeError(err), 'error');
+        } finally {
+          inFlight = null;
+          button.disabled = false;
+          button.removeAttribute('aria-busy');
+        }
+      }
+
+      function describeError(err) {
+        switch (err && err.name) {
+          case 'NotAllowedError':
+            return 'Passkey creation was cancelled or timed out.';
+          case 'InvalidStateError':
+            return 'A passkey for this account already exists on this device.';
+          case 'AbortError':
+            return 'Passkey creation was cancelled.';
+          case 'SecurityError':
+            return 'Passkey creation is not allowed on this site.';
+          case 'NotSupportedError':
+            return 'Your device does not support the requested passkey type.';
+          default:
+            if (err && err.status === 401) return 'Please sign in again before creating a passkey.';
+            return 'Something went wrong creating your passkey. Please try again.';
+        }
+      }
+
+      button.addEventListener('click', registerPasskey);
+    })();
+  </script>
+
