--- /dev/null
+++ b/js/account-api.js
@@ -0,0 +1,94 @@
+/**
+ * HTTP client for the Daily Grind account + passkey backend.
+ *
+ * Backend contract (JSON bodies, same-origin session cookie). The server MUST
+ * generate/verify WebAuthn ceremonies with a vetted library (e.g. SimpleWebAuthn),
+ * store challenges in the session, and use a constant RP ID.
+ *
+ *   GET    /api/session                -> 200 { user: { name, displayName } } | 401
+ *   POST   /api/auth/logout            -> 204
+ *
+ *   Registration (new customer)
+ *   POST   /api/auth/signup/options    { name, displayName } -> PublicKeyCredentialCreationOptionsJSON
+ *                                         (409 if the email is taken; residentKey "required")
+ *   POST   /api/auth/signup/verify     RegistrationResponseJSON -> { user }   (signs the user in)
+ *
+ *   Sign-in
+ *   POST   /api/auth/passkey/options   -> PublicKeyCredentialRequestOptionsJSON (allowCredentials: [])
+ *   POST   /api/auth/passkey/verify    AuthenticationResponseJSON -> { user } | 404 unknown credential
+ *   POST   /api/auth/password          { username, password } -> { user } | 401
+ *
+ *   Passkey management (signed in)
+ *   GET    /api/passkeys               -> { rpId, userId, credentials: StoredPasskeyCredential[] }
+ *   POST   /api/passkeys/options       { promotion: boolean } -> creation options (excludeCredentials set)
+ *   POST   /api/passkeys/verify        RegistrationResponseJSON -> StoredPasskeyCredential
+ *   PATCH  /api/passkeys/:id           { name } -> StoredPasskeyCredential
+ *   DELETE /api/passkeys/:id           -> 204 | 403 { error: "reauth_required" }
+ *
+ *   Profile (signed in)
+ *   PUT    /api/user                   { name, displayName } -> { name, displayName, rpId, userId }
+ *                                         | 403 { error: "reauth_required" } | 409 email taken
+ *
+ *   Reauthentication (signed in; marks the session as recently verified, e.g. 5 min)
+ *   POST   /api/reauth/options         -> request options, allowCredentials = this user's passkeys only
+ *   POST   /api/reauth/verify          AuthenticationResponseJSON -> 204 | 404 | 403 (other user's passkey)
+ *   POST   /api/reauth/password        { password } -> 204 | 401
+ *
+ * All IDs (credential id, userId) are unpadded Base64URL strings.
+ */
+
+export class ApiError extends Error {
+  constructor(response, body) {
+    super(body?.message || body?.error || `Request failed (${response.status})`);
+    this.name = 'ApiError';
+    this.status = response.status;
+    this.code = body?.error;
+  }
+}
+
+async function request(method, path, body) {
+  const response = await fetch(path, {
+    method,
+    credentials: 'same-origin',
+    headers: {
+      Accept: 'application/json',
+      // Custom header: simple cross-site form posts can't set it (CSRF defence in depth).
+      'X-Requested-With': 'fetch',
+      ...(body !== undefined && { 'Content-Type': 'application/json' }),
+    },
+    body: body === undefined ? undefined : JSON.stringify(body),
+  });
+  const text = await response.text();
+  let data = null;
+  if (text) {
+    try { data = JSON.parse(text); } catch { data = null; }
+  }
+  if (!response.ok) throw new ApiError(response, data);
+  return data;
+}
+
+export const api = {
+  session: () => request('GET', '/api/session'),
+  logout: () => request('POST', '/api/auth/logout'),
+
+  signupOptions: (profile) => request('POST', '/api/auth/signup/options', profile),
+  signupVerify: (credential) => request('POST', '/api/auth/signup/verify', credential),
+
+  signinOptions: () => request('POST', '/api/auth/passkey/options'),
+  signinVerify: (credential) => request('POST', '/api/auth/passkey/verify', credential),
+  passwordSignin: (username, password) =>
+    request('POST', '/api/auth/password', { username, password }),
+
+  listPasskeys: () => request('GET', '/api/passkeys'),
+  passkeyOptions: (promotion = false) => request('POST', '/api/passkeys/options', { promotion }),
+  passkeyVerify: (credential) => request('POST', '/api/passkeys/verify', credential),
+  renamePasskey: (id, name) =>
+    request('PATCH', `/api/passkeys/${encodeURIComponent(id)}`, { name }),
+  deletePasskey: (id) => request('DELETE', `/api/passkeys/${encodeURIComponent(id)}`),
+
+  updateUser: (profile) => request('PUT', '/api/user', profile),
+
+  reauthOptions: () => request('POST', '/api/reauth/options'),
+  reauthVerify: (credential) => request('POST', '/api/reauth/verify', credential),
+  reauthPassword: (password) => request('POST', '/api/reauth/password', { password }),
+};
