+  createPasskeyUnsupported: $('#create-passkey-unsupported'),
+  signoutBtn: $('#signout-btn'),
+
+  renameDialog: $('#rename-dialog'),
+  renameInput: $('#rename-input'),
+  deleteDialog: $('#delete-dialog'),
+  deleteName: $('#delete-passkey-name'),
+
+  reauthDialog: $('#reauth-dialog'),
+  reauthReason: $('#reauth-reason'),
+  reauthStatus: $('#reauth-status'),
+  reauthPasskeyBtn: $('#reauth-passkey-btn'),
+  reauthPasswordForm: $('#reauth-password-form'),
+  reauthPasswordDetails: $('#reauth-password-details'),
+};
+
+const state = {
+  user: null,
+  passkeys: [],
