+    item.dataset.id = passkey.id;
+
+    const icon = $('.passkey-icon', item);
+    icon.src = passkey.providerIcon || DEFAULT_PASSKEY_ICON;
+
+    $('.passkey-name', item).textContent = passkey.name || 'Passkey';
+
+    const created = `Created ${dateFormat.format(new Date(passkey.registeredAt))}`;
+    const used = passkey.lastUsedAt
+      ? `Last used ${dateFormat.format(new Date(passkey.lastUsedAt))}`
+      : 'Never used';
+    const synced = passkey.credentialBackedUp ? ' · Synced' : '';
