+
+async function loadPasskeys() {
+  const { rpId, userId, credentials } = await api.listPasskeys();
+  state.passkeys = credentials ?? [];
+  renderPasskeys();
+  // Keep password managers in lockstep with the server's accepted credentials.
+  await signalAcceptedCredentials(rpId, userId, state.passkeys);
