+
+/* ---------- Session ---------- */
+
+async function onSignedIn(user, message) {
+  stopConditionalSignin();
+  state.user = user;
+  els.signinForm.reset();
+  els.signupForm.reset();
+  render();
+  setStatus(message, 'success');
+  try {
+    await loadPasskeys();
+  } catch (err) {
+    setStatus(`Signed in, but we couldn’t load your passkeys. ${errorMessage(err)}`, 'error');
+  }
