+/** Resolves true when WebAuthn is usable, loading the JSON/capabilities polyfill only if needed. */
+export function webauthnReady() {
+  readyPromise ??= (async () => {
+    if (!window.isSecureContext || !window.PublicKeyCredential) return false;
+    const PKC = window.PublicKeyCredential;
+    const missing =
+      !PKC.getClientCapabilities ||
+      !PKC.parseCreationOptionsFromJSON ||
+      !PKC.parseRequestOptionsFromJSON ||
+      !PKC.prototype.toJSON;
+    if (missing) {
+      try {
+        await import(POLYFILL_URL);
+      } catch (err) {
+        console.warn('WebAuthn polyfill failed to load:', err);
+        return false;
+      }
+    }
+    return true;
+  })();
+  return readyPromise;
+}
+
+export async function getCapabilities() {
+  if (!(await webauthnReady())) return {};
+  try {
+    return await PublicKeyCredential.getClientCapabilities();
+  } catch {
+    return {};
+  }
+}
+
+/** Gate for passkey creation: platform authenticator plus conditional UI sign-in support. */
+export async function canCreatePasskeys() {
+  const caps = await getCapabilities();
+  return Boolean(caps.passkeyPlatformAuthenticator && caps.conditionalGet);
+}
+
+export async function canUseConditionalGet() {
+  const caps = await getCapabilities();
+  return caps.conditionalGet === true;
+}
