+/** User-facing error for passkey ceremonies. `cancelled` errors should be shown quietly or not at all. */
+export class PasskeyError extends Error {
+  constructor(message, { cancelled = false, cause } = {}) {
+    super(message, { cause });
+    this.name = 'PasskeyError';
+    this.cancelled = cancelled;
+  }
+}
+
+function mapCeremonyError(err, kind) {
+  switch (err?.name) {
+    case 'NotAllowedError':
+      return new PasskeyError(
+        kind === 'create' ? 'Passkey creation was cancelled.' : 'Passkey sign-in was cancelled.',
+        { cancelled: true, cause: err },
