+    case 'AbortError':
+      return new PasskeyError('The passkey request was cancelled.', { cancelled: true, cause: err });
+    case 'InvalidStateError':
+      return new PasskeyError('You already have a passkey for this account on this device or password manager.', { cause: err });
+    case 'SecurityError':
+      return new PasskeyError('Passkeys aren’t available on this connection. Please contact support.', { cause: err });
+    default:
+      return new PasskeyError('Something went wrong with your passkey. Please try again.', { cause: err });
+  }
