+  if (!PublicKeyCredential.signalUnknownCredential || !rpId || !isValidBase64Url(credentialId)) return;
+  try {
+    await PublicKeyCredential.signalUnknownCredential({ rpId, credentialId });
+  } catch (err) {
+    console.warn('signalUnknownCredential sync warning:', err);
+  }
+}
+
+/**
+ * Runs navigator.credentials.create() with server JSON options, then server verification.
+ * If verification fails, the orphaned credential is reported via signalUnknownCredential.
+ */
+export async function createPasskey(optionsJSON, verify) {
+  if (!(await webauthnReady())) throw new PasskeyError('This browser doesn’t support passkeys.');
+  const publicKey = PublicKeyCredential.parseCreationOptionsFromJSON(optionsJSON);
