+:root {
+  --primary: #4e342e;
+  --secondary: #d7ccc8;
+  --accent: #ffab40;
+  --text: #3e2723;
+  --light: #fafafa;
+  --muted: #6d5c57;
+  --danger: #b3261e;
+  --success: #2e7d32;
+  --border: #e6dcd8;
+}
+
+* {
+  box-sizing: border-box;
+  margin: 0;
+  padding: 0;
+}
+
+[hidden] {
+  display: none !important;
+}
+
+body {
+  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
+  line-height: 1.6;
+  color: var(--text);
+  background-color: var(--light);
+}
+
+/* Navigation (matches homepage) */
+nav {
+  background: var(--primary);
+  color: white;
+  padding: 1rem 5%;
+  display: flex;
+  justify-content: space-between;
+  align-items: center;
+  position: sticky;
+  top: 0;
+  z-index: 1000;
+}
+
+.logo {
+  font-size: 1.5rem;
+  font-weight: bold;
+  letter-spacing: 1px;
+}
+
+nav ul {
+  display: flex;
+  list-style: none;
+  align-items: center;
+}
+
+nav ul li {
+  margin-left: 20px;
+}
+
+nav a {
+  color: white;
+  text-decoration: none;
+  font-size: 0.9rem;
+  transition: color 0.3s;
+}
+
+nav a:hover,
+nav a[aria-current="page"] {
+  color: var(--accent);
+}
+
+.logout-link {
+  border: 1px solid var(--accent);
+  padding: 5px 12px;
+  border-radius: 4px;
+}
+
+/* Hero */
+.account-hero {
+  background: linear-gradient(rgba(0, 0, 0, 0.55), rgba(0, 0, 0, 0.55)),
+    url('https://images.unsplash.com/photo-1442512595331-e89e73853f31?auto=format&fit=crop&w=1350&q=80');
+  background-size: cover;
+  background-position: center;
+  color: white;
+  text-align: center;
+  padding: 60px 20px;
+}
+
+.account-hero h1 {
+  font-size: 2.5rem;
+  margin-bottom: 0.25rem;
+}
+
+.container {
+  max-width: 1100px;
+  margin: 40px auto;
+  padding: 0 20px;
+}
+
+h2,
+h3,
+h4 {
+  color: var(--primary);
+  line-height: 1.3;
+}
+
+.muted {
+  color: var(--muted);
+  font-size: 0.9rem;
+}
+
+.center {
+  text-align: center;
+}
+
+/* Panels */
+.panel {
+  background: white;
+  padding: 24px;
+  border-radius: 8px;
+  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
+}
+
+.panel-head {
+  display: flex;
+  justify-content: space-between;
+  align-items: flex-start;
+  gap: 16px;
+  margin-bottom: 16px;
+}
+
+/* Buttons */
+.btn {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  gap: 8px;
+  background: var(--primary);
+  color: white;
+  padding: 10px 20px;
+  border: 1px solid var(--primary);
+  border-radius: 5px;
+  font: inherit;
+  font-size: 0.95rem;
+  cursor: pointer;
+  text-decoration: none;
+  transition: background 0.3s, opacity 0.2s;
+  white-space: nowrap;
+}
+
+.btn:hover {
+  background: #3e2723;
+}
+
+.btn:focus-visible,
+.link:focus-visible,
+.tabs button:focus-visible,
+input:focus-visible {
+  outline: 3px solid var(--accent);
+  outline-offset: 2px;
+}
+
+.btn[disabled],
+.btn[aria-busy="true"] {
+  opacity: 0.6;
+  cursor: progress;
+}
+
+.btn-block {
+  width: 100%;
+  margin-top: 8px;
+}
+
+.btn-small {
+  padding: 6px 14px;
+  font-size: 0.85rem;
+}
+
+.btn-outline {
+  background: transparent;
+  color: var(--primary);
+}
+
+.btn-outline:hover {
+  background: var(--secondary);
+}
+
+.btn-danger {
+  background: var(--danger);
+  border-color: var(--danger);
+  color: white;
+}
+
+.btn-danger:hover {
+  background: #8c1d18;
+}
+
+.link {
+  background: none;
+  border: none;
+  color: var(--primary);
+  font: inherit;
+  text-decoration: underline;
+  cursor: pointer;
+}
+
+.key-icon {
+  display: inline-block;
+  width: 1.1em;
+  height: 1.1em;
+  background: currentColor;
+  -webkit-mask: url('/assets/passkey.svg') center / contain no-repeat;
+  mask: url('/assets/passkey.svg') center / contain no-repeat;
+}
+
+/* Forms */
+label {
+  display: block;
+  font-weight: 600;
+  font-size: 0.9rem;
+  margin: 14px 0 4px;
+}
+
+input[type="text"],
+input[type="email"] {
+  width: 100%;
+  padding: 10px 12px;
+  border: 1px solid #bcaaa4;
+  border-radius: 5px;
+  font: inherit;
+  background: white;
+  color: var(--text);
+}
+
+input[aria-invalid="true"] {
+  border-color: var(--danger);
+}
+
+.hint {
+  color: var(--muted);
+  font-size: 0.82rem;
+  margin: 6px 0 10px;
+}
+
+.form-error {
+  background: #fdecea;
+  color: var(--danger);
+  border-radius: 5px;
+  padding: 8px 12px;
+  font-size: 0.88rem;
+  margin-top: 12px;
+}
+
+.actions {
+  display: flex;
+  justify-content: flex-end;
+  gap: 10px;
+  margin-top: 16px;
+}
+
+/* Toast */
+.toast {
+  position: fixed;
+  left: 50%;
+  bottom: 24px;
+  transform: translateX(-50%);
+  background: var(--primary);
+  color: white;
+  padding: 12px 20px;
+  border-radius: 6px;
+  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.25);
+  z-index: 2000;
+  max-width: min(90vw, 520px);
+  text-align: center;
+}
+
+.toast.error {
+  background: var(--danger);
+}
+
+/* Signed-out layout */
+.auth-layout {
+  display: grid;
+  grid-template-columns: 1fr minmax(320px, 420px);
+  gap: 40px;
+  align-items: start;
+}
+
+.perks {
+  list-style: none;
+  margin: 16px 0;
+}
+
+.perks li {
+  padding: 10px 0 10px 32px;
+  position: relative;
+  border-bottom: 1px solid var(--border);
+}
+
+.perks li::before {
+  content: '☕';
+  position: absolute;
+  left: 0;
+}
+
+.explainer {
+  background: white;
+  border-radius: 8px;
+  padding: 12px 16px;
+  border: 1px solid var(--border);
+}
+
+.explainer summary {
+  cursor: pointer;
+  font-weight: 600;
+  color: var(--primary);
+}
+
+.explainer p {
+  margin-top: 8px;
+  font-size: 0.92rem;
+}
+
+.tabs {
+  display: flex;
+  border-bottom: 2px solid var(--border);
+  margin-bottom: 8px;
+}
+
+.tabs button {
+  flex: 1;
+  background: none;
+  border: none;
+  font: inherit;
+  font-weight: 600;
+  padding: 10px;
+  color: var(--muted);
+  cursor: pointer;
+  border-bottom: 3px solid transparent;
+  margin-bottom: -2px;
+}
+
+.tabs button[aria-selected="true"] {
+  color: var(--primary);
+  border-bottom-color: var(--accent);
+}
+
+.switch {
+  text-align: center;
+  margin-top: 16px;
+  font-size: 0.9rem;
+}
+
+/* Signed-in layout */
+.welcome {
+  display: flex;
+  justify-content: space-between;
+  align-items: center;
+  gap: 16px;
+  margin-bottom: 24px;
+}
+
+.account-grid {
+  display: grid;
+  grid-template-columns: repeat(2, 1fr);
+  gap: 20px;
+}
+
+.passkeys-panel {
+  grid-column: 1 / -1;
+}
+
+.profile-view {
+  display: grid;
+  grid-template-columns: max-content 1fr;
+  gap: 8px 20px;
+}
+
+.profile-view dt {
+  font-weight: 600;
+  color: var(--muted);
+}
+
+.profile-view dd {
+  word-break: break-word;
+}
+
+.reauth-status {
+  display: flex;
+  gap: 12px;
+  align-items: flex-start;
+  margin-bottom: 12px;
+}
+
+.status-dot {
+  flex: none;
+  width: 12px;
+  height: 12px;
+  border-radius: 50%;
+  margin-top: 6px;
+  background: #9e9e9e;
+}
+
+.reauth-status.fresh .status-dot {
+  background: var(--success);
+}
+
+.danger-zone {
+  margin-top: 24px;
+  padding-top: 16px;
+  border-top: 1px solid var(--border);
+}
+
+.danger-zone h4 {
+  color: var(--danger);
+}
+
+.danger-zone .btn {
+  margin-top: 8px;
+}
+
+/* Passkey list */
+.passkey-list {
+  list-style: none;
+}
+
+.passkey {
+  display: flex;
+  align-items: center;
+  gap: 16px;
+  padding: 14px 0;
+  border-top: 1px solid var(--border);
+}
+
+.passkey-icon {
+  flex: none;
+  width: 44px;
+  height: 44px;
+  border-radius: 10px;
+  background: var(--secondary);
+  color: var(--primary);
+  display: grid;
+  place-items: center;
+}
+
+.passkey-icon .key-icon {
+  width: 24px;
+  height: 24px;
+}
+
+.passkey-main {
+  flex: 1;
+  min-width: 0;
+}
+
+.passkey-name {
+  font-weight: 600;
+  overflow-wrap: anywhere;
+}
+
+.passkey-meta {
+  font-size: 0.82rem;
+  color: var(--muted);
+}
+
+.badge {
+  display: inline-block;
+  font-size: 0.72rem;
+  font-weight: 600;
+  padding: 1px 8px;
+  border-radius: 999px;
+  background: #efebe9;
+  color: var(--primary);
+  margin-left: 6px;
+  vertical-align: middle;
+}
+
+.badge.synced {
+  background: #e8f5e9;
+  color: var(--success);
+}
+
+.badge.current {
+  background: #fff3e0;
+  color: #a65c00;
+}
+
+.passkey-actions {
+  display: flex;
+  gap: 8px;
+  flex-wrap: wrap;
+  justify-content: flex-end;
+}
+
+/* Dialogs */
+dialog {
+  border: none;
+  border-radius: 10px;
+  padding: 0;
+  width: min(92vw, 440px);
+  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.3);
+  margin: auto;
+}
+
+dialog::backdrop {
+  background: rgba(30, 20, 15, 0.55);
+}
+
+.dialog-body {
+  padding: 24px;
+}
+
+.dialog-body h3 {
+  margin-bottom: 8px;
+}
+
+footer {
+  background: var(--secondary);
+  text-align: center;
+  padding: 40px 20px;
+  margin-top: 40px;
+}
+
+.footer-links {
+  margin-bottom: 20px;
+}
+
+.footer-links a {
+  margin: 0 10px;
+  color: var(--text);
+  text-decoration: none;
+  font-size: 0.85rem;
+}
+
+@media (max-width: 800px) {
+  .auth-layout,
+  .account-grid {
+    grid-template-columns: 1fr;
+  }
+
+  .auth-card {
+    order: -1;
+  }
+
+  nav {
+    flex-direction: column;
+    gap: 8px;
+  }
+
+  nav ul li {
+    margin: 0 8px;
+  }
+
+  .passkey {
+    flex-wrap: wrap;
+  }
+
+  .passkey-actions {
+    width: 100%;
+    justify-content: flex-start;
+  }
+}
