@@ -0,0 +1,709 @@
+import {
+  isSupported,
+  isConditionalMediationAvailable,
+  createPasskey,
+  getPasskey,
+  isCancellation,
+  describeError,
+  signalUnknownCredential,
+  signalAllAcceptedCredentials,
+  signalCurrentUserDetails,
+} from '/assets/webauthn.js';
+
+const $ = (sel, root = document) => root.querySelector(sel);
+const $$ = (sel, root = document) => [...root.querySelectorAll(sel)];
+
+let session = { signedIn: false, rpId: location.hostname };
+let currentTab = 'signin';
+
+/* -------------------------------------------------------------------------- */
+/* API                                                                        */
+/* -------------------------------------------------------------------------- */
+
+class ApiError extends Error {
+  constructor(status, data) {
+    super(data?.error || `Request failed (${status}).`);
+    this.status = status;
+    this.code = data?.code;
+    this.data = data || {};
+  }
+}
+
+async function api(method, path, body) {
+  const res = await fetch(path, {
+    method,
+    credentials: 'same-origin',
+    headers: { Accept: 'application/json', ...(body !== undefined ? { 'Content-Type': 'application/json' } : {}) },
+    body: body !== undefined ? JSON.stringify(body) : undefined,
+  });
+  let data = null;
+  try {
+    data = await res.json();
+  } catch { /* non-JSON response */ }
+  if (!res.ok) {
+    const err = new ApiError(res.status, data);
+    if (err.code === 'signed_out' && session.signedIn) {
+      // Session expired in the background – go back to the sign-in screen.
+      setSession({ signedIn: false, rpId: session.rpId });
+      toast('Your session has ended. Please sign in again.', { error: true });
+    }
+    throw err;
+  }
+  return data;
+}
+
+/* -------------------------------------------------------------------------- */
+/* Ceremony management                                                        */
+/* -------------------------------------------------------------------------- */
+
+// Only one WebAuthn request may be pending at a time. Starting a new one aborts
+// the previous (e.g. the background autofill request when a button is pressed).
+let ceremony = null;
+
+function newCeremony() {
+  ceremony?.abort(new DOMException('Superseded by another passkey request.', 'AbortError'));
+  ceremony = new AbortController();
+  return ceremony.signal;
+}
+
+function cancelCeremony() {
+  ceremony?.abort(new DOMException('Cancelled.', 'AbortError'));
+  ceremony = null;
+}
+
+/** Hides stale passkeys in the user's password manager when the server no longer knows them. */
+function handleUnknownCredential(err) {
+  if (err instanceof ApiError && err.code === 'unknown_credential' && err.data.credentialId) {
+    signalUnknownCredential(session.rpId, err.data.credentialId);
+  }
+}
+
+/** Tells passkey providers which passkeys are still valid and what the account is called. */
+function syncProviders() {
+  if (!session.signedIn) return;
+  const { user, passkeys, rpId } = session;
+  signalAllAcceptedCredentials(rpId, user.webauthnUserId, passkeys.map((p) => p.id));
+  signalCurrentUserDetails(rpId, user.webauthnUserId, user.email, user.displayName);
+}
+
+/* -------------------------------------------------------------------------- */
+/* UI helpers                                                                 */
+/* -------------------------------------------------------------------------- */
+
+let toastTimer;
+function toast(message, { error = false } = {}) {
+  const el = $('#toast');
+  el.textContent = message;
+  el.classList.toggle('error', error);
+  el.hidden = false;
+  clearTimeout(toastTimer);
+  toastTimer = setTimeout(() => (el.hidden = true), 5000);
+}
+
+function showError(el, message) {
+  el.textContent = message || '';
+  el.hidden = !message;
+}
+
+async function busy(button, fn) {
+  if (button.getAttribute('aria-busy') === 'true') return;
+  button.setAttribute('aria-busy', 'true');
+  button.disabled = true;
+  try {
+    return await fn();
+  } finally {
+    button.removeAttribute('aria-busy');
+    button.disabled = false;
+  }
+}
+
+const dateFmt = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium' });
+const dateTimeFmt = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' });
+const relFmt = new Intl.RelativeTimeFormat(undefined, { numeric: 'auto' });
+
+function relativeTime(iso) {
+  const diff = (new Date(iso).getTime() - Date.now()) / 1000;
+  const units = [
+    ['year', 31536000], ['month', 2592000], ['week', 604800],
+    ['day', 86400], ['hour', 3600], ['minute', 60],
+  ];
+  for (const [unit, secs] of units) {
+    if (Math.abs(diff) >= secs) return relFmt.format(Math.round(diff / secs), unit);
+  }
+  return 'just now';
+}
+
+function setInvalid(input, invalid) {
+  if (invalid) input.setAttribute('aria-invalid', 'true');
+  else input.removeAttribute('aria-invalid');
+}
+
+const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+
+/* -------------------------------------------------------------------------- */
+/* Rendering                                                                  */
+/* -------------------------------------------------------------------------- */
+
+function setSession(next) {
+  session = next;
+  render();
+}
+
+function showView(id) {
+  for (const v of ['view-loading', 'view-unsupported', 'view-signed-out', 'view-signed-in']) {
+    $(`#${v}`).hidden = v !== id;
+  }
+}
+
+function render() {
+  window.dgRenderAuthNav?.(session.signedIn);
+
+  if (!session.signedIn) {
+    stopReauthTicker();
+    if (!isSupported()) return showView('view-unsupported');
+    showView('view-signed-out');
+    selectTab(currentTab, { focus: false });
+    return;
+  }
+
+  cancelCeremony(); // drop any pending autofill request
+  showView('view-signed-in');
+  const { user } = session;
+  for (const el of $$('[data-bind="displayName"]')) el.textContent = user.displayName;
+  for (const el of $$('[data-bind="email"]')) el.textContent = user.email;
+  for (const el of $$('[data-bind="memberSince"]')) el.textContent = dateFmt.format(new Date(user.createdAt));
+  renderPasskeys();
+  startReauthTicker();
+}
+
+function renderPasskeys() {
+  const list = $('#passkey-list');
+  list.replaceChildren();
+  const onlyOne = session.passkeys.length <= 1;
+
+  for (const pk of session.passkeys) {
+    const li = document.createElement('li');
+    li.className = 'passkey';
+    li.dataset.id = pk.id;
+
+    const icon = document.createElement('div');
+    icon.className = 'passkey-icon';
+    icon.innerHTML = '<span class="key-icon" aria-hidden="true"></span>';
+
+    const main = document.createElement('div');
+    main.className = 'passkey-main';
+    const name = document.createElement('div');
+    name.className = 'passkey-name';
+    name.textContent = pk.name;
+    const badge = document.createElement('span');
+    badge.className = pk.synced ? 'badge synced' : 'badge';
+    badge.textContent = pk.synced ? 'Synced' : 'This device only';
+    badge.title = pk.synced
+      ? 'Backed up and available on your other devices signed in to the same password manager.'
+      : 'Stored only on the device or security key that created it.';
+    name.append(badge);
+
+    const meta = document.createElement('div');
+    meta.className = 'passkey-meta';
+    const parts = [];
+    if (pk.provider && pk.provider.name !== pk.name) parts.push(pk.provider.name);
+    parts.push(`Created ${dateFmt.format(new Date(pk.createdAt))}`);
+    parts.push(pk.lastUsedAt ? `Last used ${relativeTime(pk.lastUsedAt)}` : 'Not used to sign in yet');
+    meta.textContent = parts.join(' · ');
+    if (pk.lastUsedAt) meta.title = `Last used ${dateTimeFmt.format(new Date(pk.lastUsedAt))}`;
+    main.append(name, meta);
+
+    const actions = document.createElement('div');
+    actions.className = 'passkey-actions';
+    const rename = document.createElement('button');
+    rename.type = 'button';
+    rename.className = 'btn btn-small btn-outline';
+    rename.textContent = 'Rename';
+    rename.setAttribute('aria-label', `Rename passkey ${pk.name}`);
+    rename.addEventListener('click', () => openRename(pk));
+    const del = document.createElement('button');
+    del.type = 'button';
+    del.className = 'btn btn-small btn-outline';
+    del.textContent = 'Remove';
+    del.setAttribute('aria-label', `Remove passkey ${pk.name}`);
+    if (onlyOne) {
+      del.disabled = true;
+      del.title = 'This is your only passkey. Create another one before removing it.';
+    }
+    del.addEventListener('click', () => removePasskey(pk, del));
+    actions.append(rename, del);
+
+    li.append(icon, main, actions);
+    list.append(li);
+  }
+
+  if (onlyOne) {
+    const tip = document.createElement('li');
+    tip.className = 'hint';
+    tip.textContent = 'Tip: add a passkey on a second device or password manager so you can still sign in if you lose this one.';
+    list.append(tip);
+  }
+}
+
+/* ---- Reauthentication status ---- */
+
+let reauthTicker;
+
+function startReauthTicker() {
+  stopReauthTicker();
+  updateReauthStatus();
+  reauthTicker = setInterval(updateReauthStatus, 1000);
+}
+
+function stopReauthTicker() {
+  clearInterval(reauthTicker);
+}
+
+function updateReauthStatus() {
+  const box = $('#reauth-status');
+  const remaining = session.reauthExpiresAt ? new Date(session.reauthExpiresAt).getTime() - Date.now() : 0;
+  const fresh = remaining > 0;
+  box.classList.toggle('fresh', fresh);
+  if (fresh) {
+    const mins = Math.floor(remaining / 60000);
+    const secs = String(Math.floor((remaining % 60000) / 1000)).padStart(2, '0');
+    $('#reauth-title').textContent = 'Identity confirmed';
+    $('#reauth-detail').textContent = `You can change your email and manage passkeys without confirming again for ${mins}:${secs}.`;
+    $('#reauth-button').hidden = true;
+  } else {
+    $('#reauth-title').textContent = 'Protected';
+    $('#reauth-detail').textContent = 'We’ll ask you to confirm with a passkey before sensitive changes such as updating your email or managing passkeys.';
+    $('#reauth-button').hidden = false;
+  }
+}
+
+/* -------------------------------------------------------------------------- */
+/* Signed out: tabs, sign-in, registration                                   */
+/* -------------------------------------------------------------------------- */
+
+function selectTab(name, { focus = true } = {}) {
+  currentTab = name;
+  for (const tab of ['signin', 'register']) {
+    const button = $(`#tab-${tab}`);
+    const selected = tab === name;
+    button.setAttribute('aria-selected', String(selected));
+    button.tabIndex = selected ? 0 : -1;
+    $(`#panel-${tab}`).hidden = !selected;
+  }
+  showError($('#auth-error'), '');
+  if (focus) $(name === 'signin' ? '#signin-email' : '#register-name').focus();
+  if (name === 'signin') startConditionalSignIn();
+  else cancelCeremony();
+}
+
+/** Passkey autofill: offers saved passkeys in the email field's suggestions. */
+async function startConditionalSignIn() {
+  if (session.signedIn || currentTab !== 'signin' || !isSupported()) return;
+  if (!(await isConditionalMediationAvailable())) return;
+  const signal = newCeremony();
+  try {
+    const options = await api('POST', '/api/login/options', {});
+    if (signal.aborted) return;
+    const credential = await getPasskey(options, { signal, mediation: 'conditional' });
+    await completeSignIn(credential);
+  } catch (err) {
+    if (signal.aborted) return;
+    handleUnknownCredential(err);
+    if (!isCancellation(err)) {
+      showError($('#auth-error'), err instanceof ApiError ? err.message : describeError(err));
+    }
+    // Re-arm autofill so the user can try another passkey after the server rejected one.
+    if (!session.signedIn && err instanceof ApiError && err.status === 400) {
+      setTimeout(startConditionalSignIn, 500);
+    }
+  }
+}
+
+async function signInWithButton() {
+  showError($('#auth-error'), '');
+  const signal = newCeremony();
+  await busy($('#signin-button'), async () => {
+    try {
+      const options = await api('POST', '/api/login/options', {});
+      const credential = await getPasskey(options, { signal });
+      await completeSignIn(credential);
+    } catch (err) {
+      if (signal.aborted && err?.name === 'AbortError') return;
+      handleUnknownCredential(err);
+      showError(
+        $('#auth-error'),
+        err instanceof ApiError
+          ? err.message
+          : isCancellation(err)
+            ? 'Sign-in was cancelled. If you don’t have a passkey for The Daily Grind yet, create an account first.'
+            : describeError(err),
+      );
+    }
+  });
+  if (!session.signedIn) startConditionalSignIn();
+}
+
+async function completeSignIn(credential) {
+  await api('POST', '/api/login/verify', credential);
+  const next = await api('GET', '/api/session');
+  setSession(next);
+  syncProviders();
+  toast(`Welcome back, ${next.user.displayName}!`);
+  $('#signin-form').reset();
+}
+
+async function register(event) {
+  event.preventDefault();
+  const nameInput = $('#register-name');
+  const emailInput = $('#register-email');
+  const errorEl = $('#auth-error');
+  const displayName = nameInput.value.trim();
+  const email = emailInput.value.trim();
+  setInvalid(nameInput, !displayName);
+  setInvalid(emailInput, !EMAIL_RE.test(email));
+  if (!displayName) return showError(errorEl, 'Please enter your name.'), nameInput.focus();
+  if (!EMAIL_RE.test(email)) return showError(errorEl, 'Please enter a valid email address.'), emailInput.focus();
+  showError(errorEl, '');
+
+  const signal = newCeremony();
+  await busy($('#register-button'), async () => {
+    try {
+      const options = await api('POST', '/api/register/options', { displayName, email });
+      const credential = await createPasskey(options, { signal });
+      await api('POST', '/api/register/verify', credential);
+      setSession(await api('GET', '/api/session'));
+      $('#register-form').reset();
+      toast(`Welcome to The Daily Grind, ${displayName}! Your passkey is saved.`);
+    } catch (err) {
+      if (signal.aborted && err?.name === 'AbortError') return;
+      showError(errorEl, err instanceof ApiError ? err.message : describeError(err, 'create'));
+      if (err instanceof ApiError && err.code === 'account_exists') setInvalid(emailInput, true);
+    }
+  });
+}
+
+/* -------------------------------------------------------------------------- */
+/* Reauthentication                                                           */
+/* -------------------------------------------------------------------------- */
+
+/**
+ * Asks the user to confirm with a passkey. Resolves true once verified, false if cancelled.
+ * When `needsGesture` is set (the caller will start another WebAuthn ceremony afterwards),
+ * the dialog shows a "Continue" step so that ceremony runs from a fresh user click.
+ */
+function requestReauth(reason, { needsGesture = false, continueLabel = 'Continue' } = {}) {
+  const dialog = $('#reauth-dialog');
+  const confirmBtn = $('#reauth-dialog-confirm');
+  const label = $('.label', confirmBtn);
+  const errorEl = $('#reauth-dialog-error');
+
+  $('#reauth-dialog-reason').textContent = reason;
+  label.textContent = 'Use my passkey';
+  showError(errorEl, '');
+
+  return new Promise((resolve) => {
+    let verified = false;
+    let settled = false;
+
+    const finish = (result) => {
+      if (settled) return;
+      settled = true;
+      confirmBtn.removeEventListener('click', onConfirm);
+      dialog.removeEventListener('close', onClose);
+      for (const b of $$('[data-close]', dialog)) b.removeEventListener('click', onCancel);
+      if (dialog.open) dialog.close();
+      resolve(result);
+    };
+
+    const onConfirm = async () => {
+      if (verified) return finish(true);
+      showError(errorEl, '');
+      const signal = newCeremony();
+      await busy(confirmBtn, async () => {
+        try {
+          const options = await api('POST', '/api/reauth/options', {});
+          const credential = await getPasskey(options, { signal });
+          const next = await api('POST', '/api/reauth/verify', credential);
+          setSession(next);
+          verified = true;
+          if (!needsGesture) return finish(true);
+          $('#reauth-dialog-reason').textContent = 'Thanks, you’re verified.';
+          label.textContent = continueLabel;
+        } catch (err) {
+          if (signal.aborted && err?.name === 'AbortError') return;
+          handleUnknownCredential(err);
+          showError(errorEl, err instanceof ApiError ? err.message : describeError(err));
+        }
+      });
+      if (verified && needsGesture) confirmBtn.focus();
+    };
+
+    // Cancelling never continues the action: after the "Continue" step it would
+    // start a new passkey prompt without the user's click.
+    const onCancel = () => {
+      cancelCeremony();
+      finish(false);
+    };
+    const onClose = () => onCancel(); // Esc key
+
+    confirmBtn.addEventListener('click', onConfirm);
+    dialog.addEventListener('close', onClose);
+    for (const b of $$('[data-close]', dialog)) b.addEventListener('click', onCancel);
+    dialog.showModal();
+    confirmBtn.focus();
+  });
+}
+
+/** Runs `fn`; if the server asks for a fresh passkey check, prompts for it and retries once. */
+async function withReauth(fn, reason, opts) {
+  try {
+    return { ok: true, value: await fn() };
+  } catch (err) {
+    if (!(err instanceof ApiError) || err.code !== 'reauth_required') throw err;
+    const verified = await requestReauth(reason, opts);
+    if (!verified) return { ok: false };
+    return { ok: true, value: await fn() };
+  }
+}
+
+/* -------------------------------------------------------------------------- */
+/* Signed in: profile                                                         */
+/* -------------------------------------------------------------------------- */
+
+function openProfileEditor(open) {
+  $('#profile-view').hidden = open;
+  $('#profile-form').hidden = !open;
+  $('#profile-edit-button').hidden = open;
+  showError($('#profile-error'), '');
+  if (open) {
+    $('#profile-name').value = session.user.displayName;
+    $('#profile-email').value = session.user.email;
+    setInvalid($('#profile-name'), false);
+    setInvalid($('#profile-email'), false);
+    $('#profile-name').focus();
+  } else {
+    $('#profile-edit-button').focus();
+  }
+}
+
+async function saveProfile(event) {
+  event.preventDefault();
+  const form = event.currentTarget;
+  const submit = $('button[type="submit"]', form);
+  const errorEl = $('#profile-error');
+  const displayName = $('#profile-name').value.trim();
+  const email = $('#profile-email').value.trim();
+  setInvalid($('#profile-name'), !displayName);
+  setInvalid($('#profile-email'), !EMAIL_RE.test(email));
+  if (!displayName) return showError(errorEl, 'Please enter your name.');
+  if (!EMAIL_RE.test(email)) return showError(errorEl, 'Please enter a valid email address.');
+
+  const changes = {};
+  if (displayName !== session.user.displayName) changes.displayName = displayName;
+  if (email.toLowerCase() !== session.user.email) changes.email = email;
+  if (!Object.keys(changes).length) return openProfileEditor(false);
+
+  await busy(submit, async () => {
+    try {
+      const result = await withReauth(
+        () => api('PATCH', '/api/profile', changes),
+        'Please confirm it’s you with a passkey to change the email address on your account.',
+      );
+      if (!result.ok) return showError(errorEl, 'Your email wasn’t changed because verification was cancelled.');
+      setSession(result.value);
+      // Update the account name shown by passkey providers (e.g. in the autofill list).
+      const { user, rpId } = session;
+      signalCurrentUserDetails(rpId, user.webauthnUserId, user.email, user.displayName);
+      openProfileEditor(false);
+      toast('Profile updated.');
+    } catch (err) {
+      showError(errorEl, err.message);
+    }
+  });
+}
+
+/* -------------------------------------------------------------------------- */
+/* Signed in: passkey management                                              */
+/* -------------------------------------------------------------------------- */
+
+async function addPasskey() {
+  const button = $('#add-passkey-button');
+  await busy(button, async () => {
+    try {
+      const result = await withReauth(
+        () => api('POST', '/api/passkeys/options', {}),
+        'Please confirm it’s you with an existing passkey before creating a new one.',
+        { needsGesture: true, continueLabel: 'Create new passkey' },
+      );
+      if (!result.ok) return;
+      const signal = newCeremony();
+      const credential = await createPasskey(result.value, { signal });
+      const next = await api('POST', '/api/passkeys/verify', credential);
+      setSession(next);
+      const added = next.passkeys.find((p) => p.id === next.added);
+      toast(`Passkey “${added?.name ?? 'Passkey'}” saved. You can rename it to make it easier to recognize.`);
+    } catch (err) {
+      if (err?.name === 'AbortError') return;
+      toast(err instanceof ApiError ? err.message : describeError(err, 'create'), { error: true });
+    }
+  });
+}
+
+let renaming = null;
+
+function openRename(pk) {
+  renaming = pk;
+  const input = $('#rename-input');
+  input.value = pk.name;
+  setInvalid(input, false);
+  showError($('#rename-error'), '');
+  $('#rename-dialog').showModal();
+  input.select();
+}
+
+async function saveRename(event) {
+  event.preventDefault();
+  const input = $('#rename-input');
+  const name = input.value.trim();
+  setInvalid(input, !name);
+  if (!name) return showError($('#rename-error'), 'Please enter a name.');
+  await busy($('button[type="submit"]', event.currentTarget), async () => {
+    try {
+      setSession(await api('PATCH', `/api/passkeys/${encodeURIComponent(renaming.id)}`, { name }));
+      $('#rename-dialog').close();
+      toast('Passkey renamed.');
+    } catch (err) {
+      showError($('#rename-error'), err.message);
+    }
+  });
+}
+
+function confirmDialog({ title, message, confirmLabel }) {
+  const dialog = $('#confirm-dialog');
+  $('#confirm-dialog-title').textContent = title;
+  $('#confirm-dialog-message').textContent = message;
+  $('#confirm-dialog-ok').textContent = confirmLabel;
+  dialog.returnValue = '';
+  dialog.showModal();
+  return new Promise((resolve) => {
+    dialog.addEventListener('close', () => resolve(dialog.returnValue === 'confirm'), { once: true });
+  });
+}
+
+async function removePasskey(pk, button) {
+  const ok = await confirmDialog({
+    title: 'Remove this passkey?',
+    message: `“${pk.name}” will no longer work for signing in to The Daily Grind. Your other passkeys keep working.`,
+    confirmLabel: 'Remove passkey',
+  });
+  if (!ok) return;
+  await busy(button, async () => {
+    try {
+      const result = await withReauth(
+        () => api('DELETE', `/api/passkeys/${encodeURIComponent(pk.id)}`),
+        'Please confirm it’s you with a passkey to remove a saved passkey.',
+      );
+      if (!result.ok) return;
+      setSession(result.value);
+      // Ask the password manager to hide the removed passkey.
+      const { user, passkeys, rpId } = session;
+      signalAllAcceptedCredentials(rpId, user.webauthnUserId, passkeys.map((p) => p.id));
+      toast('Passkey removed. You may also delete it from your device or password manager.');
+    } catch (err) {
+      toast(err.message, { error: true });
+    }
+  });
+}
+
+/* -------------------------------------------------------------------------- */
+/* Signed in: session & account                                               */
+/* -------------------------------------------------------------------------- */
+
+async function signOut() {
+  await busy($('#signout-button'), async () => {
+    try {
+      await api('POST', '/api/logout', {});
+    } catch { /* ignore – we reset the UI regardless */ }
+    currentTab = 'signin';
+    setSession({ signedIn: false, rpId: session.rpId });
+    toast('You’ve been signed out.');
+  });
+}
+
+async function deleteAccount() {
+  const ok = await confirmDialog({
+    title: 'Delete your account?',
+    message: 'This permanently deletes your profile, rewards, and all saved passkeys. This can’t be undone.',
+    confirmLabel: 'Delete account',
+  });
+  if (!ok) return;
+  await busy($('#delete-account-button'), async () => {
+    try {
+      const result = await withReauth(
+        () => api('DELETE', '/api/account'),
+        'Please confirm it’s you with a passkey to delete your account.',
+      );
+      if (!result.ok) return;
+      // No passkeys are valid for this user any more.
+      signalAllAcceptedCredentials(result.value.rpId, result.value.webauthnUserId, []);
+      currentTab = 'register';
+      setSession({ signedIn: false, rpId: session.rpId });
+      toast('Your account has been deleted.');
+    } catch (err) {
+      toast(err.message, { error: true });
+    }
+  });
+}
+
+/* -------------------------------------------------------------------------- */
+/* Wiring                                                                     */
+/* -------------------------------------------------------------------------- */
+
+function wireEvents() {
+  // Tabs (with arrow-key navigation)
+  for (const tab of ['signin', 'register']) {
+    $(`#tab-${tab}`).addEventListener('click', () => selectTab(tab));
+    $(`#tab-${tab}`).addEventListener('keydown', (e) => {
+      if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') {
+        const next = tab === 'signin' ? 'register' : 'signin';
+        selectTab(next, { focus: false });
+        $(`#tab-${next}`).focus();
+      }
+    });
+  }
+  for (const b of $$('[data-switch-tab]')) b.addEventListener('click', () => selectTab(b.dataset.switchTab));
+
+  $('#signin-form').addEventListener('submit', (e) => {
+    e.preventDefault();
+    signInWithButton();
+  });
+  $('#register-form').addEventListener('submit', register);
+
+  $('#signout-button').addEventListener('click', signOut);
+  $('#profile-edit-button').addEventListener('click', () => openProfileEditor(true));
+  $('#profile-cancel').addEventListener('click', () => openProfileEditor(false));
+  $('#profile-form').addEventListener('submit', saveProfile);
+  $('#add-passkey-button').addEventListener('click', addPasskey);
+  $('#rename-form').addEventListener('submit', saveRename);
+  $('#rename-dialog [data-close]').addEventListener('click', () => $('#rename-dialog').close());
+  $('#delete-account-button').addEventListener('click', deleteAccount);
+  $('#reauth-button').addEventListener('click', async () => {
+    const ok = await requestReauth('Confirm it’s you with a passkey to unlock sensitive account changes for 5 minutes.');
+    if (ok) toast('Thanks, you’re verified.');
+  });
+}
+
+async function init() {
+  wireEvents();
+  try {
+    session = await api('GET', '/api/session');
+  } catch {
+    showView('view-loading');
+    $('#view-loading p').textContent = 'We couldn’t reach the account service. Please refresh to try again.';
+    return;
+  }
+  if (location.hash === '#register') currentTab = 'register';
+  render();
+}
+
+init();
