+// Shows "Sign in" or "Logout" in the site navigation depending on the session.
+(function () {
+  const links = () => document.querySelectorAll('[data-auth-link], .logout-link');
+
+  async function logout(event) {
+    event.preventDefault();
+    try {
+      await fetch('/api/logout', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' });
+    } finally {
+      window.location.assign('/account');
+    }
+  }
+
+  function render(signedIn) {
+    for (const link of links()) {
+      link.hidden = false;
+      link.removeEventListener('click', logout);
+      if (signedIn) {
+        link.textContent = 'Logout';
+        link.setAttribute('href', '/logout');
+        link.addEventListener('click', logout);
+      } else {
+        link.textContent = 'Sign in';
+        link.setAttribute('href', '/account');
+      }
+    }
+  }
+
+  // Lets the account page update the nav without another request.
+  window.dgRenderAuthNav = render;
+
+  fetch('/api/session', { headers: { Accept: 'application/json' } })
+    .then((r) => (r.ok ? r.json() : Promise.reject()))
+    .then((s) => render(!!s.signedIn))
+    .catch(() => { for (const link of links()) link.hidden = false; });
+})();
