+// Small, dependency-free WebAuthn helpers for the browser.
+
+const b64urlToBuffer = (value) => {
+  const base64 = value.replace(/-/g, '+').replace(/_/g, '/');
+  const padded = base64 + '='.repeat((4 - (base64.length % 4)) % 4);
+  const bin = atob(padded);
+  const bytes = new Uint8Array(bin.length);
+  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
+  return bytes.buffer;
+};
+
+const bufferToB64url = (buffer) => {
+  const bytes = new Uint8Array(buffer);
+  let bin = '';
+  for (const b of bytes) bin += String.fromCharCode(b);
+  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+};
+
+export function isSupported() {
+  return typeof window.PublicKeyCredential === 'function' && !!navigator.credentials?.create;
+}
+
+export async function isConditionalMediationAvailable() {
+  try {
+    return (await window.PublicKeyCredential?.isConditionalMediationAvailable?.()) === true;
+  } catch {
+    return false;
+  }
+}
+
+export async function hasPlatformAuthenticator() {
+  try {
+    return await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable();
+  } catch {
+    return false;
+  }
+}
+
+function parseCreationOptions(json) {
+  if (typeof PublicKeyCredential.parseCreationOptionsFromJSON === 'function') {
+    return PublicKeyCredential.parseCreationOptionsFromJSON(json);
+  }
+  return {
+    ...json,
+    challenge: b64urlToBuffer(json.challenge),
+    user: { ...json.user, id: b64urlToBuffer(json.user.id) },
+    excludeCredentials: (json.excludeCredentials || []).map((c) => ({ ...c, id: b64urlToBuffer(c.id) })),
+  };
+}
+
+function parseRequestOptions(json) {
+  if (typeof PublicKeyCredential.parseRequestOptionsFromJSON === 'function') {
+    return PublicKeyCredential.parseRequestOptionsFromJSON(json);
+  }
+  return {
+    ...json,
+    challenge: b64urlToBuffer(json.challenge),
+    allowCredentials: (json.allowCredentials || []).map((c) => ({ ...c, id: b64urlToBuffer(c.id) })),
+  };
+}
+
+function credentialToJSON(cred) {
+  // Some browser extensions return objects whose toJSON() is missing or broken,
+  // so fall back to manual serialization.
+  try {
+    if (typeof cred.toJSON === 'function') return cred.toJSON();
+  } catch { /* fall through */ }
+
+  const r = cred.response;
+  const json = {
+    id: cred.id,
+    rawId: bufferToB64url(cred.rawId),
+    type: cred.type,
+    authenticatorAttachment: cred.authenticatorAttachment ?? undefined,
+    clientExtensionResults: cred.getClientExtensionResults?.() ?? {},
+    response: { clientDataJSON: bufferToB64url(r.clientDataJSON) },
+  };
+  if (r.attestationObject) {
+    json.response.attestationObject = bufferToB64url(r.attestationObject);
+    json.response.transports = r.getTransports?.() ?? [];
+  } else {
+    json.response.authenticatorData = bufferToB64url(r.authenticatorData);
+    json.response.signature = bufferToB64url(r.signature);
+    if (r.userHandle) json.response.userHandle = bufferToB64url(r.userHandle);
+  }
+  return json;
+}
+
+/** Runs navigator.credentials.create() with JSON options; returns the JSON response. */
+export async function createPasskey(optionsJSON, { signal } = {}) {
+  const cred = await navigator.credentials.create({ publicKey: parseCreationOptions(optionsJSON), signal });
+  if (!cred) throw new DOMException('No credential was created.', 'NotAllowedError');
+  return credentialToJSON(cred);
+}
+
+/** Runs navigator.credentials.get() with JSON options; returns the JSON response. */
+export async function getPasskey(optionsJSON, { signal, mediation } = {}) {
+  const cred = await navigator.credentials.get({
+    publicKey: parseRequestOptions(optionsJSON),
+    signal,
+    ...(mediation ? { mediation } : {}),
+  });
+  if (!cred) throw new DOMException('No passkey was selected.', 'NotAllowedError');
+  return credentialToJSON(cred);
+}
+
+/** True when the error just means the user dismissed the prompt or it was aborted on purpose. */
+export function isCancellation(err) {
+  return err?.name === 'AbortError' || err?.name === 'NotAllowedError';
+}
+
+export function describeError(err, kind = 'get') {
+  switch (err?.name) {
+    case 'NotAllowedError':
+      return kind === 'create'
+        ? 'Passkey creation was cancelled or timed out.'
+        : 'Passkey sign-in was cancelled or timed out.';
+    case 'InvalidStateError':
+      return kind === 'create'
+        ? 'A passkey for this account already exists on this device or password manager.'
+        : 'Your device couldn’t use this passkey.';
+    case 'SecurityError':
+      return 'Passkeys can’t be used on this address. Make sure you are on the official Daily Grind site over HTTPS (or localhost).';
+    case 'NotSupportedError':
+      return 'This device doesn’t support the required passkey options.';
+    case 'AbortError':
+      return 'The passkey request was interrupted.';
+    default:
+      return err?.message || 'Something went wrong with your passkey.';
+  }
+}
+
+/* ---- WebAuthn Signal API: keeps passkey providers in sync with our server ---- */
+
+async function signal(method, payload) {
+  try {
+    if (typeof PublicKeyCredential[method] === 'function') await PublicKeyCredential[method](payload);
+  } catch (err) {
+    console.debug(`PublicKeyCredential.${method} failed`, err);
+  }
+}
+
+/** The server doesn't know this credential: ask the provider to hide/remove it. */
+export const signalUnknownCredential = (rpId, credentialId) =>
+  signal('signalUnknownCredential', { rpId, credentialId });
+
+/** Tells the provider which passkeys are still valid for this user. */
+export const signalAllAcceptedCredentials = (rpId, userId, allAcceptedCredentialIds) =>
+  signal('signalAllAcceptedCredentials', { rpId, userId, allAcceptedCredentialIds });
+
+/** Updates the name/display name the provider shows for this user's passkeys. */
+export const signalCurrentUserDetails = (rpId, userId, name, displayName) =>
+  signal('signalCurrentUserDetails', { rpId, userId, name, displayName });
