diff --git a/server.js b/server.js
new file mode 100644
index 0000000..27e9348
--- /dev/null
+++ b/server.js
@@ -0,0 +1,697 @@
+// The Daily Grind – static site + passkey (WebAuthn) account API.
+//
+// Zero-framework Node server: serves the static pages and exposes a small JSON
+// API under /api used by the "My Account" UI (/account).
+//
+// Configuration (environment variables):
+//   PORT        Port to listen on                      (default 11222)
+//   RP_ID       WebAuthn Relying Party ID (domain)      (default "localhost")
+//   RP_NAME     Name shown in passkey prompts           (default "The Daily Grind")
+//   ORIGINS     Comma separated list of allowed origins (default http://localhost:PORT)
+//   DATA_FILE   Path of the JSON "database"             (default ./data/db.json)
+
+import http from 'node:http';
+import crypto from 'node:crypto';
+import fs from 'node:fs';
+import path from 'node:path';
+import { fileURLToPath } from 'node:url';
+import {
+  generateRegistrationOptions,
+  verifyRegistrationResponse,
+  generateAuthenticationOptions,
+  verifyAuthenticationResponse,
+} from '@simplewebauthn/server';
+import { isoBase64URL } from '@simplewebauthn/server/helpers';
+import { providerForAaguid } from './lib/aaguids.js';
+
+const ROOT = path.dirname(fileURLToPath(import.meta.url));
+const PORT = Number(process.env.PORT || 11222);
+const RP_ID = process.env.RP_ID || 'localhost';
+const RP_NAME = process.env.RP_NAME || 'The Daily Grind';
+const ORIGINS = (process.env.ORIGINS || `http://localhost:${PORT}`)
+  .split(',')
+  .map((o) => o.trim().replace(/\/$/, ''))
+  .filter(Boolean);
+const DATA_FILE = path.resolve(process.env.DATA_FILE || path.join(ROOT, 'data', 'db.json'));
+const SECURE_COOKIES = ORIGINS.every((o) => o.startsWith('https://'));
+
+const SESSION_COOKIE = SECURE_COOKIES ? '__Host-dg_sid' : 'dg_sid';
+const SESSION_TTL_MS = 12 * 60 * 60 * 1000; // absolute session lifetime
+const CHALLENGE_TTL_MS = 5 * 60 * 1000; // a ceremony must finish within 5 minutes
+const REAUTH_WINDOW_MS = 5 * 60 * 1000; // sensitive actions need a passkey check this recent
+const MAX_BODY_BYTES = 64 * 1024;
+const MAX_PASSKEYS_PER_USER = 20;
+
+/* -------------------------------------------------------------------------- */
+/* Persistence (tiny JSON file store)                                         */
+/* -------------------------------------------------------------------------- */
+
+function loadDb() {
+  try {
+    const db = JSON.parse(fs.readFileSync(DATA_FILE, 'utf8'));
+    return { users: db.users || [], credentials: db.credentials || [] };
+  } catch (err) {
+    if (err.code !== 'ENOENT') console.error('Could not read database, starting fresh:', err.message);
+    return { users: [], credentials: [] };
+  }
+}
+
+const db = loadDb();
+
+function saveDb() {
+  fs.mkdirSync(path.dirname(DATA_FILE), { recursive: true });
+  const tmp = `${DATA_FILE}.${process.pid}.tmp`;
+  fs.writeFileSync(tmp, JSON.stringify(db, null, 2), { mode: 0o600 });
+  fs.renameSync(tmp, DATA_FILE);
+}
+
+const findUserById = (id) => db.users.find((u) => u.id === id);
+const findUserByEmail = (email) => db.users.find((u) => u.email === email);
+const credentialsForUser = (userId) => db.credentials.filter((c) => c.userId === userId);
+const findCredential = (id) => db.credentials.find((c) => c.id === id);
+
+/* -------------------------------------------------------------------------- */
+/* Sessions (in memory, HttpOnly cookie)                                      */
+/* -------------------------------------------------------------------------- */
+
+const sessions = new Map();
+
+function newSessionId() {
+  return crypto.randomBytes(32).toString('base64url');
+}
+
+function parseCookies(header = '') {
+  const out = {};
+  for (const part of header.split(';')) {
+    const idx = part.indexOf('=');
+    if (idx < 0) continue;
+    out[part.slice(0, idx).trim()] = decodeURIComponent(part.slice(idx + 1).trim());
+  }
+  return out;
+}
+
+function getSession(req) {
+  const sid = parseCookies(req.headers.cookie)[SESSION_COOKIE];
+  if (!sid) return null;
+  const session = sessions.get(sid);
+  if (!session) return null;
+  if (Date.now() > session.expiresAt) {
+    sessions.delete(sid);
+    return null;
+  }
+  return session;
+}
+
+function setSessionCookie(res, sid, maxAgeMs) {
+  const attrs = [
+    `${SESSION_COOKIE}=${sid}`,
+    'Path=/',
+    'HttpOnly',
+    'SameSite=Lax',
+    `Max-Age=${Math.floor(maxAgeMs / 1000)}`,
+  ];
+  if (SECURE_COOKIES) attrs.push('Secure');
+  res.setHeader('Set-Cookie', attrs.join('; '));
+}
+
+/** Returns the existing session or creates an anonymous one (used to hold challenges). */
+function ensureSession(req, res) {
+  const existing = getSession(req);
+  if (existing) return existing;
+  const sid = newSessionId();
+  const session = { id: sid, userId: null, authAt: 0, challenges: {}, expiresAt: Date.now() + SESSION_TTL_MS };
+  sessions.set(sid, session);
+  setSessionCookie(res, sid, SESSION_TTL_MS);
+  return session;
+}
+
+/** Issues a fresh session id on privilege change (prevents session fixation). */
+function startAuthenticatedSession(req, res, userId) {
+  const old = getSession(req);
+  if (old) sessions.delete(old.id);
+  const sid = newSessionId();
+  const now = Date.now();
+  sessions.set(sid, { id: sid, userId, authAt: now, challenges: {}, expiresAt: now + SESSION_TTL_MS });
+  setSessionCookie(res, sid, SESSION_TTL_MS);
+}
+
+function destroySession(req, res) {
+  const s = getSession(req);
+  if (s) sessions.delete(s.id);
+  setSessionCookie(res, '', 0);
+}
+
+function destroyUserSessions(userId, exceptId) {
+  for (const [sid, s] of sessions) if (s.userId === userId && sid !== exceptId) sessions.delete(sid);
+}
+
+setInterval(() => {
+  const now = Date.now();
+  for (const [sid, s] of sessions) if (now > s.expiresAt) sessions.delete(sid);
+}, 10 * 60 * 1000).unref();
+
+function storeChallenge(session, purpose, challenge, extra = {}) {
+  session.challenges[purpose] = { challenge, expiresAt: Date.now() + CHALLENGE_TTL_MS, ...extra };
+}
+
+/** Challenges are single use: they are removed as soon as a verification is attempted. */
+function takeChallenge(session, purpose) {
+  const entry = session?.challenges?.[purpose];
+  if (session) delete session.challenges[purpose];
+  if (!entry || Date.now() > entry.expiresAt) return null;
+  return entry;
+}
+
+/* -------------------------------------------------------------------------- */
+/* Helpers                                                                    */
+/* -------------------------------------------------------------------------- */
+
+class HttpError extends Error {
+  constructor(status, message, extra = {}) {
+    super(message);
+    this.status = status;
+    this.extra = extra;
+  }
+}
+
+function sendJson(res, status, body) {
+  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
+  res.end(JSON.stringify(body));
+}
+
+async function readJson(req) {
+  if (!/^application\/json\b/i.test(req.headers['content-type'] || '')) {
+    throw new HttpError(415, 'Expected an application/json request body.');
+  }
+  let size = 0;
+  const chunks = [];
+  for await (const chunk of req) {
+    size += chunk.length;
+    if (size > MAX_BODY_BYTES) throw new HttpError(413, 'Request body too large.');
+    chunks.push(chunk);
+  }
+  if (!size) return {};
+  try {
+    const parsed = JSON.parse(Buffer.concat(chunks).toString('utf8'));
+    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error();
+    return parsed;
+  } catch {
+    throw new HttpError(400, 'Malformed JSON body.');
+  }
+}
+
+const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+
+function cleanEmail(value) {
+  const email = String(value ?? '').trim().toLowerCase();
+  if (!email || email.length > 254 || !EMAIL_RE.test(email)) {
+    throw new HttpError(400, 'Please enter a valid email address.');
+  }
+  return email;
+}
+
+function cleanText(value, label, max) {
+  // Strip control characters, collapse whitespace.
+  const text = String(value ?? '').replace(/[\u0000-\u001f\u007f]/g, '').replace(/\s+/g, ' ').trim();
+  if (!text) throw new HttpError(400, `${label} is required.`);
+  if (text.length > max) throw new HttpError(400, `${label} must be ${max} characters or fewer.`);
+  return text;
+}
+
+function requireUser(session) {
+  const user = session?.userId ? findUserById(session.userId) : null;
+  if (!user) throw new HttpError(401, 'Please sign in to continue.', { code: 'signed_out' });
+  return user;
+}
+
+function requireRecentAuth(session) {
+  if (Date.now() - session.authAt > REAUTH_WINDOW_MS) {
+    throw new HttpError(401, 'Please confirm it’s you with your passkey.', { code: 'reauth_required' });
+  }
+}
+
+function publicUser(user) {
+  return {
+    id: user.id,
+    webauthnUserId: user.webauthnUserId,
+    email: user.email,
+    displayName: user.displayName,
+    createdAt: user.createdAt,
+  };
+}
+
+function publicPasskey(cred) {
+  return {
+    id: cred.id,
+    name: cred.name,
+    provider: providerForAaguid(cred.aaguid),
+    createdAt: cred.createdAt,
+    lastUsedAt: cred.lastUsedAt,
+    synced: cred.deviceType === 'multiDevice',
+    backedUp: cred.backedUp,
+    transports: cred.transports || [],
+  };
+}
+
+function sessionPayload(session) {
+  const user = session?.userId ? findUserById(session.userId) : null;
+  if (!user) return { signedIn: false, rpId: RP_ID };
+  const reauthExpiresAt = session.authAt + REAUTH_WINDOW_MS;
+  return {
+    signedIn: true,
+    rpId: RP_ID,
+    user: publicUser(user),
+    passkeys: credentialsForUser(user.id)
+      .sort((a, b) => b.createdAt.localeCompare(a.createdAt))
+      .map(publicPasskey),
+    reauthExpiresAt: reauthExpiresAt > Date.now() ? new Date(reauthExpiresAt).toISOString() : null,
+  };
+}
+
+function registrationOptionsFor({ email, displayName, webauthnUserId, exclude = [] }) {
+  return generateRegistrationOptions({
+    rpName: RP_NAME,
+    rpID: RP_ID,
+    userName: email,
+    userDisplayName: displayName,
+    userID: isoBase64URL.toBuffer(webauthnUserId),
+    attestationType: 'none',
+    timeout: CHALLENGE_TTL_MS,
+    excludeCredentials: exclude.map((c) => ({ id: c.id, transports: c.transports })),
+    authenticatorSelection: {
+      residentKey: 'required', // discoverable credential = a true passkey
+      requireResidentKey: true,
+      userVerification: 'required', // the passkey is the only factor, so require PIN/biometrics
+    },
+    extensions: { credProps: true },
+  });
+}
+
+async function verifyRegistration(body, expectedChallenge) {
+  let verification;
+  try {
+    verification = await verifyRegistrationResponse({
+      response: body,
+      expectedChallenge,
+      expectedOrigin: ORIGINS,
+      expectedRPID: RP_ID,
+      requireUserVerification: true,
+    });
+  } catch (err) {
+    throw new HttpError(400, `Passkey could not be verified: ${err.message}`);
+  }
+  if (!verification.verified) throw new HttpError(400, 'Passkey could not be verified.');
+  const info = verification.registrationInfo;
+  if (findCredential(info.credential.id)) throw new HttpError(409, 'This passkey is already registered.');
+  return info;
+}
+
+function credentialRecord(userId, info, transportsFromClient) {
+  const provider = providerForAaguid(info.aaguid);
+  const now = new Date().toISOString();
+  const transports = info.credential.transports?.length
+    ? info.credential.transports
+    : Array.isArray(transportsFromClient) ? transportsFromClient.filter((t) => typeof t === 'string') : [];
+  return {
+    id: info.credential.id,
+    userId,
+    publicKey: isoBase64URL.fromBuffer(info.credential.publicKey),
+    counter: info.credential.counter,
+    transports,
+    deviceType: info.credentialDeviceType,
+    backedUp: info.credentialBackedUp,
+    aaguid: info.aaguid,
+    name: provider?.name || (info.credentialDeviceType === 'multiDevice' ? 'Synced passkey' : 'Passkey'),
+    createdAt: now,
+    lastUsedAt: null,
+  };
+}
+
+/** Verifies an assertion for a stored credential and updates its metadata. */
+async function verifyAssertion(body, expectedChallenge, cred) {
+  let verification;
+  try {
+    verification = await verifyAuthenticationResponse({
+      response: body,
+      expectedChallenge,
+      expectedOrigin: ORIGINS,
+      expectedRPID: RP_ID,
+      requireUserVerification: true,
+      credential: {
+        id: cred.id,
+        publicKey: isoBase64URL.toBuffer(cred.publicKey),
+        counter: cred.counter,
+        transports: cred.transports,
+      },
+    });
+  } catch (err) {
+    throw new HttpError(400, `Passkey could not be verified: ${err.message}`);
+  }
+  if (!verification.verified) throw new HttpError(400, 'Passkey could not be verified.');
+  const info = verification.authenticationInfo;
+  cred.counter = info.newCounter;
+  cred.backedUp = info.credentialBackedUp;
+  cred.deviceType = info.credentialDeviceType;
+  cred.lastUsedAt = new Date().toISOString();
+  saveDb();
+}
+
+/* -------------------------------------------------------------------------- */
+/* API routes                                                                 */
+/* -------------------------------------------------------------------------- */
+
+const routes = {
+  'GET /api/session': async (req, res) => {
+    sendJson(res, 200, sessionPayload(getSession(req)));
+  },
+
+  /* ---- Registration (new customer + first passkey) ---- */
+
+  'POST /api/register/options': async (req, res) => {
+    const body = await readJson(req);
+    const email = cleanEmail(body.email);
+    const displayName = cleanText(body.displayName, 'Name', 64);
+    if (findUserByEmail(email)) {
+      throw new HttpError(409, 'An account with this email already exists. Sign in with your passkey instead.', {
+        code: 'account_exists',
+      });
+    }
+    const session = ensureSession(req, res);
+    const webauthnUserId = isoBase64URL.fromBuffer(crypto.randomBytes(32));
+    const options = await registrationOptionsFor({ email, displayName, webauthnUserId });
+    storeChallenge(session, 'register', options.challenge, { email, displayName, webauthnUserId });
+    sendJson(res, 200, options);
+  },
+
+  'POST /api/register/verify': async (req, res) => {
+    const body = await readJson(req);
+    const pending = takeChallenge(getSession(req), 'register');
+    if (!pending) throw new HttpError(400, 'Registration expired. Please try again.');
+    // Re-check: the email might have been taken while the ceremony was running.
+    if (findUserByEmail(pending.email)) throw new HttpError(409, 'An account with this email already exists.');
+
+    const info = await verifyRegistration(body, pending.challenge);
+    const user = {
+      id: crypto.randomUUID(),
+      webauthnUserId: pending.webauthnUserId,
+      email: pending.email,
+      displayName: pending.displayName,
+      createdAt: new Date().toISOString(),
+    };
+    db.users.push(user);
+    db.credentials.push(credentialRecord(user.id, info, body?.response?.transports));
+    saveDb();
+    startAuthenticatedSession(req, res, user.id);
+    sendJson(res, 200, { ok: true });
+  },
+
+  /* ---- Sign in (discoverable credentials; modal or conditional UI) ---- */
+
+  'POST /api/login/options': async (req, res) => {
+    const session = ensureSession(req, res);
+    const options = await generateAuthenticationOptions({
+      rpID: RP_ID,
+      userVerification: 'required',
+      timeout: CHALLENGE_TTL_MS,
+      allowCredentials: [], // empty => the browser offers every passkey it has for this site
+    });
+    storeChallenge(session, 'login', options.challenge);
+    sendJson(res, 200, options);
+  },
+
+  'POST /api/login/verify': async (req, res) => {
+    const body = await readJson(req);
+    const pending = takeChallenge(getSession(req), 'login');
+    if (!pending) throw new HttpError(400, 'Sign-in expired. Please try again.');
+
+    const cred = typeof body.id === 'string' ? findCredential(body.id) : null;
+    if (!cred) {
+      // Lets the client tell the passkey provider to hide/remove this stale passkey.
+      throw new HttpError(400, 'This passkey isn’t registered with The Daily Grind. It may have been removed.', {
+        code: 'unknown_credential',
+        credentialId: typeof body.id === 'string' ? body.id : undefined,
+      });
+    }
+    const user = findUserById(cred.userId);
+    if (!user || body?.response?.userHandle !== user.webauthnUserId) {
+      throw new HttpError(400, 'Passkey could not be verified.');
+    }
+    await verifyAssertion(body, pending.challenge, cred);
+    startAuthenticatedSession(req, res, user.id);
+    sendJson(res, 200, { ok: true });
+  },
+
+  'POST /api/logout': async (req, res) => {
+    destroySession(req, res);
+    sendJson(res, 200, { ok: true });
+  },
+
+  /* ---- Reauthentication (step-up before sensitive changes) ---- */
+
+  'POST /api/reauth/options': async (req, res) => {
+    const session = getSession(req);
+    const user = requireUser(session);
+    const options = await generateAuthenticationOptions({
+      rpID: RP_ID,
+      userVerification: 'required',
+      timeout: CHALLENGE_TTL_MS,
+      allowCredentials: credentialsForUser(user.id).map((c) => ({ id: c.id, transports: c.transports })),
+    });
+    storeChallenge(session, 'reauth', options.challenge);
+    sendJson(res, 200, options);
+  },
+
+  'POST /api/reauth/verify': async (req, res) => {
+    const body = await readJson(req);
+    const session = getSession(req);
+    const user = requireUser(session);
+    const pending = takeChallenge(session, 'reauth');
+    if (!pending) throw new HttpError(400, 'Verification expired. Please try again.');
+    const cred = typeof body.id === 'string' ? findCredential(body.id) : null;
+    if (!cred || cred.userId !== user.id) {
+      throw new HttpError(400, 'That passkey doesn’t belong to this account.', {
+        code: cred ? undefined : 'unknown_credential',
+        credentialId: cred ? undefined : body.id,
+      });
+    }
+    await verifyAssertion(body, pending.challenge, cred);
+    session.authAt = Date.now();
+    sendJson(res, 200, sessionPayload(session));
+  },
+
+  /* ---- Passkey management ---- */
+
+  'POST /api/passkeys/options': async (req, res) => {
+    const session = getSession(req);
+    const user = requireUser(session);
+    requireRecentAuth(session);
+    const existing = credentialsForUser(user.id);
+    if (existing.length >= MAX_PASSKEYS_PER_USER) {
+      throw new HttpError(400, `You can save up to ${MAX_PASSKEYS_PER_USER} passkeys.`);
+    }
+    const options = await registrationOptionsFor({
+      email: user.email,
+      displayName: user.displayName,
+      webauthnUserId: user.webauthnUserId,
+      exclude: existing, // stops the same authenticator being registered twice
+    });
+    storeChallenge(session, 'add-passkey', options.challenge);
+    sendJson(res, 200, options);
+  },
+
+  'POST /api/passkeys/verify': async (req, res) => {
+    const body = await readJson(req);
+    const session = getSession(req);
+    const user = requireUser(session);
+    const pending = takeChallenge(session, 'add-passkey');
+    if (!pending) throw new HttpError(400, 'Passkey creation expired. Please try again.');
+    const info = await verifyRegistration(body, pending.challenge);
+    const record = credentialRecord(user.id, info, body?.response?.transports);
+    db.credentials.push(record);
+    saveDb();
+    sendJson(res, 200, { ...sessionPayload(session), added: record.id });
+  },
+
+  'PATCH /api/passkeys/:id': async (req, res, { id }) => {
+    const body = await readJson(req);
+    const session = getSession(req);
+    const user = requireUser(session);
+    const cred = findCredential(id);
+    if (!cred || cred.userId !== user.id) throw new HttpError(404, 'Passkey not found.');
+    cred.name = cleanText(body.name, 'Passkey name', 48);
+    saveDb();
+    sendJson(res, 200, sessionPayload(session));
+  },
+
+  'DELETE /api/passkeys/:id': async (req, res, { id }) => {
+    const session = getSession(req);
+    const user = requireUser(session);
+    const cred = findCredential(id);
+    if (!cred || cred.userId !== user.id) throw new HttpError(404, 'Passkey not found.');
+    requireRecentAuth(session);
+    if (credentialsForUser(user.id).length <= 1) {
+      throw new HttpError(400, 'You can’t remove your only passkey – create another one first so you don’t get locked out.');
+    }
+    db.credentials = db.credentials.filter((c) => c.id !== id);
+    saveDb();
+    sendJson(res, 200, sessionPayload(session));
+  },
+
+  /* ---- Profile ---- */
+
+  'PATCH /api/profile': async (req, res) => {
+    const body = await readJson(req);
+    const session = getSession(req);
+    const user = requireUser(session);
+    const displayName = body.displayName === undefined ? user.displayName : cleanText(body.displayName, 'Name', 64);
+    const email = body.email === undefined ? user.email : cleanEmail(body.email);
+
+    if (email !== user.email) {
+      // Changing the sign-in identifier is sensitive: require a fresh passkey check.
+      requireRecentAuth(session);
+      const other = findUserByEmail(email);
+      if (other && other.id !== user.id) throw new HttpError(409, 'That email is already used by another account.');
+    }
+    user.email = email;
+    user.displayName = displayName;
+    saveDb();
+    sendJson(res, 200, sessionPayload(session));
+  },
+
+  /* ---- Account deletion ---- */
+
+  'DELETE /api/account': async (req, res) => {
+    const session = getSession(req);
+    const user = requireUser(session);
+    requireRecentAuth(session);
+    db.users = db.users.filter((u) => u.id !== user.id);
+    db.credentials = db.credentials.filter((c) => c.userId !== user.id);
+    saveDb();
+    destroyUserSessions(user.id, session.id);
+    destroySession(req, res);
+    sendJson(res, 200, { ok: true, rpId: RP_ID, webauthnUserId: user.webauthnUserId });
+  },
+};
+
+function matchRoute(method, pathname) {
+  const direct = routes[`${method} ${pathname}`];
+  if (direct) return { handler: direct, params: {} };
+  for (const [key, handler] of Object.entries(routes)) {
+    const [m, pattern] = key.split(' ');
+    if (m !== method || !pattern.includes(':')) continue;
+    const re = new RegExp(`^${pattern.replace(/:(\w+)/g, '(?<$1>[^/]+)')}$`);
+    const match = pathname.match(re);
+    if (match) {
+      const params = {};
+      Object.assign(params, match.groups); // pathname is already decoded
+      return { handler, params };
+    }
+  }
+  return null;
+}
+
+/** CSRF defence for state-changing requests: the Origin header must be one of ours. */
+function checkOrigin(req) {
+  if (req.method === 'GET' || req.method === 'HEAD') return;
+  const origin = req.headers.origin;
+  if (!origin || !ORIGINS.includes(origin)) throw new HttpError(403, 'Cross-origin request blocked.');
+}
+
+/* -------------------------------------------------------------------------- */
+/* Static files                                                               */
+/* -------------------------------------------------------------------------- */
+
+const MIME = {
+  '.html': 'text/html; charset=utf-8',
+  '.js': 'text/javascript; charset=utf-8',
+  '.css': 'text/css; charset=utf-8',
+  '.svg': 'image/svg+xml',
+  '.png': 'image/png',
+  '.jpg': 'image/jpeg',
+  '.ico': 'image/x-icon',
+  '.json': 'application/json; charset=utf-8',
+};
+
+// Only these locations are publicly served (never server.js, data/, node_modules/ …).
+const STATIC_DIRS = ['account', 'assets'];
+const STATIC_ALIASES = { '/': 'index.html', '/index.html': 'index.html', '/account': 'account/index.html' };
+
+const SECURITY_HEADERS = {
+  'X-Content-Type-Options': 'nosniff',
+  'Referrer-Policy': 'strict-origin-when-cross-origin',
+  'X-Frame-Options': 'DENY',
+  'Content-Security-Policy':
+    "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; " +
+    "img-src 'self' data: https://images.unsplash.com; connect-src 'self'; frame-ancestors 'none'; " +
+    "base-uri 'self'; form-action 'self'",
+};
+
+function resolveStatic(pathname) {
+  if (STATIC_ALIASES[pathname]) return path.join(ROOT, STATIC_ALIASES[pathname]);
+  const rel = path.posix.normalize(pathname).replace(/^\/+/, '');
+  const top = rel.split('/')[0];
+  if (!STATIC_DIRS.includes(top) || rel.includes('..')) return null;
+  let file = path.join(ROOT, rel);
+  if (!file.startsWith(path.join(ROOT, top))) return null;
+  if (rel.endsWith('/') || !path.extname(rel)) file = path.join(file, 'index.html');
+  return file;
+}
+
+function serveStatic(req, res, pathname) {
+  const file = resolveStatic(pathname);
+  if (!file) return notFound(res);
+  fs.stat(file, (err, stat) => {
+    if (err || !stat.isFile()) return notFound(res);
+    res.writeHead(200, {
+      'Content-Type': MIME[path.extname(file)] || 'application/octet-stream',
+      'Content-Length': stat.size,
+      'Cache-Control': 'no-cache',
+    });
+    if (req.method === 'HEAD') return res.end();
+    fs.createReadStream(file).pipe(res);
+  });
+}
+
+function notFound(res) {
+  res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
+  res.end('Not found');
+}
+
+/* -------------------------------------------------------------------------- */
+/* Server                                                                     */
+/* -------------------------------------------------------------------------- */
+
+const server = http.createServer(async (req, res) => {
+  for (const [k, v] of Object.entries(SECURITY_HEADERS)) res.setHeader(k, v);
+  let pathname;
+  try {
+    pathname = decodeURIComponent(new URL(req.url, 'http://x').pathname);
+  } catch {
+    return notFound(res);
+  }
+
+  if (pathname.startsWith('/api/')) {
+    try {
+      checkOrigin(req);
+      const route = matchRoute(req.method, pathname);
+      if (!route) throw new HttpError(404, 'Not found.');
+      await route.handler(req, res, route.params);
+    } catch (err) {
+      if (err instanceof HttpError) {
+        sendJson(res, err.status, { error: err.message, ...err.extra });
+      } else {
+        console.error(err);
+        sendJson(res, 500, { error: 'Something went wrong. Please try again.' });
+      }
+    }
+    return;
+  }
+
+  if (req.method !== 'GET' && req.method !== 'HEAD') return notFound(res);
+  serveStatic(req, res, pathname);
+});
+
+server.listen(PORT, () => {
+  console.log(`The Daily Grind running on http://localhost:${PORT}`);
+  console.log(`WebAuthn RP ID: ${RP_ID} · allowed origins: ${ORIGINS.join(', ')}`);
+});

