+import {
+  apiUrl,
+  getCapabilities,
+  pageUrl,
+  registerPasskey,
+  syncAcceptedCredentials,
+  syncCurrentUserDetails,
+} from '../lib/passkeys';
+import { useReauthDialog } from './ReauthDialog';
+
+interface Passkey {
+  id: string;
+  name: string;
+  providerName: string;
+  providerIcon?: { light?: string; dark?: string };
+  credentialDeviceType: 'singleDevice' | 'multiDevice';
+  credentialBackedUp: boolean;
+  registeredAt: number;
+  lastUsedAt?: number;
+}
+
+interface AccountData {
+  rpId: string;
+  userId: string;
+  username: string;
+  displayName: string;
+  credentials: Passkey[];
+}
+
+interface Props {
+  username: string;
+  displayName: string;
+}
+
+const dateFormat = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' });
+const formatDate = (epoch: number) => dateFormat.format(new Date(epoch));
+
+const buttonPrimary =
+  'inline-flex items-center justify-center gap-2 py-2 px-4 rounded-md text-sm font-medium text-white bg-gray-900 hover:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-900 disabled:opacity-75 disabled:cursor-not-allowed';
+const buttonSecondary =
+  'inline-flex items-center justify-center gap-1.5 py-1.5 px-3 rounded-md text-sm font-medium border border-gray-300 text-gray-800 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-gray-900 disabled:opacity-75';
+
+const buttonDangerOutline =
+  'inline-flex items-center justify-center gap-1.5 py-1.5 px-3 rounded-md text-sm font-medium border border-red-300 text-red-700 bg-white hover:bg-red-50 focus:outline-none focus:ring-2 focus:ring-red-700';
+const buttonDanger =
+  'inline-flex items-center justify-center gap-2 py-2 px-4 rounded-md text-sm font-medium text-white bg-red-700 hover:bg-red-800 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-red-700';
+
+async function isReauthRequired(res: Response): Promise<boolean> {
+  if (res.status !== 401) return false;
+  const data = await res.clone().json().catch(() => null);
+  return data?.error === 'reauth_required';
+}
+
+export default function AccountSettings({ username, displayName: initialDisplayName }: Props) {
+  const [account, setAccount] = useState<AccountData | null>(null);
+  const [loadError, setLoadError] = useState<string | null>(null);
+  const [notice, setNotice] = useState<{ kind: 'success' | 'error'; text: string } | null>(null);
+  const [canCreatePasskey, setCanCreatePasskey] = useState<boolean | null>(null);
+  const [creating, setCreating] = useState(false);
+  const [displayName, setDisplayName] = useState(initialDisplayName);
+  const [savingProfile, setSavingProfile] = useState(false);
+  const [editingId, setEditingId] = useState<string | null>(null);
+  const [editName, setEditName] = useState('');
+  const [pendingDelete, setPendingDelete] = useState<Passkey | null>(null);
+  const deleteDialogRef = useRef<HTMLDialogElement>(null);
+  const deleteTitleId = useId();
+  const displayNameId = useId();
+
+  const { dialog: reauthDialog, requestReauth } = useReauthDialog({
+    username,
+    hasPasskeys: (account?.credentials.length ?? 0) > 0,
+  });
+
+  const loadAccount = useCallback(async (): Promise<AccountData | null> => {
+    const res = await fetch(apiUrl('passkeys'), { credentials: 'same-origin' });
+    if (res.status === 401) {
+      window.location.assign(pageUrl('signin'));
+      return null;
+    }
+    if (!res.ok) throw new Error(`HTTP ${res.status}`);
+    const data = (await res.json()) as AccountData;
+    setAccount(data);
+    // Keep the user's password manager in step with the server's passkey list.
+    void syncAcceptedCredentials(data.rpId, data.userId, data.credentials.map((c) => c.id));
+    return data;
+  }, []);
+
+  useEffect(() => {
+    loadAccount().catch(() => setLoadError('We couldn’t load your passkeys. Please refresh to try again.'));
+    getCapabilities().then((caps) => setCanCreatePasskey(Boolean(caps.passkeyPlatformAuthenticator)));
+    const params = new URLSearchParams(window.location.search);
+    if (params.get('passkey') === 'created') {
+      setNotice({ kind: 'success', text: 'Passkey created. You can now use it to sign in.' });
+      params.delete('passkey');
+      const query = params.toString();
+      history.replaceState(history.state, '', `${location.pathname}${query ? `?${query}` : ''}`);
+    }
+  }, [loadAccount]);
+
+  /** Run a sensitive request; if the server asks for step-up verification, prompt and retry once. */
+  const withReauth = useCallback(
+    async (action: () => Promise<Response>): Promise<Response | null> => {
+      let res = await action();
+      if (await isReauthRequired(res)) {
+        if (!(await requestReauth())) return null;
+        res = await action();
+      }
+      return res;
+    },
+    [requestReauth],
+  );
+
+  const handleCreatePasskey = async () => {
+    setNotice(null);
+    setCreating(true);
+    try {
+      const result = await registerPasskey({ promotion: false });
+      if (result.status === 'created') {
+        await loadAccount();
+        setNotice({ kind: 'success', text: 'Passkey created. You can now use it to sign in.' });
+      } else if (result.status === 'error') {
+        setNotice({ kind: 'error', text: result.message });
+      }
+    } finally {
+      setCreating(false);
+    }
+  };
+
+  const startRename = (passkey: Passkey) => {
+    setEditingId(passkey.id);
+    setEditName(passkey.name);
+  };
+
+  const submitRename = async (e: React.FormEvent, id: string) => {
+    e.preventDefault();
+    const res = await fetch(apiUrl(`passkeys/${encodeURIComponent(id)}`), {
+      method: 'PATCH',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ name: editName }),
+    });
+    if (res.ok) {
+      // Nickname changes are server-side labels only; no Signal API call needed.
+      setEditingId(null);
+      await loadAccount();
+      setNotice({ kind: 'success', text: 'Passkey renamed.' });
+    } else {
+      const data = await res.json().catch(() => null);
+      setNotice({ kind: 'error', text: data?.error || 'Couldn’t rename that passkey.' });
+    }
+  };
+
+  const askDelete = (passkey: Passkey) => {
+    setPendingDelete(passkey);
+    deleteDialogRef.current?.showModal();
+  };
+
+  const onDeleteDialogClose = async () => {
+    const dialog = deleteDialogRef.current;
+    const choice = dialog?.returnValue;
+    if (dialog) dialog.returnValue = '';
+    const target = pendingDelete;
+    setPendingDelete(null);
+    if (choice !== 'delete' || !target) return;
+
+    setNotice(null);
+    const res = await withReauth(() =>
+      fetch(apiUrl(`passkeys/${encodeURIComponent(target.id)}`), { method: 'DELETE' }),
+    );
+    if (!res) return; // verification cancelled
+    if (res.ok) {
+      // loadAccount() re-syncs remaining credentials via signalAllAcceptedCredentials.
+      await loadAccount();
+      setNotice({ kind: 'success', text: `“${target.name}” was deleted.` });
+    } else {
+      const data = await res.json().catch(() => null);
+      setNotice({ kind: 'error', text: data?.error || 'Couldn’t delete that passkey.' });
+    }
+  };
+
+  const submitProfile = async (e: React.FormEvent) => {
+    e.preventDefault();
+    setNotice(null);
+    setSavingProfile(true);
+    try {
+      const res = await withReauth(() =>
+        fetch(apiUrl('user'), {
+          method: 'PUT',
+          headers: { 'Content-Type': 'application/json' },
+          body: JSON.stringify({ displayName }),
+        }),
+      );
+      if (!res) return;
+      if (!res.ok) {
+        const data = await res.json().catch(() => null);
+        setNotice({ kind: 'error', text: data?.error || 'Couldn’t update your profile.' });
+        return;
+      }
+      const updated = await res.json();
+      setAccount((prev) => (prev ? { ...prev, displayName: updated.displayName } : prev));
+      setNotice({ kind: 'success', text: 'Profile updated.' });
+      // Update the name shown by the password manager for this account's passkeys.
+      await syncCurrentUserDetails({
+        rpId: updated.rpId,
+        userId: updated.userId,
+        name: updated.username,
+        displayName: updated.displayName,
+      });
+    } finally {
+      setSavingProfile(false);
+    }
+  };
+
+  const signOut = async () => {
+    await fetch(apiUrl('logout'), { method: 'POST' }).catch(() => {});
+    window.location.assign(pageUrl());
+  };
+
+  const credentials = account?.credentials ?? [];
+
+  return (
+    <div className="max-w-2xl mx-auto space-y-8">
+      <div className="flex items-start justify-between gap-4">
+        <div>
+          <h1 className="text-3xl font-bold text-gray-900">Account settings</h1>
+          <p className="mt-1 text-sm text-gray-600">
+            Signed in as <strong className="font-semibold">{username}</strong>
+          </p>
+        </div>
+        <button type="button" onClick={signOut} className={buttonSecondary}>
+          Sign out
+        </button>
+      </div>
+
+      <div aria-live="polite">
+        {notice && (
+          <div
+            className={`p-3 text-sm rounded-lg ${
+              notice.kind === 'success' ? 'text-green-800 bg-green-100' : 'text-red-700 bg-red-100'
+            }`}
+            role={notice.kind === 'error' ? 'alert' : 'status'}
+          >
+            {notice.text}
+          </div>
+        )}
+      </div>
+
+      {/* Profile */}
+      <section aria-labelledby="profile-heading" className="p-6 bg-white border border-gray-200 rounded-lg shadow-sm">
+        <h2 id="profile-heading" className="text-xl font-bold text-gray-900">
+          Profile
+        </h2>
+        <form onSubmit={submitProfile} className="mt-4 space-y-4">
+          <div>
+            <label htmlFor={displayNameId} className="block text-sm font-medium text-gray-700 mb-1">
+              Display name
+            </label>
+            <input
+              id={displayNameId}
+              name="displayName"
+              type="text"
+              autoComplete="nickname"
+              required
+              maxLength={100}
+              value={displayName}
+              onChange={(e) => setDisplayName(e.target.value)}
