+            />
+            <p id="display-name-hint" className="mt-1 text-xs text-gray-500">
+              Shown in your password manager next to your passkeys. Changing it requires verification.
+            </p>
+          </div>
+          <button
+            type="submit"
+            disabled={savingProfile || displayName.trim() === (account?.displayName ?? initialDisplayName)}
+            className={buttonPrimary}
+          >
+            {savingProfile ? 'Saving…' : 'Save profile'}
+          </button>
+        </form>
+      </section>
+
+      {/* Passkeys */}
+      <section aria-labelledby="passkeys-heading" className="p-6 bg-white border border-gray-200 rounded-lg shadow-sm">
+        <div className="flex flex-wrap items-start justify-between gap-4">
+          <div>
+            <h2 id="passkeys-heading" className="text-xl font-bold text-gray-900">
+              Passkeys
+            </h2>
+            <p className="mt-1 text-sm text-gray-600 max-w-md">
+              Passkeys let you sign in with your fingerprint, face, screen lock, or a security key — no
+              password needed.
+            </p>
+          </div>
+          {canCreatePasskey && (
+            <button type="button" onClick={handleCreatePasskey} disabled={creating} className={buttonPrimary}>
+              <PlusIcon className="h-5 w-5" aria-hidden="true" />
+              {creating ? 'Creating…' : 'Create a passkey'}
+            </button>
+          )}
+        </div>
+
+        {canCreatePasskey === false && (
+          <p className="mt-4 p-3 text-sm text-gray-700 bg-gray-100 rounded-lg">
+            This browser or device doesn’t support creating passkeys. Keep using a strong, unique password,
+            or open this page on a device that supports passkeys.
+          </p>
+        )}
+
+        {loadError && (
+          <p className="mt-4 p-3 text-sm text-red-700 bg-red-100 rounded-lg" role="alert">
+            {loadError}
+          </p>
+        )}
+
+        {!account && !loadError && <p className="mt-6 text-sm text-gray-500">Loading passkeys…</p>}
+
+        {account && credentials.length === 0 && (
+          <div className="mt-6 p-6 text-center border border-dashed border-gray-300 rounded-lg">
+            <KeyIcon className="mx-auto h-8 w-8 text-gray-400" aria-hidden="true" />
+            <p className="mt-2 text-sm font-medium text-gray-900">No passkeys found</p>
+            <p className="text-sm text-gray-600">Create one to sign in faster and more securely.</p>
+          </div>
