+
+        {credentials.length > 0 && (
+          <ul className="mt-6 divide-y divide-gray-200 border-y border-gray-200">
+            {credentials.map((passkey) => (
+              <li key={passkey.id} className="py-4 flex flex-wrap items-start gap-4">
+                <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-md bg-gray-100">
+                  {passkey.providerIcon?.light || passkey.providerIcon?.dark ? (
+                    <picture>
+                      {passkey.providerIcon.dark && (
+                        <source srcSet={passkey.providerIcon.dark} media="(prefers-color-scheme: dark)" />
