+                </span>
+
+                <div className="min-w-0 flex-1">
+                  {editingId === passkey.id ? (
+                    <form onSubmit={(e) => submitRename(e, passkey.id)} className="flex flex-wrap items-center gap-2">
+                      <label htmlFor={`rename-${passkey.id}`} className="sr-only">
+                        Passkey name
+                      </label>
+                      <input
