diff --git a/src/components/ReauthDialog.tsx b/src/components/ReauthDialog.tsx
new file mode 100644
index 0000000..5acedd7
--- /dev/null
+++ b/src/components/ReauthDialog.tsx
@@ -0,0 +1,159 @@
+import React, { useCallback, useId, useRef, useState } from 'react';
+import { KeyIcon } from '@heroicons/react/24/outline';
+import {
+  isWebAuthnAvailable,
+  reauthenticateWithPasskey,
+  reauthenticateWithPassword,
+} from '../lib/passkeys';
+
+interface Options {
+  username: string;
+  hasPasskeys: boolean;
+}
+
+/**
+ * Step-up verification before sensitive account changes.
+ * Returns the dialog element to render and `requestReauth()`, which resolves to `true` once the
+ * server has recorded a fresh verification (passkey, or password as a fallback).
+ */
+export function useReauthDialog({ username, hasPasskeys }: Options) {
+  const dialogRef = useRef<HTMLDialogElement>(null);
+  const resolver = useRef<((ok: boolean) => void) | null>(null);
+  const abortRef = useRef<AbortController | null>(null);
+  const [password, setPassword] = useState('');
+  const [error, setError] = useState<string | null>(null);
+  const [busy, setBusy] = useState<'passkey' | 'password' | null>(null);
+  const titleId = useId();
+  const descId = useId();
+  const passwordId = useId();
+
+  const finish = useCallback((ok: boolean) => {
+    abortRef.current?.abort();
+    resolver.current?.(ok);
+    resolver.current = null;
+    setPassword('');
+    setBusy(null);
+    if (dialogRef.current?.open) dialogRef.current.close();
+  }, []);
+
+  const requestReauth = useCallback(() => {
+    resolver.current?.(false);
+    setError(null);
+    setPassword('');
+    dialogRef.current?.showModal();
+    return new Promise<boolean>((resolve) => {
+      resolver.current = resolve;
+    });
+  }, []);
+
+  const verifyWithPasskey = async () => {
+    setError(null);
+    setBusy('passkey');
+    abortRef.current?.abort();
+    abortRef.current = new AbortController();
+    try {
+      const result = await reauthenticateWithPasskey(abortRef.current.signal);
+      if (result.status === 'signed-in') return finish(true);
+      if (result.status === 'error') setError(result.message);
+    } finally {
+      setBusy(null);
+    }
+  };
+
+  const submitPassword = async (e: React.FormEvent) => {
+    e.preventDefault();
+    setError(null);
+    setBusy('password');
+    try {
+      const result = await reauthenticateWithPassword(password);
+      if (result.status === 'signed-in') return finish(true);
+      if (result.status === 'error') setError(result.message);
+    } finally {
+      setBusy(null);
+    }
+  };
+
+  const showPasskey = hasPasskeys && isWebAuthnAvailable();
+
+  const dialog = (
+    <dialog
+      ref={dialogRef}
+      aria-labelledby={titleId}
+      aria-describedby={descId}
+      onClose={() => finish(false)}
+      className="reauth-dialog m-auto w-full max-w-sm rounded-lg bg-white p-6 shadow-xl"
+    >
+      <h1 id={titleId} className="text-xl font-bold text-gray-900">
+        Confirm it’s you
+      </h1>
+      <p id={descId} className="mt-1 mb-4 text-sm text-gray-600">
+        For your security, verify your identity before making this change.
+      </p>
+
+      {error && (
+        <div className="mb-4 p-3 text-sm text-red-700 bg-red-100 rounded-lg" role="alert">
+          {error}
+        </div>
+      )}
+
+      {showPasskey && (
+        <>
+          <button
+            type="button"
+            autoFocus
+            onClick={verifyWithPasskey}
+            disabled={busy !== null}
+            className="w-full inline-flex items-center justify-center gap-2 py-2 px-4 rounded-md text-sm font-medium text-white bg-gray-900 hover:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-900 disabled:opacity-75"
+          >
+            <KeyIcon className="h-5 w-5" aria-hidden="true" />
+            {busy === 'passkey' ? 'Waiting for passkey…' : 'Verify with passkey'}
+          </button>
+          <div className="my-4 flex items-center gap-3 text-xs uppercase tracking-wide text-gray-500">
+            <span className="h-px flex-1 bg-gray-200" />
+            or use your password
+            <span className="h-px flex-1 bg-gray-200" />
+          </div>
+        </>
+      )}
+
+      <form onSubmit={submitPassword} className="space-y-3">
+        {/* Helps password managers pick the right saved credential. */}
+        <input type="text" name="username" autoComplete="username" value={username} readOnly hidden />
+        <div>
+          <label htmlFor={passwordId} className="block text-sm font-medium text-gray-700 mb-1">
+            Password
+          </label>
+          <input
+            id={passwordId}
+            type="password"
+            name="password"
+            autoComplete="current-password"
+            required
+            autoFocus={!showPasskey}
+            value={password}
+            onChange={(e) => setPassword(e.target.value)}
+            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
+          />
+        </div>
+        <div className="flex justify-end gap-2 pt-2">
+          <button
+            type="button"
+            onClick={() => finish(false)}
+            className="py-2 px-4 rounded-md text-sm font-medium text-gray-700 hover:bg-gray-100"
+          >
+            Cancel
+          </button>
+          <button
+            type="submit"
+            disabled={busy !== null}
+            className="py-2 px-4 rounded-md text-sm font-medium border border-gray-300 text-gray-900 hover:bg-gray-50 disabled:opacity-75"
+          >
+            {busy === 'password' ? 'Verifying…' : 'Verify password'}
+          </button>
+        </div>
+      </form>
+    </dialog>
+  );
+
+  return { dialog, requestReauth };
+}
