diff --git a/src/lib/auth/aaguid.ts b/src/lib/auth/aaguid.ts
new file mode 100644
index 0000000..98411f8
--- /dev/null
+++ b/src/lib/auth/aaguid.ts
@@ -0,0 +1,51 @@
+import type { ProviderIcon } from './store';
+
+/**
+ * AAGUID -> passkey provider lookup, used ONLY for UX hints (name + icon) in the passkey list.
+ * Never use AAGUIDs for security decisions: platform passkeys don't attest them.
+ */
+
+const REGISTRY_URL =
+  'https://raw.githubusercontent.com/passkeydeveloper/passkey-authenticator-aaguids/refs/heads/main/combined_aaguid.json';
+const ZERO_AAGUID = '00000000-0000-0000-0000-000000000000';
+const RETRY_AFTER_MS = 10 * 60 * 1000;
+
+type Registry = Record<string, { name?: string; icon_light?: string; icon_dark?: string }>;
+
+let registry: Registry | null = null;
+let lastFailure = 0;
+let inflight: Promise<Registry | null> | null = null;
+
+async function loadRegistry(): Promise<Registry | null> {
+  if (registry) return registry;
+  if (Date.now() - lastFailure < RETRY_AFTER_MS) return null;
+  inflight ??= (async () => {
+    try {
+      const res = await fetch(REGISTRY_URL, { signal: AbortSignal.timeout(5000) });
+      if (!res.ok) throw new Error(`HTTP ${res.status}`);
+      registry = (await res.json()) as Registry;
+      return registry;
+    } catch (err) {
+      console.warn('AAGUID registry unavailable:', err);
+      lastFailure = Date.now();
+      return null;
+    } finally {
+      inflight = null;
+    }
+  })();
+  return inflight;
+}
+
+export async function lookupProvider(
+  aaguid: string,
+): Promise<{ name: string; icon?: ProviderIcon }> {
+  if (!aaguid || aaguid === ZERO_AAGUID) {
+    return { name: 'Passkey' };
+  }
+  const entry = (await loadRegistry())?.[aaguid];
+  if (!entry?.name) return { name: 'Passkey' };
+  return {
+    name: entry.name,
+    icon: entry.icon_light || entry.icon_dark ? { light: entry.icon_light, dark: entry.icon_dark } : undefined,
+  };
+}
diff --git a/src/lib/auth/server.ts b/src/lib/auth/server.ts
new file mode 100644
index 0000000..114b559
--- /dev/null
+++ b/src/lib/auth/server.ts
@@ -0,0 +1,110 @@
+import type { APIContext } from 'astro';
+import { getUser, type StoredPasskeyCredential, type UserRecord } from './store';
+
+export const RP_NAME = 'The DevTools Times';
+export const TIMES_API = 'https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api';
+
+/** Sensitive actions require a sign-in or reauthentication within this window. */
+export const REAUTH_WINDOW_MS = 5 * 60 * 1000;
+
+type Session = NonNullable<APIContext['session']>;
+
+/**
+ * Relying Party ID. Configure `RP_ID` (e.g. a registrable parent domain) in production; it falls
+ * back to the host the server received the request on. It is always sent to the client inside
+ * server-generated options so the client never derives it from `location.hostname`.
+ */
+export function getRpId(url: URL): string {
+  return process.env.RP_ID || url.hostname;
+}
+
+export function getExpectedOrigins(url: URL): string[] {
+  if (process.env.WEBAUTHN_ORIGINS) {
+    return process.env.WEBAUTHN_ORIGINS.split(',').map((o) => o.trim()).filter(Boolean);
+  }
+  // Behind TLS-terminating proxies (e.g. Cloud Run) the server may see http://.
+  return [...new Set([url.origin, `https://${url.host}`])];
+}
+
+export function json(data: unknown, status = 200): Response {
+  return new Response(JSON.stringify(data), {
+    status,
+    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' },
+  });
+}
+
+export async function readJson<T = Record<string, unknown>>(request: Request): Promise<T | null> {
+  try {
+    return (await request.json()) as T;
+  } catch {
+    return null;
+  }
+}
+
+export async function currentUser(session: APIContext['session']): Promise<UserRecord | null> {
+  const sessionUser = await session?.get('user');
+  if (!sessionUser?.username) return null;
+  return (await getUser(sessionUser.username)) ?? null;
+}
+
+export async function signIn(
+  session: Session,
+  user: UserRecord,
+  method: 'password' | 'passkey',
+): Promise<void> {
+  // Rotate the session ID on privilege change to prevent session fixation.
+  await session.regenerate();
+  session.set('user', { username: user.username, method });
+  // A fresh sign-in counts as a recent authentication.
+  session.set('reauthAt', Date.now());
+}
+
+export async function hasRecentAuth(session: APIContext['session']): Promise<boolean> {
+  const at = await session?.get('reauthAt');
+  return typeof at === 'number' && Date.now() - at < REAUTH_WINDOW_MS;
+}
+
+export function reauthRequired(): Response {
+  return json({ error: 'reauth_required', message: 'Please confirm it’s you to continue.' }, 401);
+}
+
+export function unauthorized(): Response {
+  return json({ error: 'unauthenticated', message: 'You need to sign in first.' }, 401);
+}
+
+export function publicUser(user: UserRecord, url: URL) {
+  return {
+    username: user.username,
+    displayName: user.displayName,
+    userId: user.passkeyUserId,
+    rpId: getRpId(url),
+  };
+}
+
+/** Credential view safe to send to the browser (no public key or counter). */
+export function publicCredential(c: StoredPasskeyCredential) {
+  return {
+    id: c.id,
+    name: c.name,
+    providerName: c.providerName,
+    providerIcon: c.providerIcon,
+    credentialDeviceType: c.credentialDeviceType,
+    credentialBackedUp: c.credentialBackedUp,
+    registeredAt: c.registeredAt,
+    lastUsedAt: c.lastUsedAt,
+  };
+}
+
+/** Verify a username/password pair against the Times account API. */
+export async function checkPassword(
+  username: string,
+  password: string,
+): Promise<{ ok: boolean; status: number; data: Record<string, unknown> }> {
+  const res = await fetch(`${TIMES_API}/login`, {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({ username, password }),
+  });
+  const data = ((await res.json().catch(() => ({}))) ?? {}) as Record<string, unknown>;
+  return { ok: res.ok, status: res.status, data };
+}
diff --git a/src/lib/auth/store.ts b/src/lib/auth/store.ts
new file mode 100644
index 0000000..b1ea146
--- /dev/null
+++ b/src/lib/auth/store.ts
@@ -0,0 +1,144 @@
+import { promises as fs } from 'node:fs';
+import os from 'node:os';
+import path from 'node:path';
+import { randomBytes } from 'node:crypto';
+
+/**
+ * Minimal JSON-file backed persistence for local accounts and passkey credentials.
+ *
+ * Password accounts live in the external Times API; this store only mirrors the username so
+ * passkeys can be attached to it. Point `AUTH_DB_PATH` at persistent storage in production.
+ */
+
+export interface UserRecord {
+  username: string;
+  displayName: string;
+  /** Unpadded Base64URL WebAuthn user handle (random, not derived from personal data). */
+  passkeyUserId: string;
+  createdAt: number;
+}
+
+export interface ProviderIcon {
+  light?: string;
+  dark?: string;
+}
+
+export interface StoredPasskeyCredential {
+  id: string; // Base64URL-encoded credential ID (unique lookup key)
+  passkeyUserId: string; // Associated user handle
+  credentialPublicKey: string; // Base64URL-encoded public key
+  credentialType: 'public-key';
+  credentialDeviceType: 'singleDevice' | 'multiDevice';
+  credentialBackedUp: boolean;
+  aaguid: string;
+  providerName: string; // Provider name derived from AAGUID registry
+  providerIcon?: ProviderIcon;
+  name: string; // Display label: provider name or user-chosen nickname
+  transports: string[];
+  lastUsedAt?: number;
+  registeredAt: number;
+  counter: number;
+}
+
+interface Database {
+  users: Record<string, UserRecord>;
+  credentials: Record<string, StoredPasskeyCredential>;
+}
+
+const DB_PATH =
+  process.env.AUTH_DB_PATH || path.join(os.tmpdir(), 'devtools-times-auth.json');
+
+let cache: Database | null = null;
+let writeQueue: Promise<void> = Promise.resolve();
+
+async function load(): Promise<Database> {
+  if (cache) return cache;
+  try {
+    const raw = await fs.readFile(DB_PATH, 'utf8');
+    const parsed = JSON.parse(raw) as Partial<Database>;
+    cache = { users: parsed.users ?? {}, credentials: parsed.credentials ?? {} };
+  } catch {
+    cache = { users: {}, credentials: {} };
+  }
+  return cache;
+}
+
+function persist(db: Database): Promise<void> {
+  writeQueue = writeQueue
+    .then(async () => {
+      await fs.mkdir(path.dirname(DB_PATH), { recursive: true });
+      const tmp = `${DB_PATH}.${process.pid}.tmp`;
+      await fs.writeFile(tmp, JSON.stringify(db));
+      await fs.rename(tmp, DB_PATH);
+    })
+    .catch((err) => {
+      console.warn('Failed to persist auth store:', err);
+    });
+  return writeQueue;
+}
+
+export function newUserHandle(): string {
+  return randomBytes(32).toString('base64url');
+}
+
+export async function getUser(username: string): Promise<UserRecord | undefined> {
+  const db = await load();
+  return db.users[username];
+}
+
+export async function getUserByHandle(passkeyUserId: string): Promise<UserRecord | undefined> {
+  const db = await load();
+  return Object.values(db.users).find((u) => u.passkeyUserId === passkeyUserId);
+}
+
+export async function ensureUser(username: string): Promise<UserRecord> {
+  const db = await load();
+  let user = db.users[username];
+  if (!user) {
+    user = {
+      username,
+      displayName: username,
+      passkeyUserId: newUserHandle(),
+      createdAt: Date.now(),
+    };
+    db.users[username] = user;
+    await persist(db);
+  }
+  return user;
+}
+
+export async function updateUser(
+  username: string,
+  patch: Partial<Pick<UserRecord, 'displayName'>>,
+): Promise<UserRecord | undefined> {
+  const db = await load();
+  const user = db.users[username];
+  if (!user) return undefined;
+  Object.assign(user, patch);
+  await persist(db);
+  return user;
+}
+
+export async function listCredentials(passkeyUserId: string): Promise<StoredPasskeyCredential[]> {
+  const db = await load();
+  return Object.values(db.credentials)
+    .filter((c) => c.passkeyUserId === passkeyUserId)
+    .sort((a, b) => a.registeredAt - b.registeredAt);
+}
+
+export async function getCredential(id: string): Promise<StoredPasskeyCredential | undefined> {
+  const db = await load();
+  return db.credentials[id];
+}
+
+export async function saveCredential(cred: StoredPasskeyCredential): Promise<void> {
+  const db = await load();
+  db.credentials[cred.id] = cred;
+  await persist(db);
+}
+
+export async function deleteCredential(id: string): Promise<void> {
+  const db = await load();
+  delete db.credentials[id];
+  await persist(db);
+}
diff --git a/src/lib/passkeys.ts b/src/lib/passkeys.ts
new file mode 100644
index 0000000..8c8e382
--- /dev/null
+++ b/src/lib/passkeys.ts
@@ -0,0 +1,355 @@
+/**
+ * Browser-side passkey helpers built directly on the native WebAuthn APIs.
+ * `webauthn-polyfills` fills in getClientCapabilities / parse*OptionsFromJSON / toJSON
+ * where PublicKeyCredential exists but those newer statics don't.
+ */
+
+const BASE = import.meta.env.BASE_URL.endsWith('/')
+  ? import.meta.env.BASE_URL
+  : `${import.meta.env.BASE_URL}/`;
+
+export const apiUrl = (path: string) => `${BASE}api/auth/${path}`;
+export const pageUrl = (path = '') => `${BASE}${path}`;
+
+type Capabilities = Partial<Record<
+  | 'conditionalCreate'
+  | 'conditionalGet'
+  | 'hybridTransport'
+  | 'passkeyPlatformAuthenticator'
+  | 'userVerifyingPlatformAuthenticator'
+  | 'relatedOrigins'
+  | 'signalAllAcceptedCredentials'
+  | 'signalCurrentUserDetails'
+  | 'signalUnknownCredential',
+  boolean
+>>;
+
+interface PKCStatic {
+  getClientCapabilities?: () => Promise<Capabilities>;
+  parseCreationOptionsFromJSON: (json: unknown) => PublicKeyCredentialCreationOptions;
+  parseRequestOptionsFromJSON: (json: unknown) => PublicKeyCredentialRequestOptions;
+  signalUnknownCredential?: (o: { rpId: string; credentialId: string }) => Promise<void>;
+  signalAllAcceptedCredentials?: (o: {
+    rpId: string;
+    userId: string;
+    allAcceptedCredentialIds: string[];
+  }) => Promise<void>;
+  signalCurrentUserDetails?: (o: {
+    rpId: string;
+    userId: string;
+    name: string;
+    displayName: string;
+  }) => Promise<void>;
+}
+
+type JSONCredential = PublicKeyCredential & { toJSON(): { id: string } & Record<string, unknown> };
+
+const PKC = () => window.PublicKeyCredential as unknown as PKCStatic;
+
+let polyfillsLoaded: Promise<unknown> | null = null;
+
+export function isWebAuthnAvailable(): boolean {
+  return typeof window !== 'undefined' && typeof window.PublicKeyCredential === 'function';
+}
+
+async function ensurePolyfills(): Promise<boolean> {
+  if (!isWebAuthnAvailable()) return false;
+  polyfillsLoaded ??= import('webauthn-polyfills').catch((err) =>
+    console.warn('WebAuthn polyfills failed to load:', err),
+  );
+  await polyfillsLoaded;
+  return true;
+}
+
+export async function getCapabilities(): Promise<Capabilities> {
+  if (!(await ensurePolyfills())) return {};
+  try {
+    return (await PKC().getClientCapabilities?.()) ?? {};
+  } catch {
+    return {};
+  }
+}
+
+export function isValidBase64Url(value: unknown): value is string {
+  return (
+    typeof value === 'string' &&
+    value.length > 0 &&
+    value.length % 4 !== 1 &&
+    /^[A-Za-z0-9_-]+$/.test(value)
+  );
+}
+
+async function postJSON(path: string, body?: unknown): Promise<Response> {
+  return fetch(apiUrl(path), {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    credentials: 'same-origin',
+    body: JSON.stringify(body ?? {}),
+  });
+}
+
+async function errorMessage(res: Response, fallback: string): Promise<string> {
+  const data = await res.json().catch(() => null);
+  return data?.message || data?.error || fallback;
+}
+
+// ---------------------------------------------------------------------------
+// Signal API (progressive enhancement; failures are non-fatal and only warned)
+// ---------------------------------------------------------------------------
+
+async function signalUnknownCredential(rpId: string | undefined, credentialId: string) {
+  const pkc = PKC();
+  if (!rpId || !pkc.signalUnknownCredential || !isValidBase64Url(credentialId)) return;
+  try {
+    // rpId always comes from server-provided options, never location.hostname.
+    await pkc.signalUnknownCredential({ rpId, credentialId });
+  } catch (e) {
+    console.warn('signalUnknownCredential warning:', e);
+  }
+}
+
+export async function syncAcceptedCredentials(
+  rpId: string,
+  userId: string,
+  credentialIds: string[],
+): Promise<void> {
+  if (!isWebAuthnAvailable() || !PKC().signalAllAcceptedCredentials) return;
+  if (!rpId || !isValidBase64Url(userId) || !credentialIds.every(isValidBase64Url)) {
+    console.warn('signalAllAcceptedCredentials skipped: invalid rpId, userId or credential IDs.');
+    return;
+  }
+  try {
+    await PKC().signalAllAcceptedCredentials!({
+      rpId,
+      userId,
+      allAcceptedCredentialIds: credentialIds,
+    });
+  } catch (e) {
+    console.warn('signalAllAcceptedCredentials warning:', e);
+  }
+}
+
+export async function syncCurrentUserDetails(details: {
+  rpId: string;
+  userId: string;
+  name: string;
+  displayName: string;
+}): Promise<void> {
+  if (!isWebAuthnAvailable() || !PKC().signalCurrentUserDetails) return;
+  if (!details.rpId || !isValidBase64Url(details.userId)) {
+    console.warn('signalCurrentUserDetails skipped: invalid rpId or userId.');
+    return;
+  }
+  try {
+    await PKC().signalCurrentUserDetails!(details);
+  } catch (e) {
+    console.warn('signalCurrentUserDetails warning:', e);
+  }
+}
+
+// ---------------------------------------------------------------------------
+// Registration
+// ---------------------------------------------------------------------------
+
+export type RegisterResult =
+  | { status: 'created' }
+  | { status: 'cancelled' }
+  | { status: 'error'; message: string };
+
+/**
+ * Explicit passkey creation.
+ * `promotion: true` restricts to platform authenticators (post-sign-up prompt);
+ * otherwise (account settings) security keys are allowed too.
+ */
+export async function registerPasskey({ promotion = false } = {}): Promise<RegisterResult> {
+  if (!(await ensurePolyfills())) {
+    return { status: 'error', message: 'Passkeys aren’t supported in this browser.' };
+  }
+
+  const optionsRes = await postJSON('passkey/register-options', { promotion });
+  if (!optionsRes.ok) {
+    return { status: 'error', message: await errorMessage(optionsRes, 'Couldn’t start passkey creation.') };
+  }
+  const publicKey = PKC().parseCreationOptionsFromJSON(await optionsRes.json());
+
+  let credential: JSONCredential;
+  try {
+    credential = (await navigator.credentials.create({ publicKey })) as JSONCredential;
+  } catch (err) {
+    const name = (err as DOMException).name;
+    if (name === 'InvalidStateError') {
+      return { status: 'error', message: 'A passkey for this account already exists in this password manager.' };
+    }
+    if (name === 'NotAllowedError' || name === 'AbortError') return { status: 'cancelled' };
+    if (name === 'SecurityError') {
+      return { status: 'error', message: 'Passkeys can’t be used on this site configuration (secure origin / RP ID).' };
+    }
+    return { status: 'error', message: 'Something went wrong creating your passkey.' };
+  }
+
+  const encoded = credential.toJSON();
+  try {
+    const verifyRes = await postJSON('passkey/register-verify', encoded);
+    if (!verifyRes.ok) {
+      // The provider saved a passkey the server rejected — tell it to drop the orphan.
+      await signalUnknownCredential(publicKey.rp.id, encoded.id);
+      return { status: 'error', message: await errorMessage(verifyRes, 'Your passkey couldn’t be saved.') };
+    }
+  } catch {
+    await signalUnknownCredential(publicKey.rp.id, encoded.id);
+    return { status: 'error', message: 'Network error while saving your passkey.' };
+  }
+  return { status: 'created' };
+}
+
+/**
+ * Conditional create: silently offer to save a passkey right after a successful password sign-in.
+ * All failures are swallowed; this must never block or show errors.
+ */
+export async function conditionalCreatePasskey(timeoutMs = 10_000): Promise<boolean> {
+  const caps = await getCapabilities();
+  if (caps.conditionalCreate !== true) return false;
+
+  let publicKey: PublicKeyCredentialCreationOptions;
+  try {
+    const optionsRes = await postJSON('passkey/register-options', { conditional: true });
+    if (!optionsRes.ok) return false;
+    publicKey = PKC().parseCreationOptionsFromJSON(await optionsRes.json());
+  } catch {
+    return false;
+  }
+
+  let credential: JSONCredential;
+  try {
+    credential = (await navigator.credentials.create({
+      publicKey,
+      mediation: 'conditional',
+      // Never let a pending silent request hold up the post-sign-in navigation.
+      signal: AbortSignal.timeout(timeoutMs),
+    } as CredentialCreationOptions)) as JSONCredential;
+  } catch (e) {
+    if (!['InvalidStateError', 'NotAllowedError', 'AbortError', 'TimeoutError'].includes((e as DOMException).name)) {
+      console.warn('Unexpected conditional create error:', e);
+    }
+    return false;
+  }
+
+  const encoded = credential.toJSON();
+  try {
+    const res = await postJSON('passkey/register-verify', encoded);
+    if (!res.ok) {
+      await signalUnknownCredential(publicKey.rp.id, encoded.id);
+      return false;
+    }
+  } catch {
+    await signalUnknownCredential(publicKey.rp.id, encoded.id);
+    return false;
+  }
+  return true;
+}
+
+// ---------------------------------------------------------------------------
+// Authentication
+// ---------------------------------------------------------------------------
+
+export type SignInResult =
+  | { status: 'signed-in' }
+  | { status: 'cancelled' }
+  | { status: 'error'; message: string };
+
+async function authenticate(
+  mediation: CredentialMediationRequirement | undefined,
+  signal: AbortSignal,
+): Promise<SignInResult> {
+  const optionsRes = await postJSON('passkey/login-options');
+  if (!optionsRes.ok) {
+    return { status: 'error', message: await errorMessage(optionsRes, 'Couldn’t start passkey sign-in.') };
+  }
+  const publicKey = PKC().parseRequestOptionsFromJSON(await optionsRes.json());
+
+  let credential: JSONCredential;
+  try {
+    credential = (await navigator.credentials.get({
+      publicKey,
+      signal,
+      ...(mediation && { mediation }),
+    })) as JSONCredential;
+  } catch (err) {
+    const name = (err as DOMException).name;
+    if (name === 'NotAllowedError' || name === 'AbortError') return { status: 'cancelled' };
+    console.warn('Passkey sign-in error:', err);
+    return { status: 'error', message: 'Passkey sign-in failed. Please try again.' };
+  }
+
+  const encoded = credential.toJSON();
+  try {
+    const verifyRes = await postJSON('passkey/login-verify', encoded);
+    if (verifyRes.ok) return { status: 'signed-in' };
+    if (verifyRes.status === 404) {
+      // Unauthenticated + credential unknown to the server: let the provider hide it.
+      await signalUnknownCredential(publicKey.rpId, encoded.id);
+    }
+    return { status: 'error', message: await errorMessage(verifyRes, 'Passkey sign-in failed.') };
+  } catch {
+    return { status: 'error', message: 'Network error during passkey sign-in.' };
+  }
+}
+
+/** Arm passkey suggestions in the username field's autofill (Conditional UI). */
+export async function startConditionalSignIn(signal: AbortSignal): Promise<SignInResult | null> {
+  const caps = await getCapabilities();
+  if (caps.conditionalGet !== true || signal.aborted) return null;
+  return authenticate('conditional', signal);
+}
+
+/** Explicit "Sign in with a passkey" button. */
+export async function signInWithPasskey(signal: AbortSignal): Promise<SignInResult> {
+  if (!(await ensurePolyfills())) {
+    return { status: 'error', message: 'Passkeys aren’t supported in this browser.' };
+  }
+  return authenticate(undefined, signal);
+}
+
+// ---------------------------------------------------------------------------
+// Reauthentication
+// ---------------------------------------------------------------------------
+
+export async function reauthenticateWithPasskey(signal?: AbortSignal): Promise<SignInResult> {
+  if (!(await ensurePolyfills())) {
+    return { status: 'error', message: 'Passkeys aren’t supported in this browser.' };
+  }
+  const optionsRes = await postJSON('reauth/options');
+  if (!optionsRes.ok) {
+    return { status: 'error', message: await errorMessage(optionsRes, 'Couldn’t start verification.') };
+  }
+  const publicKey = PKC().parseRequestOptionsFromJSON(await optionsRes.json());
+
+  let credential: JSONCredential;
+  try {
+    credential = (await navigator.credentials.get({ publicKey, signal })) as JSONCredential;
+  } catch (err) {
+    const name = (err as DOMException).name;
+    if (name === 'NotAllowedError' || name === 'AbortError') return { status: 'cancelled' };
+    return { status: 'error', message: 'Verification failed. Please try again.' };
+  }
+
+  const encoded = credential.toJSON();
+  try {
+    const verifyRes = await postJSON('reauth/verify', encoded);
+    if (verifyRes.ok) return { status: 'signed-in' };
+    if (verifyRes.status === 404) await signalUnknownCredential(publicKey.rpId, encoded.id);
+    return { status: 'error', message: await errorMessage(verifyRes, 'Verification failed.') };
+  } catch {
+    return { status: 'error', message: 'Network error during verification.' };
+  }
+}
+
+export async function reauthenticateWithPassword(password: string): Promise<SignInResult> {
+  try {
+    const res = await postJSON('reauth/password', { password });
+    if (res.ok) return { status: 'signed-in' };
+    return { status: 'error', message: await errorMessage(res, 'Verification failed.') };
+  } catch {
+    return { status: 'error', message: 'Network error during verification.' };
+  }
+}
