+import type { APIRoute } from 'astro';
+import { ensureUser } from '../../../lib/auth/store';
+import { checkPassword, json, publicUser, readJson, signIn } from '../../../lib/auth/server';
+
+/** Password sign-in: verified against the Times account API, then a local session is created. */
+export const POST: APIRoute = async ({ request, session, url }) => {
+  const body = await readJson<{ username?: string; password?: string }>(request);
+  const username = body?.username?.trim();
+  const password = body?.password;
+  if (!username || !password || !session) {
+    return json({ error: 'Username and password are required.' }, 400);
+  }
+
+  try {
+    const result = await checkPassword(username, password);
+    if (!result.ok) return json(result.data, result.status);
+
+    const user = await ensureUser(username);
+    await signIn(session, user, 'password');
+    return json({ ...result.data, user: publicUser(user, url) });
+  } catch (err) {
+    console.error('Login proxy failed:', err);
+    return json({ error: 'Sign-in service unavailable.' }, 502);
+  }
+};
