+import type { APIRoute } from 'astro';
+import { generateAuthenticationOptions } from '@simplewebauthn/server';
+import { getRpId, json } from '../../../../lib/auth/server';
+
+/** Request options for discoverable passkey sign-in (autofill or button). */
+export const POST: APIRoute = async ({ session, url }) => {
+  if (!session) return json({ error: 'Sessions unavailable.' }, 500);
+
+  const userVerification = 'preferred' as const;
+  const options = await generateAuthenticationOptions({
+    rpID: getRpId(url),
+    allowCredentials: [], // discoverable credentials: no username needed
+    userVerification,
+  });
+
+  // Persist the expected UV level server-side so the client can't downgrade it.
+  session.set('passkeyAuthentication', {
+    challenge: options.challenge,
+    userVerification,
+    expires: Date.now() + 5 * 60 * 1000,
+  });
+
+  return json(options);
+};
