@@ -0,0 +1,69 @@
+import type { APIRoute } from 'astro';
+import { verifyAuthenticationResponse, type AuthenticationResponseJSON } from '@simplewebauthn/server';
+import { getCredential, getUserByHandle, saveCredential } from '../../../../lib/auth/store';
+import {
+  getExpectedOrigins,
+  getRpId,
+  json,
+  publicUser,
+  readJson,
+  signIn,
+} from '../../../../lib/auth/server';
+
+export const POST: APIRoute = async ({ request, session, url }) => {
+  if (!session) return json({ error: 'Sessions unavailable.' }, 500);
+
+  const pending = await session.get('passkeyAuthentication');
+  session.delete('passkeyAuthentication');
+  if (!pending || pending.expires < Date.now()) {
+    return json({ error: 'Sign-in request expired. Please try again.' }, 400);
+  }
+
+  const response = await readJson<AuthenticationResponseJSON>(request);
+  if (!response?.id) return json({ error: 'Invalid sign-in response.' }, 400);
+
+  const stored = await getCredential(response.id);
+  if (!stored) {
+    // 404 lets the client tell the password manager this passkey is gone (signalUnknownCredential).
+    return json({ error: 'This passkey isn’t registered with The DevTools Times.' }, 404);
+  }
+
+  const user = await getUserByHandle(stored.passkeyUserId);
+  if (!user || (response.response.userHandle && response.response.userHandle !== user.passkeyUserId)) {
+    return json({ error: 'Passkey could not be verified.' }, 400);
+  }
+
+  let verification;
+  try {
+    verification = await verifyAuthenticationResponse({
+      response,
+      expectedChallenge: pending.challenge,
+      expectedOrigin: getExpectedOrigins(url),
+      expectedRPID: getRpId(url),
+      credential: {
+        id: stored.id,
+        publicKey: new Uint8Array(Buffer.from(stored.credentialPublicKey, 'base64url')),
+        counter: stored.counter,
+        transports: stored.transports,
+      },
+      requireUserVerification: pending.userVerification === 'required',
+    });
+  } catch (err) {
+    console.warn('Passkey authentication failed:', err);
+    return json({ error: 'Passkey could not be verified.' }, 400);
+  }
+
+  if (!verification.verified) return json({ error: 'Passkey could not be verified.' }, 400);
+
+  const { newCounter, credentialBackedUp, credentialDeviceType } = verification.authenticationInfo;
+  await saveCredential({
+    ...stored,
+    counter: newCounter,
+    credentialBackedUp,
+    credentialDeviceType,
+    lastUsedAt: Date.now(),
+  });
+
+  await signIn(session, user, 'passkey');
+  return json({ user: publicUser(user, url) });
+};
