+import type { APIRoute } from 'astro';
+import { generateRegistrationOptions } from '@simplewebauthn/server';
+import { listCredentials } from '../../../../lib/auth/store';
+import { RP_NAME, currentUser, getRpId, json, readJson, unauthorized } from '../../../../lib/auth/server';
+
+/**
+ * Creation options for a new passkey on the signed-in account.
+ * - `promotion` (post-sign-up prompt) and `conditional` (silent post-password-login create)
+ *   restrict to platform authenticators.
+ * - Management flow (account settings) omits `authenticatorAttachment` so security keys work too.
+ */
+export const POST: APIRoute = async ({ request, session, url }) => {
+  const user = await currentUser(session);
+  if (!user || !session) return unauthorized();
+
+  const body = (await readJson<{ promotion?: boolean; conditional?: boolean }>(request)) ?? {};
+  const conditional = body.conditional === true;
+  const platformOnly = conditional || body.promotion === true;
+
+  const existing = await listCredentials(user.passkeyUserId);
+  const options = await generateRegistrationOptions({
+    rpName: RP_NAME,
+    rpID: getRpId(url),
+    userName: user.username,
+    userID: new Uint8Array(Buffer.from(user.passkeyUserId, 'base64url')),
+    userDisplayName: user.displayName || user.username,
+    attestationType: 'none',
+    excludeCredentials: existing.map((c) => ({ id: c.id, transports: c.transports })),
+    authenticatorSelection: {
+      residentKey: 'required',
+      requireResidentKey: true,
+      userVerification: 'preferred',
+      ...(platformOnly && { authenticatorAttachment: 'platform' as const }),
+    },
+  });
+
+  session.set('passkeyRegistration', {
+    challenge: options.challenge,
+    conditional,
+    expires: Date.now() + 5 * 60 * 1000,
+  });
+
+  return json(options);
+};
