@@ -0,0 +1,76 @@
+import type { APIRoute } from 'astro';
+import { verifyRegistrationResponse, type RegistrationResponseJSON } from '@simplewebauthn/server';
+import { lookupProvider } from '../../../../lib/auth/aaguid';
+import { getCredential, saveCredential } from '../../../../lib/auth/store';
+import {
+  currentUser,
+  getExpectedOrigins,
+  getRpId,
+  json,
+  publicCredential,
+  readJson,
+  unauthorized,
+} from '../../../../lib/auth/server';
+
+export const POST: APIRoute = async ({ request, session, url }) => {
+  const user = await currentUser(session);
+  if (!user || !session) return unauthorized();
+
+  const pending = await session.get('passkeyRegistration');
+  session.delete('passkeyRegistration');
+  if (!pending || pending.expires < Date.now()) {
+    return json({ error: 'Registration expired. Please try again.' }, 400);
+  }
+
+  const response = await readJson<RegistrationResponseJSON>(request);
+  if (!response?.id) return json({ error: 'Invalid registration response.' }, 400);
+
+  let verification;
+  try {
+    verification = await verifyRegistrationResponse({
+      response,
+      expectedChallenge: pending.challenge,
+      expectedOrigin: getExpectedOrigins(url),
+      expectedRPID: getRpId(url),
+      // UP may be absent only for conditional-create (automatic) registrations.
+      requireUserPresence: !pending.conditional,
+      // Options asked for userVerification: "preferred", so don't fail UV-less authenticators.
+      requireUserVerification: false,
+    });
+  } catch (err) {
+    console.warn('Passkey registration verification failed:', err);
+    return json({ error: 'Passkey could not be verified.' }, 400);
+  }
+
+  if (!verification.verified) {
+    return json({ error: 'Passkey could not be verified.' }, 400);
+  }
+
+  const { credential, credentialDeviceType, credentialBackedUp, aaguid } =
+    verification.registrationInfo;
+
+  if (await getCredential(credential.id)) {
+    return json({ error: 'This passkey is already registered.' }, 409);
+  }
+
+  const provider = await lookupProvider(aaguid);
+  const now = Date.now();
+  const stored = {
+    id: credential.id,
+    passkeyUserId: user.passkeyUserId,
+    credentialPublicKey: Buffer.from(credential.publicKey).toString('base64url'),
+    credentialType: 'public-key' as const,
+    credentialDeviceType,
+    credentialBackedUp,
+    aaguid,
+    providerName: provider.name,
+    providerIcon: provider.icon,
+    name: provider.name,
+    transports: credential.transports ?? response.response.transports ?? [],
+    registeredAt: now,
+    counter: credential.counter,
+  };
+  await saveCredential(stored);
+
+  return json({ credential: publicCredential(stored) });
+};
diff --git a/src/pages/api/auth/passkeys/[id].ts b/src/pages/api/auth/passkeys/[id].ts
