@@ -0,0 +1,47 @@
+import type { APIRoute } from 'astro';
+import { deleteCredential, getCredential, saveCredential } from '../../../../lib/auth/store';
+import {
+  currentUser,
+  hasRecentAuth,
+  json,
+  publicCredential,
+  readJson,
+  reauthRequired,
+  unauthorized,
+} from '../../../../lib/auth/server';
+
+/** Rename a passkey (server-side label only). */
+export const PATCH: APIRoute = async ({ params, request, session }) => {
+  const user = await currentUser(session);
+  if (!user) return unauthorized();
+
+  const cred = params.id ? await getCredential(params.id) : undefined;
+  if (!cred || cred.passkeyUserId !== user.passkeyUserId) {
+    return json({ error: 'Passkey not found.' }, 404);
+  }
+
+  const body = await readJson<{ name?: string }>(request);
+  const name = body?.name?.trim();
+  if (!name || name.length > 64) {
+    return json({ error: 'Name must be between 1 and 64 characters.' }, 400);
+  }
+
+  const updated = { ...cred, name };
+  await saveCredential(updated);
+  return json({ credential: publicCredential(updated) });
+};
+
+/** Delete a passkey. Sensitive: requires a recent (re)authentication. */
+export const DELETE: APIRoute = async ({ params, session }) => {
+  const user = await currentUser(session);
+  if (!user) return unauthorized();
+
+  const cred = params.id ? await getCredential(params.id) : undefined;
+  if (!cred || cred.passkeyUserId !== user.passkeyUserId) {
+    return json({ error: 'Passkey not found.' }, 404);
+  }
+  if (!(await hasRecentAuth(session))) return reauthRequired();
+
+  await deleteCredential(cred.id);
+  return json({ ok: true });
+};
