+import type { APIRoute } from 'astro';
+import { listCredentials } from '../../../../lib/auth/store';
+import { currentUser, getRpId, json, publicCredential, unauthorized } from '../../../../lib/auth/server';
+
+/** List the signed-in user's passkeys plus the rpId/userId needed for Signal API sync. */
+export const GET: APIRoute = async ({ session, url }) => {
+  const user = await currentUser(session);
+  if (!user) return unauthorized();
+
+  const creds = await listCredentials(user.passkeyUserId);
+  return json({
+    rpId: getRpId(url),
+    userId: user.passkeyUserId,
+    username: user.username,
+    displayName: user.displayName,
+    credentials: creds.map(publicCredential),
+  });
+};
