+import type { APIRoute } from 'astro';
+import { generateAuthenticationOptions } from '@simplewebauthn/server';
+import { listCredentials } from '../../../../lib/auth/store';
+import { currentUser, getRpId, json, unauthorized } from '../../../../lib/auth/server';
+
+/** Step-up options constrained to the signed-in user's own passkeys. */
+export const POST: APIRoute = async ({ session, url }) => {
+  const user = await currentUser(session);
+  if (!user || !session) return unauthorized();
+
+  const creds = await listCredentials(user.passkeyUserId);
+  if (creds.length === 0) {
+    return json({ error: 'no_passkeys', message: 'No passkeys are registered on this account.' }, 409);
+  }
+
+  const options = await generateAuthenticationOptions({
+    rpID: getRpId(url),
+    // Never empty here: an empty list would fall back to discoverable (any-account) sign-in.
+    allowCredentials: creds.map((c) => ({ id: c.id, transports: c.transports as any })),
+    userVerification: 'preferred',
+  });
+
+  session.set('passkeyReauthentication', {
+    challenge: options.challenge,
+    expires: Date.now() + 5 * 60 * 1000,
+  });
+  return json(options);
+};
