+import type { APIRoute } from 'astro';
+import { checkPassword, currentUser, json, readJson, unauthorized } from '../../../../lib/auth/server';
+
+/** Password fallback for reauthentication (e.g. accounts without passkeys). */
+export const POST: APIRoute = async ({ request, session }) => {
+  const user = await currentUser(session);
+  if (!user || !session) return unauthorized();
+
+  const body = await readJson<{ password?: string }>(request);
+  if (!body?.password) return json({ error: 'Password is required.' }, 400);
+
+  try {
+    const result = await checkPassword(user.username, body.password);
+    if (!result.ok) return json({ error: 'Incorrect password.' }, 401);
+  } catch {
+    return json({ error: 'Verification service unavailable.' }, 502);
+  }
+
+  session.set('reauthAt', Date.now());
+  return json({ ok: true });
+};
