+import type { APIRoute } from 'astro';
+import { verifyAuthenticationResponse, type AuthenticationResponseJSON } from '@simplewebauthn/server';
+import { getCredential, saveCredential } from '../../../../lib/auth/store';
+import {
+  currentUser,
+  getExpectedOrigins,
+  getRpId,
+  json,
+  readJson,
+  unauthorized,
+} from '../../../../lib/auth/server';
+
+export const POST: APIRoute = async ({ request, session, url }) => {
+  const user = await currentUser(session);
+  if (!user || !session) return unauthorized();
+
+  const pending = await session.get('passkeyReauthentication');
+  session.delete('passkeyReauthentication');
+  if (!pending || pending.expires < Date.now()) {
+    return json({ error: 'Verification expired. Please try again.' }, 400);
+  }
+
+  const response = await readJson<AuthenticationResponseJSON>(request);
+  if (!response?.id) return json({ error: 'Invalid verification response.' }, 400);
+
+  const stored = await getCredential(response.id);
+  if (!stored) return json({ error: 'This passkey isn’t registered.' }, 404);
+
+  // The passkey must belong to the signed-in account — reject any other user's credential.
+  if (stored.passkeyUserId !== user.passkeyUserId) {
+    return json({ error: 'That passkey belongs to a different account.' }, 403);
+  }
+
+  let verification;
+  try {
+    verification = await verifyAuthenticationResponse({
+      response,
+      expectedChallenge: pending.challenge,
+      expectedOrigin: getExpectedOrigins(url),
+      expectedRPID: getRpId(url),
+      credential: {
+        id: stored.id,
+        publicKey: new Uint8Array(Buffer.from(stored.credentialPublicKey, 'base64url')),
+        counter: stored.counter,
+        transports: stored.transports,
+      },
+      requireUserVerification: false,
+    });
+  } catch (err) {
+    console.warn('Passkey reauthentication failed:', err);
+    return json({ error: 'Passkey could not be verified.' }, 400);
+  }
+  if (!verification.verified) return json({ error: 'Passkey could not be verified.' }, 400);
+
+  const { newCounter, credentialBackedUp, credentialDeviceType } = verification.authenticationInfo;
+  await saveCredential({ ...stored, counter: newCounter, credentialBackedUp, credentialDeviceType, lastUsedAt: Date.now() });
+
+  session.set('reauthAt', Date.now());
+  return json({ ok: true });
+};
