+import type { APIRoute } from 'astro';
+import { ensureUser } from '../../../lib/auth/store';
+import { TIMES_API, json, publicUser, readJson, signIn } from '../../../lib/auth/server';
+
+/** Sign-up: creates the account in the Times API and signs the new user in. */
+export const POST: APIRoute = async ({ request, session, url }) => {
+  const body = await readJson<{ username?: string; password?: string }>(request);
+  const username = body?.username?.trim();
+  const password = body?.password;
+  if (!username || !password || !session) {
+    return json({ error: 'Username and password are required.' }, 400);
+  }
+
+  try {
+    const res = await fetch(`${TIMES_API}/register`, {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ username, password }),
+    });
+    const data = ((await res.json().catch(() => ({}))) ?? {}) as Record<string, unknown>;
+    if (!res.ok) return json(data, res.status);
+
+    const user = await ensureUser(username);
+    await signIn(session, user, 'password');
+    return json({ ...data, user: publicUser(user, url) });
+  } catch (err) {
+    console.error('Register proxy failed:', err);
+    return json({ error: 'Sign-up service unavailable.' }, 502);
+  }
+};
