+import type { APIRoute } from 'astro';
+import { updateUser } from '../../../lib/auth/store';
+import {
+  currentUser,
+  hasRecentAuth,
+  json,
+  publicUser,
+  readJson,
+  reauthRequired,
+  unauthorized,
+} from '../../../lib/auth/server';
+
+/** Update account profile details. Sensitive: requires a recent (re)authentication. */
+export const PUT: APIRoute = async ({ request, session, url }) => {
+  const user = await currentUser(session);
+  if (!user) return unauthorized();
+  if (!(await hasRecentAuth(session))) return reauthRequired();
+
+  const body = await readJson<{ displayName?: string }>(request);
+  const displayName = body?.displayName?.trim();
+  if (!displayName || displayName.length > 100) {
+    return json({ error: 'Display name must be between 1 and 100 characters.' }, 400);
+  }
+
+  const updated = await updateUser(user.username, { displayName });
+  return json(publicUser(updated!, url));
+};
