+import React, { useEffect, useState } from 'react';
+import {
+  CheckBadgeIcon,
+  CloudIcon,
+  DevicePhoneMobileIcon,
+  FingerPrintIcon,
+  KeyIcon,
+  PencilSquareIcon,
+  TrashIcon,
+} from '@heroicons/react/24/outline';
+import ReauthDialog from './ReauthDialog';
+import {
+  ApiError,
+  api,
+  BASE,
+  createPasskey,
+  PasskeyCancelledError,
+  passkeysSupported,
+  signalAcceptedCredentials,
+  signalCurrentUserDetails,
+  type PublicPasskey,
+} from '../lib/passkeys-client';
+
+interface Props {
+  username: string;
+  userId: string;
+  rpID: string;
+  authMethod: 'password' | 'passkey' | null;
+  initialPasskeys: PublicPasskey[];
+}
+
+interface PendingAction {
+  key: string;
+  reason: string;
+  run: () => Promise<void>;
+}
+
+const dateFormat = new Intl.DateTimeFormat('en-US', { dateStyle: 'medium', timeStyle: 'short' });
+const formatDate = (ms: number) => dateFormat.format(new Date(ms));
+
+export default function AccountSettings({ username, userId, rpID, authMethod, initialPasskeys }: Props) {
+  const [passkeys, setPasskeys] = useState<PublicPasskey[]>(initialPasskeys);
+  const [supported, setSupported] = useState(true);
+  const [busy, setBusy] = useState<string | null>(null);
+  const [error, setError] = useState<string | null>(null);
+  const [notice, setNotice] = useState<string | null>(null);
+  const [editingId, setEditingId] = useState<string | null>(null);
+  const [editName, setEditName] = useState('');
+  const [pending, setPending] = useState<PendingAction | null>(null);
+
+  useEffect(() => {
+    setSupported(passkeysSupported());
+    // Keep the user's password manager in sync with what the server knows about.
+    signalAcceptedCredentials(rpID, userId, initialPasskeys);
+    signalCurrentUserDetails(rpID, userId, username);
+  }, []);
+
+  const flash = (message: string) => {
+    setError(null);
+    setNotice(message);
+  };
+
+  const handleError = (err: unknown) => {
+    if (err instanceof PasskeyCancelledError) return;
+    setNotice(null);
+    setError((err as Error).message);
+  };
+
+  /** Runs a sensitive action, asking the user to reauthenticate first if the server requires it. */
+  const runSensitive = async (key: string, reason: string, action: () => Promise<void>) => {
+    setError(null);
+    setNotice(null);
+    setBusy(key);
+    try {
+      await action();
+    } catch (err) {
+      if (err instanceof ApiError && err.code === 'REAUTH_REQUIRED') {
+        setPending({ key, reason, run: action });
+      } else {
+        handleError(err);
+      }
+    } finally {
+      setBusy(null);
+    }
+  };
+
+  const addPasskey = () =>
+    runSensitive('add', 'add a passkey', async () => {
+      const result = await createPasskey();
+      setPasskeys(result.passkeys);
+      flash(`Passkey “${result.passkey.name}” added. You can now use it to sign in.`);
+    });
+
+  const removePasskey = (passkey: PublicPasskey) => {
+    const lastOne = passkeys.length === 1;
+    const message = lastOne
+      ? `Remove “${passkey.name}”? This is your only passkey, so you’ll need your password to sign in.`
+      : `Remove “${passkey.name}”? You won’t be able to sign in with it anymore.`;
+    if (!window.confirm(message)) return;
+
+    runSensitive(`delete:${passkey.id}`, 'remove this passkey', async () => {
+      const result = await api<{ passkeys: PublicPasskey[]; rpID: string; userId: string }>(
+        `api/passkeys/${encodeURIComponent(passkey.id)}`,
+        { method: 'DELETE' },
+      );
+      setPasskeys(result.passkeys);
+      // Ask the passkey provider to hide the removed credential.
+      signalAcceptedCredentials(result.rpID, result.userId, result.passkeys);
+      flash(
+        `Passkey “${passkey.name}” removed from your account. You can also delete it from your password manager.`,
+      );
+    });
+  };
+
+  const startEditing = (passkey: PublicPasskey) => {
+    setEditingId(passkey.id);
+    setEditName(passkey.name);
+  };
+
+  const saveName = async (e: React.FormEvent, passkey: PublicPasskey) => {
+    e.preventDefault();
+    setBusy(`rename:${passkey.id}`);
+    try {
+      const result = await api<{ passkey: PublicPasskey }>(`api/passkeys/${encodeURIComponent(passkey.id)}`, {
+        method: 'PATCH',
+        body: { name: editName },
+      });
+      setPasskeys((list) => list.map((p) => (p.id === passkey.id ? result.passkey : p)));
+      setEditingId(null);
+      flash('Passkey renamed.');
+    } catch (err) {
+      handleError(err);
+    } finally {
+      setBusy(null);
+    }
+  };
+
+  const signOut = async () => {
+    setBusy('signout');
+    try {
+      await api('api/auth/logout', { body: {} });
+    } finally {
+      window.location.assign(BASE);
+    }
+  };
+
+  return (
+    <div className="max-w-2xl mx-auto mt-10 space-y-8">
+      <div className="flex items-start justify-between gap-4">
+        <div>
+          <h1 className="text-3xl font-bold text-gray-900">Account settings</h1>
+          <p className="mt-1 text-sm text-gray-600">
+            Signed in as <strong>{username}</strong>
+            {authMethod && <> · via {authMethod === 'passkey' ? 'passkey' : 'password'}</>}
+          </p>
+        </div>
+        <button
+          type="button"
+          onClick={signOut}
+          disabled={busy === 'signout'}
+          className="shrink-0 py-2 px-3 text-sm font-medium border border-gray-300 rounded-md text-gray-800 hover:bg-gray-50 disabled:opacity-50"
+        >
+          Sign out
+        </button>
+      </div>
+
+      <section aria-labelledby="passkeys-heading" className="bg-white border border-gray-200 rounded-lg shadow-sm">
+        <div className="p-6 border-b border-gray-200 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
+          <div>
+            <h2 id="passkeys-heading" className="text-xl font-bold text-gray-900 flex items-center gap-2">
+              <KeyIcon className="h-6 w-6" aria-hidden="true" />
+              Passkeys
+            </h2>
+            <p className="mt-1 text-sm text-gray-600">
+              Passkeys let you sign in securely with your fingerprint, face, screen lock or security key — no password
+              needed.
+            </p>
+          </div>
+          {supported && (
+            <button
+              type="button"
+              onClick={addPasskey}
+              disabled={busy !== null}
+              className="shrink-0 inline-flex items-center justify-center gap-2 py-2 px-4 rounded-md text-sm font-medium text-white bg-gray-900 hover:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-900 disabled:opacity-75"
+            >
+              <FingerPrintIcon className="h-5 w-5" aria-hidden="true" />
+              {busy === 'add' ? 'Creating…' : 'Create a passkey'}
+            </button>
+          )}
+        </div>
+
+        <div aria-live="polite">
+          {error && (
+            <div className="mx-6 mt-4 p-3 text-sm text-red-700 bg-red-100 rounded-lg" role="alert">
+              {error}
+            </div>
+          )}
+          {notice && (
+            <div className="mx-6 mt-4 p-3 text-sm text-green-700 bg-green-100 rounded-lg" role="status">
+              {notice}
+            </div>
+          )}
+        </div>
+
+        {!supported && (
+          <p className="mx-6 mt-4 p-3 text-sm text-gray-700 bg-gray-100 rounded-lg">
+            This browser doesn’t support passkeys. You can still manage existing passkeys here.
+          </p>
+        )}
+
+        {passkeys.length === 0 ? (
+          <div className="p-6 text-center text-sm text-gray-600">
+            <p>You don’t have any passkeys yet.</p>
+          </div>
+        ) : (
+          <ul className="divide-y divide-gray-200">
+            {passkeys.map((passkey) => {
+              const synced = passkey.deviceType === 'multiDevice';
+              const isEditing = editingId === passkey.id;
+              return (
+                <li key={passkey.id} className="p-6 flex flex-col sm:flex-row sm:items-center gap-4">
+                  <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-amber-100">
+                    {synced ? (
+                      <CloudIcon className="h-6 w-6 text-amber-800" aria-hidden="true" />
+                    ) : (
+                      <DevicePhoneMobileIcon className="h-6 w-6 text-amber-800" aria-hidden="true" />
+                    )}
+                  </div>
+
+                  <div className="flex-1 min-w-0">
+                    {isEditing ? (
+                      <form onSubmit={(e) => saveName(e, passkey)} className="flex gap-2">
+                        <label htmlFor={`name-${passkey.id}`} className="sr-only">
+                          Passkey name
+                        </label>
+                        <input
+                          id={`name-${passkey.id}`}
+                          value={editName}
+                          onChange={(e) => setEditName(e.target.value)}
+                          maxLength={64}
+                          required
+                          autoFocus
+                          onKeyDown={(e) => e.key === 'Escape' && setEditingId(null)}
+                          className="flex-1 min-w-0 px-2 py-1 border border-gray-300 rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
+                        />
+                        <button
+                          type="submit"
+                          disabled={busy === `rename:${passkey.id}`}
+                          className="px-3 py-1 text-sm font-medium text-white bg-gray-900 rounded-md hover:bg-gray-800 disabled:opacity-75"
+                        >
+                          Save
+                        </button>
+                        <button
+                          type="button"
+                          onClick={() => setEditingId(null)}
+                          className="px-3 py-1 text-sm text-gray-700 hover:underline"
+                        >
+                          Cancel
+                        </button>
+                      </form>
+                    ) : (
+                      <p className="font-semibold text-gray-900 truncate">{passkey.name}</p>
+                    )}
+                    <p className="mt-1 text-xs text-gray-600">
+                      Created {formatDate(passkey.createdAt)} ·{' '}
+                      {passkey.lastUsedAt ? `Last used ${formatDate(passkey.lastUsedAt)}` : 'Never used to sign in'}
+                    </p>
+                    <p className="mt-1 flex flex-wrap gap-2 text-xs">
+                      {passkey.provider && passkey.provider !== passkey.name && (
+                        <span className="rounded bg-gray-100 px-2 py-0.5 text-gray-700">{passkey.provider}</span>
+                      )}
+                      {synced ? (
+                        <span className="inline-flex items-center gap-1 rounded bg-green-50 px-2 py-0.5 text-green-800">
+                          <CheckBadgeIcon className="h-3.5 w-3.5" aria-hidden="true" />
+                          {passkey.backedUp ? 'Synced across your devices' : 'Syncable'}
+                        </span>
+                      ) : (
+                        <span className="rounded bg-gray-100 px-2 py-0.5 text-gray-700">This device only</span>
+                      )}
+                    </p>
+                  </div>
+
+                  {!isEditing && (
+                    <div className="flex gap-2 shrink-0">
+                      <button
+                        type="button"
+                        onClick={() => startEditing(passkey)}
+                        disabled={busy !== null}
+                        className="inline-flex items-center gap-1 px-3 py-1.5 text-sm border border-gray-300 rounded-md text-gray-800 hover:bg-gray-50 disabled:opacity-50"
+                        aria-label={`Rename ${passkey.name}`}
+                      >
+                        <PencilSquareIcon className="h-4 w-4" aria-hidden="true" />
+                        Rename
+                      </button>
+                      <button
+                        type="button"
+                        onClick={() => removePasskey(passkey)}
+                        disabled={busy !== null}
+                        className="inline-flex items-center gap-1 px-3 py-1.5 text-sm border border-red-300 rounded-md text-red-700 hover:bg-red-50 disabled:opacity-50"
+                        aria-label={`Remove ${passkey.name}`}
+                      >
+                        <TrashIcon className="h-4 w-4" aria-hidden="true" />
+                        {busy === `delete:${passkey.id}` ? 'Removing…' : 'Remove'}
+                      </button>
+                    </div>
+                  )}
+                </li>
+              );
+            })}
+          </ul>
+        )}
+      </section>
+
+      <ReauthDialog
+        open={pending !== null}
+        username={username}
+        hasPasskeys={passkeys.length > 0}
+        reason={pending?.reason ?? 'continue'}
+        onCancel={() => setPending(null)}
+        onSuccess={() => {
+          const action = pending;
+          setPending(null);
+          if (action) runSensitive(action.key, action.reason, action.run);
+        }}
+      />
+    </div>
+  );
+}
