+}
+
+/** Offers to create a passkey right after sign-up / password sign-in. */
+export default function PasskeyPrompt({ username, heading, onDone }: Props) {
+  const [busy, setBusy] = useState(false);
+  const [error, setError] = useState<string | null>(null);
+  const supported = passkeysSupported();
+
+  const handleCreate = async () => {
+    setBusy(true);
+    setError(null);
+    try {
+      await createPasskey();
+      onDone(true);
+    } catch (err) {
+      if (!(err instanceof PasskeyCancelledError)) setError((err as Error).message);
+      setBusy(false);
+    }
+  };
+
+  return (
+    <div className="text-center" aria-live="polite">
+      <div className="mx-auto mb-4 flex h-14 w-14 items-center justify-center rounded-full bg-amber-100">
+        <FingerPrintIcon className="h-8 w-8 text-amber-800" aria-hidden="true" />
+      </div>
+      <h2 className="text-2xl font-bold mb-2 text-gray-800">{heading}</h2>
+      <p className="text-sm text-gray-600 mb-6">
+        Signed in as <strong>{username}</strong>. Next time, skip the password: sign in with a passkey using your
+        fingerprint, face or screen lock.
+      </p>
+
+      {error && (
+        <div className="mb-4 p-3 text-sm text-red-700 bg-red-100 rounded-lg text-left" role="alert">
+          {error}
+        </div>
+      )}
+
+      {supported ? (
+        <button
+          type="button"
+          onClick={handleCreate}
+          disabled={busy}
+          className="w-full inline-flex items-center justify-center gap-2 py-2 px-4 rounded-md shadow-sm text-sm font-medium text-white bg-gray-900 hover:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-900 disabled:opacity-75 disabled:cursor-not-allowed"
+        >
+          <FingerPrintIcon className="h-5 w-5" aria-hidden="true" />
+          {busy ? 'Creating passkey…' : 'Create a passkey'}
+        </button>
+      ) : (
+        <p className="mb-4 p-3 text-sm text-gray-700 bg-gray-100 rounded-lg">
+          This browser doesn’t support passkeys. You can add one later from your account settings on another device.
+        </p>
+      )}
+
+      <button
+        type="button"
+        onClick={() => onDone(false)}
+        disabled={busy}
+        className="mt-3 w-full py-2 px-4 text-sm font-medium text-gray-700 hover:text-gray-900 hover:underline disabled:opacity-50"
+      >
+        Not now
+      </button>
+    </div>
+  );
+}
