@@ -0,0 +1,160 @@
+import React, { useEffect, useRef, useState } from 'react';
+import { FingerPrintIcon, ShieldCheckIcon } from '@heroicons/react/24/outline';
+import { api, PasskeyCancelledError, passkeysSupported, reauthenticateWithPasskey } from '../lib/passkeys-client';
+
+interface Props {
+  open: boolean;
+  username: string;
+  hasPasskeys: boolean;
+  /** Short description of what the user is about to do, e.g. "remove this passkey". */
+  reason: string;
+  onSuccess: () => void;
+  onCancel: () => void;
+}
+
+/**
+ * Asks the signed-in user to prove it's them again before a sensitive change.
+ * Passkey verification is offered first when available; password is the fallback.
+ */
+export default function ReauthDialog({ open, username, hasPasskeys, reason, onSuccess, onCancel }: Props) {
+  const dialogRef = useRef<HTMLDialogElement>(null);
+  const [password, setPassword] = useState('');
+  const [error, setError] = useState<string | null>(null);
+  const [busy, setBusy] = useState<'passkey' | 'password' | null>(null);
+  const passkeyOption = hasPasskeys && passkeysSupported();
+  const [showPassword, setShowPassword] = useState(!passkeyOption);
+
+  useEffect(() => {
+    const dialog = dialogRef.current;
+    if (!dialog) return;
+    if (open && !dialog.open) {
+      setError(null);
+      setPassword('');
+      setBusy(null);
+      setShowPassword(!passkeyOption);
+      dialog.showModal();
+    } else if (!open && dialog.open) {
+      dialog.close();
+    }
+  }, [open]);
+
+  const handlePasskey = async () => {
+    setError(null);
+    setBusy('passkey');
+    try {
+      await reauthenticateWithPasskey();
+      onSuccess();
+    } catch (err) {
+      if (!(err instanceof PasskeyCancelledError)) setError((err as Error).message);
+    } finally {
+      setBusy(null);
+    }
+  };
+
+  const handlePassword = async (e: React.FormEvent) => {
+    e.preventDefault();
+    setError(null);
+    setBusy('password');
+    try {
+      await api('api/auth/reauth/password', { body: { password } });
+      setPassword('');
+      onSuccess();
+    } catch (err) {
+      setError((err as Error).message);
+    } finally {
+      setBusy(null);
+    }
+  };
+
+  return (
+    <dialog
+      ref={dialogRef}
+      onCancel={(e) => {
+        e.preventDefault();
+        if (!busy) onCancel();
+      }}
+      aria-labelledby="reauth-title"
+      className="m-auto w-full max-w-sm rounded-lg p-0 shadow-xl backdrop:bg-black/50"
+    >
+      <div className="p-6">
+        <div className="mx-auto mb-3 flex h-12 w-12 items-center justify-center rounded-full bg-gray-100">
+          <ShieldCheckIcon className="h-7 w-7 text-gray-800" aria-hidden="true" />
+        </div>
+        <h2 id="reauth-title" className="text-lg font-bold text-center text-gray-900">
+          Confirm it’s you
+        </h2>
+        <p className="mt-1 mb-5 text-sm text-center text-gray-600">
+          For your security, verify your identity to {reason}.
+        </p>
+
+        {error && (
+          <div className="mb-4 p-3 text-sm text-red-700 bg-red-100 rounded-lg" role="alert">
+            {error}
+          </div>
+        )}
+
+        {passkeyOption && (
+          <button
+            type="button"
+            onClick={handlePasskey}
+            disabled={busy !== null}
+            className="w-full inline-flex items-center justify-center gap-2 py-2 px-4 rounded-md text-sm font-medium text-white bg-gray-900 hover:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-900 disabled:opacity-75"
+          >
+            <FingerPrintIcon className="h-5 w-5" aria-hidden="true" />
+            {busy === 'passkey' ? 'Waiting for passkey…' : 'Use your passkey'}
+          </button>
+        )}
+
+        {passkeyOption && !showPassword && (
+          <button
+            type="button"
+            onClick={() => setShowPassword(true)}
+            className="mt-3 w-full text-sm text-gray-700 hover:underline"
+          >
+            Use your password instead
+          </button>
+        )}
+
+        {showPassword && (
+          <form onSubmit={handlePassword} className={passkeyOption ? 'mt-4 space-y-3' : 'space-y-3'}>
+            {/* Hidden username helps password managers fill the right credential. */}
+            <input type="text" name="username" autoComplete="username" value={username} readOnly hidden />
+            <label htmlFor="reauth-password" className="block text-sm font-medium text-gray-700">
+              Password
+            </label>
+            <input
+              id="reauth-password"
+              type="password"
+              autoComplete="current-password"
+              value={password}
+              onChange={(e) => setPassword(e.target.value)}
+              required
+              autoFocus={!passkeyOption}
+              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
+            />
+            <button
+              type="submit"
+              disabled={busy !== null}
+              className={`w-full py-2 px-4 rounded-md text-sm font-medium focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-900 disabled:opacity-75 ${
+                passkeyOption
+                  ? 'border border-gray-900 text-gray-900 bg-white hover:bg-gray-50'
+                  : 'text-white bg-gray-900 hover:bg-gray-800'
+              }`}
+            >
+              {busy === 'password' ? 'Verifying…' : 'Verify password'}
+            </button>
+          </form>
+        )}
+
+        <button
+          type="button"
+          onClick={onCancel}
+          disabled={busy !== null}
+          className="mt-4 w-full py-2 text-sm text-gray-600 hover:text-gray-900 disabled:opacity-50"
+        >
+          Cancel
+        </button>
+      </div>
+    </dialog>
+  );
+}
