diff --git a/src/lib/auth/session.ts b/src/lib/auth/session.ts
new file mode 100644
index 0000000..5d1c147
--- /dev/null
+++ b/src/lib/auth/session.ts
@@ -0,0 +1,108 @@
+import type { APIContext } from 'astro';
+import { CHALLENGE_TTL_MS } from './webauthn';
+import type { UserRecord } from './store';
+
+/** Sensitive account actions require a (re)authentication within this window. */
+export const REAUTH_WINDOW_MS = 5 * 60 * 1000;
+
+export const UPSTREAM_API = 'https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api';
+
+type Ctx = Pick<APIContext, 'session'>;
+
+export function json(body: unknown, status = 200): Response {
+  return new Response(JSON.stringify(body), {
+    status,
+    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' },
+  });
+}
+
+export function errorResponse(status: number, error: string, code?: string): Response {
+  return json({ error, ...(code ? { code } : {}) }, status);
+}
+
+export async function getSessionUser(ctx: Ctx) {
+  return (await ctx.session?.get('user')) ?? null;
+}
+
+export async function isRecentlyAuthenticated(ctx: Ctx): Promise<boolean> {
+  const authAt = await ctx.session?.get('authAt');
+  return typeof authAt === 'number' && Date.now() - authAt < REAUTH_WINDOW_MS;
+}
+
+/** Starts a fresh authenticated session (new session ID to prevent fixation). */
+export async function startSession(ctx: Ctx, user: UserRecord, method: 'password' | 'passkey') {
+  if (!ctx.session) throw new Error('Sessions are not configured.');
+  await ctx.session.regenerate();
+  ctx.session.set('user', { id: user.id, username: user.username });
+  markAuthenticated(ctx, method);
+}
+
+export function markAuthenticated(ctx: Ctx, method: 'password' | 'passkey') {
+  ctx.session?.set('authAt', Date.now());
+  ctx.session?.set('authMethod', method);
+}
+
+export function endSession(ctx: Ctx) {
+  ctx.session?.delete('user');
+  ctx.session?.delete('authAt');
+  ctx.session?.delete('authMethod');
+  ctx.session?.delete('webauthnChallenge');
+}
+
+export function saveChallenge(
+  ctx: Ctx,
+  challenge: string,
+  purpose: App.SessionData['webauthnChallenge']['purpose'],
+  userId?: string,
+) {
+  ctx.session?.set('webauthnChallenge', {
+    challenge,
+    purpose,
+    userId,
+    expiresAt: Date.now() + CHALLENGE_TTL_MS,
+  });
+}
+
+/** Returns and clears the pending challenge if it matches the expected purpose. */
+export async function consumeChallenge(
+  ctx: Ctx,
+  purpose: App.SessionData['webauthnChallenge']['purpose'],
+) {
+  const pending = await ctx.session?.get('webauthnChallenge');
+  ctx.session?.delete('webauthnChallenge');
+  if (!pending || pending.purpose !== purpose || pending.expiresAt < Date.now()) return null;
+  return pending;
+}
+
+/**
+ * Checks a username/password pair against the upstream Times account API.
+ * Returns `null` on success, or the upstream error message.
+ */
+export async function verifyPasswordUpstream(
+  endpoint: 'login' | 'register',
+  username: string,
+  password: string,
+): Promise<{ ok: true } | { ok: false; status: number; error: string }> {
+  try {
+    const response = await fetch(`${UPSTREAM_API}/${endpoint}`, {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ username, password }),
+    });
+    const data = await response.json().catch(() => ({}));
+    if (!response.ok) {
+      return { ok: false, status: response.status, error: data.error || 'Unknown error' };
+    }
+    return { ok: true };
+  } catch {
+    return { ok: false, status: 502, error: 'The account service is unavailable. Please try again later.' };
+  }
+}
+
+export async function readJson<T = any>(request: Request): Promise<T | null> {
+  try {
+    return (await request.json()) as T;
+  } catch {
+    return null;
+  }
+}
diff --git a/src/lib/auth/store.ts b/src/lib/auth/store.ts
new file mode 100644
index 0000000..0ab373e
--- /dev/null
+++ b/src/lib/auth/store.ts
@@ -0,0 +1,146 @@
+/**
+ * Tiny JSON-file backed store for local user records and their passkeys.
+ *
+ * Passwords are owned by the upstream Times account API; this store only keeps
+ * what the WebAuthn relying party needs: a stable, opaque user handle per
+ * username and the public-key credentials registered to it.
+ *
+ * The file location can be overridden with the PASSKEY_STORE_PATH env var.
+ */
+import { promises as fs } from 'node:fs';
+import path from 'node:path';
+import { randomBytes } from 'node:crypto';
+import type { AuthenticatorTransportFuture, CredentialDeviceType } from '@simplewebauthn/server';
+
+export interface UserRecord {
+  /** Opaque WebAuthn user handle (base64url, 32 random bytes). Never the username. */
+  id: string;
+  username: string;
+  createdAt: number;
+}
+
+export interface PasskeyRecord {
+  /** Credential ID (base64url). */
+  id: string;
+  userId: string;
+  /** COSE public key (base64url). */
+  publicKey: string;
+  counter: number;
+  transports: AuthenticatorTransportFuture[];
+  /** User-editable label. */
+  name: string;
+  aaguid: string;
+  deviceType: CredentialDeviceType;
+  backedUp: boolean;
+  createdAt: number;
+  lastUsedAt: number | null;
+}
+
+interface StoreShape {
+  users: UserRecord[];
+  passkeys: PasskeyRecord[];
+}
+
+const STORE_PATH = path.resolve(
+  process.env.PASSKEY_STORE_PATH ?? path.join(process.cwd(), '.data', 'passkeys.json'),
+);
+
+let cache: StoreShape | null = null;
+let writeChain: Promise<void> = Promise.resolve();
+
+async function load(): Promise<StoreShape> {
+  if (cache) return cache;
+  try {
+    const raw = await fs.readFile(STORE_PATH, 'utf8');
+    const parsed = JSON.parse(raw) as Partial<StoreShape>;
+    cache = { users: parsed.users ?? [], passkeys: parsed.passkeys ?? [] };
+  } catch (err: any) {
+    if (err?.code !== 'ENOENT') console.error('[passkeys] Failed to read store, starting empty:', err);
+    cache = { users: [], passkeys: [] };
+  }
+  return cache;
+}
+
+/** Serialise writes and replace the file atomically. */
+function persist(): Promise<void> {
+  writeChain = writeChain
+    .catch(() => {})
+    .then(async () => {
+      if (!cache) return;
+      await fs.mkdir(path.dirname(STORE_PATH), { recursive: true });
+      const tmp = `${STORE_PATH}.${process.pid}.tmp`;
+      await fs.writeFile(tmp, JSON.stringify(cache, null, 2), 'utf8');
+      await fs.rename(tmp, STORE_PATH);
+    });
+  return writeChain;
+}
+
+const normalise = (username: string) => username.trim().toLowerCase();
+
+export async function findUserByUsername(username: string): Promise<UserRecord | undefined> {
+  const db = await load();
+  const key = normalise(username);
+  return db.users.find((u) => normalise(u.username) === key);
+}
+
+export async function findUserById(id: string): Promise<UserRecord | undefined> {
+  const db = await load();
+  return db.users.find((u) => u.id === id);
+}
+
+/** Returns the local record for a username, creating one if needed. */
+export async function ensureUser(username: string): Promise<UserRecord> {
+  const existing = await findUserByUsername(username);
+  if (existing) return existing;
+  const db = await load();
+  const user: UserRecord = {
+    id: randomBytes(32).toString('base64url'),
+    username: username.trim(),
+    createdAt: Date.now(),
+  };
+  db.users.push(user);
+  await persist();
+  return user;
+}
+
+export async function listPasskeys(userId: string): Promise<PasskeyRecord[]> {
+  const db = await load();
+  return db.passkeys
+    .filter((p) => p.userId === userId)
+    .sort((a, b) => b.createdAt - a.createdAt);
+}
+
+export async function findPasskey(id: string): Promise<PasskeyRecord | undefined> {
+  const db = await load();
+  return db.passkeys.find((p) => p.id === id);
+}
+
+export async function addPasskey(passkey: PasskeyRecord): Promise<void> {
+  const db = await load();
+  if (db.passkeys.some((p) => p.id === passkey.id)) {
+    throw new Error('This passkey is already registered.');
+  }
+  db.passkeys.push(passkey);
+  await persist();
+}
+
+export async function updatePasskey(
+  id: string,
+  patch: Partial<Pick<PasskeyRecord, 'name' | 'counter' | 'backedUp' | 'deviceType' | 'lastUsedAt'>>,
+): Promise<PasskeyRecord | undefined> {
+  const db = await load();
+  const passkey = db.passkeys.find((p) => p.id === id);
+  if (!passkey) return undefined;
+  Object.assign(passkey, patch);
+  await persist();
+  return passkey;
+}
+
+export async function deletePasskey(id: string, userId: string): Promise<boolean> {
+  const db = await load();
+  const before = db.passkeys.length;
+  db.passkeys = db.passkeys.filter((p) => !(p.id === id && p.userId === userId));
+  if (db.passkeys.length === before) return false;
+  await persist();
+  return true;
+}
diff --git a/src/lib/auth/webauthn.ts b/src/lib/auth/webauthn.ts
new file mode 100644
index 0000000..cbbd20d
--- /dev/null
+++ b/src/lib/auth/webauthn.ts
@@ -0,0 +1,96 @@
+import type { APIContext } from 'astro';
+import type { PasskeyRecord } from './store';
+
+export const RP_NAME = 'The DevTools Times';
+
+/** Challenges are single-use and expire after five minutes. */
+export const CHALLENGE_TTL_MS = 5 * 60 * 1000;
+
+/**
+ * The relying party ID and allowed origins are derived from the request so the
+ * same build works on localhost and every deployed hostname. They can be pinned
+ * with PASSKEY_RP_ID / PASSKEY_ORIGINS (comma-separated) if needed.
+ */
+export function getRelyingParty(context: Pick<APIContext, 'url'>) {
+  const rpID = process.env.PASSKEY_RP_ID || context.url.hostname;
+  const origins = process.env.PASSKEY_ORIGINS
+    ? process.env.PASSKEY_ORIGINS.split(',').map((o) => o.trim()).filter(Boolean)
+    : [context.url.origin];
+  return { rpID, rpName: RP_NAME, origins };
+}
+
+/**
+ * Best-effort friendly names for common passkey providers, keyed by AAGUID.
+ * Source: https://github.com/passkeydeveloper/passkey-authenticator-aaguids
+ */
+const AAGUID_NAMES: Record<string, string> = {
+  'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4': 'Google Password Manager',
+  'adce0002-35bc-c60a-648b-0b25f1f05503': 'Chrome on Mac',
+  'fbfc3007-154e-4ecc-8c0b-6e020557d7bd': 'iCloud Keychain',
+  'dd4ec289-e01d-41c9-bb89-70fa845d4bf2': 'iCloud Keychain (Managed)',
+  '08987058-cadc-4b81-b6e1-30de50dcbe96': 'Windows Hello',
+  '9ddd1817-af5a-4672-a2b9-3e3dd95000a9': 'Windows Hello',
+  '6028b017-b1d4-4c02-b4b3-afcdafc96bb2': 'Windows Hello',
+  '771b48fd-d3d4-4f74-9232-fc157ab0507a': 'Edge on Mac',
+  'bada5566-a7aa-401f-bd96-45619a55120d': '1Password',
+  'd548826e-79b4-db40-a3d8-11116f7e8349': 'Bitwarden',
+  '531126d6-e717-415c-9320-3d9aa6981239': 'Dashlane',
+  'b84e4048-15dc-4dd0-8640-f4f60813c8af': 'NordPass',
+  '0ea242b4-43c4-4a1b-8b17-dd6d0b6baec6': 'Keeper',
+  'f3809540-7f14-49c1-a8b3-8f813b225541': 'Enpass',
+  '53414d53-554e-4700-0000-000000000000': 'Samsung Pass',
+  'cb69481e-8ff7-4039-93ec-0a2729a154a8': 'YubiKey 5',
+  'ee882879-721c-4913-9775-3dfcce97072a': 'YubiKey 5',
+  'fa2b99dc-9e39-4257-8f92-4a30d23c4118': 'YubiKey 5 NFC',
+};
+
+export function providerNameFor(aaguid: string | undefined): string | null {
+  if (!aaguid) return null;
+  return AAGUID_NAMES[aaguid.toLowerCase()] ?? null;
+}
+
+/** Shape sent to the browser. Never includes the public key or counter. */
+export interface PublicPasskey {
+  id: string;
+  name: string;
+  provider: string | null;
+  deviceType: PasskeyRecord['deviceType'];
+  backedUp: boolean;
+  transports: PasskeyRecord['transports'];
+  createdAt: number;
+  lastUsedAt: number | null;
+}
+
+export function toPublicPasskey(p: PasskeyRecord): PublicPasskey {
+  return {
+    id: p.id,
+    name: p.name,
+    provider: providerNameFor(p.aaguid),
+    deviceType: p.deviceType,
+    backedUp: p.backedUp,
+    transports: p.transports,
+    createdAt: p.createdAt,
+    lastUsedAt: p.lastUsedAt,
+  };
+}
+
+/** Picks a sensible default label for a freshly created passkey. */
+export function defaultPasskeyName(aaguid: string, userAgent: string | null): string {
+  const provider = providerNameFor(aaguid);
+  if (provider) return provider;
+  const ua = userAgent ?? '';
+  const os = /Android/i.test(ua)
+    ? 'Android'
+    : /iPhone|iPad/i.test(ua)
+      ? 'iOS'
+      : /Mac OS X/i.test(ua)
+        ? 'macOS'
+        : /Windows/i.test(ua)
+          ? 'Windows'
+          : /CrOS/i.test(ua)
+            ? 'ChromeOS'
+            : /Linux/i.test(ua)
+              ? 'Linux'
+              : null;
+  return os ? `Passkey on ${os}` : 'Passkey';
+}
diff --git a/src/lib/passkeys-client.ts b/src/lib/passkeys-client.ts
new file mode 100644
index 0000000..e587e6a
--- /dev/null
+++ b/src/lib/passkeys-client.ts
@@ -0,0 +1,192 @@
+/**
+ * Browser-side helpers for the passkey flows. Wraps @simplewebauthn/browser and
+ * the app's /api/passkeys endpoints.
+ */
+import {
+  browserSupportsWebAuthn,
+  browserSupportsWebAuthnAutofill,
+  startAuthentication,
+  startRegistration,
+  WebAuthnAbortService,
+  WebAuthnError,
+} from '@simplewebauthn/browser';
+
+export const BASE = import.meta.env.BASE_URL;
+
+export interface PublicPasskey {
+  id: string;
+  name: string;
+  provider: string | null;
+  deviceType: 'singleDevice' | 'multiDevice';
+  backedUp: boolean;
+  transports: string[];
+  createdAt: number;
+  lastUsedAt: number | null;
+}
+
+export class ApiError extends Error {
+  constructor(
+    message: string,
+    public status: number,
+    public code?: string,
+    public data?: any,
+  ) {
+    super(message);
+  }
+}
+
+/** Thrown when the user dismisses the browser's passkey sheet; callers usually ignore it. */
+export class PasskeyCancelledError extends Error {}
+
+export async function api<T = any>(path: string, init: { method?: string; body?: unknown } = {}): Promise<T> {
+  const response = await fetch(`${BASE}${path}`, {
+    method: init.method ?? (init.body !== undefined ? 'POST' : 'GET'),
+    headers: init.body !== undefined ? { 'Content-Type': 'application/json' } : undefined,
+    body: init.body !== undefined ? JSON.stringify(init.body) : undefined,
+    credentials: 'same-origin',
+  });
+  const data = await response.json().catch(() => ({}));
+  if (!response.ok) {
+    throw new ApiError(data.error || `Request failed (${response.status})`, response.status, data.code, data);
+  }
+  return data as T;
+}
+
+export const passkeysSupported = () => typeof window !== 'undefined' && browserSupportsWebAuthn();
+
+export async function autofillSupported(): Promise<boolean> {
+  try {
+    return passkeysSupported() && (await browserSupportsWebAuthnAutofill());
+  } catch {
+    return false;
+  }
+}
+
+/** Is the browser able to do conditional ("automatic") passkey creation? */
+async function conditionalCreateSupported(): Promise<boolean> {
+  const PKC = (window as any).PublicKeyCredential;
+  if (!PKC?.getClientCapabilities) return false;
+  try {
+    const caps = await PKC.getClientCapabilities();
+    return caps?.conditionalCreate === true;
+  } catch {
+    return false;
+  }
+}
+
+function translateWebAuthnError(err: unknown, mode: 'create' | 'get'): Error {
+  if (err instanceof WebAuthnError) {
+    switch (err.code) {
+      case 'ERROR_CEREMONY_ABORTED':
+        return new PasskeyCancelledError('Cancelled');
+      case 'ERROR_AUTHENTICATOR_PREVIOUSLY_REGISTERED':
+        return new Error('You already have a passkey for this account in this password manager or device.');
+      case 'ERROR_INVALID_DOMAIN':
+      case 'ERROR_INVALID_RP_ID':
+        return new Error('Passkeys aren’t available on this domain.');
+    }
+  }
+  const name = (err as Error)?.name;
+  if (name === 'NotAllowedError' || name === 'AbortError') {
+    return new PasskeyCancelledError(
+      mode === 'create' ? 'Passkey creation was cancelled.' : 'Passkey sign-in was cancelled.',
+    );
+  }
+  if (err instanceof ApiError) return err;
+  return new Error((err as Error)?.message || 'Something went wrong with the passkey. Please try again.');
+}
+
+/**
+ * Creates a passkey for the signed-in user.
+ * With `automatic: true`, uses conditional create so a compatible password
+ * manager can silently upgrade the account right after a password sign-in.
+ */
+export async function createPasskey({ automatic = false } = {}): Promise<{
+  passkey: PublicPasskey;
+  passkeys: PublicPasskey[];
+}> {
+  if (automatic && !(await conditionalCreateSupported())) {
+    throw new PasskeyCancelledError('Automatic passkey creation not supported');
+  }
+  const { options } = await api('api/passkeys/registration-options', { body: {} });
+  let response;
+  try {
+    response = await startRegistration({ optionsJSON: options, useAutoRegister: automatic });
+  } catch (err) {
+    throw translateWebAuthnError(err, 'create');
+  }
+  const result = await api('api/passkeys/register', { body: { response } });
+  signalAcceptedCredentials(result.rpID, result.userId, result.passkeys);
+  return result;
+}
+
+/**
+ * Signs in with a passkey. `autofill: true` starts a conditional-mediation
+ * request that resolves when the user picks a passkey from the username field's
+ * autofill menu.
+ */
+export async function signInWithPasskey({ autofill = false } = {}): Promise<{ user: { username: string } }> {
+  return runAssertion('login', autofill);
+}
+
+/** Re-confirms the signed-in user with one of their passkeys. */
+export async function reauthenticateWithPasskey(): Promise<void> {
+  await runAssertion('reauth', false);
+}
+
+async function runAssertion(purpose: 'login' | 'reauth', autofill: boolean) {
+  const { options } = await api('api/passkeys/authentication-options', { body: { purpose } });
+  let response;
+  try {
+    response = await startAuthentication({ optionsJSON: options, useBrowserAutofill: autofill });
+  } catch (err) {
+    throw translateWebAuthnError(err, 'get');
+  }
+  try {
+    return await api('api/passkeys/verify-authentication', { body: { purpose, response } });
+  } catch (err) {
+    if (err instanceof ApiError && err.code === 'UNKNOWN_CREDENTIAL') {
+      signalUnknownCredential(err.data?.rpID ?? options.rpId ?? location.hostname, response.id);
+    }
+    throw err;
+  }
+}
+
+export function cancelPendingPasskeyRequest() {
+  WebAuthnAbortService.cancelCeremony();
+}
+
+/* ---- WebAuthn Signal API (keeps password managers in sync; no-ops where unsupported) ---- */
+
+function signalUnknownCredential(rpId: string, credentialId: string) {
+  const PKC = (window as any).PublicKeyCredential;
+  PKC?.signalUnknownCredential?.({ rpId, credentialId }).catch(() => {});
+}
+
+export function signalAcceptedCredentials(rpId: string, userId: string, passkeys: PublicPasskey[]) {
+  const PKC = (window as any).PublicKeyCredential;
+  PKC?.signalAllAcceptedCredentials?.({
+    rpId,
+    userId,
+    allAcceptedCredentialIds: passkeys.map((p) => p.id),
+  }).catch(() => {});
+}
+
+export function signalCurrentUserDetails(rpId: string, userId: string, username: string) {
+  const PKC = (window as any).PublicKeyCredential;
+  PKC?.signalCurrentUserDetails?.({ rpId, userId, name: username, displayName: username }).catch(() => {});
+}
+
+/** Only allow same-site relative redirects under the app's base path. */
+export function safeNextUrl(fallback = `${BASE}account`): string {
+  if (typeof window === 'undefined') return fallback;
+  const next = new URLSearchParams(window.location.search).get('next');
+  if (!next) return fallback;
+  try {
+    const url = new URL(next, window.location.origin);
+    if (url.origin !== window.location.origin || !url.pathname.startsWith(BASE)) return fallback;
+    return url.pathname + url.search + url.hash;
+  } catch {
+    return fallback;
+  }
+}
