+---
+import Layout from '../layouts/Layout.astro';
+import AccountSettings from '../components/AccountSettings';
+import { listPasskeys } from '../lib/auth/store';
+import { getRelyingParty, toPublicPasskey } from '../lib/auth/webauthn';
+
+const base = import.meta.env.BASE_URL;
+const user = await Astro.session?.get('user');
+if (!user) {
+  return Astro.redirect(`${base}signin?next=${encodeURIComponent(`${base}account`)}`);
+}
+
+Astro.response.headers.set('Cache-Control', 'no-store');
+const passkeys = (await listPasskeys(user.id)).map(toPublicPasskey);
+const authMethod = (await Astro.session?.get('authMethod')) ?? null;
+const { rpID } = getRelyingParty(Astro);
+---
+
+<Layout title="Account settings | The DevTools Times">
+  <div class="py-12 px-4 sm:px-6 lg:px-8">
+    <AccountSettings
+      client:load
+      username={user.username}
+      userId={user.id}
+      rpID={rpID}
+      authMethod={authMethod}
+      initialPasskeys={passkeys}
+    />
+  </div>
+</Layout>
diff --git a/src/pages/api/auth/login.ts b/src/pages/api/auth/login.ts
new file mode 100644
index 0000000..c78859c
--- /dev/null
+++ b/src/pages/api/auth/login.ts
@@ -0,0 +1,20 @@
+import type { APIRoute } from 'astro';
+import { ensureUser, listPasskeys } from '../../../lib/auth/store';
+import { errorResponse, json, readJson, startSession, verifyPasswordUpstream } from '../../../lib/auth/session';
+
+/** Password sign-in: verifies with the upstream account API, then starts a local session. */
+export const POST: APIRoute = async (context) => {
+  const body = await readJson<{ username?: string; password?: string }>(context.request);
+  const username = body?.username?.trim();
+  const password = body?.password;
+  if (!username || !password) return errorResponse(400, 'Username and password are required.');
+
+  const result = await verifyPasswordUpstream('login', username, password);
+  if (!result.ok) return errorResponse(result.status, result.error);
+
+  const user = await ensureUser(username);
+  await startSession(context, user, 'password');
+  const passkeys = await listPasskeys(user.id);
+
+  return json({ user: { username: user.username }, hasPasskeys: passkeys.length > 0 });
+};
