+import type { APIRoute } from 'astro';
+import {
+  errorResponse,
+  getSessionUser,
+  json,
+  markAuthenticated,
+  readJson,
+  verifyPasswordUpstream,
+} from '../../../../lib/auth/session';
+
+/** Re-confirms the signed-in user's identity with their password. */
+export const POST: APIRoute = async (context) => {
+  const user = await getSessionUser(context);
+  if (!user) return errorResponse(401, 'You need to sign in first.', 'UNAUTHENTICATED');
+
+  const body = await readJson<{ password?: string }>(context.request);
+  if (!body?.password) return errorResponse(400, 'Password is required.');
+
+  const result = await verifyPasswordUpstream('login', user.username, body.password);
+  if (!result.ok) {
+    return errorResponse(result.status === 502 ? 502 : 401, result.status === 502 ? result.error : `Verification failed: ${result.error}`);
+  }
+
+  markAuthenticated(context, 'password');
+  return json({ ok: true });
+};
diff --git a/src/pages/api/auth/register.ts b/src/pages/api/auth/register.ts
new file mode 100644
index 0000000..f19a342
--- /dev/null
+++ b/src/pages/api/auth/register.ts
@@ -0,0 +1,22 @@
+import type { APIRoute } from 'astro';
+import { ensureUser } from '../../../lib/auth/store';
+import { errorResponse, json, readJson, startSession, verifyPasswordUpstream } from '../../../lib/auth/session';
+
+/**
+ * Password sign-up: creates the account upstream and signs the new user in, so
+ * the UI can immediately offer to create a passkey.
+ */
+export const POST: APIRoute = async (context) => {
+  const body = await readJson<{ username?: string; password?: string }>(context.request);
+  const username = body?.username?.trim();
+  const password = body?.password;
+  if (!username || !password) return errorResponse(400, 'Username and password are required.');
+
+  const result = await verifyPasswordUpstream('register', username, password);
+  if (!result.ok) return errorResponse(result.status, result.error);
+
+  const user = await ensureUser(username);
+  await startSession(context, user, 'password');
+
