+import type { APIRoute } from 'astro';
+import { deletePasskey, findPasskey, listPasskeys, updatePasskey, type PasskeyRecord } from '../../../lib/auth/store';
+import { getRelyingParty, toPublicPasskey } from '../../../lib/auth/webauthn';
+import {
+  errorResponse,
+  getSessionUser,
+  isRecentlyAuthenticated,
+  json,
+  readJson,
+} from '../../../lib/auth/session';
+
+type Owned =
+  | { ok: false; error: Response }
+  | { ok: true; user: { id: string; username: string }; passkey: PasskeyRecord };
+
+async function ownedPasskey(context: Parameters<APIRoute>[0]): Promise<Owned> {
+  const user = await getSessionUser(context);
+  if (!user) return { ok: false, error: errorResponse(401, 'You need to sign in first.', 'UNAUTHENTICATED') };
+  const id = context.params.id;
+  const passkey = id ? await findPasskey(id) : undefined;
+  if (!passkey || passkey.userId !== user.id) return { ok: false, error: errorResponse(404, 'Passkey not found.') };
+  return { ok: true, user, passkey };
+}
+
+/** Rename a passkey. */
+export const PATCH: APIRoute = async (context) => {
+  const found = await ownedPasskey(context);
+  if (!found.ok) return found.error;
+
+  const body = await readJson<{ name?: string }>(context.request);
+  const name = body?.name?.trim();
+  if (!name) return errorResponse(400, 'Please enter a name.');
+  if (name.length > 64) return errorResponse(400, 'Names can be at most 64 characters.');
+
+  const updated = await updatePasskey(found.passkey.id, { name });
+  return json({ passkey: toPublicPasskey(updated!) });
+};
+
+/** Delete a passkey. Requires a recent (re)authentication. */
+export const DELETE: APIRoute = async (context) => {
+  const found = await ownedPasskey(context);
+  if (!found.ok) return found.error;
+  if (!(await isRecentlyAuthenticated(context))) {
+    return errorResponse(403, 'Please confirm it’s you before removing a passkey.', 'REAUTH_REQUIRED');
+  }
+
+  await deletePasskey(found.passkey.id, found.user.id);
+  const passkeys = (await listPasskeys(found.user.id)).map(toPublicPasskey);
+  return json({ passkeys, rpID: getRelyingParty(context).rpID, userId: found.user.id });
+};
