+import type { APIRoute } from 'astro';
+import { generateAuthenticationOptions } from '@simplewebauthn/server';
+import { listPasskeys } from '../../../lib/auth/store';
+import { getRelyingParty } from '../../../lib/auth/webauthn';
+import { errorResponse, getSessionUser, json, readJson, saveChallenge } from '../../../lib/auth/session';
+
+/**
+ * Step 1 of passkey authentication.
+ *  - purpose "login":  discoverable-credential sign-in (button or autofill / conditional UI).
+ *  - purpose "reauth": re-confirm the signed-in user, restricted to their own passkeys.
+ */
+export const POST: APIRoute = async (context) => {
+  const body = await readJson<{ purpose?: 'login' | 'reauth' }>(context.request);
+  const purpose = body?.purpose === 'reauth' ? 'reauth' : 'login';
+  const { rpID } = getRelyingParty(context);
+
+  if (purpose === 'reauth') {
+    const user = await getSessionUser(context);
+    if (!user) return errorResponse(401, 'You need to sign in first.', 'UNAUTHENTICATED');
+    const passkeys = await listPasskeys(user.id);
+    if (passkeys.length === 0) return errorResponse(400, 'You have no passkeys yet.', 'NO_PASSKEYS');
+
+    const options = await generateAuthenticationOptions({
+      rpID,
+      userVerification: 'required',
+      allowCredentials: passkeys.map((p) => ({ id: p.id, transports: p.transports })),
+    });
+    saveChallenge(context, options.challenge, 'reauth', user.id);
+    return json({ options });
+  }
+
+  const options = await generateAuthenticationOptions({
+    rpID,
+    userVerification: 'preferred',
+    allowCredentials: [],
+  });
+  saveChallenge(context, options.challenge, 'login');
+  return json({ options });
+};
