@@ -0,0 +1,70 @@
+import type { APIRoute } from 'astro';
+import { verifyRegistrationResponse, type RegistrationResponseJSON } from '@simplewebauthn/server';
+import { isoBase64URL } from '@simplewebauthn/server/helpers';
+import { addPasskey, listPasskeys } from '../../../lib/auth/store';
+import { defaultPasskeyName, getRelyingParty, toPublicPasskey } from '../../../lib/auth/webauthn';
+import {
+  consumeChallenge,
+  errorResponse,
+  getSessionUser,
+  isRecentlyAuthenticated,
+  json,
+  readJson,
+} from '../../../lib/auth/session';
+
+/** Step 2 of passkey registration: verify the attestation and store the credential. */
+export const POST: APIRoute = async (context) => {
+  const user = await getSessionUser(context);
+  if (!user) return errorResponse(401, 'You need to sign in first.', 'UNAUTHENTICATED');
+  if (!(await isRecentlyAuthenticated(context))) {
+    return errorResponse(403, 'Please confirm it’s you before adding a passkey.', 'REAUTH_REQUIRED');
+  }
+
+  const body = await readJson<{ response?: RegistrationResponseJSON }>(context.request);
+  if (!body?.response) return errorResponse(400, 'Missing registration response.');
+
+  const pending = await consumeChallenge(context, 'register');
+  if (!pending || pending.userId !== user.id) {
+    return errorResponse(400, 'The passkey request expired. Please try again.', 'CHALLENGE_EXPIRED');
+  }
+
+  const { rpID, origins } = getRelyingParty(context);
+  let verification;
+  try {
+    verification = await verifyRegistrationResponse({
+      response: body.response,
+      expectedChallenge: pending.challenge,
+      expectedOrigin: origins,
+      expectedRPID: rpID,
+      requireUserVerification: false,
+    });
+  } catch (err) {
+    return errorResponse(400, `Passkey verification failed: ${(err as Error).message}`);
+  }
+
+  if (!verification.verified) return errorResponse(400, 'Passkey verification failed.');
+
+  const { credential, aaguid, credentialDeviceType, credentialBackedUp } = verification.registrationInfo;
+  const record = {
+    id: credential.id,
+    userId: user.id,
+    publicKey: isoBase64URL.fromBuffer(credential.publicKey),
+    counter: credential.counter,
+    transports: credential.transports ?? body.response.response.transports ?? [],
+    name: defaultPasskeyName(aaguid, context.request.headers.get('user-agent')),
+    aaguid,
+    deviceType: credentialDeviceType,
+    backedUp: credentialBackedUp,
+    createdAt: Date.now(),
+    lastUsedAt: null,
+  };
+
+  try {
+    await addPasskey(record);
+  } catch (err) {
+    return errorResponse(409, (err as Error).message);
+  }
+
+  const passkeys = (await listPasskeys(user.id)).map(toPublicPasskey);
+  return json({ passkey: toPublicPasskey(record), passkeys, rpID, userId: user.id });
+};
