+import type { APIRoute } from 'astro';
+import { generateRegistrationOptions } from '@simplewebauthn/server';
+import { isoBase64URL } from '@simplewebauthn/server/helpers';
+import { listPasskeys } from '../../../lib/auth/store';
+import { getRelyingParty } from '../../../lib/auth/webauthn';
+import {
+  errorResponse,
+  getSessionUser,
+  isRecentlyAuthenticated,
+  json,
+  saveChallenge,
+} from '../../../lib/auth/session';
+
+/** Step 1 of passkey registration for the signed-in user. Requires a recent sign-in. */
+export const POST: APIRoute = async (context) => {
+  const user = await getSessionUser(context);
+  if (!user) return errorResponse(401, 'You need to sign in first.', 'UNAUTHENTICATED');
+  if (!(await isRecentlyAuthenticated(context))) {
+    return errorResponse(403, 'Please confirm it’s you before adding a passkey.', 'REAUTH_REQUIRED');
+  }
+
+  const { rpID, rpName } = getRelyingParty(context);
+  const existing = await listPasskeys(user.id);
+
+  const options = await generateRegistrationOptions({
+    rpName,
+    rpID,
+    userID: isoBase64URL.toBuffer(user.id),
+    userName: user.username,
+    userDisplayName: user.username,
+    attestationType: 'none',
+    // Prevent registering a second passkey on an authenticator that already has one.
+    excludeCredentials: existing.map((p) => ({ id: p.id, transports: p.transports })),
+    authenticatorSelection: {
+      residentKey: 'required',
+      userVerification: 'preferred',
+    },
+    extensions: { credProps: true } as any,
+  });
+
+  saveChallenge(context, options.challenge, 'register', user.id);
+  return json({ options });
+};
