+import type { APIRoute } from 'astro';
+import { verifyAuthenticationResponse, type AuthenticationResponseJSON } from '@simplewebauthn/server';
+import { isoBase64URL } from '@simplewebauthn/server/helpers';
+import { findPasskey, findUserById, updatePasskey } from '../../../lib/auth/store';
+import { getRelyingParty } from '../../../lib/auth/webauthn';
+import {
+  consumeChallenge,
+  errorResponse,
+  getSessionUser,
+  json,
+  markAuthenticated,
+  readJson,
+  startSession,
+} from '../../../lib/auth/session';
+
+/** Step 2 of passkey authentication, for both sign-in and reauthentication. */
+export const POST: APIRoute = async (context) => {
+  const body = await readJson<{ purpose?: 'login' | 'reauth'; response?: AuthenticationResponseJSON }>(
+    context.request,
+  );
+  const purpose = body?.purpose === 'reauth' ? 'reauth' : 'login';
+  const response = body?.response;
+  if (!response) return errorResponse(400, 'Missing authentication response.');
+
+  const { rpID, origins } = getRelyingParty(context);
+
+  const sessionUser = purpose === 'reauth' ? await getSessionUser(context) : null;
+  if (purpose === 'reauth' && !sessionUser) {
+    return errorResponse(401, 'You need to sign in first.', 'UNAUTHENTICATED');
+  }
+
+  const pending = await consumeChallenge(context, purpose);
+  if (!pending || (purpose === 'reauth' && pending.userId !== sessionUser!.id)) {
+    return errorResponse(400, 'The passkey request expired. Please try again.', 'CHALLENGE_EXPIRED');
+  }
+
+  const passkey = await findPasskey(response.id);
+  if (!passkey) {
+    // Lets the client tell the passkey provider to hide/remove this stale credential.
+    return json(
+      { error: 'This passkey is not registered with The DevTools Times. It may have been removed.', code: 'UNKNOWN_CREDENTIAL', rpID },
+      404,
+    );
+  }
+
+  if (response.response.userHandle && response.response.userHandle !== passkey.userId) {
+    return errorResponse(400, 'Passkey does not match its account.');
+  }
+  if (purpose === 'reauth' && passkey.userId !== sessionUser!.id) {
+    return errorResponse(403, 'That passkey belongs to a different account.');
+  }
+
+  const user = await findUserById(passkey.userId);
+  if (!user) return errorResponse(404, 'Account not found.', 'UNKNOWN_CREDENTIAL');
+
+  let verification;
+  try {
+    verification = await verifyAuthenticationResponse({
+      response,
+      expectedChallenge: pending.challenge,
+      expectedOrigin: origins,
+      expectedRPID: rpID,
+      credential: {
+        id: passkey.id,
+        publicKey: isoBase64URL.toBuffer(passkey.publicKey),
+        counter: passkey.counter,
+        transports: passkey.transports,
+      },
+      requireUserVerification: purpose === 'reauth',
+    });
+  } catch (err) {
+    return errorResponse(400, `Passkey verification failed: ${(err as Error).message}`);
+  }
+  if (!verification.verified) return errorResponse(400, 'Passkey verification failed.');
+
+  const info = verification.authenticationInfo;
+  await updatePasskey(passkey.id, {
+    counter: info.newCounter,
+    backedUp: info.credentialBackedUp,
+    deviceType: info.credentialDeviceType,
+    lastUsedAt: Date.now(),
+  });
+
+  if (purpose === 'login') {
+    await startSession(context, user, 'passkey');
+  } else {
+    markAuthenticated(context, 'passkey');
+  }
+
+  return json({ user: { username: user.username }, rpID, userId: user.id });
+};
