+/**
+ * <drink-card> — hydrates server-rendered drink cards in place.
+ *
+ * Each card ships its shadow tree in the HTML through Declarative Shadow DOM
+ * (<template shadowrootmode="open">), so the browser attaches and styles it
+ * while parsing, before this script runs. On upgrade the element reuses the
+ * shadow root it already has. It never re-renders. It only attaches event
+ * listeners and restores state that was saved in the browser.
+ */
+
+const STORAGE_KEY = 'dailygrind:favorites';
+
+function readFavorites() {
+  try {
+    const parsed = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
+    return new Set(Array.isArray(parsed) ? parsed : []);
+  } catch {
+    return new Set();
+  }
+}
+
+function writeFavorites(set) {
+  try {
+    localStorage.setItem(STORAGE_KEY, JSON.stringify([...set]));
+  } catch {
+    /* storage unavailable (private mode, quota) — keep in-memory state only */
+  }
+}
+
+class DrinkCard extends HTMLElement {
+  static observedAttributes = ['favorite'];
+
+  #root = null;
+  #favBtn = null;
+  #detailsBtn = null;
+  #panel = null;
+
+  connectedCallback() {
+    if (this.#root) return; // already hydrated (e.g. element was moved)
+
+    // Reuse the declaratively-attached root. Older browsers without Declarative
+    // Shadow DOM fall back to attaching the inline template once.
+    let root = this.shadowRoot;
+    if (!root) {
+      const tpl = this.querySelector(':scope > template[shadowrootmode]');
+      if (!tpl) return;
+      root = this.attachShadow({ mode: tpl.getAttribute('shadowrootmode') || 'open' });
+      root.appendChild(tpl.content);
+      tpl.remove();
+    }
+    this.#root = root;
+
+    this.#favBtn = root.querySelector('[data-action="favorite"]');
+    this.#detailsBtn = root.querySelector('[data-action="details"]');
