+    this.#favBtn?.addEventListener('click', () => this.toggleFavorite());
+    this.#detailsBtn?.addEventListener('click', () => this.toggleDetails());
+
+    // Restore saved favorite state. This changes nothing unless the user
+    // favorited this drink on an earlier visit.
+    const id = this.drinkId;
+    if (id && readFavorites().has(id)) this.setAttribute('favorite', '');
+    else this.#syncFavorite();
+
+    // Turn on the controls now that they work.
+    this.#favBtn?.removeAttribute('disabled');
+    this.#detailsBtn?.removeAttribute('disabled');
+    this.setAttribute('hydrated', '');
+  }
+
+  attributeChangedCallback(name) {
+    if (name === 'favorite' && this.#root) this.#syncFavorite();
+  }
+
+  get drinkId() {
+    return this.getAttribute('drink-id');
+  }
+
+  get favorite() {
+    return this.hasAttribute('favorite');
+  }
+
+  set favorite(value) {
+    this.toggleAttribute('favorite', Boolean(value));
+  }
+
+  toggleFavorite() {
+    this.favorite = !this.favorite;
+
+    const id = this.drinkId;
+    if (id) {
+      const favs = readFavorites();
+      this.favorite ? favs.add(id) : favs.delete(id);
+      writeFavorites(favs);
+    }
+
+    this.dispatchEvent(
+      new CustomEvent('favorite-change', {
+        bubbles: true,
+        composed: true,
+        detail: { id, favorite: this.favorite },
+      })
+    );
+  }
+
+  toggleDetails(force) {
+    if (!this.#panel || !this.#detailsBtn) return;
+    const open = typeof force === 'boolean' ? force : this.#panel.hidden;
+    this.#panel.hidden = !open;
+    this.#detailsBtn.setAttribute('aria-expanded', String(open));
+    this.#detailsBtn.querySelector('.label').textContent = open ? 'Hide details' : 'View details';
+  }
+
+  #syncFavorite() {
+    if (!this.#favBtn) return;
+    const on = this.favorite;
+    const name = this.querySelector('[slot="title"]')?.textContent.trim() || 'drink';
+    this.#favBtn.setAttribute('aria-pressed', String(on));
+    this.#favBtn.setAttribute('aria-label', `${on ? 'Remove' : 'Add'} ${name} ${on ? 'from' : 'to'} favorites`);
+  }
+}
+
+if (!customElements.get('drink-card')) {
+  customElements.define('drink-card', DrinkCard);
+}
