+# HTTP response headers for The Daily Grind (Netlify / Cloudflare Pages `_headers` format).
+# Translate 1:1 into nginx `add_header`, Express middleware, or CDN rules if hosted elsewhere.
+# index.html carries a <meta> CSP + referrer fallback, but frame-ancestors, report-to,
+# Permissions-Policy, HSTS, COOP/CORP and Clear-Site-Data only take effect as real headers.
+
+/*
+  Content-Security-Policy: default-src 'none'; script-src 'self' 'report-sample'; style-src 'self'; img-src 'self'; font-src 'self'; connect-src 'self'; manifest-src 'self'; worker-src 'self'; form-action 'self'; base-uri 'none'; object-src 'none'; frame-src 'none'; frame-ancestors 'none'; require-trusted-types-for 'script'; trusted-types 'none'; upgrade-insecure-requests; report-to csp
+  # First-party report collector. Strip query strings / PII from reports before storing them.
+  Reporting-Endpoints: csp="/reports/csp"
+  Referrer-Policy: same-origin
+  # Deny powerful and ad/tracking-related features to this page and any embedded frame.
+  Permissions-Policy: accelerometer=(), ambient-light-sensor=(), attribution-reporting=(), autoplay=(), bluetooth=(), browsing-topics=(), camera=(), display-capture=(), encrypted-media=(), gamepad=(), geolocation=(), gyroscope=(), hid=(), identity-credentials-get=(), idle-detection=(), join-ad-interest-group=(), local-fonts=(), magnetometer=(), microphone=(), midi=(), otp-credentials=(), payment=(), private-state-token-issuance=(), private-state-token-redemption=(), publickey-credentials-get=(self), run-ad-auction=(), screen-wake-lock=(), serial=(), storage-access=(), usb=(), window-management=(), xr-spatial-tracking=()
+  X-Frame-Options: DENY
+  X-Content-Type-Options: nosniff
+  Cross-Origin-Opener-Policy: same-origin-allow-popups
+  Cross-Origin-Resource-Policy: same-origin
+  # Start short and ramp up to 31536000 (then add `preload`) once HTTPS is verified everywhere.
+  Strict-Transport-Security: max-age=300; includeSubDomains
+
+# Pages that may show personal data must never be cached by browsers or shared proxies.
+/account/*
+  Cache-Control: no-store
+/rewards/*
+  Cache-Control: no-store
+/order-online/*
+  Cache-Control: no-store
+
+# Logout (POST): wipe cookies, Web Storage, IndexedDB, service workers and HTTP cache for
+# this origin. The session cookie itself should be `__Host-session; Secure; HttpOnly;
+# SameSite=Lax; Path=/` and invalidated server-side as well.
+/logout
+  Clear-Site-Data: "cookies", "storage", "cache"
+  Cache-Control: no-store
+
+# Static, non-personal assets.
+/images/*
+  Cache-Control: public, max-age=604800
+/.well-known/gpc.json
+  Content-Type: application/json
