+++ b/js/privacy.js
@@ -0,0 +1,51 @@
+// Client-side privacy helpers for The Daily Grind.
+//
+// Principles:
+//  - No analytics, ads, tag managers, or third-party SDKs are loaded.
+//  - Nothing personal is written to localStorage/sessionStorage (any embedded
+//    script could read it); sessions live in HttpOnly cookies set by the server.
+//  - On logout, wipe anything the browser holds for this origin. The server's
+//    `Clear-Site-Data` response header is the primary mechanism; this is a
+//    best-effort fallback for browsers that ignore or only partially honour it.
+
+const LOGOUT_CLEANUP_TIMEOUT_MS = 1500;
+
+async function clearClientState() {
+  try {
+    localStorage.clear();
+    sessionStorage.clear();
+  } catch {
+    // Storage can be unavailable (e.g. blocked by user settings) — nothing to clear.
+  }
+
+  const tasks = [];
+  if ('caches' in window) {
+    tasks.push(
+      caches.keys().then((keys) => Promise.all(keys.map((key) => caches.delete(key)))),
+    );
+  }
+  if ('serviceWorker' in navigator) {
+    tasks.push(
+      navigator.serviceWorker
+        .getRegistrations()
+        .then((regs) => Promise.all(regs.map((reg) => reg.unregister()))),
+    );
+  }
+
+  // Never let cleanup block the user from logging out.
+  await Promise.race([
+    Promise.allSettled(tasks),
+    new Promise((resolve) => setTimeout(resolve, LOGOUT_CLEANUP_TIMEOUT_MS)),
+  ]);
+}
+
+for (const form of document.querySelectorAll('form[data-logout]')) {
+  form.addEventListener('submit', async (event) => {
+    event.preventDefault();
+    const button = form.querySelector('button');
+    if (button) button.disabled = true;
+    await clearClientState();
+    // HTMLFormElement.submit() does not re-dispatch the submit event.
+    form.submit();
+  });
+}

