+# Security & privacy response headers (Netlify / Cloudflare Pages format).
+# For other hosts, port these to the server or CDN config (see PRIVACY.md).
+# Keep the CSP in sync with the <meta http-equiv="Content-Security-Policy"> in index.html.
+
+/*
+  Content-Security-Policy: default-src 'none'; script-src 'self'; style-src 'self'; img-src 'self'; font-src 'self'; connect-src 'self'; manifest-src 'self'; form-action 'self'; frame-ancestors 'none'; base-uri 'none'; object-src 'none'; upgrade-insecure-requests
+  Strict-Transport-Security: max-age=63072000; includeSubDomains; preload
+  Referrer-Policy: strict-origin-when-cross-origin
+  Permissions-Policy: accelerometer=(), ambient-light-sensor=(), autoplay=(), battery=(), bluetooth=(), browsing-topics=(), camera=(), display-capture=(), document-domain=(), encrypted-media=(), geolocation=(), gyroscope=(), hid=(), idle-detection=(), interest-cohort=(), magnetometer=(), microphone=(), midi=(), payment=(), publickey-credentials-get=(), screen-wake-lock=(), serial=(), usb=(), xr-spatial-tracking=()
+  X-Content-Type-Options: nosniff
+  X-Frame-Options: DENY
+  Cross-Origin-Opener-Policy: same-origin
+  Cross-Origin-Resource-Policy: same-origin
+  Cross-Origin-Embedder-Policy: require-corp
+  Origin-Agent-Cluster: ?1
+  X-DNS-Prefetch-Control: off
+  X-Permitted-Cross-Domain-Policies: none
+
+# Pages that may show personal data must never be cached by shared caches.
+/
+  Cache-Control: no-store
+/index.html
+  Cache-Control: no-store
+/account*
+  Cache-Control: no-store
+  X-Robots-Tag: noindex, nofollow
+/rewards*
+  Cache-Control: no-store
+/order-online*
+  Cache-Control: no-store
+
+# Logout: wipe everything the browser holds for this origin.
+/logout
+  Clear-Site-Data: "cache", "cookies", "storage"
+  Cache-Control: no-store
+
+# Static assets carry no personal data and are safe to cache. (Use "immutable" + a
+# long max-age only once filenames are content-hashed.)
+/assets/*
+  Cache-Control: public, max-age=86400
+
+# Global Privacy Control support declaration.
+/.well-known/gpc.json
+  Content-Type: application/json
+  Access-Control-Allow-Origin: *
+  Cross-Origin-Resource-Policy: cross-origin
