+/*
+ * The Daily Grind: client-side privacy controls.
+ *
+ * Principles (see PRIVACY.md):
+ *   - Privacy by default: anything that isn't strictly necessary is OFF until
+ *     the visitor opts in. Nothing is stored before they make a choice.
+ *   - Respect browser signals: Global Privacy Control (GPC) and Do Not Track
+ *     count as an opt-out and can't be overridden from this page.
+ *   - Data minimization: we store only the consent choice (category flags,
+ *     policy version, and the date, with no time of day) and nothing that
+ *     identifies the visitor.
+ *   - Secure handling: client-side storage is wiped on logout, and only
+ *     scripts listed in the audited registry below may be loaded, even after
+ *     consent.
+ *
+ * Loaded as an external, same-origin, deferred script so the CSP needs no
+ * 'unsafe-inline'.
+ */
+(function () {
+  'use strict';
+
+  var STORAGE_KEY = 'dg_privacy_consent';
+  // Bump this when the privacy policy or the categories change, so visitors
+  // are asked again.
+  var POLICY_VERSION = '2026-11-20';
+  var CONSENT_MAX_AGE_DAYS = 365;
+
+  var CATEGORIES = ['functional', 'analytics', 'marketing'];
+  // Categories that GPC / DNT turn off ("sale/share" and cross-context tracking).
+  var SIGNAL_RESTRICTED = ['analytics', 'marketing'];
+
+  /*
+   * Audited third-party registry. A script marked up as
+   *   <script type="text/plain" data-consent="analytics" data-src="...">
+   * only runs if (1) the visitor consented to its category AND (2) its origin
+   * is listed here with a matching category. Adding an entry means:
+   *   a) a completed review in PRIVACY.md ("Third-party audit"),
+   *   b) adding the origin to the CSP in index.html and _headers,
+   *   c) a Subresource Integrity hash on the tag.
+   * Empty on purpose: the site currently uses no third parties.
+   */
+  var THIRD_PARTY_REGISTRY = [
+    // { origin: 'https://analytics.example', category: 'analytics' }
+  ];
+
+  // Tracking parameters removed from the address bar so they aren't kept in
+  // history, bookmarks, or links visitors share.
+  var TRACKING_PARAMS = /^(utm_[a-z]+|fbclid|gclid|dclid|gbraid|wbraid|msclkid|mc_eid|mc_cid|_hsenc|_hsmi|igshid|yclid|twclid|li_fat_id)$/i;
+
+  var listeners = [];
+
+  // ---------- Browser privacy signals ----------
+
+  function hasGlobalPrivacyControl() {
+    return navigator.globalPrivacyControl === true;
+  }
+
+  function hasDoNotTrack() {
+    var dnt = navigator.doNotTrack || window.doNotTrack || navigator.msDoNotTrack;
+    return dnt === '1' || dnt === 'yes';
+  }
+
+  function optOutSignal() {
+    return hasGlobalPrivacyControl() || hasDoNotTrack();
+  }
+
+  // ---------- Safe storage helpers ----------
+
+  function storageAvailable(type) {
+    try {
+      var s = window[type];
+      var k = '__dg_test__';
+      s.setItem(k, k);
+      s.removeItem(k);
+      return true;
+    } catch (e) {
+      return false;
+    }
+  }
+
+  var canUseLocalStorage = storageAvailable('localStorage');
+
+  function today() {
+    // Date only (YYYY-MM-DD). A precise timestamp isn't needed.
+    return new Date().toISOString().slice(0, 10);
+  }
+
+  function daysSince(isoDate) {
+    var then = Date.parse(isoDate);
+    if (isNaN(then)) return Infinity;
+    return (Date.now() - then) / 86400000;
+  }
+
+  // ---------- Consent state ----------
+
+  function defaultConsent() {
+    var c = { essential: true };
+    CATEGORIES.forEach(function (cat) { c[cat] = false; });
+    return c;
+  }
+
+  function sanitize(raw) {
+    // Rebuild from a fixed schema. Never trust or keep unknown fields.
+    var c = defaultConsent();
+    if (raw && typeof raw === 'object') {
+      CATEGORIES.forEach(function (cat) { c[cat] = raw[cat] === true; });
+    }
+    if (optOutSignal()) {
+      SIGNAL_RESTRICTED.forEach(function (cat) { c[cat] = false; });
+    }
+    return c;
+  }
+
+  function readStored() {
+    if (!canUseLocalStorage) return null;
+    try {
+      var parsed = JSON.parse(localStorage.getItem(STORAGE_KEY));
+      if (!parsed || parsed.v !== POLICY_VERSION || daysSince(parsed.d) > CONSENT_MAX_AGE_DAYS) {
+        localStorage.removeItem(STORAGE_KEY);
+        return null;
+      }
+      return parsed;
+    } catch (e) {
+      try { localStorage.removeItem(STORAGE_KEY); } catch (ignore) { /* noop */ }
+      return null;
+    }
+  }
+
+  function getConsent() {
+    var stored = readStored();
+    return sanitize(stored && stored.c);
+  }
+
+  function hasStoredChoice() {
+    return readStored() !== null;
+  }
+
+  function saveConsent(choice) {
+    var clean = sanitize(choice);
+    var record = { v: POLICY_VERSION, d: today(), c: {} };
+    CATEGORIES.forEach(function (cat) { record.c[cat] = clean[cat]; });
+    if (canUseLocalStorage) {
+      try {
+        localStorage.setItem(STORAGE_KEY, JSON.stringify(record));
+      } catch (e) { /* storage full or blocked: consent applies to this page view only */ }
+    }
+    if (!clean.functional) clearNonEssentialStorage();
+    listeners.forEach(function (fn) {
+      try { fn(clean); } catch (e) { /* isolate listener failures */ }
+    });
+    activateConsentedScripts(clean);
+    return clean;
+  }
+
+  function hasConsent(category) {
+    if (category === 'essential') return true;
+    if (CATEGORIES.indexOf(category) === -1) return false; // unknown category: deny
+    return getConsent()[category] === true;
+  }
+
+  function onConsentChange(fn) {
+    if (typeof fn === 'function') listeners.push(fn);
+  }
+
+  // ---------- Secure data handling ----------
+
+  // Remove everything except the consent record itself.
+  function clearNonEssentialStorage() {
+    if (canUseLocalStorage) {
+      try {
+        Object.keys(localStorage).forEach(function (k) {
+          if (k !== STORAGE_KEY) localStorage.removeItem(k);
+        });
+      } catch (e) { /* noop */ }
+    }
+  }
+
+  // Wipe everything this page can reach on the client. Used on logout.
+  // HttpOnly session cookies can't be touched from JS; the server clears those
+  // with Clear-Site-Data on POST /logout (see _headers / PRIVACY.md).
+  function clearClientData() {
+    try { if (window.sessionStorage) sessionStorage.clear(); } catch (e) { /* noop */ }
+    clearNonEssentialStorage();
+    // Expire every cookie visible to JS, on this path and the root path.
+    try {
+      document.cookie.split(';').forEach(function (part) {
+        var name = part.split('=')[0].trim();
+        if (!name) return;
+        document.cookie = name + '=; Max-Age=0';
+        document.cookie = name + '=; Max-Age=0; path=/';
+      });
+    } catch (e) { /* noop */ }
+    if (window.caches && caches.keys) {
+      caches.keys().then(function (keys) {
+        keys.forEach(function (k) { caches.delete(k); });
+      }).catch(function () { /* noop */ });
+    }
+  }
+
+  // ---------- Consent-gated script loading ----------
+
+  function isRegistered(src, category) {
+    var url;
+    try { url = new URL(src, location.href); } catch (e) { return false; }
+    if (url.protocol !== 'https:' && url.origin !== location.origin) return false;
+    if (url.origin === location.origin) return true; // first-party scripts
+    return THIRD_PARTY_REGISTRY.some(function (entry) {
+      return entry.origin === url.origin && entry.category === category;
+    });
+  }
+
+  function activateConsentedScripts(consent) {
+    var pending = document.querySelectorAll('script[type="text/plain"][data-consent][data-src]');
+    Array.prototype.forEach.call(pending, function (placeholder) {
+      var category = placeholder.getAttribute('data-consent');
+      var src = placeholder.getAttribute('data-src');
+      if (!consent[category] || !isRegistered(src, category)) return;
+      var s = document.createElement('script');
+      s.src = src;
+      s.defer = true;
+      s.referrerPolicy = 'no-referrer';
+      var integrity = placeholder.getAttribute('data-integrity');
+      if (integrity) {
+        s.integrity = integrity;
+        s.crossOrigin = 'anonymous';
+      } else if (new URL(src, location.href).origin !== location.origin) {
+        return; // third-party scripts must have SRI
+      }
+      placeholder.parentNode.replaceChild(s, placeholder);
+    });
+  }
+
+  // ---------- Data minimization: tracking parameters ----------
+
+  function stripTrackingParams() {
+    if (!window.history || !history.replaceState || !window.URL) return;
+    try {
+      var url = new URL(location.href);
+      var changed = false;
+      Array.from(url.searchParams.keys()).forEach(function (key) {
+        if (TRACKING_PARAMS.test(key)) {
+          url.searchParams.delete(key);
+          changed = true;
+        }
+      });
+      if (changed) history.replaceState(history.state, '', url.pathname + url.search + url.hash);
+    } catch (e) { /* noop */ }
+  }
+
+  // ---------- UI wiring ----------
+
+  function initPreferencesDialog() {
+    var dialog = document.getElementById('privacy-dialog');
+    var openBtn = document.getElementById('privacy-choices-btn');
+    if (!dialog || !openBtn) return;
+
+    // Only show the "Privacy choices" button when JS runs (it does nothing otherwise).
+    openBtn.hidden = false;
+    var openBtnSep = document.getElementById('privacy-choices-sep');
+    if (openBtnSep) openBtnSep.hidden = false;
+
+    var form = dialog.querySelector('form');
+    var gpcNote = document.getElementById('gpc-status');
+
+    function render() {
+      var consent = getConsent();
+      var signal = optOutSignal();
+      CATEGORIES.forEach(function (cat) {
+        var box = form.elements[cat];
+        if (!box) return;
+        box.checked = consent[cat];
+        box.disabled = signal && SIGNAL_RESTRICTED.indexOf(cat) !== -1;
+      });
+      if (gpcNote) gpcNote.hidden = !signal;
+    }
+
+    function open() {
+      render();
+      if (typeof dialog.showModal === 'function') dialog.showModal();
+      else dialog.setAttribute('open', '');
+    }
+
+    function close() {
+      if (typeof dialog.close === 'function') dialog.close();
+      else dialog.removeAttribute('open');
+      openBtn.focus();
+    }
+
+    openBtn.addEventListener('click', open);
+
+    form.addEventListener('submit', function (e) {
+      e.preventDefault();
+      var action = e.submitter ? e.submitter.value : 'save';
+      var choice = {};
+      CATEGORIES.forEach(function (cat) {
+        if (action === 'reject') choice[cat] = false;
+        else choice[cat] = !!(form.elements[cat] && form.elements[cat].checked);
+      });
+      saveConsent(choice);
+      close();
+    });
+
+    var cancel = dialog.querySelector('[data-action="cancel"]');
+    if (cancel) cancel.addEventListener('click', close);
+  }
+
+  function initLogout() {
+    var forms = document.querySelectorAll('form[data-logout]');
+    Array.prototype.forEach.call(forms, function (f) {
+      // Clear client data, then let the POST go ahead so the server can end
+      // the session and send Clear-Site-Data.
+      f.addEventListener('submit', clearClientData);
+    });
+  }
+
+  // ---------- Public API ----------
+
+  window.DailyGrindPrivacy = Object.freeze({
+    hasConsent: hasConsent,
+    getConsent: getConsent,
+    hasStoredChoice: hasStoredChoice,
+    onConsentChange: onConsentChange,
+    clearClientData: clearClientData,
+    signals: Object.freeze({
+      globalPrivacyControl: hasGlobalPrivacyControl(),
+      doNotTrack: hasDoNotTrack()
+    })
+  });
+
+  stripTrackingParams();
+
+  function ready() {
+    initPreferencesDialog();
+    initLogout();
+    activateConsentedScripts(getConsent());
+  }
+
+  if (document.readyState === 'loading') {
+    document.addEventListener('DOMContentLoaded', ready);
+  } else {
+    ready();
+  }
+})();
