--- /dev/null
+++ b/src/components/PrivacyConsent.astro
@@ -0,0 +1,199 @@
+---
+/**
+ * Privacy consent manager (privacy by design / by default).
+ *
+ * - No third-party analytics is loaded until the visitor explicitly opts in.
+ * - Global Privacy Control (and legacy Do Not Track) are honoured as an opt-out
+ *   and suppress the banner entirely.
+ * - Authentication pages are never tracked, even if consent was given.
+ * - Any element inside a `[data-private]` region is never tracked.
+ * - Consent can be reviewed or withdrawn at any time via any element with
+ *   `data-privacy-settings` (e.g. the footer link).
+ *
+ * The choice is stored only in localStorage on the visitor's device (no
+ * cookie, nothing sent to our servers).
+ */
+const baseUrl = import.meta.env.BASE_URL.replace(/\/?$/, "/");
+---
+
+<script is:inline>
+  (function () {
+    if (window.dtPrivacy) return; // already initialised (ClientRouter navigations)
+
+    var STORAGE_KEY = "dt-privacy-consent-v1";
+    var ANALYTICS_SRC =
+      "https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/lib/analytics-client.js";
+    var PRIVATE_PATH = /\/(signin|signup)\/?$/;
+
+    var analyticsLoaded = false;
+
+    function hasOptOutSignal() {
+      return (
+        navigator.globalPrivacyControl === true ||
+        navigator.doNotTrack === "1" ||
+        window.doNotTrack === "1"
+      );
+    }
+
+    function readConsent() {
+      try {
+        var raw = localStorage.getItem(STORAGE_KEY);
+        return raw ? JSON.parse(raw) : null;
+      } catch (e) {
+        return null;
+      }
+    }
+
+    function writeConsent(analytics) {
+      // Store only what is needed: the decision and the day it was made.
+      var value = { analytics: !!analytics, date: new Date().toISOString().slice(0, 10) };
+      try {
+        localStorage.setItem(STORAGE_KEY, JSON.stringify(value));
+      } catch (e) {}
+      return value;
+    }
+
+    function analyticsAllowed() {
+      if (hasOptOutSignal()) return false;
+      var c = readConsent();
+      return !!(c && c.analytics === true);
+    }
+
+    function isPrivatePage() {
+      return PRIVATE_PATH.test(location.pathname);
+    }
+
+    function loadAnalytics() {
+      if (analyticsLoaded || !analyticsAllowed() || isPrivatePage()) return;
+      analyticsLoaded = true;
+      var s = document.createElement("script");
+      s.src = ANALYTICS_SRC;
+      s.defer = true;
+      s.referrerPolicy = "no-referrer";
+      document.head.appendChild(s);
+    }
+
+    // Capture-phase guard: runs before the analytics click listener and marks
+    // the clicked element as untracked whenever tracking is not permitted
+    // (consent withdrawn, private page, or private region).
+    window.addEventListener(
+      "click",
+      function (event) {
+        var el = event.target && event.target.closest && event.target.closest("a, button");
+        if (!el) return;
+        if (!analyticsAllowed() || isPrivatePage() || el.closest("[data-private]")) {
+          el.setAttribute("data-skip-tracking", "true");
+        }
+      },
+      true
+    );
+
+    function banner() {
+      return document.getElementById("privacy-consent");
+    }
+
+    function showBanner(force) {
+      var b = banner();
+      if (!b) return;
+      var gpc = hasOptOutSignal();
+      var note = b.querySelector("[data-gpc-note]");
+      var accept = b.querySelector("[data-consent-accept]");
+      if (note) note.hidden = !gpc;
+      if (accept) accept.disabled = gpc;
+      if (force || (!gpc && readConsent() === null)) {
+        b.hidden = false;
+      }
+    }
+
+    function hideBanner() {
+      var b = banner();
+      if (b) b.hidden = true;
+    }
+
+    document.addEventListener("click", function (event) {
+      var t = event.target;
+      if (!t || !t.closest) return;
+      if (t.closest("[data-privacy-settings]")) {
+        event.preventDefault();
+        showBanner(true);
+      } else if (t.closest("[data-consent-accept]")) {
+        writeConsent(true);
+        hideBanner();
+        loadAnalytics();
+      } else if (t.closest("[data-consent-reject]")) {
+        writeConsent(false);
+        hideBanner();
+        // An already-loaded tracker cannot be unloaded; the capture-phase guard
+        // above stops it from recording anything further on this page, and it
+        // will not be loaded again on the next full page load.
+      }
+    });
+
+    function onPage() {
+      showBanner(false);
+      loadAnalytics();
+    }
+
+    document.addEventListener("astro:page-load", onPage);
+    if (document.readyState === "loading") {
+      document.addEventListener("DOMContentLoaded", onPage);
+    } else {
+      onPage();
+    }
+
+    window.dtPrivacy = {
+      open: function () {
+        showBanner(true);
+      },
+      getConsent: readConsent,
+    };
+  })();
+</script>
+
+<div
+  id="privacy-consent"
+  transition:persist
+  hidden
+  role="region"
+  aria-labelledby="privacy-consent-title"
+  class="fixed inset-x-0 bottom-0 z-[100] border-t border-gray-300 bg-white p-4 shadow-lg md:p-6"
+  data-private
+>
+  <div class="mx-auto flex max-w-4xl flex-col gap-4 md:flex-row md:items-end md:justify-between">
+    <div class="text-sm text-gray-700">
+      <h2 id="privacy-consent-title" class="mb-1 text-base font-bold text-gray-900">Your privacy</h2>
+      <p>
+        We'd like to measure which links and buttons readers click (the element type, its label
+        and a timestamp) to improve The DevTools Times. This uses a script hosted on Google Cloud
+        and is <strong>off unless you allow it</strong>. We never track the sign-in or sign-up
+        pages, and we don't use advertising or cross-site tracking cookies.
+      </p>
+      <p class="mt-1">
+        You can change your choice at any time via "Manage Privacy Preferences" in the footer.
+        <a href={`${baseUrl}legal/privacy`} class="underline">Read our Privacy Policy</a>.
+      </p>
+      <p data-gpc-note hidden class="mt-2 font-medium text-gray-900">
+        Your browser is sending a Global Privacy Control / Do Not Track signal, so analytics stays
+        off.
+      </p>
+    </div>
+    <div class="flex shrink-0 gap-2">
+      <button
+        type="button"
+        data-consent-reject
+        data-skip-tracking="true"
+        class="rounded-md border border-gray-900 px-4 py-2 text-sm font-medium text-gray-900 hover:bg-gray-100"
+      >
+        Reject analytics
+      </button>
+      <button
+        type="button"
+        data-consent-accept
+        data-skip-tracking="true"
+        class="rounded-md border border-gray-900 bg-gray-900 px-4 py-2 text-sm font-medium text-white hover:bg-gray-800 disabled:cursor-not-allowed disabled:opacity-50"
+      >
+        Allow analytics
+      </button>
+    </div>
+  </div>
+</div>
