+        caption = '1 more drink until your next free one.';
+      } else if (stamps / goal >= 0.5) {
+        headline = "You're almost there!";
+        caption = remaining + ' more drinks until your next free one.';
+      } else {
+        headline = "You're on your way!";
+        caption = remaining + ' more drinks until your next free one.';
