+      bar.style.strokeDasharray = circumference;
+      bar.style.strokeDashoffset = circumference;
+      bar.getBoundingClientRect();
+      requestAnimationFrame(function () {
+        bar.style.strokeDashoffset = circumference * (1 - stamps / goal);
+      });
+    })();
+  </script>
