+      <p class="fine-print">New here? <a href="/register">Create an account</a> &middot; <a href="/forgot-password">Forgot password?</a></p>
+    </form>
+  </dialog>
+
+  <script>
+    /*
+     * In-page sign-in for returning customers.
+     *
+     * 1. When a signed-out visitor clicks a protected link (Rewards, My Account, Order Now) or "Sign In",
+     *    we first ask the browser for a saved passkey OR password with `mediation: "immediate"`. Supporting
+     *    browsers show their own account picker right over the page; if nothing is saved they reject
+     *    immediately (NotAllowedError) without showing anything.
+     * 2. Otherwise we open an in-page <dialog> whose email field offers passkey autofill
+     *    (conditional mediation) and whose password field works with the password manager.
+     * 3. After sign-in, the original destination continues — no detour through a login page.
+     *
+     * Assumed backend endpoints (same origin):
+     *   GET  /api/auth/session     -> { signedIn: boolean, name?: string }
+     *   POST /api/auth/challenge   -> { challenge: base64url, rpId?: string, timeout?: number }
+     *   POST /api/auth/passkey     <- WebAuthn assertion JSON
+     *   POST /api/auth/password    <- { username, password }
+     *   POST /api/auth/logout
+     *   All sign-in endpoints respond { ok: true, name?: string } on success.
+     */
+    (() => {
+      const API = {
+        session: '/api/auth/session',
+        challenge: '/api/auth/challenge',
+        passkey: '/api/auth/passkey',
+        password: '/api/auth/password',
+        logout: '/api/auth/logout',
+      };
+
+      const $ = (id) => document.getElementById(id);
+      const dialog = $('signin-dialog');
+      const form = $('signin-form');
+      const errorEl = $('signin-error');
+      const submitBtn = $('signin-submit');
+      const passkeyBtn = $('passkey-button');
+
+      const state = { signedIn: false, name: '', pendingHref: null, conditionalAbort: null, busy: false };
+
+      // ---------- helpers ----------
+      const b64urlToBuf = (s) => {
+        const b64 = s.replace(/-/g, '+').replace(/_/g, '/').padEnd(Math.ceil(s.length / 4) * 4, '=');
+        return Uint8Array.from(atob(b64), (c) => c.charCodeAt(0)).buffer;
+      };
+      const bufToB64url = (buf) =>
+        btoa(String.fromCharCode(...new Uint8Array(buf))).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+
+      async function postJSON(url, body) {
+        const res = await fetch(url, {
+          method: 'POST',
+          credentials: 'same-origin',
+          headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
+          body: body === undefined ? undefined : JSON.stringify(body),
+        });
+        let data = {};
+        try { data = await res.json(); } catch { /* empty body */ }
+        if (!res.ok || data.ok === false) throw new Error(data.error || 'Sign-in failed. Please try again.');
+        return data;
+      }
+
+      async function getPublicKeyOptions() {
+        const { challenge, rpId, timeout } = await postJSON(API.challenge);
+        const options = { challenge: b64urlToBuf(challenge), userVerification: 'preferred', timeout: timeout || 60000 };
+        if (rpId) options.rpId = rpId;
+        return options;
+      }
+
+      function serializeAssertion(cred) {
+        if (typeof cred.toJSON === 'function') return cred.toJSON();
+        const r = cred.response;
+        return {
+          id: cred.id,
+          rawId: bufToB64url(cred.rawId),
+          type: cred.type,
+          authenticatorAttachment: cred.authenticatorAttachment || null,
+          clientExtensionResults: cred.getClientExtensionResults(),
+          response: {
+            clientDataJSON: bufToB64url(r.clientDataJSON),
+            authenticatorData: bufToB64url(r.authenticatorData),
+            signature: bufToB64url(r.signature),
+            userHandle: r.userHandle ? bufToB64url(r.userHandle) : null,
+          },
+        };
+      }
+
+      // Exchange whatever credential the browser returned for a session.
+      async function verifyCredential(cred) {
+        if (cred.type === 'public-key') return postJSON(API.passkey, serializeAssertion(cred));
+        if (cred.type === 'password') return postJSON(API.password, { username: cred.id, password: cred.password });
+        throw new Error('Unsupported credential type.');
+      }
