+      // ---------- capability detection ----------
+      const hasWebAuthn = 'PublicKeyCredential' in window && !!navigator.credentials;
+      let capabilitiesPromise = null;
+      function getCapabilities() {
+        if (!capabilitiesPromise) {
+          capabilitiesPromise = (async () => {
+            const caps = { immediate: false, conditional: false };
+            if (!hasWebAuthn) return caps;
+            try {
+              if (PublicKeyCredential.getClientCapabilities) {
+                const c = await PublicKeyCredential.getClientCapabilities();
+                caps.immediate = !!c.immediateGet;
+                caps.conditional = !!c.conditionalGet;
+              }
+              if (!caps.conditional && PublicKeyCredential.isConditionalMediationAvailable) {
+                caps.conditional = await PublicKeyCredential.isConditionalMediationAvailable();
+              }
+            } catch { /* treat as unsupported */ }
+            return caps;
+          })();
+        }
+        return capabilitiesPromise;
+      }
+
+      // ---------- UI state ----------
+      function renderAuthState() {
+        document.querySelectorAll('[data-auth]').forEach((el) => {
+          el.hidden = (el.dataset.auth === 'signed-in') !== state.signedIn;
+        });
+        $('greeting').textContent = state.signedIn ? `Hi, ${state.name || 'friend'}` : '';
+      }
+
+      function onSignedIn(data) {
+        state.signedIn = true;
+        state.name = (data && data.name) || state.name;
+        renderAuthState();
+        closeDialog();
+        const href = state.pendingHref;
+        state.pendingHref = null;
+        if (href) window.location.assign(href);
+      }
+
+      // ---------- sign-in flow ----------
+      async function trySignIn(href, contextMessage) {
+        if (state.busy) return;
+        state.busy = true;
+        state.pendingHref = href;
+        try {
+          const caps = await getCapabilities();
+          if (caps.immediate) {
+            try {
+              // Browser shows its own sheet with saved passkeys and passwords, in place.
+              const cred = await navigator.credentials.get({
+                mediation: 'immediate',
+                password: true,
+                publicKey: await getPublicKeyOptions(),
+              });
+              if (cred) {
+                onSignedIn(await verifyCredential(cred));
+                return;
+              }
+            } catch (err) {
+              // NotAllowedError: no saved credentials or user dismissed — fall through to the dialog.
+              if (err.name !== 'NotAllowedError' && err.name !== 'AbortError') console.warn('Immediate sign-in failed:', err);
+            }
+          }
+          openDialog(contextMessage);
+        } finally {
+          state.busy = false;
+        }
+      }
+
+      async function startConditionalPasskeyAutofill() {
+        const caps = await getCapabilities();
+        if (!caps.conditional) return;
+        stopConditional();
+        const controller = new AbortController();
+        state.conditionalAbort = controller;
+        try {
+          const cred = await navigator.credentials.get({
+            mediation: 'conditional',
+            publicKey: await getPublicKeyOptions(),
+            signal: controller.signal,
+          });
+          if (cred) onSignedIn(await verifyCredential(cred));
+        } catch (err) {
+          if (err.name !== 'AbortError' && err.name !== 'NotAllowedError') showError(err.message);
+        }
+      }
+
+      function stopConditional() {
+        if (state.conditionalAbort) {
+          state.conditionalAbort.abort();
+          state.conditionalAbort = null;
+        }
+      }
+
+      function showError(msg) { errorEl.textContent = msg || ''; }
+
+      function openDialog(contextMessage) {
+        $('signin-context').textContent = contextMessage || 'Sign in to continue.';
+        showError('');
+        form.reset();
+        if (!dialog.open) dialog.showModal();
+        $('signin-username').focus();
+        startConditionalPasskeyAutofill();
+      }
+
+      function closeDialog() {
+        stopConditional();
+        if (dialog.open) dialog.close();
+      }
+
+      // Modal passkey button (for browsers with WebAuthn but no autofill UI).
+      getCapabilities().then(() => {
+        if (hasWebAuthn) {
+          passkeyBtn.hidden = false;
+          $('passkey-divider').hidden = false;
+        }
+      });
+
+      passkeyBtn.addEventListener('click', async () => {
+        stopConditional(); // only one WebAuthn request may be pending at a time
+        showError('');
+        passkeyBtn.disabled = true;
+        try {
+          const cred = await navigator.credentials.get({ publicKey: await getPublicKeyOptions() });
+          if (cred) onSignedIn(await verifyCredential(cred));
+        } catch (err) {
+          if (err.name !== 'NotAllowedError' && err.name !== 'AbortError') showError(err.message);
+          else startConditionalPasskeyAutofill();
+        } finally {
+          passkeyBtn.disabled = false;
+        }
+      });
+
+      form.addEventListener('submit', async (e) => {
+        e.preventDefault();
+        const username = form.username.value.trim();
+        const password = form.password.value;
+        if (!username || !password) {
+          showError('Please enter your email and password.');
+          return;
+        }
+        showError('');
+        submitBtn.disabled = true;
+        try {
+          const data = await postJSON(API.password, { username, password });
+          // Offer to save/update the password in the browser's password manager.
+          if ('PasswordCredential' in window) {
+            try { await navigator.credentials.store(new PasswordCredential({ id: username, password })); } catch { /* optional */ }
+          }
+          onSignedIn(data);
+        } catch (err) {
+          showError(err.message);
+          form.password.select();
+        } finally {
+          submitBtn.disabled = false;
+        }
+      });
+
+      $('signin-close').addEventListener('click', () => { state.pendingHref = null; closeDialog(); });
+      dialog.addEventListener('cancel', () => { state.pendingHref = null; stopConditional(); });
+      dialog.addEventListener('click', (e) => { if (e.target === dialog) { state.pendingHref = null; closeDialog(); } });
+
+      // ---------- link interception ----------
+      document.addEventListener('click', (e) => {
+        const link = e.target.closest('a[data-requires-auth]');
+        if (!link || state.signedIn) return;
+        if (e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
+        e.preventDefault();
+        trySignIn(link.href, link.dataset.requiresAuth);
+      });
+
+      $('signin-button').addEventListener('click', () => trySignIn(null, 'Sign in to your Daily Grind account.'));
+
+      $('logout-link').addEventListener('click', async (e) => {
+        e.preventDefault();
+        try { await postJSON(API.logout); } catch { /* clear local state regardless */ }
+        if (navigator.credentials && navigator.credentials.preventSilentAccess) {
+          try { await navigator.credentials.preventSilentAccess(); } catch { /* ignore */ }
+        }
+        state.signedIn = false;
+        state.name = '';
+        renderAuthState();
+      });
+
+      // ---------- initial session check ----------
+      (async () => {
+        try {
+          const res = await fetch(API.session, { credentials: 'same-origin', headers: { Accept: 'application/json' } });
+          if (res.ok) {
+            const data = await res.json();
+            state.signedIn = !!data.signedIn;
+            state.name = data.name || '';
+          }
+        } catch { /* assume signed out */ }
+        renderAuthState();
+      })();
+
+      renderAuthState();
+      getCapabilities();
+    })();
+  </script>
+
