@@ -0,0 +1,76 @@
+// Newsletter signup: progressively enhances the <form> so it submits via fetch()
+// and shows the customer a clear message when the request can't go through
+// (offline, server error, or blocked by the page's outbound-connection policy).
+const form = document.getElementById('newsletter-form');
+
+if (form) {
+  const input = form.elements.namedItem('email');
+  const button = form.querySelector('button[type="submit"]');
+  const status = document.getElementById('newsletter-status');
+
+  const setStatus = (state, message) => {
+    status.dataset.state = state;
+    status.textContent = message;
+  };
+
+  // Clear errors while the user is fixing them; don't validate on every keystroke.
+  input.addEventListener('input', () => {
+    input.removeAttribute('aria-invalid');
+    if (status.dataset.state === 'error') setStatus('', '');
+  });
+
+  form.addEventListener('submit', async (event) => {
+    event.preventDefault();
+
+    if (!form.checkValidity()) {
+      input.setAttribute('aria-invalid', 'true');
+      setStatus('error', 'Please enter a valid email address, like name@example.com.');
+      input.focus();
+      return;
+    }
+
+    button.disabled = true;
+    setStatus('pending', 'Signing you up…');
+
+    try {
+      const response = await fetch(form.action, {
+        method: 'POST',
+        headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
+        body: JSON.stringify({ email: input.value.trim() }),
+        // Our own server never redirects this endpoint; treat any redirect as a failure.
+        redirect: 'error',
+      });
+
+      let data = null;
+      try {
+        data = await response.json();
+      } catch {
+        // Non-JSON body; fall through to the generic message below.
+      }
+
+      if (!response.ok) {
+        const message =
+          (data && typeof data.error === 'string' && data.error) ||
+          'Sorry, we couldn’t sign you up right now. Please try again in a few minutes.';
+        if (response.status === 400) input.setAttribute('aria-invalid', 'true');
+        setStatus('error', message);
+        return;
+      }
+
+      form.reset();
+      setStatus('success', 'Thanks! You’re on the list. Watch your inbox for our next brew.');
+    } catch (error) {
+      // fetch() rejects with a TypeError when the network is down or the request
+      // was blocked by Connection-Allowlist / Content-Security-Policy.
+      console.error('Newsletter signup request failed:', error);
+      setStatus(
+        'error',
+        navigator.onLine === false
+          ? 'You appear to be offline. Please check your connection and try again.'
+          : 'We couldn’t reach our server to complete your signup. Please try again later.',
+      );
+    } finally {
+      button.disabled = false;
+    }
+  });
+}
