@@ -0,0 +1,219 @@
+// Daily Grind homepage server.
+//
+// Serves the static homepage and the newsletter signup endpoint, and attaches
+// response headers that restrict the page to talking only to this server and
+// the Unsplash image host, so an injected script cannot exfiltrate customer data.
+import { createServer } from 'node:http';
+import { readFile, appendFile, mkdir } from 'node:fs/promises';
+import { fileURLToPath } from 'node:url';
+import path from 'node:path';
+
+const ROOT = path.dirname(fileURLToPath(import.meta.url));
+const PUBLIC_DIR = path.join(ROOT, 'public');
+const DATA_DIR = path.join(ROOT, 'data');
+const SUBSCRIBERS_FILE = path.join(DATA_DIR, 'subscribers.jsonl');
+const PORT = Number(process.env.PORT) || 11222;
+const MAX_BODY_BYTES = 4 * 1024;
+
+// The only external origin the page may contact.
+const UNSPLASH_IMAGES = 'https://images.unsplash.com';
+const REPORT_ENDPOINT_NAME = 'security';
+const REPORT_PATH = '/api/security-reports';
+
+// Static files are served from an explicit list, never from arbitrary paths.
+const STATIC_FILES = new Map([
+  ['/', { file: 'index.html', type: 'text/html; charset=utf-8' }],
+  ['/index.html', { file: 'index.html', type: 'text/html; charset=utf-8' }],
+  ['/styles.css', { file: 'styles.css', type: 'text/css; charset=utf-8' }],
+  ['/newsletter.js', { file: 'newsletter.js', type: 'text/javascript; charset=utf-8' }],
+]);
+
+// Content-Security-Policy: works in every modern browser. No inline script/style
+// is allowed, fetch()/XHR/beacons/WebSockets may only reach this origin, images
+// may only come from this origin or Unsplash, and forms may only post here.
+const CSP = [
+  "default-src 'none'",
+  "script-src 'self'",
+  "style-src 'self'",
+  `img-src 'self' ${UNSPLASH_IMAGES}`,
+  "connect-src 'self'",
+  "form-action 'self'",
+  "worker-src 'none'",
+  "frame-src 'none'",
+  "object-src 'none'",
+  "base-uri 'none'",
+  "frame-ancestors 'none'",
+  "require-trusted-types-for 'script'",
+  "trusted-types 'none'",
+  `report-to ${REPORT_ENDPOINT_NAME}`,
+].join('; ');
+
+// Connection-Allowlist: network-layer allowlist (Chrome/Edge 152+) that also covers
+// channels CSP misses — preconnect/dns-prefetch, WebRTC, and navigations. Redirects
+// and WebRTC are blocked by default. Must be a valid RFC 9651 inner list, otherwise
+// the browser fails closed and blocks everything.
+const CONNECTION_ALLOWLIST = `(response-origin "${UNSPLASH_IMAGES}"); report-to=${REPORT_ENDPOINT_NAME}`;
+
+// Applied to every response.
+function setBaseHeaders(res) {
+  res.setHeader('X-Content-Type-Options', 'nosniff');
+  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
+  res.setHeader('Cross-Origin-Opener-Policy', 'same-origin');
+  res.setHeader('Cross-Origin-Resource-Policy', 'same-origin');
+  res.setHeader('Vary', 'Sec-Fetch-Dest');
+}
+
+// Applied to HTML documents (Connection-Allowlist is only honored on documents/workers).
+function setDocumentHeaders(res) {
+  res.setHeader('Reporting-Endpoints', `${REPORT_ENDPOINT_NAME}="${REPORT_PATH}"`);
+  res.setHeader('Content-Security-Policy', CSP);
+  res.setHeader('Connection-Allowlist', CONNECTION_ALLOWLIST);
+  res.setHeader('Permissions-Policy', 'camera=(), microphone=(), geolocation=(), payment=()');
+}
+
+function sendJson(res, status, body) {
+  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
+  res.end(JSON.stringify(body));
+}
+
+const escapeHtml = (s) =>
+  s.replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
+
+// No-JS fallback for the newsletter form: a minimal page under the same policy.
+function sendHtmlMessage(res, status, message) {
+  setDocumentHeaders(res);
+  res.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' });
+  res.end(`<!DOCTYPE html>
+<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0">
+<title>Newsletter | The Daily Grind</title><link rel="stylesheet" href="/styles.css"></head>
+<body><main class="container"><section class="newsletter"><p>${escapeHtml(message)}</p>
+<a class="btn" href="/">Back to the homepage</a></section></main></body></html>`);
+}
+
+class HttpError extends Error {
+  constructor(status, message) {
+    super(message);
+    this.status = status;
+  }
+}
+
+async function readBody(req) {
+  const chunks = [];
+  let size = 0;
+  for await (const chunk of req) {
+    size += chunk.length;
+    if (size > MAX_BODY_BYTES) throw new HttpError(413, 'Request is too large.');
+    chunks.push(chunk);
+  }
+  return Buffer.concat(chunks).toString('utf8');
+}
+
+// Pragmatic email check; the browser's type="email" validation is the first line.
+const EMAIL_RE = /^[^\s@<>()[\]\\,;:"]+@[^\s@<>()[\]\\,;:"]+\.[^\s@<>()[\]\\,;:"]{2,}$/;
+
+async function handleNewsletter(req, res) {
+  const contentType = (req.headers['content-type'] || '').split(';')[0].trim().toLowerCase();
+  const wantsJson = contentType === 'application/json';
+  const fail = (status, message) =>
+    wantsJson ? sendJson(res, status, { error: message }) : sendHtmlMessage(res, status, message);
+
+  // Reject cross-site submissions (CSRF) when the browser tells us the origin.
+  const site = req.headers['sec-fetch-site'];
+  if (site && site !== 'same-origin' && site !== 'none') {
+    return fail(403, 'This request was not allowed.');
+  }
+
+  let email;
+  try {
+    const raw = await readBody(req);
+    if (wantsJson) {
+      email = JSON.parse(raw)?.email;
+    } else if (contentType === 'application/x-www-form-urlencoded') {
+      email = new URLSearchParams(raw).get('email');
+    } else {
+      return fail(415, 'Unsupported request format.');
+    }
+  } catch (err) {
+    if (err instanceof HttpError) return fail(err.status, err.message);
+    return fail(400, 'We couldn’t read that request. Please try again.');
+  }
+
+  email = typeof email === 'string' ? email.trim().toLowerCase() : '';
+  if (email.length > 254 || !EMAIL_RE.test(email)) {
+    return fail(400, 'Please enter a valid email address, like name@example.com.');
+  }
+
+  try {
+    await mkdir(DATA_DIR, { recursive: true });
+    await appendFile(SUBSCRIBERS_FILE, JSON.stringify({ email, subscribedAt: new Date().toISOString() }) + '\n');
+  } catch (err) {
+    console.error('Failed to store subscriber:', err);
+    return fail(500, 'Sorry, we couldn’t sign you up right now. Please try again in a few minutes.');
+  }
+
+  return wantsJson
+    ? sendJson(res, 201, { ok: true })
+    : sendHtmlMessage(res, 201, 'Thanks! You’re on the list. Watch your inbox for our next brew.');
+}
+
+async function handleSecurityReport(req, res) {
+  try {
+    const raw = await readBody(req);
+    console.warn('[security report]', raw);
+  } catch {
+    // Ignore oversized/malformed reports.
+  }
+  res.writeHead(204);
+  res.end();
+}
+
+async function handleStatic(req, res, pathname) {
+  const entry = STATIC_FILES.get(pathname);
+  if (!entry) {
+    res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
+    return res.end('Not found');
+  }
+  const body = await readFile(path.join(PUBLIC_DIR, entry.file));
+  if (entry.type.startsWith('text/html')) setDocumentHeaders(res);
+  res.writeHead(200, { 'Content-Type': entry.type, 'Cache-Control': 'no-cache' });
+  res.end(req.method === 'HEAD' ? undefined : body);
+}
+
+const server = createServer(async (req, res) => {
+  setBaseHeaders(res);
+  try {
+    const { pathname } = new URL(req.url, 'http://localhost');
+
+    if (pathname === '/api/newsletter') {
+      if (req.method !== 'POST') {
+        res.setHeader('Allow', 'POST');
+        return sendJson(res, 405, { error: 'Method not allowed.' });
+      }
+      return await handleNewsletter(req, res);
+    }
+
+    if (pathname === REPORT_PATH) {
+      if (req.method !== 'POST') {
+        res.setHeader('Allow', 'POST');
+        res.writeHead(405);
+        return res.end();
+      }
+      return await handleSecurityReport(req, res);
+    }
+
+    if (req.method !== 'GET' && req.method !== 'HEAD') {
+      res.setHeader('Allow', 'GET, HEAD');
+      res.writeHead(405);
+      return res.end();
+    }
+    return await handleStatic(req, res, pathname);
+  } catch (err) {
+    console.error(err);
+    if (!res.headersSent) res.writeHead(500, { 'Content-Type': 'text/plain; charset=utf-8' });
+    res.end('Internal server error');
+  }
+});
+
+server.listen(PORT, () => {
+  console.log(`Daily Grind listening on http://localhost:${PORT}`);
+});

