+'use strict';
+
+(function () {
+  var form = document.getElementById('newsletter-form');
+  var status = document.getElementById('newsletter-status');
+  if (!form || !status) return;
+
+  var input = form.querySelector('input[name="email"]');
+  var button = form.querySelector('button[type="submit"]');
+  var EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+  var BLOCKED_MSG =
+    "Sorry, we couldn't send your request. It was blocked by this page's security settings. " +
+    'Please refresh the page and try again, or contact us if the problem continues.';
+  var NETWORK_MSG =
+    "Sorry, we couldn't reach our server. Please check your connection and try again.";
+
+  function show(message, kind) {
+    status.textContent = message;
+    status.className = 'newsletter-status ' + kind;
+    status.hidden = false;
+  }
+
+  // Track Content-Security-Policy blocks so customers get a clear message
+  // instead of a silent failure when a request isn't allowed to go out.
+  var lastViolation = null;
+  document.addEventListener('securitypolicyviolation', function (e) {
+    lastViolation = e;
+    if (e.effectiveDirective === 'connect-src' || e.effectiveDirective === 'form-action') {
+      show(BLOCKED_MSG, 'error');
+    }
+  });
+
+  // Show a result passed back from the no-JavaScript form fallback.
+  var params = new URLSearchParams(window.location.search);
+  if (params.get('newsletter') === 'subscribed') {
+    show("Thanks! You're on the list.", 'success');
+  } else if (params.get('newsletter') === 'error') {
+    show("Sorry, we couldn't sign you up. Please check your email address and try again.", 'error');
+  }
+
+  form.addEventListener('submit', function (event) {
+    event.preventDefault();
+
+    var email = input.value.trim();
+    if (!EMAIL_RE.test(email) || email.length > 254) {
+      show('Please enter a valid email address.', 'error');
+      input.focus();
+      return;
+    }
+
+    button.disabled = true;
+    lastViolation = null;
+    show('Signing you up…', 'pending');
+
+    var controller = new AbortController();
+    var timer = setTimeout(function () { controller.abort(); }, 10000);
+
+    fetch('/api/newsletter', {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
+      body: JSON.stringify({ email: email }),
+      credentials: 'same-origin',
+      signal: controller.signal
+    })
+      .then(function (res) {
+        return res.json().catch(function () { return {}; }).then(function (data) {
+          if (res.ok) {
+            show(data.message || "Thanks! You're on the list.", 'success');
+            form.reset();
+          } else if (res.status === 429) {
+            show('Too many attempts. Please wait a minute and try again.', 'error');
+          } else {
+            show(data.error || 'Sorry, something went wrong on our end. Please try again later.', 'error');
+          }
+        });
+      })
+      .catch(function (err) {
+        if (err && err.name === 'AbortError') {
+          show('Our server is taking too long to respond. Please try again in a moment.', 'error');
+        } else if (lastViolation) {
+          show(BLOCKED_MSG, 'error');
+        } else {
+          show(NETWORK_MSG, 'error');
+        }
+      })
+      .finally(function () {
+        clearTimeout(timer);
+        button.disabled = false;
+      });
+  });
+})();
