+'use strict';
+
+const http = require('node:http');
+const fs = require('node:fs');
+const path = require('node:path');
+
+const PORT = Number(process.env.PORT) || 11222;
+const PUBLIC_DIR = path.join(__dirname, 'public');
+const DATA_DIR = process.env.DATA_DIR || path.join(__dirname, 'data');
+const SUBSCRIBERS_FILE = path.join(DATA_DIR, 'subscribers.jsonl');
+const MAX_BODY_BYTES = 2 * 1024;
+const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+
+// Only our own origin and the Unsplash photo host are reachable from the page.
+// Scripts and styles are same-origin files only (no inline code, no eval), so an
+// injected <script> or inline handler won't run, and fetch/XHR/WebSocket/beacon
+// (connect-src), form posts (form-action), images (img-src), frames, workers,
+// fonts, media, etc. can only talk to 'self' (+ images.unsplash.com for images).
+const CSP = [
+  "default-src 'none'",
+  "script-src 'self'",
+  "style-src 'self'",
+  "img-src 'self' https://images.unsplash.com",
+  "font-src 'self'",
+  "connect-src 'self'",
+  "media-src 'none'",
+  "object-src 'none'",
+  "frame-src 'none'",
+  "child-src 'none'",
+  "worker-src 'none'",
+  "manifest-src 'self'",
+  "form-action 'self'",
+  "base-uri 'none'",
+  "frame-ancestors 'none'",
+  'report-uri /api/csp-report',
+].join('; ');
+
+const SECURITY_HEADERS = {
+  'Content-Security-Policy': CSP,
+  'X-Content-Type-Options': 'nosniff',
+  'Referrer-Policy': 'same-origin',
+  'X-Frame-Options': 'DENY',
+  'Cross-Origin-Opener-Policy': 'same-origin',
+  'Cross-Origin-Resource-Policy': 'same-origin',
+  'X-DNS-Prefetch-Control': 'off',
+  'Permissions-Policy': 'camera=(), microphone=(), geolocation=(), payment=(), usb=()',
+};
+
+// Explicit allow-list of static files: nothing else on disk can be requested.
+const STATIC_FILES = {
+  '/': { file: 'index.html', type: 'text/html; charset=utf-8', cache: 'no-cache' },
+  '/index.html': { file: 'index.html', type: 'text/html; charset=utf-8', cache: 'no-cache' },
+  '/styles.css': { file: 'styles.css', type: 'text/css; charset=utf-8', cache: 'public, max-age=300' },
+  '/app.js': { file: 'app.js', type: 'text/javascript; charset=utf-8', cache: 'public, max-age=300' },
+};
+
+function send(res, status, body, headers = {}) {
+  res.writeHead(status, { ...SECURITY_HEADERS, ...headers });
+  res.end(body);
+}
+
+function sendJson(res, status, obj) {
+  send(res, status, JSON.stringify(obj), {
+    'Content-Type': 'application/json; charset=utf-8',
+    'Cache-Control': 'no-store',
+  });
+}
+
+function readBody(req) {
+  return new Promise((resolve, reject) => {
+    let size = 0;
+    const chunks = [];
+    req.on('data', (chunk) => {
+      size += chunk.length;
+      if (size > MAX_BODY_BYTES) {
+        reject(Object.assign(new Error('Payload too large'), { status: 413 }));
+        req.destroy();
+        return;
+      }
+      chunks.push(chunk);
+    });
+    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
+    req.on('error', reject);
+  });
+}
+
+// Basic per-IP rate limit for the signup endpoint.
+const RATE_WINDOW_MS = 60 * 1000;
+const RATE_MAX = 5;
+const hits = new Map();
+function rateLimited(ip) {
+  const now = Date.now();
+  const entry = hits.get(ip);
+  if (!entry || now - entry.start > RATE_WINDOW_MS) {
+    hits.set(ip, { start: now, count: 1 });
+    return false;
+  }
+  entry.count += 1;
+  return entry.count > RATE_MAX;
+}
+setInterval(() => {
+  const now = Date.now();
+  for (const [ip, entry] of hits) if (now - entry.start > RATE_WINDOW_MS) hits.delete(ip);
+}, RATE_WINDOW_MS).unref();
+
+async function saveSubscriber(email) {
+  await fs.promises.mkdir(DATA_DIR, { recursive: true });
+  const line = JSON.stringify({ email, subscribedAt: new Date().toISOString() }) + '\n';
+  await fs.promises.appendFile(SUBSCRIBERS_FILE, line, { mode: 0o600 });
+}
+
+async function handleNewsletter(req, res) {
+  const contentType = (req.headers['content-type'] || '').split(';')[0].trim().toLowerCase();
+  const isForm = contentType === 'application/x-www-form-urlencoded';
+  const isJson = contentType === 'application/json';
+
+  // Plain HTML form fallback (no JavaScript): redirect back with a result flag.
+  const finish = (status, ok, message) => {
+    if (isForm) {
+      send(res, 303, '', { Location: `/?newsletter=${ok ? 'subscribed' : 'error'}#newsletter-title` });
+    } else {
+      sendJson(res, status, ok ? { ok: true, message } : { ok: false, error: message });
+    }
+  };
+
+  if (!isForm && !isJson) {
+    return sendJson(res, 415, { ok: false, error: 'Unsupported request format.' });
+  }
+
+  // Reject cross-site posts: only our own page may submit.
+  const origin = req.headers.origin;
+  if (origin && origin !== `http://${req.headers.host}` && origin !== `https://${req.headers.host}`) {
+    return finish(403, false, 'This request is not allowed.');
+  }
+
+  if (rateLimited(req.socket.remoteAddress || 'unknown')) {
+    return finish(429, false, 'Too many attempts. Please wait a minute and try again.');
+  }
+
+  let raw;
+  try {
+    raw = await readBody(req);
+  } catch (err) {
+    return finish(err.status || 400, false, 'Your request could not be read. Please try again.');
+  }
+
+  let email;
+  try {
+    email = isJson ? JSON.parse(raw).email : new URLSearchParams(raw).get('email');
+  } catch {
+    return finish(400, false, 'Your request could not be read. Please try again.');
+  }
+
+  email = typeof email === 'string' ? email.trim().toLowerCase() : '';
+  if (!email || email.length > 254 || !EMAIL_RE.test(email)) {
+    return finish(400, false, 'Please enter a valid email address.');
+  }
+
+  try {
+    await saveSubscriber(email);
+  } catch (err) {
+    console.error('Failed to save subscriber:', err);
+    return finish(500, false, "Sorry, we couldn't sign you up right now. Please try again later.");
+  }
+
+  return finish(201, true, "Thanks! You're on the list.");
+}
+
+async function handleCspReport(req, res) {
+  try {
+    const raw = await readBody(req);
+    console.warn('CSP violation report:', raw.slice(0, 1000));
+  } catch {
+    /* ignore oversized/broken reports */
+  }
+  send(res, 204, '');
+}
+
+function serveStatic(req, res, pathname) {
+  const entry = STATIC_FILES[pathname];
+  if (!entry) {
+    return send(res, 404, 'Not found', { 'Content-Type': 'text/plain; charset=utf-8' });
+  }
+  fs.readFile(path.join(PUBLIC_DIR, entry.file), (err, data) => {
+    if (err) {
+      console.error(err);
+      return send(res, 500, 'Internal server error', { 'Content-Type': 'text/plain; charset=utf-8' });
+    }
+    send(res, 200, req.method === 'HEAD' ? '' : data, {
+      'Content-Type': entry.type,
+      'Content-Length': data.length,
+      'Cache-Control': entry.cache,
+    });
+  });
+}
+
+const server = http.createServer(async (req, res) => {
+  let pathname;
+  try {
+    pathname = new URL(req.url, 'http://localhost').pathname;
+  } catch {
+    return send(res, 400, 'Bad request', { 'Content-Type': 'text/plain; charset=utf-8' });
+  }
+
+  try {
+    if (pathname === '/api/newsletter') {
+      if (req.method !== 'POST') return sendJson(res, 405, { ok: false, error: 'Method not allowed.' });
+      return await handleNewsletter(req, res);
+    }
+    if (pathname === '/api/csp-report') {
+      if (req.method !== 'POST') return send(res, 405, '');
+      return await handleCspReport(req, res);
+    }
+    if (req.method !== 'GET' && req.method !== 'HEAD') {
+      return send(res, 405, 'Method not allowed', { 'Content-Type': 'text/plain; charset=utf-8', Allow: 'GET, HEAD' });
+    }
+    return serveStatic(req, res, pathname);
+  } catch (err) {
+    console.error(err);
+    if (!res.headersSent) sendJson(res, 500, { ok: false, error: 'Internal server error.' });
+  }
+});
+
+if (require.main === module) {
+  server.listen(PORT, () => console.log(`The Daily Grind running on http://localhost:${PORT}`));
+}
+
+module.exports = { server, CSP };

