+/*
+ * Customer reviews for the Seasonal Favorites section.
+ *
+ * Reviews are untrusted, user-supplied HTML. They are stored raw and
+ * sanitized at render time on every display, so tightening the allowlist
+ * below retroactively protects previously stored reviews too.
+ *
+ * Sanitization strategy:
+ *   1. Parse the markup with DOMParser into an inert document (scripts do not
+ *      execute, images/resources do not load, event handlers never fire).
+ *   2. Walk the parsed tree and REBUILD a brand-new fragment in the live
+ *      document, copying only allowlisted elements and attributes and creating
+ *      text via createTextNode. Nothing from the parsed tree is moved or
+ *      re-serialized to a string and re-parsed, which avoids mutation-XSS
+ *      (mXSS) tricks that rely on parse/serialize round trips.
+ *   3. The resulting fragment is appended with DOM APIs — innerHTML is never
+ *      used with user content.
+ */
+(function () {
+  'use strict';
+
+  var STORAGE_KEY = 'dailyGrind.reviews.v1';
+  var MAX_BODY_LENGTH = 2000;
+  var MAX_AUTHOR_LENGTH = 40;
+  var MAX_DEPTH = 20;
+  var DRINKS = ['Maple Oat Latte', 'Dark Roast Espresso', 'Cold Brew'];
+
+  // Elements that are kept (with their children).
+  var ALLOWED_TAGS = {
+    B: true, STRONG: true, I: true, EM: true, U: true, S: true,
+    P: true, BR: true, UL: true, OL: true, LI: true,
+    BLOCKQUOTE: true, CODE: true, PRE: true, SPAN: true, A: true
+  };
+
+  // Attributes allowed per element. Everything else (on*, style, class, id,
+  // src, srcset, formaction, xlink:href, etc.) is dropped.
+  var ALLOWED_ATTRS = {
+    A: { href: true, title: true }
+  };
+
+  // Elements that are removed entirely, including all of their contents.
+  // Any other non-allowlisted element is "unwrapped": the tag is dropped but
+  // its (sanitized) children are kept, so e.g. <div>hi</div> becomes "hi".
+  var DROP_WITH_CONTENT = {
+    SCRIPT: true, STYLE: true, IFRAME: true, FRAME: true, FRAMESET: true,
+    OBJECT: true, EMBED: true, APPLET: true, SVG: true, MATH: true,
+    TEMPLATE: true, NOSCRIPT: true, NOEMBED: true, NOFRAMES: true,
+    TEXTAREA: true, SELECT: true, OPTION: true, BUTTON: true, INPUT: true,
+    FORM: true, LINK: true, META: true, BASE: true, TITLE: true, HEAD: true,
+    XMP: true, PLAINTEXT: true, IMG: true, PICTURE: true, VIDEO: true,
+    AUDIO: true, SOURCE: true, TRACK: true, CANVAS: true, PORTAL: true
+  };
+
+  var SAFE_URL_PROTOCOLS = { 'http:': true, 'https:': true, 'mailto:': true };
+
+  function sanitizeUrl(value) {
+    // Strip whitespace/control characters that browsers ignore inside schemes
+    // (e.g. "java\tscript:"), then resolve and check the protocol.
+    var cleaned = String(value).replace(/[\u0000- \u007F-\u009F]/g, '');
+    if (!cleaned) return null;
+    var url;
+    try {
+      url = new URL(cleaned, window.location.href);
+    } catch (e) {
+      return null;
+    }
+    return SAFE_URL_PROTOCOLS[url.protocol] ? url.href : null;
+  }
+
+  function sanitizeNode(source, depth) {
+    var out = document.createDocumentFragment();
+    if (depth > MAX_DEPTH) return out;
+
+    var children = source.childNodes;
+    for (var i = 0; i < children.length; i++) {
+      var node = children[i];
+
+      if (node.nodeType === Node.TEXT_NODE) {
+        out.appendChild(document.createTextNode(node.nodeValue));
+        continue;
+      }
+      if (node.nodeType !== Node.ELEMENT_NODE) {
+        continue; // comments, processing instructions, CDATA, etc.
+      }
+      // Only accept plain HTML-namespace elements (rejects SVG/MathML content
+      // that could be hoisted in via namespace confusion).
