+    {
+      drink: 'Maple Oat Latte', author: 'Priya', rating: 5, date: '2026-11-02',
+      body: '<b>Autumn in a cup!</b> The maple is <i>subtle</i>, not syrupy.'
+    },
+    {
+      drink: 'Dark Roast Espresso', author: 'Marco', rating: 4, date: '2026-11-10',
+      body: '<p>Rich and bold.</p><ul><li>Great crema</li><li>A bit smoky for some</li></ul>'
+    },
+    {
+      drink: 'Cold Brew', author: 'Sam', rating: 5, date: '2026-11-15',
+      body: '<blockquote>Smoothest cold brew in town.</blockquote> Worth the 18 hours.'
+    }
+  ];
