+    for (var i = 0; i < lists.length; i++) {
+      var list = lists[i];
+      var drink = list.getAttribute('data-review-list');
+      list.replaceChildren();
+
+      var matching = reviews.filter(function (r) { return r && r.drink === drink; });
+      if (!matching.length) {
+        var empty = document.createElement('li');
+        empty.className = 'review-empty';
+        empty.textContent = 'No reviews yet — be the first!';
+        list.appendChild(empty);
+        continue;
+      }
+      // Newest first.
+      for (var j = matching.length - 1; j >= 0; j--) {
+        list.appendChild(renderReview(matching[j]));
