+                log(task.type, `Started #${task.id} after ${Math.round(task.startedAt - task.queuedAt)} ms wait`);
+              } else {
+                log(task.type, `Resumed #${task.id}`);
+              }
+            }
+
+            busyWork(CHUNK_MS);
+            task.doneChunks++;
+            task.bar.style.width = (task.doneChunks / task.total * 100) + '%';
+
+            if (task.doneChunks >= task.total) finish(task);
+
+            // Yield so input, rendering and newly queued urgent work can get in.
+            await yieldToMain(PRIORITIES[task.type].schedulerPriority);
+          }
+        } finally {
+          running = false;
+          current = null;
+        }
+      }
+
+      function finish(task) {
+        queue.splice(queue.indexOf(task), 1);
+        completed++;
+        const total = Math.round(performance.now() - task.queuedAt);
+        log(task.type, `Completed #${task.id} ${task.name} (${total} ms total)`);
+        task.el.remove();
+        current = null;
+        updateCounts();
+      }
+
+      // ----- Rendering -----
+      function renderTask(task) {
+        const li = document.createElement('li');
+        li.className = `ops-task p-${task.type}`;
+        const head = document.createElement('div');
+        head.className = 'ops-task-head';
+        const name = document.createElement('span');
+        name.textContent = `#${task.id} ${task.name}`;
+        const badge = document.createElement('span');
+        badge.className = 'ops-badge';
+        badge.textContent = PRIORITIES[task.type].label;
+        head.append(name, badge);
+        const progress = document.createElement('div');
+        progress.className = 'ops-progress';
+        const bar = document.createElement('div');
+        progress.append(bar);
+        li.append(head, progress);
+        task.el = li;
+        task.bar = bar;
