+        // Keep the DOM list in priority order too.
+        const siblings = [...els.queue.querySelectorAll('.ops-task')];
+        const before = siblings.find((el) => {
+          const other = queue.find((t) => t.el === el);
+          return other && (other.rank > task.rank);
+        });
+        els.queue.insertBefore(li, before || null);
+        updateEmpty();
+      }
+
+      function updateEmpty() {
+        const empty = els.queue.querySelector('.ops-empty');
+        if (queue.length === 0 && !empty) {
+          const li = document.createElement('li');
+          li.className = 'ops-empty';
+          li.textContent = 'Queue is idle';
+          els.queue.append(li);
+        } else if (queue.length > 0 && empty) {
+          empty.remove();
+        }
+      }
+
+      function updateCounts() {
+        els.pending.textContent = queue.length;
+        els.done.textContent = completed;
+        updateEmpty();
+      }
+
+      const MAX_LOG = 200;
+      function log(level, msg) {
+        const li = document.createElement('li');
+        li.className = `lvl-${level}`;
+        const t = new Date().toLocaleTimeString([], { hour12: false });
+        li.textContent = `[${t}] ${msg}`;
+        els.log.prepend(li);
+        while (els.log.children.length > MAX_LOG) els.log.lastChild.remove();
+      }
+
+      // ----- Responsiveness monitor -----
+      let lastFrame = performance.now();
+      let worstGap = 0;
+      let windowStart = lastFrame;
+      function frame(now) {
+        worstGap = Math.max(worstGap, now - lastFrame);
+        lastFrame = now;
+        if (now - windowStart > 1000) {
+          els.frame.textContent = Math.round(worstGap);
+          worstGap = 0;
+          windowStart = now;
+        }
+        requestAnimationFrame(frame);
+      }
+      requestAnimationFrame(frame);
+
+      // ----- Controls -----
+      document.querySelectorAll('.ops-btn[data-task]').forEach((btn) => {
+        btn.addEventListener('click', () => enqueue(btn.dataset.task));
+      });
+
+      document.getElementById('ops-batch').addEventListener('click', () => {
+        // Deliberately enqueue in reverse-priority order: the scheduler
+        // still executes urgent checkout work first, telemetry last.
+        const batch = [
+          ['background', 0], ['standard', 0], ['background', 1],
+          ['urgent', 0], ['standard', 1], ['urgent', 1],
+          ['background', 2], ['urgent', 2], ['standard', 2]
+        ];
+        log('system', `Batch submitted: ${batch.length} mixed tasks`);
+        batch.forEach(([type, variant]) => enqueue(type, variant));
+      });
+
+      document.getElementById('ops-clear').addEventListener('click', () => {
+        els.log.replaceChildren();
+      });
+
+      updateCounts();
+      log('system', 'Operations queue ready');
+    })();
+  </script>
