+  const section = document.getElementById('seasonal');
+  if (!section || !Element.prototype.animate) return;
+
+  const grid = section.querySelector('.seasonal-grid');
+  const tray = section.querySelector('.removed-tray');
+  const trayList = section.querySelector('.removed-list');
+  const live = section.querySelector('[data-live]');
+  const STORAGE_KEY = 'daily-grind:seasonal:v1';
+
+  /* ------------------------------------------------------------------ */
+  /* Options                                                             */
+  /* ------------------------------------------------------------------ */
+  const SIZES = [
+    { id: 'S', label: 'S', delta: 0 },
+    { id: 'M', label: 'M', delta: 0.5 },
+    { id: 'L', label: 'L', delta: 1 },
+  ];
+  const MILKS = [
+    { id: 'whole', label: 'Whole', delta: 0 },
+    { id: 'oat', label: 'Oat', delta: 0.6 },
+    { id: 'almond', label: 'Almond', delta: 0.6 },
+    { id: 'skim', label: 'Skim', delta: 0 },
+    { id: 'none', label: 'No milk', delta: 0 },
+  ];
+  const ADDONS = [
+    { id: 'shot', label: 'Extra shot', delta: 0.9 },
+    { id: 'vanilla', label: 'Vanilla syrup', delta: 0.5 },
+    { id: 'caramel', label: 'Caramel drizzle', delta: 0.5 },
+    { id: 'maple', label: 'Maple syrup', delta: 0.5 },
+    { id: 'cinnamon', label: 'Cinnamon dust', delta: 0 },
+    { id: 'whip', label: 'Whipped cream', delta: 0.5 },
+    { id: 'foam', label: 'Cold foam', delta: 0.75 },
+  ];
+  const DEFAULTS = {
+    'maple-oat': { size: 'M', milk: 'oat', addons: ['maple'] },
+    'dark-roast': { size: 'S', milk: 'none', addons: [] },
+    'cold-brew': { size: 'L', milk: 'none', addons: ['foam'] },
+    'pumpkin-cortado': { size: 'S', milk: 'whole', addons: ['cinnamon'] },
+  };
+  const byId = (list, id) => list.find((o) => o.id === id);
+
+  /* ------------------------------------------------------------------ */
+  /* Animation primitives                                                */
+  /* ------------------------------------------------------------------ */
+  const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)');
+  const dur = (ms) => (reducedMotion.matches ? 1 : ms);
+  const EASE = 'cubic-bezier(.2, .8, .2, 1)';
+
+  const moveAnims = new WeakMap(); // el -> translate animation
+  const sizeAnims = new WeakMap(); // el -> height animation
+  const fadeAnims = new WeakMap(); // el -> enter/exit animation
+
+  const track = (map, el, anim) => {
+    map.set(el, anim);
+    const clear = () => { if (map.get(el) === anim) map.delete(el); };
+    anim.addEventListener('finish', clear);
+    anim.addEventListener('cancel', clear);
+    return anim;
+  };
+
+  // Anchor point that stays fixed under height changes and top-origin scale.
+  const anchor = (el) => {
+    const r = el.getBoundingClientRect();
+    return { x: r.left + r.width / 2, y: r.top };
