+   * as currently painted, including any translate still running, so a new
+   * move continues smoothly from wherever an interrupted one left off.
+   */
+  function flip(els, mutate) {
+    const first = new Map();
+    for (const el of els) first.set(el, anchor(el));
+    mutate();
+    for (const el of first.keys()) moveAnims.get(el)?.cancel();
+    for (const [el, a] of first) {
+      if (!el.isConnected || el.classList.contains('is-leaving')) continue;
