+      h('option', { value: '', text: available.length ? '+ Add an extra…' : 'All extras added' }),
+      ...available.map((a) => h('option', { value: a.id,
+        text: a.label + (a.delta ? ` (+$${a.delta.toFixed(2)})` : '') })),
+    );
+    card.addSel.disabled = !available.length;
+    const text = `$${priceOf(card).toFixed(2)}`;
