+        { duration: dur(360), easing: EASE });
+    }
+    card.price.textContent = text;
+  }
+
+  /** Bring the chip list in line with state, animating chips in and out. */
+  function renderAddons(card, { animate = true } = {}) {
+    const list = card.addonList;
+    const present = new Map(
+      [...list.querySelectorAll('.addon-chip:not(.is-leaving)')].map((c) => [c.dataset.addon, c]));
+    const wanted = card.state.addons;
+
+    for (const [id, chip] of present) {
+      if (!wanted.includes(id)) {
+        if (animate) exit(chip, list); else chip.remove();
+      }
+    }
+    let ref = null;
+    for (const id of [...wanted].reverse()) {
+      let chip = present.get(id);
+      const isNew = !chip;
+      if (isNew) chip = chipFor(card, id);
+      list.insertBefore(chip, ref || list.querySelector('.addon-chip.is-leaving, .addon-empty'));
