+      list.append(card.empty);
+      if (animate) enter(card.empty, { scale: 1 });
+    }
+  }
+
+  /** Run a customization with transitions that only touch this one card. */
+  function customize(card, change) {
+    const chips = [...card.addonList.querySelectorAll('.addon-chip:not(.is-leaving), .addon-empty')];
+    animateHeight(card.el, () => flip(chips, () => {
+      change(card.state);
+      renderControls(card);
+      renderAddons(card);
+    }));
+    save();
+  }
+
+  /* ------------------------------------------------------------------ */
+  /* Grid-level operations                                               */
+  /* ------------------------------------------------------------------ */
+  function updateMoveButtons() {
+    const vis = visibleCards();
+    vis.forEach((el, i) => {
+      const c = cards.get(el.dataset.id);
+      // aria-disabled (not `disabled`) so a focused button keeps focus as it moves.
+      c.prev.setAttribute('aria-disabled', String(i === 0));
+      c.next.setAttribute('aria-disabled', String(i === vis.length - 1));
+    });
+  }
+
+  /** Grid layout change: cards FLIP, grid height eases, page stays live. */
+  function layoutChange(mutate) {
+    animateHeight(grid, () => flip(visibleCards(), mutate));
+    updateMoveButtons();
+    save();
+  }
+
+  function moveCard(card, toIndex) {
+    const vis = visibleCards();
+    const from = vis.indexOf(card.el);
+    if (from < 0 || toIndex < 0 || toIndex >= vis.length || toIndex === from) return false;
+    const focused = document.activeElement;
+    layoutChange(() => {
+      const others = vis.filter((el) => el !== card.el);
+      grid.insertBefore(card.el, others[toIndex] || null);
+      // Keep leaving cards at the end so they don't affect grid order.
+      for (const el of grid.querySelectorAll('.drink.is-leaving')) grid.append(el);
+    });
+    if (focused && card.el.contains(focused) && document.activeElement !== focused) {
+      focused.focus({ preventScroll: true });
+    }
+    return true;
+  }
+
+  function removeCard(card) {
+    const vis = visibleCards();
+    const i = vis.indexOf(card.el);
+    if (i < 0) return;
+    const hadFocus = card.el.contains(document.activeElement);
+    card.removed = true;
+    layoutChange(() => exit(card.el, grid));
+    addTrayItem(card);
+    announce(`${card.title} removed. You can restore it from the removed list.`);
+    if (hadFocus) {
+      const target = visibleCards()[Math.min(i, visibleCards().length - 1)];
+      (target ? cards.get(target.dataset.id).el.querySelector('.remove') : card.trayItem.querySelector('button'))
+        ?.focus({ preventScroll: true });
+    }
+  }
+
+  function insertionPoint(card) {
+    return visibleCards().find((el) => cards.get(el.dataset.id).originalIndex > card.originalIndex) || null;
+  }
+
+  function restoreCard(card, { focus = true } = {}) {
+    if (!card.removed) return;
+    card.removed = false;
+    removeTrayItem(card);
+    let fromOpacity = 0;
+    layoutChange(() => {
+      fromOpacity = cancelExit(card.el);
+      grid.insertBefore(card.el, insertionPoint(card));
+    });
+    enter(card.el, { from: fromOpacity });
+    announce(`${card.title} restored.`);
