+    card.trayItem = h('li', {}, b);
+    trayList.append(card.trayItem);
+    tray.hidden = false;
+  }
+
+  function addTrayItem(card) {
+    makeTrayItem(card);
+    enter(card.trayItem, { scale: 0.8 });
+  }
+
+  function removeTrayItem(card) {
+    const item = card.trayItem;
+    card.trayItem = null;
+    if (!item) return;
+    const rest = [...trayList.children].filter((li) => li !== item);
+    flip(rest, () => item.remove());
+    if (!trayList.children.length) tray.hidden = true;
+  }
+
+  function reset() {
+    for (const c of cards.values()) if (c.removed) restoreCard(c, { focus: false });
