+  }
+
+  /* ------------------------------------------------------------------ */
+  /* Events                                                              */
+  /* ------------------------------------------------------------------ */
+  section.addEventListener('click', (e) => {
+    const t = e.target.closest('button');
+    if (!t || !section.contains(t)) return;
+
+    if (t.dataset.action === 'reset') return reset();
+    if (t.dataset.restore) return restoreCard(cards.get(t.dataset.restore));
+
+    const li = t.closest('.drink');
+    const card = li && cards.get(li.dataset.id);
+    if (!card || li.classList.contains('is-leaving')) return;
+
+    if (t.classList.contains('remove')) return removeCard(card);
+    if (t.classList.contains('move-prev') || t.classList.contains('move-next')) {
+      const i = visibleCards().indexOf(li);
+      const to = t.classList.contains('move-prev') ? i - 1 : i + 1;
