+    }
+    if (t.dataset.size && t.dataset.size !== card.state.size) {
+      return customize(card, (s) => { s.size = t.dataset.size; });
+    }
+    if (t.dataset.removeAddon) {
+      const id = t.dataset.removeAddon;
+      const label = byId(ADDONS, id).label;
+      // Move focus before the chip goes inert.
+      const chip = t.closest('.addon-chip');
+      const sib = chip.nextElementSibling?.querySelector('button') || chip.previousElementSibling?.querySelector('button');
