+    const li = e.target.closest('.drink');
+    const card = li && cards.get(li.dataset.id);
+    if (!card) return;
+    if (e.target === card.milkSel) {
+      customize(card, (s) => { s.milk = e.target.value; });
+    } else if (e.target === card.addSel && e.target.value) {
