+    e.preventDefault();
+    e.dataTransfer.dropEffect = 'move';
+    const over = e.target.closest('.drink:not(.is-leaving)');
+    if (!over || over === dragging.el || moveAnims.has(over)) return; // avoid jitter
+    // Take the hovered card's slot; it and everything between shift over.
+    moveCard(dragging, visibleCards().indexOf(over));
+  });
