+  const endDrag = () => {
+    if (!dragging) {
+      for (const el of grid.querySelectorAll('[draggable="true"]')) el.draggable = false;
+      return;
+    }
+    dragging.el.classList.remove('is-dragging');
+    dragging.el.draggable = false;
+    announce(`${dragging.title} moved to position ${visibleCards().indexOf(dragging.el) + 1}.`);
