+// <drink-card> — reusable card for menu items.
+//
+// Usage:
+//   <drink-card href="/menu/seasonal" action-label="View Details" limited>
+//     <h3 slot="title">Maple Oat Latte</h3>
+//     <p>Creamy oat milk with a hint of Vermont maple syrup.</p>
+//   </drink-card>
+//
+// Attributes / properties:
+//   href          (string)  URL for the action link. Link is hidden when absent.
+//   action-label  (string)  Link text. Defaults to "View Details".
+//   limited       (boolean) Shows the "Limited" badge. Toggle at any time:
+//                           card.limited = true | false, or toggleAttribute('limited').
+//
+// Slots:
+//   title    The heading (use a real heading element, e.g. <h3>).
+//   (default) The description.
+//
+// Theming (inherited custom properties, all optional):
+//   --drink-card-bg, --drink-card-accent, --drink-card-badge-bg, --drink-card-badge-fg
+// Parts: card, badge, action
+
+const sheet = new CSSStyleSheet();
+sheet.replaceSync(`
+  :host {
+    --_bg: var(--drink-card-bg, white);
+    --_accent: var(--drink-card-accent, #4e342e);
+    --_accent-hover: var(--drink-card-accent-hover, #3e2723);
+    --_badge-bg: var(--drink-card-badge-bg, #ffab40);
+    --_badge-fg: var(--drink-card-badge-fg, #3e2723);
+    display: block;
+  }
+  :host([hidden]) { display: none; }
+
+  * { box-sizing: border-box; }
+
+  .card {
+    position: relative;
+    display: grid;
+    justify-items: center;
+    align-content: start;
+    gap: 10px;
+    block-size: 100%;
+    padding: 20px;
+    background: var(--_bg);
+    border-radius: 8px;
+    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
+    text-align: center;
+  }
+
+  .title { color: var(--_accent); }
+  ::slotted([slot="title"]) { margin: 0; }
+  ::slotted(p) { margin: 0; }
+
+  .badge {
+    position: absolute;
+    inset-block-start: 12px;
+    inset-inline-end: 12px;
+    padding: 2px 10px;
+    border-radius: 999px;
+    background: var(--_badge-bg);
+    color: var(--_badge-fg);
+    font-size: 0.75rem;
+    font-weight: 700;
+    letter-spacing: 0.05em;
+    text-transform: uppercase;
+    line-height: 1.6;
+  }
+  :host(:not([limited])) .badge { display: none; }
+
+  .action {
+    display: inline-block;
+    margin-block-start: 5px;
+    padding: 10px 20px;
+    border-radius: 5px;
+    background: var(--_accent);
+    color: white;
+    font: inherit;
+    text-decoration: none;
+    transition: background 0.3s;
+  }
+  .action:hover { background: var(--_accent-hover); }
+  .action:focus-visible { outline: 2px solid var(--_badge-bg); outline-offset: 2px; }
+  .action[hidden] { display: none; }
+`);
+
+const template = document.createElement('template');
+template.innerHTML = `
+  <article class="card" part="card">
+    <span class="badge" part="badge">Limited</span>
+    <div class="title"><slot name="title"></slot></div>
+    <slot></slot>
+    <a class="action" part="action" hidden></a>
+  </article>
+`;
+
+class DrinkCard extends HTMLElement {
+  static observedAttributes = ['href', 'action-label'];
+
+  #link;
+
+  constructor() {
+    super();
+    this.attachShadow({ mode: 'open' });
+    this.shadowRoot.adoptedStyleSheets = [sheet];
+    this.shadowRoot.append(template.content.cloneNode(true));
+    this.#link = this.shadowRoot.querySelector('.action');
+  }
+
+  connectedCallback() {
+    this.#syncLink();
+  }
+
+  attributeChangedCallback(_name, oldVal, newVal) {
+    if (oldVal !== newVal) this.#syncLink();
+  }
+
+  get href() { return this.getAttribute('href') ?? ''; }
+  set href(v) { v ? this.setAttribute('href', v) : this.removeAttribute('href'); }
+
+  get actionLabel() { return this.getAttribute('action-label') ?? 'View Details'; }
+  set actionLabel(v) { v ? this.setAttribute('action-label', v) : this.removeAttribute('action-label'); }
+
+  get limited() { return this.hasAttribute('limited'); }
+  set limited(on) { this.toggleAttribute('limited', !!on); }
+
+  #syncLink() {
+    const href = this.href;
+    this.#link.hidden = !href;
+    if (href) this.#link.href = href;
+    else this.#link.removeAttribute('href');
+    this.#link.textContent = this.actionLabel;
+  }
+}
+
+if (!customElements.get('drink-card')) {
+  customElements.define('drink-card', DrinkCard);
+}
