--- /dev/null
+++ b/components/drink-card.js
@@ -0,0 +1,180 @@
+/**
+ * <drink-card> — reusable menu card with encapsulated styles.
+ *
+ * Attributes (all reactive — change them at any time and the card updates):
+ *   heading       Card title, e.g. "Cold Brew"
+ *   description   Short blurb shown under the title
+ *   href          URL for the action link
+ *   action-label  Text for the action link (default: "View Details")
+ *   limited       Boolean. When present, shows the "Limited" badge.
+ *   badge-label   Optional override for the badge text (default: "Limited")
+ *
+ * Example:
+ *   <drink-card heading="Cold Brew" description="Steeped for 18 hours."
+ *               href="/menu/cold-brew" limited></drink-card>
+ *
+ *   card.toggleAttribute('limited', false); // or card.limited = false
+ *
+ * Styles live in a Shadow DOM, so global page CSS can't leak in and the
+ * card's CSS can't leak out. Theme colours can still be tuned from the page
+ * via CSS custom properties (--primary, --text, --accent) which inherit
+ * through the shadow boundary by design.
+ */
+(() => {
+  const template = document.createElement('template');
+  template.innerHTML = `
+    <style>
+      :host {
+        all: initial;
+        display: block;
+        box-sizing: border-box;
+        font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
+        line-height: 1.6;
+        color: var(--text, #3e2723);
+      }
+
+      :host([hidden]) {
+        display: none;
+      }
+
+      *, *::before, *::after {
+        box-sizing: border-box;
+        margin: 0;
+        padding: 0;
+      }
+
+      .card {
+        position: relative;
+        height: 100%;
+        background: #fff;
+        padding: 20px;
+        border-radius: 8px;
+        box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
+        text-align: center;
+      }
+
+      .badge {
+        display: none;
+        position: absolute;
+        top: 12px;
+        right: 12px;
+        background: var(--accent, #ffab40);
+        color: var(--text, #3e2723);
+        font-size: 0.7rem;
+        font-weight: 700;
+        letter-spacing: 0.05em;
+        text-transform: uppercase;
+        padding: 2px 8px;
+        border-radius: 999px;
+      }
+
+      :host([limited]) .badge {
+        display: inline-block;
+      }
+
+      h3 {
+        font-size: 1.17em;
+        font-weight: bold;
+        margin-bottom: 10px;
+        color: var(--primary, #4e342e);
+      }
+
+      :host([limited]) h3 {
+        /* keep long titles clear of the badge */
+        padding: 0 56px;
+      }
+
+      .btn {
+        display: inline-block;
+        background: var(--primary, #4e342e);
+        color: #fff;
+        padding: 10px 20px;
+        text-decoration: none;
+        border-radius: 5px;
+        margin-top: 15px;
+        transition: background 0.3s;
+      }
+
+      .btn:hover {
+        background: #3e2723;
+      }
+
+      .btn:focus-visible {
+        outline: 2px solid var(--accent, #ffab40);
+        outline-offset: 2px;
+      }
+    </style>
+    <article class="card" part="card">
+      <span class="badge" part="badge"></span>
+      <h3 part="heading"></h3>
+      <p part="description"></p>
+      <a class="btn" part="action"></a>
+    </article>
+  `;
+
+  class DrinkCard extends HTMLElement {
+    static get observedAttributes() {
+      return ['heading', 'description', 'href', 'action-label', 'limited', 'badge-label'];
+    }
+
+    constructor() {
+      super();
+      const root = this.attachShadow({ mode: 'open' });
+      root.appendChild(template.content.cloneNode(true));
+      this._els = {
+        badge: root.querySelector('.badge'),
+        heading: root.querySelector('h3'),
+        description: root.querySelector('p'),
+        action: root.querySelector('a'),
+      };
+    }
+
+    connectedCallback() {
+      this._render();
+    }
+
+    attributeChangedCallback() {
+      this._render();
+    }
+
+    get limited() {
+      return this.hasAttribute('limited');
+    }
+
+    set limited(value) {
+      this.toggleAttribute('limited', Boolean(value));
+    }
+
+    _render() {
+      const { badge, heading, description, action } = this._els;
+      const limited = this.limited;
+
+      // textContent only — never interpret attribute values as HTML.
+      badge.textContent = this.getAttribute('badge-label') || 'Limited';
+      badge.setAttribute('aria-hidden', String(!limited));
+      heading.textContent = this.getAttribute('heading') || '';
+      description.textContent = this.getAttribute('description') || '';
+      description.hidden = !description.textContent;
+
+      const href = this.getAttribute('href');
+      const label = this.getAttribute('action-label') || 'View Details';
+      action.textContent = label;
+      action.hidden = !href;
+      if (href) {
+        action.setAttribute('href', href);
+      } else {
+        action.removeAttribute('href');
+      }
+      const title = heading.textContent;
+      if (title) {
+        action.setAttribute('aria-label', `${label}: ${title}${limited ? ' (limited)' : ''}`);
+      } else {
+        action.removeAttribute('aria-label');
+      }
+    }
+  }
+
+  if (!customElements.get('drink-card')) {
+    customElements.define('drink-card', DrinkCard);
+  }
+})();
