+import { useEffect, type RefObject } from 'react';
+
+type Field = HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement;
+
+const isField = (el: EventTarget | null): el is Field =>
+  el instanceof Element && el.matches('input, select, textarea');
+
+/**
+ * Keeps aria-invalid and aria-describedby in sync with the native :user-invalid state, so
+ * screen readers only hear an error after the user has interacted with a field — the same
+ * moment the error becomes visible. Each field names its error element via `data-error`.
+ */
+export function useAccessibleValidation(formRef: RefObject<HTMLFormElement | null>, deps: unknown[] = []) {
+  useEffect(() => {
+    const form = formRef.current;
+    if (!form) return;
+
+    // One polite live region announces an error when the user leaves a field.
+    const announcer = document.createElement('div');
+    announcer.setAttribute('aria-live', 'polite');
+    announcer.className = 'sr-only';
+    document.body.append(announcer);
+    let announceTimer: ReturnType<typeof setTimeout> | undefined;
+    let announcedField: Field | null = null;
+
+    const flagged = new WeakSet<Field>();
+    const announced = new WeakSet<Field>();
+
+    const linkError = (el: Field, shown: boolean) => {
+      const errorId = el.dataset.error;
+      if (!errorId) return;
+      const ids = (el.getAttribute('aria-describedby') || '').split(/\s+/).filter((id) => id && id !== errorId);
+      if (shown) ids.push(errorId);
+      if (ids.length) el.setAttribute('aria-describedby', ids.join(' '));
+      else el.removeAttribute('aria-describedby');
+    };
+
+    const announceError = (el: Field) => {
+      const error = el.dataset.error && document.getElementById(el.dataset.error);
+      if (!error) return;
+      const label = el.labels?.[0]?.textContent?.trim();
+      clearTimeout(announceTimer);
+      announcer.textContent = '';
+      announcedField = el;
+      // Wait until the screen reader has announced the next focused field.
+      announceTimer = setTimeout(() => {
+        announcer.textContent = `${label ? `${label}: ` : ''}${error.textContent?.trim() ?? ''}`;
+      }, 500);
