--- /dev/null
+++ b/src/lib/phoneVerification.ts
@@ -0,0 +1,90 @@
+import { createHmac, randomInt, timingSafeEqual } from 'node:crypto';
+
+export const CODE_LENGTH = 6;
+export const CODE_TTL_MS = 10 * 60 * 1000; // 10 minutes
+export const RESEND_COOLDOWN_MS = 30 * 1000; // 30 seconds
+export const MAX_ATTEMPTS = 5;
+export const SESSION_KEY = 'phoneVerification';
+
+export interface PhoneVerificationState {
+  phone: string;
+  codeHash: string;
+  expiresAt: number;
+  sentAt: number;
+  attempts: number;
+  verified: boolean;
+}
+
+// Secret used to hash codes at rest in the session store. Set OTP_SECRET in production.
+const SECRET = process.env.OTP_SECRET || import.meta.env.OTP_SECRET || 'dev-only-otp-secret';
+
+/**
+ * Normalizes user-entered phone numbers to E.164 (e.g. "+1 (555) 123-4567" -> "+15551234567").
+ * Returns null when the number can't be a valid international number.
+ */
+export function normalizePhone(input: unknown): string | null {
+  if (typeof input !== 'string') return null;
+  const trimmed = input.trim();
+  const digits = trimmed.replace(/\D/g, '');
+  // Accept "00" international prefix as an alternative to "+".
+  const national = trimmed.startsWith('+') ? digits : trimmed.startsWith('00') ? digits.slice(2) : null;
+  if (!national || !/^[1-9]\d{7,14}$/.test(national)) return null;
+  return `+${national}`;
+}
+
+export function generateCode(): string {
+  return randomInt(0, 10 ** CODE_LENGTH).toString().padStart(CODE_LENGTH, '0');
+}
+
+export function hashCode(phone: string, code: string): string {
+  return createHmac('sha256', SECRET).update(`${phone}:${code}`).digest('hex');
+}
+
+export function codesMatch(expectedHash: string, phone: string, code: string): boolean {
+  const a = Buffer.from(expectedHash, 'hex');
+  const b = Buffer.from(hashCode(phone, code), 'hex');
+  return a.length === b.length && timingSafeEqual(a, b);
+}
+
+export function maskPhone(phone: string): string {
+  return `${phone.slice(0, 3)}${'•'.repeat(Math.max(0, phone.length - 5))}${phone.slice(-2)}`;
+}
+
+/**
+ * Builds an origin-bound SMS body. The final line must be exactly "@<host> #<code>" so the
+ * WebOTP API and `autocomplete="one-time-code"` autofill only offer the code on this domain.
+ */
+export function buildSmsBody(code: string, host: string): string {
+  return `Your DevTools Times verification code is ${code}. It expires in 10 minutes.\n\n@${host} #${code}`;
+}
+
+/**
+ * Delivers the SMS. If SMS_WEBHOOK_URL is configured, the message is POSTed there as
+ * { to, body } so any SMS provider can be wired in; otherwise it is logged for local development.
+ */
+export async function sendSms(to: string, body: string): Promise<void> {
+  const webhook = process.env.SMS_WEBHOOK_URL || import.meta.env.SMS_WEBHOOK_URL;
+  if (!webhook) {
+    console.info(`[sms] to ${to}:\n${body}`);
+    return;
+  }
+  const res = await fetch(webhook, {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({ to, body }),
+  });
+  if (!res.ok) throw new Error(`SMS provider responded with ${res.status}`);
+}
+
+/** Host only (no scheme, port, or path) for the "@domain" token. */
+export function smsOriginHost(requestUrl: URL): string {
+  const configured = process.env.SMS_ORIGIN_HOST || import.meta.env.SMS_ORIGIN_HOST;
+  return configured || requestUrl.hostname;
+}
+
+export function json(data: unknown, status = 200): Response {
+  return new Response(JSON.stringify(data), {
+    status,
+    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' },
+  });
+}
