new file mode 100644
index 0000000..365e9dd
--- /dev/null
+++ b/src/pages/api/phone/send-code.ts
@@ -0,0 +1,63 @@
+import type { APIRoute } from 'astro';
+import {
+  CODE_TTL_MS,
+  RESEND_COOLDOWN_MS,
+  SESSION_KEY,
+  buildSmsBody,
+  generateCode,
+  hashCode,
+  json,
+  maskPhone,
+  normalizePhone,
+  sendSms,
+  smsOriginHost,
+  type PhoneVerificationState,
+} from '../../../lib/phoneVerification';
+
+export const prerender = false;
+
+export const POST: APIRoute = async ({ request, session, url }) => {
+  let body: { phone?: unknown };
+  try {
+    body = await request.json();
+  } catch {
+    return json({ error: 'Invalid request body.' }, 400);
+  }
+
+  const phone = normalizePhone(body.phone);
+  if (!phone) {
+    return json({ error: 'Enter a valid phone number including the country code, for example +1 555 123 4567.' }, 400);
+  }
+
+  const now = Date.now();
+  const existing = (await session?.get(SESSION_KEY)) as PhoneVerificationState | undefined;
+  if (existing && existing.phone === phone && now - existing.sentAt < RESEND_COOLDOWN_MS) {
+    const retryAfter = Math.ceil((RESEND_COOLDOWN_MS - (now - existing.sentAt)) / 1000);
+    return json({ error: `Please wait ${retryAfter} seconds before requesting a new code.`, retryAfter }, 429);
+  }
+
+  const code = generateCode();
+  const state: PhoneVerificationState = {
+    phone,
+    codeHash: hashCode(phone, code),
+    expiresAt: now + CODE_TTL_MS,
+    sentAt: now,
+    attempts: 0,
+    verified: false,
+  };
+
+  try {
+    await sendSms(phone, buildSmsBody(code, smsOriginHost(url)));
+  } catch (err) {
+    console.error('[sms] delivery failed', err);
+    return json({ error: 'We could not send a text message right now. Please try again later.' }, 502);
+  }
+
+  session?.set(SESSION_KEY, state);
+
+  return json({
+    maskedPhone: maskPhone(phone),
+    expiresIn: CODE_TTL_MS / 1000,
+    resendIn: RESEND_COOLDOWN_MS / 1000,
+  });
+};
