--- /dev/null
+++ b/src/pages/api/phone/verify-code.ts
@@ -0,0 +1,59 @@
+import type { APIRoute } from 'astro';
+import {
+  CODE_LENGTH,
+  MAX_ATTEMPTS,
+  SESSION_KEY,
+  codesMatch,
+  json,
+  type PhoneVerificationState,
+} from '../../../lib/phoneVerification';
+
+export const prerender = false;
+
+export const POST: APIRoute = async ({ request, session }) => {
+  let body: { code?: unknown };
+  try {
+    body = await request.json();
+  } catch {
+    return json({ error: 'Invalid request body.' }, 400);
+  }
+
+  const code = typeof body.code === 'string' ? body.code.replace(/\s/g, '') : '';
+  if (!new RegExp(`^\\d{${CODE_LENGTH}}$`).test(code)) {
+    return json({ error: `Enter the ${CODE_LENGTH}-digit code from the text message.` }, 400);
+  }
+
+  const state = (await session?.get(SESSION_KEY)) as PhoneVerificationState | undefined;
+  if (!state) {
+    return json({ error: 'No verification is in progress. Request a new code.' }, 400);
+  }
+  if (state.verified) {
+    return json({ verified: true, phone: state.phone });
+  }
+  if (Date.now() > state.expiresAt) {
+    session?.delete(SESSION_KEY);
+    return json({ error: 'This code has expired. Request a new code.', expired: true }, 410);
+  }
+  if (state.attempts >= MAX_ATTEMPTS) {
+    session?.delete(SESSION_KEY);
+    return json({ error: 'Too many incorrect attempts. Request a new code.', expired: true }, 429);
+  }
+
+  if (!codesMatch(state.codeHash, state.phone, code)) {
+    const attempts = state.attempts + 1;
+    session?.set(SESSION_KEY, { ...state, attempts });
+    const remaining = MAX_ATTEMPTS - attempts;
+    return json(
+      {
+        error: remaining > 0
+          ? `That code is incorrect. ${remaining} ${remaining === 1 ? 'attempt' : 'attempts'} left.`
+          : 'Too many incorrect attempts. Request a new code.',
+        expired: remaining <= 0,
+      },
+      400,
+    );
+  }
+
+  session?.set(SESSION_KEY, { ...state, verified: true, codeHash: '' });
+  return json({ verified: true, phone: state.phone });
+};

