+++ b/src/lib/phoneVerification.ts
@@ -0,0 +1,94 @@
+import { createHash, randomInt, timingSafeEqual } from 'node:crypto';
+
+export const CODE_LENGTH = 6;
+export const CODE_TTL_MS = 5 * 60 * 1000;
+export const RESEND_COOLDOWN_MS = 30 * 1000;
+export const MAX_VERIFY_ATTEMPTS = 5;
+export const MAX_SENDS_PER_SESSION = 5;
+
+/** Session-stored state for an in-progress phone verification. */
+export interface PendingVerification {
+  phone: string;
+  codeHash: string;
+  expiresAt: number;
+  lastSentAt: number;
+  attempts: number;
+  sends: number;
+}
+
+export interface VerifiedPhone {
+  phone: string;
+  verifiedAt: number;
+}
+
+const E164 = /^\+[1-9]\d{7,14}$/;
+
+/**
+ * Normalises user input like "+1 (555) 123-4567" or "0044 20 7946 0958"
+ * into E.164 ("+15551234567"). Returns null when the result is not valid.
+ */
+export function normalizePhone(input: unknown): string | null {
+  if (typeof input !== 'string') return null;
+  let phone = input.trim().replace(/[\s().\-]/g, '');
+  if (phone.startsWith('00')) phone = `+${phone.slice(2)}`;
+  return E164.test(phone) ? phone : null;
+}
+
+export function maskPhone(phone: string): string {
+  return phone.length <= 4 ? phone : `${phone.slice(0, 3)}${'•'.repeat(Math.max(phone.length - 5, 0))}${phone.slice(-2)}`;
+}
+
+export function generateCode(): string {
+  return randomInt(0, 10 ** CODE_LENGTH).toString().padStart(CODE_LENGTH, '0');
+}
+
+export function hashCode(phone: string, code: string): string {
+  return createHash('sha256').update(`${phone}:${code}`).digest('hex');
+}
+
+export function codeMatches(pending: PendingVerification, code: string): boolean {
+  const a = Buffer.from(hashCode(pending.phone, code), 'hex');
+  const b = Buffer.from(pending.codeHash, 'hex');
+  return a.length === b.length && timingSafeEqual(a, b);
+}
+
+/**
+ * Builds an SMS body compatible with the WebOTP API / Android SMS Retriever
+ * and iOS/macOS security-code AutoFill. The final line must be
+ * "@<origin host> #<code>" so the browser can bind the code to this site.
+ */
+export function buildOtpMessage(code: string, host: string): string {
+  return `${code} is your DevTools Times verification code. It expires in ${Math.round(CODE_TTL_MS / 60000)} minutes.\n\n@${host} #${code}`;
+}
+
+export type SmsResult = { delivered: true } | { delivered: false; reason: 'not-configured' | 'provider-error' };
+
+/**
+ * Delivers an SMS through Twilio when credentials are configured
+ * (TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN, TWILIO_FROM_NUMBER).
+ */
+export async function sendSms(to: string, body: string): Promise<SmsResult> {
+  const sid = process.env.TWILIO_ACCOUNT_SID;
+  const token = process.env.TWILIO_AUTH_TOKEN;
+  const from = process.env.TWILIO_FROM_NUMBER;
+  if (!sid || !token || !from) return { delivered: false, reason: 'not-configured' };
+
+  try {
+    const res = await fetch(`https://api.twilio.com/2010-04-01/Accounts/${encodeURIComponent(sid)}/Messages.json`, {
+      method: 'POST',
+      headers: {
+        Authorization: `Basic ${Buffer.from(`${sid}:${token}`).toString('base64')}`,
+        'Content-Type': 'application/x-www-form-urlencoded',
+      },
+      body: new URLSearchParams({ To: to, From: from, Body: body }),
+    });
+    if (!res.ok) {
+      console.error('[sms] Provider rejected message', res.status, await res.text().catch(() => ''));
+      return { delivered: false, reason: 'provider-error' };
+    }
+    return { delivered: true };
+  } catch (err) {
+    console.error('[sms] Failed to reach provider', err);
+    return { delivered: false, reason: 'provider-error' };
+  }
+}
