@@ -0,0 +1,149 @@
+import type { APIRoute } from 'astro';
+import {
+  CODE_LENGTH,
+  CODE_TTL_MS,
+  MAX_SENDS_PER_SESSION,
+  MAX_VERIFY_ATTEMPTS,
+  RESEND_COOLDOWN_MS,
+  buildOtpMessage,
+  codeMatches,
+  generateCode,
+  hashCode,
+  maskPhone,
+  normalizePhone,
+  sendSms,
+  type PendingVerification,
+  type VerifiedPhone,
+} from '../../lib/phoneVerification';
+
+export const prerender = false;
+
+const PENDING_KEY = 'phoneVerificationPending';
+const VERIFIED_KEY = 'phoneVerified';
+
+function json(body: Record<string, unknown>, status = 200, headers: Record<string, string> = {}) {
+  return new Response(JSON.stringify(body), {
+    status,
+    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store', ...headers },
+  });
+}
+
+/**
+ * POST /api/phone-verification
+ *   { action: "send",   phone }        -> sends a one-time code by SMS
+ *   { action: "verify", phone, code }  -> checks the code
+ */
+export const POST: APIRoute = async ({ request, session, url }) => {
+  if (!session) return json({ error: 'Sessions are unavailable.', code: 'SESSION_UNAVAILABLE' }, 500);
+
+  let payload: { action?: unknown; phone?: unknown; code?: unknown };
+  try {
+    payload = await request.json();
+  } catch {
+    return json({ error: 'Invalid request body.', code: 'BAD_REQUEST' }, 400);
+  }
+
+  const phone = normalizePhone(payload.phone);
+  if (!phone) {
+    return json(
+      { error: 'Enter a valid mobile number including the country code, e.g. +1 555 123 4567.', code: 'INVALID_PHONE' },
+      400,
+    );
+  }
+
+  const now = Date.now();
+  const pending = (await session.get(PENDING_KEY)) as PendingVerification | undefined;
+
+  if (payload.action === 'send') {
+    const samePhone = pending?.phone === phone;
+    if (samePhone && now - pending.lastSentAt < RESEND_COOLDOWN_MS) {
+      const retryAfter = Math.ceil((RESEND_COOLDOWN_MS - (now - pending.lastSentAt)) / 1000);
+      return json(
+        { error: `Please wait ${retryAfter} seconds before requesting a new code.`, code: 'RATE_LIMITED', retryAfter },
+        429,
+        { 'Retry-After': String(retryAfter) },
+      );
+    }
+    const sends = (pending?.sends ?? 0) + 1;
+    if (sends > MAX_SENDS_PER_SESSION) {
+      return json({ error: 'Too many codes requested. Please try again later.', code: 'TOO_MANY_SENDS' }, 429);
+    }
+
+    const code = generateCode();
+    const result = await sendSms(phone, buildOtpMessage(code, url.hostname));
+
+    let devCode: string | undefined;
+    if (!result.delivered) {
+      if (result.reason === 'not-configured' && import.meta.env.DEV) {
+        // Local development without an SMS provider: surface the code instead.
+        console.info(`[sms:dev] ${phone} <- ${buildOtpMessage(code, url.hostname).replace(/\n/g, ' ')}`);
+        devCode = code;
+      } else {
+        return json({ error: 'We could not send a text message right now. Please try again later.', code: 'SMS_FAILED' }, 503);
+      }
+    }
+
+    const next: PendingVerification = {
+      phone,
+      codeHash: hashCode(phone, code),
+      expiresAt: now + CODE_TTL_MS,
+      lastSentAt: now,
+      attempts: 0,
+      sends,
+    };
+    session.set(PENDING_KEY, next);
+    session.delete(VERIFIED_KEY);
+
+    return json({
+      ok: true,
+      maskedPhone: maskPhone(phone),
+      codeLength: CODE_LENGTH,
+      expiresIn: CODE_TTL_MS / 1000,
+      resendIn: RESEND_COOLDOWN_MS / 1000,
+      ...(devCode ? { devCode } : {}),
+    });
+  }
+
+  if (payload.action === 'verify') {
+    const code = typeof payload.code === 'string' ? payload.code.replace(/\D/g, '') : '';
+    if (code.length !== CODE_LENGTH) {
+      return json({ error: `Enter the ${CODE_LENGTH}-digit code.`, code: 'INVALID_CODE_FORMAT' }, 400);
+    }
+    if (!pending || pending.phone !== phone) {
+      return json({ error: 'No code was requested for this number. Please request a new code.', code: 'NO_PENDING_CODE' }, 400);
+    }
+    if (now > pending.expiresAt) {
+      session.delete(PENDING_KEY);
+      return json({ error: 'This code has expired. Please request a new one.', code: 'CODE_EXPIRED' }, 410);
+    }
+    if (pending.attempts >= MAX_VERIFY_ATTEMPTS) {
+      session.delete(PENDING_KEY);
+      return json({ error: 'Too many incorrect attempts. Please request a new code.', code: 'TOO_MANY_ATTEMPTS' }, 429);
+    }
+
+    if (!codeMatches(pending, code)) {
+      const attempts = pending.attempts + 1;
+      const remaining = MAX_VERIFY_ATTEMPTS - attempts;
+      if (remaining <= 0) {
+        session.delete(PENDING_KEY);
+        return json({ error: 'Too many incorrect attempts. Please request a new code.', code: 'TOO_MANY_ATTEMPTS' }, 429);
+      }
+      session.set(PENDING_KEY, { ...pending, attempts });
+      return json(
+        {
+          error: `That code is incorrect. ${remaining} ${remaining === 1 ? 'attempt' : 'attempts'} remaining.`,
+          code: 'INCORRECT_CODE',
+          remainingAttempts: remaining,
+        },
+        400,
+      );
+    }
+
+    session.delete(PENDING_KEY);
+    const verified: VerifiedPhone = { phone, verifiedAt: now };
+    session.set(VERIFIED_KEY, verified);
+    return json({ ok: true, phone, maskedPhone: maskPhone(phone) });
+  }
+
+  return json({ error: 'Unknown action.', code: 'BAD_REQUEST' }, 400);
+};

