+/**
+ * Accessible spatial (arrow-key) navigation for card grids.
+ *
+ * Navigation is computed from the cards' rendered geometry rather than DOM
+ * order or an assumed column count, so it stays correct across layout modes
+ * (auto-fit grid, single-column list, compact, dense "mosaic" with spanning
+ * cards), responsive reflows, CSS `order`, and right-to-left direction.
+ *
+ * Keyboard model (roving tabindex — the grid is a single Tab stop):
+ *   ArrowUp / ArrowDown     nearest card in the row above / below
+ *   ArrowLeft / ArrowRight  nearest card in the same row; at the row edge it
+ *                           continues in reading order (wraps to next/prev row)
+ *   Home / End              first / last card in the current visual row
+ *   Ctrl+Home / Ctrl+End    first / last card in reading order
+ *   Enter / Space           activate the card's primary link
+ */
+(function () {
+  'use strict';
+
+  // Pixels of tolerance when comparing edges, to absorb sub-pixel rounding.
+  var EPS = 1;
+
+  function isRendered(el) {
+    if (el.hidden) return false;
+    var r = el.getBoundingClientRect();
+    return r.width > 0 && r.height > 0;
+  }
+
+  function isRtl(el) {
+    return getComputedStyle(el).direction === 'rtl';
+  }
+
+  function overlap(aStart, aEnd, bStart, bEnd) {
+    return Math.min(aEnd, bEnd) - Math.max(aStart, bStart);
+  }
+
+  function SpatialGrid(container, itemSelector) {
+    this.container = container;
+    this.itemSelector = itemSelector;
+    this.activeItem = null;
+
+    this.onKeyDown = this.onKeyDown.bind(this);
+    this.onFocusIn = this.onFocusIn.bind(this);
+
+    container.addEventListener('keydown', this.onKeyDown);
+    container.addEventListener('focusin', this.onFocusIn);
+
+    this.refresh();
+  }
+
+  SpatialGrid.prototype.items = function () {
+    return Array.prototype.filter.call(
+      this.container.querySelectorAll(this.itemSelector),
+      isRendered
+    );
+  };
+
+  /**
+   * Ensure exactly one rendered card is in the Tab order and that the cards'
+   * inner links don't add extra Tab stops. Call after any layout/content change.
+   */
+  SpatialGrid.prototype.refresh = function () {
+    var items = this.items();
+    var all = this.container.querySelectorAll(this.itemSelector);
+    var active = this.activeItem;
+
+    if (!active || items.indexOf(active) === -1) {
+      active = this.readingOrder(items)[0] || null;
+    }
+
+    Array.prototype.forEach.call(all, function (item) {
+      item.setAttribute('tabindex', item === active ? '0' : '-1');
+      Array.prototype.forEach.call(
+        item.querySelectorAll('a[href], button, input, select, textarea, [tabindex]'),
+        function (el) {
+          if (el !== item) el.setAttribute('tabindex', '-1');
+        }
+      );
+    });
+
+    this.activeItem = active;
+  };
+
+  SpatialGrid.prototype.setActive = function (item) {
+    if (!item) return;
+    if (this.activeItem && this.activeItem !== item) {
+      this.activeItem.setAttribute('tabindex', '-1');
+    }
+    item.setAttribute('tabindex', '0');
+    this.activeItem = item;
+  };
+
+  SpatialGrid.prototype.focusItem = function (item) {
+    if (!item) return;
+    this.setActive(item);
+    item.focus();
+    // focus() scrolls, but `nearest` avoids jumping when the card is already visible
+    // and keeps it clear of the sticky nav where possible.
+    item.scrollIntoView({ block: 'nearest', inline: 'nearest' });
+  };
+
+  SpatialGrid.prototype.onFocusIn = function (event) {
+    var item = event.target.closest(this.itemSelector);
+    if (item && this.container.contains(item)) this.setActive(item);
+  };
+
+  /** Group rendered cards into visual rows (by vertical overlap of their boxes). */
+  SpatialGrid.prototype.rows = function (items) {
+    var entries = items.map(function (el) {
+      return { el: el, rect: el.getBoundingClientRect() };
+    });
+    entries.sort(function (a, b) {
+      return a.rect.top - b.rect.top || a.rect.left - b.rect.left;
+    });
+
+    var rows = [];
+    entries.forEach(function (entry) {
+      var row = rows[rows.length - 1];
+      // A card starts a new row if its top is below the current row's first
+      // card's vertical center — robust to cards that span multiple rows.
+      if (row && entry.rect.top < row.top + row.firstHeight / 2) {
+        row.items.push(entry);
+      } else {
+        rows.push({ top: entry.rect.top, firstHeight: entry.rect.height, items: [entry] });
+      }
+    });
+    return rows;
+  };
+
+  /** Cards in visual reading order: rows top-to-bottom, inline-start to inline-end. */
+  SpatialGrid.prototype.readingOrder = function (items) {
+    var rtl = isRtl(this.container);
+    var out = [];
+    this.rows(items).forEach(function (row) {
+      row.items.sort(function (a, b) {
+        return rtl ? b.rect.right - a.rect.right : a.rect.left - b.rect.left;
+      });
+      row.items.forEach(function (e) { out.push(e.el); });
+    });
+    return out;
+  };
+
+  /**
+   * Cards visually sharing a row with `item`: every card whose vertical extent
+   * covers the middle of the item's (first) row. This includes cards spanning several
+   * rows (e.g. a featured card in mosaic mode) beside the item.
+   */
+  SpatialGrid.prototype.rowOf = function (item, items) {
+    var r = item.getBoundingClientRect();
+    // For a card spanning several rows, probe its first row: use the height of
+    // the shortest card as the row height.
+    var minH = Math.min.apply(null, items.map(function (el) {
+      return el.getBoundingClientRect().height;
+    }));
+    var cy = r.top + Math.min(r.height, minH) / 2;
+    return items.filter(function (el) {
+      var o = el.getBoundingClientRect();
+      return o.top - EPS <= cy && o.bottom + EPS >= cy;
+    });
+  };
+
+  /**
+   * Find the best card in a physical direction from `current`.
+   * Candidates must lie entirely beyond the current card's edge in that
+   * direction. Cards overlapping the current one on the perpendicular axis
+   * (same row/column) are strongly preferred; otherwise distance is weighted
+   * so straight moves beat diagonal ones.
+   */
+  SpatialGrid.prototype.findInDirection = function (current, items, dir) {
+    var cur = current.getBoundingClientRect();
+    var horizontal = dir === 'left' || dir === 'right';
+    var best = null;
+    var bestScore = Infinity;
+
+    items.forEach(function (el) {
+      if (el === current) return;
+      var r = el.getBoundingClientRect();
+      var gap;
+
+      if (dir === 'right') gap = r.left - cur.right;
+      else if (dir === 'left') gap = cur.left - r.right;
+      else if (dir === 'down') gap = r.top - cur.bottom;
+      else gap = cur.top - r.bottom;
+
+      if (gap < -EPS) return; // not beyond the edge in this direction
+      gap = Math.max(0, gap);
+
+      var ov = horizontal
+        ? overlap(cur.top, cur.bottom, r.top, r.bottom)
+        : overlap(cur.left, cur.right, r.left, r.right);
+
+      var curCenter = horizontal ? (cur.top + cur.bottom) / 2 : (cur.left + cur.right) / 2;
+      var candCenter = horizontal ? (r.top + r.bottom) / 2 : (r.left + r.right) / 2;
+      var offAxis = Math.abs(candCenter - curCenter);
+
+      var score;
+      if (ov > EPS) {
+        // Aligned: closest first, then best centred.
+        score = gap + offAxis * 0.01;
+      } else {
+        // Not aligned: heavily penalised so aligned cards always win.
+        score = 1e6 + gap + offAxis * 2;
+      }
+
+      if (score < bestScore) {
+        bestScore = score;
+        best = { el: el, aligned: ov > EPS };
+      }
+    });
+
+    return best;
+  };
+
+  SpatialGrid.prototype.onKeyDown = function (event) {
+    if (event.defaultPrevented || event.altKey || event.metaKey) return;
+
+    var item = event.target.closest(this.itemSelector);
+    // Only handle keys when the card itself has focus (not form controls inside it).
+    if (!item || event.target !== item || !this.container.contains(item)) return;
+
+    var items = this.items();
+    if (!items.length) return;
+
+    var rtl = isRtl(this.container);
+    var target = null;
+    var key = event.key;
+    var ctrl = event.ctrlKey;
+
+    switch (key) {
+      case 'ArrowUp':
+      case 'ArrowDown': {
+        if (ctrl) return;
+        var v = this.findInDirection(item, items, key === 'ArrowUp' ? 'up' : 'down');
+        target = v && v.el;
+        break;
+      }
+
+      case 'ArrowLeft':
+      case 'ArrowRight': {
+        if (ctrl) return;
+        var dir = key === 'ArrowLeft' ? 'left' : 'right';
+        var h = this.findInDirection(item, items, dir);
+        if (h && h.aligned) {
+          target = h.el;
+        } else {
+          // At the row edge (or in a single-column list): continue in reading
+          // order so every card is reachable with Left/Right alone.
+          var order = this.readingOrder(items);
+          var idx = order.indexOf(item);
+          var forward = (dir === 'right') !== rtl;
+          target = order[idx + (forward ? 1 : -1)] || null;
+        }
+        break;
+      }
+
+      case 'Home':
+      case 'End': {
+        var list = ctrl ? items : this.rowOf(item, items);
+        var ordered = this.readingOrder(list);
+        target = key === 'Home' ? ordered[0] : ordered[ordered.length - 1];
+        break;
+      }
+
+      case 'Enter':
+      case ' ': {
+        if (ctrl || event.shiftKey) return;
+        var link = item.querySelector('a[href], button');
+        if (link) {
+          event.preventDefault();
+          link.click();
+        }
+        return;
+      }
+
+      default:
+        return;
+    }
+
+    // Always consume handled navigation keys so the page doesn't scroll,
+    // even when there is no card further in that direction.
+    event.preventDefault();
+    if (target && target !== item) this.focusItem(target);
+  };
+
+  // ---------------------------------------------------------------------------
+  // Wire-up
+  // ---------------------------------------------------------------------------
+
+  function init() {
+    var container = document.getElementById('seasonal-grid');
+    if (!container) return;
+
+    var grid = new SpatialGrid(container, '.card');
+
+    // Layout mode switcher
+    var layoutButtons = document.querySelectorAll('.grid-toolbar [data-layout]');
+    Array.prototype.forEach.call(layoutButtons, function (btn) {
+      btn.addEventListener('click', function () {
+        container.setAttribute('data-layout', btn.getAttribute('data-layout'));
+        Array.prototype.forEach.call(layoutButtons, function (b) {
+          b.setAttribute('aria-pressed', b === btn ? 'true' : 'false');
+        });
+        grid.refresh();
+      });
+    });
