+    // Direction toggle
+    var dirBtn = document.querySelector('.grid-toolbar [data-dir-toggle]');
+    if (dirBtn) {
+      dirBtn.addEventListener('click', function () {
+        var on = dirBtn.getAttribute('aria-pressed') !== 'true';
+        dirBtn.setAttribute('aria-pressed', on ? 'true' : 'false');
+        if (on) container.setAttribute('dir', 'rtl');
+        else container.removeAttribute('dir');
+        grid.refresh();
+      });
+    }
