+    // Keep the roving tab stop valid if cards are hidden/shown by resizing
+    // or media queries.
+    if ('ResizeObserver' in window) {
+      new ResizeObserver(function () { grid.refresh(); }).observe(container);
+    }
+
+  }
+
+  window.SpatialGrid = SpatialGrid;
+
+  if (document.readyState === 'loading') {
+    document.addEventListener('DOMContentLoaded', init);
+  } else {
+    init();
+  }
+})();

