+          // Fresh visit / deep link: seed one history entry per level so the
+          // browser Back button walks up the hierarchy instead of leaving.
+          history.replaceState(makeState(nodes.slice(0, 1), false), '', hrefFor('/'));
+          for (let i = 1; i < nodes.length; i++) {
+            const slice = nodes.slice(0, i + 1);
+            history.pushState(makeState(slice, true), '', hrefFor(nodes[i].path));
+          }
