+/**
+ * <drink-card> — an encapsulated menu card for The Daily Grind.
+ *
+ * Theming (inherited custom properties — set them anywhere up the tree):
+ *   --primary, --secondary, --accent, --text, --light   (site palette, read as fallbacks)
+ *   --drink-card-bg, --drink-card-fg, --drink-card-accent,
+ *   --drink-card-radius, --drink-card-shadow, --drink-card-padding
+ *
+ * Variants (attribute on the host):
+ *   variant="classic"  (default) — white card, centered text
+ *   variant="featured" — bordered with accent, ribbon badge, horizontal layout when wide
+ *   variant="iced"     — cool-toned surface for cold drinks
+ *
+ * Slots:
+ *   media   — an <img> (optional; hidden when empty)
+ *   badge   — short label, e.g. "New" (optional)
+ *   title   — drink name (e.g. <h3 slot="title">)
+ *   (default) — description
+ *   price   — price text (optional)
+ *   action  — call to action link/button
+ *
+ * Parts (style freely from the page with drink-card::part(name)):
+ *   card, media, badge, title, body, footer
+ *
+ * Custom states (read-only from the page): :state(has-media), :state(has-badge)
+ */
+
+const sheet = new CSSStyleSheet();
+sheet.replaceSync(/* css */ `
+  /* Priority tiers, lowest → highest. Later layers win regardless of specificity,
+     so variants never have to out-specify base rules, and layout rules
+     (container queries) always get the final say over structure. */
+  @layer reset, tokens, base, variants, layout, states;
+
+  @layer reset {
+    *, *::before, *::after { box-sizing: border-box; }
+    ::slotted(*) { margin: 0; }
+  }
+
+  @layer tokens {
+    :host {
+      /* Private aliases: public properties stay unset here so the page can
+         override them from any ancestor; the site palette is the fallback. */
+      --_bg: var(--drink-card-bg, #fff);
+      --_fg: var(--drink-card-fg, var(--text, #3e2723));
+      --_heading: var(--drink-card-heading, var(--primary, #4e342e));
+      --_accent: var(--drink-card-accent, var(--accent, #ffab40));
+      --_muted: var(--secondary, #d7ccc8);
+      --_radius: var(--drink-card-radius, 8px);
+      --_shadow: var(--drink-card-shadow, 0 2px 5px rgb(0 0 0 / 0.1));
+      --_pad: var(--drink-card-padding, 20px);
+      --_border: transparent;
+    }
+  }
+
+  @layer base {
+    :host {
+      display: block; /* custom elements are inline by default; containment needs a box */
+      container: drink-card / inline-size;
+      color: var(--_fg);
+    }
+    :host([hidden]) { display: none; }
+
+    .card {
+      display: grid;
+      grid-template-areas:
+        "media"
+        "content";
+      height: 100%;
+      overflow: hidden;
+      background: var(--_bg);
+      border: 2px solid var(--_border);
+      border-radius: var(--_radius);
+      box-shadow: var(--_shadow);
+      text-align: center;
+      position: relative;
+      transition: box-shadow 0.3s, translate 0.3s;
+    }
+
+    .media {
+      grid-area: media;
+      aspect-ratio: 16 / 9;
+      background: var(--_muted);
+      overflow: hidden;
+    }
+    .media ::slotted(img) {
+      display: block;
+      width: 100%;
+      height: 100%;
+      object-fit: cover;
+    }
+
+    .content {
+      grid-area: content;
+      display: flex;
+      flex-direction: column;
+      gap: 10px;
+      padding: var(--_pad);
+    }
+
+    .badge {
+      position: absolute;
+      inset-block-start: 12px;
+      inset-inline-start: 12px;
+      padding: 2px 10px;
+      border-radius: 999px;
+      background: var(--_accent);
+      color: var(--_heading);
+      font-size: 0.75rem;
+      font-weight: 700;
+      letter-spacing: 0.05em;
+      text-transform: uppercase;
+    }
+
+    .title { color: var(--_heading); }
+    .title ::slotted(*) { font-size: 1.17em; line-height: 1.3; }
+
+    .body { flex: 1; }
+
+    .footer {
