+      flex-wrap: wrap;
+      gap: 10px 15px;
+      align-items: center;
+      justify-content: center;
+    }
+    .footer ::slotted([slot="price"]) {
+      font-weight: 700;
+      color: var(--_heading);
+    }
+  }
+
+  @layer variants {
+    :host([variant="featured"]) {
+      --_border: var(--_accent);
+      --_shadow: var(--drink-card-shadow, 0 6px 18px rgb(78 52 46 / 0.2));
