@@ -0,0 +1,315 @@
+/**
+ * <drink-card> — encapsulated card for the "Seasonal Favorites" menu.
+ *
+ * Theme inheritance
+ *   CSS custom properties pierce the shadow boundary, so the card reads the
+ *   site's tokens (--primary, --secondary, --accent, --text, --light) and also
+ *   accepts component-scoped overrides (--drink-card-*) from the page.
+ *
+ * Attributes
+ *   variant       "default" | "featured" | "limited" | "compact"
+ *   href          destination for the internal action link
+ *   action-label  text of the action link (default "View Details")
+ *
+ * Slots (projected content — styled by the page like any light-DOM content)
+ *   media         an <img> (or <picture>) for the drink
+ *   badge         small label, e.g. "New" or "Limited"
+ *   title         the drink name (usually an <h3>)
+ *   (default)     description copy
+ *   price         price / size info
+ *
+ * Parts (internal elements the page may style via ::part())
+ *   card, media, badge, body, title, description, footer, price, action
+ *
+ * Internal style priority (lowest → highest)
+ *   @layer reset, tokens, base, layout, variants, states
+ */
+
+const sheetText = /* css */ `
+@layer reset, tokens, base, layout, variants, states;
+
+/* ---------- reset: neutralise UA defaults inside the shadow tree ---------- */
+@layer reset {
+  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
+  [hidden] { display: none !important; }
+}
+
+/* ---------- tokens: map inherited site theme → component tokens ---------- */
+@layer tokens {
+  :host {
+    --_bg:        var(--drink-card-bg, #fff);
+    --_fg:        var(--drink-card-fg, var(--text, #3e2723));
+    --_heading:   var(--drink-card-heading, var(--primary, #4e342e));
+    --_accent:    var(--drink-card-accent, var(--accent, #ffab40));
+    --_muted:     var(--drink-card-muted, var(--secondary, #d7ccc8));
+    --_btn-bg:    var(--drink-card-button-bg, var(--primary, #4e342e));
+    --_btn-fg:    var(--drink-card-button-fg, var(--light, #fafafa));
+    --_btn-hover: var(--drink-card-button-hover, var(--text, #3e2723));
+    --_radius:    var(--drink-card-radius, 8px);
+    --_pad:       var(--drink-card-padding, 20px);
+    --_shadow:    var(--drink-card-shadow, 0 2px 5px rgb(0 0 0 / 0.1));
+    --_shadow-hover: 0 10px 24px rgb(0 0 0 / 0.14);
+    --_border:    transparent;
+    --_media-ratio: 16 / 10;
+  }
+}
+
+/* ---------- base: host box + element defaults ---------- */
+@layer base {
+  :host {
+    display: block;
+    /* each card is its own size container → layout follows the card, not the viewport */
+    container: drink-card / inline-size;
+    color: var(--_fg);
+    font: inherit;
+    min-width: 0;
+  }
+
+  .card {
+    position: relative;
+    height: 100%;
+    background: var(--_bg);
+    border: 2px solid var(--_border);
+    border-radius: var(--_radius);
+    box-shadow: var(--_shadow);
+    overflow: hidden;
+    text-align: center;
+    transition: box-shadow 0.25s ease, transform 0.25s ease;
+  }
+
+  .media { position: relative; background: var(--_muted); }
+  .media:not(.has-content) { display: none; }
+
+  ::slotted([slot="media"]) {
+    display: block;
+    width: 100%;
+    height: 100%;
+    aspect-ratio: var(--_media-ratio);
+    object-fit: cover;
+  }
+
+  .badge {
+    position: absolute;
+    top: 12px;
+    left: 12px;
+    z-index: 1;
+    padding: 2px 10px;
+    border-radius: 999px;
+    background: var(--_accent);
+    color: var(--_heading);
+    font-size: 0.75rem;
+    font-weight: 700;
+    letter-spacing: 0.05em;
+    text-transform: uppercase;
+  }
+  .badge:not(.has-content) { display: none; }
+
+  .title { color: var(--_heading); margin-bottom: 10px; }
+  ::slotted([slot="title"]) {
+    margin: 0;
+    color: inherit;
+    font-size: clamp(1.1rem, 0.9rem + 2cqi, 1.6rem);
+    line-height: 1.25;
+  }
+
+  .description ::slotted(*) { margin: 0; }
+
+  .price { font-weight: 700; color: var(--_heading); }
+  .price:not(.has-content) { display: none; }
+
+  .action {
+    display: inline-block;
+    background: var(--_btn-bg);
+    color: var(--_btn-fg);
+    padding: 10px 20px;
+    border-radius: 5px;
+    text-decoration: none;
+    transition: background 0.3s, color 0.3s;
+  }
+  .action:focus-visible { outline: 3px solid var(--_accent); outline-offset: 2px; }
+}
+
+/* ---------- layout: responds to the card's own inline size ---------- */
+@layer layout {
+  .card { display: flex; flex-direction: column; }
+  .body {
+    display: flex;
+    flex-direction: column;
+    flex: 1;
+    gap: 6px;
+    padding: var(--_pad);
+  }
+  .description { flex: 1; }
+  .footer {
+    display: flex;
+    flex-wrap: wrap;
+    align-items: center;
+    justify-content: center;
+    gap: 10px 16px;
+    margin-top: 15px;
+  }
+
+  /* Narrow cards: tighten spacing, full-width action */
+  @container drink-card (max-width: 239px) {
+    .body { --_pad: 14px; }
+    .footer { flex-direction: column; align-items: stretch; }
+    .action { text-align: center; }
+  }
+
+  /* Wide cards: media beside the copy */
+  @container drink-card (min-width: 520px) {
+    .card {
+      display: grid;
+      grid-template-columns: minmax(200px, 42%) 1fr;
+      text-align: start;
+    }
+    .media { height: 100%; }
+    ::slotted([slot="media"]) { aspect-ratio: auto; min-height: 100%; }
+    .body { justify-content: center; padding: calc(var(--_pad) * 1.5); }
+    .footer { justify-content: space-between; }
+  }
+
+  /* Very wide cards: roomier copy */
+  @container drink-card (min-width: 800px) {
+    .card { grid-template-columns: 1fr 1fr; }
+    .description { font-size: 1.1rem; max-width: 45ch; }
+  }
+}
+
+/* ---------- variants: host adjusts its own outer styling ---------- */
+@layer variants {
+  :host([variant="featured"]) {
+    --_bg: var(--drink-card-bg, var(--primary, #4e342e));
+    --_fg: var(--drink-card-fg, var(--light, #fafafa));
+    --_heading: var(--drink-card-heading, var(--light, #fafafa));
+    --_btn-bg: var(--drink-card-button-bg, var(--accent, #ffab40));
+    --_btn-fg: var(--drink-card-button-fg, var(--primary, #4e342e));
+    --_btn-hover: var(--drink-card-button-hover, #ffc77a);
+    --_shadow: var(--drink-card-shadow, 0 8px 24px rgb(62 39 35 / 0.3));
+  }
+  :host([variant="featured"]) .price { color: var(--_accent); }
+
+  :host([variant="limited"]) {
+    --_border: var(--_accent);
+    --_bg: var(--drink-card-bg, color-mix(in srgb, var(--accent, #ffab40) 8%, #fff));
+  }
+  :host([variant="limited"]) .card {
+    background-image: repeating-linear-gradient(
+      -45deg, transparent 0 14px,
+      color-mix(in srgb, var(--_accent) 6%, transparent) 14px 28px);
+  }
+
+  :host([variant="compact"]) {
+    --_pad: var(--drink-card-padding, 12px);
+    --_media-ratio: 3 / 1;
+    font-size: 0.9rem;
+  }
+}
+
+/* ---------- states: highest internal priority ---------- */
+@layer states {
+  :host(:hover) .card,
+  :host(:focus-within) .card {
+    box-shadow: var(--_shadow-hover);
+    transform: translateY(-3px);
+  }
+  .action:hover { background: var(--_btn-hover); }
+
+  @media (prefers-reduced-motion: reduce) {
+    .card, .action { transition: none; }
+    :host(:hover) .card, :host(:focus-within) .card { transform: none; }
+  }
+}
+`;
+
+const template = document.createElement('template');
+template.innerHTML = /* html */ `
+  <article class="card" part="card">
+    <div class="media" part="media">
+      <span class="badge" part="badge"><slot name="badge"></slot></span>
+      <slot name="media"></slot>
+    </div>
+    <div class="body" part="body">
+      <div class="title" part="title"><slot name="title"></slot></div>
+      <div class="description" part="description"><slot></slot></div>
+      <div class="footer" part="footer">
+        <span class="price" part="price"><slot name="price"></slot></span>
+        <a class="action" part="action" href="#"><span class="action-label">View Details</span></a>
+      </div>
+    </div>
+  </article>
+`;
+
+// One parsed stylesheet shared by every instance (falls back to <style>).
+let sharedSheet = null;
+if ('adoptedStyleSheets' in Document.prototype && 'replaceSync' in CSSStyleSheet.prototype) {
+  sharedSheet = new CSSStyleSheet();
+  sharedSheet.replaceSync(sheetText);
+}
+
+class DrinkCard extends HTMLElement {
+  static observedAttributes = ['href', 'action-label'];
+
+  #action;
+  #label;
+
+  constructor() {
+    super();
+    const root = this.attachShadow({ mode: 'open' });
+    if (sharedSheet) {
+      root.adoptedStyleSheets = [sharedSheet];
+    } else {
+      const style = document.createElement('style');
+      style.textContent = sheetText;
+      root.append(style);
+    }
+    root.append(template.content.cloneNode(true));
+
+    this.#action = root.querySelector('.action');
+    this.#label = root.querySelector('.action-label');
+
+    // Hide wrappers whose slots receive nothing; refresh accessible name on title changes.
+    root.querySelectorAll('slot').forEach((slot) => {
+      slot.addEventListener('slotchange', () => this.#syncSlot(slot));
+    });
+  }
+
+  connectedCallback() {
+    this.shadowRoot.querySelectorAll('slot').forEach((slot) => this.#syncSlot(slot));
+    this.#render();
+  }
+
+  attributeChangedCallback() {
+    this.#render();
+  }
+
+  #syncSlot(slot) {
+    const wrapper = slot.name === 'media' ? slot.parentElement : slot.closest('[part]');
+    const filled = slot.assignedNodes({ flatten: true })
+      .some((n) => n.nodeType === Node.ELEMENT_NODE || n.textContent.trim());
+    wrapper?.classList.toggle('has-content', filled);
+    if (slot.name === 'title') this.#render();
+  }
+
+  #render() {
+    if (!this.#action) return;
+    const href = this.getAttribute('href');
+    if (href) this.#action.setAttribute('href', href);
+    else this.#action.removeAttribute('href');
+    this.#action.hidden = !href;
+
+    const label = this.getAttribute('action-label') || 'View Details';
+    this.#label.textContent = label;
+
+    // Give each repeated "View Details" link a unique accessible name.
+    const title = this.querySelector('[slot="title"]')?.textContent.trim();
+    if (title) this.#action.setAttribute('aria-label', `${label}: ${title}`);
+    else this.#action.removeAttribute('aria-label');
+  }
+}
+
+if (!customElements.get('drink-card')) {
+  customElements.define('drink-card', DrinkCard);
+}
+
+export { DrinkCard };
