+    (() => {
+      const menu = document.getElementById('coffee-menu');
+      const tablist = menu.querySelector('[role="tablist"]');
+      const tabs = [...tablist.querySelectorAll('[role="tab"]')];
+      const panelFor = tab => menu.querySelector(`[role="tabpanel"][aria-labelledby="${tab.id}"]`);
+
+      function select(selected) {
+        for (const tab of tabs) {
+          const isSelected = tab === selected;
+          tab.setAttribute('aria-selected', String(isSelected));
+          tab.toggleAttribute('focusgroupstart', isSelected);
+          const panel = panelFor(tab);
+          if (isSelected) panel.removeAttribute('hidden');
+          else panel.hidden = 'until-found';
+        }
+        // Scroll only the tab bar so the selected tab (and a peek of its neighbour) is visible
+        selected.scrollIntoView({ block: 'nearest', inline: 'nearest', container: 'nearest' });
+      }
+
+      // Selection follows focus (arrow keys via focusgroup), plus click for browsers
+      // that don't focus buttons on click.
+      tablist.addEventListener('focusin', e => {
+        const tab = e.target.closest('[role="tab"]');
+        if (tab && tab.getAttribute('aria-selected') !== 'true') select(tab);
+      });
+      tablist.addEventListener('click', e => {
+        const tab = e.target.closest('[role="tab"]');
+        if (tab) select(tab);
+      });
+
+      // Find-in-page revealed a hidden panel: sync the tab selection.
+      for (const tab of tabs) {
+        panelFor(tab).addEventListener('beforematch', () => select(tab));
+      }
+    })();
+  </script>
