+  interface TranslatorCreateCoreOptions {
+    sourceLanguage: string;
+    targetLanguage: string;
+  }
+
+  interface TranslatorCreateOptions extends TranslatorCreateCoreOptions {
+    signal?: AbortSignal;
+    monitor?: (monitor: TranslatorCreateMonitor) => void;
+  }
+
+  interface Translator {
+    readonly sourceLanguage: string;
+    readonly targetLanguage: string;
+    translate(input: string, options?: { signal?: AbortSignal }): Promise<string>;
+    translateStreaming(input: string, options?: { signal?: AbortSignal }): ReadableStream<string>;
+    destroy(): void;
+  }
+
+  var Translator: {
+    availability(options: TranslatorCreateCoreOptions): Promise<TranslatorAvailability>;
+    create(options: TranslatorCreateOptions): Promise<Translator>;
+  };
