index 0000000..b1f89f5
--- /dev/null
+++ b/src/components/TranslateButton.tsx
@@ -0,0 +1,416 @@
+import { useEffect, useId, useRef, useState } from 'react';
+import { LanguageIcon } from '@heroicons/react/24/outline';
+
+/**
+ * On-device article translation using the built-in Translator API.
+ *
+ * Translates every element marked with `data-translatable` on the current page
+ * (article headline, lead, body, captions and teaser titles/summaries). Only
+ * text nodes are rewritten so links, emphasis and other markup are preserved.
+ * Originals are kept in memory so readers can switch languages or restore the
+ * original text at any time. Nothing leaves the device.
+ */
+
+const LANGUAGES: Record<string, string> = {
+  ar: 'العربية (Arabic)',
+  bg: 'Български (Bulgarian)',
+  bn: 'বাংলা (Bengali)',
+  cs: 'Čeština (Czech)',
+  da: 'Dansk (Danish)',
+  de: 'Deutsch (German)',
+  el: 'Ελληνικά (Greek)',
+  en: 'English',
+  es: 'Español (Spanish)',
+  fi: 'Suomi (Finnish)',
+  fr: 'Français (French)',
+  he: 'עברית (Hebrew)',
+  hi: 'हिन्दी (Hindi)',
+  hr: 'Hrvatski (Croatian)',
+  hu: 'Magyar (Hungarian)',
+  id: 'Bahasa Indonesia (Indonesian)',
+  it: 'Italiano (Italian)',
+  ja: '日本語 (Japanese)',
+  kn: 'ಕನ್ನಡ (Kannada)',
+  ko: '한국어 (Korean)',
+  lt: 'Lietuvių (Lithuanian)',
+  mr: 'मराठी (Marathi)',
+  nl: 'Nederlands (Dutch)',
+  no: 'Norsk (Norwegian)',
+  pl: 'Polski (Polish)',
+  pt: 'Português (Portuguese)',
+  ro: 'Română (Romanian)',
+  ru: 'Русский (Russian)',
+  sk: 'Slovenčina (Slovak)',
+  sl: 'Slovenščina (Slovenian)',
+  sv: 'Svenska (Swedish)',
+  ta: 'தமிழ் (Tamil)',
+  te: 'తెలుగు (Telugu)',
+  th: 'ไทย (Thai)',
+  tr: 'Türkçe (Turkish)',
+  uk: 'Українська (Ukrainian)',
+  vi: 'Tiếng Việt (Vietnamese)',
+  zh: '中文 简体 (Chinese)',
+  'zh-Hant': '中文 繁體 (Chinese, Traditional)',
+};
+
+const RTL = new Set(['ar', 'he']);
+const STORAGE_KEY = 'dtt:translation';
+const SELECTOR = '[data-translatable]';
+const SKIP_TAGS = new Set(['SCRIPT', 'STYLE', 'CODE', 'PRE', 'KBD', 'SAMP', 'NOSCRIPT']);
+
+// Module-level state survives client-side (ClientRouter) navigations.
+const originals = new WeakMap<Text, string>();
+const translators = new Map<string, Promise<Translator>>();
+
+type Pair = { sourceLanguage: string; targetLanguage: string };
+type Status =
+  | { kind: 'idle' }
+  | { kind: 'checking' }
+  | { kind: 'downloading'; progress: number }
+  | { kind: 'translating'; done: number; total: number }
+  | { kind: 'translated'; lang: string }
+  | { kind: 'error'; message: string };
+
+const isSupported = () => typeof self !== 'undefined' && 'Translator' in self;
+
+function loadPreference(): Pair | null {
+  try {
+    const raw = localStorage.getItem(STORAGE_KEY);
+    const pair = raw ? (JSON.parse(raw) as Pair) : null;
+    if (pair && LANGUAGES[pair.sourceLanguage] && LANGUAGES[pair.targetLanguage]) return pair;
+  } catch {
+    /* ignore */
+  }
+  return null;
+}
+
+function savePreference(pair: Pair | null) {
+  try {
+    if (pair) localStorage.setItem(STORAGE_KEY, JSON.stringify(pair));
+    else localStorage.removeItem(STORAGE_KEY);
+  } catch {
+    /* ignore */
+  }
+}
+
+function defaultTarget(source: string) {
+  const preferred = (typeof navigator !== 'undefined' ? navigator.languages : []) ?? [];
+  for (const tag of preferred) {
+    const base = tag.split('-')[0];
+    const code = /^zh-(TW|HK|MO|Hant)/i.test(tag) ? 'zh-Hant' : base;
+    if (LANGUAGES[code] && code !== source) return code;
+  }
+  return source === 'es' ? 'en' : 'es';
+}
+
+function collectTextNodes(root: Element): Text[] {
+  const nodes: Text[] = [];
+  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
+    acceptNode(node) {
+      for (let el = node.parentElement; el && el !== root.parentElement; el = el.parentElement) {
+        if (SKIP_TAGS.has(el.tagName) || el.getAttribute('translate') === 'no') {
+          return NodeFilter.FILTER_REJECT;
+        }
+      }
+      const text = originals.get(node as Text) ?? node.nodeValue ?? '';
+      return /\p{L}/u.test(text) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT;
+    },
+  });
+  while (walker.nextNode()) nodes.push(walker.currentNode as Text);
+  return nodes;
+}
+
+function restorePage() {
+  for (const el of document.querySelectorAll<HTMLElement>(`${SELECTOR}[data-translated-lang]`)) {
+    for (const node of collectTextNodes(el)) {
+      const original = originals.get(node);
+      if (original !== undefined) node.nodeValue = original;
+    }
+    const originalLang = el.dataset.originalLang;
+    if (originalLang) el.lang = originalLang;
+    else el.removeAttribute('lang');
+    el.removeAttribute('dir');
+    delete el.dataset.translatedLang;
+    delete el.dataset.originalLang;
+  }
+}
+
+function getTranslator(pair: Pair, onProgress: (p: number) => void): Promise<Translator> {
+  const key = `${pair.sourceLanguage}>${pair.targetLanguage}`;
+  let promise = translators.get(key);
+  if (!promise) {
+    promise = Translator.create({
+      ...pair,
+      monitor(m) {
+        m.addEventListener('downloadprogress', (e) => onProgress(e.loaded));
+      },
+    });
+    // Drop failed attempts so the user can retry (e.g. after a missing gesture).
+    promise.catch(() => translators.delete(key));
+    translators.set(key, promise);
+  }
+  return promise;
+}
+
+export default function TranslateButton() {
+  const panelId = useId();
+  const sourceId = useId();
+  const targetId = useId();
+  const buttonRef = useRef<HTMLButtonElement>(null);
+  const panelRef = useRef<HTMLDivElement>(null);
+  const abortRef = useRef<AbortController | null>(null);
+
+  const [supported, setSupported] = useState<boolean | null>(null);
+  const [source, setSource] = useState('en');
+  const [target, setTarget] = useState('es');
+  const [status, setStatus] = useState<Status>({ kind: 'idle' });
+
+  async function translatePage(pair: Pair, { auto = false } = {}) {
+    abortRef.current?.abort();
+    const controller = new AbortController();
+    abortRef.current = controller;
+    const { signal } = controller;
+
+    try {
+      setStatus({ kind: 'checking' });
+      const availability = await Translator.availability(pair);
+      if (signal.aborted) return;
+      if (availability === 'unavailable') {
+        setStatus({
+          kind: 'error',
+          message: `${LANGUAGES[pair.sourceLanguage]} → ${LANGUAGES[pair.targetLanguage]} isn't available on this device.`,
+        });
+        return;
+      }
+      // Downloading a language pack requires a user gesture; never auto-start it.
+      if (auto && availability !== 'available') {
+        setStatus({ kind: 'idle' });
+        return;
+      }
+      if (availability !== 'available') setStatus({ kind: 'downloading', progress: 0 });
+
+      const translator = await getTranslator(pair, (progress) => {
+        if (!signal.aborted) setStatus({ kind: 'downloading', progress });
+      });
+      if (signal.aborted) return;
+
+      // Always translate from the original text, never from a previous translation.
+      restorePage();
+      const elements = [...document.querySelectorAll<HTMLElement>(SELECTOR)];
+      const work = elements.map((el) => ({ el, nodes: collectTextNodes(el) }));
+      const total = work.reduce((n, w) => n + w.nodes.length, 0);
+      const cache = new Map<string, Promise<string>>();
+      let done = 0;
+      setStatus({ kind: 'translating', done, total });
+
+      for (const { el, nodes } of work) {
+        if (!el.isConnected) continue;
+        if (el.lang) el.dataset.originalLang = el.lang;
+        el.dataset.translatedLang = pair.targetLanguage;
+        // Accessibility: translated content must declare its language.
+        el.lang = pair.targetLanguage;
+        el.dir = RTL.has(pair.targetLanguage) ? 'rtl' : 'ltr';
+
+        for (const node of nodes) {
+          const original = originals.get(node) ?? node.nodeValue ?? '';
+          originals.set(node, original);
+          const [, lead, body, trail] = original.match(/^(\s*)([\s\S]*?)(\s*)$/)!;
+          let pending = cache.get(body);
+          if (!pending) {
+            pending = translator.translate(body, { signal });
+            cache.set(body, pending);
+          }
+          const translated = await pending;
+          if (signal.aborted) return;
+          node.nodeValue = `${lead}${translated}${trail}`;
+          done++;
+          if (done % 5 === 0 || done === total) setStatus({ kind: 'translating', done, total });
+        }
+      }
+
+      savePreference(pair);
+      setStatus({ kind: 'translated', lang: pair.targetLanguage });
+    } catch (err) {
+      if (signal.aborted) return;
+      console.error('Translation failed', err);
+      restorePage();
+      const message =
+        err instanceof DOMException && err.name === 'NotAllowedError'
+          ? 'Click "Translate" to download the language pack.'
+          : 'Translation failed. Please try again.';
+      setStatus(auto ? { kind: 'idle' } : { kind: 'error', message });
+    }
+  }
+
+  function showOriginal() {
+    abortRef.current?.abort();
+    restorePage();
+    savePreference(null);
+    setStatus({ kind: 'idle' });
+  }
+
+  useEffect(() => {
+    const ok = isSupported();
+    setSupported(ok);
+    const pref = loadPreference();
+    if (pref) {
+      setSource(pref.sourceLanguage);
+      setTarget(pref.targetLanguage);
+    } else {
+      setTarget(defaultTarget('en'));
+    }
+    // Re-apply the reader's chosen language on new pages when the model is already on-device.
+    if (ok && pref) translatePage(pref, { auto: true });
+    return () => abortRef.current?.abort();
+    // eslint-disable-next-line react-hooks/exhaustive-deps
+  }, []);
+
+  // Position the popover (top layer) beneath its trigger button.
+  function placePanel() {
+    const button = buttonRef.current;
+    const panel = panelRef.current;
+    if (!button || !panel) return;
+    const rect = button.getBoundingClientRect();
+    const width = Math.min(320, document.documentElement.clientWidth - 16);
+    const left = Math.max(8, Math.min(rect.left, document.documentElement.clientWidth - width - 8));
+    panel.style.width = `${width}px`;
+    panel.style.left = `${left + window.scrollX}px`;
+    panel.style.top = `${rect.bottom + window.scrollY + 6}px`;
+  }
+
+  useEffect(() => {
+    const panel = panelRef.current;
+    if (!panel) return;
+    const onToggle = (e: Event) => {
+      if ((e as ToggleEvent).newState === 'open') placePanel();
+    };
+    panel.addEventListener('beforetoggle', onToggle);
+    return () => panel.removeEventListener('beforetoggle', onToggle);
+  }, []);
+
+  const busy = status.kind === 'checking' || status.kind === 'downloading' || status.kind === 'translating';
+  const translatedLang = status.kind === 'translated' ? status.lang : null;
+
+  let statusText = '';
+  switch (status.kind) {
+    case 'checking':
+      statusText = 'Checking language availability…';
+      break;
+    case 'downloading':
+      statusText = `Downloading language pack… ${Math.round(status.progress * 100)}%`;
+      break;
+    case 'translating':
+      statusText = `Translating… ${status.done} of ${status.total}`;
+      break;
+    case 'translated':
+      statusText = `Translated to ${LANGUAGES[status.lang]} on your device.`;
+      break;
+    case 'error':
+      statusText = status.message;
+      break;
+  }
+
+  return (
+    <>
+      <button
+        ref={buttonRef}
+        type="button"
+        popoverTarget={panelId}
+        aria-label={translatedLang ? `Translate page (currently ${LANGUAGES[translatedLang]})` : 'Translate page'}
+        className="p-1 flex items-center gap-1 text-gray-700 hover:text-amber-500"
+      >
+        <LanguageIcon className={`h-6 w-6 ${translatedLang ? 'text-amber-500' : ''}`} aria-hidden="true" />
+        {translatedLang && (
+          <span className="text-[10px] font-bold uppercase leading-none bg-amber-400 text-gray-900 rounded px-1 py-0.5">
+            {translatedLang}
+          </span>
+        )}
+      </button>
+
+      <div
+        ref={panelRef}
+        id={panelId}
+        popover="auto"
+        className="absolute m-0 inset-auto p-4 bg-white text-gray-800 rounded-md shadow-lg border border-gray-200 font-inter"
+      >
+        <h2 className="text-sm font-semibold mb-1">Translate articles</h2>
+        <p className="text-xs text-gray-500 mb-3">
+          Headlines, teasers and article text are translated privately in your browser.
+        </p>
+
+        {supported === false ? (
+          <p className="text-xs text-gray-700 bg-gray-100 rounded p-2" role="note">
+            On-device translation isn't supported in this browser. Try a recent desktop version of Chrome or Edge.
+          </p>
+        ) : (
+          <form
+            onSubmit={(e) => {
+              e.preventDefault();
+              if (source === target) {
+                showOriginal();
+                return;
+              }
+              translatePage({ sourceLanguage: source, targetLanguage: target });
+            }}
+          >
+            <div className="grid grid-cols-[auto_1fr] items-center gap-x-2 gap-y-2 text-xs">
+              <label htmlFor={sourceId} className="font-medium">From</label>
+              <select
+                id={sourceId}
+                value={source}
+                disabled={busy}
+                onChange={(e) => setSource(e.target.value)}
+                className="border border-gray-300 rounded px-2 py-1 bg-white"
+              >
+                {Object.entries(LANGUAGES).map(([code, name]) => (
+                  <option key={code} value={code}>{name}</option>
+                ))}
+              </select>
+              <label htmlFor={targetId} className="font-medium">To</label>
+              <select
+                id={targetId}
+                value={target}
+                disabled={busy}
+                onChange={(e) => setTarget(e.target.value)}
+                className="border border-gray-300 rounded px-2 py-1 bg-white"
+              >
+                {Object.entries(LANGUAGES).map(([code, name]) => (
+                  <option key={code} value={code}>{name}</option>
+                ))}
+              </select>
+            </div>
+
+            <div className="flex gap-2 mt-3">
+              <button
+                type="submit"
+                disabled={busy || supported === null}
+                className="flex-1 bg-gray-800 text-white text-xs font-semibold py-2 px-3 rounded hover:bg-gray-700 disabled:opacity-50"
+              >
+                Translate
+              </button>
+              <button
+                type="button"
+                onClick={showOriginal}
+                disabled={!translatedLang && !busy}
+                className="flex-1 bg-gray-200 text-gray-800 text-xs font-semibold py-2 px-3 rounded hover:bg-gray-300 disabled:opacity-50"
+              >
+                {busy ? 'Cancel' : 'Show original'}
+              </button>
+            </div>
+
+            {status.kind === 'downloading' && (
+              <progress className="w-full mt-3 h-1.5 accent-amber-500" max={1} value={status.progress} aria-label="Language pack download progress" />
+            )}
+          </form>
+        )}
+
+        <p
+          role="status"
+          className={`text-xs mt-2 min-h-4 ${status.kind === 'error' ? 'text-red-700' : 'text-gray-600'}`}
+        >
+          {statusText}
+        </p>
+      </div>
+    </>
+  );
+}
