diff --git a/src/components/TranslateButton.tsx b/src/components/TranslateButton.tsx
new file mode 100644
index 0000000..8b62d13
--- /dev/null
+++ b/src/components/TranslateButton.tsx
@@ -0,0 +1,315 @@
+import React, { useCallback, useEffect, useId, useRef, useState } from 'react';
+import { LanguageIcon, XMarkIcon } from '@heroicons/react/24/outline';
+import {
+  LANGUAGES,
+  detectSourceLanguage,
+  getAvailability,
+  getSavedTarget,
+  hasTranslatableContent,
+  isTranslatorSupported,
+  languageName,
+  restoreOriginal,
+  saveTarget,
+  translatePage,
+} from '../utils/translation';
+
+type Status =
+  | { kind: 'idle' }
+  | { kind: 'checking' }
+  | { kind: 'downloading'; progress: number }
+  | { kind: 'translating'; done: number; total: number }
+  | { kind: 'translated'; source: string; target: string }
+  | { kind: 'error'; message: string };
+
+const AUTO = 'auto';
+
+function defaultTarget(): string {
+  const preferred = (navigator.languages ?? [navigator.language]).map((l) => l.split('-')[0]);
+  const match = preferred.find((code) => code !== 'en' && LANGUAGES.some((l) => l.code === code));
+  return match ?? 'es';
+}
+
+/**
+ * Header control that translates headlines, teasers and article bodies
+ * on-device using the browser's built-in Translator API.
+ */
+export default function TranslateButton() {
+  const [supported, setSupported] = useState<boolean | null>(null);
+  const [isOpen, setIsOpen] = useState(false);
+  const [source, setSource] = useState<string>(AUTO);
+  const [target, setTarget] = useState<string>('es');
+  const [status, setStatus] = useState<Status>({ kind: 'idle' });
+  const abortRef = useRef<AbortController | null>(null);
+  const panelRef = useRef<HTMLDivElement>(null);
+  const buttonRef = useRef<HTMLButtonElement>(null);
+  const panelId = useId();
+
+  const run = useCallback(async (sourceChoice: string, targetLanguage: string, { automatic = false } = {}) => {
+    abortRef.current?.abort();
+    const controller = new AbortController();
+    abortRef.current = controller;
+    const { signal } = controller;
+
+    try {
+      setStatus({ kind: 'checking' });
+      const sourceLanguage = sourceChoice === AUTO ? await detectSourceLanguage() : sourceChoice;
+      signal.throwIfAborted();
+
+      if (sourceLanguage === targetLanguage) {
+        restoreOriginal();
+        setStatus({ kind: 'translated', source: sourceLanguage, target: targetLanguage });
+        return;
+      }
+
+      const availability = await getAvailability(sourceLanguage, targetLanguage);
+      signal.throwIfAborted();
+      if (availability === 'unavailable') {
+        throw new Error(
+          `On-device translation from ${languageName(sourceLanguage)} to ${languageName(targetLanguage)} isn't available in this browser.`,
+        );
+      }
+      // Restoring a saved preference on page load has no user gesture, so we
+      // can't trigger a model download – wait for the reader to click instead.
+      if (automatic && availability !== 'available') {
+        setStatus({ kind: 'idle' });
+        return;
+      }
+
+      await translatePage({
+        sourceLanguage,
+        targetLanguage,
+        signal,
+        onDownloadProgress: (progress) => setStatus({ kind: 'downloading', progress }),
+        onProgress: (done, total) => setStatus({ kind: 'translating', done, total }),
+      });
+      signal.throwIfAborted();
+      setStatus({ kind: 'translated', source: sourceLanguage, target: targetLanguage });
+    } catch (error) {
+      if (signal.aborted) return;
+      console.error('[translate]', error);
+      const message =
+        error instanceof DOMException && error.name === 'NotAllowedError'
+          ? 'The language model needs to be downloaded first. Click “Translate” again to start the download.'
+          : error instanceof Error
+            ? error.message
+            : 'Translation failed.';
+      setStatus({ kind: 'error', message });
+    }
+  }, []);
+
+  // Feature detection + re-apply the reader's saved language on every page.
+  useEffect(() => {
+    const isSupported = isTranslatorSupported();
+    setSupported(isSupported);
+    const saved = getSavedTarget();
+    setTarget(saved ?? defaultTarget());
+    if (isSupported && saved && hasTranslatableContent()) {
+      run(AUTO, saved, { automatic: true });
+    }
+    return () => abortRef.current?.abort();
+  }, [run]);
+
+  // Close on outside click / Escape.
+  useEffect(() => {
+    if (!isOpen) return;
+    const onPointerDown = (e: PointerEvent) => {
+      const t = e.target as Node;
+      if (!panelRef.current?.contains(t) && !buttonRef.current?.contains(t)) setIsOpen(false);
+    };
+    const onKeyDown = (e: KeyboardEvent) => {
+      if (e.key === 'Escape') {
+        setIsOpen(false);
+        buttonRef.current?.focus();
+      }
+    };
+    document.addEventListener('pointerdown', onPointerDown);
+    document.addEventListener('keydown', onKeyDown);
+    return () => {
+      document.removeEventListener('pointerdown', onPointerDown);
+      document.removeEventListener('keydown', onKeyDown);
+    };
+  }, [isOpen]);
+
+  const handleTranslate = (e: React.FormEvent) => {
+    e.preventDefault();
+    saveTarget(target);
+    run(source, target);
+  };
+
+  const handleShowOriginal = () => {
+    abortRef.current?.abort();
+    restoreOriginal();
+    saveTarget(null);
+    setStatus({ kind: 'idle' });
+  };
+
+  const busy = status.kind === 'checking' || status.kind === 'downloading' || status.kind === 'translating';
+  const isTranslated = status.kind === 'translated' && status.source !== status.target;
+
+  return (
+    <div className="relative">
+      <button
+        ref={buttonRef}
+        type="button"
+        onClick={() => setIsOpen((open) => !open)}
+        aria-expanded={isOpen}
+        aria-controls={panelId}
+        aria-label="Translate articles"
+        title="Translate articles"
+        className={`p-1 flex items-center gap-1 hover:text-amber-400 ${isTranslated ? 'text-amber-500' : 'text-gray-600'}`}
+      >
+        {busy ? (
+          <span className="w-6 h-6 flex items-center justify-center">
+            <span className="w-5 h-5 border-2 border-amber-400 border-t-transparent rounded-full animate-spin" />
+          </span>
+        ) : (
+          <LanguageIcon className="h-6 w-6" />
+        )}
+        {isTranslated && (
+          <span className="text-xs font-semibold uppercase">{status.target}</span>
+        )}
+      </button>
+
+      {isOpen && (
+        <div
+          ref={panelRef}
+          id={panelId}
+          role="dialog"
+          aria-label="Translate articles"
+          className="absolute left-0 top-full mt-2 z-50 w-72 bg-white border border-gray-200 rounded-md shadow-lg p-4 text-sm text-gray-800"
+        >
+          <div className="flex items-start justify-between mb-2">
+            <div>
+              <h2 className="font-semibold text-base">Translate articles</h2>
+              <p className="text-xs text-gray-500">Runs privately on your device.</p>
+            </div>
+            <button
+              type="button"
+              onClick={() => setIsOpen(false)}
+              className="p-1 -mr-1 -mt-1 text-gray-400 hover:text-gray-700"
+              aria-label="Close"
+            >
+              <XMarkIcon className="w-5 h-5" />
+            </button>
+          </div>
+
+          {supported === false ? (
+            <p className="text-gray-600 bg-gray-50 border border-gray-200 rounded p-3">
+              Your browser doesn't support on-device translation yet. Try a recent version of Chrome on desktop
+              (built-in Translator API).
+            </p>
+          ) : (
+            <form onSubmit={handleTranslate} className="space-y-3">
+              <label className="block">
+                <span className="block text-xs font-semibold text-gray-600 mb-1">From</span>
+                <select
+                  value={source}
+                  onChange={(e) => setSource(e.target.value)}
+                  disabled={busy}
+                  className="w-full border border-gray-300 rounded px-2 py-1.5 bg-white"
+                >
+                  <option value={AUTO}>Detect language</option>
+                  {LANGUAGES.map((l) => (
+                    <option key={l.code} value={l.code}>
+                      {l.name}
+                    </option>
+                  ))}
+                </select>
+              </label>
+              <label className="block">
+                <span className="block text-xs font-semibold text-gray-600 mb-1">To</span>
+                <select
+                  value={target}
+                  onChange={(e) => setTarget(e.target.value)}
+                  disabled={busy}
+                  className="w-full border border-gray-300 rounded px-2 py-1.5 bg-white"
+                >
+                  {LANGUAGES.map((l) => (
+                    <option key={l.code} value={l.code}>
+                      {l.name}
+                    </option>
+                  ))}
+                </select>
+              </label>
+
+              <div className="flex gap-2">
+                <button
+                  type="submit"
+                  disabled={busy || supported === null}
+                  className="flex-1 bg-gray-800 text-white text-xs font-semibold py-2 px-3 rounded hover:bg-gray-700 disabled:opacity-50"
+                >
+                  Translate
+                </button>
+                {(isTranslated || busy) && (
+                  <button
+                    type="button"
+                    onClick={handleShowOriginal}
+                    className="flex-1 bg-gray-100 text-gray-800 text-xs font-semibold py-2 px-3 rounded hover:bg-gray-200"
+                  >
+                    {busy ? 'Cancel' : 'Show original'}
+                  </button>
+                )}
+              </div>
+
+              <StatusLine status={status} />
+            </form>
+          )}
+        </div>
+      )}
+    </div>
+  );
+}
+
+function StatusLine({ status }: { status: Status }) {
+  let content: React.ReactNode = null;
+  switch (status.kind) {
+    case 'checking':
+      content = 'Preparing translation…';
+      break;
+    case 'downloading':
+      content = (
+        <>
+          <span>Downloading language model… {Math.round(status.progress * 100)}%</span>
+          <Progress value={status.progress} />
+        </>
+      );
+      break;
+    case 'translating':
+      content = (
+        <>
+          <span>
+            Translating… {status.done}/{status.total}
+          </span>
+          <Progress value={status.total ? status.done / status.total : 0} />
+        </>
+      );
+      break;
+    case 'translated':
+      content =
+        status.source === status.target
+          ? `This page is already in ${languageName(status.target)}.`
+          : `Translated from ${languageName(status.source)} to ${languageName(status.target)}.`;
+      break;
+    case 'error':
+      return (
+        <p role="alert" className="text-xs text-red-700">
+          {status.message}
+        </p>
+      );
+    default:
+      return null;
+  }
+  return (
+    <div role="status" aria-live="polite" className="text-xs text-gray-600 space-y-1">
+      {content}
+    </div>
+  );
+}
+
+function Progress({ value }: { value: number }) {
+  return (
+    <div className="h-1 w-full bg-gray-200 rounded overflow-hidden">
+      <div className="h-full bg-amber-400 transition-[width]" style={{ width: `${Math.min(100, value * 100)}%` }} />
+    </div>
+  );
+}
