diff --git a/src/utils/translation.ts b/src/utils/translation.ts
new file mode 100644
index 0000000..a20f482
--- /dev/null
+++ b/src/utils/translation.ts
@@ -0,0 +1,304 @@
+/**
+ * On-device article translation using Chrome's built-in AI APIs
+ * (Translator + LanguageDetector). Nothing leaves the reader's browser.
+ *
+ * Any element marked with `data-translatable` (headlines, teaser summaries,
+ * article bodies, captions, ...) is translated in place, text node by text
+ * node, so links and inline formatting are preserved. The original text is
+ * remembered so the page can always be restored or re-translated from source.
+ */
+
+export const TRANSLATABLE_SELECTOR = '[data-translatable]';
+const STORAGE_KEY = 'devtools-times:translation-target';
+const SKIP_TAGS = new Set(['SCRIPT', 'STYLE', 'NOSCRIPT', 'CODE', 'PRE', 'KBD', 'SAMP', 'svg']);
+const CONCURRENCY = 4;
+
+export const LANGUAGES: { code: string; name: string }[] = [
+  { code: 'en', name: 'English' },
+  { code: 'es', name: 'Español' },
+  { code: 'fr', name: 'Français' },
+  { code: 'de', name: 'Deutsch' },
+  { code: 'it', name: 'Italiano' },
+  { code: 'pt', name: 'Português' },
+  { code: 'nl', name: 'Nederlands' },
+  { code: 'pl', name: 'Polski' },
