+      '<a href="/menu/seasonal" class="btn">View Details</a>' +
+    '</div>',
+
+    '<div class="card">' +
+      '<img class="card-img" src="' + IMG_BASE + '1510707577719-ae7c14805e3a' + IMG_PARAMS + '"' +
+      ' alt="Fresh espresso shot pouring into a cup" width="600" height="400" loading="lazy">' +
+      '<h3>Dark Roast Espresso</h3>' +
+      '<p>Bold, smokey, and perfect for a morning boost.</p>' +
