+/* ------------------------------------------------------------------
+ * Semantic surface context
+ * Sections opt in by setting --surface; teaser components react to it
+ * via container style queries without knowing which section they're in.
+ * ------------------------------------------------------------------ */
+.surface-featured {
+  --surface: featured;
+}
+
+/* Default (subtle) presentation */
+.teaser-badge {
+  display: none;
+  align-self: flex-start;
+  margin-block-end: 0.5rem;
+  padding: 0.125rem 0.5rem;
+  border-radius: 9999px;
+  background: var(--color-amber-400);
+  color: var(--color-gray-900);
+  font-size: 0.6875rem;
+  font-weight: 700;
+  letter-spacing: 0.08em;
+  text-transform: uppercase;
+}
+
+.teaser-action {
+  display: inline-flex;
+  align-items: center;
+  gap: 0.25rem;
+  align-self: flex-start;
+  margin-block-start: 0.75rem;
+  padding: 0.375rem 0.875rem;
+  border: 1px solid var(--color-gray-300);
+  border-radius: 0.375rem;
+  background: transparent;
+  color: var(--color-gray-800);
+  font-size: 0.875rem;
+  font-weight: 600;
+  transition: background-color 150ms, border-color 150ms, color 150ms;
+}
+
+.teaser-action:hover {
+  border-color: var(--color-gray-900);
+}
+
+.teaser-action:focus-visible {
+  outline: 2px solid var(--color-amber-800);
+  outline-offset: 2px;
+}
+
+/* Fallback for browsers without container style queries.
+ * :where() keeps specificity equal so the style query below wins when supported. */
