+}
+/* ------------------------------------------------------------------
+ * Context-aware teasers
+ *
+ * A parent section declares its semantic context with
+ * `data-teaser-context="featured"` or `data-teaser-context="default"`.
+ * The context is expressed as inherited custom properties, so teaser
+ * cards and their action buttons always follow their *nearest*
+ * contextual ancestor (nested contexts work as expected) and need no
+ * per-instance props. Without any context the subtle default applies.
+ * ------------------------------------------------------------------ */
+@layer components {
+  [data-teaser-context="default"] {
+    --teaser-badge-display: none;
+    --teaser-action-bg: transparent;
+    --teaser-action-fg: var(--color-gray-900);
+    --teaser-action-border: var(--color-gray-300);
+    --teaser-action-hover-bg: var(--color-gray-100);
+    --teaser-action-hover-fg: var(--color-gray-900);
+    --teaser-action-hover-border: var(--color-gray-900);
+  }
+
+  [data-teaser-context="featured"] {
+    --teaser-badge-display: inline-flex;
+    --teaser-action-bg: var(--color-gray-900);
+    --teaser-action-fg: var(--color-white);
+    --teaser-action-border: var(--color-gray-900);
+    --teaser-action-hover-bg: var(--color-amber-400);
+    --teaser-action-hover-fg: var(--color-gray-900);
+    --teaser-action-hover-border: var(--color-amber-400);
+  }
+
+  .teaser-badge {
+    display: var(--teaser-badge-display, none);
+    align-items: center;
+    gap: 0.25rem;
+    width: fit-content;
+    padding: 0.125rem 0.5rem;
+    border-radius: 9999px;
+    background-color: var(--color-amber-400);
+    color: var(--color-gray-900);
+    font-size: 0.6875rem;
+    line-height: 1rem;
+    font-weight: 700;
+    letter-spacing: 0.08em;
+    text-transform: uppercase;
+  }
+
+  .teaser-action {
+    display: inline-flex;
+    align-items: center;
+    gap: 0.375rem;
+    padding: 0.375rem 0.875rem;
+    border: 1px solid var(--teaser-action-border, var(--color-gray-300));
+    border-radius: 0.375rem;
+    background-color: var(--teaser-action-bg, transparent);
+    color: var(--teaser-action-fg, var(--color-gray-900));
+    font-size: 0.875rem;
+    line-height: 1.25rem;
+    font-weight: 600;
+    white-space: nowrap;
+    transition: background-color 150ms, color 150ms, border-color 150ms;
+  }
+
+  .teaser-action:hover,
+  .teaser-action:focus-visible {
+    background-color: var(--teaser-action-hover-bg, var(--color-gray-100));
+    color: var(--teaser-action-hover-fg, var(--color-gray-900));
+    border-color: var(--teaser-action-hover-border, var(--color-gray-900));
+  }
+
+  .teaser-action:focus-visible {
+    outline: 2px solid var(--color-amber-400);
+    outline-offset: 2px;
+  }
+}

