+      announcer.setAttribute('aria-live', 'polite');
+      announcer.className = 'visually-hidden';
+      document.body.append(announcer);
+      let announceTimer;
+      let announced = false;
+
+      // Only reference the error in aria-describedby while it's visible.
+      const linkError = (shown) => {
+        const errorId = email.dataset.error;
+        const ids = (email.getAttribute('aria-describedby') || '').split(/\s+/).filter((id) => id && id !== errorId);
