+++ b/server.mjs
@@ -0,0 +1,274 @@
+// The Daily Grind web server.
+//
+// - GET /                 renders index.html with a fresh, single-use EVP nonce
+//                         in the rewards sign-up form.
+// - POST /api/verify-email handles rewards sign-up. If the browser supplied a
+//                         valid Email Verification Token (EVT + KB-JWT), the
+//                         email is marked verified immediately; otherwise we
+//                         fall back to the traditional verification email.
+//
+// Env:
+//   PORT                     (default 11222)
+//   RP_ORIGIN                public origin of this site, e.g. https://dailygrind.example
+//   EVP_ORIGIN_TRIAL_TOKEN   Chrome Origin Trial token for the Email Verification API
+import { createServer } from 'node:http';
+import { readFile } from 'node:fs/promises';
+import { randomBytes, scrypt as scryptCb } from 'node:crypto';
+import { promisify } from 'node:util';
+import { verifyEmailVerificationToken } from './lib/verify-email-token.mjs';
+
+const scrypt = promisify(scryptCb);
+
+const PORT = Number(process.env.PORT) || 11222;
+const RP_ORIGIN = (process.env.RP_ORIGIN || `http://localhost:${PORT}`).replace(/\/+$/, '');
+const ORIGIN_TRIAL_TOKEN = process.env.EVP_ORIGIN_TRIAL_TOKEN || '';
+const SECURE_COOKIE = RP_ORIGIN.startsWith('https://');
+const SESSION_COOKIE = SECURE_COOKIE ? '__Host-dg_sid' : 'dg_sid';
+const SESSION_TTL_MS = 30 * 60 * 1000;
+const NONCE_TTL_MS = 10 * 60 * 1000;
+const MAX_BODY_BYTES = 16 * 1024;
+
+const indexTemplate = await readFile(new URL('./index.html', import.meta.url), 'utf8');
+
+// ---------------------------------------------------------------------------
+// Server-side session store. The cookie only carries an opaque session ID;
+// the expected nonce never leaves the server.
+// TODO: replace with a shared store (e.g. Redis GETDEL) when running >1 instance.
+const sessions = new Map(); // sid -> { nonce, nonceIssuedAt, touchedAt }
+
+function parseCookies(header = '') {
+  const out = {};
+  for (const part of header.split(';')) {
+    const i = part.indexOf('=');
+    if (i > 0) out[part.slice(0, i).trim()] = decodeURIComponent(part.slice(i + 1).trim());
+  }
+  return out;
+}
+
+function getOrCreateSession(req, res) {
+  const sid = parseCookies(req.headers.cookie)[SESSION_COOKIE];
+  if (sid && sessions.has(sid)) {
+    const session = sessions.get(sid);
+    session.touchedAt = Date.now();
+    return session;
+  }
+  const newSid = randomBytes(32).toString('base64url');
+  const session = { nonce: null, nonceIssuedAt: 0, touchedAt: Date.now() };
+  sessions.set(newSid, session);
+  res.setHeader(
+    'Set-Cookie',
+    `${SESSION_COOKIE}=${newSid}; Path=/; HttpOnly; SameSite=Lax${SECURE_COOKIE ? '; Secure' : ''}; Max-Age=${SESSION_TTL_MS / 1000}`,
+  );
+  return session;
+}
+
+/** Atomically read and delete the session's single-use nonce. */
+function consumeSessionNonce(req) {
+  const sid = parseCookies(req.headers.cookie)[SESSION_COOKIE];
+  const session = sid && sessions.get(sid);
+  if (!session || !session.nonce) return null;
+  const { nonce, nonceIssuedAt } = session;
+  session.nonce = null;
+  session.nonceIssuedAt = 0;
+  return Date.now() - nonceIssuedAt <= NONCE_TTL_MS ? nonce : null;
+}
+
+setInterval(() => {
+  const cutoff = Date.now() - SESSION_TTL_MS;
+  for (const [sid, s] of sessions) if (s.touchedAt < cutoff) sessions.delete(sid);
+}, 60 * 1000).unref();
+
+// ---------------------------------------------------------------------------
+// Rewards accounts (in-memory demo store).
+// TODO: persist to the real customer database.
+const accounts = new Map(); // lower-cased email -> account
+
+async function hashPassword(password) {
+  const salt = randomBytes(16);
+  const key = await scrypt(password.normalize('NFKC'), salt, 64);
+  return `scrypt$${salt.toString('base64url')}$${key.toString('base64url')}`;
+}
+
+async function sendTraditionalVerificationEmail(account) {
+  // TODO: integrate with the transactional email provider (OTP / magic link).
+  console.info(`[signup] Email verification required for ${account.email}; sending OTP/magic link.`);
+}
+
+// ---------------------------------------------------------------------------
+// HTML helpers
+const escapeHtml = (s) =>
+  String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
+
+function baseHeaders(res) {
+  res.setHeader('Content-Type', 'text/html; charset=utf-8');
+  // Back/forward navigation must never reuse an already-consumed nonce.
+  res.setHeader('Cache-Control', 'no-store');
+  res.setHeader('X-Content-Type-Options', 'nosniff');
+  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
+  if (ORIGIN_TRIAL_TOKEN) res.setHeader('Origin-Trial', ORIGIN_TRIAL_TOKEN);
+}
+
+function renderHome(req, res, { status = 200, message = null, values = {} } = {}) {
+  const session = getOrCreateSession(req, res);
+  session.nonce = randomBytes(32).toString('base64url');
+  session.nonceIssuedAt = Date.now();
+
+  const messageHtml = message
+    ? `<p class="form-message form-message--${message.kind}" role="${message.kind === 'error' ? 'alert' : 'status'}">${escapeHtml(message.text)}</p>`
+    : '';
+
+  const html = indexTemplate
+    .replaceAll('{{EVP_NONCE}}', session.nonce)
+    .replaceAll('{{SIGNUP_MESSAGE}}', messageHtml)
+    .replaceAll('{{SIGNUP_NAME}}', escapeHtml(values.name ?? ''))
+    .replaceAll('{{SIGNUP_EMAIL}}', escapeHtml(values.email ?? ''));
+
+  baseHeaders(res);
+  res.writeHead(status);
+  res.end(html);
+}
+
+function renderResult(res, { status = 200, title, body }) {
+  baseHeaders(res);
+  res.writeHead(status);
+  res.end(`<!DOCTYPE html>
+<html lang="en">
+<head>
+  <meta charset="UTF-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1.0">
+  <title>${escapeHtml(title)} | The Daily Grind</title>
+  <style>
+    body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; line-height: 1.6; color: #3e2723; background: #fafafa; margin: 0; }
+    main { max-width: 36rem; margin: 4rem auto; padding: 2rem; background: white; border-radius: 8px; box-shadow: 0 2px 5px rgba(0,0,0,.1); }
+    h1 { color: #4e342e; margin-block: 0 1rem; }
+    a { color: #4e342e; font-weight: 600; }
+  </style>
+</head>
+<body>
+  <main>
+    <h1>${escapeHtml(title)}</h1>
+    ${body}
+    <p><a href="/">Back to The Daily Grind</a></p>
+  </main>
+</body>
+</html>`);
+}
+
+// ---------------------------------------------------------------------------
+// POST /api/verify-email — rewards sign-up with EVP fast path.
+async function readForm(req) {
+  const type = (req.headers['content-type'] || '').split(';')[0].trim();
+  if (type !== 'application/x-www-form-urlencoded') throw Object.assign(new Error('Unsupported content type'), { status: 415 });
+  let size = 0;
+  const chunks = [];
+  for await (const chunk of req) {
+    size += chunk.length;
+    if (size > MAX_BODY_BYTES) throw Object.assign(new Error('Payload too large'), { status: 413 });
+    chunks.push(chunk);
+  }
+  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
+}
+
+async function handleSignup(req, res) {
+  // Basic CSRF defence on top of the SameSite=Lax session cookie.
+  const origin = req.headers.origin;
+  if (origin && origin !== RP_ORIGIN) {
+    res.writeHead(403, { 'Content-Type': 'text/plain' });
+    return res.end('Forbidden');
+  }
+
+  const form = await readForm(req);
+  const name = String(form.get('name') || '').trim();
+  const email = String(form.get('email') || '').trim();
+  const password = String(form.get('new-password') || '');
+  const rawToken = String(form.get('email-verification-token') || '').trim();
+
+  // Consume the nonce first, regardless of what happens next, so it can't be replayed.
+  const expectedNonce = consumeSessionNonce(req);
+
+  const errors = [];
+  if (!name || name.length > 100) errors.push('Please enter your name.');
+  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) || email.length > 254) errors.push('Please enter a valid email address.');
+  if (password.length < 8 || password.length > 128) errors.push('Choose a password of 8 to 128 characters.');
+  if (!errors.length && accounts.has(email.toLowerCase())) {
+    errors.push('A rewards account already exists for that email. Try signing in instead.');
+  }
+  if (errors.length) {
+    return renderHome(req, res, {
+      status: 422,
+      message: { kind: 'error', text: errors.join(' ') },
+      values: { name, email },
+    });
+  }
+
+  let emailVerified = false;
+  if (rawToken && expectedNonce) {
+    try {
+      await verifyEmailVerificationToken({
+        rawToken,
+        submittedEmail: email,
+        expectedNonce,
+        expectedAudience: RP_ORIGIN,
+      });
+      emailVerified = true;
+    } catch (err) {
+      console.warn('[signup] Email verification token check failed:', err?.message || err);
+    }
+  }
