+  const account = {
+    id: randomBytes(16).toString('hex'),
+    name,
+    email, // preserve the submitted string
+    passwordHash: await hashPassword(password),
+    emailVerified,
+    emailVerifiedVia: emailVerified ? 'email-verification-protocol' : null,
+    createdAt: new Date().toISOString(),
+  };
+  accounts.set(email.toLowerCase(), account);
+
+  if (emailVerified) {
+    return renderResult(res, {
+      status: 201,
+      title: 'Welcome to Daily Grind Rewards!',
+      body: `<p>Thanks, ${escapeHtml(name)}. Your email address <strong>${escapeHtml(email)}</strong> was confirmed by your email provider, so there's no code to enter. Your first reward is already brewing.</p>`,
+    });
+  }
+
+  // Fallback: no token (unsupported browser, signed out of provider, non-participating
+  // domain) or verification failed — never block sign-up, verify the old way.
+  await sendTraditionalVerificationEmail(account);
+  return renderResult(res, {
+    status: 202,
+    title: 'Check your inbox',
+    body: `<p>Thanks, ${escapeHtml(name)}. We sent a confirmation link to <strong>${escapeHtml(email)}</strong>. Open it to activate your rewards account.</p>`,
+  });
+}
+
+// ---------------------------------------------------------------------------
+const server = createServer(async (req, res) => {
+  try {
+    const { pathname } = new URL(req.url, RP_ORIGIN);
+    if ((pathname === '/' || pathname === '/index.html') && (req.method === 'GET' || req.method === 'HEAD')) {
+      return renderHome(req, res);
+    }
+    if (pathname === '/api/verify-email') {
+      if (req.method !== 'POST') {
+        res.writeHead(405, { Allow: 'POST', 'Content-Type': 'text/plain' });
+        return res.end('Method Not Allowed');
+      }
+      return await handleSignup(req, res);
+    }
+    res.writeHead(404, { 'Content-Type': 'text/plain' });
+    res.end('Not Found');
+  } catch (err) {
+    const status = err?.status || 500;
+    if (status === 500) console.error(err);
+    if (!res.headersSent) res.writeHead(status, { 'Content-Type': 'text/plain' });
+    res.end(status === 500 ? 'Internal Server Error' : err.message);
+  }
+});
+
+server.listen(PORT, () => {
+  console.info(`The Daily Grind listening on ${RP_ORIGIN} (port ${PORT})`);
+});

