+// Email Verification Protocol (EVP) — relying-party verification.
+//
+// The browser (acting on behalf of the user's email provider) hands the page an
+// SD-JWT+KB "presentation token" proving control of an email address, so we never
+// have to send an OTP or magic link. Format:
+//
+//   <issuer-signed SD-JWT>~[<disclosure>~...]<key-binding JWT>
+//
+// Verification steps (all must pass):
+//   1. Discover the issuer for the email domain via DNS TXT
+//      `_email-verification.<domain>`  ->  "iss=<issuer-host>"
+//   2. Fetch https://<issuer>/.well-known/email-verification -> jwks_uri, then the JWKS.
+//   3. Verify the SD-JWT signature with the issuer key; check iss, iat, email, email_verified.
+//   4. Verify the KB-JWT with the key in the SD-JWT `cnf.jwk`; check aud == our origin,
+//      nonce == the nonce we issued for this session, iat freshness, sd_hash.
+
+import { createHash, createPublicKey, verify as cryptoVerify } from 'node:crypto';
+import { promises as dnsPromises } from 'node:dns';
+import net from 'node:net';
+
+const ISSUER_TYPS = new Set(['evp+sd-jwt', 'web-identity+sd-jwt']);
+const KB_TYP = 'kb+jwt';
+const ALGS = {
+  ES256: { kty: 'EC', crv: 'P-256', hash: 'sha256', dsaEncoding: 'ieee-p1363' },
+  ES384: { kty: 'EC', crv: 'P-384', hash: 'sha384', dsaEncoding: 'ieee-p1363' },
+  RS256: { kty: 'RSA', hash: 'sha256' },
+  PS256: { kty: 'RSA', hash: 'sha256', pss: true },
+  EdDSA: { kty: 'OKP', crv: 'Ed25519', hash: null },
+};
+const MAX_SKEW_SEC = 60;
+const MAX_AGE_SEC = 300;
+const MAX_FETCH_BYTES = 64 * 1024;
+const CACHE_TTL_MS = 10 * 60 * 1000;
+
+export class EvpError extends Error {
+  constructor(code, message) {
+    super(message);
+    this.code = code;
+  }
+}
+
+const fail = (code, msg) => {
+  throw new EvpError(code, msg);
+};
+
+const b64urlDecode = (s) => {
+  if (typeof s !== 'string' || !/^[A-Za-z0-9_-]*$/.test(s)) fail('malformed', 'Invalid base64url');
+  return Buffer.from(s, 'base64url');
+};
+const b64urlJson = (s) => {
+  try {
+    return JSON.parse(b64urlDecode(s).toString('utf8'));
+  } catch (e) {
+    if (e instanceof EvpError) throw e;
+    fail('malformed', 'Invalid JSON segment');
+  }
+};
+const sha256b64url = (s) => createHash('sha256').update(s, 'ascii').digest('base64url');
+
+export function normalizeEmail(email) {
+  if (typeof email !== 'string') return null;
+  const e = email.trim().toLowerCase();
+  if (e.length > 254 || !/^[^\s@]+@[a-z0-9.-]+\.[a-z0-9-]{2,}$/.test(e)) return null;
+  return e;
+}
+
+function parseJwt(jwt) {
+  const parts = jwt.split('.');
+  if (parts.length !== 3) fail('malformed', 'JWT must have three parts');
+  const header = b64urlJson(parts[0]);
+  const payload = b64urlJson(parts[1]);
+  if (!header || typeof header !== 'object' || !payload || typeof payload !== 'object') {
+    fail('malformed', 'JWT header/payload must be objects');
+  }
+  return { header, payload, signingInput: `${parts[0]}.${parts[1]}`, signature: b64urlDecode(parts[2]) };
+}
+
+function verifyJwtSignature(parsed, jwk, allowedAlgs) {
+  const { alg } = parsed.header;
+  const spec = ALGS[alg];
+  if (!spec || !allowedAlgs.includes(alg)) fail('bad_alg', `Unsupported alg ${alg}`);
+  if (!jwk || jwk.kty !== spec.kty || (spec.crv && jwk.crv !== spec.crv)) {
+    fail('bad_key', 'Key type does not match alg');
+  }
+  if (jwk.d) fail('bad_key', 'Private key material not allowed');
+  let key;
+  try {
+    const { kty, crv, x, y, n, e } = jwk;
+    key = createPublicKey({ key: { kty, crv, x, y, n, e }, format: 'jwk' });
+  } catch {
+    fail('bad_key', 'Invalid JWK');
+  }
+  const opts = { key };
+  if (spec.dsaEncoding) opts.dsaEncoding = spec.dsaEncoding;
+  if (spec.pss) {
+    opts.padding = 6; // RSA_PKCS1_PSS_PADDING
+    opts.saltLength = 32;
+  }
+  const ok = cryptoVerify(spec.hash, Buffer.from(parsed.signingInput, 'ascii'), opts, parsed.signature);
+  if (!ok) fail('bad_signature', 'Signature verification failed');
+}
+
+function checkIat(iat, now, label) {
+  if (typeof iat !== 'number' || !Number.isFinite(iat)) fail('bad_claims', `${label} iat missing`);
+  if (iat > now + MAX_SKEW_SEC) fail('bad_claims', `${label} issued in the future`);
+  if (iat < now - MAX_AGE_SEC) fail('expired', `${label} is too old`);
+}
+
+// ---------- Issuer discovery (DNS + HTTPS) ----------
+
+function isPrivateAddress(ip) {
+  if (net.isIPv4(ip)) {
+    const [a, b] = ip.split('.').map(Number);
+    return (
+      a === 10 || a === 127 || a === 0 || (a === 169 && b === 254) || (a === 172 && b >= 16 && b <= 31) ||
+      (a === 192 && b === 168) || (a === 100 && b >= 64 && b <= 127) || a >= 224
+    );
+  }
+  const v = ip.toLowerCase();
+  if (v.startsWith('::ffff:')) return isPrivateAddress(v.slice(7));
+  return v === '::1' || v === '::' || v.startsWith('fc') || v.startsWith('fd') || v.startsWith('fe80');
+}
+
+function assertPublicHostname(host) {
+  if (
+    typeof host !== 'string' ||
+    host.length > 253 ||
+    !/^(?=.{1,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/.test(host) ||
+    net.isIP(host)
+  ) {
+    fail('bad_issuer', 'Issuer must be a public DNS hostname');
+  }
+}
+
+export function createDefaultDeps() {
+  return {
+    async resolveTxt(name) {
+      return dnsPromises.resolveTxt(name);
+    },
+    async fetchJson(url) {
+      const u = new URL(url);
+      if (u.protocol !== 'https:' || u.port || u.username || u.password) fail('bad_issuer', 'Only plain https URLs allowed');
+      assertPublicHostname(u.hostname);
+      // Basic SSRF guard: refuse hostnames that resolve to private/loopback ranges.
+      const addrs = await dnsPromises.lookup(u.hostname, { all: true });
+      if (!addrs.length || addrs.some((a) => isPrivateAddress(a.address))) {
+        fail('bad_issuer', 'Issuer resolves to a non-public address');
+      }
+      const res = await fetch(u, {
+        redirect: 'error',
+        signal: AbortSignal.timeout(5000),
+        headers: { accept: 'application/json' },
+      });
+      if (!res.ok) fail('issuer_unreachable', `GET ${u.href} -> ${res.status}`);
+      const text = await res.text();
+      if (text.length > MAX_FETCH_BYTES) fail('issuer_unreachable', 'Issuer response too large');
+      return JSON.parse(text);
+    },
+  };
+}
+
+export function createVerifier({ expectedOrigin, deps = createDefaultDeps(), now = () => Math.floor(Date.now() / 1000) }) {
+  if (!expectedOrigin) throw new Error('expectedOrigin is required');
+  const cache = new Map();
+  const cached = async (key, fn) => {
+    const hit = cache.get(key);
+    if (hit && hit.exp > Date.now()) return hit.value;
+    const value = await fn();
+    cache.set(key, { value, exp: Date.now() + CACHE_TTL_MS });
+    return value;
+  };
+
+  async function discoverIssuer(domain) {
+    return cached(`dns:${domain}`, async () => {
+      let records;
+      try {
+        records = await deps.resolveTxt(`_email-verification.${domain}`);
+      } catch {
+        fail('no_issuer', `No email-verification issuer published for ${domain}`);
+      }
+      const issuers = records
+        .map((chunks) => chunks.join(''))
+        .map((r) => /^iss=(.+)$/.exec(r.trim()))
+        .filter(Boolean)
+        .map((m) => m[1].trim().toLowerCase());
+      if (issuers.length !== 1) fail('no_issuer', `Expected exactly one issuer for ${domain}`);
+      assertPublicHostname(issuers[0]);
+      return issuers[0];
+    });
+  }
+
+  async function issuerKeys(issuer) {
+    return cached(`jwks:${issuer}`, async () => {
+      let meta;
+      try {
+        meta = await deps.fetchJson(`https://${issuer}/.well-known/email-verification`);
+      } catch (e) {
+        if (e instanceof EvpError) throw e;
+        fail('issuer_unreachable', 'Could not load issuer metadata');
+      }
+      if (!meta || typeof meta.jwks_uri !== 'string') fail('bad_issuer', 'Issuer metadata missing jwks_uri');
+      const jwksUrl = new URL(meta.jwks_uri);
+      if (jwksUrl.protocol !== 'https:') fail('bad_issuer', 'jwks_uri must be https');
+      let jwks;
+      try {
+        jwks = await deps.fetchJson(jwksUrl.href);
+      } catch (e) {
+        if (e instanceof EvpError) throw e;
+        fail('issuer_unreachable', 'Could not load issuer JWKS');
+      }
+      if (!jwks || !Array.isArray(jwks.keys)) fail('bad_issuer', 'Invalid JWKS');
+      const algs = Array.isArray(meta.signing_alg_values_supported)
+        ? meta.signing_alg_values_supported.filter((a) => a in ALGS)
+        : Object.keys(ALGS);
+      return { keys: jwks.keys, algs };
+    });
+  }
+
+  /**
+   * @param {string} token     presentation token from the browser
+   * @param {string} nonce     nonce this server issued to the session
+   * @param {string} email     email the user typed (must match the token)
+   * @returns {Promise<{email: string, issuer: string}>}
+   */
+  async function verify(token, { nonce, email }) {
+    if (typeof token !== 'string' || token.length > 16 * 1024) fail('malformed', 'Token missing or too large');
+    if (typeof nonce !== 'string' || nonce.length < 16) fail('bad_nonce', 'No active nonce');
+    const expectedEmail = normalizeEmail(email);
+    if (!expectedEmail) fail('bad_email', 'Invalid email');
+
+    const segments = token.split('~');
+    if (segments.length < 2) fail('malformed', 'Token is not an SD-JWT+KB');
+    const issuerJwt = segments[0];
+    const disclosures = segments.slice(1, -1);
+    const kbJwt = segments[segments.length - 1];
+    if (!kbJwt) fail('malformed', 'Key-binding JWT is required');
+
+    const sd = parseJwt(issuerJwt);
+    if (!ISSUER_TYPS.has(sd.header.typ)) fail('malformed', 'Unexpected SD-JWT typ');
+    const claims = { ...sd.payload };
+
+    // Selective disclosures (if any) — only object-property disclosures with sha-256.
+    if (disclosures.length) {
+      if ((claims._sd_alg ?? 'sha-256') !== 'sha-256') fail('malformed', 'Unsupported _sd_alg');
+      const digests = new Set(Array.isArray(claims._sd) ? claims._sd : []);
+      for (const d of disclosures) {
+        if (!digests.has(sha256b64url(d))) fail('malformed', 'Disclosure not referenced by SD-JWT');
+        const arr = b64urlJson(d);
+        if (!Array.isArray(arr) || arr.length !== 3 || typeof arr[1] !== 'string') fail('malformed', 'Bad disclosure');
+        if (arr[1] in claims || arr[1].startsWith('_sd')) fail('malformed', 'Disclosure overrides claim');
+        claims[arr[1]] = arr[2];
+      }
+    }
+
+    // 1. Issuer must be the one the email domain delegates to.
+    const tokenEmail = normalizeEmail(claims.email);
+    if (!tokenEmail) fail('bad_claims', 'Token has no valid email');
+    if (tokenEmail !== expectedEmail) fail('email_mismatch', 'Token email does not match entered email');
+    if (claims.email_verified !== true) fail('bad_claims', 'Issuer did not assert email_verified');
+    const domain = tokenEmail.slice(tokenEmail.lastIndexOf('@') + 1);
+    const issuer = await discoverIssuer(domain);
+    if (typeof claims.iss !== 'string') fail('bad_claims', 'iss missing');
+    const issHost = claims.iss.replace(/^https:\/\//, '').replace(/\/$/, '').toLowerCase();
+    if (issHost !== issuer) fail('bad_issuer', 'iss does not match DNS-delegated issuer');
+    const t = now();
+    checkIat(claims.iat, t, 'SD-JWT');
+    if (typeof claims.exp === 'number' && claims.exp < t - MAX_SKEW_SEC) fail('expired', 'SD-JWT expired');
+
+    // 2/3. Issuer signature.
+    const { keys, algs } = await issuerKeys(issuer);
+    const candidates = sd.header.kid ? keys.filter((k) => k.kid === sd.header.kid) : keys;
+    if (candidates.length !== 1) fail('bad_key', 'Could not select issuer signing key');
+    verifyJwtSignature(sd, candidates[0], algs);
+
+    // 4. Key binding: proves the browser that requested the token is presenting it, to us, now.
+    const cnfJwk = claims.cnf && claims.cnf.jwk;
+    if (!cnfJwk || typeof cnfJwk !== 'object') fail('bad_claims', 'cnf.jwk missing');
+    const kb = parseJwt(kbJwt);
+    if (kb.header.typ !== KB_TYP) fail('malformed', 'Unexpected KB-JWT typ');
+    verifyJwtSignature(kb, cnfJwk, Object.keys(ALGS));
+    const aud = Array.isArray(kb.payload.aud) ? kb.payload.aud : [kb.payload.aud];
+    if (aud.length !== 1 || aud[0] !== expectedOrigin) fail('bad_audience', 'KB-JWT aud does not match this site');
+    if (kb.payload.nonce !== nonce) fail('bad_nonce', 'Nonce mismatch');
+    checkIat(kb.payload.iat, t, 'KB-JWT');
+    const expectedSdHash = sha256b64url(segments.slice(0, -1).join('~') + '~');
+    if (kb.payload.sd_hash !== expectedSdHash) fail('bad_claims', 'sd_hash mismatch');
+
+    return { email: tokenEmail, issuer };
+  }
+
+  return { verify };
+}
diff --git a/server/index.js b/server/index.js
new file mode 100644
index 0000000..0421c52
--- /dev/null
+++ b/server/index.js
@@ -0,0 +1,198 @@
+// The Daily Grind — tiny zero-dependency server.
+// Serves the homepage and the rewards sign-up API:
+//   GET  /api/rewards/nonce         -> { nonce }   (bound to an HttpOnly session cookie)
+//   POST /api/rewards/verify-email  -> { email }   (verifies the browser's EVP presentation token)
+//   POST /api/rewards/register      -> { member }  (creates the rewards account)
+//
+// Env: PORT (default 11222), PUBLIC_ORIGIN (e.g. https://dailygrind.example — must match
+// what the browser sees; used as the KB-JWT audience and for Origin checks).
+
+import { createServer } from 'node:http';
+import { randomBytes, randomUUID } from 'node:crypto';
+import { readFile, writeFile, mkdir, rename } from 'node:fs/promises';
+import path from 'node:path';
+import { fileURLToPath } from 'node:url';
+import { createVerifier, normalizeEmail, EvpError } from './evp.js';
+
+const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
+const PORT = Number(process.env.PORT || 11222);
+const PUBLIC_ORIGIN = (process.env.PUBLIC_ORIGIN || `http://localhost:${PORT}`).replace(/\/$/, '');
+const SECURE_COOKIE = PUBLIC_ORIGIN.startsWith('https://');
+const DATA_FILE = path.join(ROOT, 'data', 'members.json');
+const SESSION_TTL_MS = 30 * 60 * 1000;
+const NONCE_TTL_MS = 5 * 60 * 1000;
+const VERIFIED_TTL_MS = 15 * 60 * 1000;
+
+const verifier = createVerifier({ expectedOrigin: PUBLIC_ORIGIN });
+const sessions = new Map(); // sid -> { exp, nonce, nonceExp, verified: { email, issuer, exp } }
+
+setInterval(() => {
+  const t = Date.now();
+  for (const [sid, s] of sessions) if (s.exp < t) sessions.delete(sid);
+}, 60_000).unref();
+
+// ---------- members store (JSON file, serialized writes) ----------
+let members = [];
+let writeChain = Promise.resolve();
+try {
+  members = JSON.parse(await readFile(DATA_FILE, 'utf8'));
+} catch {
+  members = [];
+}
+function persist() {
+  writeChain = writeChain.then(async () => {
+    await mkdir(path.dirname(DATA_FILE), { recursive: true });
+    const tmp = `${DATA_FILE}.${process.pid}.tmp`;
+    await writeFile(tmp, JSON.stringify(members, null, 2));
+    await rename(tmp, DATA_FILE);
+  });
+  return writeChain;
+}
+
+// ---------- helpers ----------
+const SECURITY_HEADERS = {
+  'x-content-type-options': 'nosniff',
+  'referrer-policy': 'strict-origin-when-cross-origin',
+  'x-frame-options': 'DENY',
+};
+
+function send(res, status, body, headers = {}) {
+  const isJson = typeof body !== 'string';
+  res.writeHead(status, {
+    ...SECURITY_HEADERS,
+    'content-type': isJson ? 'application/json; charset=utf-8' : 'text/html; charset=utf-8',
+    'cache-control': 'no-store',
+    ...headers,
+  });
+  res.end(isJson ? JSON.stringify(body) : body);
+}
+
+function getSession(req, res) {
+  const m = /(?:^|;\s*)dg_sid=([A-Za-z0-9_-]{43})(?:;|$)/.exec(req.headers.cookie || '');
+  let sid = m && m[1];
+  let s = sid && sessions.get(sid);
+  if (!s || s.exp < Date.now()) {
+    sid = randomBytes(32).toString('base64url');
+    s = {};
+    sessions.set(sid, s);
+    res.setHeader(
+      'set-cookie',
+      `dg_sid=${sid}; Path=/api/rewards; HttpOnly; SameSite=Strict; Max-Age=${SESSION_TTL_MS / 1000}${SECURE_COOKIE ? '; Secure' : ''}`,
+    );
+  }
+  s.exp = Date.now() + SESSION_TTL_MS;
+  return s;
+}
+
+async function readJson(req) {
+  if (!/^application\/json\b/i.test(req.headers['content-type'] || '')) {
+    throw Object.assign(new Error('Expected application/json'), { status: 415 });
+  }
+  let size = 0;
+  const chunks = [];
+  for await (const chunk of req) {
+    size += chunk.length;
+    if (size > 32 * 1024) throw Object.assign(new Error('Body too large'), { status: 413 });
+    chunks.push(chunk);
+  }
+  try {
+    const v = JSON.parse(Buffer.concat(chunks).toString('utf8'));
+    if (!v || typeof v !== 'object') throw new Error();
+    return v;
+  } catch {
+    throw Object.assign(new Error('Invalid JSON'), { status: 400 });
+  }
+}
+
+function sameOrigin(req) {
+  return req.headers.origin === PUBLIC_ORIGIN;
+}
+
+// ---------- routes ----------
+async function handleNonce(req, res) {
+  const s = getSession(req, res);
+  s.nonce = randomBytes(32).toString('base64url');
+  s.nonceExp = Date.now() + NONCE_TTL_MS;
+  send(res, 200, { nonce: s.nonce });
+}
+
+async function handleVerify(req, res) {
+  if (!sameOrigin(req)) return send(res, 403, { error: 'Bad origin' });
+  const s = getSession(req, res);
+  const { token, email } = await readJson(req);
+  const nonce = s.nonce && s.nonceExp > Date.now() ? s.nonce : null;
+  // Nonces are single use, whether or not verification succeeds.
+  s.nonce = s.nonceExp = undefined;
+  if (!nonce) return send(res, 400, { error: 'Verification session expired. Please re-enter your email.', code: 'bad_nonce' });
+  try {
+    const result = await verifier.verify(token, { nonce, email });
+    s.verified = { ...result, exp: Date.now() + VERIFIED_TTL_MS };
+    send(res, 200, { email: result.email, verified: true });
+  } catch (e) {
+    if (!(e instanceof EvpError)) throw e;
+    console.warn(`[evp] verification failed: ${e.code}: ${e.message}`);
+    send(res, 400, { error: 'We could not verify that email address.', code: e.code });
+  }
+}
+
+async function handleRegister(req, res) {
+  if (!sameOrigin(req)) return send(res, 403, { error: 'Bad origin' });
+  const s = getSession(req, res);
+  const body = await readJson(req);
+  const name = typeof body.name === 'string' ? body.name.trim().replace(/\s+/g, ' ') : '';
+  const email = normalizeEmail(body.email);
+  const favoriteDrink = typeof body.favoriteDrink === 'string' ? body.favoriteDrink.trim().slice(0, 60) : '';
+  if (!name || name.length > 80) return send(res, 400, { error: 'Please enter your name (max 80 characters).' });
+  if (!email) return send(res, 400, { error: 'Please enter a valid email address.' });
+  if (body.terms !== true) return send(res, 400, { error: 'Please accept the rewards program terms.' });
+
+  const emailVerified = !!(s.verified && s.verified.exp > Date.now() && s.verified.email === email);
+  const existing = members.find((m) => m.email === email);
+  if (existing) {
+    // A verified sign-up may take over an unverified (unproven) claim on the address;
+    // otherwise anyone could squat a victim's email before they register.
+    if (existing.emailVerified || !emailVerified) {
+      return send(res, 409, { error: 'That email is already enrolled in Daily Grind Rewards.' });
+    }
+    members = members.filter((m) => m !== existing);
+  }
+
+  const member = {
+    id: randomUUID(),
+    name,
+    email,
+    favoriteDrink,
+    emailVerified,
+    verifiedBy: emailVerified ? s.verified.issuer : null,
+    stars: emailVerified ? 50 : 0, // welcome bonus once the email is proven
+    createdAt: new Date().toISOString(),
+  };
+  members.push(member);
+  await persist();
+  if (emailVerified) s.verified = undefined;
+  send(res, 201, { member: { name, email, emailVerified, stars: member.stars } });
+}
+
+const routes = {
+  'GET /api/rewards/nonce': handleNonce,
+  'POST /api/rewards/verify-email': handleVerify,
+  'POST /api/rewards/register': handleRegister,
+};
+
+const server = createServer(async (req, res) => {
+  try {
+    const { pathname } = new URL(req.url, PUBLIC_ORIGIN);
+    const route = routes[`${req.method} ${pathname}`];
+    if (route) return await route(req, res);
+    if (req.method === 'GET' && (pathname === '/' || pathname === '/index.html')) {
+      return send(res, 200, await readFile(path.join(ROOT, 'index.html'), 'utf8'), { 'cache-control': 'no-cache' });
+    }
+    send(res, 404, pathname.startsWith('/api/') ? { error: 'Not found' } : '<h1>Not found</h1>');
+  } catch (e) {
+    if (e.status) return send(res, e.status, { error: e.message });
+    console.error(e);
+    send(res, 500, { error: 'Something went wrong.' });
+  }
+});
+
+server.listen(PORT, () => console.log(`Daily Grind listening on ${PORT} (origin ${PUBLIC_ORIGIN})`));
