index 0000000..f995999
--- /dev/null
+++ b/test/evp.test.js
@@ -0,0 +1,74 @@
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { generateKeyPairSync, sign, createHash } from 'node:crypto';
+import { createVerifier } from '../server/evp.js';
+
+const ORIGIN = 'https://dailygrind.example';
+const NONCE = 'n'.repeat(43);
+const b64 = (o) => Buffer.from(JSON.stringify(o)).toString('base64url');
+const now = () => Math.floor(Date.now() / 1000);
+
+function es256Jwt(header, payload, privateKey) {
+  const input = `${b64(header)}.${b64(payload)}`;
+  const sig = sign('sha256', Buffer.from(input), { key: privateKey, dsaEncoding: 'ieee-p1363' });
+  return `${input}.${sig.toString('base64url')}`;
+}
+
+const issuerKey = generateKeyPairSync('ec', { namedCurve: 'P-256' });
+const issuerJwk = { ...issuerKey.publicKey.export({ format: 'jwk' }), kid: 'k1', alg: 'ES256' };
+const browserKey = generateKeyPairSync('ec', { namedCurve: 'P-256' });
+const browserJwk = browserKey.publicKey.export({ format: 'jwk' });
+
+const deps = {
+  async resolveTxt(name) {
+    if (name === '_email-verification.mail.example') return [['iss=issuer.example']];
+    throw new Error('ENOTFOUND');
+  },
+  async fetchJson(url) {
+    if (url === 'https://issuer.example/.well-known/email-verification') {
+      return { jwks_uri: 'https://issuer.example/jwks', signing_alg_values_supported: ['ES256'] };
+    }
+    if (url === 'https://issuer.example/jwks') return { keys: [issuerJwk] };
+    throw new Error('404');
+  },
+};
+
+function makeToken({ claims = {}, kb = {}, issuerPriv = issuerKey.privateKey, kbPriv = browserKey.privateKey } = {}) {
+  const sdJwt = es256Jwt(
+    { alg: 'ES256', typ: 'evp+sd-jwt', kid: 'k1' },
+    { iss: 'issuer.example', iat: now(), email: 'Ada@mail.example', email_verified: true, cnf: { jwk: browserJwk }, ...claims },
+    issuerPriv,
+  );
+  const sdHash = createHash('sha256').update(`${sdJwt}~`).digest('base64url');
+  const kbJwt = es256Jwt({ alg: 'ES256', typ: 'kb+jwt' }, { aud: ORIGIN, nonce: NONCE, iat: now(), sd_hash: sdHash, ...kb }, kbPriv);
+  return `${sdJwt}~${kbJwt}`;
+}
+
+const verifier = createVerifier({ expectedOrigin: ORIGIN, deps });
+const opts = { nonce: NONCE, email: 'ada@mail.example' };
+
+test('accepts a valid presentation token', async () => {
+  assert.deepEqual(await verifier.verify(makeToken(), opts), { email: 'ada@mail.example', issuer: 'issuer.example' });
+});
+
+const rejects = (name, tokenFn, code, o = opts) =>
+  test(`rejects: ${name}`, async () => {
+    await assert.rejects(verifier.verify(tokenFn(), o), (e) => e.code === code);
+  });
+
+rejects('wrong nonce', () => makeToken({ kb: { nonce: 'x'.repeat(43) } }), 'bad_nonce');
+rejects('wrong audience', () => makeToken({ kb: { aud: 'https://evil.example' } }), 'bad_audience');
+rejects('email mismatch', () => makeToken(), 'email_mismatch', { ...opts, email: 'bob@mail.example' });
+rejects('issuer not delegated by DNS', () => makeToken({ claims: { iss: 'evil.example' } }), 'bad_issuer');
+rejects('domain without issuer', () => makeToken({ claims: { email: 'a@other.example' } }), 'no_issuer', { ...opts, email: 'a@other.example' });
+rejects('forged issuer signature', () => makeToken({ issuerPriv: generateKeyPairSync('ec', { namedCurve: 'P-256' }).privateKey }), 'bad_signature');
+rejects('KB signed by a different key', () => makeToken({ kbPriv: generateKeyPairSync('ec', { namedCurve: 'P-256' }).privateKey }), 'bad_signature');
+rejects('stale KB-JWT', () => makeToken({ kb: { iat: now() - 3600 } }), 'expired');
+rejects('email_verified not asserted', () => makeToken({ claims: { email_verified: false } }), 'bad_claims');
+rejects('missing key binding', () => makeToken().split('~')[0] + '~', 'malformed');
+rejects('sd_hash mismatch', () => makeToken({ kb: { sd_hash: 'abc' } }), 'bad_claims');
+rejects('alg none', () => {
+  const [sd, kb] = makeToken().split('~');
+  const [, p] = sd.split('.');
+  return `${b64({ alg: 'none', typ: 'evp+sd-jwt', kid: 'k1' })}.${p}.~${kb}`;
+}, 'bad_alg');

