+<!doctype html>
+<html lang="en">
+<head>
+  <meta charset="utf-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1">
+  <title>Visually Stable Mixed Fonts</title>
+  <style>
+    :root {
+      color-scheme: light dark;
+    }
+
+    body {
+      margin: 0;
+      padding: 2rem;
+      font-family: system-ui, sans-serif;
+      line-height: 1.6;
+      max-width: 70ch;
+      margin-inline: auto;
+    }
+
+    h1, h2 {
+      line-height: 1.2;
+      text-wrap: balance;
+    }
+
+    section {
+      padding: 1.5rem;
+      margin-block: 1.5rem;
+      border: 1px solid color-mix(in oklab, currentColor 20%, transparent);
+      border-radius: 0.75rem;
+    }
+
+    /* ---------------------------------------------------------------
+       Mixed fonts: body text in a serif, inline code in a monospace.
+       `from-font` reads the x-height ratio of the container's primary
+       font and applies it to every descendant, so the inline <code>
+       (a different family) renders with a matching x-height.
+       --------------------------------------------------------------- */
+    #mixed-fonts-container {
+      font-family: Georgia, "Times New Roman", serif;
+      font-size: 1.125rem;
+      font-size-adjust: from-font;
+    }
+
+    #mixed-fonts-container code {
+      font-family: ui-monospace, "Courier New", Courier, monospace;
+      padding: 0.1em 0.3em;
+      border-radius: 0.25em;
+      background: color-mix(in oklab, currentColor 10%, transparent);
+    }
+
+    /* ---------------------------------------------------------------
+       Independent theme: not a descendant of the font whose
+       proportions it should match, so `from-font` can't inherit the
+       ratio. Lock it to an explicit x-height / font-size aspect ratio.
+       --------------------------------------------------------------- */
+    #independent-theme-container {
+      font-family: "Times New Roman", Times, serif;
+      font-size: 1.125rem;
+      font-size-adjust: 0.5;
+      background: color-mix(in oklab, Canvas 85%, SteelBlue);
+    }
+
+    #independent-theme-container code {
+      font-family: ui-monospace, "Courier New", Courier, monospace;
+    }
+
+    /* Fallback for browsers without font-size-adjust support:
+       nudge monospace sizes manually to approximate the x-height match. */
+    @supports not (font-size-adjust: from-font) {
+      #mixed-fonts-container code,
+      #independent-theme-container code {
+        font-size: 1.1em;
+        line-height: 1;
+      }
+
+      #independent-theme-container {
+        font-size: 1.2rem;
+        line-height: 1.6;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main>
+    <h1>Visually Stable Mixed Fonts</h1>
+
+    <section id="mixed-fonts-container" aria-labelledby="mixed-heading">
+      <h2 id="mixed-heading">Mixed font families</h2>
+      <p>
+        This paragraph is set in a serif face, while snippets such as
+        <code>font-size-adjust: from-font</code> and
+        <code>document.querySelector()</code> use a monospace face. Thanks to
+        <code>from-font</code>, the lowercase letters in both families share
+        the same visual height, so the code doesn't look shrunken or bloated.
+      </p>
+    </section>
+
+    <section id="independent-theme-container" aria-labelledby="theme-heading">
+      <h2 id="theme-heading">Independent theme</h2>
+      <p>
+        This themed block uses its own font stack and is locked to an
+        x-height aspect ratio of <code>0.5</code>, so its proportions stay
+        consistent regardless of which font in the stack actually loads.
+      </p>
+    </section>
+  </main>
+</body>
+</html>

