+          <path d="M12 21s-7.5-4.6-9.5-9.2C1 8.2 3.3 4.5 7 4.5c2 0 3.4 1 5 2.9 1.6-1.9 3-2.9 5-2.9 3.7 0 6 3.7 4.5 7.3C19.5 16.4 12 21 12 21z"/>
+        </svg>
+        <span class="label-off">Favorite</span><span class="label-on">Favorited</span><span class="visually-hidden"> <span class="name"></span></span>
+      </button>
+    </footer>
+  </article>
+`;
+
+export class DgCoffeeCard extends HTMLElement {
+  static observedAttributes = ['name', 'href', 'image', 'image-alt', 'price', 'drink-id', 'heading-level'];
+
+  #internals;
+  #favorited = false;
+  #els;
+
+  constructor() {
+    super();
+    this.#internals = this.attachInternals();
+    const root = this.attachShadow({ mode: 'open' });
+    root.adoptedStyleSheets = [sharedSheet, sheet];
+    root.append(template.content.cloneNode(true));
+
+    this.#els = {
+      image: root.querySelector('img'),
+      title: root.querySelector('.title'),
+      price: root.querySelector('.price'),
+      link: root.querySelector('a'),
+      favorite: root.querySelector('.favorite'),
+      names: root.querySelectorAll('.name'),
+    };
+
+    this.#els.favorite.addEventListener('click', () => this.toggleFavorite());
+  }
+
+  connectedCallback() {
+    window.addEventListener('storage', this.#onStorage);
+    this.#render();
+    this.#setFavorited(readFavorites().has(this.drinkId), { persist: false, notify: false });
+  }
+
+  disconnectedCallback() {
+    window.removeEventListener('storage', this.#onStorage);
+  }
+
+  attributeChangedCallback(name, oldValue, newValue) {
+    if (oldValue === newValue || !this.isConnected) return;
+    if (name === 'drink-id') {
+      this.#setFavorited(readFavorites().has(this.drinkId), { persist: false, notify: false });
+    }
+    this.#render();
+  }
+
+  get name() {
+    return this.getAttribute('name') ?? '';
+  }
+  set name(value) {
+    this.setAttribute('name', value);
+  }
+
+  get drinkId() {
+    return this.getAttribute('drink-id') || slugify(this.name);
+  }
+
+  get tags() {
+    return (this.getAttribute('tags') ?? '').split(/\s+/).filter(Boolean);
+  }
+
+  get favorited() {
+    return this.#favorited;
+  }
+  set favorited(value) {
+    this.#setFavorited(Boolean(value), { persist: true, notify: false });
+  }
+
+  toggleFavorite() {
+    this.#setFavorited(!this.#favorited, { persist: true, notify: true });
+  }
+
+  #onStorage = (event) => {
+    if (event.key !== STORAGE_KEY) return;
+    this.#setFavorited(readFavorites().has(this.drinkId), { persist: false, notify: true });
+  };
+
+  #setFavorited(on, { persist, notify }) {
+    const changed = on !== this.#favorited;
+    this.#favorited = on;
+
+    // Accessible state lives on the native button; the custom state is a styling hook only.
+    this.#els.favorite.setAttribute('aria-pressed', String(on));
+    try {
+      on ? this.#internals.states.add('favorited') : this.#internals.states.delete('favorited');
+    } catch {
+      // CustomStateSet unsupported: internal styles rely on aria-pressed, so nothing breaks.
+    }
+
+    if (persist) {
+      const favorites = readFavorites();
+      on ? favorites.add(this.drinkId) : favorites.delete(this.drinkId);
+      writeFavorites(favorites);
+    }
+
+    if (notify && changed) {
+      this.dispatchEvent(
+        new CustomEvent('favorite-change', {
+          bubbles: true,
+          detail: { id: this.drinkId, name: this.name, favorited: on },
+        }),
+      );
+    }
+  }
+
+  #render() {
+    const { image, price, link, names } = this.#els;
+    this.#syncHeadingLevel();
+
+    this.#els.title.textContent = this.name;
+    names.forEach((el) => (el.textContent = this.name));
+
+    const src = this.getAttribute('image');
+    image.hidden = !src;
+    if (src) {
+      if (image.getAttribute('src') !== src) image.src = src;
+      image.alt = this.getAttribute('image-alt') ?? '';
+    } else {
+      image.removeAttribute('src');
+    }
+
+    const priceText = this.getAttribute('price');
+    price.hidden = !priceText;
+    price.textContent = priceText ?? '';
+
+    const href = this.getAttribute('href');
+    link.hidden = !href;
+    if (href) link.href = href;
+    else link.removeAttribute('href');
+  }
+
+  #syncHeadingLevel() {
+    const level = Math.min(6, Math.max(1, Number(this.getAttribute('heading-level')) || 3));
+    const tag = `H${level}`;
+    if (this.#els.title.tagName === tag) return;
+    const heading = document.createElement(tag);
+    heading.className = 'title';
+    heading.setAttribute('part', 'title');
+    this.#els.title.replaceWith(heading);
+    this.#els.title = heading;
+  }
+}
+
+if (!customElements.get('dg-coffee-card')) {
+  customElements.define('dg-coffee-card', DgCoffeeCard);
+}
diff --git a/components/dg-coffee-filter.js b/components/dg-coffee-filter.js
new file mode 100644
index 0000000..ebf0b9e
--- /dev/null
+++ b/components/dg-coffee-filter.js
@@ -0,0 +1,248 @@
+import { sharedSheet } from './shared-styles.js';
+
+/**
+ * <dg-coffee-filter for="grid-id" label="Filter drinks">
+ *   <option value="all" selected>All</option>
+ *   <option value="hot">Hot</option>
+ *   <option value="favorites">My favorites</option>
+ * </dg-coffee-filter>
+ *
+ * Renders the <option> children as a native radio group (single tab stop,
+ * arrow-key navigation for free) and hides <dg-coffee-card> elements inside
+ * the element referenced by `for` whose `tags` don't match. The special
+ * value "all" shows everything; "favorites" shows favorited cards.
+ * A polite live region announces the result count after each change.
+ *
+ * Attributes:  for, label, value (reflects the current selection)
+ * Properties:  value
+ * Events:      change (bubbles) after the selection changes
+ * Parts:       ::part(legend | chip | status)
+ */
+
+const sheet = new CSSStyleSheet();
+sheet.replaceSync(`
+  :host {
+    display: block;
+    text-align: center;
+  }
+
+  fieldset {
+    display: flex;
+    flex-wrap: wrap;
+    justify-content: center;
+    align-items: center;
+    gap: 0.5rem;
+    margin: 0;
+    padding: 0;
+    border: 0;
+  }
+
+  legend {
+    float: inline-start; /* Lets the legend sit in the flex row. */
+    margin-inline-end: 0.25rem;
+    padding: 0;
+    font-weight: 600;
+  }
+
+  label {
+    position: relative;
+    display: inline-flex;
+    align-items: center;
+    min-block-size: 2.75rem;
+    padding: 0.4rem 1rem;
+    border: 2px solid var(--_primary);
+    border-radius: 999px;
+    color: var(--_primary);
+    background: var(--_surface);
+    cursor: pointer;
+    transition: background-color 0.2s, color 0.2s;
+  }
+
+  label:hover {
+    background: var(--_secondary);
+  }
+
+  /* The radio stays in the accessibility tree and keyboard order; only its box is hidden. */
+  input {
+    position: absolute;
+    inset: 0;
+    margin: 0;
+    opacity: 0;
+    cursor: pointer;
+  }
+
+  label:has(:focus-visible) {
+    outline: 3px solid var(--_focus);
+    outline-offset: 2px;
+  }
+
+  /* Selected: filled chip plus a check mark, so it isn't conveyed by color alone. */
+  label:has(:checked) {
+    background: var(--_primary);
+    color: #fff;
+  }
+
+  label:has(:checked)::before {
+    content: '✓\\00a0';
+    content: '✓\\00a0' / ''; /* Decorative: hidden from assistive tech where supported. */
+  }
+
+  .status {
+    min-block-size: 1.6em;
+    margin: 0.75rem 0 0;
+    font-size: 0.9rem;
+  }
+
+  @media (forced-colors: active) {
+    label:has(:checked) {
+      outline: 3px solid Highlight;
+    }
+  }
+`);
+
+const template = document.createElement('template');
+template.innerHTML = `
+  <fieldset>
+    <legend part="legend"></legend>
+  </fieldset>
+  <p class="status" part="status" role="status"></p>
+`;
+
+export class DgCoffeeFilter extends HTMLElement {
+  static observedAttributes = ['label', 'value', 'for'];
+
+  #fieldset;
+  #legend;
+  #status;
+  #target = null;
+  #built = false;
+
+  constructor() {
+    super();
+    const root = this.attachShadow({ mode: 'open' });
+    root.adoptedStyleSheets = [sharedSheet, sheet];
+    root.append(template.content.cloneNode(true));
+    this.#fieldset = root.querySelector('fieldset');
+    this.#legend = root.querySelector('legend');
+    this.#status = root.querySelector('.status');
+
+    this.#fieldset.addEventListener('change', (event) => {
+      this.value = event.target.value;
+      this.dispatchEvent(new Event('change', { bubbles: true }));
+    });
+  }
+
+  connectedCallback() {
+    this.#legend.textContent = this.getAttribute('label') || 'Filter';
+    if (!this.#built) this.#buildOptions();
+    this.#attachTarget();
+    // Apply a non-default initial value once the cards are upgraded (they expose `favorited`/`tags`).
+    customElements.whenDefined('dg-coffee-card').then(() => this.#apply({ announce: false }));
+  }
+
+  disconnectedCallback() {
+    this.#detachTarget();
+  }
+
+  attributeChangedCallback(name, oldValue, newValue) {
+    if (oldValue === newValue) return;
+    if (name === 'label') this.#legend.textContent = newValue || 'Filter';
+    if (!this.isConnected) return;
+    if (name === 'for') {
+      this.#detachTarget();
+      this.#attachTarget();
+      this.#apply({ announce: false });
+    }
+    if (name === 'value') {
+      this.#syncRadios();
+      this.#apply({ announce: true });
+    }
+  }
+
+  get value() {
+    return this.getAttribute('value') || 'all';
+  }
+  set value(v) {
+    this.setAttribute('value', v);
+  }
+
+  #buildOptions() {
+    const options = [...this.querySelectorAll(':scope > option')];
+    if (!options.length) return;
+    this.#built = true;
+
+    const selected = options.find((o) => o.hasAttribute('selected'));
+    if (!this.hasAttribute('value') && selected) this.setAttribute('value', selected.value);
+
+    for (const option of options) {
+      const label = document.createElement('label');
+      label.setAttribute('part', 'chip');
+      const input = document.createElement('input');
+      input.type = 'radio';
+      input.name = 'filter';
+      input.value = option.value;
+      label.append(input, option.textContent.trim());
+      this.#fieldset.append(label);
+    }
+    this.#syncRadios();
+  }
+
+  #syncRadios() {
+    for (const input of this.#fieldset.querySelectorAll('input')) {
+      input.checked = input.value === this.value;
+    }
+  }
+
+  #attachTarget() {
+    const id = this.getAttribute('for');
+    this.#target = id ? document.getElementById(id) : null;
+    this.#target?.addEventListener('favorite-change', this.#onFavoriteChange);
+  }
+
+  #detachTarget() {
+    this.#target?.removeEventListener('favorite-change', this.#onFavoriteChange);
+    this.#target = null;
+  }
+
+  #onFavoriteChange = () => {
+    if (this.value === 'favorites') this.#apply({ announce: true });
+  };
+
+  #matches(card) {
+    if (this.value === 'all') return true;
+    if (this.value === 'favorites') return Boolean(card.favorited);
+    return (card.tags ?? []).includes(this.value);
+  }
+
+  #apply({ announce }) {
+    if (!this.#target) return;
+    const cards = [...this.#target.querySelectorAll('dg-coffee-card')];
+    const active = document.activeElement;
+    let shown = 0;
+    let lostFocus = false;
+
+    for (const card of cards) {
+      const match = this.#matches(card);
+      if (!match && card.contains(active)) lostFocus = true;
+      card.hidden = !match;
+      if (match) shown++;
+    }
+
+    // Hiding the focused card would drop focus to <body>; keep the user in place.
+    if (lostFocus) this.#fieldset.querySelector('input:checked')?.focus();
+
+    if (!announce) return;
+    if (shown === 0) {
+      this.#status.textContent =
+        this.value === 'favorites'
+          ? 'No favorites yet. Use the Favorite button on a drink to save it.'
+          : 'No drinks match this filter.';
+    } else {
+      this.#status.textContent = `Showing ${shown} of ${cards.length} drinks.`;
+    }
+  }
+}
+
+if (!customElements.get('dg-coffee-filter')) {
+  customElements.define('dg-coffee-filter', DgCoffeeFilter);
+}
diff --git a/components/dg-site-nav.js b/components/dg-site-nav.js
new file mode 100644
index 0000000..9af7f2d
--- /dev/null
+++ b/components/dg-site-nav.js
@@ -0,0 +1,338 @@
+import { sharedSheet } from './shared-styles.js';
+
+/**
+ * <dg-site-nav label="Primary">
+ *   <a slot="brand" href="/">The Daily Grind</a>
+ *   <a href="/menu">Menu</a>
+ *   <a href="/logout" data-variant="outline">Logout</a>
+ * </dg-site-nav>
+ *
+ * Responsive site navigation. Links stay in the Light DOM (usable without JS
+ * and indexable) and are projected one-per-<li> into a semantic
+ * <nav><ul> via imperative slot assignment.
+ *
+ * Layout is content-driven, not breakpoint-driven: the links render inline
+ * when the whole row fits, otherwise they collapse behind a "Menu" button that
+ * opens a native popover (light dismiss, Escape, focus return for free).
+ * The link matching the current URL gets aria-current="page" unless one is
+ * already set.
+ *
+ * Parts: ::part(bar | menu-button | menu)
+ */
+
+const sheet = new CSSStyleSheet();
+sheet.replaceSync(`
+  :host {
+    display: block;
+    position: sticky;
+    inset-block-start: 0;
+    z-index: 1000;
+    background: var(--_primary);
+    color: #fff;
+  }
+
+  .bar {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    gap: 1rem;
+    padding: 0.75rem 5%;
+  }
+
+  /* Keep the row's natural width measurable. */
+  .bar > *,
+  .menu > li {
+    flex-shrink: 0;
+    white-space: nowrap;
+  }
+
+  .is-measuring * {
+    transition: none !important;
+  }
+
+  ::slotted([slot='brand']) {
+    color: inherit;
+    font-size: 1.5rem;
+    font-weight: bold;
+    letter-spacing: 1px;
+    text-decoration: none;
+    text-transform: uppercase;
+  }
+
+  ul {
+    list-style: none;
+    margin: 0;
+    padding: 0;
+  }
+
+  ::slotted(a) {
+    display: block;
+    padding: 0.6rem 0.75rem;
+    border-radius: 4px;
+    color: inherit;
+    font-size: 0.95rem;
+    text-decoration: none;
+    transition: color 0.2s;
+  }
+
+  ::slotted(a:hover) {
+    color: var(--_accent);
+  }
+
+  ::slotted(a:focus-visible) {
+    outline: 3px solid var(--_focus);
+    outline-offset: 2px;
+  }
+
+  /* Current page: underline (shape) as well as color. */
+  ::slotted(a[aria-current='page']) {
+    color: var(--_accent);
+    text-decoration: underline;
+    text-decoration-thickness: 2px;
+    text-underline-offset: 0.35em;
+  }
+
+  ::slotted(a[data-variant='outline']) {
+    border: 1px solid var(--_accent);
+  }
+
+  .menu-button {
+    anchor-name: --dg-menu-button;
+    min-block-size: 2.75rem;
+    border-color: var(--_accent);
+    background: transparent;
+  }
+
+  .menu-button:hover {
+    border-color: var(--_accent);
+    background: var(--_primary-dark);
+  }
+
+  .menu-button svg {
+    inline-size: 1.25em;
+    block-size: 1.25em;
+    stroke: currentColor;
+    stroke-width: 2;
+    stroke-linecap: round;
+  }
+
+  /* Collapsed layout (default, and the no-anchor-positioning fallback). */
+  .menu {
+    position: fixed;
+    inset: auto;
+    inset-block-start: 4.5rem;
+    inset-block-start: anchor(--dg-menu-button bottom);
+    inset-inline-end: 5%;
+    inline-size: min(80dvw, 20rem);
+    max-block-size: calc(100dvh - 6rem);
+    margin: 0.5rem 0 0;
+    padding: 0.5rem;
+    overflow: auto;
+    border: 1px solid var(--_accent);
+    border-radius: var(--_radius);
+    background: var(--_primary);
+    color: #fff;
+    box-shadow: 0 8px 24px rgb(0 0 0 / 0.3);
+  }
+
+  .bar:not(.is-wide) .menu:not(:is(:popover-open, .is-open)) {
+    display: none;
+  }
+
+  .menu > li + li {
+    margin-block-start: 0.25rem;
+  }
+
+  @media (prefers-reduced-motion: no-preference) {
+    .menu {
+      transition: opacity 0.15s, translate 0.15s, display 0.15s, overlay 0.15s;
+      transition-behavior: allow-discrete;
+    }
+
+    @starting-style {
+      .menu:is(:popover-open, .is-open) {
+        opacity: 0;
+        translate: 0 -0.5rem;
+      }
+    }
+  }
+
+  /* Wide layout: the same list renders inline. */
+  .is-wide .menu-button {
+    display: none;
+  }
+
+  .is-wide .menu {
+    position: static;
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+    inline-size: auto;
+    max-block-size: none;
+    margin: 0;
+    padding: 0;
+    overflow: visible;
+    border: 0;
+    background: transparent;
+    box-shadow: none;
+  }
+
+  .is-wide .menu > li + li {
+    margin-block-start: 0;
+  }
+
+  @media (forced-colors: active) {
+    ::slotted(a[aria-current='page']) {
+      text-decoration-color: CanvasText;
+    }
+  }
+`);
+
+const template = document.createElement('template');
+template.innerHTML = `
+  <header class="bar" part="bar">
+    <slot name="brand"></slot>
+    <nav>
+      <button class="btn menu-button" part="menu-button" type="button" popovertarget="menu" aria-controls="menu">
+        <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M4 7h16M4 12h16M4 17h16"/></svg>
+        <span>Menu</span>
+      </button>
+      <ul id="menu" class="menu" part="menu" popover="auto"></ul>
+    </nav>
+  </header>
+`;
+
+const supportsPopover = Object.hasOwn(HTMLElement.prototype, 'popover');
+
+export class DgSiteNav extends HTMLElement {
+  #bar;
+  #nav;
+  #menu;
+  #button;
+  #brandSlot;
+  #wide = false;
+  #lastWidth = 0;
+  #resizeObserver = new ResizeObserver(() => this.#syncLayout());
+  #mutationObserver = new MutationObserver(() => this.#assignSlots());
+
+  constructor() {
+    super();
+    const root = this.attachShadow({ mode: 'open', slotAssignment: 'manual' });
+    root.adoptedStyleSheets = [sharedSheet, sheet];
+    root.append(template.content.cloneNode(true));
+
+    this.#bar = root.querySelector('.bar');
+    this.#nav = root.querySelector('nav');
+    this.#menu = root.querySelector('.menu');
+    this.#button = root.querySelector('.menu-button');
+    this.#brandSlot = root.querySelector('slot[name="brand"]');
+
+    if (!supportsPopover) this.#installPopoverFallback();
+  }
+
+  connectedCallback() {
+    this.#nav.setAttribute('aria-label', this.getAttribute('label') || 'Primary');
+    this.#assignSlots();
+    this.#mutationObserver.observe(this, { childList: true });
+    this.#resizeObserver.observe(this.#bar);
+    this.#resizeObserver.observe(this.#menu);
+  }
+
+  disconnectedCallback() {
+    this.#mutationObserver.disconnect();
+    this.#resizeObserver.disconnect();
+  }
+
+  /** Project each Light DOM link into its own <li><slot>. */
+  #assignSlots() {
+    const brand = this.querySelector(':scope > [slot="brand"]');
+    this.#brandSlot.assign(...(brand ? [brand] : []));
+
+    const links = [...this.children].filter((el) => el !== brand && el.matches('a'));
+    this.#menu.replaceChildren(
+      ...links.map((link) => {
+        const li = document.createElement('li');
+        const slot = document.createElement('slot');
+        li.append(slot);
+        slot.assign(link);
+        return li;
+      }),
+    );
+
+    this.#markCurrentPage(links);
+    this.#lastWidth = 0; // Force a re-measure: content changed.
+    this.#syncLayout();
+  }
+
+  #markCurrentPage(links) {
+    if (links.some((a) => a.hasAttribute('aria-current'))) return;
+    const here = location.pathname.replace(/\/$/, '') || '/';
+    const current = links.find((a) => {
+      try {
+        const path = new URL(a.href, location.href).pathname.replace(/\/$/, '') || '/';
+        return path === here;
+      } catch {
+        return false;
+      }
+    });
+    current?.setAttribute('aria-current', 'page');
+  }
+
+  #isOpen() {
+    return this.#menu.matches(supportsPopover ? ':popover-open' : '.is-open');
+  }
+
+  /**
+   * Inline when the full row fits, otherwise collapsed behind the popover.
+   * While collapsed, only re-measure when the bar grows, to avoid thrashing.
+   */
+  #syncLayout() {
+    if (!this.isConnected) return;
+    const width = this.#bar.clientWidth;
+    if (!this.#wide && width <= this.#lastWidth) {
+      this.#lastWidth = width;
+      return;
+    }
+    this.#lastWidth = width;
+
+    const wasOpen = this.#isOpen();
+    this.#bar.classList.add('is-measuring', 'is-wide');
+    this.#menu.removeAttribute('popover'); // Closes it if open.
+    this.#menu.classList.remove('is-open');
+
+    const wide = this.#bar.scrollWidth <= this.#bar.clientWidth;
+    this.#bar.classList.toggle('is-wide', wide);
+    this.#wide = wide;
+
+    if (!wide) {
+      if (supportsPopover) {
+        this.#menu.setAttribute('popover', 'auto');
+        if (wasOpen) this.#menu.showPopover();
+      } else if (wasOpen) {
+        this.#menu.classList.add('is-open');
+      }
+    }
+
