+/**
+ * Constructed stylesheet shared by every Daily Grind component.
+ * Adopted (not duplicated) into each shadow root, so it is parsed once.
+ *
+ * Theming: components read the page's public custom properties
+ * (--dg-primary, --dg-primary-dark, --dg-secondary, --dg-accent,
+ * --dg-text, --dg-surface, --dg-radius). They are inherited across the
+ * shadow boundary; every var() has a fallback so components work standalone.
+ */
+export const sharedSheet = new CSSStyleSheet();
+
+sharedSheet.replaceSync(`
+  :host {
+    --_primary: var(--dg-primary, #4e342e);
+    --_primary-dark: var(--dg-primary-dark, #3e2723);
+    --_secondary: var(--dg-secondary, #d7ccc8);
+    --_accent: var(--dg-accent, #ffab40);
+    --_text: var(--dg-text, #3e2723);
+    --_surface: var(--dg-surface, #fff);
+    --_radius: var(--dg-radius, 8px);
+    --_focus: var(--dg-focus, #ffab40);
+  }
+
+  :host([hidden]),
+  [hidden] {
+    display: none !important;
+  }
+
+  *,
+  *::before,
+  *::after {
+    box-sizing: border-box;
+  }
+
+  /* Form controls don't inherit typography from the UA stylesheet. */
+  button,
+  input {
+    font: inherit;
+    color: inherit;
+  }
+
+  :focus-visible {
+    outline: 3px solid var(--_focus);
+    outline-offset: 2px;
+  }
+
+  .visually-hidden {
+    clip-path: inset(50%);
+    height: 1px;
+    overflow: hidden;
+    position: absolute;
+    white-space: nowrap;
+    width: 1px;
+  }
+
+  .btn {
+    display: inline-flex;
+    align-items: center;
+    justify-content: center;
+    gap: 0.4em;
+    min-block-size: 2.75rem;
+    padding: 0.5rem 1.25rem;
+    border: 2px solid var(--_primary);
+    border-radius: 5px;
+    background: var(--_primary);
+    color: #fff;
+    text-decoration: none;
+    cursor: pointer;
+    transition: background-color 0.2s, border-color 0.2s, color 0.2s;
+  }
+
+  .btn:hover {
+    background: var(--_primary-dark);
+    border-color: var(--_primary-dark);
+  }
+
+  @media (forced-colors: active) {
+    .btn {
+      border-color: ButtonText;
+    }
+  }
+
+  @media (prefers-reduced-motion: reduce) {
+    *,
+    *::before,
+    *::after {
+      transition-duration: 0.01ms !important;
+      animation-duration: 0.01ms !important;
+    }
+  }
+`);
