+import { applyStyles, buttonCss } from './shared-styles.js';
+
+const styles = `
+  :host {
+    display: block;
+    color: #fff;
+  }
+
+  .hero {
+    min-height: var(--dg-hero-height, 60vh);
+    display: flex;
+    flex-direction: column;
+    justify-content: center;
+    align-items: center;
+    gap: 1rem;
+    padding: 3rem 20px;
+    text-align: center;
+    background-color: var(--_primary-dark);
+    background-image:
+      linear-gradient(rgba(0, 0, 0, 0.55), rgba(0, 0, 0, 0.55)),
+      var(--_hero-image, none);
+    background-size: cover;
+    background-position: center;
+  }
+
+  ::slotted([slot='heading']) {
+    margin: 0;
+    font-size: clamp(2rem, 6vw, 3rem);
+    line-height: 1.15;
+  }
+
+  ::slotted(:not([slot])) {
+    margin: 0;
+    max-width: 40rem;
+    font-size: 1.125rem;
+  }
+
+  .actions { margin-top: 0.5rem; }
+
+  ${buttonCss("[slot='action']")}
+  ::slotted([slot='action']:hover) { background: var(--_accent); color: var(--_text); }
+`;
+
+const template = document.createElement('template');
+template.innerHTML = `
+  <div class="hero" part="hero">
+    <slot name="heading"></slot>
+    <slot></slot>
+    <div class="actions"><slot name="action"></slot></div>
+  </div>
+`;
+
+/**
+ * <hero-banner> — full-width promotional banner.
+ *
+ * Slots: heading, (default) tagline, action
+ * Attributes: image – background image URL (purely decorative, so it is
+ *             applied via CSS and never exposed to assistive tech)
+ * CSS custom properties: --dg-hero-height
+ * CSS parts: hero
+ */
+export class HeroBanner extends HTMLElement {
+  static observedAttributes = ['image'];
+
+  #hero;
+
+  constructor() {
+    super();
+    const root = this.attachShadow({ mode: 'open' });
+    root.append(template.content.cloneNode(true));
+    applyStyles(root, styles);
+    this.#hero = root.querySelector('.hero');
+  }
+
+  attributeChangedCallback() {
+    const src = this.getAttribute('image');
+    if (src) {
+      this.#hero.style.setProperty('--_hero-image', `url("${src.replace(/["\\\n]/g, encodeURIComponent)}")`);
+    } else {
+      this.#hero.style.removeProperty('--_hero-image');
+    }
+  }
+}
+
+if (!customElements.get('hero-banner')) {
+  customElements.define('hero-banner', HeroBanner);
+}
