new file mode 100644
index 0000000..86e3322
--- /dev/null
+++ b/components/shared-styles.js
@@ -0,0 +1,98 @@
+/**
+ * Styles shared across Daily Grind components.
+ *
+ * Exposed as a constructable stylesheet so every shadow root can adopt the
+ * same parsed sheet (no duplicate parsing per instance). Design tokens are
+ * read from CSS custom properties, which inherit through the shadow boundary,
+ * so the page can theme components without breaking encapsulation.
+ */
+const css = `
+  :host {
+    --_primary: var(--dg-primary, #4e342e);
+    --_primary-dark: var(--dg-primary-dark, #3e2723);
+    --_secondary: var(--dg-secondary, #d7ccc8);
+    --_accent: var(--dg-accent, #ffab40);
+    --_text: var(--dg-text, #3e2723);
+    --_surface: var(--dg-surface, #ffffff);
+    --_radius: var(--dg-radius, 8px);
+    --_focus-ring: 3px solid var(--_accent);
+    box-sizing: border-box;
+  }
+
+  *, *::before, *::after { box-sizing: inherit; }
+
+  [hidden] { display: none !important; }
+
+  .visually-hidden {
+    position: absolute !important;
+    width: 1px; height: 1px;
+    padding: 0; margin: -1px;
+    overflow: hidden;
+    clip: rect(0 0 0 0);
+    white-space: nowrap;
+    border: 0;
+  }
+
+  @media (prefers-reduced-motion: reduce) {
+    *, *::before, *::after {
+      transition-duration: 0.01ms !important;
+      animation-duration: 0.01ms !important;
+    }
+  }
+`;
+
+/**
+ * CSS for a slotted call-to-action link. `sel` is the compound selector placed
+ * inside ::slotted(), e.g. "[slot='action']" — pseudo-classes must live inside
+ * the parentheses for ::slotted to match them.
+ */
+export const buttonCss = (sel) => `
+  ::slotted(${sel}) {
+    display: inline-block;
+    background: var(--_primary);
+    color: #fff;
+    padding: 10px 20px;
+    text-decoration: none;
+    border-radius: 5px;
+    font-weight: 600;
+    transition: background-color 0.3s;
+  }
+  ::slotted(${sel}:hover) { background: var(--_primary-dark); }
+  ::slotted(${sel}:focus-visible) { outline: var(--_focus-ring); outline-offset: 3px; }
+`;
+
+let sheet;
+const componentSheets = new Map();
+
+/** Returns a stylesheet to adopt, or null if constructable sheets are unsupported. */
+export function sharedSheet() {
+  if (sheet !== undefined) return sheet;
+  try {
+    sheet = new CSSStyleSheet();
+    sheet.replaceSync(css);
+  } catch {
+    sheet = null;
+  }
+  return sheet;
+}
+
+/**
+ * Attach styles to a shadow root: shared sheet + component-specific CSS.
+ * Falls back to a <style> element where adoptedStyleSheets isn't available.
+ */
+export function applyStyles(root, componentCss) {
+  const shared = sharedSheet();
+  if (shared && 'adoptedStyleSheets' in root) {
+    let own = componentSheets.get(componentCss);
+    if (!own) {
+      own = new CSSStyleSheet();
+      own.replaceSync(componentCss);
+      componentSheets.set(componentCss, own);
+    }
+    root.adoptedStyleSheets = [shared, own];
+  } else {
+    const style = document.createElement('style');
+    style.textContent = css + componentCss;
+    root.prepend(style);
+  }
+}
