+import { applyStyles } from './shared-styles.js';
+
+const styles = `
+  :host {
+    display: block;
+    position: sticky;
+    top: 0;
+    z-index: 1000;
+    background: var(--_primary);
+    color: #fff;
+  }
+
+  nav {
+    display: flex;
