+    justify-content: space-between;
+    align-items: center;
+    gap: 0.5rem 1rem;
+    padding: 1rem 5%;
+  }
+
+  ::slotted([slot='brand']) {
+    color: inherit;
+    font-size: 1.5rem;
+    font-weight: bold;
+    letter-spacing: 1px;
+    text-decoration: none;
+  }
+
+  ::slotted([slot='brand']:focus-visible) {
+    outline: var(--_focus-ring);
+    outline-offset: 4px;
+  }
+
+  ul {
+    display: flex;
+    align-items: center;
+    gap: 20px;
+    margin: 0;
+    padding: 0;
+    list-style: none;
+  }
+
+  a {
+    display: inline-block;
+    color: #fff;
+    text-decoration: none;
+    font-size: 0.9rem;
+    padding: 5px 0;
+    transition: color 0.3s;
+  }
+
+  a:hover { color: var(--_accent); }
+
+  a:focus-visible {
+    outline: var(--_focus-ring);
+    outline-offset: 3px;
+    border-radius: 2px;
+  }
+
+  a[aria-current='page'] {
+    color: var(--_accent);
+    text-decoration: underline;
+    text-underline-offset: 6px;
+  }
+
+  a[data-variant='outline'] {
+    border: 1px solid var(--_accent);
+    padding: 5px 12px;
+    border-radius: 4px;
+  }
+
+  .toggle {
+    display: none;
+    align-items: center;
+    gap: 0.5rem;
+    min-width: 44px;
+    min-height: 44px;
+    padding: 0 12px;
+    background: transparent;
+    color: inherit;
+    font: inherit;
+    border: 1px solid rgba(255, 255, 255, 0.5);
+    border-radius: 4px;
+    cursor: pointer;
+  }
+
+  .toggle:focus-visible { outline: var(--_focus-ring); outline-offset: 2px; }
+
+  .bars, .bars::before, .bars::after {
+    display: block;
+    width: 20px;
+    height: 2px;
+    background: currentColor;
+    transition: transform 0.2s ease, opacity 0.2s ease;
+  }
+  .bars { position: relative; }
+  .bars::before, .bars::after { content: ''; position: absolute; left: 0; }
+  .bars::before { top: -6px; }
+  .bars::after { top: 6px; }
+
+  .toggle[aria-expanded='true'] .bars { background: transparent; }
+  .toggle[aria-expanded='true'] .bars::before { transform: translateY(6px) rotate(45deg); }
+  .toggle[aria-expanded='true'] .bars::after { transform: translateY(-6px) rotate(-45deg); }
+
+  @media (max-width: 720px) {
+    .toggle { display: inline-flex; }
+
+    ul {
+      flex-basis: 100%;
+      flex-direction: column;
+      align-items: stretch;
+      gap: 0;
+      padding-top: 0.5rem;
+    }
+
+    ul:not(.open) { display: none; }
+
+    li + li { border-top: 1px solid rgba(255, 255, 255, 0.15); }
+
+    a { display: block; padding: 12px 0; font-size: 1rem; }
+
+    a[data-variant='outline'] {
+      margin: 12px 0 4px;
+      text-align: center;
+    }
+  }
+`;
+
+const template = document.createElement('template');
+template.innerHTML = `
+  <nav part="nav">
+    <slot name="brand"></slot>
+    <button type="button" class="toggle" part="toggle" aria-expanded="false" aria-controls="menu">
+      <span class="bars" aria-hidden="true"></span>
+      <span class="toggle-text">Menu</span>
+    </button>
+    <ul id="menu" part="menu"></ul>
+  </nav>
+`;
+
+const MOBILE_QUERY = '(max-width: 720px)';
+
+/**
+ * <site-nav> — responsive, accessible primary navigation.
+ *
+ * Author markup (works without JS as a plain list of links):
+ *   <site-nav label="Main">
+ *     <a slot="brand" href="/">Brand</a>
+ *     <ul>
+ *       <li><a href="/menu">Menu</a></li>
+ *       <li><a href="/logout" data-variant="outline">Logout</a></li>
+ *     </ul>
+ *   </site-nav>
+ *
+ * The links are mirrored into the shadow tree so they can be styled and
+ * laid out with encapsulated CSS; the light-DOM list stays as the source of
+ * truth and is observed for changes.
+ *
+ * Behaviour on small screens: a disclosure button (aria-expanded /
+ * aria-controls) toggles the menu. Escape closes it and returns focus to the
+ * button; clicking outside or following a link also closes it.
+ *
+ * Attributes: label – accessible name for the nav landmark (default "Main")
+ * Events: nav-toggle – { detail: { open } }
+ * CSS parts: nav, toggle, menu
+ */
+export class SiteNav extends HTMLElement {
+  static observedAttributes = ['label'];
+
+  #nav;
+  #toggle;
+  #menu;
+  #observer;
+  #mql;
+
+  constructor() {
+    super();
+    const root = this.attachShadow({ mode: 'open' });
+    root.append(template.content.cloneNode(true));
+    applyStyles(root, styles);
+
+    this.#nav = root.querySelector('nav');
+    this.#toggle = root.querySelector('.toggle');
+    this.#menu = root.querySelector('#menu');
+
+    this.#toggle.addEventListener('click', () => this.toggle());
+    this.#menu.addEventListener('click', (e) => {
+      if (e.target.closest('a')) this.close();
+    });
+    this.addEventListener('keydown', this.#onKeydown);
+    this.#observer = new MutationObserver(() => this.#render());
+  }
+
+  connectedCallback() {
+    if (!this.hasAttribute('label')) this.#nav.setAttribute('aria-label', 'Main');
+    this.#render();
+    this.#observer.observe(this, {
+      childList: true,
+      subtree: true,
+      characterData: true,
+      attributes: true,
+      attributeFilter: ['href', 'data-variant', 'aria-current'],
+    });
+    document.addEventListener('click', this.#onDocumentClick);
+    this.#mql = window.matchMedia(MOBILE_QUERY);
+    this.#mql.addEventListener('change', this.#onViewportChange);
+  }
+
+  disconnectedCallback() {
+    this.#observer.disconnect();
+    document.removeEventListener('click', this.#onDocumentClick);
+    this.#mql?.removeEventListener('change', this.#onViewportChange);
+  }
+
+  attributeChangedCallback(name, _old, value) {
+    if (name === 'label') this.#nav.setAttribute('aria-label', value || 'Main');
+  }
+
+  get open() {
+    return this.#toggle.getAttribute('aria-expanded') === 'true';
+  }
+
+  toggle(force = !this.open) {
+    if (force === this.open) return;
+    this.#toggle.setAttribute('aria-expanded', String(force));
+    this.#menu.classList.toggle('open', force);
+    this.dispatchEvent(new CustomEvent('nav-toggle', { bubbles: true, composed: true, detail: { open: force } }));
+  }
+
+  close({ restoreFocus = false } = {}) {
+    if (!this.open) return;
+    this.toggle(false);
+    if (restoreFocus) this.#toggle.focus();
+  }
+
+  #render() {
+    const links = [...this.querySelectorAll(':scope > ul a[href], :scope > ol a[href]')];
+    const here = location.pathname.replace(/\/$/, '') || '/';
+
+    this.#menu.replaceChildren(
+      ...links.map((source) => {
+        const li = document.createElement('li');
+        const a = source.cloneNode(true);
+        a.removeAttribute('id');
+        a.removeAttribute('class');
+        const path = new URL(a.href, location.href).pathname.replace(/\/$/, '') || '/';
+        if (!source.hasAttribute('aria-current') && path === here) {
+          a.setAttribute('aria-current', 'page');
+        }
+        li.append(a);
+        return li;
+      }),
+    );
+  }
+
+  #onKeydown = (event) => {
+    if (event.key === 'Escape' && this.open) {
+      event.stopPropagation();
+      this.close({ restoreFocus: true });
+    }
+  };
+
+  #onDocumentClick = (event) => {
+    if (this.open && !event.composedPath().includes(this)) this.close();
+  };
+
+  #onViewportChange = (event) => {
+    // Reset the disclosure when switching back to the desktop layout.
+    if (!event.matches) this.close();
+  };
+}
+
+if (!customElements.get('site-nav')) {
+  customElements.define('site-nav', SiteNav);
+}
