+  <script type="module">
+    // ---- Menu data ----
+    const SIZES = ['small', 'medium', 'large'];
+    const MILKS = ['oat', 'almond', 'whole'];
+    const MENU = {
+      'maple-oat-latte': {
+        name: 'Maple Oat Latte',
+        prices: { small: 4.75, medium: 5.25, large: 5.75 },
+        milks: MILKS,
+        defaultMilk: 'oat',
+      },
+      'dark-roast-espresso': {
+        name: 'Dark Roast Espresso',
+        prices: { small: 2.95, medium: 3.45, large: 3.95 },
+      },
+      'cold-brew': {
+        name: 'Cold Brew',
+        prices: { small: 4.25, medium: 4.75, large: 5.25 },
+      },
+    };
+    const DRINK_IDS = Object.keys(MENU);
+    const MAX_QUANTITY = 10;
+
+    const currency = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });
+    const capitalize = (s) => s.charAt(0).toUpperCase() + s.slice(1);
+
+    // ---- Order state ----
+    const order = [];
+    let nextLineId = 1;
+
+    const lineTotal = (line) => MENU[line.drink].prices[line.size] * line.quantity;
+    const orderTotal = () => order.reduce((sum, line) => sum + lineTotal(line), 0);
+    const describeLine = (line) => {
+      const drink = MENU[line.drink];
+      const milk = line.milk ? `, ${line.milk} milk` : '';
+      return `${line.quantity} × ${capitalize(line.size)} ${drink.name}${milk}`;
+    };
+    const snapshot = () => ({
+      items: order.map((line) => ({
+        lineId: line.id,
+        drink: line.drink,
+        name: MENU[line.drink].name,
+        size: line.size,
+        ...(line.milk ? { milk: line.milk } : {}),
+        quantity: line.quantity,
+        lineTotal: Number(lineTotal(line).toFixed(2)),
+      })),
+      total: Number(orderTotal().toFixed(2)),
+    });
+
+    // Validates input and returns either { line } or { error }.
+    function validateItem({ drink, size = 'medium', quantity = 1, milk }) {
+      const item = MENU[drink];
+      if (!item) return { error: `Unknown drink "${drink}".`, availableDrinks: DRINK_IDS };
+      if (!SIZES.includes(size)) return { error: `Unknown size "${size}".`, availableSizes: SIZES };
+      if (!Number.isInteger(quantity) || quantity < 1 || quantity > MAX_QUANTITY) {
+        return { error: `Quantity must be a whole number from 1 to ${MAX_QUANTITY}.` };
+      }
+      if (item.milks) {
+        milk ??= item.defaultMilk;
+        if (!item.milks.includes(milk)) return { error: `Unknown milk "${milk}".`, availableMilks: item.milks };
+      } else if (milk !== undefined) {
+        return { error: `${item.name} does not take milk. Omit the milk option.` };
+      }
+      return { line: { drink, size, quantity, ...(item.milks ? { milk } : {}) } };
+    }
+
+    function addToOrder(input) {
+      const result = validateItem(input);
+      if (result.error) return result;
+      const { line } = result;
+      const existing = order.find((l) => l.drink === line.drink && l.size === line.size && l.milk === line.milk);
+      if (existing) {
+        existing.quantity = Math.min(MAX_QUANTITY, existing.quantity + line.quantity);
+      } else {
+        order.push({ id: `line-${nextLineId++}`, ...line });
+      }
+      render();
+      announce(`Added ${describeLine(line)} to your order.`);
+      return snapshot();
+    }
+
+    function removeFromOrder(lineId) {
+      const index = order.findIndex((l) => l.id === lineId);
+      if (index === -1) {
+        return { error: `No order line with id "${lineId}".`, lineIds: order.map((l) => l.id) };
+      }
+      const [removed] = order.splice(index, 1);
+      render();
+      announce(`Removed ${describeLine(removed)} from your order.`);
+      return snapshot();
+    }
+
+    // ---- Rendering ----
+    const linesEl = document.getElementById('order-lines');
+    const emptyEl = document.getElementById('order-empty');
+    const totalEl = document.getElementById('order-total');
+    const placeBtn = document.getElementById('place-order');
+    const statusEl = document.getElementById('order-status');
+    const dialog = document.getElementById('confirm-order');
+
+    const announce = (msg) => { statusEl.textContent = msg; };
+
+    function render() {
+      linesEl.replaceChildren(...order.map((line) => {
+        const li = document.createElement('li');
+        const label = document.createElement('span');
+        label.textContent = `${describeLine(line)} — ${currency.format(lineTotal(line))}`;
+        const remove = document.createElement('button');
+        remove.type = 'button';
+        remove.className = 'remove';
+        remove.textContent = 'Remove';
+        remove.setAttribute('aria-label', `Remove ${describeLine(line)}`);
+        remove.addEventListener('click', () => removeFromOrder(line.id));
+        li.append(label, remove);
+        return li;
+      }));
+      emptyEl.hidden = order.length > 0;
+      totalEl.textContent = currency.format(orderTotal());
+      placeBtn.disabled = order.length === 0;
+    }
+
+    // Populate card controls from the menu data.
+    for (const card of document.querySelectorAll('.card[data-drink]')) {
+      const drink = MENU[card.dataset.drink];
+      const form = card.querySelector('form');
+      card.querySelector('[data-price]').textContent =
+        `${currency.format(drink.prices.small)} – ${currency.format(drink.prices.large)}`;
+      form.elements.size.append(...SIZES.map((size) =>
+        new Option(`${capitalize(size)} (${currency.format(drink.prices[size])})`, size, false, size === 'medium')));
+      if (drink.milks) {
+        form.elements.milk.append(...drink.milks.map((milk) =>
+          new Option(capitalize(milk), milk, false, milk === drink.defaultMilk)));
+      }
+      form.addEventListener('submit', (event) => {
+        event.preventDefault();
+        const data = new FormData(form);
+        addToOrder({
+          drink: card.dataset.drink,
+          size: data.get('size'),
+          quantity: Number(data.get('quantity')),
+          ...(drink.milks ? { milk: data.get('milk') } : {}),
+        });
+      });
+    }
+
+    // ---- Checkout (always requires the user to confirm in the dialog) ----
+    function confirmWithUser(signal) {
+      return new Promise((resolve, reject) => {
+        signal?.throwIfAborted();
+        const confirmLines = document.getElementById('confirm-lines');
+        confirmLines.replaceChildren(...order.map((line) => {
+          const li = document.createElement('li');
+          li.textContent = `${describeLine(line)} — ${currency.format(lineTotal(line))}`;
+          return li;
+        }));
+        document.getElementById('confirm-total').textContent = currency.format(orderTotal());
+
+        const onAbort = () => dialog.close();
+        dialog.addEventListener('close', () => {
+          signal?.removeEventListener('abort', onAbort);
+          const confirmed = dialog.returnValue === 'confirm';
+          dialog.returnValue = '';
+          if (signal?.aborted) reject(signal.reason);
+          else resolve(confirmed);
+        }, { once: true });
+        signal?.addEventListener('abort', onAbort, { once: true });
+        dialog.showModal();
+      });
+    }
+
+    async function placeOrder(signal) {
+      if (order.length === 0) return { error: 'The order is empty. Add at least one drink first.' };
+      if (dialog.open) return { error: 'An order confirmation is already waiting for the user.' };
+      const summary = snapshot();
+      const confirmed = await confirmWithUser(signal);
+      if (!confirmed) {
+        announce('Order not placed. Your items are still saved.');
+        return { status: 'cancelled', message: 'The user chose not to place the order.' };
+      }
+      const orderNumber = `DG-${Date.now().toString(36).toUpperCase()}`;
+      order.length = 0;
+      render();
+      announce(`Thanks! Order ${orderNumber} is placed. Total ${currency.format(summary.total)}.`);
+      return { status: 'placed', orderNumber, ...summary };
+    }
+
+    placeBtn.addEventListener('click', () => placeOrder());
+    render();
+
+    // ---- WebMCP: expose ordering actions to browser AI agents ----
+    if ('modelContext' in document) {
+      const orderSchema = {
+        type: 'object',
+        properties: {
+          items: {
+            type: 'array',
+            items: {
+              type: 'object',
+              properties: {
+                lineId: { type: 'string', description: 'Pass to remove_item_from_order.' },
+                drink: { type: 'string', enum: DRINK_IDS },
+                name: { type: 'string' },
+                size: { type: 'string', enum: SIZES },
+                milk: { type: 'string', enum: MILKS },
+                quantity: { type: 'integer' },
+                lineTotal: { type: 'number', description: 'Price in USD.' },
+              },
+              required: ['lineId', 'drink', 'name', 'size', 'quantity', 'lineTotal'],
+            },
+          },
+          total: { type: 'number', description: 'Order total in USD.' },
+        },
+        required: ['items', 'total'],
+      };
+      const errorSchema = {
+        type: 'object',
+        properties: { error: { type: 'string' } },
+        required: ['error'],
+      };
+      const orderOrError = { anyOf: [orderSchema, errorSchema] };
+
+      const tools = [
+        {
+          name: 'get_seasonal_menu',
+          description: 'Lists the seasonal coffee drinks available to order, with prices and options. Use to answer menu questions or before adding drinks.',
+          inputSchema: { type: 'object', properties: {} },
+          execute() {
+            return {
+              drinks: DRINK_IDS.map((id) => ({
+                drink: id,
+                name: MENU[id].name,
+                pricesUSD: MENU[id].prices,
+                ...(MENU[id].milks ? { milks: MENU[id].milks, defaultMilk: MENU[id].defaultMilk } : {}),
+              })),
+            };
+          },
+          annotations: { readOnlyHint: true },
+        },
+        {
+          name: 'add_drink_to_order',
+          description: "Adds a seasonal drink to the user's current order. Adding the same drink with the same options increases its quantity.",
+          inputSchema: {
+            type: 'object',
+            properties: {
+              drink: { type: 'string', enum: DRINK_IDS, description: 'Which seasonal drink to add.' },
+              size: { type: 'string', enum: SIZES, default: 'medium', description: 'Cup size.' },
+              quantity: { type: 'integer', minimum: 1, maximum: MAX_QUANTITY, default: 1, description: 'How many of this drink.' },
+              milk: { type: 'string', enum: MILKS, description: 'Milk choice. Only applies to the Maple Oat Latte, which defaults to oat.' },
+            },
+            required: ['drink'],
+          },
+          outputSchema: orderOrError,
+          execute(input) {
+            return addToOrder(input ?? {});
+          },
+          annotations: { readOnlyHint: false },
+        },
+        {
+          name: 'get_current_order',
+          description: "Returns the drinks currently in the user's order and the running total.",
+          inputSchema: { type: 'object', properties: {} },
+          outputSchema: orderSchema,
+          execute() {
+            return snapshot();
+          },
+          annotations: { readOnlyHint: true },
+        },
+        {
+          name: 'remove_item_from_order',
+          description: "Removes one line from the user's current order.",
+          inputSchema: {
+            type: 'object',
+            properties: {
+              lineId: { type: 'string', description: 'The order line to remove, as returned by get_current_order.' },
+            },
+            required: ['lineId'],
