@@ -0,0 +1,104 @@
+import { useWebMCP } from 'use-webmcp-tool';
+
+interface Props {
+  slug: string;
+  title: string;
+  summary: string;
+  author: string;
+  date: string;
+  category: string;
+  tags: string[];
+  readingTime?: number;
+  bodyId: string;
+}
+
+const BLOCK_SELECTOR = 'p, li, blockquote, h2, h3, h4';
+const WORDS_PER_MINUTE = 230;
+const HIGHLIGHT_CLASSES = ['bg-amber-100', 'outline', 'outline-2', 'outline-amber-400'];
+
+function getBlocks(bodyId: string): HTMLElement[] {
+  const body = document.getElementById(bodyId);
+  if (!body) throw new Error('The article body is not on the page anymore.');
+  return [...body.querySelectorAll<HTMLElement>(BLOCK_SELECTOR)].filter(
+    (block) => block.textContent?.trim() && !block.parentElement?.closest(BLOCK_SELECTOR),
+  );
+}
+
+const blockText = (block: HTMLElement) => (block.textContent ?? '').replace(/\s+/g, ' ').trim();
+
+/** Article-page WebMCP tools. Registered only while an article is displayed. */
+export default function ArticleAgentTools({ bodyId, ...meta }: Props) {
+  useWebMCP({
+    name: 'get-current-article',
+    description:
+      'Returns the article the reader is viewing: its details plus the full text split into numbered paragraphs. Use to summarize, quote, or answer questions about this article.',
+    inputSchema: { type: 'object', properties: {} },
+    execute() {
+      const paragraphs = getBlocks(bodyId).map(blockText);
+      const wordCount = paragraphs.join(' ').split(/\s+/).filter(Boolean).length;
+      return {
+        ...meta,
+        url: location.href,
+        wordCount,
+        readingTimeMinutes: meta.readingTime ?? Math.max(1, Math.round(wordCount / WORDS_PER_MINUTE)),
+        paragraphs: paragraphs.map((text, index) => ({ index, text })),
+      };
+    },
+    annotations: { readOnlyHint: true },
+  });
+
+  useWebMCP<{ query: string }>({
+    name: 'find-in-article',
+    description:
+      'Finds the paragraphs of the open article that mention a word or phrase. Use to locate a passage before quoting it or scrolling to it.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        query: { type: 'string', description: 'Word or phrase to look for. Matching ignores case.' },
+      },
+      required: ['query'],
+    },
+    execute({ query }) {
+      if (typeof query !== 'string' || !query.trim()) {
+        throw new Error('Pass a word or phrase to look for.');
+      }
+      const needle = query.trim().toLowerCase();
+      const matches = getBlocks(bodyId)
+        .map((block, index) => ({ index, text: blockText(block) }))
+        .filter(({ text }) => text.toLowerCase().includes(needle));
+      return { query, matchCount: matches.length, matches };
+    },
+    annotations: { readOnlyHint: true },
+  });
+
+  useWebMCP<{ index: number }>({
+    name: 'scroll-to-article-paragraph',
+    description:
+      'Scrolls the open article to a paragraph and briefly highlights it so the reader can see the passage being discussed.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        index: {
+          type: 'integer',
+          minimum: 0,
+          description: 'Paragraph number as returned by get-current-article or find-in-article.',
+        },
+      },
+      required: ['index'],
+    },
+    execute({ index }) {
+      const blocks = getBlocks(bodyId);
+      if (!Number.isInteger(index) || index < 0 || index >= blocks.length) {
+        throw new Error(`Paragraph index must be a whole number from 0 to ${blocks.length - 1}.`);
+      }
+      const block = blocks[index];
+      const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;
+      block.scrollIntoView({ block: 'center', behavior: reduceMotion ? 'auto' : 'smooth' });
+      block.classList.add(...HIGHLIGHT_CLASSES);
+      setTimeout(() => block.classList.remove(...HIGHLIGHT_CLASSES), 2500);
+      return { index, text: blockText(block) };
+    },
+  });
+
+  return null;
+}
