@@ -0,0 +1,112 @@
+import { useWebMCP } from 'use-webmcp-tool';
+import { navigate } from 'astro:transitions/client';
+import {
+  articleUrl,
+  describeArticle,
+  findArticle,
+  getArticles,
+  getReadingList,
+  setReadingListMembership,
+} from '../utils/agent-tools';
+
+const SLUG_PROPERTY = {
+  type: 'string',
+  description: 'Article identifier, e.g. "housing-crisis". Find slugs with list-articles or search-articles.',
+} as const;
+
+const SLUG_SCHEMA = {
+  type: 'object',
+  properties: { slug: SLUG_PROPERTY },
+  required: ['slug'],
+} as const;
+
+function requireSlug(slug: unknown): string {
+  if (typeof slug !== 'string' || !slug.trim()) {
+    throw new Error('Pass the slug of an article, e.g. "housing-crisis".');
+  }
+  return slug.trim();
+}
+
+/** Site-wide WebMCP tools, mounted once in the main layout. Renders nothing. */
+export default function SiteAgentTools() {
+  useWebMCP<{ category?: string; limit?: number }>({
+    name: 'list-articles',
+    description:
+      'Lists published articles, newest first, optionally narrowed to one news section. Use to browse what the paper covers or to look up article slugs.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        category: { type: 'string', description: 'News section name such as Economy, Sports or Arts. Matching ignores case.' },
+        limit: { type: 'integer', minimum: 1, maximum: 50, default: 10, description: 'Maximum number of articles to return.' },
+      },
+    },
+    async execute({ category, limit = 10 }) {
+      const articles = await getArticles();
+      const max = Number.isInteger(limit) && limit > 0 ? Math.min(limit, 50) : 10;
+      const categories = [...new Set(articles.map((article) => article.category))];
+      const wanted = typeof category === 'string' ? category.trim().toLowerCase() : '';
+      const matches = articles
+        .filter((article) => !wanted || article.category.toLowerCase() === wanted)
+        .sort((a, b) => b.date.localeCompare(a.date));
+      if (wanted && matches.length === 0) {
+        throw new Error(`No articles in category "${category}". Available categories: ${categories.join(', ')}.`);
+      }
+      return {
+        total: matches.length,
+        categories,
+        articles: matches.slice(0, max).map(describeArticle),
+      };
+    },
+    annotations: { readOnlyHint: true },
+  });
+
+  useWebMCP({
+    name: 'get-reading-list',
+    description: "Returns the articles the reader has saved to their reading list.",
+    inputSchema: { type: 'object', properties: {} },
+    async execute(_args, { signal }) {
+      const [slugs, articles] = await Promise.all([getReadingList(signal), getArticles()]);
+      const saved = slugs
+        .map((slug) => articles.find((article) => article.slug === slug))
+        .filter((article) => article !== undefined)
