@@ -0,0 +1,107 @@
+// Shared client-side helpers backing the WebMCP tools (declarative forms and
+// imperative `useWebMCP` tools) exposed across The DevTools Times.
+
+export interface ArticleSummary {
+  slug: string;
+  title: string;
+  summary: string;
+  image: string;
+  author: string;
+  category: string;
+  date: string;
+  tags: string[];
+}
+
+export const READING_LIST_CHANGE = 'readinglistchange';
+
+const BASE_URL = import.meta.env.BASE_URL;
+const READING_LIST_URL = `${BASE_URL}api/reading-list.json`;
+
+export const articleUrl = (slug: string) =>
+  new URL(`${BASE_URL}articles/${slug}`, location.origin).href;
+
+let articlesPromise: Promise<ArticleSummary[]> | undefined;
+
+/** Fetches the article index once per page session and caches it. */
+export function getArticles(): Promise<ArticleSummary[]> {
+  articlesPromise ??= fetch(`${BASE_URL}api/articles.json`)
+    .then((response) => {
+      if (!response.ok) throw new Error(`Article index request failed (${response.status}).`);
+      return response.json() as Promise<ArticleSummary[]>;
+    })
+    .catch((error) => {
+      articlesPromise = undefined; // allow a retry on the next call
+      throw error;
+    });
+  return articlesPromise;
+}
+
+export function searchArticles(articles: ArticleSummary[], query: string): ArticleSummary[] {
+  const terms = query.toLowerCase().split(/\s+/).filter(Boolean);
+  if (terms.length === 0) return [];
+  return articles.filter((article) => {
+    const haystack = [article.title, article.summary, article.category, article.author, ...article.tags]
+      .join(' ')
+      .toLowerCase();
+    return terms.every((term) => haystack.includes(term));
+  });
+}
+
+/** Compact, agent-friendly representation of an article. */
+export const describeArticle = (article: ArticleSummary) => ({
+  slug: article.slug,
+  title: article.title,
+  summary: article.summary,
+  author: article.author,
+  category: article.category,
+  date: article.date,
+  url: articleUrl(article.slug),
+});
+
+export async function findArticle(slug: string): Promise<ArticleSummary> {
+  const articles = await getArticles();
+  const article = articles.find((entry) => entry.slug === slug);
+  if (!article) {
+    throw new Error(
+      `No article with slug "${slug}". Known slugs: ${articles.map((entry) => entry.slug).join(', ')}.`,
+    );
+  }
+  return article;
+}
+
+function announceReadingList(readingList: string[]) {
+  window.dispatchEvent(new CustomEvent(READING_LIST_CHANGE, { detail: { readingList } }));
+}
+
+export async function getReadingList(signal?: AbortSignal): Promise<string[]> {
+  const response = await fetch(READING_LIST_URL, { signal });
+  if (!response.ok) throw new Error(`Reading list request failed (${response.status}).`);
+  const data = await response.json();
+  return data.readingList ?? [];
+}
+
+/** The API toggles membership; this posts the toggle and broadcasts the new list. */
+export async function toggleReadingList(slug: string, signal?: AbortSignal): Promise<string[]> {
+  const response = await fetch(READING_LIST_URL, {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({ slug }),
+    signal,
+  });
+  if (!response.ok) throw new Error(`Updating the reading list failed (${response.status}).`);
+  const data = await response.json();
+  const readingList: string[] = data.readingList ?? [];
+  announceReadingList(readingList);
+  return readingList;
+}
+
+/** Idempotently ensures `slug` is (or is not) on the reading list. */
+export async function setReadingListMembership(
+  slug: string,
+  saved: boolean,
+  signal?: AbortSignal,
+): Promise<string[]> {
+  const current = await getReadingList(signal);
+  if (current.includes(slug) === saved) return current;
+  return toggleReadingList(slug, signal);
+}

