+/**
+ * WebMCP (navigator.modelContext) tools for The DevTools Times.
+ *
+ * Exposes client-side utilities to in-browser AI agents:
+ *  - Site-wide tools, registered once per document: article discovery,
+ *    reading articles, navigation, and opening the search / reading-list
+ *    panels (which in turn expose the declarative `search_articles` and
+ *    `manage_reading_list` form tools).
+ *  - Article-page tools, registered while an article is displayed and
+ *    unregistered again on client-side navigation away from it.
+ *
+ * Everything is feature-detected, so browsers without WebMCP are unaffected.
+ */
+import { navigate } from 'astro:transitions/client';
+import type { ModelContext, ModelContextTool } from '../../global';
+import { fetchReadingList, setReadingListItem } from '../utils/readingListClient';
+
+interface ArticleSummary {
+  slug: string;
+  title: string;
+  summary: string;
+  image?: string;
+  category: string;
+  author: string;
+  date: string;
+  tags: string[];
+  readingTime?: number;
+}
+
+interface ContentBlock {
+  type: 'heading' | 'paragraph' | 'list-item' | 'quote';
+  level?: number;
+  text: string;
+}
+
+const BASE_URL = import.meta.env.BASE_URL;
+const HIGHLIGHT_NAME = 'webmcp-find';
+const DEFAULT_WORDS_PER_MINUTE = 230;
+
+// ---------------------------------------------------------------------------
+// Helpers
+// ---------------------------------------------------------------------------
+
+const textResult = (data: unknown) => ({
+  content: [{ type: 'text', text: typeof data === 'string' ? data : JSON.stringify(data, null, 2) }],
+});
+
+const errorResult = (message: string) => ({
+  content: [{ type: 'text', text: message }],
+  isError: true,
+});
+
+const articleUrl = (slug: string) => new URL(`${BASE_URL}articles/${slug}`, location.origin).href;
+
+let articlesCache: Promise<ArticleSummary[]> | null = null;
+function getArticles(): Promise<ArticleSummary[]> {
+  if (!articlesCache) {
+    articlesCache = fetch(`${BASE_URL}api/articles.json`)
+      .then(response => {
+        if (!response.ok) throw new Error(`Failed to load articles (${response.status})`);
+        return response.json();
+      })
+      .catch(error => {
+        articlesCache = null;
+        throw error;
+      });
+  }
+  return articlesCache;
+}
+
+async function findArticle(slug: string): Promise<ArticleSummary | undefined> {
+  const normalized = slug.trim().toLowerCase();
+  return (await getArticles()).find(article => article.slug.toLowerCase() === normalized);
+}
+
+const countWords = (text: string) => (text.match(/\S+/g) ?? []).length;
+
+function extractBlocks(body: Element): ContentBlock[] {
+  const blocks: ContentBlock[] = [];
+  body.querySelectorAll('h1, h2, h3, h4, h5, h6, p, li, blockquote').forEach(element => {
+    // Skip paragraphs nested inside list items / quotes to avoid duplicates.
+    if (element.tagName === 'P' && element.parentElement?.closest('li, blockquote')) return;
+    const text = (element.textContent ?? '').replace(/\s+/g, ' ').trim();
+    if (!text) return;
+    if (/^H[1-6]$/.test(element.tagName)) {
+      blocks.push({ type: 'heading', level: Number(element.tagName[1]), text });
+    } else if (element.tagName === 'LI') {
+      blocks.push({ type: 'list-item', text });
+    } else if (element.tagName === 'BLOCKQUOTE') {
+      blocks.push({ type: 'quote', text });
+    } else {
+      blocks.push({ type: 'paragraph', text });
+    }
+  });
+  return blocks;
+}
+
+function blocksToText(blocks: ContentBlock[]): string {
+  return blocks
+    .map(block => {
+      if (block.type === 'heading') return `${'#'.repeat(block.level ?? 2)} ${block.text}`;
+      if (block.type === 'list-item') return `- ${block.text}`;
+      if (block.type === 'quote') return `> ${block.text}`;
+      return block.text;
+    })
+    .join('\n\n');
+}
+
+/** Reads article metadata and content from an article page document. */
+function readArticleFromDocument(doc: Document) {
+  const article = doc.querySelector<HTMLElement>('article[data-article-slug]');
+  const body = article?.querySelector('[data-article-body]');
+  if (!article || !body) return null;
+  const data = article.dataset;
+  const blocks = extractBlocks(body);
+  const text = blocksToText(blocks);
+  return {
+    slug: data.articleSlug!,
+    title: data.articleTitle ?? '',
+    summary: data.articleSummary ?? '',
+    author: data.articleAuthor ?? '',
+    category: data.articleCategory ?? '',
+    date: data.articleDate ?? '',
+    tags: data.articleTags ? data.articleTags.split(',').filter(Boolean) : [],
+    declaredReadingTimeMinutes: data.articleReadingTime ? Number(data.articleReadingTime) : undefined,
+    wordCount: countWords(text),
+    url: articleUrl(data.articleSlug!),
+    blocks,
+    text,
+  };
+}
+
+const getCurrentArticleElements = () => {
+  const article = document.querySelector<HTMLElement>('article[data-article-slug]');
+  const body = article?.querySelector<HTMLElement>('[data-article-body]') ?? null;
+  return { article, body };
+};
+
+function clearFindHighlight() {
+  (CSS as any).highlights?.delete(HIGHLIGHT_NAME);
+}
+
+// ---------------------------------------------------------------------------
+// Site-wide tools
+// ---------------------------------------------------------------------------
+
+const siteTools: ModelContextTool[] = [
+  {
+    name: 'list_articles',
+    description:
+      'List articles published on The DevTools Times with their slug, title, summary, category, author, date, tags and URL. ' +
+      'Optionally filter by category, tag or author, and sort by date.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        category: { type: 'string', description: "Only return articles in this category (case-insensitive), e.g. 'sports', 'science', 'Politics'." },
+        tag: { type: 'string', description: 'Only return articles with this tag (case-insensitive).' },
+        author: { type: 'string', description: 'Only return articles whose author/desk contains this text (case-insensitive).' },
+        sort: { type: 'string', enum: ['newest', 'oldest'], description: 'Sort order by publication date. Defaults to newest.' },
+        limit: { type: 'integer', minimum: 1, maximum: 100, description: 'Maximum number of articles to return. Defaults to 50.' },
+      },
+    },
+    annotations: { readOnlyHint: true },
+    async execute({ category, tag, author, sort = 'newest', limit = 50 } = {}) {
+      let articles = await getArticles();
+      if (category) articles = articles.filter(a => a.category.toLowerCase() === String(category).toLowerCase());
+      if (tag) articles = articles.filter(a => a.tags.some(t => t.toLowerCase() === String(tag).toLowerCase()));
+      if (author) articles = articles.filter(a => a.author.toLowerCase().includes(String(author).toLowerCase()));
+      articles = [...articles].sort((a, b) => (sort === 'oldest' ? a.date.localeCompare(b.date) : b.date.localeCompare(a.date)));
+      const categories = [...new Set((await getArticles()).map(a => a.category))];
+      return textResult({
+        total: articles.length,
+        availableCategories: categories,
+        articles: articles.slice(0, limit).map(({ image, ...rest }) => ({ ...rest, url: articleUrl(rest.slug) })),
+      });
+    },
+  },
+  {
+    name: 'read_article',
+    description:
+      'Fetch and return the full text of an article on The DevTools Times by its slug, including metadata (author, date, category, tags) and word count. ' +
+      'Use list_articles or search_articles to discover slugs.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        slug: { type: 'string', description: "The article slug, e.g. 'urban-cycling'." },
+      },
+      required: ['slug'],
+    },
+    annotations: { readOnlyHint: true },
+    async execute({ slug }) {
+      const article = await findArticle(String(slug ?? ''));
+      if (!article) return errorResult(`No article found with slug "${slug}". Use list_articles to see available slugs.`);
+
+      // Use the live DOM if the article is already open, otherwise fetch the page.
+      let doc: Document = document;
+      if (getCurrentArticleElements().article?.dataset.articleSlug !== article.slug) {
+        const response = await fetch(articleUrl(article.slug));
+        if (!response.ok) return errorResult(`Failed to load article "${slug}" (${response.status}).`);
+        doc = new DOMParser().parseFromString(await response.text(), 'text/html');
+      }
+      const content = readArticleFromDocument(doc);
+      if (!content) return errorResult(`Could not extract content for article "${slug}".`);
+      const { blocks, ...rest } = content;
+      return textResult(rest);
+    },
+  },
+  {
+    name: 'open_article',
+    description: 'Navigate the browser tab to an article on The DevTools Times, identified by its slug.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        slug: { type: 'string', description: "The article slug, e.g. 'urban-cycling'." },
+      },
+      required: ['slug'],
+    },
+    async execute({ slug }) {
+      const article = await findArticle(String(slug ?? ''));
+      if (!article) return errorResult(`No article found with slug "${slug}". Use list_articles to see available slugs.`);
+      const url = articleUrl(article.slug);
+      navigate(url);
+      return textResult({ navigatingTo: url, title: article.title });
+    },
+  },
+  {
+    name: 'open_search',
+    description:
+      'Open the site search panel, optionally pre-filled with a query, so the user can see the results. ' +
+      'While the panel is open the declarative `search_articles` form tool is also available.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        query: { type: 'string', description: 'Optional search text to pre-fill.' },
+      },
+    },
+    async execute({ query } = {}) {
+      window.dispatchEvent(new CustomEvent('devtools-times:open-search', { detail: { query: query ? String(query) : '' } }));
+      return textResult(query ? `Opened the search panel with query "${query}".` : 'Opened the search panel.');
+    },
+  },
+  {
+    name: 'open_reading_list',
+    description:
+      "Open the reader's reading list panel so the user can see their saved articles. " +
+      'While the panel is open the declarative `manage_reading_list` form tool is also available.',
+    inputSchema: { type: 'object', properties: {} },
+    async execute() {
+      window.dispatchEvent(new CustomEvent('devtools-times:open-reading-list'));
+      return textResult('Opened the reading list panel.');
+    },
+  },
+  {
+    name: 'get_reading_list',
+    description: "Return the articles currently saved in the reader's reading list.",
+    inputSchema: { type: 'object', properties: {} },
+    annotations: { readOnlyHint: true },
+    async execute() {
+      const [slugs, articles] = await Promise.all([fetchReadingList(), getArticles()]);
+      const saved = slugs.map(slug => {
+        const article = articles.find(a => a.slug === slug);
+        return article
+          ? { slug, title: article.title, summary: article.summary, url: articleUrl(slug) }
+          : { slug };
+      });
+      return textResult({ count: saved.length, articles: saved });
+    },
+  },
+];
+
+// ---------------------------------------------------------------------------
+// Article-page tools
+// ---------------------------------------------------------------------------
+
+const articlePageTools: ModelContextTool[] = [
+  {
+    name: 'get_current_article',
+    description:
+      'Return the article currently open in this tab: slug, title, summary, author, date, category, tags, word count and full text.',
+    inputSchema: { type: 'object', properties: {} },
+    annotations: { readOnlyHint: true },
+    async execute() {
+      const content = readArticleFromDocument(document);
+      if (!content) return errorResult('No article is open in this tab.');
+      const { blocks, ...rest } = content;
+      return textResult(rest);
+    },
+  },
+  {
+    name: 'get_article_outline',
+    description: 'Return the section headings of the current article in order, with the word count of each section.',
+    inputSchema: { type: 'object', properties: {} },
+    annotations: { readOnlyHint: true },
+    async execute() {
+      const content = readArticleFromDocument(document);
+      if (!content) return errorResult('No article is open in this tab.');
+      const sections: { heading: string; level: number; wordCount: number }[] = [
+        { heading: '(Introduction)', level: 1, wordCount: 0 },
+      ];
+      for (const block of content.blocks) {
+        if (block.type === 'heading') sections.push({ heading: block.text, level: block.level ?? 2, wordCount: 0 });
+        else sections[sections.length - 1].wordCount += countWords(block.text);
+      }
+      return textResult({
+        title: content.title,
+        sections: sections.filter((s, i) => i > 0 || s.wordCount > 0),
+      });
+    },
+  },
+  {
+    name: 'estimate_reading_time',
+    description: 'Estimate how long it takes to read the current article, based on its word count and a reading speed.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        wordsPerMinute: {
+          type: 'integer',
+          minimum: 50,
+          maximum: 1000,
+          description: `Reading speed in words per minute. Defaults to ${DEFAULT_WORDS_PER_MINUTE}.`,
+        },
+      },
+    },
+    annotations: { readOnlyHint: true },
+    async execute({ wordsPerMinute = DEFAULT_WORDS_PER_MINUTE } = {}) {
+      const content = readArticleFromDocument(document);
+      if (!content) return errorResult('No article is open in this tab.');
+      const wpm = Math.min(1000, Math.max(50, Number(wordsPerMinute) || DEFAULT_WORDS_PER_MINUTE));
+      return textResult({
+        title: content.title,
+        wordCount: content.wordCount,
+        wordsPerMinute: wpm,
+        estimatedMinutes: Math.max(1, Math.ceil(content.wordCount / wpm)),
+        declaredReadingTimeMinutes: content.declaredReadingTimeMinutes,
+      });
+    },
+  },
+  {
+    name: 'find_in_article',
+    description:
+      'Find a word or phrase in the current article. Returns each matching passage, highlights all matches on the page and scrolls the first one into view.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        query: { type: 'string', description: 'Text to find (case-insensitive).' },
+      },
+      required: ['query'],
+    },
+    async execute({ query }) {
+      const { body } = getCurrentArticleElements();
+      if (!body) return errorResult('No article is open in this tab.');
