+      const highlights = (CSS as any).highlights;
+      const HighlightCtor = (window as any).Highlight;
+      if (highlights && HighlightCtor) highlights.set(HIGHLIGHT_NAME, new HighlightCtor(...ranges));
+
+      const blockOf = (range: Range) =>
+        (range.startContainer.parentElement?.closest('p, li, blockquote, h1, h2, h3, h4, h5, h6') ?? body) as HTMLElement;
+      blockOf(ranges[0]).scrollIntoView({ behavior: 'smooth', block: 'center' });
+
+      const passages = [...new Set(ranges.map(blockOf))].map(el => (el.textContent ?? '').replace(/\s+/g, ' ').trim());
+      return textResult({ query, matchCount: ranges.length, passages });
+    },
+  },
+  {
+    name: 'save_current_article',
+    description: "Add the current article to, or remove it from, the reader's reading list (the bookmark button on the page).",
+    inputSchema: {
+      type: 'object',
+      properties: {
+        saved: { type: 'boolean', description: 'true to save the article to the reading list, false to remove it. Defaults to true.' },
+      },
+    },
+    async execute({ saved = true } = {}) {
+      const slug = getCurrentArticleElements().article?.dataset.articleSlug;
+      if (!slug) return errorResult('No article is open in this tab.');
+      const readingList = await setReadingListItem(slug, saved !== false);
+      return textResult({ slug, saved: readingList.includes(slug), readingListCount: readingList.length });
+    },
+  },
+  {
+    name: 'get_article_share_links',
+    description: 'Return the canonical URL of the current article along with ready-to-use share links (email, X, Facebook, WhatsApp).',
+    inputSchema: { type: 'object', properties: {} },
+    annotations: { readOnlyHint: true },
+    async execute() {
+      const { article } = getCurrentArticleElements();
+      const slug = article?.dataset.articleSlug;
+      if (!article || !slug) return errorResult('No article is open in this tab.');
