+    },
+  },
+];
+
+// ---------------------------------------------------------------------------
+// Registration
+// ---------------------------------------------------------------------------
+
+function registerTools(modelContext: ModelContext, tools: ModelContextTool[], signal?: AbortSignal) {
+  for (const tool of tools) {
+    try {
+      const registration: any = modelContext.registerTool(tool, signal ? { signal } : undefined);
+      signal?.addEventListener('abort', () => {
+        try {
+          if (registration && typeof registration.unregister === 'function') registration.unregister();
+          else modelContext.unregisterTool?.(tool.name);
+        } catch {
+          // Already unregistered (e.g. natively via the AbortSignal).
+        }
+      });
+    } catch (error) {
+      console.warn(`[WebMCP] Failed to register tool "${tool.name}":`, error);
+    }
+  }
+}
+
+const modelContext = typeof navigator !== 'undefined' ? navigator.modelContext : undefined;
+
+if (modelContext && typeof modelContext.registerTool === 'function') {
+  registerTools(modelContext, siteTools);
+
+  let pageController: AbortController | null = null;
+  let registeredFor: string | null = null;
+
+  const syncPageTools = () => {
+    const slug = getCurrentArticleElements().article?.dataset.articleSlug ?? null;
+    if (slug === registeredFor) return;
+    pageController?.abort();
+    pageController = null;
+    registeredFor = slug;
+    if (slug) {
+      pageController = new AbortController();
+      registerTools(modelContext, articlePageTools, pageController.signal);
+    }
+  };
+
+  syncPageTools();
+  // Re-evaluate after every client-side (view transition) navigation.
+  document.addEventListener('astro:page-load', syncPageTools);
+  document.addEventListener('astro:before-swap', clearFindHighlight);
+}
