+// Client-side helpers for the session-backed reading list API.
+// Every mutation broadcasts `devtools-times:reading-list-changed` so that
+// bookmark buttons and the reading-list flyout stay in sync no matter who
+// (a human click or an AI agent tool call) changed the list.
+
+const endpoint = () => `${import.meta.env.BASE_URL}api/reading-list.json`;
+
+function broadcast(readingList: string[]) {
+  window.dispatchEvent(
+    new CustomEvent('devtools-times:reading-list-changed', { detail: { readingList } }),
+  );
+}
+
+export async function fetchReadingList(): Promise<string[]> {
+  const response = await fetch(endpoint());
+  if (!response.ok) throw new Error(`Failed to load reading list (${response.status})`);
+  const data = await response.json();
+  return data.readingList ?? [];
+}
+
+export async function toggleReadingListItem(slug: string): Promise<string[]> {
+  const response = await fetch(endpoint(), {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({ slug }),
+  });
+  if (!response.ok) throw new Error(`Failed to update reading list (${response.status})`);
+  const data = await response.json();
+  const readingList: string[] = data.readingList ?? [];
+  broadcast(readingList);
+  return readingList;
+}
+
+/**
+ * Idempotently adds or removes an article. The API only exposes a toggle, so
+ * we check the current state first to avoid accidentally undoing a change.
+ */
+export async function setReadingListItem(slug: string, saved: boolean): Promise<string[]> {
+  const current = await fetchReadingList();
+  if (current.includes(slug) === saved) return current;
+  return toggleReadingListItem(slug);
+}
